window.__ykCourses = window.__ykCourses || {};
window.__ykCourses.N5 = {"level":"N5","units":[{"n":1,"ja":"名詞の文","en":"Saying what things are","days":[{"title":"〜は〜です・〜じゃありません","grammar":{"points":[{"id":"n5u01d1.p1","form":"〜は〜です","gloss":"A is B","connect":[{"pos":"Noun (the topic), then noun (what it is)","rule":"〜 ＋ は ＋ 〜 ＋ {です}"},{"pos":"Another person's name + さん","rule":"〜さん ＋ は ＋ 〜 ＋ {です}"}],"examples":[{"ja":"わたし{は}[学生|がくせい]{です}。","en":"I am a student.","clip":"x_n5u01d1_p1_1"},{"ja":"ルイスさん{は}ブラジル[人|じん]{です}。","en":"Luis is Brazilian.","clip":"x_n5u01d1_p1_2"}],"watch":{"note":"The little word after the topic is written は but said わ. Write it with は.","bad":"わたしわがくせいです。","good":"わたしはがくせいです。"}},{"id":"n5u01d1.p2","form":"〜じゃありません","gloss":"A is not B","connect":[{"pos":"Noun","rule":"〜 ＋ {じゃありません}"},{"pos":"Noun, more formal","rule":"〜 ＋ {ではありません}"}],"examples":[{"ja":"わたしは[先生|せんせい]{じゃありません}。","en":"I am not a teacher.","clip":"x_n5u01d1_p2_1"},{"ja":"ルイスさんはかいしゃいん{じゃありません}。","en":"Luis is not a company employee.","clip":"x_n5u01d1_p2_2"}],"watch":{"note":"じゃありません takes the place of です. Keep じゃ (or では): without it, せんせいありません does not mean \"not a teacher\".","bad":"わたしはせんせいありません。","good":"わたしはせんせいじゃありません。"}}],"compare":{"intro":"Three polite endings after a noun: one says it is, two say it is not.","forms":[{"form":"〜です","tag":"そうです · it is","mark":"dot","ja":"わたしは[学生|がくせい]{です}。","en":"I am a student."},{"form":"〜じゃありません","tag":"ちがいます · it is not","mark":"down","ja":"わたしは[先生|せんせい]{じゃありません}。","en":"I am not a teacher."},{"form":"〜ではありません","tag":"かたい · it is not (formal)","mark":"down","ja":"わたしはかいしゃいん{ではありません}。","en":"I am not a company employee. (more formal)"}],"check":{"id":"n5u01d1.c1","kind":"choice","type":"文の文法1","label":"じこしょうかい","q":"マリアさんは[先生|せんせい]（　　）。^[日本語|にほんご]をおしえます^。","options":["ですか","です","じゃありません"],"answer":2,"why":["This asks whether she is a teacher, but the speaker already knows: the next sentence says she teaches Japanese.","Maria teaches Japanese, so she is a teacher: use です.","This says she is not a teacher, but the next sentence says she teaches Japanese."],"explain":null}},"drill":[{"id":"n5u01d1.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"はじめまして。わたし（　　）^ルイスです^。","options":["で","は","を","へ"],"answer":2,"why":["で shows where something happens, as in がっこうで. It cannot mark the topic.","は marks the topic, the person you talk about: わたし. Then ルイスです says who that is.","を marks the thing an action is done to, as in パンをたべます. There is no action here.","へ shows the direction you go, as in がっこうへいきます. It cannot mark the topic."],"explain":null},{"id":"n5u01d1.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは^[中国人|ちゅうごくじん]^（　　）。","options":["です","ます","は","を"],"answer":1,"why":["中国人 is a noun, and です after a noun says what someone is.","ます goes after a verb, as in たべます. 中国人 is a noun.","は marks a topic. The sentence still needs an ending after 中国人.","を marks the thing an action is done to. There is no action, and no ending."]},{"id":"n5u01d1.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは[先生|せんせい]（　　）。^[学生|がくせい]です^。","options":["です","ます","を","じゃありません"],"answer":4,"why":["先生です would say I am a teacher, but the next sentence says I am a student.","ます goes after a verb. 先生 is a noun.","を marks the thing an action is done to. The sentence would have no ending.","The next sentence says I am a student, so I am not a teacher: 先生じゃありません."],"explain":null},{"id":"n5u01d1.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ルイスさんは[日本人|にほんじん]（　　）。^ブラジル[人|じん]です^。","options":["ありません","ではありません","です","ですか"],"answer":2,"why":["Without では, ありません here would mean \"there is none\", not \"is not\".","Luis is Brazilian, so he is not Japanese. ではありません is the formal way to say \"is not\".","日本人です would say he is Japanese, but the next sentence says he is Brazilian.","This asks whether he is Japanese, but the next sentence already says what he is: Brazilian."],"explain":null},{"id":"n5u01d1.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"はじめまして。","after":"。","tiles":["わたしは","[日本語|にほんご]の","[先生|せんせい]","です"],"star":1,"bank":[3,0,2,1],"hint":"Start with the topic and は. です comes at the very end.","full":"はじめまして。わたし{は}[日本語|にほんご]の[先生|せんせい]{です}。","explain":"わたしは is the topic, so it comes first. 日本語の tells what kind of teacher, so it sits right before 先生, and です closes the sentence."},{"id":"n5u01d1.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしは","after":"。","tiles":["[学校|がっこう]の","[先生|せんせい]","では","ありません"],"star":2,"bank":[1,3,0,2],"hint":"Which tiles make \"is not\"? They come after the noun.","full":"わたしは[学校|がっこう]の[先生|せんせい]{ではありません}。","explain":"学校の tells what kind of teacher, so it sits right before 先生. では and ありません together mean \"is not\" (more formal than じゃありません), and they follow the noun."}],"exam":[{"id":"n5u01d1.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「マリアさんは　先生ですか。」\nB「いいえ、先生（　　）。学生です。」","options":["ます","ありません","じゃありません","です"],"answer":3,"explain":"いいえ and 学生です show that Maria is not a teacher, so 先生じゃありません. 先生です says the opposite, ます goes after a verb, not a noun, and ありません without じゃ does not mean \"is not\" here."},{"id":"n5u01d1.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ルイスさん（　　）　ブラジル人です。","options":["に","で","は","を"],"answer":3,"explain":"は marks ルイスさん as the topic, and ブラジル人です says what he is. を marks the thing an action is done to, に marks a time or a place to go, and で marks where something happens. None of them can mark the topic."},{"id":"n5u01d1.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしの","after":"。かいしゃいんです。","tiles":["父は","日本語の","先生","じゃありません"],"star":2,"bank":[3,1,0,2],"full":"わたしの父は日本語の{先生}じゃありません。かいしゃいんです。","explain":"父は, 日本語の, 先生, じゃありません. わたしの goes with 父, the topic. 日本語の tells what kind of teacher, and じゃありません comes last, after the noun."}]},"scene":{"ja":"じこしょうかいカード","en":"A self-introduction card","intro":"Tap each word on the card you fill in on your first day at the language school.","words":[{"id":"name","word":"名前","reading":"なまえ","gloss":"name","parts":[["名","な","name"],["前","まえ","front, before"]],"clip":"s_n5u1d1_name"},{"id":"country","word":"国","reading":"くに","gloss":"country","parts":[["国","くに","country"]],"clip":"s_n5u1d1_country"},{"id":"student","word":"学生","reading":"がくせい","gloss":"student","parts":[["学","ガク","study"],["生","セイ","life, birth"]],"clip":"s_n5u1d1_student"},{"id":"teacher","word":"先生","reading":"せんせい","gloss":"teacher","parts":[["先","セン","ahead, before"],["生","セイ","life, birth"]],"clip":"s_n5u1d1_teacher"},{"id":"company","word":"会社","reading":"かいしゃ","gloss":"company (where you work)","parts":[["会","カイ","meet"],["社","シャ","company"]],"clip":"s_n5u1d1_company"},{"id":"japanese","word":"日本語","reading":"にほんご","gloss":"Japanese (the language)","parts":[["日","ニ","sun, day"],["本","ホン","origin, book"],["語","ゴ","word, language"]],"clip":"s_n5u1d1_japanese"},{"id":"school","word":"学校","reading":"がっこう","gloss":"school","parts":[["学","ガッ","study"],["校","コウ","school"]],"clip":"s_n5u1d1_school"},{"id":"phone","word":"電話","reading":"でんわ","gloss":"telephone","parts":[["電","デン","electricity"],["話","ワ","talk"]],"clip":"s_n5u1d1_phone"}],"check":{"id":"n5u01d1.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"わたしは　日本語学校の　_学生_です。","options":["がっせい","かくせい","がくせ","がくせい"],"answer":4,"explain":"学生 is がくせい, with a long せい at the end. 学 becomes がっ only before some sounds, as in 学校 (がっこう), not here. かくせい has the wrong first sound, and がくせ drops the い."}},"skill":{"kind":"listening","ja":"発話表現","en":"Expressions","situation":"On her first day at a language school, a student with a name tag that says リン meets her new teacher.","ask":"はじめて　先生に　あいました。何と　いいますか。","item":{"id":"n5u01d1.r1","kind":"choice","type":"発話表現","q":"はじめて　先生に　あいました。何と　いいますか。","script":["ナレーター：はじめて　先生に　あいました。何と　いいますか。","ナレーター：1","女：どうも　ありがとう。リンです。","ナレーター：2","女：はじめまして。リンです。よろしく　おねがいします。","ナレーター：3","女：はじめまして。リンさんですか。"],"options":["どうも　ありがとう。リンです。","はじめまして。リンです。よろしく　おねがいします。","はじめまして。リンさんですか。"],"printed":false,"short":["ありがとう。リンです","はじめまして。リンです","リンさんですか"],"answer":2,"why":["ありがとう is for thanks. The teacher has not done anything for her yet.","","She is Lin. リンさんですか asks the teacher if the teacher is Lin."],"clip":"l_n5u1d1"},"audio":[["N","はじめて　先生に　あいました。何と　いいますか。","はじめて　せんせいに　あいました。なんと　いいますか。"],["N","1","いち"],["F","どうも　ありがとう。リンです。",null],["N","2","に"],["F","はじめまして。リンです。よろしく　おねがいします。",null],["N","3","さん"],["F","はじめまして。リンさんですか。",null]]}},{"title":"〜か・〜も","grammar":{"points":[{"id":"n5u01d2.p1","form":"〜か","gloss":"question ending: …?","connect":[{"pos":"Noun","rule":"〜 ＋ です ＋ {か}"},{"pos":"Answer: yes","rule":"はい、{そうです}。"},{"pos":"Answer: no","rule":"いいえ、{ちがいます}。"}],"examples":[{"ja":"リンさんは[学生|がくせい]です{か}。……はい、そうです。","en":"Lin, are you a student? Yes, I am.","clip":"x_n5u01d2_p1_1"},{"ja":"やまださんは[先生|せんせい]です{か}。……いいえ、ちがいます。[学生|がくせい]です。","en":"Is Ms Yamada a teacher? No, she isn't. She's a student.","clip":"x_n5u01d2_p1_2"}],"watch":{"note":"In polite talk, keep です before か. 学生か on its own sounds rough, not polite.","bad":"リンさんは学生か。","good":"リンさんは学生ですか。"}},{"id":"n5u01d2.p2","form":"〜も","gloss":"also, too","connect":[{"pos":"Noun, in place of は","rule":"〜 ＋ {も}（は → も）"},{"pos":"Noun, in place of が","rule":"〜 ＋ {も}（が → も）"},{"pos":"Two nouns","rule":"〜{も}　〜{も}"}],"examples":[{"ja":"わたしは[学生|がくせい]です。リンさん{も}[学生|がくせい]です。","en":"I am a student. Lin is a student too.","clip":"x_n5u01d2_p2_1"},{"ja":"[本|ほん]があります。ノート{も}あります。","en":"There is a book. There is a notebook too.","clip":"x_n5u01d2_p2_2"}],"watch":{"note":"も takes the place of は. Do not use both together.","bad":"リンさんはも学生です。","good":"リンさんも学生です。"}}],"compare":{"intro":"Three small words that change a です sentence: は gives the topic, も says \"too\", and か at the end asks.","forms":[{"form":"〜か","tag":"しつもん · question","mark":"dot","ja":"リンさんは[学生|がくせい]です{か}。","en":"Is Lin a student?"},{"form":"〜も","tag":"おなじ · also, too","mark":"up","ja":"キムさん{も}[学生|がくせい]です。","en":"Kim is a student too."},{"form":"〜は","tag":"トピック · as for","mark":"dot","ja":"やまださん{は}[先生|せんせい]です。","en":"Ms Yamada is a teacher."}],"check":{"id":"n5u01d2.c1","kind":"choice","type":"文の文法1","label":"クラスで","q":"A：やまださんは[先生|せんせい]ですか。B：いいえ、ちがいます。やまださん（　　）[学生|がくせい]です。","options":["は","も","か"],"answer":1,"why":["B now says what Ms Yamada really is: やまださんは学生です.","も means \"too\". Nobody else in this talk is a student, so there is nothing to add to.","か between names means \"or\", but no second name follows here."]}},"drill":[{"id":"n5u01d2.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：キムさんは[先生|せんせい]です（　　）。B：^はい、そうです^。","options":["を","か","も","は"],"answer":2,"why":["を marks what a verb acts on. It cannot follow です.","か after です makes a question, and B answers it with はい、そうです.","も goes after a noun, as in キムさんも. It cannot end a sentence after です.","は goes after a noun, as in キムさんは. It cannot end a sentence after です."],"explain":null},{"id":"n5u01d2.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：それは[日本語|にほんご]の[本|ほん]ですか。B：いいえ、（　　）。^ノートです^。","options":["そうですか","ちがいますか","ちがいます","そうです"],"answer":3,"why":["そうですか means \"oh, I see\". It reacts to news. It does not answer A's question.","ちがいますか asks a question back. B is answering here, not asking.","After いいえ, ちがいます says \"that's not right\". Then B says what it really is: a notebook.","そうです means \"yes, that's right\". It clashes with いいえ, and B goes on to say it is a notebook."],"explain":null},{"id":"n5u01d2.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"やまださん（　　）^キムさんも^[学生|がくせい]です。","options":["は","か","が","も"],"answer":4,"why":["は does not pair with キムさんも. When two names share the sentence like this, each one takes も.","か between names means \"or\", and then キムさん would not take も.","が does not pair with キムさんも either. Each name takes も.","Both people are students: AもBも. キムさんも asks for も after やまださん too."],"explain":null},{"id":"n5u01d2.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：^わたしは[学生|がくせい]です^。B：あ、わたし（　　）です。","options":["も","は","か","が"],"answer":1,"why":["わたしもです means \"me too\": B is a student as well. も replaces the は of わたしは学生です.","わたしはです is not a sentence. は needs a word before です, as in わたしは学生です.","か cannot sit between わたし and です. To ask, か goes at the end: ですか.","わたしがです is not a sentence. が also needs a word before です."]},{"id":"n5u01d2.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"やまださんは","after":"。","tiles":["[日本語|にほんご]の","[先生|せんせい]","です","か"],"star":2,"bank":[2,0,3,1],"hint":"What kind of teacher? 日本語の sits right before 先生. か always comes last.","full":"やまださんは[日本語|にほんご]の[先生|せんせい]です{か}。","explain":"日本語の describes 先生, so it goes first. Then です, and か at the very end turns the sentence into a question."},{"id":"n5u01d2.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A：わたしは[日本語|にほんご]の[学生|がくせい]です。B：","after":"です。","tiles":["わたし","も","[日本語|にほんご]の","[学生|がくせい]"],"star":1,"bank":[2,0,3,1],"hint":"B is a Japanese student too. Which tile can follow わたし?","full":"A：わたしは[日本語|にほんご]の[学生|がくせい]です。B：わたし{も}[日本語|にほんご]の[学生|がくせい]です。","explain":"B says the same thing as A, so わたし takes も in place of は. 日本語の must sit right before 学生."}],"exam":[{"id":"n5u01d2.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：すみません。これは　出口ですか。B：はい、（　　）。","options":["そうですか","なんですか","そうです","ちがいます"],"answer":3,"explain":"はい goes with そうです: \"yes, it is\". はい、ちがいます contradicts itself. そうですか only reacts to news, and なんですか asks a new question instead of answering."},{"id":"n5u01d2.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"つくえの　上に、本も　ノート（　　）　あります。","options":["を","も","は","が"],"answer":2,"explain":"本も comes first, so ノート takes も too: 本もノートもあります, \"both a book and a notebook\". は and が cannot pair with 本も like this, and を is not used with あります."},{"id":"n5u01d2.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A：","after":"。B：はい、そうです。","tiles":["これは","先生の","本","ですか"],"star":1,"bank":[2,0,3,1],"full":"A：これは　{先生の}　本ですか。B：はい、そうです。","explain":"これは, 先生の, 本, ですか. これは starts the question, 先生の must sit right before 本, and ですか ends it."}]},"scene":{"ja":"きょうしつで","en":"In the classroom","intro":"Tap every label and notice you can see on the classroom wall.","words":[{"id":"book","word":"本","reading":"ほん","gloss":"book","parts":[["本","ホン","book; origin"]],"clip":"s_n5u1d2_book"},{"id":"teacher","word":"先生","reading":"せんせい","gloss":"teacher","parts":[["先","セン","ahead"],["生","セイ","life, live"]],"clip":"s_n5u1d2_teacher"},{"id":"student","word":"学生","reading":"がくせい","gloss":"student","parts":[["学","ガク","study"],["生","セイ","life, live"]],"clip":"s_n5u1d2_student"},{"id":"entrance","word":"入口","reading":"いりぐち","gloss":"entrance","parts":[["入","いり","go in"],["口","ぐち","mouth, opening"]],"clip":"s_n5u1d2_entrance"},{"id":"exit","word":"出口","reading":"でぐち","gloss":"exit","parts":[["出","で","go out"],["口","ぐち","mouth, opening"]],"clip":"s_n5u1d2_exit"},{"id":"name","word":"名前","reading":"なまえ","gloss":"name","parts":[["名","な","name"],["前","まえ","front, before"]],"clip":"s_n5u1d2_name"},{"id":"japanese","word":"日本語","reading":"にほんご","gloss":"Japanese (language)","parts":[["日","ニ","sun, day"],["本","ホン","origin"],["語","ゴ","language, word"]],"clip":"s_n5u1d2_japanese"},{"id":"break","word":"休み","reading":"やすみ","gloss":"break, day off","parts":[["休","やす","rest"]],"clip":"s_n5u1d2_break"}],"check":{"id":"n5u01d2.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"すみません、_出口_は　どこですか。","options":["でくち","しゅつぐち","だしぐち","でぐち"],"answer":4,"explain":"出口 is でぐち: 出 read で, and 口 becomes ぐち after it, as in 入口 (いりぐち). でくち misses that change, しゅつ is the reading in other words, and だしぐち is not a word."}},"skill":{"kind":"reading","ja":"内容理解（短文）","en":"Short passage","ask":"Who is each sentence about, and what is that person?","seconds":90,"passage":"みなさん、はじめまして。リンです。中国から　来ました。今、^大学生^です。ともだちの　ワンさんは　^日本語の　先生^です。でも、^わたしの　先生じゃ　ありません^。ワンさん^も　中国人^です。どうぞ　よろしく。","strategy":"Track the names: what is said about リンさん, what about ワンさん, and what も after a name adds.","item":{"id":"n5u01d2.r1","kind":"choice","type":"読解・内容理解（短文）","q":"ただしい　ものは　どれですか。","options":["リンさんは　日本語の　先生です。","ワンさんは　中国人です。","ワンさんは　リンさんの　先生です。","ワンさんは　大学生です。"],"short":["リン：日本語の先生","ワン：中国人","ワン：リンの先生","ワン：大学生"],"answer":2,"explain":"ワンさんも中国人です: も means Wang is Chinese too, like Lin.","why":["Lin is a university student. The Japanese teacher is Wang.","","Wang is a teacher, but Lin says わたしの先生じゃありません: not my teacher.","Lin is the university student. Wang is a teacher."]}}},{"title":"これ／それ／あれ・この／その／あの","grammar":{"points":[{"id":"n5u01d3.p1","form":"これ／それ／あれ／どれ","gloss":"this one, that one, that one over there, which one","connect":[{"pos":"Alone, as the subject","rule":"{これ}は〜です"},{"pos":"Alone, as the object","rule":"{それ}をください"},{"pos":"Question word","rule":"{どれ}が〜ですか"}],"examples":[{"ja":"{それ}は[何|なん]ですか。","en":"What is that (near you)?","clip":"x_n5u01d3_p1_1"},{"ja":"すみません、{あれ}をください。","en":"Excuse me, I'll take that one over there, please.","clip":"x_n5u01d3_p1_2"}],"watch":{"note":"これ, それ, あれ and どれ stand alone. A noun never comes right after them. To put a noun after the word, use この, その, あの or どの.","bad":"これ本は高いです。","good":"この本は高いです。"}},{"id":"n5u01d3.p2","form":"この／その／あの／どの","gloss":"this, that, that … over there, which (+ a noun)","connect":[{"pos":"Before a noun","rule":"{この}／{その}／{あの}＋かばん"},{"pos":"Question word, before a noun","rule":"{どの}かばんですか"}],"examples":[{"ja":"{この}[魚|さかな]は[安|やす]いです。","en":"This fish is cheap.","clip":"x_n5u01d3_p2_1"},{"ja":"{あの}[白|しろ]いかばんは[高|たか]いですか。","en":"Is that white bag over there expensive?","clip":"x_n5u01d3_p2_2"}],"watch":{"note":"この, その, あの and どの always need a noun right after them. They cannot stand alone before は. With no noun, use これ, それ, あれ or どれ.","bad":"このは何ですか。","good":"これは何ですか。"}}],"compare":{"intro":"これ and この both point at something near you. The difference is whether a noun comes next.","forms":[{"form":"これ","tag":"もの · a thing, alone","mark":"dot","ja":"{これ}は[花|はな]です。","en":"This is a flower."},{"form":"この","tag":"この＋もの · before a noun","mark":"dot","ja":"{この}[花|はな]は[安|やす]いです。","en":"This flower is cheap."},{"form":"ここ","tag":"ばしょ · this place","mark":"dot","ja":"{ここ}は[本|ほん]やです。","en":"This place is a bookshop."}],"check":{"id":"n5u01d3.c1","kind":"choice","type":"文の文法1","label":"花やで","q":"すみません、（　　）[花|はな]は[何|なん]ですか。","options":["ここ","これ","この"],"answer":3,"why":["ここ means this place. It cannot go right before 花.","これ stands alone, as in これは何ですか. It cannot go right before 花.","A noun (花) comes right after the blank, so この."],"explain":null}},"drill":[{"id":"n5u01d3.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：（　　）は[何|なん]ですか。　B：^それは^[魚|さかな]です。","options":["この","どれ","あの","これ"],"answer":4,"why":["この needs a noun after it, as in この魚は.","どれ asks which one. It cannot ask 何ですか at the same time.","あの needs a noun after it, as in あの魚は.","これ stands alone before は. B answers with それ because the fish is near A."],"explain":null},{"id":"n5u01d3.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"（　　）^かばん^は[高|たか]いです。","options":["どこ","それ","その","どれ"],"answer":3,"why":["どこ asks where. It cannot go right before かばん.","それ stands alone. It cannot go right before かばん.","A noun (かばん) comes right after the blank, so その.","どれ cannot go before a noun, and this sentence is not a question."],"explain":null},{"id":"n5u01d3.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：（　　）^かさ^がいいですか。　B：その[白|しろ]いかさがいいです。","options":["どの","[何|なに]","あれ","どれ"],"answer":1,"why":["A asks which umbrella, and かさ comes right after the blank, so どの.","何 cannot go right before かさ like this.","あれ stands alone and does not ask a question.","どれ stands alone, as in どれがいいですか. It cannot go right before かさ."],"explain":null},{"id":"n5u01d3.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"すみません、（　　）^を^ください。","options":["あの","どれ","どこ","あれ"],"answer":4,"why":["あの needs a noun before を, as in あの花をください.","どれ asks which one. You cannot ask for something with a question word.","どこ asks where. A place is not something you ask a shop for.","あれ stands alone, so を can come right after it: あれをください."],"explain":null},{"id":"n5u01d3.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"すみません、","after":"。","tiles":["どの","[人|ひと]が","[先生|せんせい]","ですか"],"star":1,"bank":[2,0,3,1],"hint":"どの needs a noun right after it. Which tile can follow どの?","full":"すみません、{どの}[人|ひと]が[先生|せんせい]ですか。","explain":"どの goes right before 人が. 先生 comes before ですか: どの人が先生ですか, \"Which person is the teacher?\""},{"id":"n5u01d3.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"すみません、","after":"ですか。","tiles":["あれ","は","[何|なん]の","[店|みせ]"],"star":2,"bank":[3,1,0,2],"hint":"あれ stands alone, so は can come straight after it.","full":"すみません、{あれ}は[何|なん]の[店|みせ]ですか。","explain":"あれは comes first. 何の goes right before 店: あれは何の店ですか, \"What kind of shop is that?\""}],"exam":[{"id":"n5u01d3.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：その　魚は　高いですか。　B：いいえ、（　　）魚は　安いです。","options":["これ","この","どれ","ここ"],"answer":2,"explain":"A noun (魚) comes right after the blank, and the fish is near B, so この. これ and ここ stand alone, and どれ is a question word that also cannot go before a noun."},{"id":"n5u01d3.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：あなたの　かさは　（　　）ですか。　B：あの　白い　かさです。","options":["この","あの","どれ","どの"],"answer":3,"explain":"B picks one umbrella out of several, so A asked which one: どれ. どの, この and あの all need a noun right after them."},{"id":"n5u01d3.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"すみません、","after":"ですか。","tiles":["この","花","は","いくら"],"star":1,"bank":[3,1,0,2],"full":"すみません、{この}　花は　いくらですか。","explain":"この, 花, は, いくら. この needs a noun right after it, so この花は comes first, then いくら before ですか."}]},"scene":{"ja":"デパートで","en":"At a department store","intro":"Tap every word you would read on the floor guide and the price tags.","words":[{"id":"floor1","word":"一かい","reading":"いっかい","gloss":"first floor, ground floor","parts":[["一","イッ","one"]],"clip":"s_n5u1d3_floor1"},{"id":"books","word":"本や","reading":"ほんや","gloss":"bookshop","parts":[["本","ホン","book"]],"clip":"s_n5u1d3_books"},{"id":"flower","word":"花","reading":"はな","gloss":"flower","parts":[["花","はな","flower"]],"clip":"s_n5u1d3_flower"},{"id":"fish","word":"魚","reading":"さかな","gloss":"fish","parts":[["魚","さかな","fish"]],"clip":"s_n5u1d3_fish"},{"id":"price","word":"千円","reading":"せんえん","gloss":"1,000 yen","parts":[["千","セン","thousand"],["円","エン","yen"]],"clip":"s_n5u1d3_price"},{"id":"cheap","word":"安い","reading":"やすい","gloss":"cheap","parts":[["安","やす","cheap"]],"clip":"s_n5u1d3_cheap"},{"id":"new","word":"新しい","reading":"あたらしい","gloss":"new","parts":[["新","あたら","new"]],"clip":"s_n5u1d3_new"},{"id":"exit","word":"出口","reading":"でぐち","gloss":"exit","parts":[["出","で","go out"],["口","ぐち","mouth, opening"]],"clip":"s_n5u1d3_exit"}],"check":{"id":"n5u01d3.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"デパートで　_新しい_　本を　買いました。","options":["あたしらい","あらたしい","あたらいし","あたらしい"],"answer":4,"explain":"新しい is read あたらしい, \"new\". The other three mix up the order of the kana."}},"skill":{"kind":"listening","ja":"即時応答","en":"Quick response","ask":"この　もんだいに　えは　ありません。ぶんを　聞いてから、1から3の　へんじの　中で　いちばん　あう　ものを　えらんで　ください。","item":{"id":"n5u01d3.r1","kind":"choice","type":"即時応答","q":"男：すみません、それは　何ですか。","script":["男：すみません、それは何ですか。","ナレーター：1","女：はい、そうです。","ナレーター：2","女：これは、日本のおかしです。","ナレーター：3","女：あれは、おかしです。"],"options":["はい、そうです。","これは、日本のおかしです。","あれは、おかしです。"],"printed":false,"short":["はい、そうです","これは、日本のおかし","あれは、おかし"],"answer":2,"why":["The man asks what it is, not a yes-or-no question, so はい、そうです does not answer him.","He says それ, so the thing is near the woman. She answers with これ and says what it is.","あれ is for something far from both people. He said それ, so the thing is near her."],"clip":"l_n5u1d3"},"audio":[["M","すみません、それは何ですか。","すみません、それはなんですか。"],["N","1",null],["F","はい、そうです。",null],["N","2",null],["F","これは、日本のおかしです。","これは、にほんのおかしです。"],["N","3",null],["F","あれは、おかしです。",null]]}},{"title":"〜の・〜と","grammar":{"points":[{"id":"n5u01d4.p1","form":"〜の","gloss":"'s, of (whose, what kind)","connect":[{"pos":"Noun: who owns it","rule":"〜 ＋ {の} ＋ 〜"},{"pos":"Noun: where someone belongs","rule":"〜 ＋ {の} ＋ 〜"},{"pos":"Noun: what kind","rule":"〜 ＋ {の} ＋ 〜"}],"examples":[{"ja":"これは[母|はは]{の}[本|ほん]です。","en":"This is my mother's book.","clip":"x_n5u01d4_p1_1"},{"ja":"[中山|なかやま]さんは[日本語|にほんご]{の}[先生|せんせい]です。","en":"Ms. Nakayama is a Japanese teacher.","clip":"x_n5u01d4_p1_2"}],"watch":{"note":"When one noun tells you about another noun, put の between them. The owner or the kind comes first, then の, then the thing.","bad":"これはわたし本です。","good":"これはわたしの本です。"}},{"id":"n5u01d4.p2","form":"〜と","gloss":"and (between nouns)","connect":[{"pos":"Two nouns","rule":"〜 ＋ {と} ＋ 〜"},{"pos":"Three nouns","rule":"〜 ＋ {と} ＋ 〜 ＋ {と} ＋ 〜"}],"examples":[{"ja":"[父|ちち]{と}[母|はは]は[先生|せんせい]です。","en":"My father and mother are teachers.","clip":"x_n5u01d4_p2_1"},{"ja":"[友|とも]だち{と}わたしは[大学|だいがく]の[学生|がくせい]です。","en":"My friend and I are university students.","clip":"x_n5u01d4_p2_2"}],"watch":{"note":"This と joins nouns only, like 父と母. It does not join two sentences, and it does not join adjectives to mean \"big and new\". To say two people are teachers, join the people with と and say です once.","bad":"父は先生ですと母も先生です。","good":"父と母は先生です。"}}],"compare":{"intro":"All three come right after a noun, but each one tells you something different.","forms":[{"form":"〜の","tag":"だれの・どんな · whose, what kind","mark":"dot","ja":"[母|はは]{の}[友|とも]だちです。","en":"She is my mother's friend."},{"form":"〜と","tag":"AとB · and","mark":"up","ja":"[母|はは]{と}[友|とも]だちです。","en":"They are my mother and a friend."},{"form":"〜も","tag":"おなじ · too","mark":"dot","ja":"[母|はは]{も}[先生|せんせい]です。","en":"My mother is a teacher too."}],"check":{"id":"n5u01d4.c1","kind":"choice","type":"文の文法1","label":"アルバム","q":"A：これはだれの[本|ほん]ですか。　B：[父|ちち]（　　）[本|ほん]です。","options":["も","の","と"],"answer":2,"why":["父も本です would mean \"my father is a book too\".","The owner, then の, then the thing: 父の本 is my father's book.","父と本 would mean \"my father and a book\". The question asks whose book it is."],"explain":null}},"drill":[{"id":"n5u01d4.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：それはだれのかさですか。　B：^わたし^（　　）かさです。","options":["は","を","の","も"],"answer":3,"why":["わたしはかさです would mean \"I am an umbrella\".","を marks the thing you act on with a verb. There is no verb here.","The owner わたし, then の, then かさ: my umbrella.","わたしもかさです would mean \"I am an umbrella too\"."],"explain":null},{"id":"n5u01d4.d2","kind":"star","type":"文の文法2","label":"Build the sentence","before":"これは","after":"です。","tiles":["わたし","の","[友|とも]だち","の[本|ほん]"],"star":2,"bank":[2,3,0,1],"hint":"The owner always comes before の. Who is the friend's, and whose is the book?","full":"これはわたし{の}[友|とも]だちの[本|ほん]です。","explain":"わたしの友だち is my friend, and 友だちの本 is the friend's book. So わたし, の, 友だち, の本: my friend's book."},{"id":"n5u01d4.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[山川|やまかわ]さんは^[中学校|ちゅうがっこう]^（　　）[先生|せんせい]です。","options":["か","も","と","の"],"answer":4,"why":["中学校か先生 would mean \"a junior high school or a teacher\".","中学校も先生です would mean \"the school is a teacher too\", which makes no sense.","中学校と先生 would mean \"a junior high school and a teacher\". A person cannot be a school.","Where the teacher belongs: 中学校 + の + 先生, a junior high school teacher."],"explain":null},{"id":"n5u01d4.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[日本語|にほんご]の[先生|せんせい]は^ふたり^です。[中山|なかやま]さん（　　）[山川|やまかわ]さんです。","options":["も","か","と","の"],"answer":3,"why":["中山さんも山川さんです would mean \"Nakayama is Yamakawa too\", which makes no sense.","か means \"or\". It gives one person, not two.","と joins the two names: Nakayama and Yamakawa. That makes two teachers.","中山さんの山川さん would be one person, but the clue says there are two."],"explain":null},{"id":"n5u01d4.d5","kind":"choice","type":"文の文法1","label":"Choose the form","q":"これは^[父|ちち]の[本|ほん]^（　　）^[母|はは]の[本|ほん]^です。","options":["を","の","と","も"],"answer":3,"why":["を marks the thing you act on with a verb. There is no verb here.","父の本の母の本 would mean \"my mother's book of my father's book\", which makes no sense.","と joins the two things: my father's book and my mother's book.","父の本も母の本です would mean \"Dad's book is Mom's book too\". It does not fit after これは."],"explain":null},{"id":"n5u01d4.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしの[父|ちち]","after":"です。","tiles":["と","[母|はは]","は","[先生|せんせい]"],"star":1,"bank":[3,1,0,2],"hint":"と goes between the two people. は comes after both of them.","full":"わたしの[父|ちち]{と}[母|はは]は[先生|せんせい]です。","explain":"父と母 joins the two people, は comes after them, and 先生です says what they are: my father and mother are teachers."}],"exam":[{"id":"n5u01d4.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"これは　だれ（　　）かさですか。","options":["の","も","を","が"],"answer":1,"explain":"だれのかさ means \"whose umbrella\": だれ + の + かさ. も, を and が cannot sit between だれ and かさ in this sentence."},{"id":"n5u01d4.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしの　すきな　くだものは　りんご（　　）バナナです。","options":["も","を","の","と"],"answer":4,"explain":"と joins two nouns: apples and bananas. りんごのバナナ (\"the apple's banana\") and りんごもバナナ make no sense, and を needs a verb."},{"id":"n5u01d4.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あの　女の　人は　","after":"　です。","tiles":["わたし","の","日本語の","先生"],"star":2,"bank":[2,0,3,1],"full":"あの　女の　人は　わたしの　{日本語の}　先生　です。","explain":"わたし, の, 日本語の, 先生: my Japanese teacher. The owner わたし comes first, and 日本語の must sit right before 先生 to say what kind of teacher."}]},"scene":{"ja":"かぞくのアルバム","en":"A page of a family album","intro":"Tap each label under the photos.","words":[{"id":"father","word":"父","reading":"ちち","gloss":"(my) father","parts":[["父","ちち","father"]],"clip":"s_n5u1d4_father"},{"id":"mother","word":"母","reading":"はは","gloss":"(my) mother","parts":[["母","はは","mother"]],"clip":"s_n5u1d4_mother"},{"id":"boy","word":"男の子","reading":"おとこのこ","gloss":"boy","parts":[["男","おとこ","man, male"],["子","こ","child"]],"clip":"s_n5u1d4_boy"},{"id":"girl","word":"女の子","reading":"おんなのこ","gloss":"girl","parts":[["女","おんな","woman, female"],["子","こ","child"]],"clip":"s_n5u1d4_girl"},{"id":"friend","word":"友だち","reading":"ともだち","gloss":"friend","parts":[["友","とも","friend"]],"clip":"s_n5u1d4_friend"},{"id":"child","word":"子ども","reading":"こども","gloss":"child, children","parts":[["子","こ","child"]],"clip":"s_n5u1d4_child"},{"id":"name","word":"名前","reading":"なまえ","gloss":"name","parts":[["名","な","name"],["前","まえ","front, before"]],"clip":"s_n5u1d4_name"},{"id":"teacher","word":"先生","reading":"せんせい","gloss":"teacher","parts":[["先","セン","ahead, before"],["生","セイ","life, born"]],"clip":"s_n5u1d4_teacher"}],"check":{"id":"n5u01d4.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"しゃしんの　_女の子_は　わたしの　友だちです。","options":["おんなのこ","おんなのひと","おとこのひと","おとこのこ"],"answer":1,"explain":"女 is おんな and 子 is こ: 女の子, a girl. おとこのこ is 男の子, and おんなのひと and おとこのひと are 女の人 and 男の人."}},"skill":{"kind":"reading","ja":"内容理解（短文）","en":"Short passage","ask":"Who is who in the photo?","seconds":90,"passage":"これは　わたしの　かぞくの　しゃしんです。右の　人は　父です。左の　人は　母です。父と　母は　中学校の　先生です。まん中の　男の子は　わたしです。^わたしの　となりの　女の子^は　^父の　友だちの　子ども^です。名前は　ゆきちゃんです。ゆきちゃんと　わたしは　いい　友だちです。","strategy":"Find the girl in the text, then read the の after her carefully: whose friend, and whose child.","item":{"id":"n5u01d4.r1","kind":"choice","type":"読解・内容理解（短文）","q":"しゃしんの　まん中の　男の子の　となりの　女の子は　だれですか。","options":["父の　友だち","父の　友だちの　子ども","母の　友だちの　子ども","わたしの　いもうと"],"short":["父の友だち","父の友だちの子ども","母の友だちの子ども","わたしのいもうと"],"answer":2,"explain":"The boy in the middle is the writer. The girl next to him is 父の友だちの子ども: the child of his father's friend.","why":["Not the friend. She is the friend's child: 友だちの子ども.","","The friend is the father's friend (父の友だち), not the mother's.","The text never says she is the writer's sister."]}}},{"title":"〜ね・〜よ","grammar":{"points":[{"id":"n5u01d5.p1","form":"〜ね","gloss":"…, isn't it? / …, right?","connect":[{"pos":"Noun","rule":"〜 ＋ です ＋ {ね}"},{"pos":"Adjective (い word)","rule":"〜い ＋ です ＋ {ね}"},{"pos":"Verb, ます form","rule":"〜ます ＋ {ね}"}],"examples":[{"ja":"[今日|きょう]はさむいです{ね}。","en":"It's cold today, isn't it?","clip":"x_n5u01d5_p1_1"},{"ja":"[出口|でぐち]はあそこです{ね}。","en":"The exit is over there, right?","clip":"x_n5u01d5_p1_2"}],"watch":{"note":"ね asks the listener to agree with something they know or feel too. Do not use it for news about yourself, like your name when you first meet.","bad":"はじめまして。わたしはキムですね。","good":"はじめまして。わたしはキムです。"}},{"id":"n5u01d5.p2","form":"〜よ","gloss":"I'm telling you (new to you)","connect":[{"pos":"Noun","rule":"〜 ＋ です ＋ {よ}"},{"pos":"Verb, ます form","rule":"〜ます ＋ {よ}"}],"examples":[{"ja":"[東口|ひがしぐち]はあちらです{よ}。","en":"The east exit is that way.","clip":"x_n5u01d5_p2_1"},{"ja":"この[電車|でんしゃ]は[九時|くじ]に[出|で]ます{よ}。","en":"This train leaves at nine, just so you know.","clip":"x_n5u01d5_p2_2"}],"watch":{"note":"Your friend says さむいですね. You feel the cold too, so agree with ね. よ here sounds like you are telling them something they do not know.","bad":"ええ、さむいですよ。","good":"ええ、さむいですね。"}}],"compare":{"intro":"All three end the same sentence. What changes is who knows the answer.","forms":[{"form":"〜ね","tag":"いっしょ · you know it too","mark":"dot","ja":"[西口|にしぐち]はこちらです{ね}。","en":"The west exit is this way, right?"},{"form":"〜よ","tag":"おしえる · this is new to you","mark":"up","ja":"[西口|にしぐち]はこちらです{よ}。","en":"The west exit is this way (I'm telling you)."},{"form":"〜か","tag":"しつもん · I don't know","mark":"dot","ja":"[西口|にしぐち]はこちらです{か}。","en":"Is the west exit this way?"}],"check":{"id":"n5u01d5.c1","kind":"choice","type":"文の文法1","label":"駅で","q":"（わたしは^しっています^。[友|とも]だちは^しりません^。）あの[人|ひと]はもり[先生|せんせい]です（　　）。","options":["よ","か","ね"],"answer":1,"why":["You know and your friend does not, so you tell them with よ.","か asks a question, but you already know who she is.","ね asks your friend to agree, but your friend does not know her."],"explain":null}},"drill":[{"id":"n5u01d5.d1","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"（ふたりは^いっしょに[空|そら]を[見|み]ています^。）A「いい[天気|てんき]です（　　）。」B「ええ、そうですね。」","options":["よ","か","を","ね"],"answer":4,"why":["よ tells B something new, but B can see the sky too.","か asks a question, but A can see the weather. B's そうですね agrees; it does not answer a question.","を marks the thing a verb acts on. It cannot end a sentence after です.","Both can see the sky, so A shares a feeling B has too. B agrees with そうですね."],"explain":null},{"id":"n5u01d5.d2","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"（Bさんは^しりません^。）A「Bさん、あの[人|ひと]はわたしの[母|はは]です（　　）。」","options":["か","ね","よ","も"],"answer":3,"why":["か asks a question, but A knows who her own mother is.","ね asks B to agree, but B does not know this.","B does not know, so A tells B something new with よ.","も means \"too\". It cannot end a sentence after です."]},{"id":"n5u01d5.d3","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"（ふたりは^いっしょに^ラーメンを[食|た]べています。）A「このラーメンはおいしいです（　　）。」","options":["を","と","よ","ね"],"answer":4,"why":["を marks the thing a verb acts on. It cannot end a sentence after です.","と joins two nouns, as in パンとたまご. It cannot end this sentence.","よ tells B something new, but B is eating the same ramen.","Both are eating it, so A shares a feeling B has too."],"explain":null},{"id":"n5u01d5.d4","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「すみません、[西口|にしぐち]はどこですか。」B「[西口|にしぐち]は","after":"。」","tiles":["あの","ビルの","[前|まえ]です","よ"],"star":1,"bank":[2,3,0,1],"hint":"A asks, so A does not know. Which ending tells new information, and where does it go?","full":"A「すみません、[西口|にしぐち]はどこですか。」B「[西口|にしぐち]はあのビルの[前|まえ]です{よ}。」","explain":"あの goes before ビルの, and ビルの before 前です: \"in front of that building\". よ comes last because B tells A something A does not know."},{"id":"n5u01d5.d5","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"（^Aさんは[電車|でんしゃ]を[見|み]ました^。Bさんは[見|み]ませんでした。）A「あ、[電車|でんしゃ]が[来|き]ました（　　）。」","options":["よ","を","ね","か"],"answer":1,"why":["A saw it and B did not, so A tells B something new with よ.","を marks the thing a verb acts on. It cannot end a sentence after ました.","ね asks B to agree, but B did not see the train.","か asks a question, but A saw the train and knows."],"explain":null},{"id":"n5u01d5.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「","after":"。」B「ええ、そうですね。」","tiles":["[今日|きょう]は","いい","[天気|てんき]","ですね"],"star":2,"bank":[3,1,0,2],"hint":"A and B both feel the weather. いい describes a noun, and the ending that shares a feeling comes last.","full":"A「[今日|きょう]はいい[天気|てんき]です{ね}。」B「ええ、そうですね。」","explain":"今日は comes first as the topic. いい goes right before 天気, and ですね ends the sentence because A shares a feeling B has too."}],"exam":[{"id":"n5u01d5.e1","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"A「Bさん、いすの　上に　かさが　あります（　　）。」B「あ、わたしのです。ありがとうございます。」","options":["よ","か","を","ね"],"answer":1,"explain":"B did not know and says thank you, so A tells B something new with よ. ね would ask B to agree with something B already knows, か would ask about an umbrella A can see, and を cannot end a sentence."},{"id":"n5u01d5.e2","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"（ふたりで　駅まで　あるいて　います。）A「今日は　あついです（　　）。」B「ええ、ほんとうに。」","options":["よ","ね","を","か"],"answer":2,"explain":"They are walking together and both feel the heat, so A shares the feeling with ね and B agrees. か would ask something A can feel, よ would tell B something B already feels, and を cannot end a sentence."},{"id":"n5u01d5.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「バスは　どこから　出ますか。」B「","after":"よ。」","tiles":["北口の","前","から","出ます"],"star":2,"bank":[3,1,0,2],"full":"A「バスは　どこから　出ますか。」B「北口の　前{から}　出ますよ。」","explain":"北口の, 前, から, 出ます. 北口の describes 前, から follows the place the bus leaves from, and 出ます goes before よ."}]},"scene":{"ja":"駅で","en":"At the station","intro":"Tap every sign you would read to find your train and your way out.","words":[{"id":"exit","word":"出口","reading":"でぐち","gloss":"exit","parts":[["出","で","go out"],["口","ぐち","opening, mouth"]],"clip":"s_n5u1d5_exit"},{"id":"entrance","word":"入口","reading":"いりぐち","gloss":"entrance","parts":[["入","いり","go in"],["口","ぐち","opening, mouth"]],"clip":"s_n5u1d5_entrance"},{"id":"east","word":"東口","reading":"ひがしぐち","gloss":"east exit","parts":[["東","ひがし","east"],["口","ぐち","opening, mouth"]],"clip":"s_n5u1d5_east"},{"id":"west","word":"西口","reading":"にしぐち","gloss":"west exit","parts":[["西","にし","west"],["口","ぐち","opening, mouth"]],"clip":"s_n5u1d5_west"},{"id":"south","word":"南口","reading":"みなみぐち","gloss":"south exit","parts":[["南","みなみ","south"],["口","ぐち","opening, mouth"]],"clip":"s_n5u1d5_south"},{"id":"north","word":"北口","reading":"きたぐち","gloss":"north exit","parts":[["北","きた","north"],["口","ぐち","opening, mouth"]],"clip":"s_n5u1d5_north"},{"id":"train","word":"電車","reading":"でんしゃ","gloss":"train","parts":[["電","デン","electricity"],["車","シャ","vehicle"]],"clip":"s_n5u1d5_train"},{"id":"station","word":"駅","reading":"えき","gloss":"station","parts":[["駅","エキ","station"]],"clip":"s_n5u1d5_station"}],"check":{"id":"n5u01d5.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_北口_で　ともだちを　まちます。","options":["きたぐち","きたくち","みなみぐち","ひがしぐち"],"answer":1,"explain":"北 is きた, and in 北口 the 口 is read ぐち, as in 出口 and 入口. きたくち is not a word. みなみぐち is 南口 and ひがしぐち is 東口."}},"skill":{"kind":"listening","ja":"ポイント理解","en":"Point comprehension","ask":"男の人は　どの　出口から　出ますか。","audio":[["N","駅で、男の人と女の人が話しています。男の人はどの出口から出ますか。",null],["M","すみません。山川大学は東口ですか。","すみません。やまかわだいがくはひがしぐちですか。"],["F","山川大学ですか。東口じゃありません。北口ですよ。","やまかわだいがくですか。ひがしぐちじゃありません。きたぐちですよ。"],["M","北口ですね。ありがとうございます。","きたぐちですね。ありがとうございます。"],["F","あ、すみません。北口は山川デパートです。山川大学は西口ですよ。","あ、すみません。きたぐちはやまかわデパートです。やまかわだいがくはにしぐちですよ。"],["M","西口ですね。わかりました。","にしぐちですね。わかりました。"],["N","男の人はどの出口から出ますか。",null]],"item":{"id":"n5u01d5.r1","kind":"choice","type":"ポイント理解","q":"男の人は　どの　出口から　出ますか。","script":["ナレーター：駅で、男の人と女の人が話しています。男の人はどの出口から出ますか。","男：すみません。山川大学は東口ですか。","女：山川大学ですか。東口じゃありません。北口ですよ。","男：北口ですね。ありがとうございます。","女：あ、すみません。北口は山川デパートです。山川大学は西口ですよ。","男：西口ですね。わかりました。","ナレーター：男の人はどの出口から出ますか。"],"options":["北口","東口","西口","南口"],"printed":true,"short":["北口","東口","西口","南口"],"answer":3,"why":["The woman says 北口 first, then corrects it: the north exit is for the department store.","The man asks about the east exit, but the woman says 東口じゃありません.","The woman corrects herself: 山川大学は西口ですよ. The man checks with 西口ですね.","Nobody talks about the south exit."],"explain":null,"clip":"l_n5u1d5"}}},{"title":"まとめ：似ている文法","grammar":{"points":[],"compare":{"intro":"To tell the ten apart, look at what sits next to the blank: between two nouns you need の or と, after the topic you need は or も, before a noun この (これ stands alone), and at the very end です, じゃありません, か, ね or よ.","forms":[{"form":"〜は／〜も","tag":"ちがう・おなじ · topic or \"too\"","mark":"dot","ja":"[今日|きょう]{は}[休|やす]みです。あした{も}[休|やす]みです。","en":"Today is a day off. Tomorrow is a day off too."},{"form":"これ／この","tag":"ひとりで・＋もの · alone or + noun","mark":"dot","ja":"{これ}はわたしのペンです。{この}ペンは[安|やす]いです。","en":"This is my pen. This pen is cheap."},{"form":"〜の／〜と","tag":"どんな・AとB · of or and","mark":"dot","ja":"これは[日本語|にほんご]{の}[本|ほん]{と}ノートです。","en":"These are a Japanese book and a notebook."}],"check":{"id":"n5u01d6.c1","kind":"choice","type":"文の文法1","label":"がっこうで","q":"A：この[白|しろ]いノートは^だれの^ですか。B：[先生|せんせい]（　　）です。","options":["と","の","も"],"answer":2,"why":["先生とです would mean \"with the teacher\". A asked whose notebook it is.","A asks だれの, \"whose\". 先生のです answers it: it is the teacher's.","先生もです would mean \"the teacher too\". It does not say whose the notebook is."]}},"drill":[{"id":"n5u01d6.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[今週|こんしゅう]は[休|やす]みです。^[来週|らいしゅう]^（　　）^[休|やす]みです^。","options":["も","を","と","か"],"answer":1,"why":["This week is a day off, and next week is the same, so も: \"next week too\".","を marks the thing an action is done to. 休みです is not an action.","と joins two nouns, as in 今週と来週は休みです. Here 来週 stands alone before 休みです, so と has nothing to join.","来週か休みです is not a sentence. A question か goes at the very end, after です."],"explain":null},{"id":"n5u01d6.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^[先週|せんしゅう]^（　　）テストはどれですか。","options":["これ","この","の","と"],"answer":3,"why":["これ stands alone and never comes before a noun. 先週これテスト is not Japanese.","この points at a thing near you. It cannot come right after 先週.","先週のテスト is \"last week's test\": の joins the two nouns.","と means \"and\". 先週とテスト would be \"last week and the test\"."],"explain":null},{"id":"n5u01d6.d3","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"（^ふたりでカレンダーを[見|み]ています^。）A「わあ、[毎日|まいにち]クラスがあります（　　）。」B「^ほんとうですね^。」","options":["か","を","よ","ね"],"answer":4,"why":["か asks. A can see the answer, and B replies by agreeing, not answering.","を marks the thing an action is done to. It cannot end a sentence.","よ tells news the other person does not know. B is looking at the same calendar.","Both can see the calendar, so A shares what they both see: ね. B agrees."],"explain":null},{"id":"n5u01d6.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^[父|ちち]は[先生|せんせい]です^。[母|はは]^も^[先生|せんせい]（　　）。","options":["を","です","じゃありません","ます"],"answer":2,"why":["を marks the thing an action is done to. The sentence would have no ending.","も says the mother is the same as the father. He is a teacher, so she is a teacher too: 先生です.","This would say she is not a teacher. That does not match も after \"father is a teacher\".","ます goes after a verb. 先生 is a noun."],"explain":null},{"id":"n5u01d6.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"すみません、","after":"ですか。","tiles":["この","クラスは","[何時|なんじ]","から"],"star":0,"bank":[2,0,3,1],"hint":"この is followed by a noun. Which tile is a noun?","full":"すみません、{この}クラスは[何時|なんじ]からですか。","explain":"この needs a noun right after it, and クラスは is the topic. Then 何時から asks the start time, and ですか closes the question."},{"id":"n5u01d6.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「[午後|ごご]もクラスがありますか。」B「はい、","after":"よ。」","tiles":["[午後|ごご]は","[中山|なかやま][先生|せんせい]の","クラス","です"],"star":2,"bank":[3,1,0,2],"hint":"Start with the topic. Whose class is it?","full":"A「[午後|ごご]もクラスがありますか。」B「はい、[午後|ごご]は[中山|なかやま][先生|せんせい]{の}クラスですよ。」","explain":"午後は is the topic, so it comes first. 中山先生の tells whose class, so it sits right before クラス. です closes the sentence, and よ after it tells A something new."}],"exam":[{"id":"n5u01d6.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"マリアさん（　　）　トムさんは　この　学校の　学生です。","options":["を","の","と","も"],"answer":3,"explain":"と joins two people: マリアさんとトムさん are both students here. の would make Tom \"Maria's Tom\", which makes no sense. マリアさんも　トムさんは does not work: for both you would need マリアさんも　トムさんも. を marks the thing an action is done to."},{"id":"n5u01d6.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あしたは　休みですか。」\nB「いいえ、あしたも　クラスが　あります（　　）。」","options":["よ","を","ね","か"],"answer":1,"explain":"A did not know and asked, so B tells new information: よ. ね is for something both people already know, but A just asked. か would turn B's answer into a question, and を cannot end a sentence."},{"id":"n5u01d6.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「これは　あなたの　かさですか。」B「いいえ、","after":"。友だちのです。」","tiles":["それは","わたしの","かさ","じゃありません"],"star":1,"bank":[2,3,0,1],"full":"A「これは　あなたの　かさですか。」B「いいえ、それは{わたしの}かさじゃありません。友だちのです。」","explain":"それは, わたしの, かさ, じゃありません. それは is the topic: the umbrella is near A, so B says それ. わたしの goes before かさ, and じゃありません comes last, after the noun."}]},"scene":{"ja":"日本語学校のカレンダー","en":"The week's calendar at a language school","intro":"Tap each word on the calendar by the front door of your language school.","words":[{"id":"Mon","word":"月","reading":"げつ","gloss":"Mon. (short label for Monday)","parts":[["月","ゲツ","moon, month"]],"clip":"s_n5u1d6_Mon"},{"id":"every day","word":"毎日","reading":"まいにち","gloss":"every day","parts":[["毎","マイ","every"],["日","ニチ","sun, day"]],"clip":"s_n5u1d6_every_day"},{"id":"this week","word":"今週","reading":"こんしゅう","gloss":"this week","parts":[["今","コン","now"],["週","シュウ","week"]],"clip":"s_n5u1d6_this_week"},{"id":"last week","word":"先週","reading":"せんしゅう","gloss":"last week","parts":[["先","セン","ahead, before"],["週","シュウ","week"]],"clip":"s_n5u1d6_last_week"},{"id":"day off","word":"休み","reading":"やすみ","gloss":"day off, no class","parts":[["休","やす","rest"]],"clip":"s_n5u1d6_day_off"},{"id":"morning","word":"午前","reading":"ごぜん","gloss":"morning, a.m.","parts":[["午","ゴ","noon"],["前","ゼン","before"]],"clip":"s_n5u1d6_morning"},{"id":"afternoon","word":"午後","reading":"ごご","gloss":"afternoon, p.m.","parts":[["午","ゴ","noon"],["後","ゴ","after"]],"clip":"s_n5u1d6_afternoon"},{"id":"time","word":"時間","reading":"じかん","gloss":"time, hour(s)","parts":[["時","ジ","time, hour"],["間","カン","between"]],"clip":"s_n5u1d6_time"}],"check":{"id":"n5u01d6.k1","kind":"choice","type":"表記","label":"How the exam asks it","q":"あしたの　_ごご_は　テストが　あります。","options":["午後","後午","午前","五後"],"answer":1,"explain":"ごご is 午後: 午 (noon) and 後 (after). 午前 is ごぜん, the morning. 五後 uses 五, the number five, not 午. 後午 has the two kanji the wrong way round."}},"skill":{"kind":"reading","ja":"情報検索","en":"Finding information","ask":"Which line of the notice holds the one fact you need?","seconds":90,"passage":"さくら日本語学校\n今週の　かいわの　クラス\n十二日（月）　午後　二時〜三時\n十三日（火）　^午前^　十時〜十一時\n十五日（木）　午後　二時〜三時\n^十六日（金）　午前^　十時〜十一時\n※　^十三日は　先生が　休みです。クラスは　ありません。^","strategy":"Read the question first, then look only at the lines with 午前, and check the note at the bottom.","item":{"id":"n5u01d6.r1","kind":"choice","type":"読解・情報検索","q":"リンさんは　午前の　かいわの　クラスに　出たいです。何日に　学校へ　行きますか。","options":["十二日","十三日","十五日","十六日"],"short":["12日","13日","15日","16日"],"answer":4,"explain":"Only two lines say 午前: the 13th and the 16th. The note says the teacher is off on the 13th and there is no class, so Lin goes on the 16th.","why":["The class on the 12th is 午後, in the afternoon.","The 13th has a morning class, but the note says the teacher is off and there is no class.","The class on the 15th is 午後, in the afternoon.",""]}}}],"test":[{"id":"n5u01t.1","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"わたしの　_国_は　ブラジルです。","options":["こく","まち","しま","くに"],"answer":4,"explain":"国 on its own is くに. こく is how 国 sounds inside longer words such as 中国, never alone. まち (town) and しま (island) are other words with other kanji."},{"id":"n5u01t.2","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"父の　_会社_は　駅の　前です。","options":["かいしゃ","がいしゃ","かいしや","かいじゃ"],"answer":1,"explain":"会社 is かいしゃ, with a small ゃ. がいしゃ adds voicing to か, かいしや has a big や, and かいじゃ adds voicing to しゃ."},{"id":"n5u01t.3","kind":"choice","type":"表記","label":"Kanji spelling","q":"_でんしゃ_で　学校へ　行きます。","options":["雨車","電東","雨東","電車"],"answer":4,"explain":"でんしゃ is 電車: 電 (electricity) with 車 (car). 雨 looks like the top of 電 but is あめ (rain), and 東 looks like 車 but is ひがし (east). Only 電車 is a word."},{"id":"n5u01t.4","kind":"choice","type":"表記","label":"Kanji spelling","q":"_ひがしぐち_は　あちらです。","options":["東口","車口","東日","車日"],"answer":1,"explain":"ひがしぐち is 東口: 東 (east) and 口 (mouth, opening). 車 looks like 東 but is くるま, and 日 looks like 口 but is ひ or にち. Only 東口 is a word."},{"id":"n5u01t.5","kind":"choice","type":"文脈規定","label":"Word in context","q":"あしたは　学校が　（　　）です。","options":["休み","名前","入口","電話"],"answer":1,"explain":"学校が休みです means there is no school tomorrow. A school cannot be a name (名前), an entrance (入口) or a telephone (電話)."},{"id":"n5u01t.6","kind":"choice","type":"文脈規定","label":"Word in context","q":"駅の　前の　（　　）で　じしょを　買いました。","options":["国","本や","電話","名前"],"answer":2,"explain":"で here marks the place where you buy, and a bookshop (本や) sells dictionaries. A telephone (電話) and a name (名前) are not places, and a country (国) is not a shop in front of a station."},{"id":"n5u01t.7","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"_この　本は　ふるいです_。","options":["この　本は　あたらしいです。","この　本は　あたらしくないです。","この　本は　大きくないです。","この　本は　たかくないです。"],"answer":2,"explain":"ふるい (old) means the same as あたらしくない (not new). 大きくない is about size and たかくない about price, and あたらしい says the opposite."},{"id":"n5u01t.8","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"ここは　_入口_です。","options":["ここから　出ます。","ここで　休みます。","ここで　買います。","ここから　入ります。"],"answer":4,"explain":"An entrance (入口) is where you go in, so ここから入ります says the same thing. ここから出ます describes an exit (出口), and resting (休みます) or buying (買います) is not what an entrance is for."},{"id":"n5u01t.9","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「それは　日本の　お金ですか。」B「いいえ、日本の　お金（　　）。中国の　お金です。」","options":["ですよ","じゃ　ありません","です","ですか"],"answer":2,"explain":"B says いいえ and then names Chinese money, so B says it is not Japanese money: じゃありません. です and ですよ would say it is Japanese money, which clashes with いいえ, and ですか would ask a question back instead of answering."},{"id":"n5u01t.10","kind":"choice","type":"文の文法1","label":"Choose the form","q":"父は　先生です。母（　　）　かいしゃいんです。","options":["の","を","は","も"],"answer":3,"explain":"The mother has a different job from the father, so she is a new topic with は. も (also) would need her to have the same job as the father, but he is a teacher. 母のかいしゃいん would mean an employee belonging to the mother, and を does not go before です."},{"id":"n5u01t.11","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あの　男の　人は　だれです（　　）。」B「わたしの　父です。」","options":["か","よ","ね","を"],"answer":1,"explain":"だれ (who) makes this a question, and a polite question ends in か. よ tells the listener something and ね asks them to agree; neither can end a question with だれ. を cannot end a sentence."},{"id":"n5u01t.12","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「すみません。（　　）は　いくらですか。」B「それは　千円です。」","options":["あれ","どれ","これ","この"],"answer":3,"explain":"B answers with それ (the thing near you), so the thing is near A: A says これ. この must have a noun after it, so この cannot stand before は. With あれ, B would also say あれ. どれ is a question word, and a question word does not come before は."},{"id":"n5u01t.13","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「それは　何の　本ですか。」B「日本語（　　）　本です。」","options":["の","と","も","を"],"answer":1,"explain":"何の本 asks what kind of book, and B answers 日本語の本: the の links 日本語 to 本 to say what the book is about. 日本語と本 would mean two things, Japanese and a book. も and を cannot join two nouns like this."},{"id":"n5u01t.14","kind":"choice","type":"文の文法1","label":"Choose the form","q":"かばんの　中に　ノート（　　）　ペンが　あります。","options":["を","と","の","も"],"answer":2,"explain":"The bag has two things in it, a notebook and a pen, and と joins them. ノートのペン would mean a pen that belongs to the notebook, which makes no sense. ノートもペンが is not a way to list two things (that would be ノートもペンも), and を cannot join two nouns."},{"id":"n5u01t.15","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"（ふたりで　いっしょに　花を　見て　います。）A「きれいな　花です（　　）。」B「ええ、とても　きれいです。」","options":["ね","よ","か","を"],"answer":1,"explain":"Both people are looking at the same flowers, so A shares the feeling and asks B to agree with ね, and B agrees. よ would tell B something new, but B can see the flowers too. か would ask about something A can see, and を cannot end a sentence."},{"id":"n5u01t.16","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「それは　何ですか。」B「","after":"よ。」","tiles":["これは","日本の","おかし","です"],"star":2,"bank":[2,0,3,1],"full":"A「それは　何ですか。」B「これは　日本の　{おかし}ですよ。」","explain":"これは, 日本の, おかし, です. A says それ, so B, who holds it, says これは. 日本の describes おかし, so it comes just before it, and です goes before よ at the end."},{"id":"n5u01t.17","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「リンさんは　学生です。","after":"か。」B「はい、そうです。」","tiles":["あの","人","も","学生です"],"star":2,"bank":[1,3,2,0],"full":"A「リンさんは　学生です。あの　人{も}　学生ですか。」B「はい、そうです。」","explain":"あの, 人, も, 学生です. あの needs the noun 人 right after it. も follows 人 because that person is a student too, like リンさん. 学生です goes before か."},{"id":"n5u01t.18","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「リンさんは　日本人ですか。」B「いいえ、","after":"です。」","tiles":["リンさんは","中国","の","人"],"star":2,"bank":[3,1,0,2],"full":"A「リンさんは　日本人ですか。」B「いいえ、リンさんは　中国{の}　人です。」","explain":"リンさんは, 中国, の, 人. リンさんは is the topic and comes first. の joins 中国 and 人 (a person of China), so it sits between them, and 人 goes right before です."},{"id":"n5u01t.19","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","q":"これは　何の　おかしですか。","options":["お母さんの　国の　おかし","りんごの　おかし","バナナの　おかし","マリアさんの　国の　おかし"],"answer":3,"passage":"マリアさん\nきのうは　ありがとう　ございました。これは　わたしの　国の　おかしです。りんごの　おかしじゃ　ありません。バナナの　おかしです。とても　あまいですよ。二つ　あります。一つは　マリアさんの、一つは　お母さんのです。\nキム","short":["お母さんの国","りんご","バナナ","マリアさんの国"],"explain":"キム writes バナナのおかしです right after saying it is not an apple sweet (りんごのおかしじゃありません). It is from キム's country (わたしの国), not マリア's, and お母さん is マリア's mother, who gets one of the two sweets."},{"id":"n5u01t.20","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","q":"ただしい　ものは　どれですか。","options":["おかしは　あまく　ないです。","おかしは　一つです。","おかしは　キムさんの　国の　おかしです。","おかしは　マリアさんの　国の　おかしです。"],"answer":3,"passage":"マリアさん\nきのうは　ありがとう　ございました。これは　わたしの　国の　おかしです。りんごの　おかしじゃ　ありません。バナナの　おかしです。とても　あまいですよ。二つ　あります。一つは　マリアさんの、一つは　お母さんのです。\nキム","short":["あまくない","一つ","キムさんの国","マリアさんの国"],"explain":"わたしの国のおかし is written by キム, so it is a sweet from キム's country. There are two (二つあります), not one. It is not from マリア's country, and キム says it is very sweet (とてもあまいですよ)."},{"id":"n5u01t.21","kind":"choice","type":"読解・情報検索","label":"Finding information","q":"リンさんは　日本語の　本が　ほしいです。何かいへ　行きますか。","options":["一かい","三かい","四かい","五かい"],"answer":4,"passage":"山川デパート\n五かい　本や・きっさてん\n四かい　子どもの　ふく・おもちゃ\n三かい　男の　人の　ふく\n二かい　女の　人の　ふく・かばん\n一かい　花や・くつ\nちか一かい　魚・やさい・おかし\n出口は　一かいの　東口と　西口です。","short":["一かい","三かい","四かい","五かい"],"explain":"Books are sold at the bookshop (本や), on 五かい. 一かい has flowers and shoes, 三かい has men's clothes, and 四かい has children's clothes and toys."},{"id":"n5u01t.22","kind":"choice","type":"読解・情報検索","label":"Finding information","q":"キムさんは　お母さんに　花と　かばんを　買います。何かいと　何かいへ　行きますか。","options":["一かいと　二かい","一かいと　三かい","二かいと　五かい","二かいと　ちか一かい"],"answer":1,"passage":"山川デパート\n五かい　本や・きっさてん\n四かい　子どもの　ふく・おもちゃ\n三かい　男の　人の　ふく\n二かい　女の　人の　ふく・かばん\n一かい　花や・くつ\nちか一かい　魚・やさい・おかし\n出口は　一かいの　東口と　西口です。","short":["一と二","一と三","二と五","二とちか一"],"explain":"Flowers are at the florist (花や) on 一かい, and bags are on 二かい. 三かい has only men's clothes, 五かい has the bookshop and a café, and ちか一かい has food, not flowers."},{"id":"n5u01t.23","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","q":"ただしい　ものは　どれですか。","options":["あさっての　クラスは　三かいです。","あしたは　クラスが　あります。","あしたは　中山先生が　学校に　来ます。","あさっては　クラスが　あります。"],"answer":4,"passage":"リンさん\nあしたの　日本語の　クラスは　休みです。中山先生は　あした　学校に　来ません。あさっての　クラスは　あります。でも、きょうしつは　三かいの　きょうしつじゃ　ありません。二かいの　きょうしつです。\n山川","short":["三かいでクラス","あしたクラスがある","先生があした来る","あさってクラスがある"],"explain":"The note says あさってのクラスはあります. Tomorrow the class is off (休みです) because 中山先生 is not coming (来ません), and the room is not on 三かい but on 二かい."},{"id":"n5u01t.24","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","q":"あさって、リンさんは　どこへ　行きますか。","options":["三かいの　きょうしつ","二かいの　きょうしつ","中山先生の　うち","どこへも　行きません"],"answer":2,"passage":"リンさん\nあしたの　日本語の　クラスは　休みです。中山先生は　あした　学校に　来ません。あさっての　クラスは　あります。でも、きょうしつは　三かいの　きょうしつじゃ　ありません。二かいの　きょうしつです。\n山川","short":["三かい","二かい","先生のうち","行かない"],"explain":"There is a class the day after tomorrow, and it is in 二かいのきょうしつ. The note says it is not the room on 三かい (三かいのきょうしつじゃありません). 中山先生's home is never mentioned, and リン does go, because the class is on."}]},{"n":2,"ja":"場所・ある・いる","en":"Places and what is there","days":[{"title":"ここ／そこ／あそこ・こちら／そちら／あちら","grammar":{"points":[{"id":"n5u02d1.p1","form":"ここ／そこ／あそこ／どこ","gloss":"here, there, over there, where","connect":[{"pos":"A place word as the topic, then a noun","rule":"{ここ} ＋ は ＋ 〜 ＋ です"},{"pos":"Noun (a thing or a place), then the place word","rule":"〜 ＋ は ＋ {あそこ} ＋ です"},{"pos":"Noun, asking where it is","rule":"〜 ＋ は ＋ {どこ} ＋ ですか"}],"examples":[{"ja":"{ここ}は[駅|えき]です。","en":"This place is the station.","clip":"x_n5u02d1_p1_1"},{"ja":"トイレは{どこ}ですか。","en":"Where is the toilet?","clip":"x_n5u02d1_p1_2"}],"watch":{"note":"ここ is a place word and stands on its own. To point at a noun, use この, as in このみせ.","bad":"ここみせはやすいです。","good":"このみせはやすいです。"}},{"id":"n5u02d1.p2","form":"こちら／そちら／あちら／どちら","gloss":"this way, that way (polite); this person","connect":[{"pos":"Noun, then the polite place word","rule":"〜 ＋ は ＋ {あちら} ＋ です"},{"pos":"Noun, asking where politely","rule":"〜 ＋ は ＋ {どちら} ＋ ですか"},{"pos":"Introducing a person, then the person's name","rule":"{こちら} ＋ は ＋ 〜さん ＋ です"}],"examples":[{"ja":"[店|みせ]の[人|ひと]：トイレは{あちら}です。","en":"Shop staff: The toilet is over there.","clip":"x_n5u02d1_p2_1"},{"ja":"{こちら}は[山川|やまかわ]さんです。","en":"This is Mr Yamakawa.","clip":"x_n5u02d1_p2_2"}],"watch":{"note":"For a person in front of you, say こちら, not これ. これ is for things.","bad":"これはやまかわさんです。","good":"こちらはやまかわさんです。"}}],"compare":{"intro":"Three pointing words: one points at a place, one points politely at a place or a person, and one points at a thing.","forms":[{"form":"ここ","tag":"ばしょ · a place (here)","mark":"dot","ja":"{ここ}は[学校|がっこう]です。","en":"This place is a school."},{"form":"こちら","tag":"ていねい · polite (this way, this person)","mark":"up","ja":"[駅|えき]は{こちら}です。","en":"The station is this way."},{"form":"これ","tag":"もの · a thing (this)","mark":"dot","ja":"{これ}は[本|ほん]です。","en":"This is a book."}],"check":{"id":"n5u02d1.c1","kind":"choice","type":"文の文法1","label":"ともだちをしょうかいする","q":"[先生|せんせい]、（　　）は^[友|とも]だちのリンさん^です。","options":["これ","こちら","ここ"],"answer":2,"why":["これ points at a thing. Lin is a person.","こちら points politely at a person in front of you. You are talking to your teacher, so the polite word fits.","ここ points at a place. Lin is a person, not a place."]}},"drill":[{"id":"n5u02d1.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「すみません。[駅|えき]は（　　）ですか。」\nB「^あそこです^。」","options":["だれ","いつ","どこ","なん"],"answer":3,"why":["だれ asks who. A station is not a person.","いつ asks when. B's answer is a place, not a time.","B answers with a place, あそこ, so A asked where the station is.","なん asks what something is. B's answer is a place."],"explain":null},{"id":"n5u02d1.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「すみません、[学校|がっこう]は（　　）ですか。」\nB「^あの[白|しろ]いたてもの^です。」","options":["そこ","あそこ","どこ","ここ"],"answer":3,"why":["そこ would say the school is near B. A is asking, and B answers with a place.","あそこ is how B answers (あの白いたてもの). A does not know yet, so A cannot say it.","A does not know where the school is, so A asks with どこ, and B answers with あの白いたてもの.","ここ would say the school is right here, but A does not know where it is and asks."],"explain":null},{"id":"n5u02d1.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[店|みせ]の[人|ひと]「エレベーターは（　　）です。^どうぞ^。」","options":["だれ","あちら","あの","どちら"],"answer":2,"why":["だれ asks who. An elevator is not a person, and this is not a question.","Shop staff speak politely, and あちら is the polite way to say あそこ, over there.","あの needs a noun right after it, as in あのドア. Here です follows.","どちら asks where. The sentence ends in です, not ですか: she is telling, not asking."],"explain":null},{"id":"n5u02d1.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「^お[国|くに]^は（　　）ですか。」\nB「ブラジルです。」","options":["いつ","どちら","どれ","だれ"],"answer":2,"why":["いつ asks when. Brazil is not a time.","どちら is the polite way to ask where. お国はどちらですか is how you politely ask someone's country.","どれ asks which one of several things you can see or point at. A country is not in front of you.","だれ asks who. A country is not a person."],"explain":null},{"id":"n5u02d1.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「すみません。","after":"か。」\nB「あそこです。」","tiles":["[山川|やまかわ]","[大学|だいがく]は","どこ","です"],"star":2,"bank":[2,0,3,1],"hint":"The place you ask about comes first, with は. どこ sits right before です.","full":"A「すみません。[山川|やまかわ][大学|だいがく]は{どこ}ですか。」\nB「あそこです。」","explain":"山川 is the name of the university, so it sits right before 大学は, the topic. どこ asks where, and ですか closes the question."},{"id":"n5u02d1.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[先生|せんせい]、","after":"です。","tiles":["こちらは","わたしの","[友|とも]だちの","リンさん"],"star":2,"bank":[2,3,0,1],"hint":"Start with the polite word for the person you introduce. Then say who she is.","full":"[先生|せんせい]、{こちら}はわたしの[友|とも]だちのリンさんです。","explain":"こちらは is the topic: the person you are introducing. わたしの goes with 友だち, and 友だちの tells who Lin is, so it sits right before リンさん."}],"exam":[{"id":"n5u02d1.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「すみません。トイレは　どこですか。」\nB「（　　）です。あの　白い　ドアです。」","options":["どれ","あの","あそこ","これ"],"answer":3,"explain":"A asks where, and B points at あの白いドア, far from both of them, so あそこ. これ points at a thing near the speaker, どれ asks a question, and あの needs a noun right after it."},{"id":"n5u02d1.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「山川さんの　会社は　（　　）ですか。」\nB「駅の　前です。」","options":["いくら","だれ","どちら","いつ"],"answer":3,"explain":"B answers with a place, 駅の前, so A asked where, politely: どちら. だれ asks who, いつ asks when, and いくら asks how much."},{"id":"n5u02d1.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"すみません。","after":"か。","tiles":["山川","駅は","こちら","です"],"star":2,"bank":[3,2,0,1],"full":"すみません。山川駅は{こちら}ですか。","explain":"山川, 駅は, こちら, です. 山川 is the name of the station, so it comes right before 駅は, the topic. こちら then says \"this way\", and ですか asks."}]},"scene":{"ja":"駅のまわりのちず","en":"A map of the streets around the station","intro":"Tap each word on the map and the signs you see when you leave the station.","words":[{"id":"station","word":"駅","reading":"えき","gloss":"station","parts":[["駅","エキ","station"]],"clip":"s_n5u2d1_station"},{"id":"exit","word":"出口","reading":"でぐち","gloss":"exit","parts":[["出","で","go out"],["口","ぐち","mouth, opening"]],"clip":"s_n5u2d1_exit"},{"id":"shop","word":"店","reading":"みせ","gloss":"shop","parts":[["店","みせ","shop"]],"clip":"s_n5u2d1_shop"},{"id":"school","word":"学校","reading":"がっこう","gloss":"school","parts":[["学","ガッ","study"],["校","コウ","school"]],"clip":"s_n5u2d1_school"},{"id":"river","word":"川","reading":"かわ","gloss":"river","parts":[["川","かわ","river"]],"clip":"s_n5u2d1_river"},{"id":"road","word":"道","reading":"みち","gloss":"road, street","parts":[["道","みち","road, way"]],"clip":"s_n5u2d1_road"},{"id":"right","word":"右","reading":"みぎ","gloss":"right","parts":[["右","みぎ","right"]],"clip":"s_n5u2d1_right"},{"id":"left","word":"左","reading":"ひだり","gloss":"left","parts":[["左","ひだり","left"]],"clip":"s_n5u2d1_left"}],"check":{"id":"n5u02d1.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_出口_は　あそこです。","options":["でくち","てぐち","でぐち","だぐち"],"answer":3,"explain":"出口 is でぐち: 出 is で, and in this word 口 is read ぐち, as in 北口 (きたぐち). でくち keeps く without the dakuten, てぐち drops the dakuten on で, and だぐち has the wrong vowel."}},"skill":{"kind":"listening","ja":"課題理解","en":"Task comprehension","ask":"男の人は　はじめに　どこへ　行きますか。","audio":[["N","日本語学校で、女の人と男の人が話しています。男の人は、はじめに、どこへ行きますか。","にほんごがっこうで、おんなのひとと　おとこのひとが　はなしています。おとこのひとは、はじめに、どこへ　いきますか。"],["M","すみません。山川先生のへやはどこですか。","すみません。やまかわせんせいのへやはどこですか。"],["F","山川先生のへやは、あそこですよ。でも、山川先生は、いま、しょくどうです。","やまかわせんせいのへやは、あそこですよ。でも、やまかわせんせいは、いま、しょくどうです。"],["M","そうですか。しょくどうはどこですか。",null],["F","一かいです。あ、でも、そのまえに、こちらのうけつけで名前を書いてください。","いっかいです。あ、でも、そのまえに、こちらのうけつけで　なまえを　かいてください。"],["M","はい。うけつけは、こちらですね。",null],["F","ええ、そうです。",null],["N","男の人は、はじめに、どこへ行きますか。","おとこのひとは、はじめに、どこへ　いきますか。"]],"item":{"id":"n5u02d1.r1","kind":"choice","type":"課題理解","q":"男の人は　はじめに　どこへ　行きますか。","script":["ナレーター：日本語学校で、女の人と男の人が話しています。男の人は、はじめに、どこへ行きますか。","男：すみません。山川先生のへやはどこですか。","女：山川先生のへやは、あそこですよ。でも、山川先生は、いま、しょくどうです。","男：そうですか。しょくどうはどこですか。","女：一かいです。あ、でも、そのまえに、こちらのうけつけで名前を書いてください。","男：はい。うけつけは、こちらですね。","女：ええ、そうです。","ナレーター：男の人は、はじめに、どこへ行きますか。"],"options":["しょくどう","うけつけ","きょうしつ","先生の　へや"],"printed":true,"short":["しょくどう","うけつけ","きょうしつ","先生の へや"],"answer":2,"why":["The teacher is in the cafeteria, but the woman says そのまえに: before that, write your name at the reception desk.","そのまえに means \"before that\". He writes his name at the reception desk first, and checks with うけつけは、こちらですね.","Nobody talks about a classroom.","The man asks about the teacher's room, but the teacher is not there now. He is in the cafeteria."],"explain":null,"clip":"l_n5u2d1"}}},{"title":"あります・います","grammar":{"points":[{"id":"n5u02d2.p1","form":"あります","gloss":"there is (things, plants)","connect":[{"pos":"Thing or plant","rule":"〜 ＋ が ＋ {あります}"},{"pos":"Question","rule":"〜 ＋ が ＋ {ありますか}"},{"pos":"Not there","rule":"〜 ＋ は ＋ {ありません}"}],"examples":[{"ja":"あそこに[大|おお]きい[木|き]が{あります}。","en":"There is a big tree over there.","clip":"x_n5u02d2_p1_1"},{"ja":"すみません、[今|いま]、コーヒーは{ありません}。","en":"Sorry, we don't have any coffee right now.","clip":"x_n5u02d2_p1_2"}],"watch":{"note":"ありません means \"there isn't\". じゃありません means \"it is not\". To say a thing is not there, use は or が with ありません.","bad":"ここにペンじゃありません。","good":"ここにペンはありません。"}},{"id":"n5u02d2.p2","form":"います","gloss":"there is (people, animals)","connect":[{"pos":"Person or animal","rule":"〜 ＋ が ＋ {います}"},{"pos":"Question","rule":"〜 ＋ は ＋ {いますか}"},{"pos":"Not there","rule":"〜 ＋ は ＋ {いません}"}],"examples":[{"ja":"[川|かわ]に[魚|さかな]が{います}。","en":"There are fish in the river.","clip":"x_n5u02d2_p2_1"},{"ja":"[先生|せんせい]は{いますか}。……いいえ、{いません}。","en":"Is the teacher here? No, she isn't.","clip":"x_n5u02d2_p2_2"}],"watch":{"note":"People and animals take います, even fish and birds. あります is only for things and plants, so あります for a dog sounds wrong.","bad":"こうえんにいぬがあります。","good":"こうえんにいぬがいます。"}}],"compare":{"intro":"あります and います both say that something is there. です says what something is.","forms":[{"form":"あります","tag":"もの · things, plants","mark":"dot","ja":"[本|ほん]が{あります}。","en":"There is a book."},{"form":"います","tag":"いきもの · people, animals","mark":"dot","ja":"ねこが{います}。","en":"There is a cat."},{"form":"〜です","tag":"なに · what it is","mark":"dot","ja":"これは[本|ほん]{です}。","en":"This is a book."}],"check":{"id":"n5u02d2.c1","kind":"choice","type":"文の文法1","label":"こうえんで","q":"こうえんに[子|こ]どもが（　　）。","options":["あります","います","です"],"answer":2,"why":["あります is for things and plants. Children are people.","Children are people, so they take います.","です says what something is, as in これは本です. 子どもがです is not a sentence."]}},"drill":[{"id":"n5u02d2.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：^[水|みず]^がありますか。B：はい、（　　）。","options":["います","です","ありません","あります"],"answer":4,"why":["います is for people and animals. Water is a thing.","はい、です is not an answer. The answer repeats the verb of the question.","ありません means \"there isn't\". It clashes with はい.","Water is a thing, so it takes あります. The yes answer repeats the verb: はい、あります."],"explain":null},{"id":"n5u02d2.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あそこに^いぬ^が（　　）。","options":["います","あります","ありません","じゃありません"],"answer":1,"why":["A dog is an animal, so it takes います.","あります is for things and plants, not for a dog.","ありません is the no form of あります, so it is also wrong for a dog.","じゃありません means \"it is not\". It does not follow が."]},{"id":"n5u02d2.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：^ペン^がありますか。B：いいえ、（　　）。","options":["じゃありません","あります","ありません","いません"],"answer":3,"why":["じゃありません means \"it is not\" and needs a noun before it. Here B says the pen is not there.","あります means \"there is\". It clashes with いいえ.","A pen is a thing, so the no answer is ありません.","いません is for people and animals. A pen is a thing."],"explain":null},{"id":"n5u02d2.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：[川|かわ]に^[魚|さかな]^がいますか。B：いいえ、（　　）。","options":["じゃありません","います","いません","ありません"],"answer":3,"why":["じゃありません means \"it is not\" and needs a noun before it. Here B says there are no fish.","います means \"there is\". It clashes with いいえ.","Fish are animals, so the no answer is いません.","ありません is for things and plants. Fish are animals."],"explain":null},{"id":"n5u02d2.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A：その[店|みせ]に[日本語|にほんご]の","after":"。B：はい、あります。","tiles":["[本|ほん]","が","あります","か"],"star":2,"bank":[3,1,0,2],"hint":"日本語の needs a noun right after it. か always comes last.","full":"A：その[店|みせ]に[日本語|にほんご]の[本|ほん]が{あります}か。B：はい、あります。","explain":"日本語の describes 本, so 本 comes first. が follows the thing, then あります, and か at the end makes the question."},{"id":"n5u02d2.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あそこに","after":"。[名前|なまえ]はケンくんです。","tiles":["[男|おとこ]の","[子|こ]","が","います"],"star":2,"bank":[2,3,1,0],"hint":"男の needs a noun right after it. Which verb goes with a child?","full":"あそこに[男|おとこ]の[子|こ]が{います}。[名前|なまえ]はケンくんです。","explain":"男の describes 子, so they go together first. が follows the person, and a boy takes います."}],"exam":[{"id":"n5u02d2.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あそこに　大きい　木が（　　）。","options":["でした","あります","います","です"],"answer":2,"explain":"A tree is a plant, so it takes あります. います is for people and animals. です and でした say what something is, and cannot follow が here."},{"id":"n5u02d2.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：きょうしつに　だれか　いますか。B：はい、先生が（　　）。","options":["あります","います","いません","です"],"answer":2,"explain":"A teacher is a person, so います. あります is for things and plants. いません clashes with はい, and 先生がです is not a sentence."},{"id":"n5u02d2.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あの　川には","after":"よ。","tiles":["小さい","魚","が","います"],"star":1,"bank":[3,0,2,1],"full":"あの　川には　小さい　{魚}が　いますよ。","explain":"小さい, 魚, が, います. 小さい describes 魚, so it sits right before it. が follows the fish, and fish take います."}]},"scene":{"ja":"こうえんで","en":"At the park","intro":"Tap every word you can find on the park map and the notice board.","words":[{"id":"entrance","word":"入口","reading":"いりぐち","gloss":"entrance","parts":[["入","いり","go in"],["口","ぐち","mouth, opening"]],"clip":"s_n5u2d2_entrance"},{"id":"exit","word":"出口","reading":"でぐち","gloss":"exit","parts":[["出","で","go out"],["口","ぐち","mouth, opening"]],"clip":"s_n5u2d2_exit"},{"id":"flower","word":"花","reading":"はな","gloss":"flower","parts":[["花","はな","flower"]],"clip":"s_n5u2d2_flower"},{"id":"tree","word":"木","reading":"き","gloss":"tree","parts":[["木","き","tree, wood"]],"clip":"s_n5u2d2_tree"},{"id":"river","word":"川","reading":"かわ","gloss":"river","parts":[["川","かわ","river"]],"clip":"s_n5u2d2_river"},{"id":"fish","word":"魚","reading":"さかな","gloss":"fish","parts":[["魚","さかな","fish"]],"clip":"s_n5u2d2_fish"},{"id":"closed","word":"休み","reading":"やすみ","gloss":"closed, day off","parts":[["休","やす","rest"]],"clip":"s_n5u2d2_closed"},{"id":"children","word":"子ども","reading":"こども","gloss":"child, children","parts":[["子","こ","child"]],"clip":"s_n5u2d2_children"}],"check":{"id":"n5u02d2.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"こうえんに　きれいな　_花_が　たくさん　あります。","options":["き","そら","はな","くさ"],"answer":3,"explain":"花 is read はな, \"flower\". くさ means grass, a different word, き (tree) is 木, and そら (sky) is 空."}},"skill":{"kind":"reading","ja":"内容理解（短文）","en":"Short passage","ask":"What is in the park, and what is not there?","seconds":90,"passage":"ケンさん、こんにちは。わたしの　うちの　ちかくに　こうえんが　あります。こうえんには　川が　あります。川には　^魚が　います^。^花は　あまり　ありません^が、大きい　木が　たくさん　あります。^子どもは　あまり　いません^。でも、いつも　^白い　ねこが　います^。こんど　いっしょに　行きませんか。マリア","strategy":"Sort each sentence: あります or います means it is there, ありません or いません means it is not, and あまり before them means not much.","item":{"id":"n5u02d2.r1","kind":"choice","type":"読解・内容理解（短文）","q":"こうえんに　ついて、ただしい　ものは　どれですか。","options":["川に　魚は　いません。","花が　たくさん　あります。","白い　ねこが　います。","子どもが　たくさん　います。"],"short":["魚はいない","花がたくさん","白いねこがいる","子どもがたくさん"],"answer":3,"explain":"Maria writes いつも白いねこがいます: there is always a white cat in the park.","why":["Maria writes 川には魚がいます: there are fish in the river.","Maria writes 花はあまりありません: there are not many flowers. The trees are what there are a lot of.","","Maria writes 子どもはあまりいません: there are not many children."]}}},{"title":"〜に〜があります・〜は〜にあります","grammar":{"points":[{"id":"n5u02d3.p1","form":"〜に〜があります／〜に〜がいます","gloss":"there is … in (a place)","connect":[{"pos":"Place, then a thing","rule":"〜{に}〜{があります}"},{"pos":"Place, then a person or animal","rule":"〜{に}〜{がいます}"},{"pos":"Question: what or who is there","rule":"〜{に}[何|なに]{がありますか}／〜{に}だれ{がいますか}"}],"examples":[{"ja":"[一|いっ]かい{に}[花|はな]や{があります}。","en":"There is a flower shop on the first floor.","clip":"x_n5u02d3_p1_1"},{"ja":"[入口|いりぐち]{に}[店|みせ]の[人|ひと]{がいます}。","en":"There is a shop assistant at the entrance.","clip":"x_n5u02d3_p1_2"}],"watch":{"note":"The place comes first and the new thing takes が. A question word like 何 or だれ never takes は. Use が: 何がありますか.","bad":"あそこに何はありますか。","good":"あそこに何がありますか。"}},{"id":"n5u02d3.p2","form":"〜は〜にあります／〜は〜にいます","gloss":"(the thing or person) is in (a place)","connect":[{"pos":"Thing, then place","rule":"〜{は}〜{にあります}"},{"pos":"Person or animal, then place","rule":"〜{は}〜{にいます}"},{"pos":"Question: where","rule":"〜{は}どこ{にありますか}／〜{は}どこ{にいますか}"}],"examples":[{"ja":"[水|みず]{は}あそこ{にあります}。","en":"The water is over there.","clip":"x_n5u02d3_p2_1"},{"ja":"[母|はは]{は}[二|に]かい{にいます}。","en":"My mother is on the second floor.","clip":"x_n5u02d3_p2_2"}],"watch":{"note":"To say where someone or something is, the place takes に. で is for the place where you do something, as in 店で買います.","bad":"母は店でいます。","good":"母は店にいます。"}}],"compare":{"intro":"All three join a thing and a place. The word order and が or は show what the listener already knows.","forms":[{"form":"〜に〜があります","tag":"なにが？ · what is there (new)","mark":"dot","ja":"[二|に]かい{に}[本|ほん]や{があります}。","en":"There is a bookshop on the second floor."},{"form":"〜は〜にあります","tag":"どこに？ · where a known thing is","mark":"dot","ja":"[本|ほん]や{は}[二|に]かい{にあります}。","en":"The bookshop is on the second floor."},{"form":"〜は〜です","tag":"ばしょ · short way to say where","mark":"dot","ja":"[本|ほん]や{は}[二|に]かい{です}。","en":"The bookshop is on the second floor (short form)."}],"check":{"id":"n5u02d3.c1","kind":"choice","type":"文の文法1","label":"スーパーで","q":"すみません、[二|に]かいに[何|なに]（　　）ありますか。","options":["に","が","は"],"answer":2,"why":["に already marks the place (二かい). 何 is the thing, not a place.","The place comes first with に, and the thing you ask about takes が: 何がありますか.","A question word like 何 never takes は."],"explain":null}},"drill":[{"id":"n5u02d3.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^あそこに^いぬ（　　）いますよ。","options":["が","を","で","へ"],"answer":1,"why":["The place comes first with に, and the dog is new information, so が.","を marks what you do something to. いる does not take を.","で marks where you do something. Here いぬ is who is there, not a place.","へ marks where you go. いぬ is not a place you go to."]},{"id":"n5u02d3.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[本|ほん]やは^[二|に]かい^（　　）あります。","options":["へ","に","を","が"],"answer":2,"why":["へ marks where you go. あります does not take へ.","二かい is where the bookshop is, and the place before あります takes に.","を marks what you do something to. あります does not take を.","The bookshop already has は. 二かいが would make the second floor the thing that exists."],"explain":null},{"id":"n5u02d3.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：お[父|とう]さんは（　　）いますか。　B：^[入口|いりぐち]にいます^。","options":["だれが","どこに","どこが","どこを"],"answer":2,"why":["A already named the person (お父さんは). B answers with a place, not a person.","B answers with a place (入口に), so A asked where: どこにいますか.","どこ is a place, so it takes に here, not が.","いる does not take を."],"explain":null},{"id":"n5u02d3.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：[一|いっ]かいに^[何|なに]が^ありますか。　B：（　　）。","options":["[水|みず]と[花|はな]があります","[水|みず]と[花|はな]がいます","[水|みず]と[花|はな]はどこですか","[水|みず]と[花|はな]にあります"],"answer":1,"why":["A asks 何がありますか, so B names the things with が and uses あります.","Water and flowers are things, so あります, not います.","B must answer A's question, not ask a new one.","に marks the place. Water and flowers are the things that are there, so they take が."]},{"id":"n5u02d3.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[店|みせ]の[入口|いりぐち]に","after":"よ。","tiles":["[安|やす]い","[花|はな]","が","あります"],"star":2,"bank":[2,0,3,1],"hint":"The place (入口に) is already first. What is there, and which word marks it?","full":"[店|みせ]の[入口|いりぐち]に[安|やす]い[花|はな]{があります}よ。","explain":"安い goes right before 花. The new thing takes が, and あります comes last: 店の入口に安い花がありますよ, \"There are cheap flowers at the shop entrance.\""},{"id":"n5u02d3.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A：すみません、[花|はな]はどこですか。　B：[花|はな]","after":"よ。","tiles":["は","[二|に]かい","に","あります"],"star":2,"bank":[1,3,0,2],"hint":"A already asked about the flowers, so they take は. Which tile marks the place?","full":"A：すみません、[花|はな]はどこですか。　B：[花|はな]{は}[二|に]かい{にあります}よ。","explain":"は goes right after 花 because A already knows about the flowers. Then the place 二かい with に, and あります last: 花は二かいにありますよ."}],"exam":[{"id":"n5u02d3.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：きょうしつに　だれが　いますか。　B：先生（　　）　います。","options":["で","が","を","に"],"answer":2,"explain":"A asks だれがいますか, so B names the new person with が. いる does not take を, に would make 先生 a place, and で marks where you do something."},{"id":"n5u02d3.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"母は　いま　二かい（　　）。","options":["が　います","で　います","に　あります","に　います"],"answer":4,"explain":"母 is a person, so います, and the place where she is takes に. あります is for things, 二かいが would make the floor the one who is there, and で is for where you do something."},{"id":"n5u02d3.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしの　うちの　ちかくに","after":"。","tiles":["大きい","店","が","あります"],"star":2,"bank":[3,1,2,0],"full":"わたしの　うちの　ちかくに　大きい　店{が}　あります。","explain":"大きい, 店, が, あります. The place (ちかくに) comes first, 大きい goes right before 店, the new thing takes が, and あります comes last."}]},"scene":{"ja":"スーパーで","en":"At a supermarket","intro":"Tap every word you would read on the signs above the aisles and the doors.","words":[{"id":"entrance","word":"入口","reading":"いりぐち","gloss":"entrance","parts":[["入","いり","go in"],["口","ぐち","mouth, opening"]],"clip":"s_n5u2d3_entrance"},{"id":"exit","word":"出口","reading":"でぐち","gloss":"exit","parts":[["出","で","go out"],["口","ぐち","mouth, opening"]],"clip":"s_n5u2d3_exit"},{"id":"fish","word":"魚","reading":"さかな","gloss":"fish","parts":[["魚","さかな","fish"]],"clip":"s_n5u2d3_fish"},{"id":"water","word":"水","reading":"みず","gloss":"water","parts":[["水","みず","water"]],"clip":"s_n5u2d3_water"},{"id":"flower","word":"花","reading":"はな","gloss":"flower","parts":[["花","はな","flower"]],"clip":"s_n5u2d3_flower"},{"id":"floor2","word":"二かい","reading":"にかい","gloss":"second floor","parts":[["二","ニ","two"]],"clip":"s_n5u2d3_floor2"},{"id":"price","word":"百円","reading":"ひゃくえん","gloss":"100 yen","parts":[["百","ヒャク","hundred"],["円","エン","yen"]],"clip":"s_n5u2d3_price"},{"id":"toilet","word":"お手あらい","reading":"おてあらい","gloss":"restroom, toilet","parts":[["手","て","hand"]],"clip":"s_n5u2d3_toilet"}],"check":{"id":"n5u02d3.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"店の　_入口_に　花が　あります。","options":["いりぐち","にゅうぐち","いれくち","いりくち"],"answer":1,"explain":"入口 is read いりぐち, \"entrance\": 入 is いり and 口 becomes ぐち, as in 出口 (でぐち). いりくち misses the change to ぐ, and にゅうぐち and いれくち are not words."}},"skill":{"kind":"listening","ja":"発話表現","en":"Expressions","situation":"In a supermarket, a man holding an empty basket looks around for the water and turns to a shop assistant.","ask":"店で　水を　買いたいです。店の　人に　何と　いいますか。","item":{"id":"n5u02d3.r1","kind":"choice","type":"発話表現","q":"店で　水を　買いたいです。店の　人に　何と　いいますか。","script":["ナレーター：店で　水を　買いたいです。店の　人に　何と　いいますか。","ナレーター：1","男：すみません、水は　どこに　いますか。","ナレーター：2","男：すみません、あそこに　水が　ありますよ。","ナレーター：3","男：すみません、水は　どこに　ありますか。"],"options":["すみません、水は　どこに　いますか。","すみません、あそこに　水が　ありますよ。","すみません、水は　どこに　ありますか。"],"printed":false,"short":["水は　どこに　いますか","あそこに　水が　ありますよ","水は　どこに　ありますか"],"answer":3,"why":["Water is a thing, so the question needs あります, not います.","This tells the assistant where the water is. The man does not know, so he needs to ask.",""],"clip":"l_n5u2d3"},"audio":[["N","店で　水を　買いたいです。店の　人に　何と　いいますか。","みせで　みずを　かいたいです。みせの　ひとに　なんと　いいますか。"],["N","1","いち"],["M","すみません、水は　どこに　いますか。","すみません、みずは　どこに　いますか。"],["N","2","に"],["M","すみません、あそこに　水が　ありますよ。","すみません、あそこに　みずが　ありますよ。"],["N","3","さん"],["M","すみません、水は　どこに　ありますか。","すみません、みずは　どこに　ありますか。"]]}},{"title":"〜の上／中／前・〜や〜など","grammar":{"points":[{"id":"n5u02d4.p1","form":"〜の上／中／前","gloss":"on, in, in front of (where exactly)","connect":[{"pos":"Noun (the thing you measure from) + position word","rule":"〜 ＋ {の} ＋ {[上|うえ]}／{[下|した]}／{[中|なか]}／{[外|そと]} ＋ に"},{"pos":"Noun + position word","rule":"〜 ＋ {の} ＋ {[前|まえ]}／{[後|うし]ろ}／{[右|みぎ]}／{[左|ひだり]}／{となり} ＋ に"}],"examples":[{"ja":"つくえ{の[上|うえ]}に[日本語|にほんご]の[本|ほん]があります。","en":"There is a Japanese book on the desk.","clip":"x_n5u02d4_p1_1"},{"ja":"ねこはいす{の[下|した]}にいます。","en":"The cat is under the chair.","clip":"x_n5u02d4_p1_2"}],"watch":{"note":"Put の between the thing and the position word. The thing comes first: つくえの下 is \"under the desk\".","bad":"かばんはつくえ下にあります。","good":"かばんはつくえの下にあります。"}},{"id":"n5u02d4.p2","form":"〜や〜（など）","gloss":"A and B (and other things)","connect":[{"pos":"Two nouns, as examples","rule":"〜 ＋ {や} ＋ 〜"},{"pos":"Two nouns, and more like them","rule":"〜 ＋ {や} ＋ 〜 ＋ {など}"}],"examples":[{"ja":"かばんの[中|なか]に[本|ほん]{や}ノートがあります。","en":"In the bag there are books, notebooks and so on.","clip":"x_n5u02d4_p2_1"},{"ja":"れいぞうこに[魚|さかな]{や}くだもの{など}があります。","en":"In the fridge there is fish, fruit and other things.","clip":"x_n5u02d4_p2_2"}],"watch":{"note":"や joins two or more nouns and hints that there are other things too. With only one noun, you cannot say 本や. Say 本など (books and so on).","bad":"つくえの上に本やがあります。","good":"つくえの上に本などがあります。"}}],"compare":{"intro":"All three come right after a noun. の上 says where something is; や and と list things.","forms":[{"form":"〜の上","tag":"ばしょ · where","mark":"dot","ja":"つくえ{の[上|うえ]}にペンがあります。","en":"There is a pen on the desk."},{"form":"〜や〜","tag":"いくつか · and others","mark":"up","ja":"つくえの[上|うえ]にペン{や}ノートがあります。","en":"On the desk there are pens, notebooks and other things."},{"form":"〜と〜","tag":"ぜんぶ · and (that is all)","mark":"dot","ja":"つくえの[上|うえ]にペン{と}ノートがあります。","en":"On the desk there are a pen and a notebook."}],"check":{"id":"n5u02d4.c1","kind":"choice","type":"文の文法1","label":"はこの中","q":"A：はこの[中|なか]に[何|なに]がありますか。　B：ペン（　　）けしゴムです。^それだけです^。","options":["と","の","や"],"answer":1,"why":["B names everything in the box, so と: a pen and an eraser, nothing else.","ペンのけしゴム would be \"the pen's eraser\". B is listing two things.","や hints that there are other things too, but B says それだけです: that is all."],"explain":null}},"drill":[{"id":"n5u02d4.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"つくえ（　　）^[上|うえ]^に[本|ほん]があります。","options":["と","が","の","に"],"answer":3,"why":["つくえと上 would mean \"the desk and the top\", two separate things.","が marks what is there. Here 本が already does that.","The thing, then の, then the position word: つくえの上, on the desk.","に comes after the position word (上に), not between つくえ and 上."],"explain":null},{"id":"n5u02d4.d2","kind":"choice","type":"文の文法1","label":"Choose the word","q":"わたしは^[山川|やまかわ]さんの[右|みぎ]^にいます。[山川|やまかわ]さんはわたしの（　　）にいます。","options":["[前|まえ]","[上|うえ]","[右|みぎ]","[左|ひだり]"],"answer":4,"why":["We are side by side, so she is not in front of me.","A person standing next to me is not above me.","Two people side by side cannot both be on the other's right.","If I am on Ms. Yamakawa's right, she is on my left."],"explain":null},{"id":"n5u02d4.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"かばんの[中|なか]に[本|ほん]（　　）ノート^など^があります。","options":["や","の","も","を"],"answer":1,"why":["や joins the two nouns, and など says there are other things too.","本のノート would be \"a book's notebook\", which makes no sense.","本もノートなど does not join the two things. も means \"too\".","を marks the thing you act on with a verb. あります does not take を."]},{"id":"n5u02d4.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[店|みせ]には^いろいろなもの^があります。パン（　　）ぎゅうにゅうなどです。","options":["を","の","や","で"],"answer":3,"why":["を needs a verb that acts on something. です does not take を.","パンのぎゅうにゅう would be \"bread's milk\", which makes no sense.","The shop has many things, so や gives two examples and など says there are more.","で does not join two nouns in a list."],"explain":null},{"id":"n5u02d4.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしのかばんは","after":"あります。","tiles":["[中山|なかやま]さんの","いすの","[下|した]","に"],"star":2,"bank":[2,0,3,1],"hint":"Whose chair is it? Then the chair, then the position word, then に.","full":"わたしのかばんは[中山|なかやま]さんのいす{の[下|した]}にあります。","explain":"中山さんのいす is Mr. Nakayama's chair. いすの下 is under the chair, and に comes after the position word: under Mr. Nakayama's chair."},{"id":"n5u02d4.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"れいぞうこの[中|なか]に[魚|さかな]","after":"あります。","tiles":["や","くだもの","など","が"],"star":2,"bank":[3,2,0,1],"hint":"や goes between two nouns. など comes after the last noun, and が after など.","full":"れいぞうこの[中|なか]に[魚|さかな]{や}くだものなどがあります。","explain":"魚やくだもの joins the two foods, など says there are more, and が marks what is there before あります."}],"exam":[{"id":"n5u02d4.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ぎんこうは　えきの　前（　　）あります。","options":["で","に","が","を"],"answer":2,"explain":"The place where something is takes に: えきの前に あります. を needs an action verb, で marks where an action happens, and ぎんこうは already says what is there, so が does not fit."},{"id":"n5u02d4.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"テーブルの　上に　りんご（　　）バナナなどが　あります。","options":["へ","の","や","を"],"answer":3,"explain":"や joins two nouns, and など says there is more: apples, bananas and so on. りんごのバナナ makes no sense, を needs an action verb, and へ shows a direction."},{"id":"n5u02d4.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"かぎは　テレビの　","after":"　あります。","tiles":["前の","テーブルの","上","に"],"star":1,"bank":[2,3,1,0],"full":"かぎは　テレビの　前の　{テーブルの}　上に　あります。","explain":"前の, テーブルの, 上, に: the key is on the table in front of the TV. テレビの前の テーブル is the table in front of the TV, and テーブルの上に says it is on top of that table."}]},"scene":{"ja":"きょうしつのえ","en":"A picture of a classroom","intro":"Tap each label on the picture of the classroom.","words":[{"id":"on","word":"上","reading":"うえ","gloss":"on, above, top","parts":[["上","うえ","up, above"]],"clip":"s_n5u2d4_on"},{"id":"under","word":"下","reading":"した","gloss":"under, below","parts":[["下","した","down, below"]],"clip":"s_n5u2d4_under"},{"id":"in","word":"中","reading":"なか","gloss":"in, inside","parts":[["中","なか","middle, inside"]],"clip":"s_n5u2d4_in"},{"id":"outside","word":"外","reading":"そと","gloss":"outside","parts":[["外","そと","outside"]],"clip":"s_n5u2d4_outside"},{"id":"front","word":"前","reading":"まえ","gloss":"in front, the front","parts":[["前","まえ","front, before"]],"clip":"s_n5u2d4_front"},{"id":"back","word":"後ろ","reading":"うしろ","gloss":"behind, the back","parts":[["後","うし","behind, after"]],"clip":"s_n5u2d4_back"},{"id":"right","word":"右","reading":"みぎ","gloss":"right","parts":[["右","みぎ","right"]],"clip":"s_n5u2d4_right"},{"id":"left","word":"左","reading":"ひだり","gloss":"left","parts":[["左","ひだり","left"]],"clip":"s_n5u2d4_left"}],"check":{"id":"n5u02d4.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"まどの　_外_に　大きい　木が　あります。","options":["そと","うち","しろ","なか"],"answer":1,"explain":"外 is そと, outside. なか is 中 (inside), うち means inside or home and is not read from 外 here, and しろ means white."}},"skill":{"kind":"reading","ja":"内容理解（短文）","en":"Short passage","ask":"Where is the key?","seconds":90,"passage":"アンナさんへ　へやの　かぎは　つくえの　上に　ありません。^つくえの　となりの　本だなの　中^に　あります。本だなの　上にも　はこが　ありますが、はこの　中には　ペンや　ノートなどが　あります。れいぞうこに　パンや　くだものが　あります。どうぞ。　けい子より","strategy":"Find かぎ, then read past ありません to the sentence that says where it really is.","item":{"id":"n5u02d4.r1","kind":"choice","type":"読解・内容理解（短文）","q":"かぎは　どこに　ありますか。","options":["本だなの　上の　はこの　中","れいぞうこの　中","つくえの　上","本だなの　中"],"short":["本だなの上のはこの中","れいぞうこの中","つくえの上","本だなの中"],"answer":4,"explain":"The note says the key is not on the desk (ありません). The next sentence says it is in the bookshelf next to the desk: 本だなの中.","why":["The box on the bookshelf has pens, notebooks and so on, not the key.","The fridge has bread and fruit, not the key.","The note says つくえの上に ありません: it is not on the desk.",""]}}},{"title":"いくつ／いくら・〜ぐらい／〜ごろ","grammar":{"points":[{"id":"n5u02d5.p1","form":"いくつ・いくら","gloss":"how many (how old) / how much money","connect":[{"pos":"Noun (things you count)","rule":"〜は {いくつ} ありますか"},{"pos":"Noun (asking a price)","rule":"〜は {いくら} ですか"},{"pos":"Noun (asking someone's age)","rule":"〜は （お）{いくつ} ですか"}],"examples":[{"ja":"いすは{いくつ}ありますか。","en":"How many chairs are there?","clip":"x_n5u02d5_p1_1"},{"ja":"このかばんは{いくら}ですか。","en":"How much is this bag?","clip":"x_n5u02d5_p1_2"}],"watch":{"note":"いくら asks about money. いくつ asks how many, or how old. To ask the price of a bag, use いくら.","bad":"すみません、このかばんはいくつですか。","good":"すみません、このかばんはいくらですか。"}},{"id":"n5u02d5.p2","form":"〜ぐらい／くらい・〜ごろ","gloss":"about (an amount) / around (a time)","connect":[{"pos":"Number, amount or length of time","rule":"〜 ＋ {ぐらい}／{くらい}"},{"pos":"Clock time or day","rule":"〜 ＋ {ごろ}"}],"examples":[{"ja":"[駅|えき]まで[十分|じゅっぷん]{ぐらい}です。","en":"It's about ten minutes to the station.","clip":"x_n5u02d5_p2_1"},{"ja":"[十一時|じゅういちじ]{ごろ}ねます。","en":"I go to bed around eleven.","clip":"x_n5u02d5_p2_2"}],"watch":{"note":"ごろ is for a point in time, like a clock time. 二時間 is a length of time, so use ぐらい.","bad":"日本語を二時間ごろべんきょうしました。","good":"日本語を二時間ぐらいべんきょうしました。"}}],"compare":{"intro":"All three go in a question about a number. What changes is what kind of number you want.","forms":[{"form":"いくつ","tag":"かず · how many","mark":"dot","ja":"りんごは{いくつ}ありますか。","en":"How many apples are there?"},{"form":"いくら","tag":"おかね · how much money","mark":"dot","ja":"りんごは{いくら}ですか。","en":"How much are the apples?"},{"form":"何時ごろ","tag":"じかん · around what time","mark":"dot","ja":"[何時|なんじ]{ごろ}[来|き]ますか。","en":"Around what time will you come?"}],"check":{"id":"n5u02d5.c1","kind":"choice","type":"文の文法1","label":"くだものやで","q":"A「このりんごは（　　）ですか。」B「^[一|ひと]つ[百円|ひゃくえん]^です。」","options":["[何時|なんじ]ごろ","いくつ","いくら"],"answer":3,"why":["何時ごろ asks about a time. B answers with a price.","いくつ asks how many. B answers with a price, 百円.","B answers with a price, so A asked how much with いくら."],"explain":null}},"drill":[{"id":"n5u02d5.d1","kind":"choice","type":"文の文法1","label":"Choose the word","q":"（[店|みせ]で）A「すみません、このパンは（　　）ですか。」B「^[百五十円|ひゃくごじゅうえん]^です。」","options":["どこ","いくら","いくつ","[何時|なんじ]"],"answer":2,"why":["どこ asks where. B answers with a price.","B answers with a price, so A asks how much with いくら.","いくつ asks how many or how old. B answers with a price.","何時 asks what time it is. B answers with a price."],"explain":null},{"id":"n5u02d5.d2","kind":"choice","type":"文の文法1","label":"Choose the word","q":"A「いすは（　　）ありますか。」B「^[四|よっ]つ^あります。」","options":["いくつ","[何|なに]","だれ","いくら"],"answer":1,"why":["B counts the chairs with 四つ, so A asks how many with いくつ.","何 asks what. It cannot ask how many, and B gives a number.","だれ asks who. Chairs are not people, and B gives a number.","いくら asks about money. B counts the chairs."],"explain":null},{"id":"n5u02d5.d3","kind":"choice","type":"文の文法1","label":"Choose the word","q":"この[本|ほん]は^[千円|せんえん]^（　　）でした。","options":["ぐらい","いくつ","ごろ","いくら"],"answer":1,"why":["千円 is an amount of money, so \"about\" is ぐらい.","いくつ asks how many. This sentence does not ask anything.","ごろ is for a point in time, like a clock time. 千円 is an amount of money.","いくら asks a question. This sentence tells a price; it does not ask one."],"explain":null},{"id":"n5u02d5.d4","kind":"choice","type":"文の文法1","label":"Choose the word","q":"まいあさ^[七時|しちじ]^（　　）おきます。","options":["いくつ","や","ごろ","など"],"answer":3,"why":["いくつ asks how many. This sentence tells a time; it does not ask.","や joins two nouns in a list. Nothing follows it here.","七時 is a clock time, so \"around seven\" is 七時ごろ.","など ends a list of things, as in パンやたまごなど. It does not follow a clock time here."],"explain":null},{"id":"n5u02d5.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「ここから[駅|えき]まで[何分|なんぷん]ぐらいかかりますか。」B「そうですね、","after":"。」","tiles":["[二十分|にじゅっぷん]","ぐらい","かかります","よ"],"star":1,"bank":[2,0,3,1],"hint":"A asks about a length of time. ぐらい comes right after the number, and よ comes last.","full":"A「ここから[駅|えき]まで[何分|なんぷん]ぐらいかかりますか。」B「そうですね、[二十分|にじゅっぷん]{ぐらい}かかりますよ。」","explain":"二十分 is a length of time, so ぐらい goes right after it. かかります follows, and よ ends the sentence because B tells A something new."},{"id":"n5u02d5.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「","after":"。」B「[五|いつ]つあります。」","tiles":["その","りんごは","いくつ","ありますか"],"star":2,"bank":[3,2,0,1],"hint":"B answers with a number of apples. その goes before a noun, and the question word comes before ありますか.","full":"A「そのりんごは{いくつ}ありますか。」B「[五|いつ]つあります。」","explain":"その goes right before りんごは, the topic. B counts with 五つ, so A asks いくつ, and ありますか ends the question."}],"exam":[{"id":"n5u02d5.e1","kind":"choice","type":"文の文法1","label":"Choose the word","q":"A「この　ノートは　（　　）ですか。」B「二百円です。」","options":["いくら","だれ","いくつ","何時"],"answer":1,"explain":"B answers with a price, so A asks how much with いくら. いくつ asks how many or how old, 何時 asks the time, and だれ asks who."},{"id":"n5u02d5.e2","kind":"choice","type":"文の文法1","label":"Choose the word","q":"きのうは　八時間（　　）　ねました。","options":["ぐらい","いくら","いくつ","ごろ"],"answer":1,"explain":"八時間 is a length of time, so \"about eight hours\" is ぐらい. ごろ is only for a point in time, like 八時. いくら and いくつ ask questions, and this sentence does not ask."},{"id":"n5u02d5.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「あした　何時ごろ　来ますか。」B「","after":"よ。」","tiles":["九時","ごろ","に","行きます"],"star":1,"bank":[3,1,0,2],"full":"A「あした　何時ごろ　来ますか。」B「九時{ごろ}に　行きますよ。」","explain":"九時, ごろ, に, 行きます. ごろ comes right after the clock time, に follows ごろ, and 行きます goes before よ."}]},"scene":{"ja":"カフェで","en":"At a café","intro":"Tap every word on the menu you would read to order and pay.","words":[{"id":"water","word":"水","reading":"みず","gloss":"water","parts":[["水","みず","water"]],"clip":"s_n5u2d5_water"},{"id":"fish","word":"魚","reading":"さかな","gloss":"fish","parts":[["魚","さかな","fish"]],"clip":"s_n5u2d5_fish"},{"id":"one","word":"一つ","reading":"ひとつ","gloss":"one (thing)","parts":[["一","ひと","one"]],"clip":"s_n5u2d5_one"},{"id":"two","word":"二つ","reading":"ふたつ","gloss":"two (things)","parts":[["二","ふた","two"]],"clip":"s_n5u2d5_two"},{"id":"y300","word":"三百円","reading":"さんびゃくえん","gloss":"300 yen","parts":[["三","サン","three"],["百","ビャク","hundred"],["円","エン","yen"]],"clip":"s_n5u2d5_y300"},{"id":"y600","word":"六百円","reading":"ろっぴゃくえん","gloss":"600 yen","parts":[["六","ロッ","six"],["百","ピャク","hundred"],["円","エン","yen"]],"clip":"s_n5u2d5_y600"},{"id":"y1000","word":"千円","reading":"せんえん","gloss":"1,000 yen","parts":[["千","セン","thousand"],["円","エン","yen"]],"clip":"s_n5u2d5_y1000"},{"id":"pm","word":"午後","reading":"ごご","gloss":"afternoon, p.m.","parts":[["午","ゴ","noon"],["後","ゴ","after"]],"clip":"s_n5u2d5_pm"}],"check":{"id":"n5u02d5.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"この　ケーキは　_六百円_です。","options":["ろくびゃくえん","ろっぴゃくえん","ろくひゃくえん","ろっびゃくえん"],"answer":2,"explain":"六 and 百 join as ろっぴゃく, with a small っ and ぴゃ, as in はっぴゃく (八百). The other three spellings are not words. Compare さんびゃく (三百), which takes びゃく."}},"skill":{"kind":"listening","ja":"即時応答","en":"Quick response","ask":"えなどが　ありません。ぶんを　聞いて、1から3の　中から、いちばん　いい　ものを　一つ　えらんで　ください。","item":{"id":"n5u02d5.r1","kind":"choice","type":"即時応答","q":"男：すみません、この　りんごは　一つ　いくらですか。","script":["男：すみません、このりんごは一ついくらですか。","ナレーター：1","女：はい、一つです。","ナレーター：2","女：百二十円です。","ナレーター：3","女：三つあります。"],"options":["はい、一つです。","百二十円です。","三つあります。"],"printed":false,"short":["はい、一つです","百二十円です","三つあります"],"answer":2,"why":["The man asks a price with いくら, not a yes-or-no question. 一つ in his question only means \"for one\".","He asks how much one apple is, and she gives the price.","三つあります says how many there are. That answers いくつ, not いくら."],"clip":"l_n5u2d5"},"audio":[["M","すみません、このりんごは一ついくらですか。","すみません、このりんごはひとついくらですか。"],["N","1",null],["F","はい、一つです。","はい、ひとつです。"],["N","2",null],["F","百二十円です。","ひゃくにじゅうえんです。"],["N","3",null],["F","三つあります。","みっつあります。"]]}},{"title":"まとめ：似ている文法","grammar":{"points":[],"compare":{"intro":"To tell this unit's points apart, ask what the blank is about: a thing or a person or animal (あります or います), a new thing or one already named (〜に〜があります or 〜は〜にあります), a place or a thing (ここ or これ), a price or a number of things (いくら or いくつ), and about what time or about how long (ごろ or ぐらい).","forms":[{"form":"あります／います","tag":"もの・ひとやどうぶつ · thing or living thing","mark":"dot","ja":"[外|そと]に[木|き]{があります}。[木|き]の[下|した]に[子|こ]ども{がいます}。","en":"There is a tree outside. There is a child under the tree."},{"form":"〜に〜があります／〜は〜にあります","tag":"あたらしい・しっている · new thing or known thing","mark":"dot","ja":"[五|ご]かい{に}レストラン{が}あります。レストラン{は}[五|ご]かい{に}あります。","en":"There is a restaurant on the fifth floor. The restaurant is on the fifth floor."},{"form":"〜ごろ／〜ぐらい","tag":"なんじ・どのぐらい · what time or how long","mark":"dot","ja":"[九時|くじ]{ごろ}ホテルを[出|で]ます。[駅|えき]まで[五分|ごふん]{ぐらい}です。","en":"I leave the hotel around nine. It is about five minutes to the station."}],"check":{"id":"n5u02d6.c1","kind":"choice","type":"文の文法1","label":"ホテルで","q":"ロビーに^[山川|やまかわ]さん^が（　　）よ。","options":["です","あります","います"],"answer":3,"why":["ロビーに already says where, so the sentence needs a verb for being there. 山川さんがですよ is not Japanese.","あります is for things. 山川さん is a person.","山川さん is a person, so います: \"Mr. Yamakawa is in the lobby.\""],"explain":null}},"drill":[{"id":"n5u02d6.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^[電話|でんわ]^は[一|いっ]かいの[入口|いりぐち]の[右|みぎ]に（　　）。","options":["あります","います","です","など"],"answer":1,"why":["A phone is a thing, and 電話は〜にあります says where the phone is.","います is for people and animals. A phone is a thing.","右に needs a verb after it. With です you would say 右です, without に.","など comes after a list of things, as in 本やノートなど. It cannot take the place of the verb."]},{"id":"n5u02d6.d2","kind":"choice","type":"文の文法1","label":"Choose the question word","q":"A：このホテルには、へやが（　　）ありますか。B：^[百|ひゃく]ぐらい^あります。","options":["[何時|なんじ]ごろ","どこに","いくら","いくつ"],"answer":4,"why":["何時ごろ asks about what time. 百ぐらい is not a time.","どこに asks where. B answers how many, not where.","いくら asks a price. B answers with a number of rooms.","B says about a hundred, so A asked how many: いくつ."],"explain":null},{"id":"n5u02d6.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：リンさんはどこにいますか。B：（　　）にいますよ。^あのまどの[前|まえ]^です。","options":["あそこ","あの","あれ","こちら"],"answer":1,"why":["Lin is by a window far from both people (あの), so B points at that place: あそこ.","あの needs a noun right after it, as in あのまど. It cannot come before に.","あれ points at a thing, not a place. You cannot be \"in\" あれ here.","こちら points to the speaker's side, but B says あのまど, a window far from both people."],"explain":null},{"id":"n5u02d6.d4","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"ホテルのへやの[中|なか]（　　）テレビやれいぞうこが^あります^。","options":["で","に","を","が"],"answer":2,"why":["で marks the place where you do something. あります says where a thing is, so it takes に.","With あります, the place where things are takes に: へやの中に.","を marks the thing an action is done to. あります is not that kind of verb.","が already comes after テレビやれいぞうこ. へやの中 is the place, not the thing that is there."]},{"id":"n5u02d6.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A：[山川|やまかわ]さんはどこにいますか。B：","after":"よ。","tiles":["あの","[車|くるま]の","[中|なか]に","います"],"star":1,"bank":[2,0,3,1],"hint":"Which car? Then where in the car? A person comes last with います.","full":"A：[山川|やまかわ]さんはどこにいますか。B：あの{[車|くるま]の}[中|なか]にいますよ。","explain":"あの車 is that car over there. 車の中に is inside the car. 山川さん is a person, so います comes last: he is in that car."},{"id":"n5u02d6.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[一|いっ]かいの","after":"があります。","tiles":["[店|みせ]","の[中|なか]に","パンや","[水|みず]など"],"star":2,"bank":[3,1,0,2],"hint":"First say the place, then list what is there.","full":"[一|いっ]かいの[店|みせ]{の[中|なか]に}パン{や}[水|みず]{など}があります。","explain":"一かいの店 is the shop on the first floor, and の中に says inside it. Then the list: パンや comes first and 水など closes it, right before があります."}],"exam":[{"id":"n5u02d6.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ホテルの　ロビーに　だれ（　　）　いますか。","options":["を","で","が","は"],"answer":3,"explain":"ロビーに　だれが　いますか asks who is in the lobby: the person who is there takes が. だれ is a question word, and a question word does not take は. を marks the thing an action is done to, and います has none. で marks where you do something; here the place already has に."},{"id":"n5u02d6.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「ホテルから　駅まで　どのぐらい　かかりますか。」\nB「十五分（　　）です。」","options":["ぐらい","いくら","など","ごろ"],"answer":1,"explain":"A asks how long it takes, so B gives about how long: 十五分ぐらい. ごろ goes with a point in time, like 九時ごろ, not with how long something takes. いくら asks a price. など comes after a list of things."},{"id":"n5u02d6.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「トイレは　どこに　ありますか。」B「","after":"ありますよ。」","tiles":["あそこの","エレベーターの","右","に"],"star":2,"bank":[3,1,0,2],"full":"A「トイレは　どこに　ありますか。」B「あそこの　エレベーターの　{右}に　ありますよ。」","explain":"あそこの, エレベーターの, 右, に. あそこの points at the elevator over there, エレベーターの右 is to the right of it, and に comes after the position word, right before あります."}]},"scene":{"ja":"ビルのあんないばん","en":"The floor guide in an office building","intro":"Tap each word on the floor guide by the elevator.","words":[{"id":"1st floor","word":"一かい","reading":"いっかい","gloss":"first floor (street level)","parts":[["一","イッ","one"]],"clip":"s_n5u2d6_1st_floor"},{"id":"5th floor","word":"五かい","reading":"ごかい","gloss":"fifth floor","parts":[["五","ゴ","five"]],"clip":"s_n5u2d6_5th_floor"},{"id":"phone","word":"電話","reading":"でんわ","gloss":"telephone","parts":[["電","デン","electricity"],["話","ワ","talk"]],"clip":"s_n5u2d6_phone"},{"id":"men","word":"男","reading":"おとこ","gloss":"men (on a toilet door)","parts":[["男","おとこ","man"]],"clip":"s_n5u2d6_men"},{"id":"women","word":"女","reading":"おんな","gloss":"women (on a toilet door)","parts":[["女","おんな","woman"]],"clip":"s_n5u2d6_women"},{"id":"company","word":"会社","reading":"かいしゃ","gloss":"company, office","parts":[["会","カイ","meet"],["社","シャ","company"]],"clip":"s_n5u2d6_company"},{"id":"east exit","word":"東口","reading":"ひがしぐち","gloss":"east entrance or exit","parts":[["東","ひがし","east"],["口","ぐち","mouth, opening"]],"clip":"s_n5u2d6_east_exit"},{"id":"west exit","word":"西口","reading":"にしぐち","gloss":"west entrance or exit","parts":[["西","にし","west"],["口","ぐち","mouth, opening"]],"clip":"s_n5u2d6_west_exit"}],"check":{"id":"n5u02d6.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"ビルの　_西口_の　前に　電話が　あります。","options":["にしくち","せいぐち","ひがしぐち","にしぐち"],"answer":4,"explain":"西口 is にしぐち: 西 (にし, west) and 口, which becomes ぐち after にし. ひがしぐち is 東口, the east side. にしくち misses the change from く to ぐ, and せいぐち is not a word."}},"skill":{"kind":"reading","ja":"情報検索","en":"Finding information","ask":"Which floor of the building do you need?","seconds":90,"passage":"さくらビル\n五かい　山川会社\n四かい　^日本語学校^\n三かい　レストラン（午前十一時から　午後十時まで）\n二かい　^本や^、カメラの　店\n一かい　きっさてん、電話\n※　トイレは　二かいと　四かいに　あります。","strategy":"Look for the shop that sells books, 本や, and do not stop at the first line with 日本語.","item":{"id":"n5u02d6.r1","kind":"choice","type":"読解・情報検索","q":"リーさんは　日本語の　本を　買いたいです。何かいへ　行きますか。","options":["一かい","二かい","四かい","五かい"],"short":["1かい","2かい","4かい","5かい"],"answer":2,"explain":"Books are sold at a 本や, and the guide puts the 本や on the second floor. The fourth floor has 日本語 in its name, but it is a school, not a shop.","why":["The first floor has a café and a phone, not books.","","四かい is a Japanese school. It has 日本語 in its name, but it does not sell books.","The fifth floor is a company office."]}}}],"test":[{"id":"n5u02t.1","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"ぎんこうは　駅の　_左_に　あります。","options":["ひがし","にし","みぎ","ひだり"],"answer":4,"explain":"左 is ひだり, left. みぎ is 右 (right), which looks like 左 but has 口 at the bottom. ひがし is 東 (east) and にし is 西 (west)."},{"id":"n5u02t.2","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"つくえの　上に　りんごが　_三つ_　あります。","options":["さっつ","みつ","さんつ","みっつ"],"answer":4,"explain":"三つ is みっつ, with a small っ. みつ leaves out the small っ, and さんつ and さっつ use さん, the reading of 三 in words like 三百 or 三人. None of them is a word for three things."},{"id":"n5u02t.3","kind":"choice","type":"表記","label":"Kanji spelling","q":"こうえんの　_いりぐち_に　大きい　木が　あります。","options":["人日","人口","入日","入口"],"answer":4,"explain":"いりぐち is 入口: 入 (go in) with 口 (opening). 人 looks like 入 but is ひと (person), so 人口 is another word (population), not いりぐち. 入日 and 人日 have 日 (day) in place of 口."},{"id":"n5u02t.4","kind":"choice","type":"表記","label":"Kanji spelling","q":"_みず_は　れいぞうこの　中に　あります。","options":["木","小","少","水"],"answer":4,"explain":"みず is 水 (water). 木 is き (tree), 小 is the 小 of 小さい (small), and 少 is the 少 of 少し (a little). They look a little like 水 but none of them is read みず."},{"id":"n5u02t.5","kind":"choice","type":"文脈規定","label":"Word in context","q":"本やは　この　ビルの　三（　　）に　あります。","options":["かい","まい","にん","つ"],"answer":1,"explain":"A shop in a building is on a floor, and floors are counted with かい: 三かい. 三つ counts things, 三まい counts flat things such as paper, and 三にん counts people. Only かい says where in the building."},{"id":"n5u02t.6","kind":"choice","type":"文脈規定","label":"Word in context","q":"ここは　（　　）です。本が　たくさん　あります。","options":["ぎんこう","しょくどう","びょういん","としょかん"],"answer":4,"explain":"A place with a lot of books is a library, としょかん. A bank (ぎんこう) has money, a cafeteria (しょくどう) has food, and a hospital (びょういん) has doctors; none of them is known for having many books."},{"id":"n5u02t.7","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"_ぎんこうは　ゆうびんきょくの　右に　あります_。","options":["ゆうびんきょくは　ぎんこうの　左に　あります。","ぎんこうは　ゆうびんきょくの　左に　あります。","ゆうびんきょくは　ぎんこうの　前に　あります。","ゆうびんきょくは　ぎんこうの　右に　あります。"],"answer":1,"explain":"If the bank is on the right of the post office, the post office is on the left of the bank. Option 4 puts the post office on the right, option 2 moves the bank to the left, and option 3 puts the post office in front, not beside it."},{"id":"n5u02t.8","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"ここは　_お手あらい_です。","options":["ここは　げんかんです。","ここは　おふろです。","ここは　トイレです。","ここは　だいどころです。"],"answer":3,"explain":"お手あらい and トイレ are two words for the same room, the toilet. だいどころ is the kitchen, げんかん is the entrance of a house where you take off your shoes, and おふろ is the bath."},{"id":"n5u02t.9","kind":"choice","type":"文の文法1","label":"Choose the word","q":"A「すみません。この　ちかくに　ぎんこうは　ありますか。」B「ええ、（　　）に　ありますよ。あの　たかい　たてものです。」","options":["ここ","あそこ","あれ","どこ"],"answer":2,"explain":"B points to a tall building over there (あの), so the bank is あそこ, a place far from both people. ここ would mean the place where they are standing, which does not fit あの. あれ is a thing, not a place, so あれにあります does not say where. どこ asks a question, but B is answering one."},{"id":"n5u02t.10","kind":"choice","type":"文の文法1","label":"Choose the word","q":"（パーティーで）A「中山さん、（　　）は　わたしの　クラスの　キムさんです。」B「はじめまして。中山です。」","options":["ここ","こちら","どちら","この"],"answer":2,"explain":"When you introduce someone who is with you, you say こちらは, the polite \"this person\". この must have a noun right after it, so この cannot stand before は. ここ is a place, and a place cannot be キムさん. どちら is a question word, and A is not asking anything."},{"id":"n5u02t.11","kind":"choice","type":"文の文法1","label":"Choose the form","q":"へやに　テレビは　ありますが、つくえは　（　　）。","options":["ありません","います","あります","いません"],"answer":1,"explain":"が here means \"but\", so the second half says the opposite of the first: there is a TV but no desk. A desk is a thing, so it takes ありません. あります would not be the opposite of the first half, and います and いません are for people and animals, not for a desk."},{"id":"n5u02t.12","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"A「ジョンさんは　どこですか。」B「ジョンさんは　いま　としょかん（　　）　います。」","options":["へ","に","で","を"],"answer":2,"explain":"To say where someone is, the place takes に before います: としょかんにいます. で marks the place where you do an action (としょかんでべんきょうします), but います only says where he is. を and へ do not mark the place where someone is."},{"id":"n5u02t.13","kind":"choice","type":"文の文法1","label":"Choose the word","q":"つくえの　上に　ノートや　じしょ（　　）が　あります。","options":["ぐらい","ごろ","など","の"],"answer":3,"explain":"や lists a few examples, and など after the last one means \"and other things like that\": ノートやじしょなど. じしょのが あります does not make sense here. ぐらい is for an amount such as a number or a time span, and ごろ is for a point in time; じしょ is neither."},{"id":"n5u02t.14","kind":"choice","type":"文の文法1","label":"Choose the word","q":"A「おとうとさんは　（　　）ですか。」B「八つです。」","options":["いくつ","いつ","どれ","いくら"],"answer":1,"explain":"B answers 八つです, eight years old, so A asks a child's age with いくつ. いくら asks a price, and a person has no price. いつ asks when, and 八つ is not a time. どれ asks which one, and 八つです does not pick one out."},{"id":"n5u02t.15","kind":"choice","type":"文の文法1","label":"Choose the word","q":"きょうしつに　学生が　二十人（　　）　います。","options":["いくら","ぐらい","いくつ","ごろ"],"answer":2,"explain":"二十人 is a number of people, and ぐらい after an amount means \"about\": about twenty students. ごろ means \"around\" only with a point in time, such as 三時ごろ, not with a number of people. いくら and いくつ are question words, and this sentence is not a question."},{"id":"n5u02t.16","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「あ、あの　木の　","after":"が　いますよ。」B「ええ、かわいいですね。」","tiles":["下","に","白い","ねこ"],"star":2,"bank":[3,0,2,1],"full":"A「あ、あの　木の　下に　{白い}　ねこが　いますよ。」B「ええ、かわいいですね。」","explain":"下, に, 白い, ねこ. 木の needs a position word after it, so 下 comes first: 木の下 (under the tree). に marks that place. 白い describes ねこ, so it comes right before it, and ねこ goes before が います, because a cat is alive and takes います."},{"id":"n5u02t.17","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「わたしの　さいふは　どこですか。」B「かばんの　","after":"ありますよ。」","tiles":["中","の","小さい","はこに"],"star":1,"bank":[2,0,3,1],"full":"A「わたしの　さいふは　どこですか。」B「かばんの　中{の}　小さい　はこに　ありますよ。」","explain":"中, の, 小さい, はこに. かばんの中 is the inside of the bag. の joins it to the box: the small box in the bag. 小さい describes はこ, so it comes right before it, and はこに, with に for the place, goes before あります."},{"id":"n5u02t.18","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「あしたは　何時から　うちに　いますか。」B「","after":"いますよ。」","tiles":["午後","五時","ごろ","から"],"star":2,"bank":[1,3,0,2],"full":"A「あしたは　何時から　うちに　いますか。」B「午後　五時{ごろ}から　いますよ。」","explain":"午後, 五時, ごろ, から. 午後 (p.m.) comes before the hour, as in 午後五時. ごろ (around) goes right after the time, and から (from) comes last, answering A's 何時から."},{"id":"n5u02t.19","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ジョンさん\nわたしの　あたらしい　へやは　二かいです。へやには　ベッドと　つくえが　あります。テレビは　ありません。つくえの　上に　とけいが　あります。まどの　外に　高い　木が　あります。木の　上には　ときどき　白い　とりが　います。\nゆき","q":"ゆきさんの　へやに　ない　ものは　どれですか。","options":["ベッド","つくえ","テレビ","とけい"],"answer":3,"short":["ベッド","つくえ","テレビ","とけい"],"explain":"ゆき writes テレビはありません: there is no TV. The room has a bed and a desk (ベッドとつくえがあります), and the clock is on the desk (つくえの上にとけいがあります)."},{"id":"n5u02t.20","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ジョンさん\nわたしの　あたらしい　へやは　二かいです。へやには　ベッドと　つくえが　あります。テレビは　ありません。つくえの　上に　とけいが　あります。まどの　外に　高い　木が　あります。木の　上には　ときどき　白い　とりが　います。\nゆき","q":"ただしい　ものは　どれですか。","options":["白い　とりは　ときどき　木の　上に　います。","ゆきさんの　へやは　一かいに　あります。","とけいは　つくえの　下に　あります。","高い　木は　へやの　中に　あります。"],"answer":1,"short":["とりは木の上","へやは一かい","とけいはつくえの下","木はへやの中"],"explain":"ゆき writes 木の上にはときどき白いとりがいます: sometimes a white bird is in the tree. The room is on 二かい, not 一かい. The clock is on the desk (上), not under it (下). The tall tree is outside the window (まどの外), not in the room."},{"id":"n5u02t.21","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"パンの　店「やまの　パン」\nメロンパン　一つ　百五十円\nカレーパン　一つ　二百円\nサンドイッチ　一つ　三百五十円\n午後　五時から　パンと　サンドイッチは　ぜんぶ　一つ　百円です。\n店の　前に　テーブルと　いすが　あります。どうぞ。","q":"リンさんは　午後　二時に　この　店で　カレーパンを　二つ　買います。いくらですか。","options":["百円","二百円","四百円","七百円"],"answer":3,"short":["百円","二百円","四百円","七百円"],"explain":"At two in the afternoon the 五時から price does not apply yet, so a カレーパン is 二百円 each, and two are 四百円. 百円 is the after-five price of one. 二百円 is one at the normal price, or two after five. 七百円 is two sandwiches."},{"id":"n5u02t.22","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"パンの　店「やまの　パン」\nメロンパン　一つ　百五十円\nカレーパン　一つ　二百円\nサンドイッチ　一つ　三百五十円\n午後　五時から　パンと　サンドイッチは　ぜんぶ　一つ　百円です。\n店の　前に　テーブルと　いすが　あります。どうぞ。","q":"キムさんは　午後　六時に　この　店で　メロンパンを　一つと　サンドイッチを　一つ　買います。いくらですか。","options":["二百円","二百五十円","四百円","五百円"],"answer":1,"short":["二百円","二百五十円","四百円","五百円"],"explain":"Six p.m. is after five, and from five everything is 百円 each, so two things are 二百円. 五百円 is the normal price (百五十円 and 三百五十円). 二百五十円 takes the normal price for the メロンパン only, and 四百円 is the price of two カレーパン before five."},{"id":"n5u02t.23","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"マイクさん\nあした　いっしょに　えいがを　見ませんか。えいがは　午後　二時からです。えいがかんは　駅から　あるいて　十分ぐらいです。わたしは　一時半ごろ　駅の　東口の　前に　います。東口の　前には　大きい　花やが　あります。\nゆか","q":"ゆかさんは　あした　何時ごろ　どこに　いますか。","options":["一時半ごろ　えいがかんの　前","一時半ごろ　駅の　東口の　前","二時ごろ　駅の　東口の　前","二時ごろ　えいがかんの　前"],"answer":2,"short":["一時半 えいがかん","一時半 東口","二時 東口","二時 えいがかん"],"explain":"ゆか writes 一時半ごろ駅の東口の前にいます. 二時 is when the film starts, not when she waits. She waits at the station's east exit, not in front of the cinema, which is ten minutes away."},{"id":"n5u02t.24","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"マイクさん\nあした　いっしょに　えいがを　見ませんか。えいがは　午後　二時からです。えいがかんは　駅から　あるいて　十分ぐらいです。わたしは　一時半ごろ　駅の　東口の　前に　います。東口の　前には　大きい　花やが　あります。\nゆか","q":"ただしい　ものは　どれですか。","options":["花やは　駅の　西口の　前に　あります。","えいがは　一時半からです。","えいがかんは　駅の　中に　あります。","駅から　えいがかんまで　十分ぐらいです。"],"answer":4,"short":["花やは西口","えいがは一時半から","えいがかんは駅の中","駅から十分ぐらい"],"explain":"ゆか writes えいがかんは駅からあるいて十分ぐらいです. The film starts at 二時; 一時半 is when she will be at the station. The cinema is a ten-minute walk away, so it is not inside the station. The flower shop is in front of the east exit (東口), not the west exit."}]},{"n":3,"ja":"動詞（ます形）","en":"Verbs: polite forms","days":[{"title":"〜ます・〜ません","grammar":{"points":[{"id":"n5u03d1.p1","form":"〜ます","gloss":"do, will do (polite)","connect":[{"pos":"A habit: a word like \"every day\", then the verb","rule":"[毎日|まいにち] ＋ [行|い]き{ます}"},{"pos":"A plan: a word like \"tomorrow\", then the verb","rule":"あした ＋ [来|き]{ます}"},{"pos":"Noun (the thing you eat, see, buy…), を, then the verb","rule":"〜 ＋ を ＋ [食|た]べ{ます}"}],"examples":[{"ja":"[毎日|まいにち][七時|しちじ]におき{ます}。","en":"I get up at seven every day.","clip":"x_n5u03d1_p1_1"},{"ja":"あした[友|とも]だちと[山|やま]へ[行|い]き{ます}。","en":"Tomorrow I will go to the mountains with a friend.","clip":"x_n5u03d1_p1_2"}],"watch":{"note":"ます joins the ます stem of the verb, not the dictionary form. 飲む becomes 飲みます, and 行く becomes 行きます.","bad":"毎日コーヒーを飲むます。","good":"毎日コーヒーを飲みます。"}},{"id":"n5u03d1.p2","form":"〜ません","gloss":"do not, will not (polite)","connect":[{"pos":"Verb, polite form: change ます to ません","rule":"[行|い]きます → [行|い]き{ません}"},{"pos":"Not much: あまり before the verb","rule":"あまり ＋ [見|み]{ません}"},{"pos":"Answering no to a question with 〜ますか","rule":"いいえ、[飲|の]み{ません}"}],"examples":[{"ja":"[日|にち]よう[日|び]は[学校|がっこう]へ[行|い]き{ません}。","en":"I don't go to school on Sundays.","clip":"x_n5u03d1_p2_1"},{"ja":"わたしはコーヒーを[飲|の]み{ません}。","en":"I don't drink coffee.","clip":"x_n5u03d1_p2_2"}],"watch":{"note":"じゃありません is the no ending for a noun, as in 学生じゃありません. A verb changes ます to ません.","bad":"あしたは学校へ行くじゃありません。","good":"あしたは学校へ行きません。"}}],"compare":{"intro":"Two endings for a verb, one for yes and one for no, and the no ending for a noun that you met in unit 1.","forms":[{"form":"〜ます","tag":"します · do, will do","mark":"dot","ja":"[毎日|まいにち]テレビを[見|み]{ます}。","en":"I watch TV every day."},{"form":"〜ません","tag":"しません · don't, won't","mark":"down","ja":"[父|ちち]はテレビを[見|み]{ません}。","en":"My father doesn't watch TV."},{"form":"〜じゃありません","tag":"じゃない · is not (after a noun)","mark":"down","ja":"あれはテレビ{じゃありません}。","en":"That is not a TV."}],"check":{"id":"n5u03d1.c1","kind":"choice","type":"文の文法1","label":"あさごはんのはなし","q":"A「あさごはんを[食|た]べますか。」\nB「^いいえ^、（　　）。」","options":["[食|た]べます","[食|た]べません","[食|た]べるじゃありません"],"answer":2,"why":["食べます means yes, I eat it. B starts with いいえ, so B needs the no ending.","B says いいえ, so the verb takes the no ending: 食べます becomes 食べません.","じゃありません comes after a noun. 食べる is a verb, so its no ending is 食べません."]}},"drill":[{"id":"n5u03d1.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「[毎日|まいにち]コーヒーを[飲|の]みますか。」\nB「^はい^、[毎日|まいにち]（　　）。」","options":["[飲|の]みません","[飲|の]みます","[飲|の]みですか","[飲|の]むます"],"answer":2,"why":["飲みません means I don't drink it. B starts with はい, so B drinks it.","B says はい, so B repeats the yes form: 飲みます, I drink it every day.","です does not come right after a verb stem, and B is answering, not asking.","ます joins the ます stem 飲み, not the dictionary form 飲む."],"explain":null},{"id":"n5u03d1.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あした[友|とも]だちと^テニスを^（　　）。","options":["するます","あります","します","きます"],"answer":3,"why":["する changes completely: its polite form is します, not するます.","あります says that a thing is there. It does not take テニスを.","You play tennis with する, and the polite form of する is します. With あした it is a plan.","きます is the polite form of 来る, come. You cannot come tennis."],"explain":null},{"id":"n5u03d1.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「[日|にち]よう[日|び]も[学校|がっこう]へ[行|い]きますか。」\nB「^いいえ^、[日|にち]よう[日|び]は（　　）。」","options":["[行|い]きませんか","[行|い]きます","[行|い]くじゃありません","[行|い]きません"],"answer":4,"why":["行きませんか invites someone: won't you go? B is answering A's question, not inviting.","行きます means yes, I go. B starts with いいえ.","じゃありません comes after a noun. 行く is a verb, so its no ending is 行きません.","B says いいえ, so the verb takes the no ending: 行きます becomes 行きません."],"explain":null},{"id":"n5u03d1.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしはテレビを^あまり^（　　）。","options":["[見|み]ます","[見|み]ません","[見|み]るません","[見|み]じゃありません"],"answer":2,"why":["あまり in the sense \"not much\" goes with a no ending. 見ます is the yes form.","あまり with the no ending says \"not much\": I don't watch TV much.","ません joins the ます stem 見, not the dictionary form 見る.","じゃありません comes after a noun. 見る is a verb, so its no ending is 見ません."]},{"id":"n5u03d1.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしは[毎日|まいにち]あさ","after":"。","tiles":["[七時|しちじ]","に","おき","ます"],"star":2,"bank":[3,1,0,2],"hint":"The time comes first, with に right after it. Then the verb, with ます at the end.","full":"わたしは[毎日|まいにち]あさ[七時|しちじ]におき{ます}。","explain":"に marks the time, so it comes right after 七時. おき is the ます stem of おきる, and ます joins it at the end of the sentence."},{"id":"n5u03d1.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「[土|ど]よう[日|び]も[会社|かいしゃ]へ[行|い]きますか。」\nB「いいえ、[土|ど]よう[日|び]は","after":"。」","tiles":["[会社|かいしゃ]","へ","[行|い]き","ません"],"star":3,"bank":[2,3,0,1],"hint":"Say where first, with へ. The verb comes last, with the no ending.","full":"A「[土|ど]よう[日|び]も[会社|かいしゃ]へ[行|い]きますか。」\nB「いいえ、[土|ど]よう[日|び]は[会社|かいしゃ]へ[行|い]き{ません}。」","explain":"へ shows where you go, so it comes right after 会社. B says いいえ, so 行き takes the no ending ません."}],"exam":[{"id":"n5u03d1.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「中山さんは　毎日　何時に　うちを　出ますか。」\nB「七時に　（　　）。」","options":["出ますか","出ません","出るます","出ます"],"answer":4,"explain":"A asks what time B leaves home every day, and B answers with the time: 七時に出ます. 出ません says B does not leave at seven, which does not answer the question. 出るます is not a form: ます joins 出, the ます stem. 出ますか would be a question, but B is answering."},{"id":"n5u03d1.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「よく　本を　読みますか。」\nB「いいえ、あまり　（　　）。」","options":["読みます","読むません","読みましょう","読みません"],"answer":4,"explain":"B says いいえ, and あまり in the sense \"not much\" goes with a no ending: あまり読みません, I don't read much. 読みます is the yes form. 読むません is not a form: ません joins 読み. 読みましょう means let's read, which does not answer A."},{"id":"n5u03d1.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"先生は　あした　","after":"。","tiles":["午前","十時","に","来ます"],"star":1,"bank":[3,0,2,1],"full":"先生は　あした　午前十時に{来ます}。","explain":"午前, 十時, に, 来ます. 午前 comes before the hour, as in 午前十時, ten in the morning. に marks the time, so it follows 十時. The verb 来ます ends the sentence: the teacher will come tomorrow."}]},"scene":{"ja":"れいぞうこの一週間のよてい","en":"A weekly schedule on the fridge","intro":"Tap each word on the family's schedule stuck to the fridge door.","words":[{"id":"every-day","word":"毎日","reading":"まいにち","gloss":"every day","parts":[["毎","マイ","every"],["日","ニチ","day"]],"clip":"s_n5u3d1_every_day"},{"id":"morning","word":"午前","reading":"ごぜん","gloss":"morning (before noon), a.m.","parts":[["午","ゴ","noon"],["前","ゼン","before"]],"clip":"s_n5u3d1_morning"},{"id":"afternoon","word":"午後","reading":"ごご","gloss":"afternoon, p.m.","parts":[["午","ゴ","noon"],["後","ゴ","after"]],"clip":"s_n5u3d1_afternoon"},{"id":"day-off","word":"休み","reading":"やすみ","gloss":"day off, holiday","parts":[["休","やす","rest"]],"clip":"s_n5u3d1_day_off"},{"id":"saturday","word":"土よう日","reading":"どようび","gloss":"Saturday","parts":[["土","ド","earth, soil"],["日","び","day"]],"clip":"s_n5u3d1_saturday"},{"id":"next-week","word":"来週","reading":"らいしゅう","gloss":"next week","parts":[["来","ライ","come, next"],["週","シュウ","week"]],"clip":"s_n5u3d1_next_week"},{"id":"school","word":"学校","reading":"がっこう","gloss":"school","parts":[["学","ガッ","study"],["校","コウ","school"]],"clip":"s_n5u3d1_school"},{"id":"company","word":"会社","reading":"かいしゃ","gloss":"company, office","parts":[["会","カイ","meet"],["社","シャ","company"]],"clip":"s_n5u3d1_company"}],"check":{"id":"n5u03d1.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_来週_　友だちと　山へ　行きます。","options":["らいしゅ","きしゅう","らいしゅう","らいじゅう"],"answer":3,"explain":"来週 is らいしゅう: in this word 来 is read ライ and 週 is read シュウ. らいしゅ drops the long う, きしゅう uses き from 来ます, and らいじゅう adds a dakuten that is not there."}},"skill":{"kind":"listening","ja":"ポイント理解","en":"Point comprehension","ask":"女の人は　あしたの　午後　何を　しますか。","audio":[["N","男の人と女の人が話しています。女の人は、あしたの午後、何をしますか。","おとこのひとと　おんなのひとが　はなしています。おんなのひとは、あしたの　ごご、なにを　しますか。"],["M","中山さん、あしたは休みですね。何をしますか。","なかやまさん、あしたは　やすみですね。なにを　しますか。"],["F","午前は、うちでそうじをします。","ごぜんは、うちで　そうじを　します。"],["M","午後は、デパートへ行きますか。","ごごは、デパートへ　いきますか。"],["F","いいえ、行きません。友だちとえいがを見ます。","いいえ、いきません。ともだちと　えいがを　みます。"],["M","いいですね。わたしは、あしたも会社です。","いいですね。わたしは、あしたも　かいしゃです。"],["N","女の人は、あしたの午後、何をしますか。","おんなのひとは、あしたの　ごご、なにを　しますか。"]],"item":{"id":"n5u03d1.r1","kind":"choice","type":"ポイント理解","q":"女の人は　あしたの　午後　何を　しますか。","script":["ナレーター：男の人と女の人が話しています。女の人は、あしたの午後、何をしますか。","男：中山さん、あしたは休みですね。何をしますか。","女：午前は、うちでそうじをします。","男：午後は、デパートへ行きますか。","女：いいえ、行きません。友だちとえいがを見ます。","男：いいですね。わたしは、あしたも会社です。","ナレーター：女の人は、あしたの午後、何をしますか。"],"options":["うちで　そうじを　します","デパートへ　行きます","友だちと　えいがを　見ます","会社へ　行きます"],"printed":true,"short":["うちで そうじ","デパートへ 行く","友だちと えいが","会社へ 行く"],"answer":3,"why":["She cleans the house in the morning (午前), not in the afternoon.","The man asks if she goes to the department store, and she says いいえ、行きません.","In the afternoon she says 友だちとえいがを見ます: she will watch a film with a friend.","The man is the one who goes to work tomorrow (あしたも会社です). She has the day off."],"clip":"l_n5u3d1"}}},{"title":"〜ました・〜ませんでした","grammar":{"points":[{"id":"n5u03d2.p1","form":"〜ました","gloss":"did (polite past)","connect":[{"pos":"Verb, ます form","rule":"〜ます → 〜{ました}"},{"pos":"Question","rule":"〜{ましたか}"},{"pos":"Yes answer","rule":"はい、〜{ました}"}],"examples":[{"ja":"きのう、[友|とも]だちと[魚|さかな]を[食|た]べ{ました}。","en":"Yesterday I ate fish with a friend.","clip":"x_n5u03d2_p1_1"},{"ja":"[先週|せんしゅう]、[新|あたら]しい[本|ほん]を[買|か]い{ました}。","en":"I bought a new book last week.","clip":"x_n5u03d2_p1_2"}],"watch":{"note":"The past of ます is ました. Do not add でした to ます.","bad":"きのう、すしを食べますでした。","good":"きのう、すしを食べました。"}},{"id":"n5u03d2.p2","form":"〜ませんでした","gloss":"did not (polite past)","connect":[{"pos":"Verb, ます form","rule":"〜ます → 〜{ませんでした}"},{"pos":"No answer","rule":"いいえ、〜{ませんでした}"}],"examples":[{"ja":"きのうは[何|なに]も[食|た]べ{ませんでした}。","en":"I didn't eat anything yesterday.","clip":"x_n5u03d2_p2_1"},{"ja":"A：[先週|せんしゅう]、[学校|がっこう]へ[行|い]きましたか。B：いいえ、[行|い]き{ませんでした}。","en":"A: Did you go to school last week? B: No, I didn't.","clip":"x_n5u03d2_p2_2"}],"watch":{"note":"ません is for now, habits and the future. For something that did not happen in the past, add でした: 行きませんでした. 行かないでした is a common mistake too; it is not standard polite Japanese.","bad":"きのう、学校へ行きません。","good":"きのう、学校へ行きませんでした。"}}],"compare":{"intro":"All three are polite verb endings. What changes is the time, and whether it happened.","forms":[{"form":"〜ました","tag":"かこ · did","mark":"dot","ja":"きのう、[学校|がっこう]へ[行|い]き{ました}。","en":"I went to school yesterday."},{"form":"〜ませんでした","tag":"かこ・ない · didn't","mark":"down","ja":"きのう、[学校|がっこう]へ[行|い]き{ませんでした}。","en":"I didn't go to school yesterday."},{"form":"〜ません","tag":"いま・これから · don't, won't","mark":"down","ja":"あした、[学校|がっこう]へ[行|い]き{ません}。","en":"I won't go to school tomorrow."}],"check":{"id":"n5u03d2.c1","kind":"choice","type":"文の文法1","label":"きのうのこと","q":"A：きのう、[学校|がっこう]へ[行|い]きましたか。B：はい、（　　）。","options":["[行|い]きません","[行|い]きました","[行|い]きませんでした"],"answer":2,"why":["行きません is not past, and it means \"I don't go\". It clashes with はい too.","はい to a question about yesterday: the polite past, 行きました.","行きませんでした means \"I didn't go\". It clashes with はい."],"explain":null}},"drill":[{"id":"n5u03d2.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^きのう^、デパートで[花|はな]を[買|か]い（　　）。","options":["ません","ますでした","ます","ました"],"answer":4,"why":["ません is not past, and it means \"don't\". For yesterday you need a past form.","There is no ますでした. The past of ます is ました.","ます is for now, habits and the future. きのう points to the past.","きのう is the past, and the sentence says it happened: 買いました."],"explain":null},{"id":"n5u03d2.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：きのう、テレビを[見|み]ましたか。B：^いいえ^、（　　）。","options":["[見|み]ました","[見|み]ませんでした","[見|み]ません","[見|み]ないでした"],"answer":2,"why":["見ました means \"I watched\". It clashes with いいえ.","いいえ to a question about yesterday: the polite past no form, 見ませんでした.","見ません is not past. The question is about yesterday, so add でした.","見ないでした is a common mistake, not standard polite Japanese. Say 見ませんでした."]},{"id":"n5u03d2.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^[先週|せんしゅう]の[日|にち]よう[日|び]^は、^[何|なに]も^（　　）。","options":["しません","します","しました","しませんでした"],"answer":4,"why":["しません is a not form, but it is not past. 先週 needs でした after ません.","します is not past, and 何も needs a not form.","何も (nothing) goes with a not form. しました says you did something.","Last Sunday is past, and 何も needs a not form: しませんでした."],"explain":null},{"id":"n5u03d2.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：きのう、[何|なに]を[食|た]べ（　　）か。B：^カレーを[食|た]べました^。","options":["ません","ませんでした","ます","ました"],"answer":4,"why":["食べませんか is an invitation (won't you eat?), not a question about yesterday.","何を食べませんでしたか asks what you did not eat. B tells what she ate.","何を食べますか asks about now or later. きのう and B's answer are in the past.","B answers 食べました, so the question is in the past too: 食べましたか."],"explain":null},{"id":"n5u03d2.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"この[花|はな]は、[駅|えき]の","after":"。","tiles":["[前|まえ]の","[店|みせ]で","[買|か]い","ました"],"star":1,"bank":[2,0,3,1],"hint":"駅の needs a noun right after it. ました comes last, right after the verb.","full":"この[花|はな]は、[駅|えき]の[前|まえ]の[店|みせ]で[買|か]い{ました}。","explain":"駅の前の is \"in front of the station\" and it describes 店. 店で says where, then 買い and ました make the past verb."},{"id":"n5u03d2.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"きのうは、","after":"。うちにいました。","tiles":["どこ","へも","[行|い]き","ませんでした"],"star":3,"bank":[3,1,0,2],"hint":"どこへも means \"(not) anywhere\". Which ending is past and a not form?","full":"きのうは、どこへも[行|い]き{ませんでした}。うちにいました。","explain":"どこ and へも go together, then the verb. きのう is past and どこへも needs a not form, so 行きませんでした."}],"exam":[{"id":"n5u03d2.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きのう、スーパーで　たまごを（　　）。","options":["買いました","買いません","買いませんか","買います"],"answer":1,"explain":"きのう is the past, and the sentence says what was bought: 買いました. 買います and 買いません are not past, and 買いませんか is an invitation."},{"id":"n5u03d2.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：先週の　土よう日、山へ　行きましたか。B：いいえ、（　　）。うちに　いました。","options":["行きません","行きませんでした","行きました","行きます"],"answer":2,"explain":"いいえ to a question about last Saturday, and B stayed at home: 行きませんでした. 行きました clashes with いいえ, and 行きます and 行きません are not past."},{"id":"n5u03d2.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"先週の　日よう日、","after":"。","tiles":["友だちの","うち","へ","行きました"],"star":1,"bank":[3,1,0,2],"full":"先週の　日よう日、友だちの　{うち}へ　行きました。","explain":"友だちの, うち, へ, 行きました. 友だちの describes うち, へ marks where to, and the verb comes last."}]},"scene":{"ja":"スーパーのレシート","en":"A supermarket receipt","intro":"Tap every word you can find on the receipt.","words":[{"id":"branch","word":"駅前店","reading":"えきまえてん","gloss":"station-front branch","parts":[["駅","エキ","station"],["前","まえ","front"],["店","テン","shop"]],"clip":"s_n5u3d2_branch"},{"id":"pm","word":"午後","reading":"ごご","gloss":"p.m., afternoon","parts":[["午","ゴ","noon"],["後","ゴ","after"]],"clip":"s_n5u3d2_pm"},{"id":"water","word":"水","reading":"みず","gloss":"water","parts":[["水","みず","water"]],"clip":"s_n5u3d2_water"},{"id":"two","word":"二本","reading":"にほん","gloss":"two (bottles)","parts":[["二","ニ","two"],["本","ホン","counter for long things"]],"clip":"s_n5u3d2_two"},{"id":"fish","word":"魚","reading":"さかな","gloss":"fish","parts":[["魚","さかな","fish"]],"clip":"s_n5u3d2_fish"},{"id":"flower","word":"花","reading":"はな","gloss":"flowers","parts":[["花","はな","flower"]],"clip":"s_n5u3d2_flower"},{"id":"hundred","word":"百円","reading":"ひゃくえん","gloss":"100 yen","parts":[["百","ヒャク","hundred"],["円","エン","yen"]],"clip":"s_n5u3d2_hundred"},{"id":"thousand","word":"千円","reading":"せんえん","gloss":"1,000 yen","parts":[["千","セン","thousand"],["円","エン","yen"]],"clip":"s_n5u3d2_thousand"}],"check":{"id":"n5u03d2.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"この　花は　_千円_でした。","options":["せんえん","ぜんえん","せいえん","ちえん"],"answer":1,"explain":"千円 is read せんえん. 千 becomes ぜん only after 三 (三千, さんぜん). せいえん and ちえん are not readings of 千円."}},"skill":{"kind":"reading","ja":"内容理解（短文）","en":"Short passage","ask":"What did the writer do last weekend, and what did they not do?","seconds":90,"passage":"先週の　土よう日、^母と^　駅の　前の　店へ　行きました。魚と　花を　買いました。^本も　見ましたが、買いませんでした^。日よう日は　雨でした。^どこへも　行きませんでした^。^うちで　テレビを　見ました^。^しゅくだいは　しませんでした^。","strategy":"Look at the end of each sentence: 〜ました means it happened, 〜ませんでした means it did not.","item":{"id":"n5u03d2.r1","kind":"choice","type":"読解・内容理解（短文）","q":"この　人に　ついて、ただしい　ものは　どれですか。","options":["日よう日は　うちに　いました。","日よう日に　しゅくだいを　しました。","土よう日に　ひとりで　店へ　行きました。","土よう日に　本を　買いました。"],"short":["日よう日はうちにいた","しゅくだいをした","ひとりで店へ行った","本を買った"],"answer":1,"explain":"On Sunday the writer went nowhere (どこへも行きませんでした) and watched TV at home, so the writer was at home.","why":["","The writer writes しゅくだいはしませんでした: no homework was done.","The writer went with 母 (mother), not alone.","The writer looked at books but writes 買いませんでした: no book was bought."]}}},{"title":"〜を・〜へ／〜に","grammar":{"points":[{"id":"n5u03d3.p1","form":"〜を","gloss":"marks what you eat, read, buy…","connect":[{"pos":"Noun (the thing you eat, read, buy…)","rule":"〜{を}[食|た]べます／〜{を}[読|よ]みます／〜{を}[買|か]います"},{"pos":"Question: what","rule":"[何|なに]{を}[食|た]べますか"}],"examples":[{"ja":"[毎日|まいにち]パン{を}[食|た]べます。","en":"I eat bread every day.","clip":"x_n5u03d3_p1_1"},{"ja":"きのう、この[本|ほん]{を}[読|よ]みました。","en":"I read this book yesterday.","clip":"x_n5u03d3_p1_2"}],"watch":{"note":"The thing you eat, drink, read or buy takes を, not が. が is for the thing that is there, as in 水があります.","bad":"毎日コーヒーが飲みます。","good":"毎日コーヒーを飲みます。"}},{"id":"n5u03d3.p2","form":"〜へ／〜に","gloss":"to (the place you go)","connect":[{"pos":"Place you go to (へ is read え)","rule":"〜{へ}[行|い]きます／[来|き]ます／かえります"},{"pos":"Place you go to (same meaning with に)","rule":"〜{に}[行|い]きます／[来|き]ます／かえります"},{"pos":"Question: where to","rule":"どこ{へ}[行|い]きますか"}],"examples":[{"ja":"あした、[大学|だいがく]{へ}[行|い]きます。","en":"I am going to the university tomorrow.","clip":"x_n5u03d3_p2_1"},{"ja":"[先週|せんしゅう]、[友|とも]だちが[日本|にほん]{に}[来|き]ました。","en":"My friend came to Japan last week.","clip":"x_n5u03d3_p2_2"}],"watch":{"note":"The place you are going to takes へ or に, not を. へ is said え, but it is always written へ.","bad":"あした、学校を行きます。","good":"あした、学校へ行きます。"}}],"compare":{"intro":"All three come after a noun. The verb after it tells you which one you need.","forms":[{"form":"〜を","tag":"なにを？ · what you buy, eat, read","mark":"dot","ja":"[花|はな]{を}[買|か]います。","en":"I buy flowers."},{"form":"〜へ／〜に","tag":"どこへ？ · where you go","mark":"dot","ja":"[花|はな]や{へ}[行|い]きます。","en":"I go to the flower shop."},{"form":"〜が","tag":"なにが？ · what is there","mark":"dot","ja":"[駅|えき]に[花|はな]や{が}あります。","en":"There is a flower shop at the station."}],"check":{"id":"n5u03d3.c1","kind":"choice","type":"文の文法1","label":"ともだちと","q":"あした、[友|とも]だちのうち（　　）[行|い]きます。","options":["が","を","へ"],"answer":3,"why":["うちが行きます would make the house the one who goes.","を marks the thing you eat, read or buy. The house is the place you go to.","The friend's house is where you go, and the place before 行きます takes へ."],"explain":null}},"drill":[{"id":"n5u03d3.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[父|ちち]は[毎日|まいにち][新聞|しんぶん]（　　）^[読|よ]みます^。","options":["へ","が","に","を"],"answer":4,"why":["へ marks the place you go to. 読みます is not going anywhere.","With 読みます, the thing you read takes を, not が. 父は already says who reads.","に here would mark a place you go to. A newspaper is not a place.","The newspaper is the thing he reads, so it takes を."],"explain":null},{"id":"n5u03d3.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"らいしゅう、[日本|にほん]（　　）^[行|い]きます^。","options":["を","が","で","へ"],"answer":4,"why":["を does not mark the place you go to.","日本が行きます would make Japan the one who goes.","で marks where you do something, not where you go.","Japan is where you are going, and the place before 行きます takes へ."],"explain":null},{"id":"n5u03d3.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：きのう[何|なに]（　　）[買|か]いましたか。　B：^[本|ほん]を^[買|か]いました。","options":["は","を","へ","が"],"answer":2,"why":["何は does not work in this question. The thing you buy takes を.","A asks about the thing B bought, so 何 takes を, just like 本を in B's answer.","へ marks the place you go to. 買いました is not going anywhere.","The thing you buy takes を, not が."],"explain":null},{"id":"n5u03d3.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[先週|せんしゅう]、[母|はは]がわたしのうち^に^（　　）。","options":["[買|か]いました","[来|き]ました","[食|た]べました","[読|よ]みました"],"answer":2,"why":["うちに with 買いました does not make sense here. うちに needs a verb of going or coming.","うちに is the place she came to, so the verb is one of coming: 来ました.","My house is not something you eat, and うちに needs a verb of going or coming.","My house is not something you read, and うちに needs a verb of going or coming."],"explain":null},{"id":"n5u03d3.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしはきのう","after":"。","tiles":["[新|あたら]しい","[本|ほん]","を","[読|よ]みました"],"star":2,"bank":[3,0,2,1],"hint":"新しい goes right before the thing it describes. Which tile marks the thing you read?","full":"わたしはきのう[新|あたら]しい[本|ほん]{を}[読|よ]みました。","explain":"新しい goes right before 本. The thing you read takes を, and the verb comes last: わたしはきのう新しい本を読みました, \"I read a new book yesterday.\""},{"id":"n5u03d3.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あした、[母|はは]と","after":"。","tiles":["[新|あたら]しい","デパート","へ","[行|い]きます"],"star":2,"bank":[1,3,0,2],"hint":"Where are you going? Which tile marks that place?","full":"あした、[母|はは]と[新|あたら]しいデパート{へ}[行|い]きます。","explain":"新しい goes right before デパート. The place you go to takes へ, and 行きます comes last: あした、母と新しいデパートへ行きます, \"Tomorrow I am going to the new department store with my mother.\""}],"exam":[{"id":"n5u03d3.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：きのう　何を　しましたか。　B：ともだちと　えいが（　　）　見ました。","options":["に","を","へ","が"],"answer":2,"explain":"The film is the thing they watched, so it takes を. へ and に mark a place you go to, and with 見ました the thing you watch does not take が."},{"id":"n5u03d3.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"らいげつ　くにへ（　　）。","options":["かえります","食べます","読みます","あります"],"answer":1,"explain":"くにへ marks the place you go to, so the verb must be one of moving: かえります, \"I will go back to my country.\" 食べます and 読みます take a thing with を, and あります takes a place with に, not へ."},{"id":"n5u03d3.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"父は　きのう","after":"。","tiles":["大きい","魚","を","買いました"],"star":2,"bank":[2,3,0,1],"full":"父は　きのう　大きい　魚{を}　買いました。","explain":"大きい, 魚, を, 買いました. 大きい goes right before 魚, the thing he bought takes を, and the verb comes last."}]},"scene":{"ja":"駅のホームで","en":"On a train platform","intro":"Tap every word you would read on the platform signs and the departure board.","words":[{"id":"train","word":"電車","reading":"でんしゃ","gloss":"train","parts":[["電","デン","electricity"],["車","シャ","vehicle, car"]],"clip":"s_n5u3d3_train"},{"id":"station","word":"駅","reading":"えき","gloss":"station","parts":[["駅","エキ","station"]],"clip":"s_n5u3d3_station"},{"id":"bound","word":"行き","reading":"ゆき","gloss":"bound for (after a place name)","parts":[["行","ゆ","go"]],"clip":"s_n5u3d3_bound"},{"id":"university","word":"大学前","reading":"だいがくまえ","gloss":"University (station name: in front of the university)","parts":[["大","ダイ","big"],["学","ガク","study"],["前","まえ","front"]],"clip":"s_n5u3d3_university"},{"id":"north-exit","word":"北口","reading":"きたぐち","gloss":"north exit","parts":[["北","きた","north"],["口","ぐち","mouth, opening"]],"clip":"s_n5u3d3_north_exit"},{"id":"south-exit","word":"南口","reading":"みなみぐち","gloss":"south exit","parts":[["南","みなみ","south"],["口","ぐち","mouth, opening"]],"clip":"s_n5u3d3_south_exit"},{"id":"exit","word":"出口","reading":"でぐち","gloss":"exit","parts":[["出","で","go out"],["口","ぐち","mouth, opening"]],"clip":"s_n5u3d3_exit"},{"id":"am","word":"午前","reading":"ごぜん","gloss":"a.m., morning","parts":[["午","ゴ","noon"],["前","ゼン","before"]],"clip":"s_n5u3d3_am"}],"check":{"id":"n5u03d3.k1","kind":"choice","type":"表記","label":"How the exam asks it","q":"あ、_でんしゃ_が　来ましたよ。","options":["雨車","電東","電車","雨東"],"answer":3,"explain":"でんしゃ, \"train\", is written 電車: 電 (electricity) and 車 (vehicle). 雨 (rain) is only the top part of 電, and 東 (east) looks like 車 but is a different kanji. 雨車, 電東 and 雨東 are not words."}},"skill":{"kind":"listening","ja":"課題理解","en":"Task comprehension","ask":"男の人は　はじめに　何を　買いますか。","audio":[["N","駅で、女の人と男の人が話しています。男の人は、はじめに、何を買いますか。","えきで、おんなのひとと　おとこのひとが　はなしています。おとこのひとは、はじめに、なにを　かいますか。"],["F","電車は十時半ですね。まだ二十分ありますよ。","でんしゃは　じゅうじはんですね。まだ　にじゅっぷん　ありますよ。"],["M","じゃあ、ぼく、店へ行きます。パンとおちゃを買います。","じゃあ、ぼく、みせへ　いきます。パンと　おちゃを　かいます。"],["F","パンはありますよ。わたしのかばんの中です。","パンは　ありますよ。わたしの　かばんの　なかです。"],["M","そうですか。じゃあ、おちゃを買います。",null],["F","あ、でも、きっぷは買いましたか。",null],["M","あ、まだです。",null],["F","じゃあ、きっぷが先ですよ。","じゃあ、きっぷが　さきですよ。"],["M","そうですね。おちゃは、あとで買います。",null],["N","男の人は、はじめに、何を買いますか。","おとこのひとは、はじめに、なにを　かいますか。"]],"item":{"id":"n5u03d3.r1","kind":"choice","type":"課題理解","q":"男の人は　はじめに　何を　買いますか。","script":["ナレーター：駅で、女の人と男の人が話しています。男の人は、はじめに、何を買いますか。","女：電車は十時半ですね。まだ二十分ありますよ。","男：じゃあ、ぼく、店へ行きます。パンとおちゃを買います。","女：パンはありますよ。わたしのかばんの中です。","男：そうですか。じゃあ、おちゃを買います。","女：あ、でも、きっぷは買いましたか。","男：あ、まだです。","女：じゃあ、きっぷが先ですよ。","男：そうですね。おちゃは、あとで買います。","ナレーター：男の人は、はじめに、何を買いますか。"],"options":["きっぷ","おちゃ","パンと　おちゃ","パン"],"printed":true,"short":["きっぷ","おちゃ","パンと おちゃ","パン"],"answer":1,"why":["He has not bought a ticket yet (まだです), and the woman says きっぷが先ですよ, \"the ticket comes first\".","He will buy tea, but he says おちゃは、あとで買います: later, after the ticket.","This was his first plan, but the woman already has bread in her bag.","The woman says パンはありますよ: the bread is in her bag, so he does not buy it."],"explain":null,"clip":"l_n5u3d3"}}},{"title":"〜で（場所）・〜で（道具）","grammar":{"points":[{"id":"n5u03d4.p1","form":"〜で（場所）","gloss":"at, in (where you do something)","connect":[{"pos":"Noun (the place) + action verb, ます form","rule":"〜 ＋ {で} ＋ [食|た]べます／[読|よ]みます"},{"pos":"Noun (the place) + what you do","rule":"〜 ＋ {で} ＋ 〜 ＋ を ＋ verb"}],"examples":[{"ja":"[学校|がっこう]{で}[日本語|にほんご]をべんきょうします。","en":"I study Japanese at school.","clip":"x_n5u03d4_p1_1"},{"ja":"[駅|えき]の[前|まえ]の[店|みせ]{で}パンを[買|か]います。","en":"I buy bread at the shop in front of the station.","clip":"x_n5u03d4_p1_2"}],"watch":{"note":"で is for the place where you do something. あります and います only say where a thing or a person is, so that place takes に: 学校に としょかんが あります.","bad":"学校でとしょかんがあります。","good":"学校にとしょかんがあります。"}},{"id":"n5u03d4.p2","form":"〜で（道具）","gloss":"with, by, in (what you use)","connect":[{"pos":"Noun (a tool)","rule":"〜 ＋ {で} ＋ [食|た]べます／[書|か]きます"},{"pos":"Noun (a way to travel)","rule":"〜 ＋ {で} ＋ [行|い]きます／[来|き]ます"},{"pos":"Noun (a language)","rule":"〜 ＋ {で} ＋ [話|はな]します"}],"examples":[{"ja":"はし{で}[魚|さかな]を[食|た]べます。","en":"I eat fish with chopsticks.","clip":"x_n5u03d4_p2_1"},{"ja":"[毎日|まいにち][電車|でんしゃ]{で}[会社|かいしゃ]へ[行|い]きます。","en":"I go to work by train every day.","clip":"x_n5u03d4_p2_2"}],"watch":{"note":"With 行きます, the bus is how you go, so it takes で. バスに goes with a different verb: バスに のります (get on the bus).","bad":"バスに学校へ行きます。","good":"バスで学校へ行きます。"}}],"compare":{"intro":"All three come right after a noun. で says where you do something or what you use; に with あります says where a thing is.","forms":[{"form":"〜で（場所）","tag":"するところ · where you do it","mark":"dot","ja":"[学校|がっこう]{で}[本|ほん]を[読|よ]みます。","en":"I read books at school."},{"form":"〜に（あります）","tag":"あるところ · where it is","mark":"dot","ja":"[学校|がっこう]{に}[本|ほん]がたくさんあります。","en":"There are a lot of books at school."},{"form":"〜で（道具）","tag":"つかうもの · what you use","mark":"dot","ja":"ペン{で}[名前|なまえ]を[書|か]きます。","en":"I write my name with a pen."}],"check":{"id":"n5u03d4.c1","kind":"choice","type":"文の文法1","label":"学校の店","q":"[学校|がっこう]の[中|なか]に[店|みせ]があります。その[店|みせ]（　　）^パンを[買|か]います^。","options":["に","を","で"],"answer":3,"why":["に says where a thing is, with あります. Here you do something there: 買います.","パンを already has を. その店を パンを has two を and makes no sense.","Buying is an action, so the shop where you buy takes で."]}},"drill":[{"id":"n5u03d4.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは[毎日|まいにち]うち（　　）^テレビを[見|み]ます^。","options":["で","に","を","が"],"answer":1,"why":["見ます is an action, so the place where you watch takes で: at home.","に would say where something is. Watching TV is an action, so に does not fit.","テレビを already has を. うちを テレビを has two を.","うちが would make the house the one watching TV."]},{"id":"n5u03d4.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きょうしつ（　　）^つくえやいすがあります^。","options":["へ","で","に","を"],"answer":3,"why":["へ shows a direction you go to. あります is not going anywhere.","あります here says where desks and chairs are. That is not an action, so で does not fit.","Where things are takes に before あります: in the classroom.","あります does not take を."],"explain":null},{"id":"n5u03d4.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"はし（　　）^ごはんを[食|た]べます^。","options":["と","を","に","で"],"answer":4,"why":["はしと ごはんを would mean you eat the chopsticks and the rice.","ごはんを already has を. はしを ごはんを has two を.","はしに does not say what you eat with.","Chopsticks are what you use to eat, so they take で."],"explain":null},{"id":"n5u03d4.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは[毎日|まいにち][電車|でんしゃ]（　　）^[会社|かいしゃ]へ[行|い]きます^。","options":["で","を","と","に"],"answer":1,"why":["The train is how you go, so it takes で: by train.","行きます does not take を for the train here.","電車と would mean you go together with the train, like with a friend.","電車に goes with のります (get on). With 行きます it does not fit."],"explain":null},{"id":"n5u03d4.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[山川|やまかわ]さんは[毎日|まいにち]バス","after":"よ。","tiles":["で","[学校|がっこう]","へ","[来|き]ます"],"star":2,"bank":[3,0,2,1],"hint":"First say how Ms. Yamakawa comes, then where she comes to, then the verb.","full":"[山川|やまかわ]さんは[毎日|まいにち]バス{で}[学校|がっこう]へ[来|き]ますよ。","explain":"バスで is how she comes. 学校へ is where she comes to, and 来ます goes last, right before よ."},{"id":"n5u03d4.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[中山|なかやま]さんはいつも[駅|えき]の[前|まえ]の[店|みせ]","after":"。","tiles":["で","パン","を","[買|か]います"],"star":0,"bank":[2,3,0,1],"hint":"The shop is where the action happens. Then what is bought, then the verb.","full":"[中山|なかやま]さんはいつも[駅|えき]の[前|まえ]の[店|みせ]{で}パンを[買|か]います。","explain":"店で is where Mr. Nakayama buys. パンを is what he buys, and 買います comes last."}],"exam":[{"id":"n5u03d4.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きのう　デパート（　　）　くつを　買いました。","options":["を","へ","に","で"],"answer":4,"explain":"Buying is an action, so the place where you buy takes で: デパートで 買いました. に would say where something is, くつを already has を, and へ shows the direction you go to, which needs a verb like 行きました."},{"id":"n5u03d4.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この　かみには　えんぴつ（　　）　名前を　書きます。","options":["へ","で","を","が"],"answer":2,"explain":"The pencil is what you write with, so it takes で. 名前を already has を, えんぴつが would make the pencil the writer, and へ shows a direction."},{"id":"n5u03d4.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「きのう　学校","after":"か。」　B「カレーです。」","tiles":["で","何","を","食べました"],"star":0,"bank":[2,0,3,1],"full":"A「きのう　学校{で}　何を　食べましたか。」　B「カレーです。」","explain":"で, 何, を, 食べました: what did you eat at school yesterday? 学校で is where the eating happened, 何を asks what was eaten, and B answers カレーです."}]},"scene":{"ja":"センターのおしらせ","en":"A notice at a community centre","intro":"Tap each word on the notice about this week's Japanese classes.","words":[{"id":"japanese","word":"日本語","reading":"にほんご","gloss":"Japanese (language)","parts":[["日","ニ","sun, day"],["本","ホン","origin, book"],["語","ゴ","language, word"]],"clip":"s_n5u3d4_japanese"},{"id":"speak","word":"話す","reading":"はなす","gloss":"to speak, to talk","parts":[["話","はな","talk"]],"clip":"s_n5u3d4_speak"},{"id":"read","word":"読む","reading":"よむ","gloss":"to read","parts":[["読","よ","read"]],"clip":"s_n5u3d4_read"},{"id":"write","word":"書く","reading":"かく","gloss":"to write","parts":[["書","か","write"]],"clip":"s_n5u3d4_write"},{"id":"listen","word":"聞く","reading":"きく","gloss":"to listen, to hear","parts":[["聞","き","hear, listen"]],"clip":"s_n5u3d4_listen"},{"id":"watch","word":"見る","reading":"みる","gloss":"to see, to watch","parts":[["見","み","see"]],"clip":"s_n5u3d4_watch"},{"id":"closed","word":"休み","reading":"やすみ","gloss":"closed, day off","parts":[["休","やす","rest"]],"clip":"s_n5u3d4_closed"},{"id":"afternoon","word":"午後","reading":"ごご","gloss":"afternoon, p.m.","parts":[["午","ゴ","noon"],["後","ゴ","after"]],"clip":"s_n5u3d4_afternoon"}],"check":{"id":"n5u03d4.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"土よう日の　_午後_は　日本語の　クラスが　あります。","options":["ごこう","ごぜん","こご","ごご"],"answer":4,"explain":"午後 is ごご, afternoon. ごぜん is 午前 (morning). こご and ごこう are not words; both kanji here are read ご."}},"skill":{"kind":"reading","ja":"内容理解（短文）","en":"Short passage","ask":"Where does Lin eat lunch on Fridays?","seconds":90,"passage":"リンさんは　わたしの　クラスの　友だちです。毎日　電車で　学校へ　来ます。ひるごはんは　いつも　学校の　しょくどうで　食べますが、^金よう日は　学校の　前の　こうえんで^　食べます。よるは　うちで　日本語の　本を　読みます。","strategy":"Find ひるごはん, then read past が to see where Lin eats on 金よう日.","item":{"id":"n5u03d4.r1","kind":"choice","type":"読解・内容理解（短文）","q":"リンさんは　金よう日に　どこで　ひるごはんを　食べますか。","options":["学校の　前の　こうえん","えきの　前の　店","うち","学校の　しょくどう"],"short":["学校の前のこうえん","えきの前の店","うち","学校のしょくどう"],"answer":1,"explain":"Lin usually eats lunch in the school cafeteria, but the sentence after が says 金よう日は 学校の 前の こうえんで 食べます: on Fridays, in the park in front of the school.","why":["","The note does not talk about a shop by the station.","Lin reads books at home in the evening. The note does not say Lin eats lunch there.","That is where Lin usually eats, but not on Fridays."]}}},{"title":"〜ましょう・〜ませんか","grammar":{"points":[{"id":"n5u03d5.p1","form":"〜ましょう","gloss":"let's (suggesting, or saying yes)","connect":[{"pos":"Verb, ます form","rule":"〜ます → 〜{ましょう}"},{"pos":"Verb, doing it together","rule":"いっしょに 〜{ましょう}"},{"pos":"Saying yes to an invitation","rule":"ええ、〜{ましょう}"}],"examples":[{"ja":"いっしょにコーヒーを[飲|の]み{ましょう}。","en":"Let's have a coffee together.","clip":"x_n5u03d5_p1_1"},{"ja":"A「あした[山|やま]へ[行|い]きませんか。」B「ええ、[行|い]き{ましょう}。」","en":"A: Won't you go to the mountains tomorrow? B: Yes, let's go.","clip":"x_n5u03d5_p1_2"}],"watch":{"note":"To say yes to an invitation, answer with ましょう. ませんか is only for asking, so repeating it does not say yes.","bad":"A「いっしょに行きませんか。」B「ええ、行きませんか。」","good":"A「いっしょに行きませんか。」B「ええ、行きましょう。」"}},{"id":"n5u03d5.p2","form":"〜ませんか","gloss":"won't you…? (a polite invitation)","connect":[{"pos":"Verb, ます form","rule":"〜ます → 〜{ませんか}"},{"pos":"Verb, inviting someone to join you","rule":"いっしょに 〜{ませんか}"}],"examples":[{"ja":"[土|ど]よう[日|び]、いっしょにえいがを[見|み]{ませんか}。","en":"Won't you see a movie with me on Saturday?","clip":"x_n5u03d5_p2_1"},{"ja":"あの[店|みせ]でおちゃを[飲|の]み{ませんか}。","en":"Would you like to have some tea at that shop?","clip":"x_n5u03d5_p2_2"}],"watch":{"note":"ませんか looks negative, but it is a friendly invitation. To say no, いいえ、しません sounds cold. Say sorry and use ちょっと… instead.","bad":"A「あした、テニスをしませんか。」B「いいえ、しません。」","good":"A「あした、テニスをしませんか。」B「すみません、あしたはちょっと…。」"}}],"compare":{"intro":"All three are about doing something with someone. What changes is whether you invite, agree, or offer.","forms":[{"form":"〜ませんか","tag":"さそう · won't you…?","mark":"dot","ja":"いっしょにかえり{ませんか}。","en":"Would you like to go home together?"},{"form":"〜ましょう","tag":"いっしょに · let's","mark":"dot","ja":"ええ、かえり{ましょう}。","en":"Yes, let's go home."},{"form":"〜ましょうか","tag":"ていあん · shall we? / shall I?","mark":"dot","ja":"まどをあけ{ましょうか}。","en":"Shall I open the window?"}],"check":{"id":"n5u03d5.c1","kind":"choice","type":"文の文法1","label":"まちあわせ","q":"A「あしたは^[何時|なんじ]^に[会|あ]い（　　）。」B「^[十時|じゅうじ]はどうですか^。」","options":["ませんか","ました","ましょうか"],"answer":3,"why":["ませんか invites, and the answer is yes or no. It does not go with a question word like 何時.","ました is the past, but A is talking about あした (tomorrow).","A asks \"what time shall we meet?\", and B suggests ten o'clock."]}},"drill":[{"id":"n5u03d5.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「[日|にち]よう[日|び]、いっしょにテニスを（　　）。」B「^ええ、しましょう^。」","options":["しません","しませんでした","しませんか","しましたか"],"answer":3,"why":["しません says \"I won't play\". B answers ええ、しましょう, so A must have asked something.","しませんでした says \"I didn't play\". B's しましょう shows A is talking about a plan.","B says yes with しましょう, so A invited B: しませんか.","しましたか asks about the past. B's しましょう shows the tennis has not happened yet."],"explain":null},{"id":"n5u03d5.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「[駅|えき]の[前|まえ]の[店|みせ]でおちゃを[飲|の]みませんか。」B「^ええ^、（　　）。」","options":["[飲|の]みましょう","[飲|の]みませんか","[飲|の]みました","[飲|の]みません"],"answer":1,"why":["ええ says yes, and ましょう agrees: \"Yes, let's have some.\"","飲みませんか is A's invitation. B repeating it does not answer.","飲みました is the past. They have not had the tea yet.","ええ says yes, but 飲みません says \"I won't drink\". The two do not match."]},{"id":"n5u03d5.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[先生|せんせい]「みなさん、^[今|いま]から^いっしょにこの[本|ほん]を[読|よ]み（　　）。」","options":["ましたか","ましょう","ました","ませんでした"],"answer":2,"why":["ましたか asks about the past. 今から talks about what happens next.","今から means \"from now\", so the teacher says \"let's read\": 読みましょう.","ました is the past. 今から talks about what happens next.","ませんでした is the past too, and does not fit 今から."],"explain":null},{"id":"n5u03d5.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あした、うちへ[来|き]（　　）。」B「^ええ、ありがとうございます^。」","options":["ませんか","ましたか","ません","ました"],"answer":1,"why":["B thanks A, so A invited B: \"Won't you come to my house?\"","ましたか asks about the past, but A says あした, tomorrow.","来ません says \"I won't come\". B would not say thank you to that.","ました is the past, but A says あした, tomorrow."]},{"id":"n5u03d5.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「[土|ど]よう[日|び]に、いっしょに","after":"。」B「いいですね。[行|い]きましょう。」","tiles":["[山|やま]","へ","[行|い]き","ませんか"],"star":2,"bank":[3,1,0,2],"hint":"へ comes right after the place. ませんか joins the verb without ます.","full":"A「[土|ど]よう[日|び]に、いっしょに[山|やま]へ[行|い]き{ませんか}。」B「いいですね。[行|い]きましょう。」","explain":"山 is the place, so へ follows it. 行き is 行きます without ます, and ませんか joins it to make the invitation."},{"id":"n5u03d5.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「どこで[会|あ]いましょうか。」B「[駅|えき]の","after":"。」","tiles":["[入口|いりぐち]","の","[前|まえ]で","[会|あ]いましょう"],"star":2,"bank":[2,3,1,0],"hint":"B answers with a place. Which word can follow 駅の? The verb comes last.","full":"A「どこで[会|あ]いましょうか。」B「[駅|えき]の[入口|いりぐち]の[前|まえ]で{[会|あ]いましょう}。」","explain":"駅の入口 is the station entrance, and の joins it to 前で: in front of the entrance. 会いましょう answers A's 会いましょうか."}],"exam":[{"id":"n5u03d5.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あした　わたしの　うちで　いっしょに　ばんごはんを　（　　）。」B「ありがとうございます。」","options":["食べましたか","食べませんでした","食べました","食べませんか"],"answer":4,"explain":"A invites B for tomorrow, and B says thank you, so 食べませんか. The other three are past forms and do not fit あした."},{"id":"n5u03d5.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あしたは　どこで　（　　）。」B「駅の　入口は　どうですか。」","options":["会いませんか","会いました","会いましたか","会いましょうか"],"answer":4,"explain":"A asks where to meet tomorrow, and B suggests a place: 会いましょうか, \"shall we meet?\" 会いませんか does not go with どこ. 会いました is not a question, and 会いましたか asks about the past."},{"id":"n5u03d5.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「土よう日に　いっしょに　","after":"。」B「いいですね。」","tiles":["花見","に","行き","ませんか"],"star":2,"bank":[1,3,0,2],"full":"A「土よう日に　いっしょに　花見に行き{ませんか}。」B「いいですね。」","explain":"花見, に, 行き, ませんか. に after 花見 says where you go, and ませんか joins 行き to invite."}]},"scene":{"ja":"花見のポスター","en":"A poster for a hanami party","intro":"Tap every word on the poster you would read to know what it is, when, and where to meet.","words":[{"id":"hanami","word":"花見","reading":"はなみ","gloss":"cherry-blossom viewing","parts":[["花","はな","flower"],["見","み","see"]],"clip":"s_n5u3d5_hanami"},{"id":"sat","word":"土よう日","reading":"どようび","gloss":"Saturday","parts":[["土","ド","earth, soil"],["日","び","day"]],"clip":"s_n5u3d5_sat"},{"id":"pm","word":"午後","reading":"ごご","gloss":"afternoon, p.m.","parts":[["午","ゴ","noon"],["後","ゴ","after"]],"clip":"s_n5u3d5_pm"},{"id":"one","word":"一時","reading":"いちじ","gloss":"one o'clock","parts":[["一","イチ","one"],["時","ジ","o'clock, time"]],"clip":"s_n5u3d5_one"},{"id":"half3","word":"三時半","reading":"さんじはん","gloss":"half past three","parts":[["三","サン","three"],["時","ジ","o'clock, time"],["半","ハン","half"]],"clip":"s_n5u3d5_half3"},{"id":"entr","word":"入口","reading":"いりぐち","gloss":"entrance","parts":[["入","いり","enter"],["口","ぐち","mouth, opening"]],"clip":"s_n5u3d5_entr"},{"id":"rain","word":"雨","reading":"あめ","gloss":"rain","parts":[["雨","あめ","rain"]],"clip":"s_n5u3d5_rain"},{"id":"off","word":"休み","reading":"やすみ","gloss":"off, cancelled; a day off","parts":[["休","やす","rest"]],"clip":"s_n5u3d5_off"}],"check":{"id":"n5u03d5.k1","kind":"choice","type":"表記","label":"How the exam asks it","q":"花見は　_ごご_　一時からです。","options":["五後","午後","午前","後午"],"answer":2,"explain":"ごご is written 午後: 午 \"noon\" and 後 \"after\". 午前 is ごぜん, the morning. 後午 and 五後 are not words."}},"skill":{"kind":"listening","ja":"即時応答","en":"Quick response","ask":"えなどが　ありません。ぶんを　聞いて、1から3の　中から、いちばん　いい　ものを　一つ　えらんで　ください。","item":{"id":"n5u03d5.r1","kind":"choice","type":"即時応答","q":"女：土よう日、いっしょに　花見に　行きませんか。","script":["女：土よう日、いっしょに花見に行きませんか。","ナレーター：1","男：ええ、行きませんか。","ナレーター：2","男：はい、行きませんでした。","ナレーター：3","男：すみません、土よう日はちょっと…。"],"options":["ええ、行きませんか。","はい、行きませんでした。","すみません、土よう日は　ちょっと…。"],"printed":false,"short":["ええ、行きませんか","はい、行きませんでした","土よう日はちょっと…"],"answer":3,"why":["ええ says yes, but 行きませんか is an invitation. To say yes, he would say 行きましょう.","行きませんでした is the past, \"I didn't go\". She is asking about this Saturday.","A polite no: he says sorry and ちょっと… instead of a flat いいえ."],"clip":"l_n5u3d5"},"audio":[["F","土よう日、いっしょに花見に行きませんか。","どようび、いっしょにはなみにいきませんか。"],["N","1",null],["M","ええ、行きませんか。","ええ、いきませんか。"],["N","2",null],["M","はい、行きませんでした。","はい、いきませんでした。"],["N","3",null],["M","すみません、土よう日はちょっと…。","すみません、どようびはちょっと…。"]]}},{"title":"まとめ：似ている文法","grammar":{"points":[],"compare":{"intro":"To tell this unit's points apart, ask three things: when it happens and whether it happens (〜ます, 〜ません, 〜ました, 〜ませんでした), what job the noun does (を for the thing, へ or に for where you go, に for where something is, で for where you do it or what you use), and whether you are inviting or saying yes (〜ませんか or 〜ましょう).","forms":[{"form":"〜に／〜で","tag":"いる・する · being there or doing there","mark":"dot","ja":"こうえん{に}[子|こ]どもがいます。こうえん{で}[子|こ]どもがあそびます。","en":"There are children in the park. The children play in the park."},{"form":"〜へ／〜を","tag":"どこへ・なにを · where to, or what","mark":"dot","ja":"[新|あたら]しいきっさてん{へ}[行|い]きます。コーヒー{を}[飲|の]みます。","en":"I go to the new café. I drink coffee."},{"form":"〜ませんか／〜ましょう","tag":"さそう・こたえる · inviting or saying yes","mark":"dot","ja":"A「[今|いま]から[外|そと]で[食|た]べ{ませんか}。」B「ええ、[食|た]べ{ましょう}。」","en":"A: Shall we go and eat out now? B: Yes, let's."}],"check":{"id":"n5u03d6.c1","kind":"choice","type":"文の文法1","label":"まちで","q":"[学校|がっこう]の[前|まえ]（　　）^きっさてんがあります^。","options":["に","を","で"],"answer":1,"why":["With あります, the place where a thing is takes に: 学校の前に.","を marks the thing an action is done to. あります is not that kind of verb, and the café already has が.","で marks where you do something. あります only says where the café is, so the place takes に."],"explain":null}},"drill":[{"id":"n5u03d6.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「^きのう^、[中川|なかがわ]さんと[山|やま]へ（　　）。」B「はい、^[行|い]きました^。」","options":["[行|い]きます","[行|い]きましたか","[行|い]きませんか","[行|い]きましょう"],"answer":2,"why":["行きます is not past, so it does not fit きのう, and without か it is not a question.","きのう is past and B answers はい, 行きました, so A asked about the past: 行きましたか.","行きませんか invites someone to go later. You cannot invite someone to yesterday.","行きましょう suggests going later, and B's はい, 行きました does not answer a suggestion."],"explain":null},{"id":"n5u03d6.d2","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"[母|はは]は[月|げつ]よう[日|び]と[木|もく]よう[日|び]にデパート（　　）^はたらきます^。","options":["で","へ","を","に"],"answer":1,"why":["The department store is where she does the work, so で: デパートではたらきます.","へ marks where you go, with verbs like 行きます. はたらきます is something you do at a place.","を marks the thing an action is done to. デパート is where she works, not what she works on.","に goes with verbs like 行きます, 来ます or あります in this unit. はたらきます is an action done there, so it takes で."],"explain":null},{"id":"n5u03d6.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「つめたいジュースがありますよ。[飲|の]み（　　）。」B「^ありがとうございます^。いただきます。」","options":["ましたか","ませんでした","ませんか","ません"],"answer":3,"why":["飲みましたか asks about the past. B's いただきます takes a drink now.","飲みませんでした says \"I didn't drink\". It is not an offer, so B's thanks do not fit.","A offers a drink: 飲みませんか, \"won't you have some?\" B thanks A and takes it.","飲みません says \"I don't drink\". B would not thank A for that."],"explain":null},{"id":"n5u03d6.d4","kind":"choice","type":"文の文法1","label":"Choose the phrase","q":"A「^きのう^、[何|なに]をしましたか。」B「[友|とも]だちと[駅|えき]の[前|まえ]のデパート（　　）。」","options":["にごはんを[食|た]べません","でごはんを[食|た]べました","へごはんを[食|た]べました","でごはんを[食|た]べます"],"answer":2,"why":["に does not mark where you eat, and 食べません is neither past nor an answer to \"what did you do\".","The store is where they ate, so で, and きのう needs the past: 食べました.","へ marks where you go. 食べました is done at the store, so the place takes で.","で is right, but 食べます is not past. A asked about きのう."],"explain":null},{"id":"n5u03d6.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「[金|きん]よう[日|び]の[午後|ごご]、","after":"。」B「いいですね。[会|あ]いましょう。」","tiles":["[駅|えき]の","[中|なか]の","きっさてんで","[会|あ]いませんか"],"star":2,"bank":[2,3,1,0],"hint":"Where is the café? Start with the biggest place. The invitation comes last.","full":"A「[金|きん]よう[日|び]の[午後|ごご]、[駅|えき]の[中|なか]の{きっさてんで}[会|あ]いませんか。」B「いいですね。[会|あ]いましょう。」","explain":"駅の中の describes the café: the one inside the station. きっさてんで says where you meet, so it takes で, and 会いませんか invites. B says yes with 会いましょう."},{"id":"n5u03d6.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[先週|せんしゅう]の[金|きん]よう[日|び]、うちに","after":"。","tiles":["[父|ちち]の","[会社|かいしゃ]の","[人|ひと]が","[来|き]ました"],"star":1,"bank":[3,1,2,0],"hint":"Whose company? Which person? 先週 tells you the time, and the verb comes last.","full":"[先週|せんしゅう]の[金|きん]よう[日|び]、うちに[父|ちち]の{[会社|かいしゃ]の}[人|ひと]が[来|き]ました。","explain":"父の会社の人 is someone from father's company. 人が is the one who came, うちに is where they came to, and 先週 needs the past: 来ました."}],"exam":[{"id":"n5u03d6.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きのう　デパートへ　行きましたが、何も　（　　）。","options":["買いましょう","買いませんでした","買いました","買いませんか"],"answer":2,"explain":"何も with a negative means \"nothing\", and きのう needs the past: 何も買いませんでした. 買いました is not negative, so it does not go with 何も. 買いませんか invites and 買いましょう suggests; neither fits a story about yesterday."},{"id":"n5u03d6.e2","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"A「日よう日、いっしょに　こうえん（　　）　テニスを　しませんか。」\nB「ええ、しましょう。」","options":["に","で","へ","を"],"answer":2,"explain":"The park is where you play tennis, so で: こうえんで　テニスを　します. へ marks where you go, with 行きます. を already marks テニス. に would need a verb like 行きます or あります."},{"id":"n5u03d6.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「きのう　ばんごはんは　どこで　食べましたか。」B「","after":"。」","tiles":["友だちの","うち","で","食べました"],"star":1,"bank":[2,0,3,1],"full":"A「きのう　ばんごはんは　どこで　食べましたか。」B「友だちの　{うち}で　食べました。」","explain":"友だちの, うち, で, 食べました. 友だちの needs a noun after it, うち. で follows the place where they ate, and the verb comes last in the past, like A's question."}]},"scene":{"ja":"学校のけいじばん","en":"The notice board at a language school","intro":"Tap each word on the notices pinned to the board in the hallway.","words":[{"id":"this-week","word":"今週","reading":"こんしゅう","gloss":"this week","parts":[["今","コン","now"],["週","シュウ","week"]],"clip":"s_n5u3d6_this_week"},{"id":"next-month","word":"来月","reading":"らいげつ","gloss":"next month","parts":[["来","ライ","come, next"],["月","ゲツ","month, moon"]],"clip":"s_n5u3d6_next_month"},{"id":"friday","word":"金よう日","reading":"きんようび","gloss":"Friday","parts":[["金","キン","gold, money"],["日","び","day"]],"clip":"s_n5u3d6_friday"},{"id":"teacher","word":"先生","reading":"せんせい","gloss":"teacher","parts":[["先","セン","ahead"],["生","セイ","life"]],"clip":"s_n5u3d6_teacher"},{"id":"student","word":"学生","reading":"がくせい","gloss":"student","parts":[["学","ガク","study"],["生","セイ","life"]],"clip":"s_n5u3d6_student"},{"id":"half9","word":"九時半","reading":"くじはん","gloss":"half past nine","parts":[["九","ク","nine"],["時","ジ","o'clock, time"],["半","ハン","half"]],"clip":"s_n5u3d6_half9"},{"id":"15min","word":"十五分","reading":"じゅうごふん","gloss":"fifteen minutes","parts":[["十","ジュウ","ten"],["五","ゴ","five"],["分","フン","minute"]],"clip":"s_n5u3d6_15min"},{"id":"break","word":"休み時間","reading":"やすみじかん","gloss":"break (between classes)","parts":[["休","やす","rest"],["時","ジ","time"],["間","カン","between, a space of time"]],"clip":"s_n5u3d6_break"}],"check":{"id":"n5u03d6.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"日本語の　クラスは　_九時半_に　はじまります。","options":["きゅうじぱん","くじはん","きゅうじはん","くじばん"],"answer":2,"explain":"九時半 is くじはん: nine o'clock is くじ, and 半 is はん. きゅうじ is not used for the time, and 半 does not change to ばん or ぱん after 時."}},"skill":{"kind":"reading","ja":"情報検索","en":"Finding information","ask":"What time do the students come to school on Friday?","seconds":90,"passage":"日本語クラス　今週の　よてい\n月よう日〜木よう日\n　午前九時〜十二時　クラス（201きょうしつ）\n^金よう日^\n　^午前は　休みです^。\n　^午後一時^〜三時半　中川先生と　えいがを　見ます（305きょうしつ）\n土よう日・日よう日　休み","strategy":"Find the line for 金よう日 and read only the times under it.","item":{"id":"n5u03d6.r1","kind":"choice","type":"読解・情報検索","q":"学生は　金よう日に　何時に　学校へ　来ますか。","options":["午前九時","十二時","午後一時","三時半"],"short":["9:00","12:00","1:00","3:30"],"answer":3,"explain":"Under 金よう日, the morning is 休み, and the film starts at 午後一時. So the students come at one in the afternoon.","why":["Nine o'clock is the start time from Monday to Thursday. On Friday the morning is off.","Twelve is when the Monday to Thursday class ends.","","Half past three is when the Friday film ends, not when students arrive."]}}}],"test":[{"id":"n5u03t.1","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"_先週_は　雨が　よく　ふりました。","options":["せいしゅう","せんしゅう","せんしゅ","さきしゅう"],"answer":2,"explain":"先週 is せんしゅう, last week. せんしゅ has a short しゅ in place of しゅう, so it is a different word. さきしゅう uses さき, the reading of 先 when it stands alone, and せいしゅう has せい in place of せん; neither is a word."},{"id":"n5u03t.2","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"よる　うちで　日本の　うたを　_聞きます_。","options":["おきます","ききます","かきます","いきます"],"answer":2,"explain":"聞きます is ききます, listen. かきます is 書きます (write), いきます is 行きます (go), and おきます is get up. None of them is read from 聞, and you listen to a song."},{"id":"n5u03t.3","kind":"choice","type":"表記","label":"Kanji spelling","q":"駅の　_きたぐち_で　友だちを　まちます。","options":["北日","東口","南口","北口"],"answer":4,"explain":"きたぐち is 北口: 北 (north) with 口 (exit). 北日 has 日 (day) in place of 口, and it is not a word. 東口 is ひがしぐち (east exit) and 南口 is みなみぐち (south exit); they are real words but not read きたぐち."},{"id":"n5u03t.4","kind":"choice","type":"表記","label":"Kanji spelling","q":"母に　てがみを　_かきます_。","options":["言きます","話きます","読きます","書きます"],"answer":4,"explain":"かきます (write) is 書きます. 言 is the い of 言います (say), 話 is the はな of 話します (speak), and 読 is the よ of 読みます (read). None of them is read か, so 言きます, 話きます and 読きます are not words."},{"id":"n5u03t.5","kind":"choice","type":"文脈規定","label":"Word in context","q":"駅で　電車に　（　　）。","options":["おります","かいます","よみます","のります"],"answer":4,"explain":"電車に goes with のります: get on the train. おります (get off) takes を or から, as in 電車をおります, not に. かいます (buy) and よみます (read) do not take 電車に, and you do not buy or read a train."},{"id":"n5u03t.6","kind":"choice","type":"文脈規定","label":"Word in context","q":"（　　）は　日よう日でした。あしたは　火よう日です。","options":["あさって","おととい","きのう","きょう"],"answer":3,"explain":"If tomorrow is Tuesday, today is Monday, so yesterday, きのう, was Sunday. おととい (the day before yesterday) was Saturday. きょう is Monday, and it does not go with the past でした. あさって (the day after tomorrow) is in the future, so it cannot take でした."},{"id":"n5u03t.7","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"_まいばん_　日本語の　本を　読みます。","options":["よるは　ときどき　日本語の　本を　読みます。","よるは　日本語の　本を　読みません。","あさは　いつも　日本語の　本を　読みます。","よるは　いつも　日本語の　本を　読みます。"],"answer":4,"explain":"まいばん means every evening, so it is the same as よるは いつも (in the evening, always). Option 3 says in the morning. Option 1 says only sometimes (ときどき). Option 2 says the person does not read in the evening."},{"id":"n5u03t.8","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"きょうは　_しごとを　休みます_。","options":["きょうは　会社で　はたらきます。","きょうは　会社に　います。","きょうは　会社へ　行きます。","きょうは　会社へ　行きません。"],"answer":4,"explain":"しごとを 休みます means taking the day off work, so the person does not go to the office: 会社へ 行きません. Option 3 says the opposite. Options 1 and 2 say the person works or is at the office today."},{"id":"n5u03t.9","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「パクさんは　おさけを　飲みますか。」B「いいえ、おさけは　（　　）。」","options":["飲みませんでした","飲みましょう","飲みます","飲みません"],"answer":4,"explain":"A asks about a habit with 飲みますか, and B says いいえ, so B answers with the polite no ending: 飲みません. 飲みます is a yes answer, which does not follow いいえ. 飲みませんでした is about one time in the past, but A did not ask about the past. 飲みましょう (let's drink) is a suggestion, not an answer about B's habit."},{"id":"n5u03t.10","kind":"choice","type":"文の文法1","label":"Choose the form","q":"けさは　じかんが　ありませんでしたから、あさごはんを　（　　）。","options":["食べませんでした","食べません","食べましょう","食べました"],"answer":1,"explain":"けさ (this morning) is past, and there was no time, so the person did not eat: 食べませんでした. 食べました says the person ate, which does not follow \"there was no time\". 食べません is not past, so it does not fit けさ. 食べましょう (let's eat) is a suggestion, not something that happened."},{"id":"n5u03t.11","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"きのう　としょかんで　本（　　）　二さつ　かりました。","options":["が","に","へ","を"],"answer":4,"explain":"本 is the thing you borrow, so it takes を: 本を かりました. が would make the book the one who borrows. に and へ mark a person or a place, not the thing you borrow."},{"id":"n5u03t.12","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"A「きのうは　何時に　うち（　　）　かえりましたか。」B「十時ごろです。」","options":["と","へ","を","で"],"answer":2,"explain":"うち is where you go back to, and the place you go to takes へ: うちへ かえりました. を does not mark the place you go back to. で marks where you do something, not where you go. と means \"with\", and you do not go home with your home."},{"id":"n5u03t.13","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"日よう日は　こうえん（　　）　友だちと　テニスを　しました。","options":["に","で","を","へ"],"answer":2,"explain":"The park is where they played tennis, and the place of an action takes で: こうえんで テニスを しました. に marks where something is (こうえんに 木が あります) or where you go, but しました is an action. を is already on テニス, and へ marks where you go, which does not fit しました."},{"id":"n5u03t.14","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"わたしは　毎日　じてんしゃ（　　）　駅まで　行きます。","options":["に","が","で","を"],"answer":3,"explain":"A bicycle is how the person goes, and the thing you use takes で: じてんしゃで 行きます. を would make the bicycle the thing you go, which does not make sense. に is for getting on (じてんしゃに のります), not with 行きます. が would make the bicycle the one who goes."},{"id":"n5u03t.15","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　りんご、おいしいですよ。一つ　食べ（　　）。」B「ありがとうございます。いただきます。」","options":["ませんか","ました","ませんでした","ましたか"],"answer":1,"explain":"B thanks A and says いただきます, so A is offering an apple: 食べませんか (won't you have one?). 食べました and 食べませんでした tell what A did, and B would not thank A for that. 食べましたか asks if B already ate one, and ありがとうございます is not an answer to that question."},{"id":"n5u03t.16","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「ケンさん、来週は　何を　しますか。」B「来週の　","after":"。」A「そうですか。いいですね。」","tiles":["土よう日に","国","へ","かえります"],"star":2,"bank":[3,2,0,1],"full":"A「ケンさん、来週は　何を　しますか。」B「来週の　土よう日に　国{へ}　かえります。」A「そうですか。いいですね。」","explain":"土よう日に, 国, へ, かえります. 来週の needs a noun after it, and only 土よう日 fits (来週の土よう日, Saturday next week). へ comes right after the place you go, 国, and the verb かえります ends the sentence."},{"id":"n5u03t.17","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「きれいな　しゃしんですね。」B「ありがとうございます。","after":"　とりました。」","tiles":["父","の","古い","カメラで"],"star":2,"bank":[2,3,1,0],"full":"A「きれいな　しゃしんですね。」B「ありがとうございます。父の　{古い}　カメラで　とりました。」","explain":"父, の, 古い, カメラで. 父の goes before the thing that is his, and 古い describes the camera, so it comes right before カメラで: my father's old camera. 古い cannot come before 父, because 古い is for things, not people. カメラで, with で for the thing you use, comes right before とりました."},{"id":"n5u03t.18","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「つかれましたね。あの　","after":"　少し　休みませんか。」B「ええ、そうしましょう。」","tiles":["大きい","木","の","下で"],"star":1,"bank":[3,1,0,2],"full":"A「つかれましたね。あの　大きい　{木}の　下で　少し　休みませんか。」B「ええ、そうしましょう。」","explain":"大きい, 木, の, 下で. 大きい describes 木 (that big tree). 木の下 is \"under the tree\", and 下で, with で for the place where you do something, goes before 休みませんか. 大きい cannot describe 下, so 木の大きい下 does not work."},{"id":"n5u03t.19","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"きのうは　日よう日でした。午前は　うちで　そうじを　しました。午後は　友だちと　電車で　こうえんへ　行きました。こうえんの　花は　とても　きれいでした。よるは　テレビを　見ませんでした。日本語の　本を　読みました。","q":"この　人は　きのうの　よる　何を　しましたか。","options":["そうじを　しました。","テレビを　見ました。","日本語の　本を　読みました。","友だちと　こうえんへ　行きました。"],"answer":3,"short":["そうじ","テレビ","日本語の本","こうえん"],"explain":"The writer says よるは テレビを 見ませんでした。日本語の 本を 読みました: in the evening the writer read a Japanese book. The cleaning was in the morning (午前). The writer did not watch TV (見ませんでした). The trip to the park with a friend was in the afternoon (午後)."},{"id":"n5u03t.20","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"きのうは　日よう日でした。午前は　うちで　そうじを　しました。午後は　友だちと　電車で　こうえんへ　行きました。こうえんの　花は　とても　きれいでした。よるは　テレビを　見ませんでした。日本語の　本を　読みました。","q":"ただしい　ものは　どれですか。","options":["ひとりで　こうえんへ　行きました。","バスで　こうえんへ　行きました。","こうえんの　花は　きれいじゃ　ありませんでした。","午前は　うちに　いました。"],"answer":4,"short":["ひとりで","バスで","花はきれいじゃない","午前はうち"],"explain":"The writer cleaned at home in the morning (午前は うちで そうじを しました), so the writer was at home. The writer went with a friend (友だちと), not alone, and by train (電車で), not by bus. The flowers were very pretty (とても きれいでした)."},{"id":"n5u03t.21","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"みどりセンター　土よう日の　クラス\n午前　十時から　十一時半まで　かんじ（二かい）\n午後　一時から　二時半まで　日本の　りょうり（一かい）\n午後　三時から　四時まで　日本の　うた（二かい）\nお金は　いりません。\n日よう日は　休みです。","q":"キムさんは　りょうりの　クラスに　行きます。何時に　何かいへ　行きますか。","options":["十時に　二かい","一時に　一かい","一時に　二かい","三時に　一かい"],"answer":2,"short":["十時 二かい","一時 一かい","一時 二かい","三時 一かい"],"explain":"The cooking class (日本の りょうり) is from 一時 on 一かい. 十時 on 二かい is the kanji class. 二かい is the floor of the kanji and song classes, not the cooking class. 三時 is when the song class starts."},{"id":"n5u03t.22","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"みどりセンター　土よう日の　クラス\n午前　十時から　十一時半まで　かんじ（二かい）\n午後　一時から　二時半まで　日本の　りょうり（一かい）\n午後　三時から　四時まで　日本の　うた（二かい）\nお金は　いりません。\n日よう日は　休みです。","q":"アンナさんは　土よう日の　午後　二時半から　ひまです。どの　クラスに　行きますか。","options":["うたの　クラス","日よう日の　クラス","かんじの　クラス","りょうりの　クラス"],"answer":1,"short":["うた","日よう日","かんじ","りょうり"],"explain":"From 二時半 the only class that has not started yet is the song class, from 三時 to 四時. The kanji class is in the morning, and the cooking class ends at 二時半. There is no Sunday class, because 日よう日は 休みです."},{"id":"n5u03t.23","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ケンさん\n来週の　土よう日に　こうえんで　テニスを　しませんか。わたしは　午前は　しごとが　ありますから、午後　一時から　しましょう。こうえんまでは　駅から　バスで　行きましょう。十二時半に　駅の　南口で　会いましょう。\nたなか","q":"二人は　土よう日、何時に　どこで　会いますか。","options":["十二時半に　駅の　南口で","一時に　駅の　南口で","十二時半に　こうえんで","一時に　こうえんで"],"answer":1,"short":["十二時半 南口","一時 南口","十二時半 こうえん","一時 こうえん"],"explain":"たなか writes 十二時半に 駅の 南口で 会いましょう. 一時 is when the tennis starts, not when they meet. They meet at the station and then go to the park by bus, so they do not meet at the park."},{"id":"n5u03t.24","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ケンさん\n来週の　土よう日に　こうえんで　テニスを　しませんか。わたしは　午前は　しごとが　ありますから、午後　一時から　しましょう。こうえんまでは　駅から　バスで　行きましょう。十二時半に　駅の　南口で　会いましょう。\nたなか","q":"ただしい　ものは　どれですか。","options":["たなかさんは　土よう日の　午前　しごとが　あります。","二人は　こうえんの　入口で　会います。","テニスは　午前からです。","二人は　こうえんまで　あるいて　行きます。"],"answer":1,"short":["午前にしごと","こうえんの入口","テニスは午前","あるいて行く"],"explain":"たなか writes 午前は しごとが あります: there is work on Saturday morning. That is why the tennis is in the afternoon (午後 一時から), not the morning. They go to the park by bus (バスで), not on foot. They meet at the station's south exit (駅の 南口), not at the park entrance."}]},{"n":4,"ja":"形容詞","en":"Describing things","days":[{"title":"い形容詞・な形容詞","grammar":{"points":[{"id":"n5u04d1.p1","form":"〜いです・〜くないです","gloss":"is ~, is not ~ (い-adjectives)","connect":[{"pos":"い-adjective, yes: add です","rule":"[大|おお]きい{です}"},{"pos":"い-adjective, no: change the last い to く, then add ないです","rule":"[大|おお]きい → [大|おお]き{くないです}"},{"pos":"Before a noun (〜): the adjective as it is","rule":"{[大|おお]きい} ＋ 〜"}],"examples":[{"ja":"このアパートは[新|あたら]しい{です}。","en":"This apartment is new.","clip":"x_n5u04d1_p1_1"},{"ja":"このへやは[高|たか]{くないです}。","en":"This room is not expensive.","clip":"x_n5u04d1_p1_2"}],"watch":{"note":"いい is special. Its no form is よくないです, not いくないです.","bad":"このへやはあまりいくないです。","good":"このへやはあまりよくないです。"}},{"id":"n5u04d1.p2","form":"〜です・〜じゃありません","gloss":"is ~, is not ~ (な-adjectives)","connect":[{"pos":"な-adjective, yes: add です","rule":"しずか{です}"},{"pos":"な-adjective, no: add じゃありません","rule":"しずか{じゃありません}"},{"pos":"Before a noun (〜): add な","rule":"しずか{な} ＋ 〜"}],"examples":[{"ja":"ここはしずか{な}へやです。","en":"This is a quiet room.","clip":"x_n5u04d1_p2_1"},{"ja":"[駅|えき]の[前|まえ]はしずか{じゃありません}。","en":"The area in front of the station is not quiet.","clip":"x_n5u04d1_p2_2"}],"watch":{"note":"きれい and きらい end in い, but they are な-adjectives. Their no form is きれいじゃありません and きらいじゃありません, never きれくないです.","bad":"このへやはきれくないです。","good":"このへやはきれいじゃありません。"}}],"compare":{"intro":"Before a noun, an い-adjective joins it as it is, a な-adjective adds な, and a noun adds の, as you saw in unit 1.","forms":[{"form":"〜い＋〜","tag":"大きい本 · a big book (い-adjective)","mark":"dot","ja":"[大|おお]き{い}[本|ほん]です。","en":"It is a big book."},{"form":"〜な＋〜","tag":"しずかなへや · a quiet room (な-adjective)","mark":"dot","ja":"しずか{な}へやです。","en":"It is a quiet room."},{"form":"〜の＋〜","tag":"日本の本 · a book from Japan (noun)","mark":"dot","ja":"[日本|にほん]{の}[本|ほん]です。","en":"It is a book from Japan."}],"check":{"id":"n5u04d1.c1","kind":"choice","type":"文の文法1","label":"へやのはなし","q":"A「このへや、どうですか。」\nB「（　　）ですね。」","options":["きれいなへや","きれいへや","きれいのへや"],"answer":1,"why":["きれい is a な-adjective, so it takes な before the noun へや.","きれい ends in い, but it is a な-adjective, not an い-adjective. It cannot join へや as it is.","の joins a noun to a noun. きれい is a な-adjective, so it takes な."]}},"drill":[{"id":"n5u04d1.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「そのへやは[大|おお]きいですか。」\nB「^いいえ^、あまり（　　）。」","options":["[大|おお]きいです","[大|おお]きくないです","[大|おお]きいじゃありません","[大|おお]きくです"],"answer":2,"why":["B starts with いいえ, and あまり in the sense \"not very\" goes with a no ending. 大きいです is the yes form.","大きい is an い-adjective: the last い becomes く, then ないです. B says it is not very big.","じゃありません is the no ending for a noun or a な-adjective. 大きい is an い-adjective, so it becomes 大きくないです.","大きく needs ない after it. 大きくです is not a form."]},{"id":"n5u04d1.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「[駅|えき]の[前|まえ]のレストランはどうですか。」\nB「^あまり^（　　）。[高|たか]いです。」","options":["いくないです","よくないです","いいじゃありません","いいです"],"answer":2,"why":["いい is special: its no form is よくないです. いくないです is not a form.","B is not happy with the restaurant: あまりよくないです, it is not very good. The no form of いい is よくないです.","じゃありません is for a noun or a な-adjective. いい is an い-adjective, and its no form is よくないです.","あまり in the sense \"not very\" goes with a no ending, and B goes on to say it is expensive."],"explain":null},{"id":"n5u04d1.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「[中山|なかやま]さんのへやはしずかですか。」\nB「^いいえ^、（　　）。」","options":["しずかじゃありません","しずかないです","しずかです","しずかくないです"],"answer":1,"why":["しずか is a な-adjective, so the no form is しずかじゃありません.","しずかないです is not a form. A な-adjective takes じゃありません.","しずかです means yes, it is quiet. B starts with いいえ.","くないです is the no ending for an い-adjective. しずか is a な-adjective, so it takes じゃありません."],"explain":null},{"id":"n5u04d1.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[駅|えき]のちかくに^しずか^（　　）こうえんがあります。","options":["い","です","な","の"],"answer":3,"why":["しずか is a な-adjective. It has no い, so しずかい is not a word.","です ends a sentence. It does not come between しずか and the noun こうえん.","しずか is a な-adjective, so it takes な before the noun こうえん.","の joins a noun to a noun. しずか is a な-adjective, so it takes な."],"explain":null},{"id":"n5u04d1.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[駅|えき]の[前|まえ]に","after":"。","tiles":["[新|あたら]しい","[店|みせ]","が","あります"],"star":1,"bank":[2,0,3,1],"hint":"The い-adjective goes right before the noun it describes. Then が and the verb.","full":"[駅|えき]の[前|まえ]に{[新|あたら]しい}[店|みせ]があります。","explain":"新しい is an い-adjective, so it goes right before 店 with nothing between them. が marks the thing that is there, and あります ends the sentence."},{"id":"n5u04d1.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"このへやは","after":"。","tiles":["あまり","しずか","じゃ","ありません"],"star":1,"bank":[3,1,0,2],"hint":"あまり comes before the describing word. The no ending comes last.","full":"このへやはあまりしずか{じゃありません}。","explain":"あまり goes before しずか: not very quiet. しずか is a な-adjective, so its no ending じゃありません follows it at the end."}],"exam":[{"id":"n5u04d1.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「その　カメラ、高いですか。」\nB「いいえ、あまり　（　　）。」","options":["高くないです","高くないですか","高いです","高いじゃありません"],"answer":1,"explain":"B says いいえ, and あまり in the sense \"not very\" goes with a no ending. 高い is an い-adjective, so it becomes 高くないです. 高いです is the yes form. じゃありません is for a noun or a な-adjective, not an い-adjective. 高くないですか is a question, but B is answering."},{"id":"n5u04d1.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「中山さんの　へやは　きれいですか。」\nB「いいえ、あまり　（　　）。」","options":["きれいじゃありません","きれくないです","きれいくないです","きれいです"],"answer":1,"explain":"きれい ends in い, but it is a な-adjective, so its no form is きれいじゃありません. B says いいえ and あまり, so the yes form きれいです does not fit. きれくないです and きれいくないです treat きれい as an い-adjective, which it is not."},{"id":"n5u04d1.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"山川さんは　","after":"です。","tiles":["とても","きれい","な","人"],"star":1,"bank":[2,3,0,1],"full":"山川さんは　とても　きれい{な}人です。","explain":"とても, きれい, な, 人. とても goes before the describing word: very pretty. きれい is a な-adjective, so な joins it to the noun 人. Ms. Yamakawa is a very pretty person."}]},"scene":{"ja":"アパートのはりがみ","en":"A room-for-rent notice","intro":"Tap each word on the notice for a room for rent in the window of a small apartment office.","words":[{"id":"station","word":"駅","reading":"えき","gloss":"station","parts":[["駅","エキ","station"]],"clip":"s_n5u4d1_station"},{"id":"north-exit","word":"北口","reading":"きたぐち","gloss":"north exit","parts":[["北","きた","north"],["口","ぐち","mouth, opening"]],"clip":"s_n5u4d1_north_exit"},{"id":"five-minutes","word":"五分","reading":"ごふん","gloss":"five minutes","parts":[["五","ゴ","five"],["分","フン","minute"]],"clip":"s_n5u4d1_five_minutes"},{"id":"new","word":"新しい","reading":"あたらしい","gloss":"new","parts":[["新","あたら","new"]],"clip":"s_n5u4d1_new"},{"id":"big","word":"大きい","reading":"おおきい","gloss":"big","parts":[["大","おお","big"]],"clip":"s_n5u4d1_big"},{"id":"cheap","word":"安い","reading":"やすい","gloss":"cheap","parts":[["安","やす","cheap"]],"clip":"s_n5u4d1_cheap"},{"id":"every-month","word":"毎月","reading":"まいつき","gloss":"every month","parts":[["毎","マイ","every"],["月","つき","month"]],"clip":"s_n5u4d1_every_month"},{"id":"fifty-thousand-yen","word":"五万円","reading":"ごまんえん","gloss":"50,000 yen","parts":[["五","ゴ","five"],["万","マン","ten thousand"],["円","エン","yen"]],"clip":"s_n5u4d1_fifty_thousand_yen"}],"check":{"id":"n5u04d1.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"この　アパートは　_新しい_です。","options":["あらたしい","あたしい","あたらしい","しんしい"],"answer":3,"explain":"新しい is あたらしい. あらたしい swaps two sounds, あたしい drops ら, and しんしい uses シン, another reading of 新, but 新しい is never read that way."}},"skill":{"kind":"listening","ja":"発話表現","en":"Expressions","situation":"On a sunny summer day, a man wiping sweat from his face meets a friend in the street.","ask":"友だちに　あいました。何と　いいますか。","item":{"id":"n5u04d1.r1","kind":"choice","type":"発話表現","q":"友だちに　あいました。何と　いいますか。","script":["ナレーター：友だちに　あいました。何と　いいますか。","ナレーター：1","男：きょうは　さむいですね。","ナレーター：2","男：きょうは　あついですね。","ナレーター：3","男：きょうは　あつくないですね。"],"options":["きょうは　さむいですね。","きょうは　あついですね。","きょうは　あつくないですね。"],"printed":false,"short":["さむいですね","あついですね","あつくないですね"],"answer":2,"why":["さむい means cold. It is a sunny summer day and he is wiping sweat.","","あつくないです means it is not hot. The man is sweating, so it is hot."],"clip":"l_n5u4d1"},"audio":[["N","友だちに　あいました。何と　いいますか。","ともだちに　あいました。なんと　いいますか。"],["N","1","いち"],["M","きょうは　さむいですね。",null],["N","2","に"],["M","きょうは　あついですね。",null],["N","3","さん"],["M","きょうは　あつくないですね。",null]]}},{"title":"〜かったです・〜でした","grammar":{"points":[{"id":"n5u04d2.p1","form":"〜かったです／〜くなかったです","gloss":"was / was not (い-adjectives)","connect":[{"pos":"い-adjective","rule":"〜い → 〜{かったです}"},{"pos":"い-adjective, not","rule":"〜い → 〜{くなかったです}"},{"pos":"いい (good)","rule":"いい → {よかったです}／{よくなかったです}"}],"examples":[{"ja":"きのうは、とてもさむ{かったです}。","en":"It was very cold yesterday.","clip":"x_n5u04d2_p1_1"},{"ja":"[先週|せんしゅう]の[天気|てんき]は、あまりよ{くなかったです}。","en":"The weather last week was not very good.","clip":"x_n5u04d2_p1_2"}],"watch":{"note":"An い-adjective changes itself for the past: 大きい becomes 大きかったです. Do not put でした after it. For いい, the past is よかったです, not いかったです.","bad":"その店は大きいでした。","good":"その店は大きかったです。"}},{"id":"n5u04d2.p2","form":"〜でした／〜じゃありませんでした","gloss":"was / was not (な-adjectives, nouns)","connect":[{"pos":"な-adjective (without な)","rule":"〜{でした}"},{"pos":"Noun","rule":"〜{でした}"},{"pos":"Not (both)","rule":"〜{じゃありませんでした}"}],"examples":[{"ja":"[先週|せんしゅう]の[日|にち]よう[日|び]は[雨|あめ]{でした}。","en":"Last Sunday it rained. (It was rain.)","clip":"x_n5u04d2_p2_1"},{"ja":"きのうのこうえんは、あまりしずか{じゃありませんでした}。","en":"The park was not very quiet yesterday.","clip":"x_n5u04d2_p2_2"}],"watch":{"note":"きれい ends in い, but it is a な-adjective. Use でした, as with しずか: きれいでした. Do not change it like an い-adjective.","bad":"花はとてもきれいかったです。","good":"花はとてもきれいでした。"}}],"compare":{"intro":"All three describe something politely. The time and the kind of word decide the ending.","forms":[{"form":"〜かったです","tag":"い・かこ · was (い-adjective)","mark":"dot","ja":"きのうはさむ{かったです}。","en":"It was cold yesterday."},{"form":"〜でした","tag":"な・めいし・かこ · was (な-adjective, noun)","mark":"dot","ja":"きのうはしずか{でした}。","en":"It was quiet yesterday."},{"form":"〜いです","tag":"いま · is (now)","mark":"dot","ja":"きょうはさむ{いです}。","en":"It is cold today."}],"check":{"id":"n5u04d2.c1","kind":"choice","type":"文の文法1","label":"きのうのテスト","q":"A：きのうのテストはどうでしたか。B：（　　）。","options":["やさしかったです","やさしいでした","やさしいです"],"answer":1,"why":["The test was yesterday, and やさしい is an い-adjective: the past is やさしかったです.","やさしい is an い-adjective. It changes itself for the past; でした does not go after it.","やさしいです is about now. A asks どうでしたか about yesterday's test."]}},"drill":[{"id":"n5u04d2.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^きのう^は、とてもさむ（　　）。","options":["いでした","かったです","かったでした","いです"],"answer":2,"why":["さむい is an い-adjective. でした does not go after it.","きのう is the past, and さむい is an い-adjective: さむかったです.","かった already makes the past. Add only です, not でした.","さむいです is about now. きのう points to the past."],"explain":null},{"id":"n5u04d2.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：きのうのえいがは、どうでしたか。B：^とても^（　　）。","options":["いいでした","よかったです","いかったです","よくなかったです"],"answer":2,"why":["いい is an い-adjective. でした does not go after it.","The past of いい is よかったです. とても よかったです means \"it was very good\".","いい changes to よ in the past: よかったです. いかったです is not a word.","とても goes with a yes form here. For \"not very good\" you say あまりよくなかったです."]},{"id":"n5u04d2.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^[先週|せんしゅう]の[土|ど]よう[日|び]^は、[雨|あめ]（　　）。","options":["かったです","じゃありません","です","でした"],"answer":4,"why":["かったです is only for い-adjectives. 雨 is a noun.","じゃありません is not past, and it says it was not rain. For last Saturday you need a past form.","雨です is about now. 先週の土よう日 is in the past.","雨 is a noun, and last Saturday is past: 雨でした."],"explain":null},{"id":"n5u04d2.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：きのうのこうえんは、しずかでしたか。B：^いいえ^、あまり（　　）。","options":["しずかじゃありませんでした","しずかくなかったです","しずかじゃありません","しずかでした"],"answer":1,"why":["いいえ to a question about yesterday, and しずか is a な-adjective: しずかじゃありませんでした.","しずか is a な-adjective. くなかったです is only for い-adjectives.","じゃありません is not past. The question is about yesterday, so add でした.","しずかでした means \"it was quiet\". It clashes with いいえ and あまり."],"explain":null},{"id":"n5u04d2.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"この","after":"。","tiles":["[店|みせ]の","ケーキは","あまり","おいしくなかったです"],"star":2,"bank":[2,3,0,1],"hint":"この needs a noun right after it. あまり goes just before the not form.","full":"この[店|みせ]のケーキはあまりおいし{くなかったです}。","explain":"この店の describes ケーキ, and ケーキは is the topic. あまり (not very) comes before おいしくなかったです, the past not form of おいしい."},{"id":"n5u04d2.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[駅|えき]の[前|まえ]の","after":"。","tiles":["[店|みせ]は","あまり","きれい","じゃありませんでした"],"star":2,"bank":[3,1,0,2],"hint":"駅の前の needs a noun right after it. きれい is a な-adjective.","full":"[駅|えき]の[前|まえ]の[店|みせ]はあまりきれい{じゃありませんでした}。","explain":"駅の前の describes 店, the topic. あまり comes before the adjective, and きれい takes じゃありませんでした because it is a な-adjective."}],"exam":[{"id":"n5u04d2.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きのうは　天気が　（　　）。","options":["いいです","いいでした","よかったです","いかったです"],"answer":3,"explain":"きのう is the past, and the past of いい is よかったです. いいでした puts でした after an い-adjective, いかったです is not a word, and いいです is about now."},{"id":"n5u04d2.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：先週の　パーティーは　どうでしたか。B：とても　（　　）。","options":["にぎやかじゃありませんでした","にぎやかでした","にぎやかかったです","にぎやかいでした"],"answer":2,"explain":"にぎやか is a な-adjective, and the party was last week: にぎやかでした. かったです is only for い-adjectives, にぎやかい is not a word, and とても does not go with じゃありませんでした (say あまり for \"not very\")."},{"id":"n5u04d2.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"日よう日は　","after":"。","tiles":["とても","いい","天気","でした"],"star":2,"bank":[2,0,3,1],"full":"日よう日は　とても　いい　{天気}でした。","explain":"とても, いい, 天気, でした. とても describes いい, いい describes 天気, and 天気 is a noun, so でした comes after it."}]},"scene":{"ja":"先週の天気","en":"A weather board for last week","intro":"Tap every word you can find on the weather board.","words":[{"id":"weather","word":"天気","reading":"てんき","gloss":"weather","parts":[["天","テン","sky, heaven"],["気","キ","air, spirit"]],"clip":"s_n5u4d2_weather"},{"id":"saturday","word":"土よう日","reading":"どようび","gloss":"Saturday","parts":[["土","ド","earth"],["日","び","day"]],"clip":"s_n5u4d2_saturday"},{"id":"pm","word":"午後","reading":"ごご","gloss":"afternoon, p.m.","parts":[["午","ゴ","noon"],["後","ゴ","after"]],"clip":"s_n5u4d2_pm"},{"id":"rain","word":"雨","reading":"あめ","gloss":"rain","parts":[["雨","あめ","rain"]],"clip":"s_n5u4d2_rain"},{"id":"sky","word":"空","reading":"そら","gloss":"sky","parts":[["空","そら","sky"]],"clip":"s_n5u4d2_sky"},{"id":"white","word":"白い","reading":"しろい","gloss":"white","parts":[["白","しろ","white"]],"clip":"s_n5u4d2_white"},{"id":"high","word":"高い","reading":"たかい","gloss":"high","parts":[["高","たか","high"]],"clip":"s_n5u4d2_high"},{"id":"temp","word":"十八ど","reading":"じゅうはちど","gloss":"18 degrees","parts":[["十","ジュウ","ten"],["八","ハチ","eight"]],"clip":"s_n5u4d2_temp"}],"check":{"id":"n5u04d2.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"きのうは　_天気_が　よかったです。","options":["てんぎ","てんき","でんき","てんけ"],"answer":2,"explain":"天気 is read てんき. でんき is a different word (電気, electricity), and てんけ and てんぎ are not readings of 天気."}},"skill":{"kind":"reading","ja":"内容理解（短文）","en":"Short passage","ask":"How was the writer's trip? What was good, and what was not?","seconds":90,"passage":"山川さん、先週の　土よう日に　母と　山へ　行きました。^午前は　雨でした^。でも、^午後は　空が　とても　きれいでした^。山の　上の　店で　魚を　食べました。^とても　おいしかったです^。^ホテルは　ちょっと　高かったです^が、きれいでした。","strategy":"Look at the ending after each thing: 〜かったです and 〜でした say how it was, 〜くなかったです and 〜じゃありませんでした say how it was not.","item":{"id":"n5u04d2.r1","kind":"choice","type":"読解・内容理解（短文）","q":"この　人に　ついて、ただしい　ものは　どれですか。","options":["魚は　あまり　おいしくなかったです。","ホテルは　高くなかったです。","土よう日は　午後も　雨でした。","午後は　空が　きれいでした。"],"short":["魚はおいしくなかった","ホテルは高くなかった","午後も雨だった","午後は空がきれいだった"],"answer":4,"explain":"Rain was only in the morning (午前は雨でした). でも, in the afternoon the sky was very pretty (午後は空がとてもきれいでした).","why":["The writer says the fish was とてもおいしかったです (very good).","The writer says the hotel was ちょっと高かったです (a little expensive).","Only the morning was rainy. In the afternoon the sky was pretty.",""]}}},{"title":"〜くて・〜で","grammar":{"points":[{"id":"n5u04d3.p1","form":"〜くて","gloss":"…and (joining an い-adjective)","connect":[{"pos":"い-adjective (drop the last い)","rule":"[安|やす]い → [安|やす]{くて}／[大|おお]きい → [大|おお]き{くて}"},{"pos":"いい (good) changes to よ","rule":"いい → {よくて}"}],"examples":[{"ja":"この[店|みせ]は[安|やす]{くて}おいしいです。","en":"This restaurant is cheap and the food is good.","clip":"x_n5u04d3_p1_1"},{"ja":"きょうは[天気|てんき]が{よくて}、あたたかいです。","en":"The weather is good today, and it is warm.","clip":"x_n5u04d3_p1_2"}],"watch":{"note":"An い-adjective drops its last い and adds くて. It never joins with で. いい becomes よくて.","bad":"このパンは安いでおいしいです。","good":"このパンは安くておいしいです。"}},{"id":"n5u04d3.p2","form":"〜で","gloss":"…and (joining a な-adjective or a noun)","connect":[{"pos":"な-adjective (no な before で)","rule":"しずか{で}／きれい{で}"},{"pos":"Noun (〜 is a noun such as 学生)","rule":"〜{で}、〜です"}],"examples":[{"ja":"このへやはしずか{で}きれいです。","en":"This room is quiet and clean.","clip":"x_n5u04d3_p2_1"},{"ja":"わたしは[学生|がくせい]{で}、[二十|にじゅっ]さいです。","en":"I am a student, and I am twenty.","clip":"x_n5u04d3_p2_2"}],"watch":{"note":"きれい ends in い, but it is a な-adjective. It takes で, not くて.","bad":"このこうえんはきれいくてしずかです。","good":"このこうえんはきれいでしずかです。"}}],"compare":{"intro":"All three use a describing word. くて and で join it to more words; な puts it right before a noun.","forms":[{"form":"〜くて","tag":"〜い → 〜くて · い-adjective, and…","mark":"dot","ja":"このりんごは[安|やす]{くて}[大|おお]きいです。","en":"These apples are cheap and big."},{"form":"〜で","tag":"〜な → 〜で · な-adjective or noun, and…","mark":"dot","ja":"このへやはしずか{で}ひろいです。","en":"This room is quiet and large."},{"form":"〜な〜","tag":"〜な＋〜 · right before a noun","mark":"dot","ja":"しずか{な}へやです。","en":"It is a quiet room."}],"check":{"id":"n5u04d3.c1","kind":"choice","type":"文の文法1","label":"レストランで","q":"あのレストランはきれい（　　）おいしいです。","options":["な","くて","で"],"answer":3,"why":["な goes right before a noun. おいしい is not a noun.","きれい ends in い, but it is a な-adjective, so きれいくて is wrong.","きれい is a な-adjective, and で joins it to おいしい."],"explain":null}},"drill":[{"id":"n5u04d3.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この[魚|さかな]は（　　）^おいしいです^。","options":["[安|やす]いで","[安|やす]くて","[安|やす]い","[安|やす]いくて"],"answer":2,"why":["安い is an い-adjective. い-adjectives never join with で.","安い drops its い and adds くて to join おいしい.","Two describing words cannot just sit side by side here. 安い needs to change to 安くて.","Drop the い first: 安くて, not 安いくて."]},{"id":"n5u04d3.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この[店|みせ]は（　　）^しずかです^。","options":["きれいだ","きれいくて","きれいな","きれいで"],"answer":4,"why":["だ ends a sentence. It cannot join きれい to しずかです.","きれい is a な-adjective, even though it ends in い. It does not take くて.","な goes right before a noun. しずか is not a noun.","きれい is a な-adjective, and で joins it to しずかです."],"explain":null},{"id":"n5u04d3.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"マリアさんは^かいしゃいん^（　　）、[三十|さんじゅっ]さいです。","options":["で","な","の","くて"],"answer":1,"why":["かいしゃいん is a noun, and で joins it to the next part: \"she is an office worker and thirty\".","かいしゃいん is a noun. A noun does not take な.","の joins two nouns as \"the X's Y\". It cannot end the first part before the comma.","くて is only for い-adjectives. かいしゃいん is a noun."],"explain":null},{"id":"n5u04d3.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きょうは[天気|てんき]が（　　）、^きもちがいいです^。","options":["よくて","いいくて","いいで","いくて"],"answer":1,"why":["いい changes to よ before くて: よくて.","いい does not keep いい before くて. It becomes よくて.","いい is an い-adjective, so it never joins with で.","いくて is not a form of いい. いい becomes よくて."]},{"id":"n5u04d3.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[駅|えき]の[前|まえ]に","after":"があります。","tiles":["[新|あたら]しくて","きれいな","パン","や"],"star":1,"bank":[2,0,3,1],"hint":"新しくて needs another describing word after it. Which word is the shop?","full":"[駅|えき]の[前|まえ]に[新|あたら]しくてきれいなパンやがあります。","explain":"新しくて joins to the next describing word, きれいな. きれいな goes right before the noun パンや, \"bakery\": 駅の前に新しくてきれいなパンやがあります, \"There is a new, nice bakery in front of the station.\""},{"id":"n5u04d3.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あした、[友|とも]だちと","after":"へ[行|い]きます。","tiles":["きれい","で","[新|あたら]しい","レストラン"],"star":1,"bank":[3,1,0,2],"hint":"で comes right after a な-adjective. The place you go to comes right before へ.","full":"あした、[友|とも]だちときれい{で}[新|あたら]しいレストランへ[行|い]きます。","explain":"きれい is a な-adjective, so で follows it. 新しい goes right before レストラン, the place before へ: \"Tomorrow I am going to a nice, new restaurant with a friend.\""}],"exam":[{"id":"n5u04d3.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：新しい　先生は　どんな　人ですか。　B：とても　（　　）　おもしろいですよ。","options":["げんきくて","げんきで","げんきな","げんきだ"],"answer":2,"explain":"げんき is a な-adjective, so it joins おもしろい with で. くて is only for い-adjectives, げんきな needs a noun right after it, and げんきだ cannot join two describing words."},{"id":"n5u04d3.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この　白い　セーターは　（　　）　あたたかいです。","options":["安いくて","安くて","安い","安いで"],"answer":2,"explain":"安い is an い-adjective: drop the い and add くて. い-adjectives never take で, 安いくて keeps the い, and 安い cannot sit right before another describing word ending the sentence."},{"id":"n5u04d3.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あの　パンやは","after":"です。","tiles":["パンが","おいしくて","店の人も","しんせつ"],"star":2,"bank":[3,0,2,1],"full":"あの　パンやは　パンが　おいしくて　{店の人も}　しんせつです。","explain":"パンが, おいしくて, 店の人も, しんせつ. おいしくて joins \"the bread is good\" to the next part, and しんせつ goes before です: \"At that bakery the bread is good, and the staff are kind too.\""}]},"scene":{"ja":"魚やで","en":"At a fish shop","intro":"Tap every word you would read on the price cards in the fish shop.","words":[{"id":"fish","word":"魚","reading":"さかな","gloss":"fish","parts":[["魚","さかな","fish"]],"clip":"s_n5u4d3_fish"},{"id":"new","word":"新しい","reading":"あたらしい","gloss":"new, fresh","parts":[["新","あたら","new"]],"clip":"s_n5u4d3_new"},{"id":"cheap","word":"安い","reading":"やすい","gloss":"cheap","parts":[["安","やす","cheap, calm"]],"clip":"s_n5u4d3_cheap"},{"id":"expensive","word":"高い","reading":"たかい","gloss":"expensive, high","parts":[["高","たか","high"]],"clip":"s_n5u4d3_expensive"},{"id":"big","word":"大きい","reading":"おおきい","gloss":"big","parts":[["大","おお","big"]],"clip":"s_n5u4d3_big"},{"id":"small","word":"小さい","reading":"ちいさい","gloss":"small","parts":[["小","ちい","small"]],"clip":"s_n5u4d3_small"},{"id":"half","word":"半分","reading":"はんぶん","gloss":"half","parts":[["半","ハン","half"],["分","ブン","part"]],"clip":"s_n5u4d3_half"},{"id":"100yen","word":"百円","reading":"ひゃくえん","gloss":"100 yen","parts":[["百","ヒャク","hundred"],["円","エン","yen, circle"]],"clip":"s_n5u4d3_100yen"}],"check":{"id":"n5u04d3.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"すみません、この　魚を　_半分_　ください。","options":["ばんぶん","はんぷん","はんぶん","はんふん"],"answer":3,"explain":"半分, \"half\", is read はんぶん. 分 is ふん or ぷん in times (五分, 十分), but in 半分 it is ぶん. はんふん, ばんぶん and はんぷん are not words."}},"skill":{"kind":"listening","ja":"ポイント理解","en":"Point comprehension","ask":"二人は　どの　店に　行きますか。","audio":[["N","男の人と女の人が話しています。二人はどの店に行きますか。","おとこのひとと　おんなのひとが　はなしています。ふたりは　どの　みせに　いきますか。"],["M","きょうのばんごはん、どこで食べますか。駅の前の新しい店はどうですか。","きょうの　ばんごはん、どこで　たべますか。えきの　まえの　あたらしい　みせは　どうですか。"],["F","あの店はきれいで、いいですね。でも、高いですよ。","あの　みせは　きれいで、いいですね。でも、たかいですよ。"],["M","そうですか。じゃあ、大学の前の店は？カレーが安くておいしいですよ。","そうですか。じゃあ、だいがくの　まえの　みせは？カレーが　やすくて　おいしいですよ。"],["F","うーん、きのうもカレーを食べました。","うーん、きのうも　カレーを　たべました。"],["M","じゃあ、川のそばの店はどうですか。しずかで、魚がおいしいですよ。","じゃあ、かわの　そばの　みせは　どうですか。しずかで、さかなが　おいしいですよ。"],["F","魚、いいですね。高いですか。","さかな、いいですね。たかいですか。"],["M","いいえ、あまり高くないです。","いいえ、あまり　たかくないです。"],["F","じゃあ、そこへ行きましょう。",null],["N","二人はどの店に行きますか。","ふたりは　どの　みせに　いきますか。"]],"item":{"id":"n5u04d3.r1","kind":"choice","type":"ポイント理解","q":"二人は　どの　店に　行きますか。","script":["ナレーター：男の人と女の人が話しています。二人はどの店に行きますか。","男：きょうのばんごはん、どこで食べますか。駅の前の新しい店はどうですか。","女：あの店はきれいで、いいですね。でも、高いですよ。","男：そうですか。じゃあ、大学の前の店は？カレーが安くておいしいですよ。","女：うーん、きのうもカレーを食べました。","男：じゃあ、川のそばの店はどうですか。しずかで、魚がおいしいですよ。","女：魚、いいですね。高いですか。","男：いいえ、あまり高くないです。","女：じゃあ、そこへ行きましょう。","ナレーター：二人はどの店に行きますか。"],"options":["大きくて　にぎやかな　店","しずかで　魚が　おいしい　店","カレーが　安くて　おいしい　店","新しくて　きれいな　店"],"printed":true,"short":["大きくて にぎやか","しずかで 魚が おいしい","カレーが 安くて おいしい","新しくて きれい"],"answer":2,"why":["Nobody talks about a big, lively shop.","The shop by the river is quiet and the fish is good, and it is not very expensive. The woman says そこへ行きましょう.","The curry is cheap and good, but the woman ate curry yesterday too (きのうもカレーを食べました).","The woman likes the new shop by the station (きれいで、いいですね), but it is expensive (でも、高いですよ)."],"explain":null,"clip":"l_n5u4d3"}}},{"title":"〜が好き・〜が上手","grammar":{"points":[{"id":"n5u04d4.p1","form":"〜がすきです／きらいです","gloss":"like, dislike","connect":[{"pos":"Noun (the thing you like)","rule":"〜 ＋ {がすきです}"},{"pos":"Noun (the thing you dislike)","rule":"〜 ＋ {がきらいです}"},{"pos":"The person first, with は, then the thing","rule":"〜 ＋ は ＋ 〜 ＋ {がすきです}"}],"examples":[{"ja":"わたしは[花|はな]{がすきです}。","en":"I like flowers.","clip":"x_n5u04d4_p1_1"},{"ja":"[父|ちち]はねこ{がきらいです}。","en":"My father doesn't like cats.","clip":"x_n5u04d4_p1_2"}],"watch":{"note":"With すきです and きらいです, the thing you like or dislike takes が, not を.","bad":"わたしはサッカーをすきです。","good":"わたしはサッカーがすきです。"}},{"id":"n5u04d4.p2","form":"〜がじょうずです／へたです","gloss":"good at, bad at","connect":[{"pos":"Noun (a skill, like a sport or a language)","rule":"〜 ＋ {がじょうずです}"},{"pos":"Noun (a skill)","rule":"〜 ＋ {がへたです}"},{"pos":"The person first, with は, then the skill","rule":"〜 ＋ は ＋ 〜 ＋ {がじょうずです}"}],"examples":[{"ja":"リンさんは[日本語|にほんご]{がじょうずです}。","en":"Lin is good at Japanese.","clip":"x_n5u04d4_p2_1"},{"ja":"[母|はは]はうた{がへたです}。","en":"My mother is bad at singing.","clip":"x_n5u04d4_p2_2"}],"watch":{"note":"じょうず is praise for someone else. Saying it about yourself sounds like bragging. About yourself, say へたです or あまりじょうずじゃありません.","bad":"わたしはりょうりがじょうずです。","good":"わたしはりょうりがあまりじょうずじゃありません。"}}],"compare":{"intro":"すきです and じょうずです take が for the thing. An action verb like します takes を.","forms":[{"form":"〜がすきです","tag":"すき · like","mark":"dot","ja":"わたしは[山|やま]{がすきです}。","en":"I like mountains."},{"form":"〜がじょうずです","tag":"よくできる · good at","mark":"up","ja":"[川口|かわぐち]さんはテニス{がじょうずです}。","en":"Mr. Kawaguchi is good at tennis."},{"form":"〜をします","tag":"すること · doing it","mark":"dot","ja":"[毎週|まいしゅう]テニス{を}します。","en":"I play tennis every week."}],"check":{"id":"n5u04d4.c1","kind":"choice","type":"文の文法1","label":"テニスクラブ","q":"わたしはテニス（　　）^すきです^。[毎週|まいしゅう][土|ど]よう[日|び]にします。","options":["を","が","に"],"answer":2,"why":["With すきです, the thing you like takes が. テニスを goes with a verb like します.","The thing you like takes が before すきです.","テニスに does not say what you like."]}},"drill":[{"id":"n5u04d4.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしはさむい[日|ひ]（　　）^きらいです^。","options":["に","を","が","で"],"answer":3,"why":["さむい日に would mean \"on cold days\", but then nothing says what you dislike.","With きらいです, the thing you dislike takes が, not を.","The thing you dislike takes が before きらいです: cold days.","さむい日で does not say what you dislike."],"explain":null},{"id":"n5u04d4.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしはやさいが（　　）。^だから、あまり[食|た]べません^。","options":["すきです","きらいです","じょうずです","へたです"],"answer":2,"why":["If you liked vegetables, you would not say あまり食べません.","You don't like vegetables, so you don't eat them much.","じょうず is for a skill. Vegetables are not a skill.","へた is for a skill too. Vegetables are not a skill."]},{"id":"n5u04d4.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしはえが（　　）。^ねこをかきましたが、[友|とも]だちは「いぬ？」と[言|い]いました^。","options":["へたいです","じょうずです","へたです","じょうずなです"],"answer":3,"why":["へた is not an い word, so へたいです is not a word. Say へたです.","A friend thought the cat was a dog, so the drawing was not good.","The cat looked like a dog: the writer is bad at drawing.","な is not used before です. Say じょうずです."],"explain":null},{"id":"n5u04d4.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[中山|なかやま]さんはテニス（　　）^[上手|じょうず]です^。","options":["で","が","へ","を"],"answer":2,"why":["テニスで would make tennis a tool or a way to do something.","The skill takes が before じょうずです: good at tennis.","へ shows a direction you go to.","With じょうずです, the skill takes が, not を."],"explain":null},{"id":"n5u04d4.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[母|はは]は","after":"。","tiles":["[雨|あめ]の","[日|ひ]","が","きらいです"],"star":2,"bank":[1,3,0,2],"hint":"の joins two nouns: what kind of day? Then the particle for what she dislikes.","full":"[母|はは]は[雨|あめ]の[日|ひ]{がきらいです}。","explain":"雨の日 is a rainy day. It is what she dislikes, so が comes next, and きらいです goes last."},{"id":"n5u04d4.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[父|ちち]は","after":"よ。","tiles":["[魚|さかな]の","りょうり","が","じょうずです"],"star":1,"bank":[2,3,1,0],"hint":"What kind of cooking? Then the particle for the skill, then the ending.","full":"[父|ちち]は[魚|さかな]のりょうり{がじょうずです}よ。","explain":"魚の describes りょうり: fish dishes. That is the skill, so が comes next, and じょうずです goes last, before よ."}],"exam":[{"id":"n5u04d4.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは　山（　　）　すきです。毎週　山へ　行きます。","options":["が","で","へ","を"],"answer":1,"explain":"The thing you like takes が before すきです: 山が すきです. を does not go with すきです, 山で would be a place where you do something, and へ shows a direction you go to."},{"id":"n5u04d4.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"リンさんは　えが　（　　）。リンさんの　えは　とても　きれいです。","options":["上手です","ひろいです","あまいです","下手です"],"answer":1,"explain":"Lin's pictures are very pretty, so Lin is good at drawing: 上手です. 下手です is the opposite. ひろい (wide) and あまい (sweet) do not describe a skill."},{"id":"n5u04d4.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「","after":"ですか。」　B「魚です。」","tiles":["どんな","食べもの","が","きらい"],"star":2,"bank":[3,1,0,2],"full":"A「どんな　食べもの{が}　きらいですか。」　B「魚です。」","explain":"どんな, 食べもの, が, きらい: what kind of food don't you like? どんな comes before the noun it asks about, the food you dislike takes が, and きらい joins ですか."}]},"scene":{"ja":"クラブのポスター","en":"School club posters","intro":"Tap each word on the club posters in the school hall.","words":[{"id":"weekly","word":"毎週","reading":"まいしゅう","gloss":"every week","parts":[["毎","マイ","every"],["週","シュウ","week"]],"clip":"s_n5u4d4_weekly"},{"id":"wednesday","word":"水よう日","reading":"すいようび","gloss":"Wednesday","parts":[["水","スイ","water"],["日","び","day"]],"clip":"s_n5u4d4_wednesday"},{"id":"japanese","word":"日本語","reading":"にほんご","gloss":"Japanese (language)","parts":[["日","ニ","sun, day"],["本","ホン","origin, book"],["語","ゴ","language, word"]],"clip":"s_n5u4d4_japanese"},{"id":"speak","word":"話す","reading":"はなす","gloss":"to speak, to talk","parts":[["話","はな","talk"]],"clip":"s_n5u4d4_speak"},{"id":"mountain","word":"山","reading":"やま","gloss":"mountain","parts":[["山","やま","mountain"]],"clip":"s_n5u4d4_mountain"},{"id":"river","word":"川","reading":"かわ","gloss":"river","parts":[["川","かわ","river"]],"clip":"s_n5u4d4_river"},{"id":"flower","word":"花","reading":"はな","gloss":"flower","parts":[["花","はな","flower"]],"clip":"s_n5u4d4_flower"},{"id":"weather","word":"天気","reading":"てんき","gloss":"weather","parts":[["天","テン","sky, heaven"],["気","キ","spirit, air"]],"clip":"s_n5u4d4_weather"}],"check":{"id":"n5u04d4.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_天気_が　いい　日は　山へ　行きます。","options":["でんき","てんき","てんぎ","でんぎ"],"answer":2,"explain":"天気 is てんき, weather. でんき is 電気 (electricity or a light). てんぎ and でんぎ are not words."}},"skill":{"kind":"reading","ja":"内容理解（短文）","en":"Short passage","ask":"What is true about Maria?","seconds":90,"passage":"はじめまして。マリアです。わたしは　^スポーツが　大すきです^。毎週　土よう日に　友だちと　テニスを　します。^でも、テニスは　まだ　へたです^。りょうりも　すきです。日よう日は　うちで　カレーを　つくります。魚は　きらいですから、魚の　りょうりは　つくりません。どうぞ　よろしく。","strategy":"Check each choice against the passage, and read what comes after でも.","item":{"id":"n5u04d4.r1","kind":"choice","type":"読解・内容理解（短文）","q":"マリアさんに　ついて　ただしい　ものは　どれですか。","options":["毎日　テニスを　します。","りょうりが　きらいです。","テニスは　すきですが、まだ　上手じゃ　ありません。","よく　魚の　りょうりを　つくります。"],"short":["毎日テニスをする","りょうりがきらい","テニスはすきだが上手じゃない","よく魚のりょうりをつくる"],"answer":3,"explain":"Maria loves sports and plays tennis, but after でも she says テニスは まだ へたです: she is not good at it yet.","why":["She plays tennis every week on Saturday, not every day.","She says りょうりも すきです: she likes cooking.","","She does not like fish, so she does not cook fish dishes."]}}},{"title":"〜がほしい・〜たい","grammar":{"points":[{"id":"n5u04d5.p1","form":"〜がほしいです","gloss":"I want (a thing)","connect":[{"pos":"Noun (the thing you want)","rule":"〜が{ほしいです}"},{"pos":"Noun, saying you do not want it","rule":"〜は{ほしくないです}"},{"pos":"Asking what someone wants","rule":"[何|なに]が{ほしいですか}"}],"examples":[{"ja":"[新|あたら]しい[車|くるま]が{ほしいです}。","en":"I want a new car.","clip":"x_n5u04d5_p1_1"},{"ja":"A「たんじょう[日|び]に[何|なに]が{ほしいですか}。」B「[白|しろ]いかばんが{ほしいです}。」","en":"A: What do you want for your birthday? B: I want a white bag.","clip":"x_n5u04d5_p1_2"}],"watch":{"note":"The thing you want takes が, not を. Also, use ほしいです for your own wishes, or in a question to the person you are talking to.","bad":"わたしは新しい車をほしいです。","good":"わたしは新しい車がほしいです。"}},{"id":"n5u04d5.p2","form":"〜たいです","gloss":"I want to (do)","connect":[{"pos":"Verb, ます form","rule":"〜ます → 〜{たいです}"},{"pos":"Verb, not wanting to","rule":"〜ます → 〜{たくないです}"},{"pos":"Verb with an object","rule":"〜を／が 〜{たいです}"}],"examples":[{"ja":"[日|にち]よう[日|び]は[山|やま]へ[行|い]き{たいです}。","en":"On Sunday I want to go to the mountains.","clip":"x_n5u04d5_p2_1"},{"ja":"[今日|きょう]は[魚|さかな]を[食|た]べ{たくないです}。","en":"I don't want to eat fish today.","clip":"x_n5u04d5_p2_2"}],"watch":{"note":"たい joins the verb in the shape it has before ます: 行きます → 行きたいです. It does not join 行く.","bad":"わたしは日本へ行くたいです。","good":"わたしは日本へ行きたいです。"}}],"compare":{"intro":"ほしい wants a thing, たい wants to do something, and すき says what you like in general.","forms":[{"form":"〜がほしいです","tag":"ほしい · want a thing","mark":"dot","ja":"[新|あたら]しいかさが{ほしいです}。","en":"I want a new umbrella."},{"form":"〜たいです","tag":"したい · want to do","mark":"dot","ja":"かさを[買|か]い{たいです}。","en":"I want to buy an umbrella."},{"form":"〜がすきです","tag":"すき · like","mark":"dot","ja":"[花|はな]が{すきです}。","en":"I like flowers."}],"check":{"id":"n5u04d5.c1","kind":"choice","type":"文の文法1","label":"たんじょう日","q":"A「^たんじょう[日|び]に^[何|なに]が（　　）。」B「^[新|あたら]しいとけい^です。」","options":["[行|い]きたいですか","すきですか","ほしいですか"],"answer":3,"why":["行きたい is about a place you want to go. 何が does not fit it, and a watch is not a place.","すき asks what you like in general. It does not go with たんじょう日に, and B names one new thing to get.","A asks what B wants as a birthday present, and B names a thing: a new watch."],"explain":null}},"drill":[{"id":"n5u04d5.d1","kind":"choice","type":"文の文法1","label":"Choose the word","q":"[新|あたら]しいかばん（　　）^ほしいです^。","options":["に","が","を","で"],"answer":2,"why":["に does not mark the thing you want. Here the bag needs が.","With ほしい, the thing you want takes が.","ほしい is not a verb like 買います. The thing you want takes が, not を.","で marks where or with what you do something. The bag is the thing you want."],"explain":null},{"id":"n5u04d5.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[日|にち]よう[日|び]は、うちでゆっくり（　　）。","options":["[休|やす]みたいです","[休|やす]むたいです","[休|やす]みますたいです","[休|やす]みほしいです"],"answer":1,"why":["休みます without ます is 休み, and たいです joins it: \"I want to rest.\"","たい does not join 休む. It joins 休み, the shape before ます.","たい takes the place of ます. You do not keep ます.","ほしい goes after a thing with が. For doing something, use たい."]},{"id":"n5u04d5.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[今日|きょう]はつかれました。^どこへも^[行|い]き（　　）。","options":["たいです","ましょう","たいですか","たくないです"],"answer":4,"why":["どこへも goes with a \"not\" ending, and たいです is not one.","どこへも goes with a \"not\" ending. Also, the speaker is tired, not inviting anyone.","どこへも goes with a \"not\" ending, and the speaker is talking about himself, not asking.","どこへも needs a \"not\" ending: \"I don't want to go anywhere.\""],"explain":null},{"id":"n5u04d5.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この[白|しろ]いかさ、[安|やす]いですよ。」B「かさは^うちに[三本|さんぼん]^あります。^[今|いま]は^（　　）。」","options":["ほしかったです","ほしくないです","ほしいくないです","ほしいじゃないです"],"answer":2,"why":["ほしかったです is the past, \"I wanted it\". B says 今は, now.","B has three umbrellas at home, so he does not want one now. ほしい → ほしくないです.","For \"not\", ほしい drops い and takes くない: ほしくない, not ほしいくない.","じゃない is for nouns and な words. ほしい is an い word: ほしくないです."],"explain":null},{"id":"n5u04d5.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「たんじょう[日|び]に[何|なに]がほしいですか。」B「","after":"。」","tiles":["[白|しろ]い","かばん","が","ほしいです"],"star":2,"bank":[1,3,0,2],"hint":"白い describes the thing. The thing you want takes が, and ほしいです comes last.","full":"A「たんじょう[日|び]に[何|なに]がほしいですか。」B「[白|しろ]いかばんが{ほしいです}。」","explain":"白い comes before かばん, which it describes. が marks the thing B wants, and ほしいです ends the answer."},{"id":"n5u04d5.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[今日|きょう]はあついですね。つめたい","after":"。","tiles":["ジュース","が","[飲|の]み","たいです"],"star":2,"bank":[2,0,3,1],"hint":"つめたい describes a drink. たいです joins the verb without ます.","full":"[今日|きょう]はあついですね。つめたいジュースが[飲|の]み{たいです}。","explain":"つめたい describes ジュース. With たい the object can take が, and 飲み (飲みます without ます) takes たいです."}],"exam":[{"id":"n5u04d5.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「今日の　ばんごはんは　何が　いいですか。」B「カレーが　（　　）。」","options":["食べたいです","食べました","食べたくないです","食べませんか"],"answer":1,"explain":"A asks what would be good for dinner tonight, and B names curry: 食べたいです. 食べました is the past. 食べたくないです does not answer \"what would be good?\". 食べませんか invites, but B is answering a question."},{"id":"n5u04d5.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「たんじょう日に　何が　ほしいですか。」B「何も　（　　）。」","options":["ほしいでした","ほしくないです","ほしいです","ほしいですか"],"answer":2,"explain":"何も goes with a \"not\" ending: \"I don't want anything.\" ほしいです and ほしいですか are not \"not\" endings. ほしいでした is not a correct form; the past of ほしい is ほしかったです."},{"id":"n5u04d5.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「来年は　何を　したいですか。」B「","after":"。」","tiles":["新しい","車","を","買いたいです"],"star":2,"bank":[3,2,0,1],"full":"A「来年は　何を　したいですか。」B「新しい車を{買いたいです}。」","explain":"新しい, 車, を, 買いたいです. 新しい describes 車, を marks what B wants to buy, and 買いたいです comes last."}]},"scene":{"ja":"ほしいものリスト","en":"A birthday wish list","intro":"Tap every word on the list you would read to know what she wants and how much it costs.","words":[{"id":"new","word":"新しい","reading":"あたらしい","gloss":"new","parts":[["新","あたら","new"]],"clip":"s_n5u4d5_new"},{"id":"white","word":"白い","reading":"しろい","gloss":"white","parts":[["白","しろ","white"]],"clip":"s_n5u4d5_white"},{"id":"big","word":"大きい","reading":"おおきい","gloss":"big","parts":[["大","おお","big"]],"clip":"s_n5u4d5_big"},{"id":"book","word":"本","reading":"ほん","gloss":"book","parts":[["本","ホン","book; origin"]],"clip":"s_n5u4d5_book"},{"id":"flower","word":"花","reading":"はな","gloss":"flower","parts":[["花","はな","flower"]],"clip":"s_n5u4d5_flower"},{"id":"car","word":"車","reading":"くるま","gloss":"car","parts":[["車","くるま","car, wheel"]],"clip":"s_n5u4d5_car"},{"id":"1000","word":"千円","reading":"せんえん","gloss":"1,000 yen","parts":[["千","セン","thousand"],["円","エン","yen"]],"clip":"s_n5u4d5_1000"},{"id":"10000","word":"一万円","reading":"いちまんえん","gloss":"10,000 yen","parts":[["一","イチ","one"],["万","マン","ten thousand"],["円","エン","yen"]],"clip":"s_n5u4d5_10000"}],"check":{"id":"n5u04d5.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"たんじょう日に　_白い_　花が　ほしいです。","options":["あかい","あおい","しろい","くろい"],"answer":3,"explain":"白い is read しろい, \"white\". くろい is black, あかい is red and あおい is blue; they are written with other kanji."}},"skill":{"kind":"listening","ja":"課題理解","en":"Task comprehension","ask":"二人は　何を　買いますか。","audio":[["N","店で、女の人と男の人が話しています。二人は、何を買いますか。","みせで、おんなのひとと　おとこのひとが　はなしています。ふたりは、なにを　かいますか。"],["F","あしたは、リンさんのたんじょう日ですね。何を買いましょうか。","あしたは、リンさんの　たんじょうびですね。なにを　かいましょうか。"],["M","本はどうですか。",null],["F","うーん、リンさんのへやには、本がたくさんありますよ。",null],["M","そうですか。じゃあ、このかばんは？大きくて、いいですね。ぼくもほしいです。","そうですか。じゃあ、この　かばんは？　おおきくて、いいですね。ぼくも　ほしいです。"],["F","いいですね。でも、一万円ですよ。ちょっと高いです。","いいですね。でも、いちまんえんですよ。ちょっと　たかいです。"],["M","そうですね。じゃあ、花はどうですか。この白い花、きれいですよ。","そうですね。じゃあ、はなは　どうですか。この　しろい　はな、きれいですよ。"],["F","ええ、いいですね。花を買いましょう。","ええ、いいですね。はなを　かいましょう。"],["N","二人は、何を買いますか。","ふたりは、なにを　かいますか。"]],"item":{"id":"n5u04d5.r1","kind":"choice","type":"課題理解","q":"二人は　何を　買いますか。","script":["ナレーター：店で、女の人と男の人が話しています。二人は、何を買いますか。","女：あしたは、リンさんのたんじょう日ですね。何を買いましょうか。","男：本はどうですか。","女：うーん、リンさんのへやには、本がたくさんありますよ。","男：そうですか。じゃあ、このかばんは？大きくて、いいですね。ぼくもほしいです。","女：いいですね。でも、一万円ですよ。ちょっと高いです。","男：そうですね。じゃあ、花はどうですか。この白い花、きれいですよ。","女：ええ、いいですね。花を買いましょう。","ナレーター：二人は、何を買いますか。"],"options":["白い　花","かばんと　花","本","大きい　かばん"],"printed":true,"short":["白い 花","かばんと 花","本","大きい かばん"],"answer":1,"why":["The man suggests the white flowers, and the woman agrees: 花を買いましょう.","They talk about both, but they do not buy the bag. It is too expensive.","The woman says Lin already has many books in her room.","The man likes the bag, but the woman says it is 一万円, a little expensive."],"explain":null,"clip":"l_n5u4d5"}}},{"title":"まとめ：似ている文法","grammar":{"points":[],"compare":{"intro":"To tell this unit's points apart, ask three things: is the word an い-adjective or a な-adjective (that decides the present, past, not and joining forms), does すき or じょうず come after it (then the thing takes が), and do you want a thing (〜がほしいです) or want to do something (〜たいです).","forms":[{"form":"〜くて／〜で","tag":"つなぐ · joining two words","mark":"dot","ja":"この[店|みせ]は[古|ふる]{くて}[小|ちい]さいです。でも、きれい{で}しずかです。","en":"This shop is old and small. But it is clean and quiet."},{"form":"〜かったです／〜でした","tag":"きのうのこと · it was","mark":"dot","ja":"[山|やま]はさむ{かったです}。でも、[花|はな]がきれい{でした}。","en":"It was cold on the mountain. But the flowers were beautiful."},{"form":"〜がほしいです／〜たいです","tag":"ものか、することか · a thing or an action","mark":"dot","ja":"[新|あたら]しいくつ{がほしいです}。あした[買|か]い{たいです}。","en":"I want new shoes. I want to buy them tomorrow."}],"check":{"id":"n5u04d6.c1","kind":"choice","type":"文の文法1","label":"[川|かわ]で","q":"^きのう^の[川|かわ]はとてもきれい（　　）。","options":["かったです","でした","です"],"answer":2,"why":["きれい ends in い, but it is a な-adjective, so it never takes かったです.","きれい is a な-adjective, and きのう is past: きれいでした.","きれいです is the present. きのう needs the past."]}},"drill":[{"id":"n5u04d6.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この[白|しろ]いシャツ、どうですか。」B「いいですね。^でも、ちょっと[高|たか]いです^。もっと（　　）シャツがほしいです。」","options":["[安|やす]い","[安|やす]くて","[安|やす]いな","[安|やす]かったです"],"answer":1,"why":["Right before a noun, an い-adjective stays as it is: 安いシャツ. B wants a cheaper shirt than this one.","安くて joins 安い to another describing word. Here a noun, シャツ, comes next, so it does not fit.","な is for な-adjectives such as しずか. 安い is an い-adjective and takes no な.","安かったです is the polite past and ends a sentence. It cannot sit right before シャツ."]},{"id":"n5u04d6.d2","kind":"choice","type":"文の文法1","label":"Choose the phrase","q":"^[先週|せんしゅう]^、[駅|えき]の[前|まえ]の[店|みせ]でカレーを[食|た]べました。（　　）。","options":["[安|やす]かったでおいしいです","[安|やす]いでおいしかったです","[安|やす]くておいしいでした","[安|やす]くておいしかったです"],"answer":4,"why":["安かった does not join with で. Use 安くて, and put the past on the last word: おいしかったです.","安い is an い-adjective, so it joins with くて, not で.","安くて is right, but おいしい is an い-adjective. Its past is おいしかったです, not おいしいでした.","安い joins with くて, and the last word carries the past for the whole sentence: おいしかったです."],"explain":null},{"id":"n5u04d6.d3","kind":"choice","type":"文の文法1","label":"Choose the particles","q":"わたしは[電車|でんしゃ]（　　）^すきです^。[日|にち]よう[日|び]、[大|おお]きい[駅|えき]（　　）^[行|い]きたいです^。","options":["で／へ","が／で","を／へ","が／へ"],"answer":4,"why":["で marks where you do something or what you use. It cannot mark the thing you like.","が is right for 電車, but 駅 is where you go. 行きたいです keeps the へ of 行きます, so で does not fit.","すきです takes が for the thing you like, not を.","The thing you like takes が: 電車がすきです. With 行きたいです, the place you go to takes へ, as with 行きます."],"explain":null},{"id":"n5u04d6.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^[前|まえ]は^コーヒーが（　　）。^でも、[今|いま]は^[毎日|まいにち][飲|の]みます。","options":["すきでした","きらいです","きらいでした","きらかったです"],"answer":3,"why":["すきでした has the right form, but でも needs a change: liked it before, and still drinks it now, is no contrast.","きらいです is the present. 前は needs the past.","きらい is a な-adjective, so its past is きらいでした. でも then shows the change: now I drink it every day.","きらい ends in い, but it is a な-adjective. It does not change like an い-adjective."],"explain":null},{"id":"n5u04d6.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしは","after":"。","tiles":["[白|しろ]くて","[小|ちい]さい","ねこが","ほしいです"],"star":1,"bank":[2,0,3,1],"hint":"Which tile joins to another describing word? Which one can sit right before a noun?","full":"わたしは[白|しろ]くて{[小|ちい]さい}ねこがほしいです。","explain":"白くて joins to the next describing word, 小さい. 小さい sits right before the noun, ねこ. The thing you want takes が, and ほしいです comes last."},{"id":"n5u04d6.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"きのうの","after":"。","tiles":["こうえんは","[花|はな]が","[多|おお]くて","きれいでした"],"star":2,"bank":[3,1,0,2],"hint":"きのうの needs a noun right after it. The past goes on the last word only.","full":"きのうのこうえんは[花|はな]が{[多|おお]くて}きれいでした。","explain":"きのうのこうえんは is the topic. 花が多くて says what was there and joins to きれいでした, which carries the past for both."}],"exam":[{"id":"n5u04d6.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きのうの　テストは　（　　）、むずかしかったです。","options":["長かったで","長いくて","長いで","長くて"],"answer":4,"explain":"長い is an い-adjective, so it joins with くて: 長くて、むずかしかったです. The past goes on the last word only. 長いで and 長かったで use で, which is for な-adjectives and nouns, and 長いくて keeps the い it should drop."},{"id":"n5u04d6.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは　えいがが　すきです。こんどの　日よう日、新しい　えいがを　（　　）。","options":["ほしいです","見ほしいです","見たいです","見るたいです"],"answer":3,"explain":"Seeing a film is an action, so use たい on the ます form: 見ます → 見たいです. ほしいです is for a thing and takes が, not を. 見ほしいです is not a form, and たい does not join 見る."},{"id":"n5u04d6.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「きのうの　レストランは　どうでしたか。」B「","after":"とても　おいしかったです。」","tiles":["店は","古くて","小さかったですが","りょうりは"],"star":2,"bank":[1,3,2,0],"full":"A「きのうの　レストランは　どうでしたか。」B「店は　古くて　{小さかったですが}　りょうりは　とても　おいしかったです。」","explain":"店は, 古くて, 小さかったですが, りょうりは. The shop was old and small: 古くて joins to 小さかったです. が (but) then turns to the food, and りょうりは goes with おいしかったです."}]},"scene":{"ja":"山のまちのパンフレット","en":"A travel brochure for a mountain town","intro":"Tap each word on the brochure page for a small mountain town.","words":[{"id":"old","word":"古い","reading":"ふるい","gloss":"old (things, not people)","parts":[["古","ふる","old"]],"clip":"s_n5u4d6_old"},{"id":"long","word":"長い","reading":"ながい","gloss":"long","parts":[["長","なが","long"]],"clip":"s_n5u4d6_long"},{"id":"many","word":"多い","reading":"おおい","gloss":"many, a lot","parts":[["多","おお","many"]],"clip":"s_n5u4d6_many"},{"id":"west-exit","word":"西口","reading":"にしぐち","gloss":"west exit (of a station)","parts":[["西","にし","west"],["口","ぐち","mouth, exit"]],"clip":"s_n5u4d6_west_exit"},{"id":"every-day","word":"毎日","reading":"まいにち","gloss":"every day","parts":[["毎","マイ","every"],["日","ニチ","day"]],"clip":"s_n5u4d6_every_day"},{"id":"am","word":"午前","reading":"ごぜん","gloss":"morning, a.m.","parts":[["午","ゴ","noon"],["前","ゼン","before"]],"clip":"s_n5u4d6_am"},{"id":"foreign","word":"外国","reading":"がいこく","gloss":"foreign country","parts":[["外","ガイ","outside"],["国","コク","country"]],"clip":"s_n5u4d6_foreign"},{"id":"child","word":"子ども","reading":"こども","gloss":"child, children","parts":[["子","こ","child"]],"clip":"s_n5u4d6_child"}],"check":{"id":"n5u04d6.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"この　まちには　_古い_　店が　たくさん　あります。","options":["くろい","ふかい","ふるい","ひろい"],"answer":3,"explain":"古い is ふるい, \"old\". ひろい (wide), くろい (black) and ふかい (deep) are real words, but they are written with other kanji or in kana."}},"skill":{"kind":"reading","ja":"情報検索","en":"Finding information","ask":"How much does a ten-year-old child pay for the tour?","seconds":90,"passage":"山の　まち　バスツアー\n毎日　午前九時半に　駅の　西口を　出ます。\n古い　店が　多い　道を　あるきます。川の　そばで　魚を　食べます。\n大人　三千円\n^子ども（六さい〜十二さい）　千五百円^\n五さいまでの　子どもは　お金は　いりません。","strategy":"Find the line for children and check which ages it covers.","item":{"id":"n5u04d6.r1","kind":"choice","type":"読解・情報検索","q":"十さいの　子どもは　いくら　はらいますか。","options":["三千円","千五百円","四千五百円","お金は　いりません"],"short":["3,000円","1,500円","4,500円","free"],"answer":2,"explain":"The line 子ども（六さい〜十二さい） covers children from six to twelve. A ten-year-old pays 千五百円.","why":["Three thousand yen is the price for 大人, adults.","","Four thousand five hundred yen is one adult and one child together. The question asks about the child only.","Only children up to five years old pay nothing."]}}}],"test":[{"id":"n5u04t.1","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"父の　カメラは　_古い_ですが、まだ　よく　とれます。","options":["ふとい","ふるい","ふろい","くるい"],"answer":2,"explain":"古い is ふるい, old. ふとい is a different word (thick), not read from 古. ふろい and くるい change one sound of ふるい, and they are not words."},{"id":"n5u04t.2","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"きょうは　_空_が　あおくて　きれいです。","options":["くも","うみ","そうら","そら"],"answer":4,"explain":"空 here is そら, the sky. くも (cloud) and うみ (sea) are other words, not read from 空. そうら has a long そう, and it is not a word."},{"id":"n5u04t.3","kind":"choice","type":"表記","label":"Kanji spelling","q":"この　くつは　_やすい_ですが、とても　いいです。","options":["高い","女い","休い","安い"],"answer":4,"explain":"やすい (cheap) is 安い. 高い is たかい (expensive), the opposite. 女 is おんな and 休 is the やす of 休みます, so 女い and 休い are not words."},{"id":"n5u04t.4","kind":"choice","type":"表記","label":"Kanji spelling","q":"あしたは　_ごご_から　雨です。","options":["午後","五後","午前","後午"],"answer":1,"explain":"ごご (afternoon) is 午後. 午前 is ごぜん (morning), a real word but not ごご. 後午 has the two kanji the wrong way round, and 五後 uses 五 (five); neither is a word."},{"id":"n5u04t.5","kind":"choice","type":"文脈規定","label":"Word in context","q":"へやが　（　　）ですから、まどを　あけました。","options":["ひろい","ふるい","あつい","さむい"],"answer":3,"explain":"You open the window because the room is hot: あつい. If the room is さむい (cold), you would not open the window. ひろい (big) and ふるい (old) are not reasons to open a window."},{"id":"n5u04t.6","kind":"choice","type":"文脈規定","label":"Word in context","q":"この　本は　（　　）ですから、子どもも　よく　読みます。","options":["むずかしい","たかい","やさしい","おもい"],"answer":3,"explain":"Children read the book often because it is easy: やさしい. むずかしい (difficult) is the opposite reason. たかい (expensive) and おもい (heavy) do not explain why children read it a lot."},{"id":"n5u04t.7","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"わたしの　へやは　_せまい_です。","options":["わたしの　へやは　しずかじゃ　ありません。","わたしの　へやは　ひろいです。","わたしの　へやは　ひろくないです。","わたしの　へやは　あかるくないです。"],"answer":3,"explain":"せまい means small (not roomy), so it is the same as ひろくないです, not big. Option 2 says the opposite. あかるくない (not bright) and しずかじゃ ありません (not quiet) talk about other things, not the size."},{"id":"n5u04t.8","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"きのうの　テストは　_むずかしくなかったです_。","options":["きのうの　テストは　むずかしかったです。","きのうの　テストは　たのしかったです。","きのうの　テストは　やさしくなかったです。","きのうの　テストは　やさしかったです。"],"answer":4,"explain":"むずかしくなかったです means the test was not difficult, so it was easy: やさしかったです. Option 1 says it was difficult. Option 2 says it was fun, which is about something else. Option 3 says it was not easy, the opposite."},{"id":"n5u04t.9","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ここは　とても　（　　）　まちですね。","options":["にぎやかな","にぎやかの","にぎやかい","にぎやかで"],"answer":1,"explain":"にぎやか is a な-word, and it takes な before a noun: にぎやかな まち (a lively town). の does not join にぎやか to a noun, and にぎやかい is not a form. にぎやかで means \"lively and\", so it cannot go right before まち."},{"id":"n5u04t.10","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この　いすは　大きいですが、あまり　（　　）。","options":["おもいじゃ　ありません","おもくないです","おもいくないです","おもいです"],"answer":2,"explain":"あまり goes with a not form, and the not form of おもい (heavy) is おもくないです: the chair is big but not very heavy. おもいです is not a not form, so it does not go with あまり. じゃ ありません is for な-words and nouns, not for an い-word like おもい. おもいくないです keeps the い, but the い changes to く."},{"id":"n5u04t.11","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きのうは　とても　（　　）から、どこへも　行きませんでした。","options":["さむかったです","さむいでした","さむくなかったです","さむいです"],"answer":1,"explain":"きのう is past, and the past of さむい is さむかったです: it was very cold, so the person went nowhere. さむいです is not past. さむいでした is not a form; an い-word does not take でした. さむくなかったです (it was not cold) does not go with とても, and it is not a reason to stay in."},{"id":"n5u04t.12","kind":"choice","type":"文の文法1","label":"Choose the form","q":"子どもの　とき、やさいが　（　　）。でも、今は　大すきです。","options":["すきでした","すきくなかったです","すきじゃ　ありません","すきじゃ　ありませんでした"],"answer":4,"explain":"でも、今は 大すきです shows that it was different as a child, so the person did not like vegetables then: すきじゃ ありませんでした. すきでした (liked) does not fit でも. すき is a な-word, so すきくなかったです is not a form. すきじゃ ありません is about now, but 子どもの とき is the past."},{"id":"n5u04t.13","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この　かばんは　（　　）、べんりです。","options":["かるくて","かるいで","かるくで","かるいくて"],"answer":1,"explain":"To join the い-word かるい (light) to べんりです, い changes to くて: かるくて、べんりです (light and handy). で joins な-words and nouns, not い-words, so かるいで and かるくで are wrong. かるいくて keeps the い, but the い changes to く."},{"id":"n5u04t.14","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"あの　人は　ピアノ（　　）　とても　じょうずですね。","options":["を","で","が","と"],"answer":3,"explain":"The thing someone is good at takes が: ピアノが じょうずです. を does not go with じょうずです. で would mark a place or a tool, and と means \"with\"; neither makes sense with じょうずです here."},{"id":"n5u04t.15","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きょねん　はじめて　日本へ　行きました。来年も　また　（　　）。","options":["行きほしいです","行きたかったです","行きたいです","行くたいです"],"answer":3,"explain":"来年 (next year) is in the future, so the person says what they want to do: 行きたいです. 行きたかったです is past, and it does not fit 来年. たい joins the ます form without ます (行き), not 行く, so 行くたいです is wrong. ほしい is for things you want, not actions, so 行きほしいです is not Japanese."},{"id":"n5u04t.16","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「山川さんは　どの　人ですか。」B「あの　","after":"です。」","tiles":["ギター","が","じょうずな","人"],"star":2,"bank":[2,3,0,1],"full":"A「山川さんは　どの　人ですか。」B「あの　ギターが　{じょうずな}　人です。」","explain":"ギター, が, じょうずな, 人. The thing someone is good at takes が, so ギターが comes first. じょうずな, with な before a noun, describes 人: あの ギターが じょうずな 人 (that person who is good at the guitar). じょうずな cannot come before ギター, because then が and 人 have no place."},{"id":"n5u04t.17","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「りょこうは　どうでしたか。」B「","after":"が、とても　きれいでした。」","tiles":["ホテルの","へやは","少し","せまかったです"],"star":2,"bank":[3,1,0,2],"full":"A「りょこうは　どうでしたか。」B「ホテルの　へやは　{少し}　せまかったですが、とても　きれいでした。」","explain":"ホテルの, へやは, 少し, せまかったです. ホテルの needs a noun after it, so it goes before へやは (the hotel room). 少し (a little) comes right before the word it describes, せまかったです, and せまかったです comes last because が follows it: the room was a little small, but very clean."},{"id":"n5u04t.18","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「今　何が　いちばん　ほしいですか。」B「","after":"　ほしいです。」","tiles":["大きくて","かるい","かばん","が"],"star":1,"bank":[1,3,0,2],"full":"A「今　何が　いちばん　ほしいですか。」B「大きくて　{かるい}　かばんが　ほしいです。」","explain":"大きくて, かるい, かばん, が. 大きくて (big and) joins the next describing word, かるい, and かるい comes right before the noun かばん: a big, light bag. The thing you want takes が, so が comes right before ほしいです. 大きくて cannot come right before かばん, because くて does not join a noun."},{"id":"n5u04t.19","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"わたしは　先月から　新しい　アパートに　すんで　います。へやは　あまり　ひろくないですが、あかるくて　きれいです。駅から　あるいて　五分ですから、べんりです。でも、ちかくに　店が　ありませんから、かいものは　たいへんです。今は　大きい　つくえが　ほしいです。","q":"この　人の　へやは　どんな　へやですか。","options":["ひろくて　あかるいです。","ひろくないですが、あかるいです。","あかるくないですが、きれいです。","ひろいですが、きれいじゃ　ありません。"],"answer":2,"short":["ひろい・あかるい","ひろくない・あかるい","あかるくない","きれいじゃない"],"explain":"The writer says へやは あまり ひろくないですが、あかるくて きれいです: not very big, but bright and clean. Option 1 says the room is big. Option 3 says it is not bright. Option 4 says it is big and not clean."},{"id":"n5u04t.20","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"わたしは　先月から　新しい　アパートに　すんで　います。へやは　あまり　ひろくないですが、あかるくて　きれいです。駅から　あるいて　五分ですから、べんりです。でも、ちかくに　店が　ありませんから、かいものは　たいへんです。今は　大きい　つくえが　ほしいです。","q":"ただしい　ものは　どれですか。","options":["アパートは　駅から　とおいです。","アパートの　ちかくに　店が　たくさん　あります。","この　人は　今　つくえが　ほしいです。","アパートは　古いです。"],"answer":3,"short":["駅からとおい","店がたくさん","つくえがほしい","古い"],"explain":"The writer ends with 今は 大きい つくえが ほしいです: now the writer wants a big desk. The apartment is new (新しい アパート), not old. It is a five-minute walk from the station, so it is not far. There are no shops near it (ちかくに 店が ありません)."},{"id":"n5u04t.21","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"アパートの　あんない\nＡ　駅から　あるいて　三分　へやは　小さいです　六万円\nＢ　駅から　バスで　十分　へやは　ひろくて　あかるいです　五万円\nＣ　駅から　あるいて　十五分　へやは　ひろいです　四万円\nＤ　駅から　あるいて　八分　へやは　せまくて　古いです　三万円","q":"リーさんは　ひろい　へやが　いいです。でも、バスは　きらいです。どの　アパートが　いいですか。","options":["Ｃ","Ｄ","Ａ","Ｂ"],"answer":1,"short":["Ｃ","Ｄ","Ａ","Ｂ"],"explain":"Ｃ has a big room (ひろいです), and you walk from the station, so there is no bus. Ａ has a small room (小さいです). Ｂ has a big room, but you go there by bus (バスで). Ｄ has a small, old room (せまくて 古いです)."},{"id":"n5u04t.22","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"アパートの　あんない\nＡ　駅から　あるいて　三分　へやは　小さいです　六万円\nＢ　駅から　バスで　十分　へやは　ひろくて　あかるいです　五万円\nＣ　駅から　あるいて　十五分　へやは　ひろいです　四万円\nＤ　駅から　あるいて　八分　へやは　せまくて　古いです　三万円","q":"ワンさんの　お金は　毎月　五万円までです。駅から　あるいて　行きたいです。いちばん　駅から　ちかい　アパートは　どれですか。","options":["Ｃ","Ｄ","Ａ","Ｂ"],"answer":2,"short":["Ｃ","Ｄ","Ａ","Ｂ"],"explain":"Ｃ (四万円) and Ｄ (三万円) cost 五万円 or less, and you walk to both from the station. Ｄ is eight minutes away and Ｃ is fifteen, so Ｄ is the nearest. Ａ is nearer, but it costs 六万円, which is too much. Ｂ costs 五万円, but you go there by bus."},{"id":"n5u04t.23","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"マリアさん\nあしたの　パーティーの　ケーキは　わたしが　買います。駅の　前の　店は　ケーキが　小さくて　高いですから、川の　ちかくの　店で　買います。そこの　ケーキは　大きくて　おいしいです。マリアさんは　つめたい　ジュースを　買って　ください。\nゆき","q":"ゆきさんは　どうして　駅の　前の　店で　ケーキを　買いませんか。","options":["ケーキが　小さくて　高いですから","ケーキが　大きくて　おいしいですから","店が　駅から　とおいですから","店に　ジュースが　ありませんから"],"answer":1,"short":["小さくて高い","大きくておいしい","駅からとおい","ジュースがない"],"explain":"ゆき writes 駅の 前の 店は ケーキが 小さくて 高いですから: the cakes there are small and expensive. Big and tasty (大きくて おいしい) is the cake at the shop near the river. The note does not say the shop is far from the station; it is in front of it. The juice is for マリア to buy, and the note says nothing about juice at that shop."},{"id":"n5u04t.24","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"マリアさん\nあしたの　パーティーの　ケーキは　わたしが　買います。駅の　前の　店は　ケーキが　小さくて　高いですから、川の　ちかくの　店で　買います。そこの　ケーキは　大きくて　おいしいです。マリアさんは　つめたい　ジュースを　買って　ください。\nゆき","q":"マリアさんは　何を　買いますか。","options":["川の　ちかくの　店の　ケーキ","つめたい　ジュース","ケーキと　ジュース","駅の　前の　店の　ケーキ"],"answer":2,"short":["川のちかくのケーキ","ジュース","ケーキとジュース","駅の前のケーキ"],"explain":"ゆき writes マリアさんは つめたい ジュースを 買って ください: マリア buys cold juice. ゆき buys the cake (ケーキは わたしが 買います), from the shop near the river, so options 3, 1 and 4 are wrong. Nobody buys cake at the shop in front of the station."}]},{"n":5,"ja":"時間・順番","en":"Time and order","days":[{"title":"〜に（時間）・〜から〜まで","grammar":{"points":[{"id":"n5u05d1.p1","form":"〜に（時間）","gloss":"at, on (a time or a day)","connect":[{"pos":"A clock time: 〜 is the number, as in 七時に","rule":"〜[時|じ]{に}"},{"pos":"A day of the week: 〜 is the day, as in 月よう日に","rule":"〜よう[日|び]{に}"},{"pos":"Words like 毎日, あした, きのう, 今: no に before the verb (〜ます)","rule":"[毎日|まいにち]・あした・きのう・[今|いま] ＋ 〜ます"}],"examples":[{"ja":"あさ[七時|しちじ]{に}おきます。","en":"I get up at seven in the morning.","clip":"x_n5u05d1_p1_1"},{"ja":"[日|にち]よう[日|び]{に}[友|とも]だちと[会|あ]います。","en":"I am meeting a friend on Sunday.","clip":"x_n5u05d1_p1_2"}],"watch":{"note":"Words that count from today, like あした and きのう, and words like 毎日 and 今, take no に. Put the verb part right after them.","bad":"あしたに学校へ行きます。","good":"あした学校へ行きます。"}},{"id":"n5u05d1.p2","form":"〜から〜まで","gloss":"from … until / to …","connect":[{"pos":"Times or days: the start, then the end","rule":"[九時|くじ]{から}[五時|ごじ]{まで}"},{"pos":"Places: where you start, then where you end","rule":"[駅|えき]{から}[学校|がっこう]{まで}"},{"pos":"Each one can also stand alone: 〜 is a time or a place","rule":"〜{から}・〜{まで}"}],"examples":[{"ja":"ぎんこうは[九時|くじ]{から}[三時|さんじ]{まで}です。","en":"The bank is open from nine to three.","clip":"x_n5u05d1_p2_1"},{"ja":"[駅|えき]{から}[学校|がっこう]{まで}あるきます。","en":"I walk from the station to school.","clip":"x_n5u05d1_p2_2"}],"watch":{"note":"In English you say \"from nine\". The start takes から, not に. に marks one point in time, not a start.","bad":"九時に五時まではたらきます。","good":"九時から五時まではたらきます。"}}],"compare":{"intro":"All three go after a time: に marks one point, から and まで mark the start and the end, and ごろ makes the time rough.","forms":[{"form":"〜に","tag":"その時間 · at (one point in time)","mark":"dot","ja":"[七時|しちじ]{に}おきます。","en":"I get up at seven."},{"form":"〜から〜まで","tag":"はじめとおわり · from … until","mark":"dot","ja":"[九時|くじ]{から}[五時|ごじ]{まで}はたらきます。","en":"I work from nine until five."},{"form":"〜ごろ","tag":"だいたい · about, around","mark":"dot","ja":"[七時|しちじ]{ごろ}おきます。","en":"I get up at about seven."}],"check":{"id":"n5u05d1.c1","kind":"choice","type":"文の文法1","label":"店のじかん","q":"この[店|みせ]は[十時|じゅうじ]（　　）[八時|はちじ]までです。","options":["ごろ","に","から"],"answer":3,"why":["ごろ means \"about\". 十時ごろ八時まで does not give a start, so the sentence does not work.","に marks one point in time, as in 十時に行きます. It cannot give the start before 八時まで.","まで gives the closing time, so the opening time takes から: from ten until eight."],"explain":null}},"drill":[{"id":"n5u05d1.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[毎日|まいにち]^あさ[六時|ろくじ]^（　　）おきます。","options":["で","に","を","へ"],"answer":2,"why":["六時でおきます is not Japanese. The time when you do something takes に.","六時 is a clock time, so it takes に: I get up at six.","を marks the thing a verb acts on, as in パンを食べます. 六時 is the time, not a thing you act on.","へ marks the place you go to. 六時 is a time, not a place."]},{"id":"n5u05d1.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「^いつ^[山|やま]へ[行|い]きますか。」\nB「（　　）[行|い]きます。」","options":["あしたに","あしたを","あした","あしたで"],"answer":3,"why":["あした counts from today, so it takes no に.","を marks the thing a verb acts on. あした is the time, and it takes nothing.","あした takes no particle: あした行きます, I will go tomorrow.","あしたで is not Japanese here. あした takes nothing before the verb."]},{"id":"n5u05d1.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この[店|みせ]は[午前|ごぜん][十時|じゅうじ]^から^[午後|ごご][七時|しちじ]（　　）です。","options":["に","を","まで","で"],"answer":3,"why":["に marks the time something happens, as in 七時に行きます. After から, the end time takes まで.","を marks the thing a verb acts on. 七時をです is not Japanese.","から gives the opening time, so まで gives the closing time: until seven.","七時でです is not Japanese. After から, the end time takes まで."]},{"id":"n5u05d1.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[月|げつ]よう[日|び]（　　）[金|きん]よう[日|び]^まで^[学校|がっこう]へ[行|い]きます。","options":["まで","で","から","に"],"answer":3,"why":["まで already sits after 金よう日. 月よう日まで金よう日まで is not Japanese.","月よう日で does not give a start. The first day takes から.","金よう日まで gives the last day, so the first day takes から: from Monday to Friday.","に marks one day, as in 月よう日に行きます. With 金よう日まで after it, the first day needs から."],"explain":null},{"id":"n5u05d1.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あしたは","after":"。","tiles":["[七時|しちじ]","[半|はん]","に","おきます"],"star":2,"bank":[3,1,0,2],"hint":"半 comes right after the hour. Then the time takes に, and the verb comes last.","full":"あしたは[七時|しちじ][半|はん]{に}おきます。","explain":"七時半 is one time, so 半 sits right after 七時. A clock time takes に, and おきます ends the sentence. あした itself takes no に; は is fine after it."},{"id":"n5u05d1.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"ぎんこうは[午前|ごぜん]","after":"です。","tiles":["[九時|くじ]","から","[午後|ごご][三時|さんじ]","まで"],"star":1,"bank":[2,3,0,1],"hint":"午前 needs an hour right after it. The start takes から, the end takes まで.","full":"ぎんこうは[午前|ごぜん][九時|くじ]{から}[午後|ごご][三時|さんじ]{まで}です。","explain":"午前 goes with 九時: nine in the morning. That is the start, so から follows it. 午後三時 is the end, so まで follows it, right before です."}],"exam":[{"id":"n5u05d1.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは　毎週　土よう日（　　）　プールへ　行きます。","options":["が","で","に","を"],"answer":3,"explain":"土よう日 is a day of the week, so it takes に: on Saturdays. 毎週 itself takes no particle. で does not give the day when something happens, を marks a thing a verb acts on, and が marks who or what does something. None of them fits after 土よう日 here."},{"id":"n5u05d1.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　店は　何時（　　）ですか。」\nB「よる　九時までです。」","options":["まで","に","を","から"],"answer":1,"explain":"B answers with 九時まで, the closing time, so A asked 何時までですか: until what time? 何時から asks the opening time, which B does not give. 何時にですか and 何時をですか do not work after この店は."},{"id":"n5u05d1.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あしたの　","after":"ですか。","tiles":["テスト","は","何時","から"],"star":2,"bank":[2,3,0,1],"full":"あしたの　テストは　{何時}からですか。","explain":"テスト, は, 何時, から. あしたの describes テスト, so テスト comes first, then は. The question is 何時からですか: from what time is tomorrow's test?"}]},"scene":{"ja":"ぎんこうのドア","en":"A bank's door sign","intro":"Tap each word on the opening-hours sign on the door of a small bank.","words":[{"id":"monday","word":"月よう日","reading":"げつようび","gloss":"Monday","parts":[["月","ゲツ","moon, Monday"],["日","び","day"]],"clip":"s_n5u5d1_monday"},{"id":"am","word":"午前","reading":"ごぜん","gloss":"a.m., morning","parts":[["午","ゴ","noon"],["前","ゼン","before"]],"clip":"s_n5u5d1_am"},{"id":"nine","word":"九時","reading":"くじ","gloss":"nine o'clock","parts":[["九","ク","nine"],["時","ジ","o'clock, time"]],"clip":"s_n5u5d1_nine"},{"id":"pm","word":"午後","reading":"ごご","gloss":"p.m., afternoon","parts":[["午","ゴ","noon"],["後","ゴ","after"]],"clip":"s_n5u5d1_pm"},{"id":"three-thirty","word":"三時半","reading":"さんじはん","gloss":"half past three","parts":[["三","サン","three"],["時","ジ","o'clock, time"],["半","ハン","half"]],"clip":"s_n5u5d1_three_thirty"},{"id":"saturday","word":"土よう日","reading":"どようび","gloss":"Saturday","parts":[["土","ド","earth, Saturday"],["日","び","day"]],"clip":"s_n5u5d1_saturday"},{"id":"sunday","word":"日よう日","reading":"にちようび","gloss":"Sunday","parts":[["日","ニチ","sun, Sunday"],["日","び","day"]],"clip":"s_n5u5d1_sunday"},{"id":"closed","word":"休み","reading":"やすみ","gloss":"closed, day off","parts":[["休","やす","rest"]],"clip":"s_n5u5d1_closed"}],"check":{"id":"n5u05d1.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"ぎんこうは　_午後_三時までです。","options":["ごうご","ごぜん","ごご","ごこ"],"answer":3,"explain":"午後 is ごご, the afternoon. ごぜん is 午前, the morning, a different word. ごこ and ごうご are not words."}},"skill":{"kind":"listening","ja":"即時応答","en":"Quick response","ask":"えなどが　ありません。ぶんを　聞いて、1から3の　中から、いちばん　いい　ものを　一つ　えらんで　ください。","item":{"id":"n5u05d1.r1","kind":"choice","type":"即時応答","q":"男：すみません、この　店は　何時までですか。","script":["男：すみません、この　店は　何時までですか。","ナレーター：1","女：午前　十時からです。","ナレーター：2","女：八時間です。","ナレーター：3","女：よる　八時までです。"],"options":["午前　十時からです。","八時間です。","よる　八時までです。"],"printed":false,"short":["午前十時からです","八時間です","よる八時までです"],"answer":3,"why":["十時から is the opening time. The man asks 何時まで, until what time.","八時間 is how many hours. The man asks for a clock time with 何時.",""],"clip":"l_n5u5d1"},"audio":[["M","すみません、この　店は　何時までですか。","すみません、この　みせは　なんじまでですか。"],["N","1","いち"],["F","午前　十時からです。","ごぜん　じゅうじからです。"],["N","2","に"],["F","八時間です。","はちじかんです。"],["N","3","さん"],["F","よる　八時までです。","よる　はちじまでです。"]]}},{"title":"〜前に・〜後で","grammar":{"points":[{"id":"n5u05d2.p1","form":"〜前に","gloss":"before …","connect":[{"pos":"Verb, dictionary form (learn these as set shapes; the full rule comes in unit 7)","rule":"ねる・[食|た]べる・[行|い]く ＋ {[前|まえ]に}"},{"pos":"Verb, from the polite ます form","rule":"[飲|の]みます → [飲|の]む ＋ {[前|まえ]に}"},{"pos":"Noun (〜)","rule":"〜 ＋ の ＋ {[前|まえ]に}"}],"examples":[{"ja":"ねる{[前|まえ]に}、まどを　しめます。","en":"I close the window before I go to sleep.","clip":"x_n5u05d2_p1_1"},{"ja":"ごはんの{[前|まえ]に}、[手|て]をあらいます。","en":"I wash my hands before meals.","clip":"x_n5u05d2_p1_2"}],"watch":{"note":"The verb before 前に is always the dictionary form, even when the story is in the past. The た-form never goes before 前に.","bad":"食べた前に、手をあらいました。","good":"食べる前に、手をあらいました。"}},{"id":"n5u05d2.p2","form":"〜後で","gloss":"after …","connect":[{"pos":"Verb, た-form (learn these as set shapes; the full rule comes in unit 7)","rule":"[食|た]べた・ねた・[見|み]た ＋ {[後|あと]で}"},{"pos":"Verb, from the polite ました form","rule":"[食|た]べました → [食|た]べた ＋ {[後|あと]で}"},{"pos":"Noun (〜)","rule":"〜 ＋ の ＋ {[後|あと]で}"}],"examples":[{"ja":"[食|た]べた{[後|あと]で}、くすりを[飲|の]みます。","en":"I take my medicine after eating.","clip":"x_n5u05d2_p2_1"},{"ja":"じゅぎょうの{[後|あと]で}、[友|とも]だちとテニスをしました。","en":"After class, I played tennis with a friend.","clip":"x_n5u05d2_p2_2"}],"watch":{"note":"The verb before 後で is always the た-form, even when you talk about tomorrow or every day. The dictionary form never goes before 後で.","bad":"食べる後で、はをみがきます。","good":"食べた後で、はをみがきます。"}}],"compare":{"intro":"All three say when you do something. 前に and 後で place it next to another action; に points to a clock time.","forms":[{"form":"〜前に","tag":"まえ · before","mark":"dot","ja":"ねる{[前|まえ]に}、シャワーをあびます。","en":"I take a shower before I go to bed."},{"form":"〜後で","tag":"あと · after","mark":"dot","ja":"ごはんの{[後|あと]で}、シャワーをあびます。","en":"I take a shower after dinner."},{"form":"〜に","tag":"じこく · at (a time)","mark":"dot","ja":"[九時|くじ]{に}、シャワーをあびます。","en":"I take a shower at nine."}],"check":{"id":"n5u05d2.c1","kind":"choice","type":"文の文法1","label":"くすりの じかん","q":"[食|た]べた（　　）、くすりを[飲|の]みます。","options":["に","[前|まえ]に","[後|あと]で"],"answer":3,"why":["に goes after a clock time such as 九時, not after a verb.","前に takes the dictionary form: 食べる前に. 食べた does not go before 前に.","食べた is the た-form, and 後で comes after it: 食べた後で, \"after eating\"."],"explain":null}},"drill":[{"id":"n5u05d2.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[学校|がっこう]へ^[行|い]く^（　　）、しんぶんを[読|よ]みます。","options":["[前|まえ]に","[後|あと]で","の[前|まえ]に","[前|まえ]で"],"answer":1,"why":["行く is the dictionary form, and 前に comes right after it: 行く前に.","後で takes the た-form: 行った後で. 行く does not go before 後で.","の goes after a noun, as in ごはんの前に. 行く is a verb.","前で is a place, \"in front of\" something. Here you need a time, 前に."]},{"id":"n5u05d2.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[友|とも]だちが^[来|き]た^（　　）、いっしょにごはんを[食|た]べました。","options":["の[後|あと]で","まで","[後|あと]で","[前|まえ]に"],"answer":3,"why":["の goes after a noun, as in じゅぎょうの後で. 来た is a verb.","まで does not go after 来た. It would also mean \"until\", which does not fit eating together.","来た is the た-form, and 後で comes right after it: 来た後で, \"after my friend came\".","前に takes the dictionary form: 来る前に. 来た does not go before 前に."],"explain":null},{"id":"n5u05d2.d3","kind":"choice","type":"文の文法1","label":"Choose the word","q":"しゅくだい（　　）^[前|まえ]に^、[少|すこ]し[休|やす]みます。","options":["の","を","に","で"],"answer":1,"why":["しゅくだい is a noun, and a noun takes の before 前に: しゅくだいの前に.","を marks the thing you act on. It cannot join a noun to 前に.","に cannot join a noun to 前に. Only の can.","で cannot join a noun to 前に. Only の can."]},{"id":"n5u05d2.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"えいがを（　　）^[後|あと]で^、[友|とも]だちとごはんを[食|た]べました。","options":["[見|み]る","[見|み]ます","[見|み]て","[見|み]た"],"answer":4,"why":["見る is the dictionary form. It goes before 前に, not 後で.","The polite ます form does not go before 後で.","見て is a different form (unit 6). It does not go before 後で.","後で takes the た-form: 見た後で, \"after watching\"."],"explain":null},{"id":"n5u05d2.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[日本|にほん]へ","after":"[買|か]いました。","tiles":["[来|く]る","[前|まえ]に","[日本語|にほんご]の","[本|ほん]を"],"star":1,"bank":[2,0,3,1],"hint":"日本へ needs a verb right after it. Which form of くる goes before 前に?","full":"[日本|にほん]へ[来|く]る{[前|まえ]に}[日本語|にほんご]の[本|ほん]を[買|か]いました。","explain":"日本へ goes with 来る, and the dictionary form 来る comes before 前に. 日本語の describes 本, and 本を is what was bought."},{"id":"n5u05d2.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"じゅぎょうが","after":"。","tiles":["おわった","[後|あと]で","[先生|せんせい]と","[話|はな]しました"],"star":1,"bank":[3,1,0,2],"hint":"じゅぎょうが needs a verb right after it. 後で follows the た-form.","full":"じゅぎょうがおわった{[後|あと]で}[先生|せんせい]と[話|はな]しました。","explain":"じゅぎょうが goes with おわった, the た-form, and 後で comes right after it. 先生と goes before the verb 話しました, which ends the sentence."}],"exam":[{"id":"n5u05d2.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"テレビを　見る　（　　）、しゅくだいを　します。","options":["の　前に","前で","前に","後で"],"answer":3,"explain":"見る is the dictionary form, so 前に comes after it: 見る前に. 後で needs the た-form (見た後で), の goes only after a noun, and 前で means \"in front of\" a place."},{"id":"n5u05d2.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"シャワーを　（　　）　後で、ばんごはんを　食べます。","options":["あびる","あびます","あびて","あびた"],"answer":4,"explain":"後で takes the た-form, even for every day: あびた後で. あびる goes before 前に, the polite ます form does not go before 後で, and あびて is a different form."},{"id":"n5u05d2.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"シャワーは　いつも　","after":"。","tiles":["学校へ","行く","前に","あびます"],"star":2,"bank":[3,2,0,1],"full":"シャワーは　いつも　学校へ　行く　{前に}　あびます。","explain":"学校へ, 行く, 前に, あびます. 学校へ goes with 行く, the dictionary form 行く comes before 前に, and the verb あびます ends the sentence."}]},"scene":{"ja":"くすりのふくろ","en":"A medicine bag from the clinic","intro":"Tap every word you can find on the medicine bag.","words":[{"id":"beforemeal","word":"食前","reading":"しょくぜん","gloss":"before meals","parts":[["食","ショク","eat, food"],["前","ゼン","before"]],"clip":"s_n5u5d2_beforemeal"},{"id":"aftermeal","word":"食後","reading":"しょくご","gloss":"after meals","parts":[["食","ショク","eat, food"],["後","ゴ","after"]],"clip":"s_n5u5d2_aftermeal"},{"id":"everyday","word":"毎日","reading":"まいにち","gloss":"every day","parts":[["毎","マイ","every"],["日","ニチ","day"]],"clip":"s_n5u5d2_everyday"},{"id":"oneday","word":"一日","reading":"いちにち","gloss":"one day, a day","parts":[["一","イチ","one"],["日","ニチ","day"]],"clip":"s_n5u5d2_oneday"},{"id":"threetimes","word":"三かい","reading":"さんかい","gloss":"three times","parts":[["三","サン","three"]],"clip":"s_n5u5d2_threetimes"},{"id":"white","word":"白い","reading":"しろい","gloss":"white","parts":[["白","しろ","white"]],"clip":"s_n5u5d2_white"},{"id":"water","word":"水","reading":"みず","gloss":"water","parts":[["水","みず","water"]],"clip":"s_n5u5d2_water"},{"id":"time","word":"時間","reading":"じかん","gloss":"time, hours","parts":[["時","ジ","time"],["間","カン","space between"]],"clip":"s_n5u5d2_time"}],"check":{"id":"n5u05d2.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"この　くすりは　_毎日_　飲みます。","options":["まいじつ","まいにち","まいび","めいにち"],"answer":2,"explain":"毎日 is read まいにち, \"every day\". まいび, めいにち and まいじつ are not readings of 毎日."}},"skill":{"kind":"reading","ja":"内容理解（短文）","en":"Short passage","ask":"What does the writer do, and in what order?","seconds":90,"passage":"わたしは　毎日　六時半に　おきます。^おきた　後で^、^水を　一ぱい　飲みます^。^それから^、あさごはんを　食べます。学校の　後で、友だちと　テニスを　します。ばんごはんの　前に、おふろに　入ります。ねる　前に、日本語の　本を　読みます。","strategy":"Find the action in the question in the text, then use 前に, 後で and それから to see what comes before it and what comes after it.","item":{"id":"n5u05d2.r1","kind":"choice","type":"読解・内容理解（短文）","q":"この　人は　あさごはんの　前に　何を　しますか。","options":["日本語の　本を　読みます。","水を　飲みます。","テニスを　します。","おふろに　入ります。"],"short":["日本語の本を読む","水を飲む","テニスをする","おふろに入る"],"answer":2,"explain":"After getting up, the writer drinks a glass of water (おきた後で、水を一ぱい飲みます). それから (after that) comes breakfast, so the water is before breakfast.","why":["The writer reads before going to bed (ねる前に), not before breakfast.","","Tennis is after school (学校の後で), so it comes after breakfast.","The bath is before dinner (ばんごはんの前に), not before breakfast."]}}},{"title":"〜てから・〜とき","grammar":{"points":[{"id":"n5u05d3.p1","form":"〜てから","gloss":"after doing A, then B","connect":[{"pos":"Verb, te-form (ends in て or で)","rule":"[食|た]べ{てから}、〜／[読|よ]ん{でから}、〜"},{"pos":"Te-forms to learn as fixed shapes for now (unit 6 teaches how to make them)","rule":"[食|た]べます→[食|た]べ{て}／[見|み]ます→[見|み]{て}／します→し{て}／[行|い]きます→[行|い]{って}"},{"pos":"More fixed te-forms for now","rule":"[読|よ]みます→[読|よ]{んで}／[飲|の]みます→[飲|の]{んで}／かえります→かえ{って}／あらいます→あら{って}"}],"examples":[{"ja":"うちへかえっ{てから}、[本|ほん]を[読|よ]みます。","en":"After I get home, I read a book.","clip":"x_n5u05d3_p1_1"},{"ja":"[手|て]をあらっ{てから}、ごはんを[食|た]べましょう。","en":"Let's wash our hands and then eat.","clip":"x_n5u05d3_p1_2"}],"watch":{"note":"から goes after the te-form. It does not join the ます stem: 読みてから is wrong. Say 読んでから.","bad":"本を読みてから、ねます。","good":"本を読んでから、ねます。"}},{"id":"n5u05d3.p2","form":"〜とき","gloss":"when …, at the time of …","connect":[{"pos":"Noun (〜 is a noun such as 子ども): add の","rule":"〜の{とき}／[子|こ]どもの{とき}"},{"pos":"な-adjective: keep な","rule":"ひまな{とき}"},{"pos":"い-adjective, or a verb in its dictionary form (行く, not 行きます)","rule":"さむい{とき}／[日本|にほん]へ[行|い]く{とき}"}],"examples":[{"ja":"[子|こ]どもの{とき}、よく[川|かわ]でおよぎました。","en":"When I was a child, I often swam in the river.","clip":"x_n5u05d3_p2_1"},{"ja":"さむい{とき}は、あたたかいおちゃを[飲|の]みます。","en":"When it is cold, I drink hot tea.","clip":"x_n5u05d3_p2_2"}],"watch":{"note":"A noun needs の before とき. 子どもとき is wrong.","bad":"子どもとき、魚がきらいでした。","good":"子どものとき、魚がきらいでした。"}}],"compare":{"intro":"てから and 後で both put two things in order. とき says when something happens.","forms":[{"form":"〜てから","tag":"〜て＋から · A first, then B","mark":"dot","ja":"しゅくだいをし{てから}、あそびます。","en":"I do my homework, and then I play."},{"form":"〜とき","tag":"〜の／〜な／〜い＋とき · at the time when","mark":"dot","ja":"ひまな{とき}、[本|ほん]を[読|よ]みます。","en":"When I am free, I read books."},{"form":"〜の後で","tag":"〜の＋後で · after an event","mark":"dot","ja":"じゅぎょうの{[後|あと]で}、[友|とも]だちと[話|はな]します。","en":"After class, I talk with my friends."}],"check":{"id":"n5u05d3.c1","kind":"choice","type":"文の文法1","label":"むかしのはなし","q":"わたしは[子|こ]ども（　　）、[魚|さかな]がきらいでした。","options":["てから","のとき","の[後|あと]で"],"answer":2,"why":["てから goes after a verb in the te-form. 子ども is a noun.","子ども is a noun, so の joins it to とき: \"when I was a child\".","の後で means \"after\". \"After a child\" makes no sense here."]}},"drill":[{"id":"n5u05d3.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[手|て]を（　　）、^ごはんを[食|た]べます^。","options":["あらいてから","あらってから","あらうてから","あらいから"],"answer":2,"why":["あらいて is not a word. The te-form of あらいます is あらって.","あらって is the te-form of あらいます. あらってから: wash first, then eat.","あらうて is not a word. Use the te-form あらって.","から does not join あらい. For \"after\", use the te-form: あらってから."]},{"id":"n5u05d3.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：^いつ^テレビを[見|み]ますか。B：しゅくだいを（　　）[見|み]ます。","options":["しますてから","してから","するから","しから"],"answer":2,"why":["てから does not go after します. Use the te-form: してから.","して is the te-form of します. してから answers いつ: after the homework.","するから means \"because I do\", not \"after\". It does not answer いつ.","から does not join し. Use the te-form: してから."],"explain":null},{"id":"n5u05d3.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^[大学生|だいがくせい]^（　　）、よくテニスをしました。","options":["でとき","とき","のとき","なとき"],"answer":3,"why":["で does not join a noun to とき. Use の.","大学生 is a noun. A noun needs の before とき.","大学生 is a noun, so の joins it to とき: \"when I was a university student\".","な is for な-adjectives such as ひま. 大学生 is a noun."],"explain":null},{"id":"n5u05d3.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"（　　）^とき^、[友|とも]だちに[電話|でんわ]をします。","options":["ひまい","ひま","ひまな","ひまだ"],"answer":3,"why":["ひまい is not a word. ひま is a な-adjective.","ひま is a な-adjective. It keeps な before とき: ひまなとき.","ひま is a な-adjective, and な joins it to とき: \"when I am free\".","だ ends a sentence. ひまだ cannot come right before とき."],"explain":null},{"id":"n5u05d3.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[毎|まい]ばん","after":"[見|み]ます。","tiles":["しゅくだいを","して","から","テレビを"],"star":2,"bank":[3,1,0,2],"hint":"から comes right after the te-form して. What do you do first?","full":"[毎|まい]ばんしゅくだいをして{から}テレビを[見|み]ます。","explain":"しゅくだいを, して, から, テレビを. してから puts the homework first, and テレビを goes with 見ます: \"Every evening I do my homework and then watch TV.\""},{"id":"n5u05d3.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[日本|にほん]へ","after":"を[買|か]いました。","tiles":["[行|い]く","とき","[新|あたら]しい","かばん"],"star":1,"bank":[2,0,3,1],"hint":"日本へ goes with 行く, and とき follows it. 新しい goes right before the thing you bought.","full":"[日本|にほん]へ[行|い]く{とき}[新|あたら]しいかばんを[買|か]いました。","explain":"行く, とき, 新しい, かばん. 日本へ行くとき is \"when I went to Japan\", and 新しい describes かばん: \"When I went to Japan, I bought a new bag.\""}],"exam":[{"id":"n5u05d3.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あさは　シャワーを　あびて（　　）、　ごはんを　食べます。","options":["ので","まえに","とき","から"],"answer":4,"explain":"あびて is the te-form, and から after it gives the order: shower first, then breakfast. まえに and とき follow the dictionary form (あびる), not the te-form, and ので never follows the te-form."},{"id":"n5u05d3.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"へやが　しずか（　　）　とき、　本を　読みます。","options":["で","の","な","に"],"answer":3,"explain":"しずか is a な-adjective, so it keeps な before とき: \"When the room is quiet, I read.\" の is for a noun (子どもの　とき), and に and で cannot join a word to とき."},{"id":"n5u05d3.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"毎あさ","after":"読みます。","tiles":["コーヒーを","飲んで","から","新聞を"],"star":2,"bank":[3,0,2,1],"full":"毎あさ　コーヒーを　飲んで　{から}　新聞を　読みます。","explain":"コーヒーを, 飲んで, から, 新聞を. 飲んでから puts the coffee first, and 新聞を goes with 読みます: \"Every morning I drink coffee and then read the newspaper.\""}]},"scene":{"ja":"としょかんで","en":"At a library","intro":"Tap every word you would read on the notice at the library door.","words":[{"id":"entrance","word":"入口","reading":"いりぐち","gloss":"entrance","parts":[["入","いり","enter"],["口","ぐち","mouth, opening"]],"clip":"s_n5u5d3_entrance"},{"id":"exit","word":"出口","reading":"でぐち","gloss":"exit","parts":[["出","で","go out"],["口","ぐち","mouth, opening"]],"clip":"s_n5u5d3_exit"},{"id":"closed","word":"休み","reading":"やすみ","gloss":"closed (day), holiday","parts":[["休","やす","rest"]],"clip":"s_n5u5d3_closed"},{"id":"hours","word":"時間","reading":"じかん","gloss":"hours, time","parts":[["時","ジ","time, hour"],["間","カン","between, interval"]],"clip":"s_n5u5d3_hours"},{"id":"book","word":"本","reading":"ほん","gloss":"book","parts":[["本","ホン","book, origin"]],"clip":"s_n5u5d3_book"},{"id":"talk","word":"話す","reading":"はなす","gloss":"to talk","parts":[["話","はな","talk"]],"clip":"s_n5u5d3_talk"},{"id":"food","word":"食べもの","reading":"たべもの","gloss":"food","parts":[["食","た","eat"]],"clip":"s_n5u5d3_food"},{"id":"drinks","word":"飲みもの","reading":"のみもの","gloss":"drinks","parts":[["飲","の","drink"]],"clip":"s_n5u5d3_drinks"}],"check":{"id":"n5u05d3.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"としょかんの　_入口_は　あちらです。","options":["いりくち","でぐち","いりぐち","にゅうぐち"],"answer":3,"explain":"入口, \"entrance\", is read いりぐち: 口 becomes ぐち after いり. でぐち is 出口, \"exit\". いりくち and にゅうぐち are not words."}},"skill":{"kind":"listening","ja":"ポイント理解","en":"Point comprehension","ask":"女の人は　うちへ　かえってから、　はじめに　何を　しますか。","audio":[["N","女の人と男の人が話しています。女の人はうちへかえってから、はじめに何をしますか。","おんなのひとと　おとこのひとが　はなしています。おんなのひとは　うちへ　かえってから、はじめに　なにを　しますか。"],["M","川口さん、きょう、しごとの後で、いっしょにごはんを食べませんか。","かわぐちさん、きょう、しごとの　あとで、いっしょに　ごはんを　たべませんか。"],["F","すみません。きょうはとしょかんへ行きます。本をかえします。","すみません。きょうは　としょかんへ　いきます。ほんを　かえします。"],["M","そうですか。",null],["F","としょかんへ行ってから、スーパーで買いものをします。","としょかんへ　いってから、スーパーで　かいものを　します。"],["M","たいへんですね。うちへかえってから、すぐばんごはんをつくりますか。",null],["F","いいえ。うちへかえってから、はじめに母に電話をします。ばんごはんはその後です。","いいえ。うちへ　かえってから、はじめに　ははに　でんわを　します。ばんごはんは　その　あとです。"],["M","そうですか。",null],["N","女の人はうちへかえってから、はじめに何をしますか。","おんなのひとは　うちへ　かえってから、はじめに　なにを　しますか。"]],"item":{"id":"n5u05d3.r1","kind":"choice","type":"ポイント理解","q":"女の人は　うちへ　かえってから、　はじめに　何を　しますか。","script":["ナレーター：女の人と男の人が話しています。女の人はうちへかえってから、はじめに何をしますか。","男：川口さん、きょう、しごとの後で、いっしょにごはんを食べませんか。","女：すみません。きょうはとしょかんへ行きます。本をかえします。","男：そうですか。","女：としょかんへ行ってから、スーパーで買いものをします。","男：たいへんですね。うちへかえってから、すぐばんごはんをつくりますか。","女：いいえ。うちへかえってから、はじめに母に電話をします。ばんごはんはその後です。","男：そうですか。","ナレーター：女の人はうちへかえってから、はじめに何をしますか。"],"options":["ばんごはんを　つくります","としょかんへ　行きます","スーパーで　買いものを　します","母に　電話を　します"],"printed":true,"short":["ばんごはん","としょかんへ 行く","スーパーで 買いもの","母に 電話"],"answer":4,"why":["The man asks about dinner, but she says いいえ. Dinner comes after the call (ばんごはんはその後です).","She goes to the library before she gets home (としょかんへ行ってから、スーパーで…).","She shops at the supermarket after the library, also before she gets home.","At home she first calls her mother: うちへかえってから、はじめに母に電話をします."],"explain":null,"clip":"l_n5u5d3"}}},{"title":"〜ながら・〜たり〜たりする","grammar":{"points":[{"id":"n5u05d4.p1","form":"〜ながら","gloss":"while (two things at once)","connect":[{"pos":"Verb, ます form without ます","rule":"[聞|き]きます → [聞|き]き ＋ {ながら}"},{"pos":"する verbs work the same way","rule":"べんきょうします → べんきょうし ＋ {ながら}"},{"pos":"The main action comes last, with the polite ending","rule":"〜{ながら}、〜ます"}],"examples":[{"ja":"おんがくを[聞|き]き{ながら}、しゅくだいをします。","en":"I do my homework while listening to music.","clip":"x_n5u05d4_p1_1"},{"ja":"[友|とも]だちと[話|はな]し{ながら}、[駅|えき]まであるきました。","en":"I walked to the station while talking with a friend.","clip":"x_n5u05d4_p1_2"}],"watch":{"note":"ながら goes on the ます form with ます taken off: 聞きます becomes 聞き. Do not keep ます.","bad":"おんがくを聞きますながら、しゅくだいをします。","good":"おんがくを聞きながら、しゅくだいをします。"}},{"id":"n5u05d4.p2","form":"〜たり〜たりします","gloss":"do things like A and B","connect":[{"pos":"Verb, た form (A), then verb, た form (B), then します","rule":"〜た{り}、〜た{り} ＋ します"},{"pos":"The た form comes in unit 7. For now, learn these common ones as set shapes","rule":"[見|み]{たり}　[食|た]べ{たり}　[行|い]っ{たり}　し{たり}"},{"pos":"Verbs whose た form ends in だ take だり","rule":"[読|よ]ん{だり}　およい{だり}　あそん{だり}"}],"examples":[{"ja":"[日|にち]よう[日|び]は[本|ほん]を[読|よ]ん{だり}、テレビを[見|み]{たり}します。","en":"On Sundays I do things like read books and watch TV.","clip":"x_n5u05d4_p2_1"},{"ja":"[休|やす]みの[日|ひ]は[山|やま]へ[行|い]っ{たり}、[川|かわ]でおよい{だり}します。","en":"On my days off I do things like go to the mountains and swim in the river.","clip":"x_n5u05d4_p2_2"}],"watch":{"note":"In a list with たり, give each action たり and end with します. Leaving たり off the second action is a common mistake.","bad":"日よう日は本を読んだり、テレビを見ます。","good":"日よう日は本を読んだり、テレビを見たりします。"}}],"compare":{"intro":"All three put two actions in one sentence. What changes is the timing.","forms":[{"form":"〜ながら","tag":"おなじとき · at the same time","mark":"dot","ja":"テレビを[見|み]{ながら}、ごはんを[食|た]べます。","en":"I eat while watching TV."},{"form":"〜たり〜たりします","tag":"いろいろ · things like","mark":"dot","ja":"[土|ど]よう[日|び]はそうじをし{たり}、[買|か]いものをし{たり}します。","en":"On Saturdays I do things like cleaning and shopping."},{"form":"〜てから","tag":"そのあとで · after","mark":"dot","ja":"ごはんを[食|た]べ{てから}、テレビを[見|み]ます。","en":"I watch TV after eating."}],"check":{"id":"n5u05d4.c1","kind":"choice","type":"文の文法1","label":"しゅくだい","q":"いつもおんがくを^[聞|き]き^（　　）、しゅくだいをします。","options":["てから","ながら","たり"],"answer":2,"why":["てから goes on the て form: 聞いてから. 聞きてから is not a form.","聞き is the ます form without ます, and ながら joins it: two things at the same time.","たり goes on the た form: 聞いたり. 聞きたり is not a form."],"explain":null}},"drill":[{"id":"n5u05d4.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[父|ちち]はいつもラジオを（　　）、^[車|くるま]をあらいます^。","options":["[聞|き]いてながら","[聞|き]きますながら","[聞|き]きながら","[聞|き]くながら"],"answer":3,"why":["聞いて is the て form. ながら does not go on it.","ます has to come off before ながら: 聞き, not 聞きます.","The ます form without ます, then ながら: he listens while he washes the car.","聞く is the dictionary form. ながら does not go on it."],"explain":null},{"id":"n5u05d4.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ジュースを[飲|の]み（　　）、^[友|とも]だちと[話|はな]しました^。","options":["まで","ながら","たり","から"],"answer":2,"why":["まで does not join 飲み.","飲み is the ます form without ます. With ながら, she drinks and talks at the same time.","たり goes on the た form: 飲んだり. 飲みたり is not a form.","から does not join 飲み. It would need 飲んでから."],"explain":null},{"id":"n5u05d4.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[休|やす]みの[日|ひ]は、[本|ほん]を^[読|よ]んだり^、テレビを（　　）します。","options":["[見|み]たり","[見|み]ながら","[見|み]て","[見|み]ます"],"answer":1,"why":["読んだり comes first, so the second action takes たり too, then します.","見ながら needs a main action after it. します alone does not say what you do.","見て cannot come right before します here.","見ます is already an ending. It cannot come before another します."]},{"id":"n5u05d4.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きのうは[友|とも]だちとカレーを（　　）、^[話|はな]したり^しました。","options":["[食|た]べますたり","[食|た]べるたり","[食|た]べたり","[食|た]べだり"],"answer":3,"why":["たり does not go on the ます form.","たり does not go on the dictionary form.","The た form of 食べます is 食べた, so 食べたり, paired with 話したり.","だり is only for verbs whose た form ends in だ, like 読んだ. 食べた ends in た."],"explain":null},{"id":"n5u05d4.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[母|はは]は","after":"。","tiles":["うたを","うたい","ながら","りょうりをします"],"star":1,"bank":[2,3,0,1],"hint":"Which action is the main one? It comes last, with the polite ending.","full":"[母|はは]はうたをうたい{ながら}りょうりをします。","explain":"うたを comes before うたい, and ながら goes right after the stem うたい. Cooking is the main action, so りょうりをします goes last."},{"id":"n5u05d4.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[日|にち]よう[日|び]は[山|やま]へ","after":"します。","tiles":["[行|い]ったり","[友|とも]だちの","うちで","あそんだり"],"star":1,"bank":[3,1,0,2],"hint":"What do you do with 山へ? Then: whose house?","full":"[日|にち]よう[日|び]は[山|やま]へ[行|い]っ{たり}[友|とも]だちのうちであそん{だり}します。","explain":"山へ goes with 行ったり. 友だちの describes うち, so 友だちの comes right before うちで, and あそんだり follows, before します."}],"exam":[{"id":"n5u05d4.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ラジオを　（　　）　ながら、そうじを　します。","options":["聞いて","聞きます","聞き","聞く"],"answer":3,"explain":"ながら goes on the ます form without ます: 聞きながら. It does not go on the dictionary form 聞く, the て form 聞いて, or 聞きます with ます still on."},{"id":"n5u05d4.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"休みの　日は　そうじを　したり、せんたくを　（　　）　します。","options":["しながら","して","します","したり"],"answer":4,"explain":"The first action has したり, so the second takes たり too, and します ends the list: せんたくを したり します. しながら needs a main action after it, and して and します cannot come right before します."},{"id":"n5u05d4.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"父は　いつも","after":"を　飲みます。","tiles":["新聞を","読み","ながら","コーヒー"],"star":2,"bank":[3,1,0,2],"full":"父は　いつも　新聞を　読み{ながら}　コーヒーを　飲みます。","explain":"新聞を, 読み, ながら, コーヒー: he drinks coffee while reading the newspaper. 新聞を goes with 読み, ながら follows the stem, and コーヒー sits right before を 飲みます."}]},"scene":{"ja":"センターのちらし","en":"A community centre flyer","intro":"Tap each word on the weekend programme flyer.","words":[{"id":"sunday","word":"日よう日","reading":"にちようび","gloss":"Sunday","parts":[["日","ニチ","sun, day"],["日","び","day"]],"clip":"s_n5u5d4_sunday"},{"id":"am","word":"午前","reading":"ごぜん","gloss":"morning, a.m.","parts":[["午","ゴ","noon"],["前","ゼン","before"]],"clip":"s_n5u5d4_am"},{"id":"pm","word":"午後","reading":"ごご","gloss":"afternoon, p.m.","parts":[["午","ゴ","noon"],["後","ゴ","after"]],"clip":"s_n5u5d4_pm"},{"id":"mountain","word":"山","reading":"やま","gloss":"mountain","parts":[["山","やま","mountain"]],"clip":"s_n5u5d4_mountain"},{"id":"flower","word":"花","reading":"はな","gloss":"flower","parts":[["花","はな","flower"]],"clip":"s_n5u5d4_flower"},{"id":"listen","word":"聞く","reading":"きく","gloss":"to listen, to hear","parts":[["聞","き","hear"]],"clip":"s_n5u5d4_listen"},{"id":"speak","word":"話す","reading":"はなす","gloss":"to speak, to talk","parts":[["話","はな","talk"]],"clip":"s_n5u5d4_speak"},{"id":"eat","word":"食べる","reading":"たべる","gloss":"to eat","parts":[["食","た","eat"]],"clip":"s_n5u5d4_eat"}],"check":{"id":"n5u05d4.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_午後_　二時から　山の　話を　聞きます。","options":["ごご","ごうご","ごこ","ごぜん"],"answer":1,"explain":"午後 is ごご, the afternoon. ごぜん is 午前, the morning. ごうご and ごこ are not words."}},"skill":{"kind":"reading","ja":"内容理解（短文）","en":"Short passage","ask":"What does the writer do on Sunday afternoons?","seconds":90,"passage":"わたしは　日よう日の　午前、よく　こうえんへ　行きます。おんがくを　聞きながら　はしります。^午後は　友だちと　きっさてんで　話したり、本やで　本を　見たり^　します。よるは　うちで　テレビを　見ながら　ばんごはんを　食べます。","strategy":"Find 午後 in the passage and read what comes right after it.","item":{"id":"n5u05d4.r1","kind":"choice","type":"読解・内容理解（短文）","q":"この　人は　日よう日の　午後、何を　しますか。","options":["うちで　おんがくを　聞きます。","こうえんで　はしります。","きっさてんや　本やへ　行きます。","テレビを　見ながら　ばんごはんを　食べます。"],"short":["うちでおんがくを聞く","こうえんではしる","きっさてんや本やへ行く","テレビを見ながらばんごはん"],"answer":3,"explain":"After 午後は, the writer talks with friends at a coffee shop and looks at books in a bookshop: they go to both places.","why":["The writer listens to music while running in the park in the morning, not at home.","Running in the park is in the morning (午前).","","Dinner in front of the TV is in the evening (よる)."]}}},{"title":"もう・まだ","grammar":{"points":[{"id":"n5u05d5.p1","form":"もう","gloss":"already; not any more","connect":[{"pos":"Verb, past polite (ました)","rule":"{もう}〜ました"},{"pos":"Asking if it has happened","rule":"{もう}〜ましたか"},{"pos":"With a \"not\" ending: not any more","rule":"{もう}〜ません"}],"examples":[{"ja":"ひるごはんは{もう}[食|た]べました。","en":"I have already eaten lunch.","clip":"x_n5u05d5_p1_1"},{"ja":"A「[白|しろ]いかさはありますか。」B「すみません、{もう}ありません。」","en":"A: Do you have white umbrellas? B: Sorry, there are none left.","clip":"x_n5u05d5_p1_2"}],"watch":{"note":"\"Already\" is もう. まだ means \"not yet\" or \"still\", so it does not fit a finished action like 食べました.","bad":"ひるごはんはまだ食べました。","good":"ひるごはんはもう食べました。"}},{"id":"n5u05d5.p2","form":"まだ","gloss":"not yet; still","connect":[{"pos":"Answering もう〜ましたか: not yet","rule":"いいえ、{まだ}です"},{"pos":"Noun: still","rule":"{まだ}〜です"},{"pos":"With あります: still have","rule":"{まだ}〜があります"}],"examples":[{"ja":"A「もうきっぷを[買|か]いましたか。」B「いいえ、{まだ}です。」","en":"A: Have you bought the ticket yet? B: No, not yet.","clip":"x_n5u05d5_p2_1"},{"ja":"[外|そと]は{まだ}[雨|あめ]です。","en":"It is still raining outside.","clip":"x_n5u05d5_p2_2"}],"watch":{"note":"To answer \"not yet\", say いいえ、まだです. 食べませんでした tells about a past time you did not eat, so it does not mean \"not yet\".","bad":"A「もう食べましたか。」B「いいえ、まだ食べませんでした。」","good":"A「もう食べましたか。」B「いいえ、まだです。」"}}],"compare":{"intro":"もう says it has already happened, まだ says it has not happened yet, and ませんでした says you did not do it at some time in the past.","forms":[{"form":"もう〜ました","tag":"もう · already","mark":"dot","ja":"しゅくだいは{もう}しました。","en":"I have already done my homework."},{"form":"まだです","tag":"まだ · not yet","mark":"down","ja":"しゅくだいは{まだ}です。","en":"My homework is not done yet."},{"form":"〜ませんでした","tag":"しませんでした · did not","mark":"down","ja":"きのうはしゅくだいを{しませんでした}。","en":"I did not do my homework yesterday."}],"check":{"id":"n5u05d5.c1","kind":"choice","type":"文の文法1","label":"しゅくだい","q":"A「もうしゅくだいをしましたか。」B「^いいえ^、（　　）。^これからします^。」","options":["しませんでした","まだです","もうしました"],"answer":2,"why":["しませんでした tells about a past time. It does not answer もう〜ましたか; for \"not yet\" say まだです.","B says いいえ and will do it from now, so it is not done yet: まだです.","もうしました means it is already done, but B says いいえ and これからします."],"explain":null}},"drill":[{"id":"n5u05d5.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「いっしょにひるごはんを[食|た]べませんか。」B「^すみません^、^もう^（　　）。」","options":["[食|た]べました","[食|た]べましょう","[食|た]べませんか","[食|た]べたいです"],"answer":1,"why":["B has already eaten, so B says sorry: もう食べました, \"I have already eaten.\"","食べましょう says yes to the plan, but B says すみません to turn it down.","食べませんか is an invitation. A is the one inviting; B is answering.","B says すみません to say no. もう食べたいです does not turn A down."]},{"id":"n5u05d5.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あんパンはありますか。」B「^すみません^、[今日|きょう]は^もう^（　　）。」","options":["ありました","ありませんでした","ありません","あります"],"answer":3,"why":["ありました is the past. The customer asks about now.","ありませんでした is the past. The bread is gone now, so the shop says ありません.","もう with a \"not\" ending means \"not any more\": they are sold out now.","すみません tells us the news is bad. もうあります does not say they are gone."],"explain":null},{"id":"n5u05d5.d3","kind":"choice","type":"文の文法1","label":"Choose the answer","q":"A「もう[駅|えき]につきましたか。」B「^いいえ^、（　　）。^あと[五分|ごふん]ぐらいです^。」","options":["まだです","もうつきました","つきませんでした","もうありません"],"answer":1,"why":["B is not at the station yet; five more minutes. いいえ、まだです is \"not yet\".","もうつきました means he has arrived, but he says いいえ and five more minutes.","つきませんでした tells about a past time. To answer もう〜ましたか with \"not yet\", say まだです.","もうありません means \"there is none any more\". It does not answer \"have you arrived?\"."]},{"id":"n5u05d5.d4","kind":"choice","type":"文の文法1","label":"Choose the word","q":"[電車|でんしゃ]は[九時|くじ]です。^[今|いま]は[八時|はちじ]です^。（　　）[時間|じかん]がありますね。","options":["いつ","ぜんぜん","まだ","もう"],"answer":3,"why":["いつ asks \"when\". This sentence is not a question.","ぜんぜん goes with a \"not\" ending like ありません. Here the verb is あります.","It is eight and the train is at nine, so there is still time: まだ時間があります.","With an hour left, the speaker means \"still\", and that is まだ. もう here would sound like time is running out."],"explain":null},{"id":"n5u05d5.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"すみません、[九時|くじ]の","after":"。","tiles":["[電車|でんしゃ]","は","もう","[出|で]ました"],"star":2,"bank":[3,2,0,1],"hint":"九時の describes a noun. Then the topic with は, then もう before the verb.","full":"すみません、[九時|くじ]の[電車|でんしゃ]は{もう}[出|で]ました。","explain":"九時の goes before 電車. は makes the train the topic, and もう comes before 出ました: \"The nine o'clock train has already left.\""},{"id":"n5u05d5.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「おとうとさんは[大学生|だいがくせい]ですか。」B「いいえ、おとうとは","after":"。」","tiles":["まだ","[十六|じゅうろく]","さい","です"],"star":0,"bank":[2,0,3,1],"hint":"まだ comes before the noun it is about. さい follows the number, and です comes last.","full":"A「おとうとさんは[大学生|だいがくせい]ですか。」B「いいえ、おとうとは{まだ}[十六|じゅうろく]さいです。」","explain":"まだ comes first, then 十六さい (sixteen years old), then です: \"He is still sixteen.\""}],"exam":[{"id":"n5u05d5.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　本、もう　読みましたか。」B「はい、（　　）。おもしろかったです。」","options":["もう　読みます","もう　読みました","まだ　読みました","まだです"],"answer":2,"explain":"B says はい and おもしろかったです, so B has finished the book: もう読みました. まだ does not go with a finished action like 読みました. まだです means \"not yet\", which does not fit はい. もう読みます talks about now or later, but B already read it."},{"id":"n5u05d5.e2","kind":"choice","type":"文の文法1","label":"Choose the word","q":"A「山下さんは　まだ　会社に　いますか。」B「いいえ、（　　）　いません。五時に　かえりました。」","options":["たくさん","すこし","もう","まだ"],"answer":3,"explain":"山下さん went home at five, so he is not at the office any more: もういません. まだいません would mean he has not come yet. たくさん and すこし tell how many or how much, and do not fit one person who has left."},{"id":"n5u05d5.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「何か　飲みませんか。」B「いいですね。でも、つめたい","after":"よ。」","tiles":["ジュース","は","もう","ありません"],"star":2,"bank":[2,3,0,1],"full":"A「何か　飲みませんか。」B「いいですね。でも、つめたいジュースは{もう}ありませんよ。」","explain":"ジュース, は, もう, ありません. つめたい describes ジュース, は makes it the topic, and もう with ありません means \"there is none left\"."}]},"scene":{"ja":"駅の電車の時間","en":"A train board at a small station","intro":"Tap every word on the board you need to know which trains have left and which are still to come.","words":[{"id":"train","word":"電車","reading":"でんしゃ","gloss":"train","parts":[["電","デン","electricity"],["車","シャ","vehicle"]],"clip":"s_n5u5d5_train"},{"id":"station","word":"駅","reading":"えき","gloss":"station","parts":[["駅","エキ","station"]],"clip":"s_n5u5d5_station"},{"id":"pm","word":"午後","reading":"ごご","gloss":"p.m., afternoon","parts":[["午","ゴ","noon"],["後","ゴ","after"]],"clip":"s_n5u5d5_pm"},{"id":"3oclock","word":"三時","reading":"さんじ","gloss":"three o'clock","parts":[["三","サン","three"],["時","ジ","o'clock, time"]],"clip":"s_n5u5d5_3oclock"},{"id":"20min","word":"二十分","reading":"にじゅっぷん","gloss":"twenty minutes; :20","parts":[["二","ニ","two"],["十","ジュッ","ten"],["分","プン","minute"]],"clip":"s_n5u5d5_20min"},{"id":"left","word":"出ました","reading":"でました","gloss":"has left","parts":[["出","で","go out, leave"]],"clip":"s_n5u5d5_left"},{"id":"coming","word":"来ます","reading":"きます","gloss":"will come","parts":[["来","き","come"]],"clip":"s_n5u5d5_coming"},{"id":"northexit","word":"北口","reading":"きたぐち","gloss":"north exit","parts":[["北","きた","north"],["口","ぐち","mouth, opening"]],"clip":"s_n5u5d5_northexit"}],"check":{"id":"n5u05d5.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"三時の　電車は　もう　_出ました_。","options":["でました","だしました","きました","いました"],"answer":1,"explain":"出ました is read でました, \"has left\". だしました would be written 出しました, with し. きました (来ました) and いました are other verbs."}},"skill":{"kind":"listening","ja":"課題理解","en":"Task comprehension","ask":"男の人は　このあと　何を　しますか。","audio":[["N","女の人と男の人が話しています。男の人は、このあと何をしますか。","おんなのひとと　おとこのひとが　はなしています。おとこのひとは、このあと　なにを　しますか。"],["F","あしたから、りょこうですね。もう、きっぷを買いましたか。","あしたから、りょこうですね。もう、きっぷを　かいましたか。"],["M","はい、きのう、駅で買いました。","はい、きのう、えきで　かいました。"],["F","ホテルは？",null],["M","ホテルにも、もう電話しました。","ホテルにも、もう　でんわしました。"],["F","じゃあ、かばんに、もうふくを入れましたか。","じゃあ、かばんに、もう　ふくを　いれましたか。"],["M","いいえ、まだです。",null],["F","え、まだですか。あしたの電車は、あさ七時ですよ。","え、まだですか。あしたの　でんしゃは、あさ　しちじですよ。"],["M","そうですね。じゃあ、今から入れます。おかしは、あした駅で買います。","そうですね。じゃあ、いまから　いれます。おかしは、あした　えきで　かいます。"],["N","男の人は、このあと何をしますか。","おとこのひとは、このあと　なにを　しますか。"]],"item":{"id":"n5u05d5.r1","kind":"choice","type":"課題理解","q":"男の人は　このあと　何を　しますか。","script":["ナレーター：女の人と男の人が話しています。男の人は、このあと何をしますか。","女：あしたから、りょこうですね。もう、きっぷを買いましたか。","男：はい、きのう、駅で買いました。","女：ホテルは？","男：ホテルにも、もう電話しました。","女：じゃあ、かばんに、もうふくを入れましたか。","男：いいえ、まだです。","女：え、まだですか。あしたの電車は、あさ七時ですよ。","男：そうですね。じゃあ、今から入れます。おかしは、あした駅で買います。","ナレーター：男の人は、このあと何をしますか。"],"options":["ホテルに　電話します","かばんに　ふくを　入れます","おかしを　買います","きっぷを　買います"],"printed":true,"short":["ホテルに 電話","ふくを 入れる","おかしを 買う","きっぷを 買う"],"answer":2,"why":["He already called the hotel: もう電話しました.","He has not packed yet (いいえ、まだです), and he says 今から入れます, \"I'll pack now.\"","He will buy snacks tomorrow at the station, not now.","He already bought the ticket yesterday at the station: はい、きのう、駅で買いました."],"explain":null,"clip":"l_n5u5d5"}}},{"title":"まとめ：似ている文法","grammar":{"points":[],"compare":{"intro":"To tell this unit's points apart, look at what comes before the blank: a clock time takes に, a start and an end take から and まで, the dictionary form goes before 前に, the た-form before 後で, the te-form before から, the ます form without ます before ながら, とき follows a noun with の, an adjective or a verb, たり comes in pairs and ends with します, and もう means already while まだです means not yet.","forms":[{"form":"〜る前に","tag":"まえに · before: dictionary form","mark":"dot","ja":"[会社|かいしゃ]へ[行|い]く{[前|まえ]に}、コーヒーを[飲|の]みます。","en":"Before I go to the office, I drink coffee."},{"form":"〜た後で","tag":"あとで · after: た-form","mark":"dot","ja":"ごはんを[食|た]べた{[後|あと]で}、コーヒーを[飲|の]みます。","en":"After I eat, I drink coffee."},{"form":"〜てから","tag":"てから · first this, then that: te-form","mark":"dot","ja":"ごはんを[食|た]べ{てから}、[会社|かいしゃ]へ[行|い]きます。","en":"I eat first, and then I go to the office."}],"check":{"id":"n5u05d6.c1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ひるごはんを^[食|た]べた^（　　）、[少|すこ]し[休|やす]みます。","options":["[前|まえ]に","[後|あと]で","てから"],"answer":2,"why":["前に comes after the dictionary form: 食べる前に. 食べた does not go before 前に.","食べた is the た-form, and the た-form goes before 後で: 食べた後で, after I eat lunch.","てから joins the te-form: 食べてから. 食べた is not a te-form."]}},"drill":[{"id":"n5u05d6.d1","kind":"choice","type":"文の文法1","label":"Choose the particles","q":"[学校|がっこう]は[八時|はちじ][半|はん]（　　）^[三時|さんじ]まで^です。わたしは[毎日|まいにち][七時|しちじ]（　　）^おきます^。","options":["から／に","まで／に","から／で","に／に"],"answer":1,"why":["The start of the school day takes から, paired with 三時まで. The time you get up is one point in time, so it takes に.","まで marks an end. 八時半まで三時まで gives two ends and no start.","から is right for the start. But a clock time with おきます takes に, not で.","The second に is right, but the first is not. With まで for the end, the start takes から."],"explain":null},{"id":"n5u05d6.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[母|はは]はいつも^ねる^（　　）、ラジオを[聞|き]きます。","options":["[前|まえ]に","[後|あと]で","てから","ながら"],"answer":1,"why":["ねる is the dictionary form, the form that goes before 前に: she listens to the radio before she goes to bed.","後で needs the た-form: ねた後で. ねる does not go before 後で.","から in this pattern joins the te-form, as in 食べてから. ねる is not a te-form.","ながら goes on the ます form without ます, as in 聞きながら. ねる is the dictionary form, so it does not fit."]},{"id":"n5u05d6.d3","kind":"choice","type":"文の文法1","label":"Choose the words","q":"この[店|みせ]は[十時|じゅうじ]から[七時|しちじ]（　　）です。^[今|いま]はよるの[八時|はちじ]^ですから、（　　）[買|か]いものができません。","options":["まで／もう","まで／まだ","に／もう","から／まだ"],"answer":1,"why":["十時から pairs with 七時まで for the closing time. It is eight at night now, after closing, so もう〜ません: you can't shop any more.","まで is right, but まだ〜ません means not yet, as if the shop opens later. At eight at night it has already closed.","With 十時から, the end takes まで, not に. もう is right.","The opening time already has から, so the closing time needs まで. And まだ means not yet, but the shop has already closed."]},{"id":"n5u05d6.d4","kind":"choice","type":"文の文法1","label":"Choose the words","q":"あつい（　　）、テレビを^[見|み]^（　　）アイスを[食|た]べます。","options":["とき／たり","のとき／から","とき／ながら","のとき／ながら"],"answer":3,"why":["とき is right, but たり needs a second たり and します at the end. This sentence ends in 食べます.","An い-adjective takes no の before とき. And から in this pattern joins the te-form, 見て, not 見.","あつい is an い-adjective, so とき comes right after it. 見 is the ます form without ます, so ながら fits: I watch TV while I eat ice cream.","ながら is right, but an い-adjective takes no の before とき: あついとき."],"explain":null},{"id":"n5u05d6.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"テストが","after":"[読|よ]んだりしました。","tiles":["おわった","[後|あと]で","[友|とも]だちと[話|はな]したり","[本|ほん]を"],"star":2,"bank":[3,1,0,2],"hint":"Which form goes before 後で? Which tile goes with 読んだり at the end?","full":"テストがおわった[後|あと]で{[友|とも]だちと[話|はな]したり}[本|ほん]を[読|よ]んだりしました。","explain":"おわった is the た-form, so it goes right before 後で. Then the two たり actions follow: 友だちと話したり first, then 本を, which goes with 読んだりしました at the end."},{"id":"n5u05d6.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「もう[本|ほん]を[買|か]いましたか。」B「いいえ、まだです。","after":"[買|か]います。」","tiles":["ぎんこう","へ","[行|い]って","から"],"star":2,"bank":[2,0,3,1],"hint":"First one action, then the other. Which tile can join から?","full":"A「もう[本|ほん]を[買|か]いましたか。」B「いいえ、まだです。ぎんこうへ{[行|い]って}から[買|か]います。」","explain":"いいえ、まだです answers もう〜ましたか: not yet. Then ぎんこうへ行ってから: 行って is the te-form, and から joins it to say first the bank, then buying the book."}],"exam":[{"id":"n5u05d6.e1","kind":"choice","type":"文の文法1","label":"Choose the answer","q":"A「もう　ひるごはんを　食べましたか。」\nB「いいえ、（　　）。じゅぎょうが　おわった　後で　食べます。」","options":["まだです","もう　食べました","食べませんでした","もう　ありません"],"answer":1,"explain":"B has not eaten yet and will eat after class, so the answer to もう〜ましたか is いいえ、まだです. もう　食べました says B has eaten, which does not go with いいえ. 食べませんでした tells about a past time B did not eat, not \"not yet\". もう　ありません means there is none left, which does not answer the question."},{"id":"n5u05d6.e2","kind":"choice","type":"文の文法1","label":"Choose the word","q":"父は　毎あさ　新聞を　読んで（　　）、会社へ　行きます。","options":["前に","後で","とき","から"],"answer":4,"explain":"読んで is the te-form, and から joins it: 読んでから, first the paper, then work. 前に needs the dictionary form (読む前に) and 後で needs the た-form (読んだ後で). とき does not join a te-form either. Only から fits after 読んで."},{"id":"n5u05d6.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"しごとの　","after":"日本語を　べんきょうします。","tiles":["後で","六時","から","八時まで"],"star":1,"bank":[3,2,0,1],"full":"しごとの　後で　{六時}　から　八時まで　日本語を　べんきょうします。","explain":"後で, 六時, から, 八時まで. しごとの goes with 後で: after work. Then the start comes first with から, 六時から, and the end comes after it with まで, 八時まで."}]},"scene":{"ja":"学校のホワイトボード","en":"A day plan on a school whiteboard","intro":"Tap each word on the whiteboard where the teacher wrote the plan for next week's trip.","words":[{"id":"next-week","word":"来週","reading":"らいしゅう","gloss":"next week","parts":[["来","ライ","come"],["週","シュウ","week"]],"clip":"s_n5u5d6_next_week"},{"id":"wednesday","word":"水よう日","reading":"すいようび","gloss":"Wednesday","parts":[["水","スイ","water, Wednesday"],["日","び","day"]],"clip":"s_n5u5d6_wednesday"},{"id":"eight-thirty","word":"八時半","reading":"はちじはん","gloss":"half past eight","parts":[["八","ハチ","eight"],["時","ジ","o'clock, time"],["半","ハン","half"]],"clip":"s_n5u5d6_eight_thirty"},{"id":"front","word":"前","reading":"まえ","gloss":"front; before","parts":[["前","まえ","front, before"]],"clip":"s_n5u5d6_front"},{"id":"top","word":"上","reading":"うえ","gloss":"top, on top of","parts":[["上","うえ","up, above"]],"clip":"s_n5u5d6_top"},{"id":"four-fifteen","word":"四時十五分","reading":"よじじゅうごふん","gloss":"a quarter past four, 4:15","parts":[["四","よ","four"],["時","ジ","o'clock, time"],["十","ジュウ","ten"],["五","ゴ","five"],["分","フン","minute"]],"clip":"s_n5u5d6_four_fifteen"},{"id":"rain","word":"雨","reading":"あめ","gloss":"rain","parts":[["雨","あめ","rain"]],"clip":"s_n5u5d6_rain"},{"id":"thursday","word":"木よう日","reading":"もくようび","gloss":"Thursday","parts":[["木","モク","tree, Thursday"],["日","び","day"]],"clip":"s_n5u5d6_thursday"}],"check":{"id":"n5u05d6.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"バスは　_四時十五分_に　学校へ　かえります。","options":["よんじじゅうごふん","しじじゅうごふん","よじじゅうごぷん","よじじゅうごふん"],"answer":4,"explain":"四時 is always よじ, and 十五分 is じゅうごふん, so 四時十五分 is よじじゅうごふん. よんじ and しじ are not used for four o'clock, and 五 is followed by ふん, not ぷん."}},"skill":{"kind":"reading","ja":"情報検索","en":"Finding information","ask":"What time does the class get back to school?","seconds":90,"passage":"来週の　水よう日　山へ　行きます\n八時半　学校の　前\n九時　バスが　出ます\n十二時　山の　上で　ひるごはん\n二時半　バスが　山を　出ます\n^四時十五分　学校に　かえります^\n雨の　日は　木よう日に　行きます。","strategy":"Find the line with 学校に　かえります and read the time at the start of it.","item":{"id":"n5u05d6.r1","kind":"choice","type":"読解・情報検索","q":"みんなは　何時に　学校に　かえりますか。","options":["九時","十二時","二時半","四時十五分"],"short":["9:00","12:00","2:30","4:15"],"answer":4,"explain":"The line 四時十五分　学校に　かえります gives the time the class gets back to school: a quarter past four.","why":["At nine the bus leaves the school.","Twelve is lunch on top of the mountain.","Half past two is when the bus leaves the mountain, not when it gets to the school.",""]}}}],"test":[{"id":"n5u05t.1","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"わたしは　_毎週_　日よう日に　テニスを　します。","options":["まいしゅう","まいしゅ","めいしゅう","まいにち"],"answer":1,"explain":"毎週 is まいしゅう, every week. まいにち is a real word, but it is 毎日 (every day), not read from 週. まいしゅ has a short しゅ, and めいしゅう changes まい to めい; neither is a word."},{"id":"n5u05t.2","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"_来月_　国へ　かえります。","options":["らいつき","らいげつ","らいがつ","こんげつ"],"answer":2,"explain":"来月 is らいげつ, next month. こんげつ is 今月 (this month), a different word. In 来月 the 月 is げつ, so らいがつ and らいつき are not words."},{"id":"n5u05t.3","kind":"choice","type":"表記","label":"Kanji spelling","q":"_せんしゅう_　友だちと　山へ　行きました。","options":["先週","千週","生週","先月"],"answer":1,"explain":"せんしゅう (last week) is 先週. 先月 is せんげつ (last month), a real word but not せんしゅう. 千 is the number one thousand and 生 is the せい of 先生, so 千週 and 生週 are not words."},{"id":"n5u05t.4","kind":"choice","type":"表記","label":"Kanji spelling","q":"_まいにち_　七時半に　うちを　出ます。","options":["毎月","毎目","母日","毎日"],"answer":4,"explain":"まいにち (every day) is 毎日. 毎月 is まいつき (every month), a real word but not まいにち. 毎目 uses 目 (eye) instead of 日, and 母日 uses 母 (mother) instead of 毎; neither is a word."},{"id":"n5u05t.5","kind":"choice","type":"文脈規定","label":"Word in context","q":"A「おなかが　すきましたね。」B「ええ。もう　十二時ですから、（　　）ごはんを　食べに　行きましょう。」","options":["あさ","ばん","ごご","ひる"],"answer":4,"explain":"They are hungry at twelve o'clock, so they go for lunch: ひるごはん. あさごはん is breakfast and ばんごはん is dinner, and neither is eaten at twelve. ごご (afternoon) does not join ごはん to name a meal."},{"id":"n5u05t.6","kind":"choice","type":"文脈規定","label":"Word in context","q":"きょうは　月よう日です。（　　）は　水よう日です。","options":["おととい","あした","きのう","あさって"],"answer":4,"explain":"Today is Monday, and Wednesday is two days later: あさって (the day after tomorrow). あした would be Tuesday. きのう (yesterday) and おととい (the day before yesterday) are days before Monday, so they would be Sunday and Saturday."},{"id":"n5u05t.7","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"テストは　_一時から　二時半まで_です。","options":["テストは　一時間です。","テストは　一時間半です。","テストは　二時間半です。","テストは　三十分です。"],"answer":2,"explain":"From one o'clock until half past two is one and a half hours: 一時間半. 一時間 is half an hour too short and 三十分 is much too short. 二時間半 comes from reading only the end time, 二時半, not the length of the test."},{"id":"n5u05t.8","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"_けさ_　コーヒーを　飲みました。","options":["きのうの　ばん　コーヒーを　飲みました。","きのうの　あさ　コーヒーを　飲みました。","きょうの　ばん　コーヒーを　飲みました。","きょうの　あさ　コーヒーを　飲みました。"],"answer":4,"explain":"けさ means this morning, which is きょうの あさ. きのうの あさ is yesterday morning, not this morning. きのうの ばん and きょうの ばん are evenings, not mornings."},{"id":"n5u05t.9","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"あしたの　あさ　十時（　　）　駅の　前で　会いましょう。","options":["が","に","で","を"],"answer":2,"explain":"A clock time when something happens takes に: 十時に 会いましょう (let's meet at ten). で here would mark a place, and the place is 駅の 前で already. を and が do not go after a time that says when you meet."},{"id":"n5u05t.10","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"うちから　学校（　　）　あるいて　二十分です。","options":["を","で","と","まで"],"answer":4,"explain":"から goes with まで: うちから 学校まで (from home to school) is twenty minutes on foot. 学校を あるいて would mean walking around inside the school. 学校で marks where something happens, and 学校と means \"with the school\"; neither gives the end of the walk."},{"id":"n5u05t.11","kind":"choice","type":"文の文法1","label":"Choose the form","q":"うちを　（　　）　前に、テレビを　けします。","options":["出た","出て","出ます","出る"],"answer":4,"explain":"前に joins the dictionary form of a verb: 出る 前に (before leaving). 出た is the past form, which goes with 後で, not 前に. 出て (the て form) and 出ます (the polite ending) do not come before 前に."},{"id":"n5u05t.12","kind":"choice","type":"文の文法1","label":"Choose the form","q":"おふろに　入った　（　　）、ジュースを　飲みます。","options":["まで","前に","ながら","後で"],"answer":4,"explain":"入った is the past form, and the past form goes before 後で: 入った 後で (after taking a bath). 前に needs the dictionary form (入る 前に), so 入った 前に is wrong. ながら joins the ます form without ます (入りながら), not 入った. 入った まで does not make sense here."},{"id":"n5u05t.13","kind":"choice","type":"文の文法1","label":"Choose the form","q":"母に　電話を　かけて（　　）、出かけます。","options":["ながら","から","とき","まで"],"answer":2,"explain":"The て form plus から means \"after doing A, then B\": かけてから 出かけます (I call my mother, then go out). ながら joins the ます form without ます (かけながら), and とき joins the dictionary or past form (かける とき), so neither follows かけて. かけて まで does not make sense here."},{"id":"n5u05t.14","kind":"choice","type":"文の文法1","label":"Choose the form","q":"なつ休みは　うみで　およいだり、山に　（　　）　しました。","options":["のぼりました","のぼったり","のぼって","のぼりながら"],"answer":2,"explain":"およいだり needs a second たり form before しました: およいだり、のぼったり しました (swam, climbed mountains and so on). のぼって and のぼりながら do not go right before しました, and のぼりました しました puts two polite verbs together."},{"id":"n5u05t.15","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「しゅくだいは　もう　おわりましたか。」B「いいえ、（　　）です。今から　します。」","options":["よく","いつも","もう","まだ"],"answer":4,"explain":"B says いいえ and will start now, so the homework is not finished yet: まだです. もうです is not a way to answer, and もう (already) does not fit いいえ. よく (often) and いつも (always) do not answer \"is it finished yet?\"."},{"id":"n5u05t.16","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「いつ　この　まちに　来ましたか。」B「","after":"　来ました。」","tiles":["十さい","の","とき","に"],"star":1,"bank":[2,0,3,1],"full":"A「いつ　この　まちに　来ましたか。」B「十さい{の}　ときに　来ました。」","explain":"十さい, の, とき, に. A noun (十さい, ten years old) joins とき with の: 十さいの とき (when I was ten). に after とき says when B came: ときに 来ました. の cannot go after とき or に, because then 十さい and とき are not joined."},{"id":"n5u05t.17","kind":"star","type":"文の文法2","label":"Build the sentence","before":"父は　毎あさ　ラジオを　","after":"。","tiles":["聞き","ながら","こうえんを","あるきます"],"star":2,"bank":[3,1,0,2],"full":"父は　毎あさ　ラジオを　聞きながら　{こうえんを}　あるきます。","explain":"聞き, ながら, こうえんを, あるきます. ラジオを needs its verb right after it, so 聞き comes first, and ながら joins it: 聞きながら (while listening). The main action comes after the ながら part: こうえんを あるきます (walks in the park), with あるきます at the end. こうえんを cannot come before 聞き, because you do not listen to a park."},{"id":"n5u05t.18","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「もう　おきますか。」B「いいえ、","after":"、もう少し　ねます。」","tiles":["まだ","六時","です","から"],"star":1,"bank":[2,3,0,1],"full":"A「もう　おきますか。」B「いいえ、まだ　{六時}ですから、もう少し　ねます。」","explain":"まだ, 六時, です, から. まだ goes before the time: まだ 六時です (it is still only six). から after です gives the reason: it is still six, so B sleeps a little more. まだ cannot come after 六時 or です, because まだ comes before the word it describes."},{"id":"n5u05t.19","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"わたしは　毎あさ　六時半に　おきて、いぬと　さんぽに　行きます。さんぽから　かえってから、シャワーを　あびて、あさごはんを　食べます。会社は　九時からです。ひる休みは　十二時から　一時までです。ひる休みには　いつも　本を　読みながら　パンを　食べます。","q":"この　人は　さんぽの　後で、はじめに　何を　しますか。","options":["シャワーを　あびます。","本を　読みます。","会社へ　行きます。","あさごはんを　食べます。"],"answer":1,"short":["シャワー","本","会社","あさごはん"],"explain":"The writer says さんぽから かえってから、シャワーを あびて、あさごはんを 食べます: first a shower, then breakfast. Breakfast comes after the shower, not first. The writer reads at lunch break, and work starts at nine, after breakfast."},{"id":"n5u05t.20","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"わたしは　毎あさ　六時半に　おきて、いぬと　さんぽに　行きます。さんぽから　かえってから、シャワーを　あびて、あさごはんを　食べます。会社は　九時からです。ひる休みは　十二時から　一時までです。ひる休みには　いつも　本を　読みながら　パンを　食べます。","q":"ただしい　ものは　どれですか。","options":["会社は　九時までです。","ひる休みは　一時間です。","ひる休みに　本を　読んだ　後で、パンを　食べます。","この　人は　六時に　おきます。"],"answer":2,"short":["九時まで","ひる休み一時間","読んだ後でパン","六時におきる"],"explain":"Lunch break is 十二時から 一時まで, which is one hour. The writer gets up at 六時半, not six. Work is 九時から (starts at nine), not until nine. The writer eats bread while reading (読みながら), not after reading."},{"id":"n5u05t.21","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"さくらプール\n月よう日　休み\n火よう日〜金よう日　午前　十時〜午後　八時\n土よう日・日よう日　午前　九時〜午後　五時\n＊水よう日の　午後　一時から　三時までは　休みです。\n＊子どもは　お父さんか　お母さんと　いっしょに　来て　ください。","q":"リンさんは　毎日　六時まで　しごとを　します。しごとの　後で　プールへ　行きたいです。何よう日に　行きますか。","options":["木よう日","土よう日","日よう日","月よう日"],"answer":1,"short":["木","土","日","月"],"explain":"Rin finishes work at six, so the pool must be open after six. On 木よう日 it is open until 午後 八時. 月よう日 is the pool's day off (休み). On 土よう日 and 日よう日 it closes at 午後 五時, before Rin finishes work."},{"id":"n5u05t.22","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"さくらプール\n月よう日　休み\n火よう日〜金よう日　午前　十時〜午後　八時\n土よう日・日よう日　午前　九時〜午後　五時\n＊水よう日の　午後　一時から　三時までは　休みです。\n＊子どもは　お父さんか　お母さんと　いっしょに　来て　ください。","q":"ヤンさんは　水よう日の　午後に　プールへ　行きます。何時に　行きますか。","options":["午後　三時半","午後　二時","午後　二時半","午後　九時"],"answer":1,"short":["三時半","二時","二時半","九時"],"explain":"On 水よう日 the pool is open until 午後 八時, but it is closed 午後 一時から 三時まで. 三時半 is after the break and before eight. 二時 and 二時半 fall in the closed time, and 九時 is after the pool closes."},{"id":"n5u05t.23","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ゆうたへ\nお母さんは　今から　買いものに　行きます。六時ごろ　かえります。しゅくだいを　してから、あそびに　行って　ください。ばんごはんの　前に、へやの　まどを　しめて　ください。おかしは　ばんごはんの　後で　食べましょう。\n母","q":"ゆうたくんは　いつ　おかしを　食べますか。","options":["しゅくだいの　前","あそびに　行く　前","ばんごはんの　前","ばんごはんの　後"],"answer":4,"short":["しゅくだいの前","あそぶ前","ばんごはんの前","ばんごはんの後"],"explain":"The note says おかしは ばんごはんの 後で 食べましょう: after dinner. Before homework and before going out to play are not times for snacks in the note. ばんごはんの 前 is when ゆうた closes the windows, not when he eats snacks."},{"id":"n5u05t.24","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ゆうたへ\nお母さんは　今から　買いものに　行きます。六時ごろ　かえります。しゅくだいを　してから、あそびに　行って　ください。ばんごはんの　前に、へやの　まどを　しめて　ください。おかしは　ばんごはんの　後で　食べましょう。\n母","q":"ただしい　ものは　どれですか。","options":["お母さんは　六時に　買いものに　行きます。","ゆうたくんは　あそびに　行ってから、しゅくだいを　します。","ゆうたくんは　お母さんと　買いものに　行きます。","ゆうたくんは　ばんごはんの　前に　まどを　しめます。"],"answer":4,"short":["六時に買いもの","あそんでからしゅくだい","母と買いもの","前にまどをしめる"],"explain":"The note says ばんごはんの 前に、へやの まどを しめて ください, so ゆうた closes the windows before dinner. His mother goes shopping now (今から) and comes back around six, so she does not leave at six. ゆうた does his homework first (しゅくだいを してから), then plays. His mother goes shopping alone; ゆうた stays and does homework."}]},{"n":6,"ja":"て形","en":"The te-form","days":[{"title":"〜て、〜・〜てください","grammar":{"points":[{"id":"n5u06d1.p1","form":"〜て、〜","gloss":"do … and (then) …","connect":[{"pos":"る-verbs, like 食べます, 見ます, おきます: drop ます and add て","rule":"[食|た]べます → [食|た]べ{て}"},{"pos":"う-verbs: the sound before ます changes. き → いて (but 行きます → 行って), ぎ → いで, み・び・に → んで, い・ち・り → って, し → して","rule":"[書|か]い{て}・[行|い]っ{て}・[読|よ]ん{で}・[話|はな]し{て}・まっ{て}"},{"pos":"します and 来ます are special. Join actions in order with 〜て、〜; the last verb says when (〜ます or 〜ました)","rule":"します → し{て}・[来|き]ます → [来|き]{て}"}],"examples":[{"ja":"あさおき{て}、かおをあらっ{て}、ごはんを[食|た]べます。","en":"In the morning I get up, wash my face and eat breakfast.","clip":"x_n5u06d1_p1_1"},{"ja":"[駅|えき]で[電車|でんしゃ]をおり{て}、[友|とも]だちに[会|あ]いました。","en":"I got off the train at the station and met a friend.","clip":"x_n5u06d1_p1_2"}],"watch":{"note":"With う-verbs you cannot just add て. The sound changes first: 書きます becomes 書いて, never 書きて.","bad":"てがみを書きて、出しました。","good":"てがみを書いて、出しました。"}},{"id":"n5u06d1.p2","form":"〜てください","gloss":"please do …","connect":[{"pos":"Verb, て form: 〜て is a て form such as 書いて, 見て, して","rule":"〜て{ください}"},{"pos":"To sound softer, start with すみませんが","rule":"すみませんが、〜て{ください}"}],"examples":[{"ja":"[九時|くじ]に[駅|えき]の[前|まえ]に[来|き]て{ください}。","en":"Please come to the front of the station at nine.","clip":"x_n5u06d1_p2_1"},{"ja":"すみませんが、ちょっとまって{ください}。","en":"Sorry, please wait a moment.","clip":"x_n5u06d1_p2_2"}],"watch":{"note":"ください goes after the て form, not after the ます form.","bad":"もう一ど言いますください。","good":"もう一ど言ってください。"}}],"compare":{"intro":"All three ask something of someone: てください asks them to do something, をください asks for a thing, and ませんか invites them to do something with you.","forms":[{"form":"〜てください","tag":"おねがい · please do","mark":"dot","ja":"ドアをしめて{ください}。","en":"Please close the door."},{"form":"〜をください","tag":"ほしいもの · please give me (a thing)","mark":"dot","ja":"コーヒー{をください}。","en":"A coffee, please."},{"form":"〜ませんか","tag":"さそう · won't you (with me)?","mark":"dot","ja":"いっしょに[行|い]き{ませんか}。","en":"Won't you come with me?"}],"check":{"id":"n5u06d1.c1","kind":"choice","type":"文の文法1","label":"店で","q":"すみません、その[白|しろ]いペン（　　）。","options":["てください","ませんか","をください"],"answer":3,"why":["てください goes after a verb in the て form, like 書いて. ペン is a noun.","ませんか goes after a verb, as in 行きませんか. It cannot come after a noun.","ペン is a thing, so you ask for it with をください: that white pen, please."],"explain":null}},"drill":[{"id":"n5u06d1.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"よる、[本|ほん]を（　　）^、ねます^。","options":["[読|よ]みて","[読|よ]いて","[読|よ]って","[読|よ]んで"],"answer":4,"why":["う-verbs do not just add て. み changes to んで.","いて is for verbs with き before ます, like 書きます → 書いて.","って is for verbs with い, ち or り before ます, like かいます → かって.","読みます has み before ます, so it becomes 読んで: I read, then I sleep."],"explain":null},{"id":"n5u06d1.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[駅|えき]へ（　　）、^[電車|でんしゃ]にのります^。","options":["[行|い]んで","[行|い]いて","[行|い]って","[行|い]きて"],"answer":3,"why":["んで is for verbs with み, び or に before ます, like 読みます → 読んで.","Most verbs with き become いて, but 行きます is the exception.","行きます becomes 行って: I go to the station, then I get on the train.","う-verbs do not just add て. 行きます becomes 行って."],"explain":null},{"id":"n5u06d1.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"すみません、ここに[名前|なまえ]を（　　）^ください^。","options":["[書|か]きて","[書|か]いで","[書|か]きます","[書|か]いて"],"answer":4,"why":["う-verbs do not just add て. き changes to い: 書いて.","いで is for verbs with ぎ before ます, like およぎます → およいで. 書きます takes て.","ください never goes after the ます form.","書きます has き before ます, so it becomes 書いて: please write your name here."],"explain":null},{"id":"n5u06d1.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[今日|きょう]、うちでしゅくだいを（　　）^ください^。","options":["して","しって","するて","します"],"answer":1,"why":["します becomes して: please do your homework at home today.","There is no small っ in the て form of します. It is just して.","する never takes て directly. The て form is して.","ください never goes after the ます form."]},{"id":"n5u06d1.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[駅|えき]で","after":"。","tiles":["[電車|でんしゃ]を","おりて","バスに","のります"],"star":1,"bank":[2,0,3,1],"hint":"Getting off the train comes first, with て. Which tile goes with おりて? The second action ends the sentence.","full":"[駅|えき]で[電車|でんしゃ]をおり{て}バスにのります。","explain":"電車をおりて is the first action, so it comes first, in the て form. バスにのります is the second action, and its ます ending closes the sentence."},{"id":"n5u06d1.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"すみません、もう","after":"。","tiles":["[少|すこ]し","ゆっくり","[話|はな]して","ください"],"star":2,"bank":[1,3,0,2],"hint":"もう少し is one phrase: a little more. ください comes last, right after the て form.","full":"すみません、もう[少|すこ]しゆっくり[話|はな]して{ください}。","explain":"もう少し means a little more, so 少し sits right after もう. ゆっくり describes how to speak, so it comes before 話して. ください follows the て form and ends the request."}],"exam":[{"id":"n5u06d1.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"友だちを　三十分　（　　）、いっしょに　えいがを　見ました。","options":["まつて","まって","まんで","まちて"],"answer":2,"explain":"まちます has ち before ます, so it becomes まって: I waited thirty minutes for my friend, then we saw a film together. まちて and まつて are not forms of this verb, and んで is for verbs with み, び or に, like よみます → よんで."},{"id":"n5u06d1.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"先生「では、本の　十ページを　（　　）　ください。」","options":["見て","見って","見んで","見ます"],"answer":1,"explain":"見ます is a る-verb: drop ます and add て, so 見てください, please look at page ten. 見って and 見んで are not forms of 見ます, and ください never goes after the ます form."},{"id":"n5u06d1.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"まどを　","after":"　ください。","tiles":["あけて","へやの","そうじを","して"],"star":2,"bank":[3,1,0,2],"full":"まどを　あけて　へやの　{そうじを}　して　ください。","explain":"あけて, へやの, そうじを, して. まどを goes with あけて, the first action. へやの describes そうじ, and そうじを して is the second action, right before ください."}]},"scene":{"ja":"テストのプリント","en":"A test instruction sheet","intro":"Tap each word on the instruction sheet your teacher hands out before a test.","words":[{"id":"name","word":"名前","reading":"なまえ","gloss":"name","parts":[["名","な","name"],["前","まえ","front"]],"clip":"s_n5u6d1_name"},{"id":"write","word":"書いて","reading":"かいて","gloss":"write (て form)","parts":[["書","か","write"]],"clip":"s_n5u6d1_write"},{"id":"read","word":"読んで","reading":"よんで","gloss":"read (て form)","parts":[["読","よ","read"]],"clip":"s_n5u6d1_read"},{"id":"put-in","word":"入れて","reading":"いれて","gloss":"put in (て form)","parts":[["入","い","enter, put in"]],"clip":"s_n5u6d1_put_in"},{"id":"hand-in","word":"出して","reading":"だして","gloss":"hand in, take out (て form)","parts":[["出","だ","go out, put out"]],"clip":"s_n5u6d1_hand_in"},{"id":"back","word":"後ろ","reading":"うしろ","gloss":"behind, the back","parts":[["後","うし","behind, after"]],"clip":"s_n5u6d1_back"},{"id":"time","word":"時間","reading":"じかん","gloss":"time (allowed)","parts":[["時","ジ","time, o'clock"],["間","カン","between"]],"clip":"s_n5u6d1_time"},{"id":"forty-min","word":"四十分","reading":"よんじゅっぷん","gloss":"forty minutes","parts":[["四","よん","four"],["十","ジュッ","ten"],["分","プン","minute"]],"clip":"s_n5u6d1_forty_min"}],"check":{"id":"n5u06d1.k1","kind":"choice","type":"文脈規定","label":"How the exam asks it","q":"テストの　前に、本を　かばんに　（　　）　ください。","options":["出して","読んで","書いて","入れて"],"answer":4,"explain":"かばんに means into the bag, so 入れて: please put your book in your bag before the test. 出して would need かばんから (out of the bag). 読んで and 書いて do not go with かばんに."}},"skill":{"kind":"listening","ja":"発話表現","en":"Expressions","situation":"On a hot day in class, a woman turns to the man sitting next to the closed window.","ask":"へやが　あついです。まどの　そばの　人に　何と　いいますか。","item":{"id":"n5u06d1.r1","kind":"choice","type":"発話表現","q":"へやが　あついです。まどの　そばの　人に　何と　いいますか。","script":["ナレーター：へやが　あついです。まどの　そばの　人に　何と　いいますか。","ナレーター：1","女：すみません、まどを　あけましたか。","ナレーター：2","女：すみません、まどを　しめて　ください。","ナレーター：3","女：すみません、まどを　あけて　ください。"],"options":["すみません、まどを　あけましたか。","すみません、まどを　しめて　ください。","すみません、まどを　あけて　ください。"],"printed":false,"short":["まどをあけましたか","まどをしめてください","まどをあけてください"],"answer":3,"why":["あけましたか asks if he already opened it. It does not ask him to open it.","しめて means close. The room is hot and the window is already closed, so she wants it open.",""],"clip":"l_n5u6d1"},"audio":[["N","へやが　あついです。まどの　そばの　人に　何と　いいますか。","へやが　あついです。まどの　そばの　ひとに　なんと　いいますか。"],["N","1","いち"],["F","すみません、まどを　あけましたか。",null],["N","2","に"],["F","すみません、まどを　しめて　ください。",null],["N","3","さん"],["F","すみません、まどを　あけて　ください。",null]]}},{"title":"〜ないでください・〜てもいいです","grammar":{"points":[{"id":"n5u06d2.p1","form":"〜ないでください","gloss":"please don't …","connect":[{"pos":"Verb, ない-form (learn these as set shapes; the ない-form is taught in unit 7)","rule":"[食|た]べない・[入|はい]らない・[書|か]かない ＋ {でください}"},{"pos":"More ない-forms to learn as set shapes (unit 7)","rule":"[話|はな]さない・しない・[来|こ]ない ＋ {でください}"}],"examples":[{"ja":"ここに[入|はい]ら{ないでください}。","en":"Please don't go in here.","clip":"x_n5u06d2_p1_1"},{"ja":"この[本|ほん]に[何|なに]も[書|か]か{ないでください}。","en":"Please don't write anything in this book.","clip":"x_n5u06d2_p1_2"}],"watch":{"note":"Use the ない-form before でください. The polite ません form never goes before でください.","bad":"ここで食べませんでください。","good":"ここで食べないでください。"}},{"id":"n5u06d2.p2","form":"〜てもいいです","gloss":"it is all right to …, you may …","connect":[{"pos":"Verb, て-form","rule":"[見|み]て・[入|はい]って・[飲|の]んで ＋ {もいいです}"},{"pos":"Asking permission: add か","rule":"[見|み]て ＋ {もいいですか}"},{"pos":"Answers: yes / a soft no","rule":"{ええ、どうぞ}。／{すみません、ちょっと…}。"}],"examples":[{"ja":"ここにすわって{もいいですか}。","en":"May I sit here?","clip":"x_n5u06d2_p2_1"},{"ja":"テストのとき、じしょを[見|み]て{もいいです}。","en":"You may look at your dictionary during the test.","clip":"x_n5u06d2_p2_2"}],"watch":{"note":"Use the て-form before もいいです. The polite ます form does not go before も.","bad":"このペンをつかいますもいいですか。","good":"このペンをつかってもいいですか。"}}],"compare":{"intro":"All three are about what someone does. ないでください asks you not to, てもいいです says it is all right, and てください asks you to do it.","forms":[{"form":"〜ないでください","tag":"しないで · please don't","mark":"down","ja":"ここで[食|た]べ{ないでください}。","en":"Please don't eat here."},{"form":"〜てもいいです","tag":"してもいい · you may","mark":"dot","ja":"ここで[食|た]べて{もいいです}。","en":"You may eat here."},{"form":"〜てください","tag":"して · please do","mark":"dot","ja":"ここで[食|た]べて{ください}。","en":"Please eat here."}],"check":{"id":"n5u06d2.c1","kind":"choice","type":"文の文法1","label":"でんわを かりる","q":"A：すみません、ここで[電話|でんわ]を（　　）か。B：ええ、どうぞ。","options":["かけないでください","かけてもいいです","かけてください"],"answer":2,"why":["ないでください asks someone not to do something. It does not take か, and ええ、どうぞ answers \"may I?\".","A asks permission with てもいいですか, and B says yes with ええ、どうぞ.","てください asks someone else to do something. くださいか is not said, and ええ、どうぞ answers \"may I?\"."]}},"drill":[{"id":"n5u06d2.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ここは^[出口|でぐち]です^。ここから（　　）ください。","options":["[入|はい]って","[入|はい]りません","[入|はい]らない","[入|はい]らないで"],"answer":4,"why":["入ってください asks people to come in, but this is the exit, not the way in.","The polite ません form does not go before ください.","でください needs で: 入らないでください. 入らないください is not said.","This is the exit, so the sign asks people not to come in: 入らないでください."],"explain":null},{"id":"n5u06d2.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この[本|ほん]は[古|ふる]いです。^[何|なに]も^（　　）ください。","options":["[書|か]きませんで","[書|か]かない","[書|か]かないで","[書|か]いて"],"answer":3,"why":["The polite ません form does not go before でください.","The で is missing: 書かないでください.","何も goes with a \"not\" form, and 書かないでください means \"please don't write\".","何も needs a \"not\" form after it. 何も書いてください is not said."],"explain":null},{"id":"n5u06d2.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：この[本|ほん]を（　　）^もいいですか^。B：ええ、どうぞ。","options":["[読|よ]んで","[読|よ]む","[読|よ]みます","[読|よ]まない"],"answer":1,"why":["もいいですか follows the て-form: 読んでもいいですか, \"may I read it?\".","読む is the dictionary form. It does not go before もいいです.","The polite ます form does not go before もいいです.","読まない is the ない-form. 読まないもいいですか is not said."]},{"id":"n5u06d2.d4","kind":"choice","type":"文の文法1","label":"Choose the answer","q":"A：まどをあけてもいいですか。B：（　　）。きょうは^さむいですから^。","options":["すみません、ちょっと…","はい、あけましょう","いいえ、どういたしまして","ええ、どうぞ"],"answer":1,"why":["B says no softly, and gives the reason: it is cold today.","あけましょう agrees to open it, but B says it is cold.","どういたしまして answers ありがとう, not a question asking permission.","ええ、どうぞ says yes, but B's reason (it is cold today) is a reason to keep the window shut."],"explain":null},{"id":"n5u06d2.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[電車|でんしゃ]の[中|なか]で","after":"。","tiles":["[大|おお]きい","こえで","[話|はな]さないで","ください"],"star":2,"bank":[2,0,3,1],"hint":"大きい describes a noun. Which tile can come right before ください?","full":"[電車|でんしゃ]の[中|なか]で[大|おお]きいこえで[話|はな]さ{ないでください}。","explain":"大きい describes こえ, so 大きいこえで goes together. 話さないで comes right before ください and ends the sentence."},{"id":"n5u06d2.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"すみません、この","after":"。","tiles":["ペンを","つかって","も","いいですか"],"star":2,"bank":[3,1,0,2],"hint":"この needs a noun right after it. も comes between the て-form and いいですか.","full":"すみません、このペンをつかって{もいいですか}。","explain":"この goes with ペン, so ペンを comes first. Then the て-form つかって, then も, then いいですか."}],"exam":[{"id":"n5u06d2.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この　へやで　おかしを　（　　）　ください。","options":["食べない","食べないで","食べませんで","食べなくて"],"answer":2,"explain":"The ない-form + でください asks someone not to do something: 食べないでください. The ません form does not go before でください, 食べなくてください is not said, and 食べないください is missing で."},{"id":"n5u06d2.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「すみません、この　いすに　（　　）　いいですか。」\nB「ええ、どうぞ。」","options":["すわりも","すわっても","すわるも","すわりますも"],"answer":2,"explain":"Asking permission uses the て-form + もいいですか: すわってもいいですか. The dictionary form, the ます form and すわり cannot go before も here."},{"id":"n5u06d2.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「すみません、","after":"。」\nB「ええ、どうぞ。」","tiles":["その","まどを","あけても","いいですか"],"star":2,"bank":[3,2,0,1],"full":"A「すみません、その　まどを　{あけても}　いいですか。」\nB「ええ、どうぞ。」","explain":"その, まどを, あけても, いいですか. その must sit right before まど, あけても is the て-form + も, and いいですか ends the question."}]},"scene":{"ja":"こうえんのきまり","en":"The rules sign at a park gate","intro":"Tap every word with kanji that you can find on the park sign.","words":[{"id":"entrance","word":"入口","reading":"いりぐち","gloss":"entrance","parts":[["入","いり","enter"],["口","ぐち","mouth, opening"]],"clip":"s_n5u6d2_entrance"},{"id":"exit","word":"出口","reading":"でぐち","gloss":"exit","parts":[["出","で","go out"],["口","ぐち","mouth, opening"]],"clip":"s_n5u6d2_exit"},{"id":"closed","word":"休み","reading":"やすみ","gloss":"closed (day off)","parts":[["休","やす","rest"]],"clip":"s_n5u6d2_closed"},{"id":"hours","word":"時間","reading":"じかん","gloss":"time, hours","parts":[["時","ジ","time"],["間","カン","space between"]],"clip":"s_n5u6d2_hours"},{"id":"am","word":"午前","reading":"ごぜん","gloss":"a.m., morning","parts":[["午","ゴ","noon"],["前","ゼン","before"]],"clip":"s_n5u6d2_am"},{"id":"pm","word":"午後","reading":"ごご","gloss":"p.m., afternoon","parts":[["午","ゴ","noon"],["後","ゴ","after"]],"clip":"s_n5u6d2_pm"},{"id":"flower","word":"花","reading":"はな","gloss":"flower","parts":[["花","はな","flower"]],"clip":"s_n5u6d2_flower"},{"id":"tree","word":"木","reading":"き","gloss":"tree","parts":[["木","き","tree, wood"]],"clip":"s_n5u6d2_tree"}],"check":{"id":"n5u06d2.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"こうえんの　_入口_は　どこですか。","options":["いりぐち","はいりぐち","いりこう","でぐち"],"answer":1,"explain":"入口 is read いりぐち, \"entrance\". でぐち is 出口, \"exit\", and はいりぐち and いりこう are not words."}},"skill":{"kind":"reading","ja":"内容理解（短文）","en":"Short passage","ask":"What may visitors do, and what may they not do?","seconds":90,"passage":"みどりこうえんの　おしらせ\nこうえんの　時間は　午前九時から　午後五時までです。月よう日は　休みです。花の　中に　入らないで　ください。^木の　下で　おべんとうを　食べても　いいです^。でも、ごみは　うちへ　もって　かえって　ください。","strategy":"Find each option in the notice, then look at how that sentence ends: てもいいです (all right) or ないでください (please don't).","item":{"id":"n5u06d2.r1","kind":"choice","type":"読解・内容理解（短文）","q":"この　こうえんで　しても　いい　ことは　どれですか。","options":["木の　下で　おべんとうを　食べます。","花の　中に　入って　しゃしんを　とります。","よる　七時に　こうえんで　あそびます。","月よう日の　午前に　さんぽします。"],"short":["木の下でおべんとうを食べる","花の中に入る","よる七時にあそぶ","月よう日にさんぽする"],"answer":1,"explain":"The notice says 木の下でおべんとうを食べてもいいです: eating your lunch under the trees is all right.","why":["","The notice says 花の中に入らないでください.","The park is open only until 5 p.m. (午後五時まで).","The park is closed on Mondays (月よう日は休みです)."]}}},{"title":"〜てはいけません・〜なくてもいいです","grammar":{"points":[{"id":"n5u06d3.p1","form":"〜てはいけません","gloss":"you must not …","connect":[{"pos":"Verb, te-form ending in て (は here sounds like わ)","rule":"[入|はい]っ{てはいけません}／[食|た]べ{てはいけません}"},{"pos":"Verb, te-form ending in で: keep で","rule":"[飲|の]ん{ではいけません}／およい{ではいけません}"},{"pos":"Saying no to \"may I …?\" (てもいいですか)","rule":"いいえ、[入|はい]っ{てはいけません}。"}],"examples":[{"ja":"ここでたばこをすっ{てはいけません}。","en":"You must not smoke here.","clip":"x_n5u06d3_p1_1"},{"ja":"この[川|かわ]でおよい{ではいけません}。","en":"You must not swim in this river.","clip":"x_n5u06d3_p1_2"}],"watch":{"note":"When the te-form ends in で, keep で: 飲んで becomes 飲んではいけません. 飲んてはいけません is wrong.","bad":"ここでジュースを飲んてはいけません。","good":"ここでジュースを飲んではいけません。"}},{"id":"n5u06d3.p2","form":"〜なくてもいいです","gloss":"you don't have to …","connect":[{"pos":"Verb, ない form: take off the last い and add くてもいいです","rule":"[書|か]かない→[書|か]かな{くてもいいです}／[来|こ]ない→[来|こ]な{くてもいいです}"},{"pos":"ない forms to learn as fixed shapes for now (unit 7 teaches how to make them)","rule":"[書|か]きます→[書|か]か{ない}／[読|よ]みます→[読|よ]ま{ない}／[入|はい]ります→[入|はい]ら{ない}／[行|い]きます→[行|い]か{ない}"},{"pos":"More fixed ない forms for now","rule":"[食|た]べます→[食|た]べ{ない}／[見|み]ます→[見|み]{ない}／します→し{ない}／[来|き]ます→[来|こ]{ない}"}],"examples":[{"ja":"あしたは[学校|がっこう]へ[来|こ]な{くてもいいです}。","en":"You don't have to come to school tomorrow.","clip":"x_n5u06d3_p2_1"},{"ja":"[名前|なまえ]はかたかなで[書|か]かな{くてもいいです}。","en":"You don't have to write your name in katakana.","clip":"x_n5u06d3_p2_2"}],"watch":{"note":"Take off the い of ない before くてもいいです. 来ないくても is wrong. Say 来なくても.","bad":"あしたは来ないくてもいいです。","good":"あしたは来なくてもいいです。"}}],"compare":{"intro":"All three are about rules: what you may do, what you must not do, and what you do not need to do.","forms":[{"form":"〜てもいいです","tag":"〜て＋もいいです · you may","mark":"dot","ja":"ここで[休|やす]ん{でもいいです}。","en":"You may rest here."},{"form":"〜てはいけません","tag":"〜て＋はいけません · you must not","mark":"down","ja":"ここで[食|た]べ{てはいけません}。","en":"You must not eat here."},{"form":"〜なくてもいいです","tag":"〜な＋くてもいいです · you don't have to","mark":"dot","ja":"[今日|きょう]は[来|こ]な{くてもいいです}。","en":"You don't have to come today."}],"check":{"id":"n5u06d3.c1","kind":"choice","type":"文の文法1","label":"プールのきまり","q":"プールのそばはあぶないですから、（　　）。","options":["はしってもいいです","はしらなくてもいいです","はしってはいけません"],"answer":3,"why":["てもいいです gives permission. Running is not allowed where it is dangerous (あぶないですから).","なくてもいいです means \"you don't have to run\". Nobody has to run, so this is not a rule here.","あぶないですから gives the reason for a rule: \"It's dangerous by the pool, so you must not run.\""]}},"drill":[{"id":"n5u06d3.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：[先生|せんせい]、ここでパンを[食|た]べてもいいですか。B：^いいえ^、（　　）。","options":["[食|た]べてもいいです","[食|た]べなくてもいいです","[食|た]べてはいけません","[食|た]べてください"],"answer":3,"why":["食べてもいいです means \"yes, you may\". It does not fit after いいえ.","食べなくてもいいです means \"you don't have to eat\". A asked for permission, not whether he has to eat.","いいえ says no to \"may I eat?\", and 食べてはいけません says it: \"No, you must not eat.\"","食べてください means \"please eat\". It does not fit after いいえ."]},{"id":"n5u06d3.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^プールの[中|なか]で^ジュースを（　　）。","options":["[飲|の]みてはいけません","[飲|の]むではいけません","[飲|の]んてはいけません","[飲|の]んではいけません"],"answer":4,"why":["飲みて is not a word. The te-form is 飲んで.","はいけません follows the te-form, not the dictionary form 飲む. Say 飲んではいけません.","The te-form of 飲みます ends in で: 飲んで. 飲んて is not a word.","飲んで is the te-form of 飲みます. 飲んではいけません: \"You must not drink juice in the pool.\""],"explain":null},{"id":"n5u06d3.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[土|ど]よう[日|び]は^じゅぎょうがありません^。[学校|がっこう]へ（　　）。","options":["きなくてもいいです","こないくてもいいです","こなくてもいいです","くなくてもいいです"],"answer":3,"why":["The ない form of 来ます is 来ない, read こない. きなくて is not a word.","Take off the い of こない before くても. こないくても is wrong.","There are no classes, so こなくてもいいです (来なくてもいいです): \"You don't have to come to school.\"","くなくて is not a word. The ない form of 来ます is こない."]},{"id":"n5u06d3.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この[本|ほん]はながいですから、[今日|きょう]^ぜんぶ^[読|よ]（　　）。","options":["まなくてもいいです","みなくてもいいです","むなくてもいいです","まないくてもいいです"],"answer":1,"why":["読まない minus い, plus くてもいいです: \"The book is long, so you don't have to read it all today.\"","読みなくて is not a word. The ない form of 読みます is 読まない.","読むなくて is not a word. The ない form is 読まない.","Take off the い of 読まない before くても. 読まないくても is wrong."],"explain":null},{"id":"n5u06d3.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"テストの","after":"いけません。","tiles":["とき","となりの","[人|ひと]と","[話|はな]しては"],"star":3,"bank":[2,0,3,1],"hint":"テストの goes with とき. となりの goes right before the person, and 話しては comes just before いけません.","full":"テストのときとなりの[人|ひと]と[話|はな]し{ては}いけません。","explain":"とき, となりの, 人と, 話しては. テストのとき is \"during the test\", and となりの describes 人: \"During the test, you must not talk with the person next to you.\""},{"id":"n5u06d3.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[今日|きょう]は[雨|あめ]ですから、","after":"です。","tiles":["プールに","[入|はい]ら","なくても","いい"],"star":2,"bank":[3,1,0,2],"hint":"入ら is the ない form without ない. なくても joins it, and いい comes just before です.","full":"[今日|きょう]は[雨|あめ]ですから、プールに[入|はい]ら{なくても}いいです。","explain":"プールに, 入ら, なくても, いい. プールに goes with 入ら, and 入らなくてもいいです means \"you don't have to go in\": \"It's raining today, so you don't have to go in the pool.\""}],"exam":[{"id":"n5u06d3.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ここは　先生の　へやです。　学生は　入っては（　　）。","options":["しません","いいです","ください","いけません"],"answer":4,"explain":"入っては needs いけません after it: \"Students must not go in.\" Permission is 入っても いいです, with も, not は. ください follows the te-form alone (入って ください), and 入っては しません is not a phrase."},{"id":"n5u06d3.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"今日は　しゅくだいが　ありません。　何も（　　）　いいです。","options":["しないくても","しても","しなくても","しては"],"answer":3,"explain":"There is no homework, so しなくても いいです: \"You don't have to do anything.\" 何も needs a negative after it, so しても いいです fails. しては goes with いけません, not いいです, and しないくても is not a form: the い of しない drops before くても."},{"id":"n5u06d3.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"プールに　入る","after":"いけません。","tiles":["前に","パンや","おかしを","食べては"],"star":3,"bank":[1,3,0,2],"full":"プールに　入る　前に　パンや　おかしを　{食べては}　いけません。","explain":"前に, パンや, おかしを, 食べては. 入る前に is \"before going in\", パンや おかしを is what you eat, and 食べては goes with いけません: \"You must not eat bread or sweets before going in the pool.\""}]},"scene":{"ja":"学校のプールで","en":"At the school pool","intro":"Tap every word you would read on the rules sign at the school pool.","words":[{"id":"student","word":"学生","reading":"がくせい","gloss":"student","parts":[["学","ガク","study"],["生","セイ","life, birth"]],"clip":"s_n5u6d3_student"},{"id":"teacher","word":"先生","reading":"せんせい","gloss":"teacher","parts":[["先","セン","ahead, before"],["生","セイ","life, birth"]],"clip":"s_n5u6d3_teacher"},{"id":"hours","word":"時間","reading":"じかん","gloss":"hours, time","parts":[["時","ジ","time, hour"],["間","カン","between, interval"]],"clip":"s_n5u6d3_hours"},{"id":"closed","word":"休み","reading":"やすみ","gloss":"closed (day), holiday","parts":[["休","やす","rest"]],"clip":"s_n5u6d3_closed"},{"id":"water","word":"水","reading":"みず","gloss":"water","parts":[["水","みず","water"]],"clip":"s_n5u6d3_water"},{"id":"enter","word":"入る","reading":"はいる","gloss":"to go in","parts":[["入","はい","enter"]],"clip":"s_n5u6d3_enter"},{"id":"food","word":"食べもの","reading":"たべもの","gloss":"food","parts":[["食","た","eat"]],"clip":"s_n5u6d3_food"},{"id":"drinks","word":"飲みもの","reading":"のみもの","gloss":"drinks","parts":[["飲","の","drink"]],"clip":"s_n5u6d3_drinks"}],"check":{"id":"n5u06d3.k1","kind":"choice","type":"表記","label":"How the exam asks it","q":"プールに　_はいる_　前に、　シャワーを　あびて　ください。","options":["人る","入る","八る","大る"],"answer":2,"explain":"はいる, \"to go in\", is written 入る. 人 (person), 八 (eight) and 大 (big) look a little like 入, but 人る, 八る and 大る are not words."}},"skill":{"kind":"listening","ja":"即時応答","en":"Quick response","ask":"えなどが　ありません。ぶんを　聞いて、1から3の　中から、いちばん　いい　ものを　一つ　えらんで　ください。","item":{"id":"n5u06d3.r1","kind":"choice","type":"即時応答","q":"男：先生、プールの　中で　ぼうしを　とっても　いいですか。","script":["男：先生、プールの　中で　ぼうしを　とっても　いいですか。","ナレーター：1","女：いいえ、とらなくても　いいです。","ナレーター：2","女：はい、とりました。","ナレーター：3","女：いいえ、とっては　いけません。"],"options":["いいえ、とらなくても　いいです。","はい、とりました。","いいえ、とっては　いけません。"],"printed":false,"short":["とらなくてもいいです","とりました","とってはいけません"],"answer":3,"why":["とらなくてもいいです means \"you don't have to take it off\". The boy asks for permission, so this does not answer him.","とりました says what someone did. The boy asks whether he may take his cap off.",""],"clip":"l_n5u6d3"},"audio":[["M","先生、プールの　中で　ぼうしを　とっても　いいですか。","せんせい、プールの　なかで　ぼうしを　とっても　いいですか。"],["N","1","いち"],["F","いいえ、とらなくても　いいです。",null],["N","2","に"],["F","はい、とりました。",null],["N","3","さん"],["F","いいえ、とっては　いけません。",null]]}},{"title":"〜ている（している最中）・〜ている（状態）","grammar":{"points":[{"id":"n5u06d4.p1","form":"〜ています（いま）","gloss":"be doing (right now)","connect":[{"pos":"Verb, て form","rule":"[見|み]て ＋ {います}"},{"pos":"Not doing it now","rule":"[見|み]て ＋ {いません}"},{"pos":"Asking what someone is doing","rule":"[何|なに]をして{いますか}"}],"examples":[{"ja":"[今|いま]テレビを[見|み]て{います}。","en":"I'm watching TV now.","clip":"x_n5u06d4_p1_1"},{"ja":"[雨|あめ]がふって{います}。","en":"It's raining.","clip":"x_n5u06d4_p1_2"}],"watch":{"note":"読みます alone is for habits or plans. For what Dad is doing at this very moment, use the て form + います: 読んでいます.","bad":"父は今、新聞を読みます。","good":"父は今、新聞を読んでいます。"}},{"id":"n5u06d4.p2","form":"〜ています（じょうたい）","gloss":"a state that goes on","connect":[{"pos":"Verbs of a change that lasts (marry, put on glasses)","rule":"けっこんします → けっこんして ＋ {います}"},{"pos":"〜 is a place; すむ (live) takes に","rule":"〜にすんで{います}"},{"pos":"しっています (I know) has a short negative","rule":"しっています → {しりません}"}],"examples":[{"ja":"あねはけっこんして{います}。","en":"My older sister is married.","clip":"x_n5u06d4_p2_1"},{"ja":"わたしはとうきょうにすんで{います}。","en":"I live in Tokyo.","clip":"x_n5u06d4_p2_2"}],"watch":{"note":"しっています means \"I know\". Its negative is しりません, not しっていません.","bad":"いいえ、しっていません。","good":"いいえ、しりません。"}}],"compare":{"intro":"Two of these use the same ています. What changes is whether it is an action now, a lasting state, or a habit.","forms":[{"form":"〜ています","tag":"いま · going on now","mark":"dot","ja":"[今|いま]、[本|ほん]を[読|よ]んで{います}。","en":"I'm reading a book now."},{"form":"〜ています","tag":"じょうたい · a lasting state","mark":"dot","ja":"リンさんはめがねをかけて{います}。","en":"Lin wears glasses."},{"form":"〜ます","tag":"いつも・これから · habit or plan","mark":"dot","ja":"[毎日|まいにち]、[新聞|しんぶん]を[読|よ]み{ます}。","en":"I read the newspaper every day."}],"check":{"id":"n5u06d4.c1","kind":"choice","type":"文の文法1","label":"かぞく","q":"あには[三年前|さんねんまえ]にけっこんしました。^[今|いま]^はおおさかに（　　）。","options":["すんでいます","すみました","すみます"],"answer":1,"why":["He moved there and still lives there: a lasting state, so すんでいます.","すみました is past, but 今は is about now.","すみます is a plan: \"will live\". 今は asks where he lives now."],"explain":null}},"drill":[{"id":"n5u06d4.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"「もしもし、^[今|いま][何|なに]をしていますか^。」「[今|いま]、テレビを（　　）。」","options":["[見|み]ます","[見|み]ました","[見|み]ています","[見|み]て"],"answer":3,"why":["見ます is a habit or a plan. It does not say what you are doing now.","見ました is past. The question is about right now.","The question asks what you are doing now, so the answer uses 見ています.","A polite answer cannot end on the て form alone. It needs います."]},{"id":"n5u06d4.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[今|いま]、[外|そと]は[雨|あめ]が（　　）^います^。","options":["ふった","ふって","ふりて","ふるて"],"answer":2,"why":["ふった is the た form. います goes on the て form.","ふります becomes ふって, then います: it is raining now.","ふりて is not a form. ふる makes its て form with って.","The dictionary form ふる does not take て."],"explain":null},{"id":"n5u06d4.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"「この[店|みせ]の[名前|なまえ]をしっていますか。」「^いいえ^、（　　）。」","options":["しりません","しっていません","しってください","しっています"],"answer":1,"why":["The negative of しっています is しりません: \"No, I don't know.\"","しっていません is not used. Say しりません.","しってください is a request. It does not answer the question.","しっています means \"I know\". It does not fit after いいえ."],"explain":null},{"id":"n5u06d4.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"「どこに（　　）か。」「^とうきょうにすんでいます^。」","options":["すみます","すみましょう","すんで","すんでいます"],"answer":4,"why":["すみますか asks where you will live. The answer says where you live now.","すみましょうか means \"shall we live?\". It does not match the answer.","すんで cannot come right before か.","The answer is すんでいます, so the question asks the same: where do you live?"]},{"id":"n5u06d4.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[父|ちち]は[今|いま]、[電話|でんわ]で","after":"います。","tiles":["[会社|かいしゃ]の","[人|ひと]","と","[話|はな]して"],"star":2,"bank":[3,0,2,1],"hint":"Whose person? Then: who is Dad talking with?","full":"[父|ちち]は[今|いま]、[電話|でんわ]で[会社|かいしゃ]の[人|ひと]と[話|はな]して{います}。","explain":"会社の describes 人, and と says who he talks with: 会社の人と. 話して comes last, right before います."},{"id":"n5u06d4.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしは","after":"。","tiles":["あの","[人|ひと]の","[名前|なまえ]を","しりません"],"star":3,"bank":[2,3,0,1],"hint":"あの points at a person. The verb comes last.","full":"わたしはあの[人|ひと]の[名前|なまえ]を{しりません}。","explain":"あの goes right before 人の, and 人の describes 名前を. しりません, the negative of しっています, ends the sentence."}],"exam":[{"id":"n5u06d4.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"「リンさんは　けっこん　して　いますか。」「はい、（　　）。子どもも　二人　います。」","options":["します","しません","して　います","して　いません"],"answer":3,"explain":"The question asks about a lasting state, so a yes answer is はい、して います: she is married. します is a plan, and しません and して いません do not fit after はい."},{"id":"n5u06d4.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"「今、何を　して　いますか。」「へやで　本を　（　　）。」","options":["読んで　います","読みます","読みました","読んで　ください"],"answer":1,"explain":"The question asks what you are doing now, so the answer is 読んで います. 読みます is a habit or plan, 読みました is past, and 読んで ください is a request."},{"id":"n5u06d4.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あの　人は　白い","after":"かけて　います。","tiles":["シャツを","きて","くろい","めがねを"],"star":2,"bank":[3,1,0,2],"full":"あの　人は　白い　シャツを　きて　{くろい}　めがねを　かけて　います。","explain":"シャツを, きて, くろい, めがねを. 白い describes シャツ, and you きる a shirt. くろい describes めがね, which goes right before かけて います."}]},"scene":{"ja":"会社のボード","en":"An office whereabouts board","intro":"Tap each word on the office board that shows where everyone is and what they are doing.","words":[{"id":"now","word":"今","reading":"いま","gloss":"now","parts":[["今","いま","now"]],"clip":"s_n5u6d4_now"},{"id":"phone","word":"電話","reading":"でんわ","gloss":"telephone, phone call","parts":[["電","デン","electric"],["話","ワ","talk"]],"clip":"s_n5u6d4_phone"},{"id":"talk","word":"話す","reading":"はなす","gloss":"to talk, to speak","parts":[["話","はな","talk"]],"clip":"s_n5u6d4_talk"},{"id":"read","word":"読む","reading":"よむ","gloss":"to read","parts":[["読","よ","read"]],"clip":"s_n5u6d4_read"},{"id":"write","word":"書く","reading":"かく","gloss":"to write","parts":[["書","か","write"]],"clip":"s_n5u6d4_write"},{"id":"out","word":"外","reading":"そと","gloss":"outside, out","parts":[["外","そと","outside"]],"clip":"s_n5u6d4_out"},{"id":"off","word":"休み","reading":"やすみ","gloss":"day off, absent","parts":[["休","やす","rest"]],"clip":"s_n5u6d4_off"},{"id":"company","word":"会社","reading":"かいしゃ","gloss":"company, office","parts":[["会","カイ","meet"],["社","シャ","company"]],"clip":"s_n5u6d4_company"}],"check":{"id":"n5u06d4.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"リンさんは　今　_電話_を　かけて　います。","options":["てんか","てんわ","でんわ","でんか"],"answer":3,"explain":"電話 is でんわ, a phone call. てんわ and てんか are not words, and でんか is a different word."}},"skill":{"kind":"reading","ja":"内容理解（短文）","en":"Short passage","ask":"What is the writer's mother doing right now?","seconds":90,"passage":"リサさん、こんにちは。今、うちの　みんなの　ことを　書きます。父は　にわで　車を　あらって　います。母は　いつも　この　時間は　テレビを　見ますが、^今日は　外で　友だちと　話して　います^。あには　へやで　本を　読んで　います。わたしは　今、この　メールを　書いて　います。","strategy":"Find 母 and look after が: what she usually does comes before it, what she is doing today comes after.","item":{"id":"n5u06d4.r1","kind":"choice","type":"読解・内容理解（短文）","q":"お母さんは　今　何を　して　いますか。","options":["へやで　本を　読んで　います。","テレビを　見て　います。","外で　友だちと　話して　います。","にわで　車を　あらって　います。"],"short":["本を読んでいる","テレビを見ている","外で友だちと話している","車をあらっている"],"answer":3,"explain":"After が, the writer says that today her mother is outside talking with a friend. 話して います is what she is doing now.","why":["The older brother is reading in his room.","She usually watches TV at this time (見ます), but not today.","","The father is washing the car."]}}},{"title":"〜に行く・〜つもりです","grammar":{"points":[{"id":"n5u06d5.p1","form":"〜に行きます","gloss":"go (somewhere) to do something","connect":[{"pos":"Verb, ます form without ます","rule":"[買|か]います → [買|か]い{に[行|い]きます}"},{"pos":"Noun of action (かいもの, さんぽ)","rule":"〜{に[行|い]きます}"},{"pos":"Also with 来ます and かえります","rule":"〜{に}[来|き]ます／かえります"}],"examples":[{"ja":"あした、[本|ほん]を[買|か]い{に[行|い]きます}。","en":"Tomorrow I am going to buy a book.","clip":"x_n5u06d5_p1_1"},{"ja":"[日|にち]よう[日|び]は、かいもの{に[行|い]きます}。","en":"On Sunday I am going shopping.","clip":"x_n5u06d5_p1_2"}],"watch":{"note":"Drop ます first, then add に: 買います becomes 買いに. The whole ます form does not go before に.","bad":"本を買いますに行きます。","good":"本を買いに行きます。"}},{"id":"n5u06d5.p2","form":"〜つもりです","gloss":"plan to; intend to","connect":[{"pos":"Verb, dictionary form (learn these as a set for now)","rule":"[行|い]く{つもりです}／[見|み]る{つもりです}"},{"pos":"Verb, ない form: plan not to","rule":"[行|い]かない{つもりです}"},{"pos":"Asking about a plan","rule":"[何|なに]をする{つもりですか}"}],"examples":[{"ja":"[来週|らいしゅう]、[山|やま]へ[行|い]く{つもりです}。","en":"I plan to go to the mountains next week.","clip":"x_n5u06d5_p2_1"},{"ja":"あしたは、[外|そと]へ[出|で]ない{つもりです}。","en":"I don't plan to go out tomorrow.","clip":"x_n5u06d5_p2_2"}],"watch":{"note":"The verb before つもり is the dictionary form (行く), not the polite ます form (行きます).","bad":"来週、山へ行きますつもりです。","good":"来週、山へ行くつもりです。"}}],"compare":{"intro":"Both に行きます sentences use に, but one says what you go to do and one says where you go; つもりです says what you plan.","forms":[{"form":"[買|か]いに[行|い]きます","tag":"なにをしに · to do something","mark":"dot","ja":"パンを[買|か]い{に}[行|い]きます。","en":"I am going out to buy bread."},{"form":"[駅|えき]に[行|い]きます","tag":"どこに · to a place","mark":"dot","ja":"あした、[駅|えき]{に}[行|い]きます。","en":"I am going to the station tomorrow."},{"form":"[行|い]くつもりです","tag":"つもり · plan to","mark":"dot","ja":"あした、[山|やま]へ[行|い]く{つもりです}。","en":"I plan to go to the mountains tomorrow."}],"check":{"id":"n5u06d5.c1","kind":"choice","type":"文の文法1","label":"しゃしん","q":"あした、[友|とも]だちと[山|やま]へ^しゃしんをとり^（　　）。","options":["に[行|い]きます","へ[行|い]きます","つもりです"],"answer":1,"why":["とり is the ます form of とります without ます. With に行きます it says what you go to do: take photos.","へ marks a place you go to, and しゃしんをとり is not a place. 山へ already says where.","つもりです needs the dictionary form: とるつもりです. とりつもりです is not Japanese."]}},"drill":[{"id":"n5u06d5.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あした、デパートへくつを（　　）^に[行|い]きます^。","options":["[買|か]う","[買|か]って","[買|か]います","[買|か]い"],"answer":4,"why":["買う is the dictionary form. In this pattern, drop ます from 買います instead: 買いに.","買って is the te-form. 買ってに is not Japanese.","買いますに is not Japanese. Take ます off first: 買いに.","Before に行きます, use the ます form without ます: 買います becomes 買い."],"explain":null},{"id":"n5u06d5.d2","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"[日|にち]よう[日|び]は、[母|はは]と^かいもの^（　　）[行|い]きます。","options":["で","が","に","を"],"answer":3,"why":["で shows where something happens or how. かいもので行きます does not mean \"go shopping\".","が would make かいもの the one who goes. The speaker and mother are the ones going.","かいもの is a noun of action. かいものに行きます means \"go shopping\".","かいものを行きます is not said. To say what you go to do, use に."],"explain":null},{"id":"n5u06d5.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[来週|らいしゅう]の[休|やす]みは、うみへ（　　）^つもりです^。","options":["[行|い]きます","[行|い]って","[行|い]く","[行|い]き"],"answer":3,"why":["行きますつもりです is a common mistake. つもり takes the dictionary form 行く.","行って is the te-form. 行ってつもりです is not Japanese.","つもりです follows the dictionary form: 行くつもりです, \"I plan to go\".","行き is the ます form without ます. It goes before に行きます, not before つもり."],"explain":null},{"id":"n5u06d5.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^あしたはテストです^。[今日|きょう]はテレビを（　　）つもりです。","options":["[見|み]ない","[見|み]ません","[見|み]て","[見|み]に"],"answer":1,"why":["There is a test tomorrow, so the plan is not to watch TV. ない form + つもりです means \"plan not to\".","見ません is the polite \"not\" ending. つもり takes the ない form: 見ないつもりです.","見て is the te-form. 見てつもりです is not Japanese.","見に goes before 行きます or 来ます, not before つもり."]},{"id":"n5u06d5.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[日|にち]よう[日|び]、[友|とも]だちが","after":"。","tiles":["うち","へ","あそび","に[来|き]ます"],"star":2,"bank":[2,0,3,1],"hint":"First the place with へ. Then what the friend comes to do, with に来ます.","full":"[日|にち]よう[日|び]、[友|とも]だちがうちへあそび{に[来|き]ます}。","explain":"うちへ says where the friend comes, and あそびに来ます says why: \"On Sunday a friend is coming to my house to hang out.\""},{"id":"n5u06d5.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[来週|らいしゅう]の[休|やす]みは、","after":"です。","tiles":["[山|やま]","へ","[行|い]く","つもり"],"star":2,"bank":[3,0,2,1],"hint":"The place comes first with へ. The dictionary form 行く goes right before つもり.","full":"[来週|らいしゅう]の[休|やす]みは、[山|やま]へ[行|い]く{つもり}です。","explain":"山へ is where, 行く is the dictionary form, and つもりです comes last: \"Next week on my day off, I plan to go to the mountains.\""}],"exam":[{"id":"n5u06d5.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あした　何を　しますか。」B「としょかんへ　本を（　　）　行きます。」","options":["かえします","かえさない","かえしに","かえす"],"answer":3,"explain":"B goes to the library to return a book: かえしに行きます, the ます form without ます plus に. かえす行きます and かえします行きます are not Japanese; to say what you go to do, drop ます and add に. かえさない is a \"not\" form and makes no sense with 行きます here."},{"id":"n5u06d5.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あしたも　会社に　行きますか。」B「いいえ、あしたは　休みです。会社には（　　）　つもりです。」","options":["行かない","行く","行きません","行って"],"answer":1,"explain":"B says いいえ and tomorrow is a day off, so B plans not to go: 行かないつもりです. 行くつもりです means B plans to go, which does not fit いいえ. 行きません is the polite ending and cannot go before つもり. 行ってつもりです is not Japanese."},{"id":"n5u06d5.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「日よう日は　何を　しますか。」B「山へ　","after":"　つもりです。」","tiles":["しゃしん","を","とりに","行く"],"star":2,"bank":[3,1,0,2],"full":"A「日よう日は　何を　しますか。」B「山へ　しゃしんをとりに行く　{つもり}です。」","explain":"しゃしん, を, とりに, 行く. しゃしんを is what B takes, とりに says what B goes to do, and the dictionary form 行く comes right before つもりです."}]},"scene":{"ja":"カレンダーの　よてい","en":"A wall calendar with plans for next week's days off","intro":"Tap every word on the calendar you need to know when and where this family is going.","words":[{"id":"nextweek","word":"来週","reading":"らいしゅう","gloss":"next week","parts":[["来","ライ","come"],["週","シュウ","week"]],"clip":"s_n5u6d5_nextweek"},{"id":"lastweek","word":"先週","reading":"せんしゅう","gloss":"last week","parts":[["先","セン","before, ahead"],["週","シュウ","week"]],"clip":"s_n5u6d5_lastweek"},{"id":"dayoff","word":"休み","reading":"やすみ","gloss":"day off, holiday","parts":[["休","やす","rest"]],"clip":"s_n5u6d5_dayoff"},{"id":"saturday","word":"土よう日","reading":"どようび","gloss":"Saturday","parts":[["土","ド","earth, soil"],["日","び","day"]],"clip":"s_n5u6d5_saturday"},{"id":"am","word":"午前","reading":"ごぜん","gloss":"a.m., morning","parts":[["午","ゴ","noon"],["前","ゼン","before"]],"clip":"s_n5u6d5_am"},{"id":"mountain","word":"山","reading":"やま","gloss":"mountain","parts":[["山","やま","mountain"]],"clip":"s_n5u6d5_mountain"},{"id":"river","word":"川","reading":"かわ","gloss":"river","parts":[["川","かわ","river"]],"clip":"s_n5u6d5_river"},{"id":"go","word":"行く","reading":"いく","gloss":"go","parts":[["行","い","go"]],"clip":"s_n5u6d5_go"}],"check":{"id":"n5u06d5.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_来週_の　土よう日は　川へ　行く　つもりです。","options":["せんしゅう","らいしゅう","らいしゅ","こんしゅう"],"answer":2,"explain":"来週 is read らいしゅう, \"next week\". らいしゅ is missing the long う. こんしゅう is 今週 (this week) and せんしゅう is 先週 (last week)."}},"skill":{"kind":"listening","ja":"課題理解","en":"Task comprehension","ask":"男の人は　土よう日　はじめに　どこへ　行きますか。","audio":[["N","女の人と男の人が話しています。男の人は、土よう日、はじめにどこへ行きますか。","おんなのひとと　おとこのひとが　はなしています。おとこのひとは、どようび、はじめに　どこへ　いきますか。"],["F","土よう日、いっしょに出かけませんか。","どようび、いっしょに　でかけませんか。"],["M","いいですね。こうえんへ行きますか。","いいですね。こうえんへ　いきますか。"],["F","土よう日は、雨ですよ。駅の前のデパートへ、くつを買いに行きませんか。","どようびは、あめですよ。えきの　まえの　デパートへ、くつを　かいに　いきませんか。"],["M","いいですよ。ぼくは、本やへ、本を買いに行くつもりです。","いいですよ。ぼくは、ほんやへ、ほんを　かいに　いく　つもりです。"],["F","じゃあ、デパートの後で、本やへ行きましょう。","じゃあ、デパートの　あとで、ほんやへ　いきましょう。"],["M","でも、デパートは十一時からですよ。本やは九時からです。","でも、デパートは　じゅういちじからですよ。ほんやは　くじからです。"],["F","そうですか。じゃあ、はじめに本やへ行きましょう。ひるごはんは、デパートのレストランで食べましょう。","そうですか。じゃあ、はじめに　ほんやへ　いきましょう。ひるごはんは、デパートの　レストランで　たべましょう。"],["M","はい、そうしましょう。",null],["N","男の人は、土よう日、はじめにどこへ行きますか。","おとこのひとは、どようび、はじめに　どこへ　いきますか。"]],"item":{"id":"n5u06d5.r1","kind":"choice","type":"課題理解","q":"男の人は　土よう日　はじめに　どこへ　行きますか。","script":["ナレーター：女の人と男の人が話しています。男の人は、土よう日、はじめにどこへ行きますか。","女：土よう日、いっしょに出かけませんか。","男：いいですね。こうえんへ行きますか。","女：土よう日は、雨ですよ。駅の前のデパートへ、くつを買いに行きませんか。","男：いいですよ。ぼくは、本やへ、本を買いに行くつもりです。","女：じゃあ、デパートの後で、本やへ行きましょう。","男：でも、デパートは十一時からですよ。本やは九時からです。","女：そうですか。じゃあ、はじめに本やへ行きましょう。ひるごはんは、デパートのレストランで食べましょう。","男：はい、そうしましょう。","ナレーター：男の人は、土よう日、はじめにどこへ行きますか。"],"options":["デパート","本や","レストラン","こうえん"],"printed":true,"short":["デパート","本や","レストラン","こうえん"],"answer":2,"why":["They first planned the department store, but it opens at eleven, so they go there after the bookshop.","The bookshop opens at nine and the store at eleven, so the woman says はじめに本やへ行きましょう and he agrees.","They will eat lunch at the restaurant in the department store, later in the day.","The man asks about the park, but the woman says it will rain on Saturday, so they do not go there."],"explain":null,"clip":"l_n5u6d5"}}},{"title":"まとめ：似ている文法","grammar":{"points":[],"compare":{"intro":"To tell this unit's points apart, look at the ending: て、〜 joins actions in order, てください asks someone to do something and ないでください asks them not to, てもいいです says it is all right, てはいけません says it is not allowed, なくてもいいです says there is no need, ています is an action going on now or a lasting state, に行きます says what you go to do, and つもりです says what you plan to do.","forms":[{"form":"〜てもいいです","tag":"してもいい · you may","mark":"dot","ja":"このへやでテレビを[見|み]て{もいいです}。","en":"You may watch TV in this room."},{"form":"〜てはいけません","tag":"してはだめ · you must not","mark":"down","ja":"このへやで[電話|でんわ]をかけ{てはいけません}。","en":"You must not make phone calls in this room."},{"form":"〜なくてもいいです","tag":"しなくてもいい · you don't have to","mark":"dot","ja":"このへやには[毎日|まいにち][来|こ]な{くてもいいです}。","en":"You don't have to come to this room every day."}],"check":{"id":"n5u06d6.c1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^ここにペンがたくさんあります^から、ペンはもって（　　）。","options":["[来|き]てはいけません","[来|こ]なくてもいいです","[来|き]てもいいです"],"answer":2,"why":["This says you must not bring a pen. Many pens being here is not a reason to ban yours.","There are many pens here, so you do not need to bring one: もって来なくてもいいです.","This says you may bring a pen. But から gives a reason: there are many pens here already. That is a reason you need not bring one, not a reason you may."],"explain":null}},"drill":[{"id":"n5u06d6.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"テストのとき、^となりの[人|ひと]のこたえ^を（　　）。","options":["[見|み]てもいいです","[見|み]ないでください","[見|み]なくてもいいです","[見|み]てください"],"answer":2,"why":["てもいいです says it is all right to look. In a test, looking at the next person's answers is not all right.","ないでください asks you not to do something: during the test, please don't look at the answers of the person next to you.","なくてもいいです says you do not need to look, as if looking were normally asked of you. The point here is that looking is not allowed.","てください asks you to look at the next person's answers. No test asks that."]},{"id":"n5u06d6.d2","kind":"choice","type":"文の文法1","label":"Choose the words","q":"A：お[母|かあ]さんはうちにいますか。B：いいえ。[母|はは]は[今|いま]、[店|みせ]へパンを（　　）^[行|い]って^（　　）。","options":["[買|か]いに／ください","[買|か]う／います","[買|か]いに／います","[買|か]います／います"],"answer":3,"why":["買いに is right, but 行ってください asks the listener to go. B is telling A where Mom is, so it does not fit 母は.","買う cannot join 行って. Before 行きます, use the ます form without ます plus に: 買いに.","買いに行って says she went to buy bread, and います says that is how things are now: she has gone to the shop, so she is not home.","買います cannot join 行って. Take off ます and add に: 買いに."]},{"id":"n5u06d6.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは[今|いま]、[中国|ちゅうごく]にすんでいます。^[来年|らいねん]^、[日本|にほん]に（　　）。","options":["すむつもりです","すみました","すみますつもりです","すんでください"],"answer":1,"why":["すむ is the dictionary form, and すむつもりです says what I plan to do next year: live in Japan.","すみました is the past. 来年 means next year, so the sentence needs a plan.","つもり follows the dictionary form, すむ, not the ます form すみます.","てください asks someone else to do something. Here わたし is talking about my own plan."],"explain":null},{"id":"n5u06d6.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[毎日|まいにち]、うちへかえって、てを（　　）^、ごはんを[食|た]べます^。","options":["あらっています","あらって","あらいます","あらってください"],"answer":2,"why":["The sentence goes on after the blank to 食べます, so the verb here takes the te-form, not ています.","The te-form joins actions in order: I go home, wash my hands, and eat. The last verb, 食べます, gives the ending for the whole sentence.","The sentence goes on after the blank to 食べます, so the verb here takes the te-form, not the ます ending.","てください asks someone to wash. This sentence tells what I do every day, and it goes on after the blank."],"explain":null},{"id":"n5u06d6.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"このへやで","after":"[飲|の]んでもいいです。","tiles":["パンを","[食|た]べては","いけませんが","[水|みず]を"],"star":1,"bank":[3,1,0,2],"hint":"Which food goes with 食べては, and which drink goes with 飲んでも at the end?","full":"このへやでパンを{[食|た]べては}いけませんが[水|みず]を[飲|の]んでもいいです。","explain":"パンを goes with 食べては, and 食べては goes with いけません: you must not eat bread. が then turns to what is all right: 水を goes with 飲んでもいいです at the end. \"You must not eat bread in this room, but you may drink water.\""},{"id":"n5u06d6.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[先生|せんせい]、ちょっと[外|そと]へ","after":"いいですか。","tiles":["ジュースを","[買|か]いに","[行|い]って","も"],"star":2,"bank":[3,0,2,1],"hint":"What do you go out to do? Which tile joins the te-form to いいですか?","full":"[先生|せんせい]、ちょっと[外|そと]へジュースを[買|か]いに{[行|い]って}もいいですか。","explain":"ジュースを goes with 買いに, and 買いに goes with 行って: go out to buy juice. Then 行って + もいいですか asks for permission. \"Teacher, may I go out for a moment to buy juice?\""}],"exam":[{"id":"n5u06d6.e1","kind":"choice","type":"文の文法1","label":"Choose the answer","q":"A「この　へやで　コーヒーを　飲んでも　いいですか。」\nB「すみません、ここでは（　　）。水は　いいですよ。」","options":["飲んで　ください","飲んでは　いけません","飲んでも　いいです","飲まなくても　いいです"],"answer":2,"explain":"B starts with すみません and then says water is all right, so coffee is not allowed: 飲んでは　いけません. 飲まなくても　いいです says A does not need to drink it, which does not answer a request for permission. 飲んで　ください asks A to drink it, and 飲んでも　いいです allows it; neither fits すみません and the contrast with 水は　いいですよ."},{"id":"n5u06d6.e2","kind":"choice","type":"文の文法1","label":"Choose the answer","q":"A「この　かみに　名前も　書きますか。」\nB「いいえ、名前は（　　）　いいです。ばんごうだけ　書いて　ください。」","options":["書いては","書かなくても","書きますも","書いても"],"answer":2,"explain":"B says いいえ and asks for only the number, so there is no need to write the name: 書かなくても　いいです. 書いても　いいです would allow the name, which does not go with いいえ and ばんごうだけ. 書いては goes with いけません, not いいです. 書きますも is not Japanese: も follows the te-form."},{"id":"n5u06d6.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"今　へやで　いもうとが　","after":"こえで　電話を　しないで　ください。","tiles":["ねて","います","から","大きい"],"star":2,"bank":[2,0,3,1],"full":"今　へやで　いもうとが　ねて　います　{から}　大きい　こえで　電話を　しないで　ください。","explain":"ねて, います, から, 大きい. いもうとが goes with ねて　います: she is sleeping now. から gives that as the reason. 大きい goes right before こえで: please don't talk on the phone in a loud voice."}]},"scene":{"ja":"学校のおしらせ","en":"A notice board at a school","intro":"Tap each word on the notice board in the school hall.","words":[{"id":"every-day","word":"毎日","reading":"まいにち","gloss":"every day","parts":[["毎","マイ","every"],["日","ニチ","day"]],"clip":"s_n5u6d6_every_day"},{"id":"every-week","word":"毎週","reading":"まいしゅう","gloss":"every week","parts":[["毎","マイ","every"],["週","シュウ","week"]],"clip":"s_n5u6d6_every_week"},{"id":"lights","word":"電気","reading":"でんき","gloss":"light; electricity","parts":[["電","デン","electricity"],["気","キ","spirit, energy"]],"clip":"s_n5u6d6_lights"},{"id":"water","word":"水","reading":"みず","gloss":"water","parts":[["水","みず","water"]],"clip":"s_n5u6d6_water"},{"id":"go-out","word":"出る","reading":"でる","gloss":"to go out, to leave","parts":[["出","で","go out"]],"clip":"s_n5u6d6_go_out"},{"id":"pm","word":"午後","reading":"ごご","gloss":"p.m., afternoon","parts":[["午","ゴ","noon"],["後","ゴ","after"]],"clip":"s_n5u6d6_pm"},{"id":"next-month","word":"来月","reading":"らいげつ","gloss":"next month","parts":[["来","ライ","come, next"],["月","ゲツ","month"]],"clip":"s_n5u6d6_next_month"},{"id":"friday","word":"金よう日","reading":"きんようび","gloss":"Friday","parts":[["金","キン","gold, Friday"],["日","び","day"]],"clip":"s_n5u6d6_friday"}],"check":{"id":"n5u06d6.k1","kind":"choice","type":"表記","label":"How the exam asks it","q":"_まいにち_　午後　五時に　学校の　ドアを　しめます。","options":["毎日","母日","毎目","毎月"],"answer":1,"explain":"まいにち, every day, is written 毎日. 母 (mother) looks like 毎 but is a different kanji, and 目 (eye) looks like 日. 毎月 is a real word, but it means every month and is read まいつき."}},"skill":{"kind":"reading","ja":"情報検索","en":"Finding information","ask":"Until what time is the library open on Friday?","seconds":90,"passage":"学校の　としょしつ\n月よう日〜木よう日　午前九時〜午後六時\n^金よう日　午前九時〜午後三時^\n土よう日・日よう日　休み\n毎週　水よう日の　午後四時から　そうじを　します。その　時間は　入らないで　ください。\nとしょしつで　電話を　しないで　ください。","strategy":"Find the line that starts with 金よう日 and read the second time on it.","item":{"id":"n5u06d6.r1","kind":"choice","type":"読解・情報検索","q":"金よう日、としょしつは　何時まで　あいて　いますか。","options":["午前九時","午後三時","午後四時","午後六時"],"short":["9:00 a.m.","3:00 p.m.","4:00 p.m.","6:00 p.m."],"answer":2,"explain":"The line 金よう日　午前九時〜午後三時 gives the Friday hours. The library opens at nine and closes at three in the afternoon.","why":["Nine in the morning is when the library opens, not when it closes.","","Four in the afternoon is when cleaning starts on Wednesdays.","Six in the evening is the closing time from Monday to Thursday, not Friday."]}}}],"test":[{"id":"n5u06t.1","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"この　ビルの　_出口_は　あちらです。","options":["でるくち","いりぐち","でくち","でぐち"],"answer":4,"explain":"出口 is でぐち, exit. いりぐち is a real word, but it is 入口 (entrance), not 出口. In 出口 the 口 is ぐち, so でくち is not a word, and でるくち uses the verb でる; it is not a word either."},{"id":"n5u06t.2","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"あしたの　_午後_、友だちと　えいがを　見に　行きます。","options":["ごこ","ごぜん","ごご","ごうご"],"answer":3,"explain":"午後 is ごご, afternoon. ごぜん is a real word, but it is 午前 (morning, a.m.). ごうご has a long ごう, and ごこ has こ without the dakuten; neither is a word."},{"id":"n5u06t.3","kind":"choice","type":"表記","label":"Kanji spelling","q":"つかれましたね。少し　_やすんで_　ください。","options":["木んで","休んで","安んで","本んで"],"answer":2,"explain":"やすんで (rest) is written 休んで, from 休みます. 安 is the やす of 安い (cheap), and it does not write the verb やすむ. 本 (book) and 木 (tree) only look like 休; 本んで and 木んで are not words."},{"id":"n5u06t.4","kind":"choice","type":"表記","label":"Kanji spelling","q":"先生の　話を　よく　_きいて_　ください。","options":["間いて","書いて","耳いて","聞いて"],"answer":4,"explain":"きいて (listen) is 聞いて, from 聞きます. 書いて is a real word, but it is かいて (write). 間 is the かん of 時間 and 耳 means ear; 間いて and 耳いて are not words."},{"id":"n5u06t.5","kind":"choice","type":"文脈規定","label":"Word in context","q":"へやが　くらいですね。でんきを　（　　）　ください。","options":["しめて","けして","あけて","つけて"],"answer":4,"explain":"The room is dark, so you ask someone to turn the light on: でんきを つけて ください. けして (turn off) would make the room darker. You open and close doors and windows with あけて and しめて, not a light."},{"id":"n5u06t.6","kind":"choice","type":"文脈規定","label":"Word in context","q":"A「すみません、トイレは　どこですか。」B「この　ろうかを　まっすぐ　行って、（　　）に　まがって　ください。」","options":["中","前","右","上"],"answer":3,"explain":"まがって means turn, and you turn right or left: 右に まがって (turn right). 前に is the way you are already going (まっすぐ), so it is not a turn. 上に and 中に do not say which way to turn in a hallway."},{"id":"n5u06t.7","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"あしたは　学校が　_休み_です。","options":["あしたは　学校に　行きます。","あしたは　学校が　あさからです。","あしたは　学校で　べんきょうします。","あしたは　学校が　ありません。"],"answer":4,"explain":"学校が 休みです means there is no school that day, the same as 学校が ありません. 学校に 行きます and 学校で べんきょうします say the opposite. 学校が あさからです says when school starts, so there is school."},{"id":"n5u06t.8","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"あの　人は　_わたしの　おばあさん_です。","options":["あの　人は　わたしの　あにの　子どもです。","あの　人は　わたしの　母の　お母さんです。","あの　人は　わたしの　父の　おねえさんです。","あの　人は　わたしの　母の　いもうとです。"],"answer":2,"explain":"おばあさん is your grandmother, and your mother's mother is a grandmother. Your father's older sister and your mother's younger sister are aunts (おばさん). Your older brother's child is a niece or nephew."},{"id":"n5u06t.9","kind":"choice","type":"文の文法1","label":"Choose the form","q":"友だちと　五時まで　こうえんで　（　　）、うちへ　かえりました。","options":["あそって","あそんで","あそいで","あそびて"],"answer":2,"explain":"あそびます (play) is a verb whose ます form ends in び, so its て form is あそんで: あそんで、かえりました (played, then went home). You cannot add て straight to the stem, so あそびて is wrong. あそって and あそいで use the endings of other verbs (like まって and およいで)."},{"id":"n5u06t.10","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あぶないですから、この　川で　（　　）　ください。","options":["およがなくて","およいで","およがないで","およぎませんで"],"answer":3,"explain":"The river is dangerous, so this asks people not to swim: およがないで ください. およいで ください asks them to swim, the opposite of what あぶないですから needs. The polite ません form does not go before で ください, and およがなくて ください is not a request."},{"id":"n5u06t.11","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　えんぴつで　（　　）　いいですか。」B「いいえ、ペンで　書いて　ください。」","options":["書きても","書いては","書くも","書いても"],"answer":4,"explain":"A asks for permission, which is the て form + も いいですか: 書いても いいですか (may I write?). 書きて is not the て form of 書きます. 書いては goes with いけません, not いいですか. 書く (the dictionary form) does not go before も here."},{"id":"n5u06t.12","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あしたは　休みですから、はやく　（　　）　いいです。ゆっくり　ねて　ください。","options":["おきなくても","おきても","おきては","おきないくても"],"answer":1,"explain":"It is a holiday and the speaker says to sleep in, so you don't have to get up early: おきなくても いいです. おきても いいです (you may get up early) does not fit ゆっくり ねて ください. おきては goes with いけません, not いいです. おきないくても keeps the い of ない, which must be dropped (おきなくても)."},{"id":"n5u06t.13","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　しんぶんを　うちへ　もって　かえっても　いいですか。」B「いいえ、みんなの　しんぶんですから、（　　）。」","options":["もって　かえっては　いけません","もって　かえらなくても　いいです","もって　かえっても　いいです","もって　かえって　ください"],"answer":1,"explain":"B says いいえ to a request for permission and gives a reason (it is everyone's newspaper), so B says you must not take it home: もって かえっては いけません. もって かえっても いいです and もって かえって ください would mean yes, not いいえ. もって かえらなくても いいです (you don't have to take it) does not answer \"may I take it?\"."},{"id":"n5u06t.14","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「もしもし、今　何を　して　いますか。」B「駅の　前で　友だちを　（　　）。」","options":["まって　ください","まちます","まって　います","まちました"],"answer":3,"explain":"A asks what B is doing right now (今 何を して いますか), so B answers with the て form + います: まって います (I am waiting). まちます is for habits or plans, not this moment. まちました is finished, and まって ください asks A to wait, which does not answer the question."},{"id":"n5u06t.15","kind":"choice","type":"文の文法1","label":"Choose the form","q":"日よう日、こうえんへ　花を　（　　）　行きました。","options":["見に","見へ","見るに","見ますに"],"answer":1,"explain":"To say why you go somewhere, use the ます form without ます + に: 見に 行きました (went to see). The purpose takes に, not へ, so 見へ is wrong. The dictionary form (見る) and the full ます form (見ます) do not go before に 行きます."},{"id":"n5u06t.16","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「どうやって　駅へ　行きますか。」B「この　みちを　","after":"　右に　まがって　ください。」","tiles":["まっすぐ","行って","二つめの","かどを"],"star":1,"bank":[2,0,3,1],"full":"A「どうやって　駅へ　行きますか。」B「この　みちを　まっすぐ　{行って}　二つめの　かどを　右に　まがって　ください。」","explain":"まっすぐ, 行って, 二つめの, かどを. まっすぐ goes right before the verb it describes: まっすぐ 行って (go straight, and then). 二つめの joins the noun after it: 二つめの かどを (the second corner), and かどを comes just before 右に まがって. 行って cannot come after かどを, because then まがって has no corner to turn at."},{"id":"n5u06t.17","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あそこで　","after":"が　わたしの　あにです。","tiles":["ギターを","ひいて","いる","人"],"star":1,"bank":[1,3,0,2],"full":"あそこで　ギターを　{ひいて}　いる　人が　わたしの　あにです。","explain":"ギターを, ひいて, いる, 人. ギターを needs its verb after it: ギターを ひいて (playing the guitar). いる follows the て form to say it is happening now, and the whole part describes 人: ひいて いる 人 (the person who is playing). 人 must come last, right before が."},{"id":"n5u06t.18","kind":"star","type":"文の文法2","label":"Build the sentence","before":"来年　とうきょうへ　","after":"　行く　つもりです。","tiles":["日本語","を","べんきょうし","に"],"star":2,"bank":[3,2,0,1],"full":"来年　とうきょうへ　日本語を　{べんきょうし}に　行く　つもりです。","explain":"日本語, を, べんきょうし, に. を marks what you study, so it goes right after 日本語: 日本語を べんきょうし. The purpose of going takes the ます form without ます + に: べんきょうしに 行く. に cannot go after 日本語, because then べんきょうし has nothing to join 行く."},{"id":"n5u06t.19","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"みなさんへ\nあしたは　みんなで　山へ　行きます。あさ　八時に　学校の　前に　来て　ください。おべんとうと　飲みものを　もって　来て　ください。おかしは　もって　来ても　いいです。でも、ゲームは　もって　来ては　いけません。あしたは　いい　天気ですから、かさは　もって　来なくても　いいです。\n先生","q":"もって　来ては　いけない　ものは　どれですか。","options":["おかし","かさ","ゲーム","おべんとう"],"answer":3,"short":["おかし","かさ","ゲーム","おべんとう"],"explain":"The note says ゲームは もって 来ては いけません: games must not be brought. おかし is allowed (もって 来ても いいです). かさ is just not needed (もって 来なくても いいです), which is different from not allowed. おべんとう must be brought (もって 来て ください)."},{"id":"n5u06t.20","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"みなさんへ\nあしたは　みんなで　山へ　行きます。あさ　八時に　学校の　前に　来て　ください。おべんとうと　飲みものを　もって　来て　ください。おかしは　もって　来ても　いいです。でも、ゲームは　もって　来ては　いけません。あしたは　いい　天気ですから、かさは　もって　来なくても　いいです。\n先生","q":"ただしい　ものは　どれですか。","options":["おかしは　もって　来ても　いいです。","かさは　もって　来て　ください。","飲みものは　もって　来ないで　ください。","おべんとうは　もって　来なくても　いいです。"],"answer":1,"short":["おかしはいい","かさをもってくる","飲みものはだめ","おべんとうはいらない"],"explain":"The note says おかしは もって 来ても いいです, so snacks are allowed. おべんとう and 飲みもの must be brought (もって 来て ください), so the options about 飲みもの and おべんとう say the opposite. かさ does not have to be brought because the weather will be good, so 来て ください is wrong."},{"id":"n5u06t.21","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"さくらとしょかん\n火よう日〜日よう日　午前　九時〜午後　七時\n（月よう日は　休み）\n＊本は　一人　五さつまで　かりても　いいです。\n＊としょかんの　中で　飲みものを　飲まないで　ください。\n＊としょかんの　中で　電話を　かけては　いけません。","q":"ヤンさんは　としょかんで　何を　しても　いいですか。","options":["本を　読みながら　ジュースを　飲みます。","中で　友だちに　電話を　かけます。","本を　四さつ　かります。","月よう日に　本を　かります。"],"answer":3,"short":["ジュース","電話","四さつ","月よう日"],"explain":"One person may borrow up to five books (五さつまで), so four books is all right. Drinking inside is not allowed (飲まないで ください), and phone calls are not allowed (かけては いけません). The library is closed on 月よう日 (休み)."},{"id":"n5u06t.22","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"さくらとしょかん\n火よう日〜日よう日　午前　九時〜午後　七時\n（月よう日は　休み）\n＊本は　一人　五さつまで　かりても　いいです。\n＊としょかんの　中で　飲みものを　飲まないで　ください。\n＊としょかんの　中で　電話を　かけては　いけません。","q":"リーさんは　本を　かりに　行きたいです。いつ　行きますか。","options":["月よう日の　午後　三時","水よう日の　午前　八時","金よう日の　午後　八時","土よう日の　午前　十一時"],"answer":4,"short":["月・三時","水・八時","金・八時","土・十一時"],"explain":"On 土よう日 the library is open from 午前 九時 to 午後 七時, so 午前 十一時 is fine. 月よう日 is the library's day off. 午前 八時 is before it opens at nine, and 午後 八時 is after it closes at seven."},{"id":"n5u06t.23","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"リサさんへ\n今、わたしは　かぞくと　こうえんに　います。わたしは　木の　下で　この　メールを　書いて　います。いもうとは　いぬと　あそんで　います。父と　母は　店で　おべんとうを　買って　います。午後は　みんなで　川へ　魚を　見に　行く　つもりです。\nマリ","q":"いもうとは　今　何を　して　いますか。","options":["おべんとうを　買って　います。","川で　魚を　見て　います。","メールを　書いて　います。","いぬと　あそんで　います。"],"answer":4,"short":["おべんとう","魚","メール","いぬ"],"explain":"The email says いもうとは いぬと あそんで います: the sister is playing with the dog. マリ, the writer, is writing the email. The parents are buying lunch boxes. Seeing the fish at the river is the plan for the afternoon, not what anyone is doing now."},{"id":"n5u06t.24","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"リサさんへ\n今、わたしは　かぞくと　こうえんに　います。わたしは　木の　下で　この　メールを　書いて　います。いもうとは　いぬと　あそんで　います。父と　母は　店で　おべんとうを　買って　います。午後は　みんなで　川へ　魚を　見に　行く　つもりです。\nマリ","q":"マリさんたちは　午後　何を　しますか。","options":["うちで　メールを　書きます。","川へ　魚を　見に　行きます。","こうえんで　いぬと　あそびます。","店で　おべんとうを　買います。"],"answer":2,"short":["メール","川で魚","いぬ","おべんとう"],"explain":"The email says 午後は みんなで 川へ 魚を 見に 行く つもりです: in the afternoon they plan to go to the river to see fish. Buying lunch boxes, writing the email and playing with the dog are what the family is doing now, in the park, not the afternoon plan."}]},{"n":7,"ja":"普通形","en":"Plain forms","days":[{"title":"辞書形・ない形","grammar":{"points":[{"id":"n5u07d1.p1","form":"辞書形","gloss":"dictionary form (plain present)","connect":[{"pos":"る-verbs, like 食べます, 見ます, おきます: drop ます and add る","rule":"[食|た]べます → [食|た]べ{る}・[見|み]ます → [見|み]{る}"},{"pos":"う-verbs: the sound before ます moves from the い-row to the う-row (い → う, き → く, み → む, ち → つ, り → る)","rule":"[買|か]います → [買|か]{う}・[書|か]きます → [書|か]{く}・[行|い]きます → [行|い]{く}・[飲|の]みます → [飲|の]{む}・まちます → ま{つ}"},{"pos":"します and 来ます are special. With friends and family, the dictionary form takes the place of 〜ます","rule":"します → {する}・[来|き]ます → {[来|く]る}"}],"examples":[{"ja":"あした、[友|とも]だちと[山|やま]へ[行|い]{く}よ。","en":"I'm going to the mountains with a friend tomorrow.","clip":"x_n5u07d1_p1_1"},{"ja":"[今|いま]から[何|なに]を{する}？","en":"What are you going to do now?","clip":"x_n5u07d1_p1_2"}],"watch":{"note":"With friends, the dictionary form is the whole verb. Do not add です after it. To be polite, use the ます form instead: 行きます.","bad":"あした、わたしも行くです。","good":"あした、わたしも行く。"}},{"id":"n5u07d1.p2","form":"ない形","gloss":"plain negative (do not …)","connect":[{"pos":"る-verbs: drop る and add ない","rule":"[食|た]べる → [食|た]べ{ない}・[見|み]る → [見|み]{ない}"},{"pos":"う-verbs: the last sound moves to the あ-row, then ない. う becomes わ, not あ. Some verbs that end in る are う-verbs too: 入る → 入らない","rule":"[書|か]く → [書|か]か{ない}・[飲|の]む → [飲|の]ま{ない}・まつ → また{ない}・[買|か]う → [買|か]わ{ない}"},{"pos":"する and 来る are special (来ない is read こない). The opposite of ある is just ない","rule":"する → {しない}・[来|く]る → {[来|こ]ない}・ある → {ない}"}],"examples":[{"ja":"あしたは[学校|がっこう]へ[行|い]か{ない}。","en":"I'm not going to school tomorrow.","clip":"x_n5u07d1_p2_1"},{"ja":"[父|ちち]はコーヒーを[飲|の]ま{ない}。","en":"My dad doesn't drink coffee.","clip":"x_n5u07d1_p2_2"}],"watch":{"note":"When the verb ends in う, the う becomes わ before ない, not あ: 買う → 買わない.","bad":"今日は何も買あない。","good":"今日は何も買わない。"}}],"compare":{"intro":"All three talk about the same habit. Who you are talking to, and yes or no, decide the form.","forms":[{"form":"辞書形","tag":"ともだちと · plain, to friends","mark":"dot","ja":"[毎日|まいにち]、[新聞|しんぶん]を[読|よ]{む}。","en":"I read the newspaper every day (to a friend)."},{"form":"ない形","tag":"ひてい · plain, not","mark":"down","ja":"[新聞|しんぶん]は[読|よ]ま{ない}。","en":"I don't read the newspaper (to a friend)."},{"form":"〜ます","tag":"ていねい · polite","mark":"dot","ja":"[毎日|まいにち]、[新聞|しんぶん]を[読|よ]み{ます}。","en":"I read the newspaper every day (polite)."}],"check":{"id":"n5u07d1.c1","kind":"choice","type":"文の文法1","label":"先生に","q":"[先生|せんせい]、あしたも[学校|がっこう]に（　　）か。","options":["[来|き]ます","[来|く]る","[来|こ]ない"],"answer":1,"why":["You speak to a teacher politely, so use the ます form: 来ますか.","来る is the plain form, for friends. 来るか to a teacher sounds rough.","来ないか is a rough, casual invitation, and it asks the wrong thing. You are asking if the teacher comes."],"explain":null}},"drill":[{"id":"n5u07d1.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：[今|いま]から[何|なに]を^する^？B：[本|ほん]を（　　）よ。","options":["[読|よ]みる","[読|よ]る","[読|よ]む","[読|よ]く"],"answer":3,"why":["読みます is a う-verb. Do not keep み and add る; み changes to む.","Only the sound before ます changes, and み becomes む, not る.","A asks in the plain form, so B answers in it too. 読みます has み before ます, so the dictionary form is 読む.","く is for verbs with き before ます, like 書きます → 書く."],"explain":null},{"id":"n5u07d1.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：あした、テニス（　　）？B：^うん、いいね^！","options":["する","しく","しる","すく"],"answer":1,"why":["します is special: its dictionary form is する. A plain question between friends: テニス、する？","しく is not a form of します.","し comes from します, but the dictionary form of します is する. しる is a different verb (to know).","く is for verbs with き before ます, like 書きます → 書く. します is special."],"explain":null},{"id":"n5u07d1.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[今日|きょう]は[店|みせ]で^[何|なに]も^（　　）。","options":["[買|か]わない","[買|か]あない","[買|か]いない","[買|か]らない"],"answer":1,"why":["何も needs a negative verb. 買う ends in う, which becomes わ: 買わない.","The last sound moves to the あ-row, but う is special: it becomes わ, not あ.","い is the sound in 買います. ない does not go after the ます-form sound.","ら is for う-verbs that end in る, like 入る → 入らない. 買う ends in う."],"explain":null},{"id":"n5u07d1.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：[山川|やまかわ]さんも[来|く]る？B：^ううん^、[山川|やまかわ]さんは（　　）よ。","options":["くない","こらない","こない","きない"],"answer":3,"why":["く stays only in くる. Before ない it changes to こ.","来る is not a う-verb, so there is no ら. It is just こ + ない.","ううん means no, so B needs the ない form. 来る is special: its ない form is こない.","き is the sound in 来ます. The ない form uses こ instead."],"explain":null},{"id":"n5u07d1.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あしたは","after":"よ。","tiles":["[七時|しちじ]に","おきて","[学校|がっこう]へ","[行|い]く"],"star":3,"bank":[2,0,3,1],"hint":"First the time, then getting up in the て form. The dictionary form 行く ends the casual sentence, right before よ.","full":"あしたは[七時|しちじ]におきて[学校|がっこう]へ[行|い]{く}よ。","explain":"七時に says when you get up, so it comes right before おきて. 学校へ goes with 行く, and 行く, the plain form, ends the sentence before よ."},{"id":"n5u07d1.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[日|にち]よう[日|び]は","after":"よ。","tiles":["うちに","いて","どこへも","[行|い]かない"],"star":2,"bank":[3,1,0,2],"hint":"どこへも needs a negative verb right after it. うちに goes with いて.","full":"[日|にち]よう[日|び]はうちにいてどこへも[行|い]か{ない}よ。","explain":"うちにいて (I stay at home) is the first part, in the て form. どこへも goes with a negative, so it sits right before 行かない, which ends the sentence before よ."}],"exam":[{"id":"n5u07d1.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あした　何を　する？」　B「友だちと　山へ　（　　）よ。」","options":["行む","行きる","行る","行く"],"answer":4,"explain":"行きます has き before ます, so the dictionary form is 行く: I'm going to the mountains with a friend. 行る and 行む change き to the wrong sound, and 行きる keeps き, which a う-verb never does."},{"id":"n5u07d1.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　ケーキ、食べる？」　B「ううん、今は　（　　）。」","options":["食べらない","食べるない","食べない","食べかない"],"answer":3,"explain":"食べる is a る-verb: drop る and add ない, so 食べない, not now. 食べらない and 食べかない treat it like a う-verb, and 食べるない keeps る."},{"id":"n5u07d1.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あした　友だちと　","after":"よ。","tiles":["えいがを","見て","ばんごはんを","食べる"],"star":1,"bank":[2,3,0,1],"full":"あした　友だちと　えいがを　{見て}　ばんごはんを　食べるよ。","explain":"えいがを, 見て, ばんごはんを, 食べる. えいがを goes with 見て, the first action. ばんごはんを 食べる is the second action, and the dictionary form ends the sentence before よ."}]},"scene":{"ja":"ドアのメモ","en":"A note on the door","intro":"Your friend came by while you were out and left a note on your door. Tap each word on it.","words":[{"id":"today","word":"今日","reading":"きょう","gloss":"today","parts":[["今日","きょう","today (a special reading for the two kanji together)"]],"clip":"s_n5u7d1_today"},{"id":"three","word":"三時","reading":"さんじ","gloss":"three o'clock","parts":[["三","サン","three"],["時","ジ","o'clock, time"]],"clip":"s_n5u7d1_three"},{"id":"later","word":"後で","reading":"あとで","gloss":"later","parts":[["後","あと","after, later"]],"clip":"s_n5u7d1_later"},{"id":"come","word":"来る","reading":"くる","gloss":"come","parts":[["来","く","come"]],"clip":"s_n5u7d1_come"},{"id":"go","word":"行く","reading":"いく","gloss":"go","parts":[["行","い","go"]],"clip":"s_n5u7d1_go"},{"id":"eat","word":"食べる","reading":"たべる","gloss":"eat","parts":[["食","た","eat"]],"clip":"s_n5u7d1_eat"},{"id":"drink","word":"飲む","reading":"のむ","gloss":"drink","parts":[["飲","の","drink"]],"clip":"s_n5u7d1_drink"},{"id":"see","word":"見る","reading":"みる","gloss":"see, watch","parts":[["見","み","see"]],"clip":"s_n5u7d1_see"}],"check":{"id":"n5u07d1.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_後で_　電話するね。","options":["ごで","まえで","うしろで","あとで"],"answer":4,"explain":"後で is read あとで, later: I'll call you later. うしろ (behind) is written 後ろ, with ろ. ご is the reading in 午後, but ごで is not a word. まえ is 前."}},"skill":{"kind":"listening","ja":"即時応答","en":"Quick response","ask":"えなどが　ありません。ぶんを　聞いて、1から3の　中から、いちばん　いい　ものを　一つ　えらんで　ください。","item":{"id":"n5u07d1.r1","kind":"choice","type":"即時応答","q":"男：あした、うちに　来る？","script":["男：あした、うちに　来る？","ナレーター：1","女：うん、来ない。","ナレーター：2","女：うん、行く。","ナレーター：3","女：ううん、行く。"],"options":["うん、来ない。","うん、行く。","ううん、行く。"],"printed":false,"short":["うん、来ない","うん、行く","ううん、行く"],"answer":2,"why":["うん means yes, but 来ない means she won't come. The two halves do not match.","A plain question gets a plain answer. When you go to the other person's place, you say 行く, not 来る.","ううん means no, but 行く says she will go. The two halves do not match."],"clip":"l_n5u7d1"},"audio":[["M","あした、うちに　来る？","あした、うちに　くる？"],["N","1","いち"],["F","うん、来ない。","うん、こない。"],["N","2","に"],["F","うん、行く。","うん、いく。"],["N","3","さん"],["F","ううん、行く。","ううん、いく。"]]}},{"title":"た形・〜たことがある","grammar":{"points":[{"id":"n5u07d2.p1","form":"〜た／〜なかった","gloss":"did / didn't (plain past)","connect":[{"pos":"Verb: take the て-form and change て／で to た／だ","rule":"[食|た]べて→[食|た]べ{た}・[書|か]いて→[書|か]い{た}・[読|よ]んで→[読|よ]ん{だ}"},{"pos":"行く, する and 来る (learn these as they are)","rule":"[行|い]っ{た}・し{た}・[来|き]{た}"},{"pos":"Did not: take the ない-form and change ない to なかった","rule":"[食|た]べ{なかった}・[行|い]か{なかった}・し{なかった}"}],"examples":[{"ja":"きのう、[友|とも]だちと[山|やま]に[行|い]っ{た}。","en":"Yesterday I went to the mountains with a friend.","clip":"x_n5u07d2_p1_1"},{"ja":"けさは[何|なに]も[食|た]べ{なかった}。","en":"I didn't eat anything this morning.","clip":"x_n5u07d2_p1_2"}],"watch":{"note":"行く is special. Its た-form is 行った, just like its て-form 行って.","bad":"きのう、こうえんに行いた。","good":"きのう、こうえんに行った。"}},{"id":"n5u07d2.p2","form":"〜たことがあります","gloss":"have done before (experience)","connect":[{"pos":"Verb, た-form","rule":"[行|い]った・[食|た]べた ＋ {ことがあります}"},{"pos":"Never done (so far)","rule":"[見|み]た ＋ {ことがありません}"},{"pos":"Asking: add か","rule":"[読|よ]んだ ＋ {ことがありますか}"}],"examples":[{"ja":"わたしは[外国|がいこく]に[行|い]った{ことがあります}。","en":"I have been abroad.","clip":"x_n5u07d2_p2_1"},{"ja":"すしを[食|た]べた{ことがありますか}。","en":"Have you ever eaten sushi?","clip":"x_n5u07d2_p2_2"}],"watch":{"note":"〜たことがあります is for something you have done at some time in your life. For something you did this morning, just use the past: 食べました.","bad":"けさ、ごはんを食べたことがあります。","good":"けさ、ごはんを食べました。"}}],"compare":{"intro":"All three talk about the past. た is the plain past, ました is the polite past, and たことがあります says you have the experience.","forms":[{"form":"〜た","tag":"ふつう · did (plain)","mark":"dot","ja":"きのう[山|やま]に[行|い]っ{た}。","en":"I went to the mountains yesterday."},{"form":"〜ました","tag":"ていねい · did (polite)","mark":"dot","ja":"きのう[山|やま]に[行|い]き{ました}。","en":"I went to the mountains yesterday."},{"form":"〜たことがあります","tag":"けいけん · have done before","mark":"dot","ja":"この[山|やま]に[行|い]った{ことがあります}。","en":"I have been to this mountain before."}],"check":{"id":"n5u07d2.c1","kind":"choice","type":"文の文法1","label":"あさごはんの話","q":"A：けさ、[何|なに]を（　　）か。B：パンを[食|た]べました。","options":["[食|た]べました","[食|た]べたことがあります","[食|た]べます"],"answer":1,"why":["けさ is one time today, so A uses the polite past, and B answers the same way.","たことがあります asks about experience in your life. It does not go with けさ, this morning.","食べます is for now or later, but けさ is already past, and B answers with 食べました."]}},"drill":[{"id":"n5u07d2.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^きのう^は^どこにも^（　　）。","options":["[行|い]きなかった","[行|い]かなかった","[行|い]った","[行|い]かない"],"answer":2,"why":["The ない-form of 行く is 行かない, so the past is 行かなかった. 行きなかった is not a word.","どこにも needs a \"not\" form, and きのう needs the past: 行かなかった.","どこにも goes with a \"not\" form. どこにも行った is not said.","行かない is for now or later, but きのう is yesterday."],"explain":null},{"id":"n5u07d2.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^きのう^、[友|とも]だちがうちに（　　）。","options":["くる","きた","こた","くった"],"answer":2,"why":["くる is for now or later, but きのう is yesterday.","The た-form of 来る is 来た, read きた.","こ is used in 来ない, not before た.","くった is not a form of 来る."],"explain":null},{"id":"n5u07d2.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは^まだ^[外国|がいこく]に[行|い]った（　　）。","options":["ことをします","ことがありません","ことがあります","ことでした"],"answer":2,"why":["The experience pattern is ことがある, not ことをする.","まだ … ことがありません: I have not been abroad yet.","まだ here needs a \"not\" ending. まだ行ったことがあります is not said.","ことでした does not follow the た-form to talk about experience."],"explain":null},{"id":"n5u07d2.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：[日本|にほん]のおかしを（　　）^ことがありますか^。B：はい、あります。","options":["[食|た]べた","[食|た]べます","[食|た]べて","[食|た]べました"],"answer":1,"why":["ことがありますか follows the た-form: 食べたことがありますか, \"have you ever eaten…?\".","The polite ます form does not go before こと.","The て-form does not go before こと.","The polite ました form does not go before こと. Use the plain 食べた."]},{"id":"n5u07d2.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしは","after":"。","tiles":["[大|おお]きい","[山|やま]に","のぼった","ことがありません"],"star":2,"bank":[2,0,3,1],"hint":"大きい describes a noun. Which verb form comes right before こと?","full":"わたしは[大|おお]きい[山|やま]にのぼった{ことがありません}。","explain":"大きい describes 山, so 大きい山に goes together. The た-form のぼった comes before ことがありません, which ends the sentence."},{"id":"n5u07d2.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"きのうは","after":"。","tiles":["[本|ほん]を","[読|よ]んで","テレビは","[見|み]なかった"],"star":1,"bank":[2,3,1,0],"hint":"You read a book and watch TV. Which form can end the sentence?","full":"きのうは[本|ほん]を[読|よ]んでテレビは[見|み]{なかった}。","explain":"本を goes with 読んで, and the て-form links to the next part. テレビは goes with 見なかった, the past negative, which ends the sentence."}],"exam":[{"id":"n5u07d2.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「きのう　何を　した？」\nB「うちで　べんきょうを　（　　）。」","options":["しった","する","した","して"],"answer":3,"explain":"A asks about yesterday in plain style, so B answers with the plain past of する: した. して asks someone to do it, しった is not a form of する, and する is for now or later."},{"id":"n5u07d2.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　まちの　古い　おてらを　見た　（　　）　ありますか。」\nB「いいえ、まだ　ありません。」","options":["ことに","ことで","ことが","ことを"],"answer":3,"explain":"Experience is た-form + ことが　あります. ことを, ことに and ことで cannot go before あります here."},{"id":"n5u07d2.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしは　","after":"　ありません。","tiles":["外国の","川で","およいだ","ことが"],"star":2,"bank":[3,2,0,1],"full":"わたしは　外国の　川で　{およいだ}　ことが　ありません。","explain":"外国の, 川で, およいだ, ことが. 外国の must sit right before 川, and the た-form およいだ comes before ことが　ありません."}]},"scene":{"ja":"りょこうのパンフレット","en":"A travel brochure for a mountain town","intro":"Tap every word with kanji that you can find in the brochure.","words":[{"id":"mountain","word":"山","reading":"やま","gloss":"mountain","parts":[["山","やま","mountain"]],"clip":"s_n5u7d2_mountain"},{"id":"river","word":"川","reading":"かわ","gloss":"river","parts":[["川","かわ","river"]],"clip":"s_n5u7d2_river"},{"id":"flower","word":"花","reading":"はな","gloss":"flower","parts":[["花","はな","flower"]],"clip":"s_n5u7d2_flower"},{"id":"weather","word":"天気","reading":"てんき","gloss":"weather","parts":[["天","テン","sky, heaven"],["気","キ","spirit, air"]],"clip":"s_n5u7d2_weather"},{"id":"abroad","word":"外国","reading":"がいこく","gloss":"foreign country, abroad","parts":[["外","ガイ","outside"],["国","コク","country"]],"clip":"s_n5u7d2_abroad"},{"id":"old","word":"古い","reading":"ふるい","gloss":"old","parts":[["古","ふる","old"]],"clip":"s_n5u7d2_old"},{"id":"big","word":"大きい","reading":"おおきい","gloss":"big","parts":[["大","おお","big"]],"clip":"s_n5u7d2_big"},{"id":"train","word":"電車","reading":"でんしゃ","gloss":"train","parts":[["電","デン","electricity"],["車","シャ","vehicle"]],"clip":"s_n5u7d2_train"}],"check":{"id":"n5u07d2.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"あしたの　_天気_は　どうですか。","options":["てんき","てんけ","でんき","てんぎ"],"answer":1,"explain":"天気 is read てんき, \"weather\". でんき is 電気, \"electricity\", and てんけ and てんぎ are not words."}},"skill":{"kind":"reading","ja":"内容理解（短文）","en":"Short passage","ask":"What has the writer done before, and what has he not done yet?","seconds":90,"passage":"リンさん、げんきですか。\nわたしは　いま　北の　まちに　います。きのうは　古い　おてらを　見ました。あしたは　大きい　山に　のぼります。三年前にも　のぼった　ことが　あります。^でも、川の　魚は　まだ　食べた　ことが　ありません^。こんばん　食べます。\nケン","strategy":"Look for まだ … ことがありません (not yet), and do not confuse it with what is planned for tomorrow.","item":{"id":"n5u07d2.r1","kind":"choice","type":"読解・内容理解（短文）","q":"ケンさんが　まだ　した　ことが　ない　ことは　どれですか。","options":["大きい　山に　のぼる　こと","川の　魚を　食べる　こと","北の　まちへ　行く　こと","古い　おてらを　見る　こと"],"short":["大きい山にのぼる","川の魚を食べる","北のまちへ行く","古いおてらを見る"],"answer":2,"explain":"Ken writes 川の魚はまだ食べたことがありません: he has not eaten the river fish yet. He will eat it tonight.","why":["He will climb tomorrow, but he climbed it three years ago too (三年前にものぼったことがあります).","","He is in the northern town now (いま北のまちにいます).","He saw the old temple yesterday (きのうは古いおてらを見ました)."]}}},{"title":"〜から（理由）・〜が（でも）","grammar":{"points":[{"id":"n5u07d3.p1","form":"〜から","gloss":"because …, so …","connect":[{"pos":"Verb or い adjective, polite or plain form","rule":"[行|い]きます{から}／[行|い]く{から}／ねむい{から}"},{"pos":"〜 is a noun or a な adjective: add です or だ","rule":"〜です{から}／〜だ{から}（[雨|あめ]だ{から}）"},{"pos":"Answering どうして (why): the reason, then から","rule":"どうしてですか。…[時間|じかん]がありません{から}。"}],"examples":[{"ja":"[今日|きょう]は[雨|あめ]です{から}、タクシーで[行|い]きます。","en":"It's raining today, so I'll go by taxi.","clip":"x_n5u07d3_p1_1"},{"ja":"ねむい{から}、もうねます。","en":"I'm sleepy, so I'm going to bed now.","clip":"x_n5u07d3_p1_2"}],"watch":{"note":"After a noun, put です or だ before から. 雨から means \"from the rain\", not \"because it's raining\".","bad":"雨から、今日は行きません。","good":"雨ですから、今日は行きません。"}},{"id":"n5u07d3.p2","form":"〜が","gloss":"…, but …","connect":[{"pos":"Verb or い adjective, polite form","rule":"[行|い]きます{が}／[高|たか]いです{が}"},{"pos":"〜 is a noun or a な adjective: add です","rule":"〜です{が}（しずかです{が}）"},{"pos":"The second part goes against what the first part makes you expect","rule":"[高|たか]いです{が}、おいしいです。"}],"examples":[{"ja":"この[店|みせ]は[小|ちい]さいです{が}、[安|やす]いです。","en":"This shop is small, but it's cheap.","clip":"x_n5u07d3_p2_1"},{"ja":"[本|ほん]は[読|よ]みます{が}、[新聞|しんぶん]は[読|よ]みません。","en":"I read books, but I don't read newspapers.","clip":"x_n5u07d3_p2_2"}],"watch":{"note":"でも cannot sit at the end of the first part. Use が there, or end the sentence and start the next one with でも.","bad":"このかばんは高いでも、買います。","good":"このかばんは高いですが、買います。"}}],"compare":{"intro":"All three join two ideas: から gives a reason, and が and でも both say \"but\".","forms":[{"form":"〜から","tag":"〜です＋から · because, so","mark":"dot","ja":"おなかがすきました{から}、パンを[食|た]べます。","en":"I'm hungry, so I'll eat some bread."},{"form":"〜が","tag":"〜です＋が · but","mark":"dot","ja":"このへやはせまいです{が}、あかるいです。","en":"This room is small, but it's bright."},{"form":"でも","tag":"〜。でも、〜 · but (starts the next sentence)","mark":"dot","ja":"この[店|みせ]は[高|たか]いです。{でも}、おいしいです。","en":"This shop is expensive. But it's good."}],"check":{"id":"n5u07d3.c1","kind":"choice","type":"文の文法1","label":"ピクニック","q":"[天気|てんき]がいいです（　　）、[外|そと]で[食|た]べましょう。","options":["でも","から","が"],"answer":2,"why":["でも starts a new sentence (いいです。でも、…). It cannot come right after いいです inside one sentence, and \"but\" does not fit the meaning either.","The good weather is the reason for eating outside: \"The weather is nice, so let's eat outside.\"","が means \"but\". Nice weather and eating outside do not go against each other."],"explain":null}},"drill":[{"id":"n5u07d3.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^ねつがありました^（　　）、[学校|がっこう]を[休|やす]みました。","options":["でも","も","が","から"],"answer":4,"why":["でも starts a new sentence (ありました。でも、…). It cannot follow ありました inside one sentence.","も means \"too\" and goes after a noun. It cannot join two sentences.","が means \"but\". Having a fever is not something that goes against staying home.","The fever is the reason: \"I had a fever, so I stayed home from school.\""],"explain":null},{"id":"n5u07d3.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[今日|きょう]は^[日|にち]よう[日|び]^（　　）、[学校|がっこう]は[休|やす]みです。","options":["いから","ですが","だから","から"],"answer":3,"why":["いから is not a form. い belongs to い adjectives such as ねむい, and 日よう日 is a noun.","ですが means \"but\". Sunday and school being closed do not go against each other.","Noun + だから gives the reason: \"Today is Sunday, so there is no school.\"","日よう日 is a noun, so it needs だ or です before から. 日よう日から means \"from Sunday\"."],"explain":null},{"id":"n5u07d3.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"このアパートはひろいです（　　）、^[古|ふる]いです^。","options":["を","が","でも","から"],"answer":2,"why":["を marks the thing you do something to. It cannot join two sentences.","Big is good and old is not, so が (but) joins them: \"This flat is big, but it's old.\"","でも starts a new sentence (ひろいです。でも、…). It cannot follow ひろいです inside one sentence.","から gives a reason, but being big is not the reason the flat is old."],"explain":null},{"id":"n5u07d3.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[毎日|まいにち][電車|でんしゃ]で[会社|かいしゃ]へ[行|い]きます（　　）、^[今日|きょう]はバスで[行|い]きました^。","options":["から","が","でも","まで"],"answer":2,"why":["から gives a reason, but going by train every day is not the reason for taking the bus today.","Every day it is the train, but today it was the bus: \"I go to work by train every day, but today I went by bus.\"","でも starts a new sentence (行きます。でも、…). It cannot follow 行きます inside one sentence.","まで means \"until\" or \"as far as\". 行きますまで is not correct."],"explain":null},{"id":"n5u07d3.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"おなかが","after":"ません。","tiles":["いたいです","から","[何|なに]も","[食|た]べ"],"star":1,"bank":[2,0,3,1],"hint":"おなかが goes with いたいです, and から comes right after the reason. 何も goes before the verb with ません.","full":"おなかがいたいです{から}[何|なに]も[食|た]べません。","explain":"いたいです, から, 何も, 食べ. The stomachache is the reason, so から follows いたいです: \"My stomach hurts, so I won't eat anything.\""},{"id":"n5u07d3.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"この[店|みせ]は","after":"ありません。","tiles":["ひろい","ですが、","あまり","きれいじゃ"],"star":3,"bank":[3,1,0,2],"hint":"ひろい goes with ですが、. あまり needs a negative, so it goes before きれいじゃ ありません.","full":"この[店|みせ]はひろい{ですが}、あまりきれいじゃありません。","explain":"ひろい, ですが、, あまり, きれいじゃ. ですが joins the good point and the bad point, and あまり goes with the negative: \"This shop is big, but it's not very clean.\""}],"exam":[{"id":"n5u07d3.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"今日は　雨（　　）、　テニスは　しません。","options":["まで","が","から","だから"],"answer":4,"explain":"雨 is a noun, so it needs だ before から: 雨だから, \"because it's raining\". 雨から means \"from the rain\", and 雨まで means \"until the rain\". 雨が needs a verb after it, such as ふります."},{"id":"n5u07d3.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしの　へやは　せまいです（　　）、　まどが　大きくて　あかるいです。","options":["が","と","から","も"],"answer":1,"explain":"The room is small (bad), but the window is big and bright (good), so が, \"but\", joins them. から would make the small room the reason for the big window. も and と cannot join two sentences here."},{"id":"n5u07d3.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あしたは　テストが","after":"します。","tiles":["あります","から","今日は","べんきょう"],"star":1,"bank":[2,3,1,0],"full":"あしたは　テストが　あります　{から}　今日は　べんきょう　します。","explain":"あります, から, 今日は, べんきょう. テストが あります is the reason, so から follows it, and 今日は べんきょう します is the result: \"I have a test tomorrow, so I'll study today.\""}]},"scene":{"ja":"店のドアで","en":"On a shop door","intro":"Tap every word you would read on the notice taped to the shop door.","words":[{"id":"shop","word":"店","reading":"みせ","gloss":"shop","parts":[["店","みせ","shop"]],"clip":"s_n5u7d3_shop"},{"id":"closed","word":"休み","reading":"やすみ","gloss":"closed (day), holiday","parts":[["休","やす","rest"]],"clip":"s_n5u7d3_closed"},{"id":"rain","word":"雨","reading":"あめ","gloss":"rain","parts":[["雨","あめ","rain"]],"clip":"s_n5u7d3_rain"},{"id":"weather","word":"天気","reading":"てんき","gloss":"weather","parts":[["天","テン","sky, heaven"],["気","キ","air, spirit"]],"clip":"s_n5u7d3_weather"},{"id":"afternoon","word":"午後","reading":"ごご","gloss":"afternoon, p.m.","parts":[["午","ゴ","noon"],["後","ゴ","after"]],"clip":"s_n5u7d3_afternoon"},{"id":"four","word":"四時","reading":"よじ","gloss":"four o'clock","parts":[["四","よ","four"],["時","ジ","o'clock, time"]],"clip":"s_n5u7d3_four"},{"id":"monday","word":"月よう日","reading":"げつようび","gloss":"Monday","parts":[["月","ゲツ","moon, month"],["日","び","day"]],"clip":"s_n5u7d3_monday"},{"id":"morning","word":"午前","reading":"ごぜん","gloss":"morning, a.m.","parts":[["午","ゴ","noon"],["前","ゼン","before"]],"clip":"s_n5u7d3_morning"}],"check":{"id":"n5u07d3.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"雨ですから、　店は　午後　_四時_に　しまります。","options":["しじ","よっじ","よんじ","よじ"],"answer":4,"explain":"四時, \"four o'clock\", is read よじ. 四 is often よん (四百, よんひゃく), but before 時 it is よ. しじ is not used for the time, and よっじ is not a word."}},"skill":{"kind":"listening","ja":"ポイント理解","en":"Point comprehension","ask":"女の人は　どうして　土よう日に　えいがに　行きませんか。","audio":[["N","男の人と女の人が話しています。女の人はどうして土よう日にえいがに行きませんか。","おとこのひとと　おんなのひとが　はなしています。おんなのひとは　どうして　どようびに　えいがに　いきませんか。"],["M","山下さん、土よう日にいっしょにえいがを見ませんか。","やましたさん、どようびに　いっしょに　えいがを　みませんか。"],["F","すみません。土よう日はちょっと…。","すみません。どようびは　ちょっと…。"],["M","しごとですか。",null],["F","いいえ、しごとは休みですが、母が国から来ます。いっしょにごはんを食べます。","いいえ、しごとは　やすみですが、ははが　くにから　きます。いっしょに　ごはんを　たべます。"],["M","そうですか。じゃあ、日よう日はどうですか。","そうですか。じゃあ、にちようびは　どうですか。"],["F","日よう日はいいですよ。えいがはだいすきですから。","にちようびは　いいですよ。えいがは　だいすきですから。"],["M","じゃ、日よう日に行きましょう。","じゃ、にちようびに　いきましょう。"],["N","女の人はどうして土よう日にえいがに行きませんか。","おんなのひとは　どうして　どようびに　えいがに　いきませんか。"]],"item":{"id":"n5u07d3.r1","kind":"choice","type":"ポイント理解","q":"女の人は　どうして　土よう日に　えいがに　行きませんか。","script":["ナレーター：男の人と女の人が話しています。女の人はどうして土よう日にえいがに行きませんか。","男：山下さん、土よう日にいっしょにえいがを見ませんか。","女：すみません。土よう日はちょっと…。","男：しごとですか。","女：いいえ、しごとは休みですが、母が国から来ます。いっしょにごはんを食べます。","男：そうですか。じゃあ、日よう日はどうですか。","女：日よう日はいいですよ。えいがはだいすきですから。","男：じゃ、日よう日に行きましょう。","ナレーター：女の人はどうして土よう日にえいがに行きませんか。"],"options":["かぜを　ひいたから","お母さんが　来るから","えいがが　すきじゃないから","しごとが　あるから"],"printed":true,"short":["かぜ","お母さんが 来る","えいがが すきじゃない","しごと"],"answer":2,"why":["Nobody talks about a cold.","しごとは休みですが、母が国から来ます: her mother is coming, and they will eat together.","She says えいがはだいすきですから, and she agrees to go on Sunday.","The man guesses work, but she says いいえ、しごとは休みです."],"explain":null,"clip":"l_n5u7d3"}}},{"title":"〜でしょう・〜と思います","grammar":{"points":[{"id":"n5u07d4.p1","form":"〜でしょう","gloss":"probably; …, right?","connect":[{"pos":"Verb or い-adjective, plain form","rule":"ふる／さむい ＋ {でしょう}"},{"pos":"〜 is a noun or a な-adjective (no だ)","rule":"〜 ＋ {でしょう}"},{"pos":"Checking with the listener (voice goes up)","rule":"〜{でしょう}？"}],"examples":[{"ja":"あしたの[午後|ごご]は[雨|あめ]{でしょう}。","en":"Tomorrow afternoon it will probably rain.","clip":"x_n5u07d4_p1_1"},{"ja":"このケーキ、おいしい{でしょう}？","en":"This cake is good, isn't it?","clip":"x_n5u07d4_p1_2"}],"watch":{"note":"でしょう takes the place of です. Do not put です before it.","bad":"あしたはさむいですでしょう。","good":"あしたはさむいでしょう。"}},{"id":"n5u07d4.p2","form":"〜とおもいます","gloss":"I think …","connect":[{"pos":"Verb or い-adjective, plain form","rule":"[来|こ]ない／たかい ＋ {とおもいます}"},{"pos":"〜 is a noun or a な-adjective: add だ","rule":"〜だ ＋ {とおもいます}"},{"pos":"Plain past works too","rule":"[来|き]た／[雨|あめ]だった ＋ {とおもいます}"}],"examples":[{"ja":"[山川|やまかわ]さんは[今日|きょう]は[来|こ]ない{とおもいます}。","en":"I think Mr. Yamakawa won't come today.","clip":"x_n5u07d4_p2_1"},{"ja":"リンさんは[学生|がくせい]だ{とおもいます}。","en":"I think Lin is a student.","clip":"x_n5u07d4_p2_2"}],"watch":{"note":"A noun before とおもいます needs だ: 先生だとおもいます.","bad":"あの人は先生とおもいます。","good":"あの人は先生だとおもいます。"}}],"compare":{"intro":"All three talk about tomorrow's weather. What changes is how sure the speaker is, and whose view it is.","forms":[{"form":"〜でしょう","tag":"たぶん · probably","mark":"dot","ja":"あしたは[雨|あめ]{でしょう}。","en":"It will probably rain tomorrow."},{"form":"〜とおもいます","tag":"わたしのいけん · I think","mark":"dot","ja":"あしたは[雨|あめ]がふる{とおもいます}。","en":"I think it will rain tomorrow."},{"form":"〜です","tag":"ほんとう · a sure fact","mark":"dot","ja":"[今日|きょう]は[雨|あめ]{です}。","en":"It's rainy today."}],"check":{"id":"n5u07d4.c1","kind":"choice","type":"文の文法1","label":"あしたのてんき","q":"「あしたは[雨|あめ]ですか。」「たぶん[雨|あめ]^だ^（　　）。」","options":["とおもいます","です","でしょう"],"answer":1,"why":["A noun takes だ before とおもいます: 雨だとおもいます.","です comes right after 雨, without だ.","でしょう comes right after 雨, without だ: 雨でしょう."],"explain":null}},"drill":[{"id":"n5u07d4.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^あした^の[午前|ごぜん]は[雨|あめ]が（　　）。","options":["ふったでしょう","ふってでしょう","ふるでしょう","ふりますでしょう"],"answer":3,"why":["ふった is past, but あした is tomorrow.","The て form does not go before でしょう.","The plain form ふる + でしょう: a guess about tomorrow.","The polite ます form does not go before でしょう."],"explain":null},{"id":"n5u07d4.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"「この[本|ほん]、おもしろい（　　）？」「^ええ、とても^おもしろいです。」","options":["でしょう","ですでしょう","だでしょう","なでしょう"],"answer":1,"why":["おもしろい + でしょう with the voice going up: \"It's interesting, right?\"","でしょう takes the place of です. You cannot use both.","だ does not go before でしょう.","おもしろい is an い-adjective, so it never takes な."]},{"id":"n5u07d4.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[山川|やまかわ]さんはかぜですから、^あした^は（　　）とおもいます。","options":["[来|こ]ない","[来|き]ません","[来|こ]なくて","[来|こ]なかった"],"answer":1,"why":["The plain form 来ない goes before とおもいます.","来ません is the polite form. Before と, use the plain form.","The て form cannot end the thought before と.","来なかった is past, but あした is tomorrow."]},{"id":"n5u07d4.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あの[人|ひと]はリンさんのお[父|とう]さん（　　）^とおもいます^。","options":["です","の","だ","な"],"answer":3,"why":["です is polite. Before と, use the plain だ.","お父さんの needs a noun after it, and とおもいます is not one.","お父さん is a noun, so it takes だ before とおもいます.","な does not come after a noun at the end of a thought."],"explain":null},{"id":"n5u07d4.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あしたは","after":"。","tiles":["[雨|あめ]が","ふって、","さむい","でしょう"],"star":1,"bank":[2,0,3,1],"hint":"What happens first, then what is it like? でしょう comes last.","full":"あしたは[雨|あめ]がふって、さむい{でしょう}。","explain":"雨が goes with ふって, and the comma joins it to the next part. さむい is the plain form, so でしょう comes right after it."},{"id":"n5u07d4.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あ、","after":"おもいます。","tiles":["この","かさは","[山川|やまかわ]さんの","だと"],"star":2,"bank":[3,1,0,2],"hint":"この points at the umbrella. Whose is it? だと comes right before おもいます.","full":"あ、このかさは[山川|やまかわ]さんのだ{とおもいます}。","explain":"この goes right before かさは. 山川さんの means \"Mr. Yamakawa's\", and it takes だ before とおもいます, like a noun."}],"exam":[{"id":"n5u07d4.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"「リンさんは　どこですか。」「さあ。でも、もう　うちへ　（　　）と　おもいます。」","options":["かえり","かえった","かえりました","かえって"],"answer":2,"explain":"もう says it has already happened, so the plain past かえった goes before と おもいます. かえりました is polite and cannot go before と, and かえって and かえり cannot end the thought."},{"id":"n5u07d4.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あしたは　東の　ほうは　はれですが、西の　ほうは　雨（　　）。","options":["ですでしょう","だと","でしょう","だでしょう"],"answer":3,"explain":"A noun takes でしょう directly: 雨でしょう, a guess about tomorrow. でしょう never comes after だ or です, and 雨だと cannot end the sentence."},{"id":"n5u07d4.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あの　店の","after":"おもいます。","tiles":["ケーキは","やすくて","おいしい","と"],"star":2,"bank":[2,3,0,1],"full":"あの　店の　ケーキは　やすくて　{おいしい}と　おもいます。","explain":"ケーキは, やすくて, おいしい, と. 店の describes ケーキ. やすくて joins on to おいしい, and the plain form おいしい goes before と おもいます."}]},"scene":{"ja":"新聞の天気よほう","en":"The weather forecast in the newspaper","intro":"Tap each word on the forecast that tells you when, where and what the weather will be.","words":[{"id":"weather","word":"天気","reading":"てんき","gloss":"weather","parts":[["天","テン","sky, heaven"],["気","キ","air, spirit"]],"clip":"s_n5u7d4_weather"},{"id":"rain","word":"雨","reading":"あめ","gloss":"rain","parts":[["雨","あめ","rain"]],"clip":"s_n5u7d4_rain"},{"id":"am","word":"午前","reading":"ごぜん","gloss":"morning, a.m.","parts":[["午","ゴ","noon"],["前","ゼン","before"]],"clip":"s_n5u7d4_am"},{"id":"pm","word":"午後","reading":"ごご","gloss":"afternoon, p.m.","parts":[["午","ゴ","noon"],["後","ゴ","after"]],"clip":"s_n5u7d4_pm"},{"id":"east","word":"東","reading":"ひがし","gloss":"east","parts":[["東","ひがし","east"]],"clip":"s_n5u7d4_east"},{"id":"west","word":"西","reading":"にし","gloss":"west","parts":[["西","にし","west"]],"clip":"s_n5u7d4_west"},{"id":"north","word":"北","reading":"きた","gloss":"north","parts":[["北","きた","north"]],"clip":"s_n5u7d4_north"},{"id":"friday","word":"金よう日","reading":"きんようび","gloss":"Friday","parts":[["金","キン","gold; Friday"],["日","び","day"]],"clip":"s_n5u7d4_friday"}],"check":{"id":"n5u07d4.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"あしたの　_午後_は　雨でしょう。","options":["ごご","ごぜん","ごうご","ごごう"],"answer":1,"explain":"午後 is ごご, the afternoon. ごぜん is 午前, the morning. ごうご and ごごう are not words."}},"skill":{"kind":"reading","ja":"内容理解（短文）","en":"Short passage","ask":"Why is the writer taking a sweater?","seconds":90,"passage":"今日は　あさから　雨でした。でも、天気よほうでは　「あしたは　はれるでしょう」と　言って　いました。あしたは　友だちと　山へ　行きます。^山の　上は　さむいと　おもいます^。^だから^、セーターを　もって　行きます。","strategy":"Find とおもいます: the writer's own guess comes before it, and だから tells you what she does because of it.","item":{"id":"n5u07d4.r1","kind":"choice","type":"読解・内容理解（短文）","q":"この　人は　どうして　セーターを　もって　行きますか。","options":["あしたは　雨が　ふるから。","山の　上は　さむいと　おもうから。","友だちが　さむいと　言ったから。","今日は　雨で　さむかったから。"],"short":["あしたは雨がふる","山の上はさむいとおもう","友だちが言った","今日さむかった"],"answer":2,"explain":"The writer thinks it will be cold on the mountain (さむいと おもいます), and だから says that is why she takes a sweater.","why":["The forecast says it will be sunny tomorrow (はれるでしょう).","","The writer thinks this herself. The friend says nothing.","Today it rained, but the passage does not say it was cold, and the sweater is for the mountain."]}}},{"title":"〜ほうがいい・〜なければならない","grammar":{"points":[{"id":"n5u07d5.p1","form":"〜ほうがいいです","gloss":"you had better …","connect":[{"pos":"Verb, た form (from day 2)","rule":"ねる→ねた{ほうがいいです}／[飲|の]む→[飲|の]んだ{ほうがいいです}"},{"pos":"Verb, ない form: you had better not","rule":"[食|た]べる→[食|た]べない{ほうがいいです}"},{"pos":"To a friend, drop です","rule":"[休|やす]んだ{ほうがいい}よ"}],"examples":[{"ja":"[今日|きょう]は、はやくねた{ほうがいいです}よ。","en":"You had better go to bed early today.","clip":"x_n5u07d5_p1_1"},{"ja":"あついですから、[外|そと]へ[出|で]ない{ほうがいいです}。","en":"It is hot, so you had better not go outside.","clip":"x_n5u07d5_p1_2"}],"watch":{"note":"Use the plain form before ほうがいいです: 飲んだ or 飲まない. The polite ます form does not go before ほう.","bad":"このくすりを飲みますほうがいいです。","good":"このくすりを飲んだほうがいいです。"}},{"id":"n5u07d5.p2","form":"〜なければなりません","gloss":"must; have to","connect":[{"pos":"Verb, ない form: take off the last い and add ければなりません","rule":"[行|い]かない→[行|い]かな{ければなりません}"},{"pos":"It works the same for every verb","rule":"[食|た]べな{ければなりません}／しな{ければなりません}／[来|こ]な{ければなりません}"},{"pos":"Asking \"Do I have to …?\"","rule":"[名前|なまえ]を[書|か]かな{ければなりませんか}"}],"examples":[{"ja":"[来週|らいしゅう]、[国|くに]へかえらな{ければなりません}。","en":"I have to go back to my country next week.","clip":"x_n5u07d5_p2_1"},{"ja":"ごはんの[後|あと]で、このくすりを[飲|の]まな{ければなりません}。","en":"I must take this medicine after meals.","clip":"x_n5u07d5_p2_2"}],"watch":{"note":"Take off the い of ない first: 行かない becomes 行かなければ. 行かないければ is wrong.","bad":"あしたは学校へ行かないければなりません。","good":"あしたは学校へ行かなければなりません。"}}],"compare":{"intro":"All three talk about what to do: one is advice, one is a must, and one says there is no need.","forms":[{"form":"ねたほうがいいです","tag":"アドバイス · had better","mark":"dot","ja":"[今日|きょう]は、はやくねた{ほうがいいです}。","en":"You had better go to bed early today."},{"form":"[行|い]かなければなりません","tag":"しなければ · must","mark":"up","ja":"あしたは、[学校|がっこう]へ[行|い]かな{ければなりません}。","en":"I have to go to school tomorrow."},{"form":"[行|い]かなくてもいいです","tag":"しなくても · no need","mark":"down","ja":"あしたは[休|やす]みですから、[行|い]かな{くてもいいです}。","en":"Tomorrow is a day off, so you don't have to go."}],"check":{"id":"n5u07d5.c1","kind":"choice","type":"文の文法1","label":"テスト","q":"^あしたはテストです^から、[今日|きょう]はべんきょうし（　　）。","options":["なくてもいいです","なければなりません","ないほうがいいです"],"answer":2,"why":["しなくてもいいです means \"you don't have to study\". With a test tomorrow, that does not make sense.","There is a test tomorrow, so you must study today: べんきょうしなければなりません.","しないほうがいいです is advice not to study. Before a test, that is the wrong advice."]}},"drill":[{"id":"n5u07d5.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^かぜ^ですね。[今日|きょう]はおふろに（　　）ほうがいいですよ。","options":["[入|はい]りません","[入|はい]らない","[入|はい]って","[入|はい]らなくて"],"answer":2,"why":["入りません is the polite ending. Before ほうがいいです, use the plain form: 入らない.","You have a cold, so the advice is not to take a bath. ない form + ほうがいいです means \"you had better not\".","入って is the te-form. 入ってほうがいい is not Japanese.","入らなくて is the te-form of 入らない. It does not go before ほうがいいです."]},{"id":"n5u07d5.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"のどがいたいですね。このくすりを（　　）^ほうがいいです^よ。","options":["[飲|の]んで","[飲|の]み","[飲|の]んだ","[飲|の]みます"],"answer":3,"why":["飲んで is the te-form. 飲んでほうがいい is not Japanese.","飲み is the ます form without ます. It goes before に行きます, not before ほうがいいです.","飲んだ is the た form. た form + ほうがいいです gives advice: \"you had better take this medicine\".","飲みます is the polite ending. The plain form goes before ほう: 飲んだ."],"explain":null},{"id":"n5u07d5.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あしたは[九時|くじ]に[駅|えき]へ（　　）^なりません^。","options":["[行|い]ってければ","[行|い]かないければ","[行|い]きなければ","[行|い]かなければ"],"answer":4,"why":["行って is the te-form. 行ってければ is not Japanese.","The い of 行かない must come off first: 行かな + ければ. 行かないければ is not Japanese.","行き is the ます form without ます. This pattern starts from the ない form 行かない, not from 行きます.","Take 行かない, drop the last い, add ければなりません: \"I have to go to the station at nine.\""],"explain":null},{"id":"n5u07d5.d4","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"A：あしたは[休|やす]みですか。B：^いいえ^、あしたも[会社|かいしゃ]へ[行|い]か（　　）。","options":["ないでください","なければなりません","なくてもいいです","ないほうがいいです"],"answer":2,"why":["行かないでください asks someone else not to go. B is talking about B's own day.","いいえ means tomorrow is not a day off, so B has to go: 行かなければなりません.","行かなくてもいいです means \"I don't have to go\". B said いいえ, tomorrow is not a day off, so that does not fit.","行かないほうがいいです is advice not to go. After いいえ, B is saying tomorrow is a work day, so this does not fit."],"explain":null},{"id":"n5u07d5.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"かぜですから、[今日|きょう]は","after":"いいです。","tiles":["うち","で","[休|やす]んだ","ほうが"],"star":2,"bank":[2,0,3,1],"hint":"First where, with で. Then the た form, then ほうが right before いいです.","full":"かぜですから、[今日|きょう]はうちで[休|やす]んだ{ほうが}いいです。","explain":"うちで says where, 休んだ is the た form, and ほうがいいです comes last: \"You have a cold, so you had better rest at home today.\""},{"id":"n5u07d5.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"このくすりは、","after":"なりません。","tiles":["ごはん","の","[後|あと]で","[飲|の]まなければ"],"star":2,"bank":[3,1,0,2],"hint":"Which meal? Then when? Then the must form before なりません.","full":"このくすりは、ごはんの{[後|あと]で}[飲|の]まなければなりません。","explain":"ごはんの後で says when, and 飲まなければなりません says it is a must: \"You have to take this medicine after meals.\""}],"exam":[{"id":"n5u07d5.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「のどが　いたいです。」B「じゃあ、つめたい　ものは（　　）　ほうが　いいですよ。」","options":["食べません","食べない","食べないで","食べなくて"],"answer":2,"explain":"A has a sore throat, so B advises not eating cold things: 食べないほうがいいです. 食べません is the polite ending and cannot go before ほう. 食べないで and 食べなくて are te-forms, and neither goes before ほうがいいです."},{"id":"n5u07d5.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あしたも　学校へ　来ますか。」B「はい。テストが　ありますから、八時に（　　）　なりません。」","options":["来て","来なければ","来ないければ","来なくても"],"answer":2,"explain":"B has a test, so B must come at eight: 来なければなりません. 来ないければ keeps the い of ない, which must come off. 来なくても goes with いいです (don't have to), not なりません. 来てなりません is not Japanese."},{"id":"n5u07d5.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「あしたは　山へ　行きます。」B「山は　さむいですよ。","after":"　いいですよ。」","tiles":["コートを","もって","行った","ほうが"],"star":2,"bank":[1,3,0,2],"full":"A「あしたは　山へ　行きます。」B「山は　さむいですよ。コートを　もって　行った　{ほうが}　いいですよ。」","explain":"コートを, もって, 行った, ほうが. コートを is what to take, もって行った is the た form of もって行く, and ほうが comes right before いいです: \"You had better take a coat.\""}]},"scene":{"ja":"いしゃの　カード","en":"A card the doctor gives you at a small clinic","intro":"Tap every word on the card you need to know when to take your medicine and what to do at home.","words":[{"id":"everyday","word":"毎日","reading":"まいにち","gloss":"every day","parts":[["毎","マイ","every"],["日","にち","day"]],"clip":"s_n5u7d5_everyday"},{"id":"water","word":"水","reading":"みず","gloss":"water","parts":[["水","みず","water"]],"clip":"s_n5u7d5_water"},{"id":"drink","word":"飲む","reading":"のむ","gloss":"drink; take (medicine)","parts":[["飲","の","drink"]],"clip":"s_n5u7d5_drink"},{"id":"eat","word":"食べる","reading":"たべる","gloss":"eat","parts":[["食","た","eat"]],"clip":"s_n5u7d5_eat"},{"id":"before","word":"前","reading":"まえ","gloss":"before","parts":[["前","まえ","before, front"]],"clip":"s_n5u7d5_before"},{"id":"after","word":"後","reading":"あと","gloss":"after","parts":[["後","あと","after"]],"clip":"s_n5u7d5_after"},{"id":"rest","word":"休む","reading":"やすむ","gloss":"rest; take a day off","parts":[["休","やす","rest"]],"clip":"s_n5u7d5_rest"},{"id":"pm","word":"午後","reading":"ごご","gloss":"p.m., afternoon","parts":[["午","ゴ","noon"],["後","ゴ","after"]],"clip":"s_n5u7d5_pm"}],"check":{"id":"n5u07d5.k1","kind":"choice","type":"文脈規定","label":"How the exam asks it","q":"かぜですから、今日は　うちで（　　）　ほうが　いいです。","options":["休んだ","およいだ","出かけた","はたらいた"],"answer":1,"explain":"With a cold, the advice is to rest at home: 休んだほうがいいです. 出かけた (went out) does not go with うちで. はたらいた (worked) and およいだ (swam) are not good advice for someone with a cold."}},"skill":{"kind":"listening","ja":"課題理解","en":"Task comprehension","ask":"男の人は　この　あと　はじめに　何を　しなければ　なりませんか。","audio":[["N","びょういんで、いしゃと男の人が話しています。男の人は、このあと、はじめに何をしなければなりませんか。","びょういんで、いしゃと　おとこのひとが　はなしています。おとこのひとは、このあと、はじめに　なにを　しなければ　なりませんか。"],["F","かぜですね。今日は、はやくうちへかえって、休んだほうがいいですよ。","かぜですね。きょうは、はやく　うちへ　かえって、やすんだ　ほうが　いいですよ。"],["M","はい。午後は、会社を休みます。","はい。ごごは、かいしゃを　やすみます。"],["F","それから、このくすりを飲まなければなりません。ごはんの後で、飲んでください。","それから、この　くすりを　のまなければ　なりません。ごはんの　あとで、のんで　ください。"],["M","あのう、今日は、まだひるごはんを食べていません。","あのう、きょうは、まだ　ひるごはんを　たべていません。"],["F","じゃあ、くすりの前に、何か食べなければなりませんね。","じゃあ、くすりの　まえに、なにか　たべなければ　なりませんね。"],["M","はい。駅の前の店で何か食べてから、うちへかえります。","はい。えきの　まえの　みせで　なにか　たべてから、うちへ　かえります。"],["F","そうですね。うちでは、水をたくさん飲んで、はやくねたほうがいいですよ。","そうですね。うちでは、みずを　たくさん　のんで、はやく　ねた　ほうが　いいですよ。"],["M","わかりました。ありがとうございました。",null],["N","男の人は、このあと、はじめに何をしなければなりませんか。","おとこのひとは、このあと、はじめに　なにを　しなければ　なりませんか。"]],"item":{"id":"n5u07d5.r1","kind":"choice","type":"課題理解","q":"男の人は　この　あと　はじめに　何を　しなければ　なりませんか。","script":["ナレーター：びょういんで、いしゃと男の人が話しています。男の人は、このあと、はじめに何をしなければなりませんか。","女：かぜですね。今日は、はやくうちへかえって、休んだほうがいいですよ。","男：はい。午後は、会社を休みます。","女：それから、このくすりを飲まなければなりません。ごはんの後で、飲んでください。","男：あのう、今日は、まだひるごはんを食べていません。","女：じゃあ、くすりの前に、何か食べなければなりませんね。","男：はい。駅の前の店で何か食べてから、うちへかえります。","女：そうですね。うちでは、水をたくさん飲んで、はやくねたほうがいいですよ。","男：わかりました。ありがとうございました。","ナレーター：男の人は、このあと、はじめに何をしなければなりませんか。"],"options":["うちで　ねる","くすりを　飲む","ごはんを　食べる","水を　飲む"],"printed":true,"short":["うちでねる","くすりを飲む","ごはんを食べる","水を飲む"],"answer":3,"why":["Going to bed early is advice for later, at home. He eats first.","The medicine is taken after a meal, and he has not had lunch yet, so the medicine comes after eating.","He has not eaten lunch, and the doctor says he must eat before the medicine. He will eat at a shop near the station first.","The doctor says to drink a lot of water at home, after he goes back."],"explain":null,"clip":"l_n5u7d5"}}},{"title":"まとめ：似ている文法","grammar":{"points":[],"compare":{"intro":"To tell this unit's points apart, look at what each one adds: the dictionary, ない and た forms are the plain way to say do, don't and did, たことがあります says you have done something at some time in your life, から gives a reason and が says but, でしょう is a guess (or a check with the listener) and とおもいます is your own view, ほうがいいです gives advice and なければなりません says you must.","forms":[{"form":"〜たことがあります","tag":"したことがある · have done before","mark":"dot","ja":"この[魚|さかな]は[前|まえ]にも[食|た]べた{ことがあります}。","en":"I have eaten this fish before, too."},{"form":"〜たほうがいいです","tag":"したほうがいい · you had better","mark":"up","ja":"この[魚|さかな]は[今日|きょう][食|た]べた{ほうがいいです}。","en":"You had better eat this fish today."},{"form":"〜なければなりません","tag":"しなければならない · you must","mark":"dot","ja":"この[魚|さかな]は[今日|きょう]、[食|た]べな{ければなりません}。","en":"This fish has to be eaten today."}],"check":{"id":"n5u07d6.c1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：すしを[食|た]べた（　　）か。B：いいえ、^まだありません^。","options":["ことがあります","ほうがいいです","なければなりません"],"answer":1,"why":["B answers まだありません, \"not yet\", so A asked about experience: have you ever eaten sushi?","食べたほうがいいですか asks for advice: should I eat sushi? まだありません does not answer that.","なければなりません follows the ない form (食べなければ), not the た form. And B's まだありません answers a question about experience."]}},"drill":[{"id":"n5u07d6.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：このえいが、[見|み]たことがある？B：うん、^[先週|せんしゅう]^[友|とも]だちと（　　）よ。","options":["[見|み]ない","[見|み]た","[見|み]る","[見|み]たことがある"],"answer":2,"why":["見ない means \"I don't watch it\". It does not go with うん or with 先週.","先週 names one time in the past, so the plain past 見た fits: I saw it with a friend last week.","見る is the dictionary form, for now or later. 先週 is last week.","たことがある is for experience at some time in your life. With a set time like 先週, just use the past: 見た."],"explain":null},{"id":"n5u07d6.d2","kind":"choice","type":"文の文法1","label":"Choose the word","q":"このくつは[安|やす]いです（　　）、^[小|ちい]さいですから、[買|か]わないほうがいいです^よ。","options":["が","でも","を","から"],"answer":1,"why":["が says but: the shoes are cheap, but they are small, so you had better not buy them.","でも cannot sit at the end of the first part. It starts a new sentence.","を marks the thing you act on. It cannot follow 安いです.","Cheap is not a reason not to buy them. The reason comes later: 小さいですから."],"explain":null},{"id":"n5u07d6.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：[午後|ごご]は[雨|あめ]がふりますか。B：さあ……。でも、^[空|そら]がくらいです^から、（　　）。","options":["ふったことがあります","ふったほうがいいです","ふらなければなりません","ふるとおもいます"],"answer":4,"why":["たことがあります tells about past experience. A asks about this afternoon.","ほうがいいです gives advice about what someone should do. Rain is not something you can advise.","なければなりません says someone must do something. Rain has no duty to fall.","B is not sure (さあ), but the dark sky is a reason to guess: I think it will rain."],"explain":null},{"id":"n5u07d6.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：あの[店|みせ]の[魚|さかな]は^[古|ふる]いですよ^。B：じゃあ、あの[店|みせ]では（　　）ほうがいいですね。","options":["[買|か]った","[買|か]いません","[買|か]わなかった","[買|か]わない"],"answer":4,"why":["買ったほうがいい says you had better buy it. Old fish is a reason not to.","The polite ます form does not go before ほう. Use the plain form: 買わない.","For \"had better not\", use the ない form, 買わない, not the past 買わなかった.","The fish is old, so the advice is not to buy it: 買わないほうがいいです. Before ほうがいい, \"not\" is the ない form."],"explain":null},{"id":"n5u07d6.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あしたは","after":"かさをもって[行|い]ったほうがいいですよ。","tiles":["[雨|あめ]が","ふる","でしょう","から"],"star":2,"bank":[2,3,0,1],"hint":"First the guess about tomorrow, then the word that makes it a reason for the advice.","full":"あしたは[雨|あめ]がふる{でしょう}からかさをもって[行|い]ったほうがいいですよ。","explain":"雨が goes with ふる, and ふる + でしょう is the guess: it will probably rain. から then makes the guess a reason for the advice at the end. \"It will probably rain tomorrow, so you had better take an umbrella.\""},{"id":"n5u07d6.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[日本|にほん]へは","after":"のぼったことがありません。","tiles":["[行|い]った","ことが","ありますが","ふじ[山|さん]には"],"star":3,"bank":[3,1,0,2],"hint":"Which place goes with 行った, and which goes with のぼった at the end?","full":"[日本|にほん]へは[行|い]ったことがありますが{ふじ[山|さん]には}のぼったことがありません。","explain":"日本へは goes with 行ったことがありますが: I have been to Japan, but. ふじ山には goes right before のぼった: I have never climbed Mount Fuji. \"I have been to Japan, but I have never climbed Mount Fuji.\""}],"exam":[{"id":"n5u07d6.e1","kind":"choice","type":"文の文法1","label":"Choose the answer","q":"子どもの　とき、父と　この　川で　およいだ（　　）。","options":["なければ　なりません","ことが　あります","ほうが　いいです","ことを　します"],"answer":2,"explain":"子どもの　とき is a time in the past, and the speaker tells an experience: I have swum in this river with my father. ほうが　いいです gives advice, which does not fit a memory from childhood. ことを　します is not Japanese here. なければ　なりません follows the ない form (およがなければ), not the た form."},{"id":"n5u07d6.e2","kind":"choice","type":"文の文法1","label":"Choose the answer","q":"あの　店は　いつも　人が　多いです（　　）、　おいしいと　おもいます。","options":["まで","から","を","でも"],"answer":2,"explain":"Many people always go there, and that is the reason for my view: I think it is good. から gives a reason. を marks the thing an action is done to and cannot follow です. でも starts a new sentence and cannot follow 多いです here. まで means until."},{"id":"n5u07d6.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あしたは　六時に　","after":"　はやく　ねた　ほうが　いいです。","tiles":["おきなければ","なりません","から","今日は"],"star":2,"bank":[3,0,2,1],"full":"あしたは　六時に　おきなければ　なりません　{から}　今日は　はやく　ねた　ほうが　いいです。","explain":"おきなければ, なりません, から, 今日は. 六時に goes with おきなければ　なりません: you must get up at six tomorrow. から makes that the reason. 今日は goes with the advice at the end: you had better go to bed early today."}]},"scene":{"ja":"先生からの手がみ","en":"A letter from the teacher about next week's walk","intro":"Tap each word in the teacher's letter about next week's class walk.","words":[{"id":"next-week","word":"来週","reading":"らいしゅう","gloss":"next week","parts":[["来","ライ","come, next"],["週","シュウ","week"]],"clip":"s_n5u7d6_next_week"},{"id":"last-week","word":"先週","reading":"せんしゅう","gloss":"last week","parts":[["先","セン","ahead, before"],["週","シュウ","week"]],"clip":"s_n5u7d6_last_week"},{"id":"time","word":"時間","reading":"じかん","gloss":"time; hours","parts":[["時","ジ","time"],["間","カン","between"]],"clip":"s_n5u7d6_time"},{"id":"rain","word":"雨","reading":"あめ","gloss":"rain","parts":[["雨","あめ","rain"]],"clip":"s_n5u7d6_rain"},{"id":"feet","word":"足","reading":"あし","gloss":"foot, leg","parts":[["足","あし","foot, leg"]],"clip":"s_n5u7d6_feet"},{"id":"long","word":"長い","reading":"ながい","gloss":"long","parts":[["長","なが","long"]],"clip":"s_n5u7d6_long"},{"id":"outside","word":"外","reading":"そと","gloss":"outside","parts":[["外","そと","outside"]],"clip":"s_n5u7d6_outside"},{"id":"name","word":"名前","reading":"なまえ","gloss":"name","parts":[["名","な","name"],["前","まえ","front"]],"clip":"s_n5u7d6_name"}],"check":{"id":"n5u07d6.k1","kind":"choice","type":"表記","label":"How the exam asks it","q":"_らいしゅう_の　土よう日に　みんなで　山を　あるきます。","options":["来週","先週","来年","毎週"],"answer":1,"explain":"らいしゅう, next week, is written 来週. 先週 is せんしゅう, last week. 来年 is らいねん, next year. 毎週 is まいしゅう, every week."}},"skill":{"kind":"reading","ja":"情報検索","en":"Finding information","ask":"How much does a child pay at the pool on Wednesday?","seconds":90,"passage":"さくらプール\n月よう日　休み\n火よう日〜日よう日　午前十時〜午後六時\n大人　四百円　^子ども　二百円^\n^火よう日は　子ども　百円です^。\n雨の　日も　あいて　います。\nプールに　入る　前に、水を　飲んで　ください。","strategy":"Find the price line for 子ども, then check whether the Tuesday line changes it for Wednesday.","item":{"id":"n5u07d6.r1","kind":"choice","type":"読解・情報検索","q":"水よう日、子どもは　いくらですか。","options":["百円","二百円","四百円","六百円"],"short":["100 yen","200 yen","400 yen","600 yen"],"answer":2,"explain":"The line 大人　四百円　子ども　二百円 gives the usual prices. The cheaper price, 百円, is only for Tuesday, so on Wednesday a child pays 二百円.","why":["One hundred yen is the child price on Tuesday only, not Wednesday.","","Four hundred yen is the price for adults.","Six hundred yen is an adult and a child together, not one child."]}}}],"test":[{"id":"n5u07t.1","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"なつ休みに　はじめて　_外国_へ　行きました。","options":["そとくに","がいごく","がいこく","かいこく"],"answer":3,"explain":"外国 is がいこく, a foreign country. The 国 here is こく, not ごく, so がいごく is wrong. かいこく has か without the dakuten. そとくに reads each kanji the way it sounds on its own (そと, くに), but 外国 is never read that way."},{"id":"n5u07t.2","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"わたしの　まちは　とうきょうの　_西_に　あります。","options":["みなみ","きた","にし","ひがし"],"answer":3,"explain":"西 is にし, west. ひがし, みなみ and きた are real words, but they are east (東), south (南) and north (北)."},{"id":"n5u07t.3","kind":"choice","type":"表記","label":"Kanji spelling","q":"友だちと　_でんしゃ_で　うみへ　行った　ことが　あります。","options":["電東","気車","雨車","電車"],"answer":4,"explain":"でんしゃ (train) is written 電車. 雨 (rain) looks like the top of 電 but is not the same kanji, and 東 (east) looks like 車 but is not 車. 気 is the き of 天気; 雨車, 電東 and 気車 are not words."},{"id":"n5u07t.4","kind":"choice","type":"表記","label":"Kanji spelling","q":"あつい　日は　水を　たくさん　_のんだ_　ほうが　いいです。","options":["飲んだ","読んだ","休んだ","話んだ"],"answer":1,"explain":"のんだ (drank) is 飲んだ, from 飲みます. 読んだ and 休んだ are real words, but they are よんだ (read) and やすんだ (rested). 話 is the はな of 話します; 話んだ is not a word."},{"id":"n5u07t.5","kind":"choice","type":"文脈規定","label":"Word in context","q":"そらが　くらいですね。午後は　（　　）が　ふるでしょう。","options":["くもり","かぜ","はれ","雨"],"answer":4,"explain":"The sky is dark, and ふる (fall) is used for rain: 雨が ふるでしょう (it will probably rain). かぜ (wind), はれ (sunny weather) and くもり (cloudy weather) do not fall, so they do not go with ふる."},{"id":"n5u07t.6","kind":"choice","type":"文脈規定","label":"Word in context","q":"この　くつは　もう　（　　）ですから、新しいのを　買います。","options":["高い","安い","新しい","古い"],"answer":4,"explain":"The speaker buys new shoes because these are already old: もう 古いですから. 新しい says the shoes are new, so there is no reason to buy new ones. もう (already) does not fit 高い or 安い; shoes do not become expensive or cheap with time."},{"id":"n5u07t.7","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"_おととい_　友だちに　あいました。","options":["二日後に　友だちに　あいます。","きのう　友だちに　あいました。","二日前に　友だちに　あいました。","三日前に　友だちに　あいました。"],"answer":3,"explain":"おととい is the day before yesterday, which is two days ago: 二日前. きのう is one day ago and 三日前 is three days ago. 二日後 is two days from now, in the future."},{"id":"n5u07t.8","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"わたしは　にくが　_すきじゃ　ありません_。","options":["わたしは　にくが　大すきです。","わたしは　にくを　食べた　ことが　ありません。","わたしは　にくを　よく　食べます。","わたしは　にくが　きらいです。"],"answer":4,"explain":"すきじゃ ありません (do not like) is closest to きらいです (dislike). 大すきです says the opposite. よく 食べます (eat it often) does not fit someone who does not like it. 食べた ことが ありません means never having eaten it, which is not the same as not liking it."},{"id":"n5u07t.9","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あした　パーティーに　行く？」B「ううん、しごとが　あるから　（　　）。」","options":["行くない","行かない","行った","行きない"],"answer":2,"explain":"B says ううん (no), so B uses the plain negative. 行きます ends in き, so ない joins the あ sound: 行かない. ない does not go on the stem (行きない) or on the dictionary form (行くない). 行った is past, but the party is あした."},{"id":"n5u07t.10","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「日よう日、何を　する？」B「うちで　へやの　そうじを　（　　）よ。」","options":["する","した","しる","して"],"answer":1,"explain":"A asks what B will do on Sunday with the plain する, so B answers with the dictionary form: そうじを するよ (I will clean). した is past and does not answer a question about Sunday plans. してよ asks A to do the cleaning. しる is not a form of する."},{"id":"n5u07t.11","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きのうは　つかれて　いたから、九時に　（　　）。","options":["ねた","ねる","ねて","ねった"],"answer":1,"explain":"きのう (yesterday) needs the past. ねます drops ます and adds た: ねた (went to bed). ねる is not past. ねて does not end a sentence about yesterday. ねった adds an extra っ; that is for verbs like かえる (かえった), not ねる."},{"id":"n5u07t.12","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「きものを　（　　）　ことが　ありますか。」B「いいえ、まだ　ありません。」","options":["きました","きた","きて","きます"],"answer":2,"explain":"To ask about experience, use the た form + ことが ありますか: きた ことが ありますか (have you ever worn a kimono?). The て form does not go before こと. The polite きます and きました do not go before こと either; the word before こと must be plain."},{"id":"n5u07t.13","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あには　スポーツが　すきです（　　）、わたしは　あまり　すきじゃ　ありません。","options":["を","から","で","が"],"answer":4,"explain":"The two parts contrast: my brother likes sports, but I don't much. が after です means but. から would say the brother's liking is the reason I don't like sports, which makes no sense. で and を cannot follow です to join two sentences."},{"id":"n5u07t.14","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「リンさんは　もう　ひるごはんを　食べましたか。」B「さあ…。まだ　（　　）と　おもいます。」","options":["食べないだ","食べなかったです","食べて　いない","食べて　いません"],"answer":3,"explain":"Before と おもいます the verb is plain, and まだ (not yet) goes with ～て いない: まだ 食べて いないと おもいます. 食べて いません and 食べなかったです are polite, and polite forms do not go before と おもいます. だ comes after a noun, not after ない, so 食べないだ is wrong."},{"id":"n5u07t.15","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あした　いっしょに　あそびませんか。」B「すみません。あしたは　びょういんへ　（　　）。」","options":["行かないで　ください","行かなければ　なりません","行かなくても　いいです","行っては　いけません"],"answer":2,"explain":"B says すみません to turn down the invitation and gives the reason: B has to go to the hospital, 行かなければ なりません. 行かなくても いいです (I don't have to go) is no reason to say no. 行っては いけません says B must not go, which is not a reason to refuse either. 行かないで ください asks A not to go."},{"id":"n5u07t.16","kind":"star","type":"文の文法2","label":"Build the sentence","before":"きのうは　","after":"　ねました。","tiles":["あたまが","いたかった","から","はやく"],"star":1,"bank":[2,3,1,0],"full":"きのうは　あたまが　{いたかった}から　はやく　ねました。","explain":"あたまが, いたかった, から, はやく. あたまが needs its adjective after it: あたまが いたかった (my head hurt). から follows the plain past to give the reason: いたかったから. はやく describes ねました, so it goes last, right before the verb. はやく cannot come first, because it does not describe いたかった."},{"id":"n5u07t.17","kind":"star","type":"文の文法2","label":"Build the sentence","before":"母は　「あしたは　","after":"」と　言いました。","tiles":["天気が","よく","なる","でしょう"],"star":1,"bank":[3,0,2,1],"full":"母は　「あしたは　天気が　{よく}　なるでしょう」と　言いました。","explain":"天気が, よく, なる, でしょう. 天気が comes first because it is what changes. An adjective before なる takes the く form: よく なる (become good). でしょう follows the plain なる and ends the quote, right before 」と."},{"id":"n5u07t.18","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あついですから、","after":"　いいですよ。","tiles":["ぼうしを","かぶって","出かけた","ほうが"],"star":2,"bank":[1,3,0,2],"full":"あついですから、ぼうしを　かぶって　{出かけた}　ほうが　いいですよ。","explain":"ぼうしを, かぶって, 出かけた, ほうが. ぼうしを needs its verb after it: ぼうしを かぶって (put on a hat, and then). Advice uses the た form + ほうが いい: 出かけた ほうが いいです. ほうが must come right before いいです, and 出かけた right before ほうが."},{"id":"n5u07t.19","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"十月十日（土）\n今日は　リーさんと　山の　上の　こうえんへ　行った。わたしは　はじめてだったが、リーさんは　前にも　来た　ことが　あると　言って　いた。こうえんには　花が　たくさん　あって、とても　きれいだった。かえりに　駅の　前の　店で　ばんごはんを　食べた。","q":"ただしい　ものは　どれですか。","options":["二人は　こうえんで　ばんごはんを　食べました。","リーさんは　前にも　この　こうえんへ　来た　ことが　あります。","こうえんには　花が　あまり　ありませんでした。","わたしは　前にも　この　こうえんへ　来た　ことが　あります。"],"answer":2,"short":["こうえんでごはん","リーさんは前にも来た","花が少ない","わたしは前にも来た"],"explain":"The diary says リーさんは 前にも 来た ことが あると 言って いた, so リーさん had been there before. The writer went for the first time (はじめてだった). They ate dinner at a shop in front of the station, not in the park. The park had a lot of flowers (たくさん)."},{"id":"n5u07t.20","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"十月十日（土）\n今日は　リーさんと　山の　上の　こうえんへ　行った。わたしは　はじめてだったが、リーさんは　前にも　来た　ことが　あると　言って　いた。こうえんには　花が　たくさん　あって、とても　きれいだった。かえりに　駅の　前の　店で　ばんごはんを　食べた。","q":"二人は　かえりに　何を　しましたか。","options":["山の　上で　しゃしんを　とりました。","駅の　前の　店で　ばんごはんを　食べました。","こうえんで　花を　買いました。","リーさんの　うちへ　行きました。"],"answer":2,"short":["しゃしん","駅の前でごはん","花を買った","リーさんのうち"],"explain":"The diary ends かえりに 駅の 前の 店で ばんごはんを 食べた: on the way home they ate dinner at a shop by the station. It says nothing about buying flowers, going to リーさん's house or taking photos."},{"id":"n5u07t.21","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"みどりプール\n午前　十時〜午後　八時（火よう日は　休み）\n・はじめて　来た　人は、うけつけで　名前を　書かなければ　なりません。\n・十さいまでの　子どもは、大人と　いっしょに　入らなければ　なりません。\n・プールに　入る　前に、シャワーを　あびて　ください。\n・プールの　中で　水や　ジュースを　飲まないで　ください。","q":"八さいの　ケンくんは　はじめて　この　プールに　来ました。ただしい　ものは　どれですか。","options":["うけつけで　名前を　書かなければ　なりません。","シャワーを　あびなくても　いいです。","プールの　中で　ジュースを　飲んでも　いいです。","一人で　プールに　入っても　いいです。"],"answer":1,"short":["名前を書く","シャワーなし","中でジュース","一人で入る"],"explain":"ケンくん is here for the first time, so he must write his name at the front desk (はじめて 来た 人は … 書かなければ なりません). He is eight, so he must go in with an adult, not alone. Everyone must shower before going in. Drinking in the pool is not allowed (飲まないで ください)."},{"id":"n5u07t.22","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"みどりプール\n午前　十時〜午後　八時（火よう日は　休み）\n・はじめて　来た　人は、うけつけで　名前を　書かなければ　なりません。\n・十さいまでの　子どもは、大人と　いっしょに　入らなければ　なりません。\n・プールに　入る　前に、シャワーを　あびて　ください。\n・プールの　中で　水や　ジュースを　飲まないで　ください。","q":"アンさんは　この　プールに　行きたいです。いつ　行きますか。","options":["月よう日の　午前　八時","火よう日の　午後　三時","水よう日の　午後　九時","木よう日の　午後　六時"],"answer":4,"short":["月・八時","火・三時","水・九時","木・六時"],"explain":"The pool is open from 午前 十時 to 午後 八時, and it is closed on 火よう日. 木よう日の 午後 六時 is inside those hours. 午前 八時 is two hours before it opens, 火よう日 is its day off, and 午後 九時 is an hour after it closes."},{"id":"n5u07t.23","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ジョンさんへ\nあした、いっしょに　山へ　行きますね。テレビの　ニュースでは、午後から　雨だと　言って　いました。だから、あさ　七時に　出かけた　ほうが　いいと　おもいます。山の　上は　さむいですから、コートを　もって　来て　ください。かさは　わたしが　二本　もって　行きます。\nゆか","q":"ゆかさんは　どうして　七時に　出かけた　ほうが　いいと　おもって　いますか。","options":["午後から　雨が　ふるからです。","山の　上は　さむいからです。","かさが　ないからです。","あさは　雨が　ふるからです。"],"answer":1,"short":["午後から雨","山の上はさむい","かさがない","あさ雨"],"explain":"ゆか writes that the news said 午後から 雨だ, and then だから (so) suggests leaving at seven. The cold on the mountain is the reason for the coat, not for leaving early. ゆか has two umbrellas, and the rain starts in the afternoon, not the morning."},{"id":"n5u07t.24","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ジョンさんへ\nあした、いっしょに　山へ　行きますね。テレビの　ニュースでは、午後から　雨だと　言って　いました。だから、あさ　七時に　出かけた　ほうが　いいと　おもいます。山の　上は　さむいですから、コートを　もって　来て　ください。かさは　わたしが　二本　もって　行きます。\nゆか","q":"ジョンさんは　何を　もって　行かなければ　なりませんか。","options":["コート","おべんとう","かさ","ぼうし"],"answer":1,"short":["コート","おべんとう","かさ","ぼうし"],"explain":"ゆか asks ジョン to bring a coat because it is cold on the mountain: コートを もって 来て ください. ゆか will bring the umbrellas herself (かさは わたしが 二本 もって 行きます). The letter does not mention a hat or a lunch box."}]},{"n":8,"ja":"くらべる・かわる","en":"Comparing and change","days":[{"title":"〜より〜のほうが・〜と〜とどちら","grammar":{"points":[{"id":"n5u08d1.p1","form":"AはBより〜・BよりAのほうが〜","gloss":"A is more … than B","connect":[{"pos":"Noun は ＋ noun より ＋ adjective. The first 〜 is the thing you talk about. The second 〜, with より, is the one you measure it against","rule":"〜は〜{より}[高|たか]いです"},{"pos":"Noun より ＋ noun のほうが ＋ adjective. Here the winner comes second and takes のほうが","rule":"〜より〜{のほうが}[安|やす]いです"}],"examples":[{"ja":"この[電車|でんしゃ]はバス{より}はやいです。","en":"This train is faster than the bus.","clip":"x_n5u08d1_p1_1"},{"ja":"コーヒーよりおちゃ{のほうが}すきです。","en":"I like tea more than coffee.","clip":"x_n5u08d1_p1_2"}],"watch":{"note":"のほうが needs の between the noun and ほう. Do not drop it.","bad":"バスより電車ほうが安いです。","good":"バスより電車のほうが安いです。"}},{"id":"n5u08d1.p2","form":"AとBとどちらが〜ですか","gloss":"which is more …, A or B?","connect":[{"pos":"Question: two nouns, each with と, then どちらが","rule":"〜と〜と{どちらが}[高|たか]いですか"},{"pos":"Answer: the one you choose ＋ のほうが","rule":"〜{のほうが}[高|たか]いです"},{"pos":"Answer when it is true of both","rule":"{どちらも}[高|たか]いです"}],"examples":[{"ja":"[電車|でんしゃ]とバスと{どちらが}[安|やす]いですか。","en":"Which is cheaper, the train or the bus?","clip":"x_n5u08d1_p2_1"},{"ja":"A：いぬとねこと、どちらがすきですか。B：{どちらも}すきです。","en":"A: Which do you like better, dogs or cats? B: I like both.","clip":"x_n5u08d1_p2_2"}],"watch":{"note":"For two things, ask with どちら. どれ is for three or more things.","bad":"電車とバスとどれが安いですか。","good":"電車とバスとどちらが安いですか。"}}],"compare":{"intro":"All three are about choosing. How many things there are, and whether you ask or answer, decide the form.","forms":[{"form":"〜より〜のほうが","tag":"くらべる · A is more than B","mark":"up","ja":"バスより[電車|でんしゃ]{のほうが}はやいです。","en":"The train is faster than the bus."},{"form":"どちら","tag":"二つ · which of two","mark":"dot","ja":"バスと[電車|でんしゃ]と{どちら}がはやいですか。","en":"Which is faster, the bus or the train?"},{"form":"どれ","tag":"たくさん · which of three or more","mark":"dot","ja":"{どれ}があなたの[本|ほん]ですか。","en":"Which one is your book? (of several)"}],"check":{"id":"n5u08d1.c1","kind":"choice","type":"文の文法1","label":"Two things","q":"[電車|でんしゃ]とバスと（　　）が[安|やす]いですか。","options":["なに","どれ","どちら"],"answer":3,"why":["なに asks what something is. The two things are already named, so you ask which one.","どれ is for three or more things. Here there are only two: the train and the bus.","Two things, 電車 and バス, are listed with と, so ask with どちら."],"explain":null}},"drill":[{"id":"n5u08d1.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この[店|みせ]は^あの[店|みせ]^（　　）[安|やす]いです。","options":["から","で","と","より"],"answer":4,"why":["から means from or because. It does not compare two things.","で marks a place where something happens. It does not compare two things.","と means and or with. あの店と安いです does not make sense.","This shop is being measured against that shop, so あの店 takes より: cheaper than that shop."],"explain":null},{"id":"n5u08d1.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^バスより^[電車|でんしゃ]（　　）はやいです。","options":["ほうが","よりが","のほうを","のほうが"],"answer":4,"why":["の is missing. A noun needs の before ほう: 電車のほうが.","よりが is not a form. より already went on バス.","はやい is an adjective, so the winner takes が, not を.","バスより names the loser, so the winner 電車 takes のほうが: the train is faster."],"explain":null},{"id":"n5u08d1.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：^コーヒーとこうちゃと^（　　）がいいですか。B：こうちゃのほうがいいです。","options":["どちら","どこ","だれ","どれ"],"answer":1,"why":["A offers two drinks, coffee and black tea, so A asks with どちら.","どこ asks about a place, not a drink.","だれ asks about a person, not a drink.","どれ is for three or more things. A offers only two drinks."],"explain":null},{"id":"n5u08d1.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：いぬとねこと、どちらがすきですか。B：（　　）すきです。^いぬもねこも^かわいいですから。","options":["どちらも","どれも","どちらが","なにも"],"answer":1,"why":["B likes dogs and cats, both of the two, so B says どちらも.","どれも is for three or more things. A asked about only two animals.","どちらが asks a question. B is answering, not asking.","なにも goes with a negative verb, like なにもすきじゃありません. Here B says すきです."]},{"id":"n5u08d1.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"この[店|みせ]の","after":"です。","tiles":["パンは","あの[店|みせ]","より","[安|やす]い"],"star":2,"bank":[2,0,3,1],"hint":"この店の must go right before the thing it owns. より follows the shop you measure against.","full":"この[店|みせ]のパンはあの[店|みせ]{より}[安|やす]いです。","explain":"この店の goes with パン, so パンは comes first. あの店 is the one you measure against, so より comes right after it. 安い ends the sentence before です."},{"id":"n5u08d1.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[電車|でんしゃ]と","after":"か。","tiles":["バスと","どちらが","[安|やす]い","です"],"star":1,"bank":[3,1,0,2],"hint":"Each of the two things takes と. どちらが comes after both of them.","full":"[電車|でんしゃ]とバスと{どちらが}[安|やす]いですか。","explain":"電車と and バスと name the two things, then どちらが asks which. 安いです comes last, before か."}],"exam":[{"id":"n5u08d1.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"電車は　バス（　　）　高いですが、はやいです。","options":["より","から","で","に"],"answer":1,"explain":"The train is measured against the bus, so バス takes より: the train costs more than the bus, but it is faster. から means from or because, で marks a place or a means, and に marks a time or a place. None of them compares two things."},{"id":"n5u08d1.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「にくと　魚と　どちらが　すきですか。」　B「魚（　　）　すきです。」","options":["のほうで","のほうへ","のほうが","ほうが"],"answer":3,"explain":"A asks which of two, so B answers with the one B chooses ＋ のほうが: I like fish better. ほうが drops the の a noun needs. のほうで and のほうへ use the wrong small word; すき takes が."},{"id":"n5u08d1.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"この　電車は　","after":"です。","tiles":["あの","電車","より","新しい"],"star":2,"bank":[3,2,0,1],"full":"この　電車は　あの　電車{より}　新しいです。","explain":"あの, 電車, より, 新しい. あの goes right before 電車, より follows the train you measure against, and 新しい ends the sentence before です: this train is newer than that one."}]},"scene":{"ja":"二つの電車","en":"Two trains compared","intro":"A poster at the station compares a new train and an old train that go to the same town. Tap each word on it.","words":[{"id":"train","word":"電車","reading":"でんしゃ","gloss":"train","parts":[["電","デン","electricity"],["車","シャ","vehicle"]],"clip":"s_n5u8d1_train"},{"id":"new","word":"新しい","reading":"あたらしい","gloss":"new","parts":[["新","あたら","new"]],"clip":"s_n5u8d1_new"},{"id":"old","word":"古い","reading":"ふるい","gloss":"old","parts":[["古","ふる","old"]],"clip":"s_n5u8d1_old"},{"id":"hour","word":"一時間","reading":"いちじかん","gloss":"one hour","parts":[["一","イチ","one"],["時","ジ","time, hour"],["間","カン","span, between"]],"clip":"s_n5u8d1_hour"},{"id":"minutes","word":"三十分","reading":"さんじゅっぷん","gloss":"thirty minutes","parts":[["三","サン","three"],["十","ジュッ","ten"],["分","プン","minute"]],"clip":"s_n5u8d1_minutes"},{"id":"yen","word":"千円","reading":"せんえん","gloss":"1,000 yen","parts":[["千","セン","thousand"],["円","エン","yen"]],"clip":"s_n5u8d1_yen"},{"id":"expensive","word":"高い","reading":"たかい","gloss":"expensive","parts":[["高","たか","high"]],"clip":"s_n5u8d1_expensive"},{"id":"cheap","word":"安い","reading":"やすい","gloss":"cheap","parts":[["安","やす","cheap"]],"clip":"s_n5u8d1_cheap"}],"check":{"id":"n5u08d1.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_新しい_　電車に　のりたいです。","options":["あたらい","あたらしい","あだらしい","あらたしい"],"answer":2,"explain":"新しい is read あたらしい, new: I want to ride the new train. あだらしい has だ instead of た, あらたしい swaps ら and た, and あたらい drops し."}},"skill":{"kind":"listening","ja":"ポイント理解","en":"Point comprehension","ask":"女の人は　何で　大学まで　行きますか。","audio":[["N","男の人と女の人が話しています。女の人は何で大学まで行きますか。","おとこのひととおんなのひとがはなしています。おんなのひとはなんでだいがくまでいきますか。"],["F","大学まで、バスと電車と、どちらがはやいですか。","だいがくまで、バスとでんしゃと、どちらがはやいですか。"],["M","電車のほうがはやいですよ。でも、駅まで十五分あるきます。","でんしゃのほうがはやいですよ。でも、えきまでじゅうごふんあるきます。"],["F","十五分ですか。バスはどうですか。","じゅうごふんですか。バスはどうですか。"],["M","バスは電車より時間がかかりますが、この店の前から出ますよ。","バスはでんしゃよりじかんがかかりますが、このみせのまえからでますよ。"],["F","じゃあ、バスで行きます。タクシーは高いですから。","じゃあ、バスでいきます。タクシーはたかいですから。"],["N","女の人は何で大学まで行きますか。","おんなのひとはなんでだいがくまでいきますか。"]],"item":{"id":"n5u08d1.r1","kind":"choice","type":"ポイント理解","q":"女の人は　何で　大学まで　行きますか。","script":["ナレーター：男の人と女の人が話しています。女の人は何で大学まで行きますか。","女：大学まで、バスと電車と、どちらがはやいですか。","男：電車のほうがはやいですよ。でも、駅まで十五分あるきます。","女：十五分ですか。バスはどうですか。","男：バスは電車より時間がかかりますが、この店の前から出ますよ。","女：じゃあ、バスで行きます。タクシーは高いですから。","ナレーター：女の人は何で大学まで行きますか。"],"options":["電車","バス","タクシー","じてんしゃ"],"printed":true,"short":["電車","バス","タクシー","じてんしゃ"],"answer":2,"why":["The man says the train is faster, but it is a 15-minute walk to the station. She asks about the bus instead.","The bus takes longer than the train (電車より時間がかかります), but it leaves from in front of this shop. She says バスで行きます.","She says タクシーは高いですから: she does not take a taxi because it costs a lot.","Nobody talks about a bicycle."],"clip":"l_n5u8d1"}}},{"title":"〜の中で〜がいちばん・どちらも／どれも","grammar":{"points":[{"id":"n5u08d2.p1","form":"〜の中で〜がいちばん","gloss":"the most … of all (three or more)","connect":[{"pos":"〜 is the group (a noun), then the one that is the most","rule":"〜{の[中|なか]で}〜が{いちばん}〜です"},{"pos":"Asking: 何 for a thing, どこ for a place, だれ for a person","rule":"〜{の[中|なか]で}[何|なに]／どこ／だれが{いちばん}〜ですか"},{"pos":"Three or more things named one by one: ask with どれ","rule":"〜と〜と〜{の[中|なか]で}、どれが{いちばん}〜ですか"}],"examples":[{"ja":"くだもの{の[中|なか]で}りんごが{いちばん}すきです。","en":"Of all fruits, I like apples best.","clip":"x_n5u08d2_p1_1"},{"ja":"[行|い]ったところ{の[中|なか]で}、どこが{いちばん}よかったですか。","en":"Of the places you went to, which one was the best?","clip":"x_n5u08d2_p1_2"}],"watch":{"note":"いちばん picks one out of three or more. With only two things, ask with どちら.","bad":"りんごとみかんの中で、どれがいちばんすきですか。","good":"りんごとみかんと、どちらがすきですか。"}},{"id":"n5u08d2.p2","form":"どちらも／どれも","gloss":"both / every one of them","connect":[{"pos":"Two things: both (with a negative ending: neither)","rule":"{どちらも}〜です・{どちらも}〜じゃありません"},{"pos":"Three or more: things, people, places","rule":"{どれも}・{だれも}・{どこも}"},{"pos":"The ending can be positive or negative; だれも almost always takes a negative","rule":"{どれも}おいしいです・{だれも}いません"}],"examples":[{"ja":"この[二|ふた]つのケーキは{どちらも}おいしいです。","en":"Both of these two cakes are delicious.","clip":"x_n5u08d2_p2_1"},{"ja":"へやには{だれも}いません。","en":"There is nobody in the room.","clip":"x_n5u08d2_p2_2"}],"watch":{"note":"だれも with a positive verb is not said for \"everyone\". Use みんな for that: みんな来ます.","bad":"あしたのパーティーには、だれも来ます。","good":"あしたのパーティーには、みんな来ます。"}}],"compare":{"intro":"All three compare things. いちばん picks one out of three or more, のほうが picks one out of two, and どれも says the same thing about all of them.","forms":[{"form":"〜の中で〜がいちばん","tag":"いちばん · the most (three or more)","mark":"up","ja":"この[三|みっ]つの[中|なか]で、これが{いちばん}[安|やす]いです。","en":"Of these three, this one is the cheapest."},{"form":"〜より〜のほうが","tag":"二つ · more (of two)","mark":"up","ja":"これ{のほうが}それより[安|やす]いです。","en":"This one is cheaper than that one."},{"form":"どれも","tag":"ぜんぶ · all of them","mark":"dot","ja":"この[三|みっ]つは{どれも}[安|やす]いです。","en":"All three of these are cheap."}],"check":{"id":"n5u08d2.c1","kind":"choice","type":"文の文法1","label":"くだものの話","q":"A：りんごとみかんと、どちらがすきですか。B：（　　）すきです。","options":["いちばん","どちらも","どれも"],"answer":2,"why":["いちばん needs three or more things, and B does not say which one. いちばんすきです does not answer A's question.","A asks about two fruits, and B likes both: どちらもすきです.","どれも is for three or more. With two things, use どちらも."]}},"drill":[{"id":"n5u08d2.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"くだものの（　　）、^[何|なに]がいちばん^すきですか。","options":["[中|なか]が","[中|なか]を","[中|なか]に","[中|なか]で"],"answer":4,"why":["が is already on 何, the one being picked. くだものの中が does not fit here.","を marks what a verb acts on. There is no verb here that takes 中を.","With いちばん, the group you choose from is marked with の中で. の中に is for where something is, like かばんの中にあります.","の中で gives the group: of all fruits, which one do you like best?"],"explain":null},{"id":"n5u08d2.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：かぞくの[中|なか]で、（　　）がいちばんせが[高|たか]いですか。B：^[父|ちち]です^。","options":["[何|なに]","だれ","いつ","どこ"],"answer":2,"why":["何 asks about a thing. For people in the family, ask with だれ.","The answer is a person (父), so the question word is だれ: who is the tallest?","いつ asks about a time, but B answers with a person.","どこ asks about a place, but B answers with a person."],"explain":null},{"id":"n5u08d2.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^この[二|ふた]つのかさは^（　　）[高|たか]いです。","options":["どれも","だれも","どこも","どちらも"],"answer":4,"why":["どれも is for three or more things. Here there are only two.","だれも is for people, and umbrellas are not people.","どこも is for places, and umbrellas are not places.","二つ means two umbrellas, so \"both\" is どちらも."],"explain":null},{"id":"n5u08d2.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：この[店|みせ]の^パン^はどうですか。B：（　　）おいしいですよ。","options":["どこも","どれも","だれも","[何|なに]も"],"answer":2,"why":["どこも is for places. B is talking about the bread, not about places.","The shop has many kinds of bread, and どれも with a positive ending means every one of them is good.","だれも is for people, and bread is not a person.","何も goes with a negative ending, like 何もありません. 何もおいしいです is not said."],"explain":null},{"id":"n5u08d2.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"この[三|みっ]つのかばんの","after":"。","tiles":["[中|なか]で","どれが","いちばん[安|やす]い","ですか"],"star":1,"bank":[2,0,3,1],"hint":"First finish the group with の中で. Then the question word, then what you want to know.","full":"この[三|みっ]つのかばんの[中|なか]でどれが{いちばん}[安|やす]いですか。","explain":"かばんの needs 中で right after it to make the group. どれが is the one being picked, then いちばん安い, and ですか ends the question."},{"id":"n5u08d2.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[本|ほん]を[三|さん]さつ[読|よ]みましたが、","after":"。","tiles":["どれも","あまり","おもしろく","ありませんでした"],"star":0,"bank":[3,1,0,2],"hint":"Which word means \"every one of the three books\"? あまり needs a negative ending.","full":"[本|ほん]を[三|さん]さつ[読|よ]みましたが、{どれも}あまりおもしろくありませんでした。","explain":"どれも, every one of the three books, comes first. あまり goes before the negative おもしろくありませんでした, which ends the sentence."}],"exam":[{"id":"n5u08d2.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　店の　ケーキの　中で　（　　）が　いちばん　人気が　ありますか。」\nB「この　白い　ケーキです。」","options":["どこ","いつ","だれ","どれ"],"answer":4,"explain":"A picks one cake out of the shop's cakes, so the question word is どれ. だれ is for people, どこ is for places and いつ is for times, but B answers with a cake."},{"id":"n5u08d2.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「へやに　だれか　いますか。」\nB「いいえ、（　　）　いません。」","options":["だれが","だれも","だれに","だれか"],"answer":2,"explain":"いいえ … いません means there is nobody, and \"nobody\" is だれも with a negative ending. だれか is \"someone\" and does not fit after いいえ, だれが asks \"who\", and だれに does not go with いません here."},{"id":"n5u08d2.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「","after":"　いちばん　新しい　本ですか。」\nB「その　白い　本です。」","tiles":["この","三つの","中で","どれが"],"star":2,"bank":[3,0,2,1],"full":"A「この　三つの　{中で}　どれが　いちばん　新しい　本ですか。」\nB「その　白い　本です。」","explain":"この, 三つの, 中で, どれが. この goes before 三つの, the group ends with 中で, and どれが, the one being picked, comes right before いちばん."}]},"scene":{"ja":"デパートの人気ランキング","en":"A poster of this month's most popular items in a department store","intro":"Tap every word with kanji that you can find on the ranking poster.","words":[{"id":"this month","word":"今月","reading":"こんげつ","gloss":"this month","parts":[["今","コン","now"],["月","ゲツ","month, moon"]],"clip":"s_n5u8d2_this_month"},{"id":"popular","word":"人気","reading":"にんき","gloss":"popularity, popular","parts":[["人","ニン","person"],["気","キ","spirit, air"]],"clip":"s_n5u8d2_popular"},{"id":"shop","word":"店","reading":"みせ","gloss":"shop","parts":[["店","みせ","shop"]],"clip":"s_n5u8d2_shop"},{"id":"new","word":"新しい","reading":"あたらしい","gloss":"new","parts":[["新","あたら","new"]],"clip":"s_n5u8d2_new"},{"id":"book","word":"本","reading":"ほん","gloss":"book","parts":[["本","ホン","book"]],"clip":"s_n5u8d2_book"},{"id":"flower","word":"花","reading":"はな","gloss":"flower","parts":[["花","はな","flower"]],"clip":"s_n5u8d2_flower"},{"id":"fish","word":"魚","reading":"さかな","gloss":"fish","parts":[["魚","さかな","fish"]],"clip":"s_n5u8d2_fish"},{"id":"1000 yen","word":"千円","reading":"せんえん","gloss":"1,000 yen","parts":[["千","セン","thousand"],["円","エン","yen, circle"]],"clip":"s_n5u8d2_1000_yen"}],"check":{"id":"n5u08d2.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"この　店で　いちばん　_人気_が　ある　本は　どれですか。","options":["にんき","にき","にんぎ","ひんき"],"answer":1,"explain":"人気 is read にんき, \"popular\". 人 is にん here, as in 三人, and 気 is き, as in 天気. にんぎ, ひんき and にき are not words."}},"skill":{"kind":"reading","ja":"内容理解（短文）","en":"Short passage","ask":"Which season does Yuki like best, and why?","seconds":90,"passage":"マリアさんへ\nわたしは　一年の　中で　あきが　いちばん　すきです。^天気が　よくて、山の　木が　とても　きれいだからです^。なつは　あついですから、あまり　すきじゃ　ありません。食べものの　中では　魚が　いちばん　すきです。父の　店の　魚は　どれも　おいしいですよ。\nユキ","strategy":"Find the sentence with いちばんすき about a season, then read the next sentence: the reason ends in からです.","item":{"id":"n5u08d2.r1","kind":"choice","type":"読解・内容理解（短文）","q":"ユキさんは　どうして　あきが　いちばん　すきですか。","options":["魚が　おいしいから","天気が　よくて、山の　木が　きれいだから","あきは　あついから","父の　店が　あるから"],"short":["魚がおいしい","天気と山の木","あきはあつい","父の店がある"],"answer":2,"explain":"Right after あきがいちばんすきです, Yuki writes the reason: 天気がよくて、山の木がとてもきれいだからです.","why":["Fish is Yuki's favourite food, and the fish is good, but that is not why Yuki likes autumn.","","It is summer that is hot (なつはあついですから), and that is why Yuki does not like summer.","Yuki's father has a shop with good fish, but this is about food, not about autumn."]}}},{"title":"〜くなる・〜になる","grammar":{"points":[{"id":"n5u08d3.p1","form":"〜くなります","gloss":"become … (い adjective)","connect":[{"pos":"い adjective: change the last い to く","rule":"さむい → さむ{くなります}"},{"pos":"いい is special: it becomes よく","rule":"いい → {よくなります}"},{"pos":"Past: it has changed and is like that now","rule":"[高|たか]い → [高|たか]{くなりました}"}],"examples":[{"ja":"[外|そと]がくら{くなりました}ね。","en":"It's got dark outside, hasn't it.","clip":"x_n5u08d3_p1_1"},{"ja":"くすりを[飲|の]みましたから、{よくなりました}。","en":"I took some medicine, so I got better.","clip":"x_n5u08d3_p1_2"}],"watch":{"note":"Take off the last い and add く. Do not keep the い and add に.","bad":"いぬが大きいになりました。","good":"いぬが大きくなりました。"}},{"id":"n5u08d3.p2","form":"〜になります","gloss":"become … (な adjective, noun)","connect":[{"pos":"な adjective: no な, add に","rule":"しずか → しずか{になります}"},{"pos":"〜 is a noun","rule":"〜{になります}（[先生|せんせい]{になりたいです}）"},{"pos":"〜 is a time or an age","rule":"[十時|じゅうじ]{になりました}"}],"examples":[{"ja":"よるは、この[道|みち]もしずか{になります}。","en":"At night, this street gets quiet too.","clip":"x_n5u08d3_p2_1"},{"ja":"わたしは[先生|せんせい]{になりたいです}。","en":"I want to become a teacher.","clip":"x_n5u08d3_p2_2"}],"watch":{"note":"げんき ends in き, but it is a な adjective, so it takes に. げんきく is not a form.","bad":"子どもはもうげんきくなりました。","good":"子どもはもうげんきになりました。"}}],"compare":{"intro":"All three can talk about the past, but only なりました says that something changed.","forms":[{"form":"〜くなりました","tag":"〜い → 〜く＋なる · became (い adjective)","mark":"dot","ja":"コーヒーがつめた{くなりました}。","en":"The coffee has gone cold."},{"form":"〜になりました","tag":"〜＋に＋なる · became (な adjective, noun)","mark":"dot","ja":"[駅|えき]の[前|まえ]がにぎやか{になりました}。","en":"The area in front of the station has become lively."},{"form":"〜かったです／〜でした","tag":"〜かった・〜でした · was (no change)","mark":"dot","ja":"きのうはさむ{かったです}。","en":"It was cold yesterday."}],"check":{"id":"n5u08d3.c1","kind":"choice","type":"文の文法1","label":"ギター","q":"[前|まえ]はへたでしたが、[今|いま]はじょうず（　　）。","options":["になりました","くなりました","でした"],"answer":1,"why":["Before it was bad, now it is good: a change. じょうず is a な adjective, so it takes に: \"I used to be bad, but now I've got good.\"","く is for い adjectives such as さむい. じょうず is a な adjective, so じょうずく is not a form.","でした is the past, but 今は means \"now\". \"Now it was good\" does not work, and it does not show the change either."]}},"drill":[{"id":"n5u08d3.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[雨|あめ]がふって、^さむ^（　　）なりました。","options":["い","くて","に","く"],"answer":4,"why":["The い must change to く before なりました. さむいなりました is not correct.","くて means \"and\" (さむくて、…). It cannot come right before なりました.","に is for な adjectives and nouns. さむい is an い adjective.","さむい is an い adjective: take off い and add く. \"It rained and it got cold.\""],"explain":null},{"id":"n5u08d3.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^くすりを[飲|の]みました^から、かぜはもう（　　）なりました。","options":["よく","いいに","よに","いく"],"answer":1,"why":["いい is special: before なります it becomes よく. \"I took medicine, so my cold is already better.\"","いい is an い adjective, so it does not take に.","よに is not a form. You need the whole よく.","いく is the verb \"go\". It is not a form of いい."],"explain":null},{"id":"n5u08d3.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは[来年|らいねん]、^[大学生|だいがくせい]^（　　）なります。","options":["に","が","く","を"],"answer":1,"why":["大学生 is a noun, so it takes に before なります: \"I will become a university student next year.\"","なります marks what you become with に. 大学生が would make the student the subject, but the subject here is わたし.","く is for い adjectives. 大学生 is a noun.","を marks the thing you do something to. なります does not take を."]},{"id":"n5u08d3.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[駅|えき]が[新|あたら]しくなって、^きれい^（　　）なりました。","options":["く","に","な","で"],"answer":2,"why":["きれい ends in い, but it is a な adjective, so きれいく is not a form.","きれい is a な adjective, so it takes に: \"The station became new and got clean.\"","な goes before a noun (きれいな駅). It cannot come before なりました.","で joins two ideas (きれいで、…). It cannot come right before なりました."]},{"id":"n5u08d3.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[外|そと]が","after":"つけましょう。","tiles":["くらく","なりました","から、","[電気|でんき]を"],"star":1,"bank":[3,1,0,2],"hint":"くらい becomes くらく before なりました. から comes right after the reason, and 電気を goes before つけましょう.","full":"[外|そと]がくら{くなりました}から、[電気|でんき]をつけましょう。","explain":"くらく, なりました, から、, 電気を. It has got dark, and that is the reason, so から follows なりました: \"It's got dark outside, so let's turn on the light.\""},{"id":"n5u08d3.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしは","after":"。","tiles":["[日本語|にほんご]の","[先生|せんせい]に","なり","たいです"],"star":2,"bank":[2,0,3,1],"hint":"日本語の tells what kind of teacher, so it goes before 先生に. たいです joins the ます stem なり.","full":"わたしは[日本語|にほんご]の[先生|せんせい]{になり}たいです。","explain":"日本語の, 先生に, なり, たいです. 先生 is a noun, so it takes に before なります, and なりたいです means \"want to become\": \"I want to become a Japanese teacher.\""}],"exam":[{"id":"n5u08d3.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"へやを　そうじしましたから、　（　　）　なりました。","options":["きれいに","きれいな","きれいで","きれいく"],"answer":1,"explain":"きれい is a な adjective, so it takes に before なりました: \"I cleaned the room, so it got clean.\" きれいく is not a form, even though きれい ends in い. きれいな goes before a noun, and きれいで joins two ideas."},{"id":"n5u08d3.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この　店の　ケーキは　先月から　百円　（　　）　なりました。","options":["高かった","高くて","高い","高く"],"answer":4,"explain":"高い is an い adjective, so い changes to く before なりました: \"The cake at this shop has gone up by 100 yen since last month.\" 高い and 高かった cannot come right before なりました, and 高くて means \"expensive and …\"."},{"id":"n5u08d3.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"もう","after":"か。","tiles":["十時に","なりました","から、","ねましょう"],"star":1,"bank":[2,3,0,1],"full":"もう　十時に　{なりました}　から、　ねましょう　か。","explain":"十時に, なりました, から、, ねましょう. A time takes に before なります, から follows the reason, and ねましょうか is the suggestion: \"It's already ten o'clock, so shall we go to bed?\""}]},"scene":{"ja":"駅前の店のおしらせ","en":"A notice at a shop by the station","intro":"Tap every word you would read on the notice about the shop's changes.","words":[{"id":"shop","word":"店","reading":"みせ","gloss":"shop","parts":[["店","みせ","shop"]],"clip":"s_n5u8d3_shop"},{"id":"by the station","word":"駅前","reading":"えきまえ","gloss":"in front of the station","parts":[["駅","エキ","station"],["前","まえ","front, before"]],"clip":"s_n5u8d3_by_the_station"},{"id":"new","word":"新しい","reading":"あたらしい","gloss":"new","parts":[["新","あたら","new"]],"clip":"s_n5u8d3_new"},{"id":"bigger","word":"大きく","reading":"おおきく","gloss":"big (before なります: become bigger)","parts":[["大","おお","big"]],"clip":"s_n5u8d3_bigger"},{"id":"this month","word":"今月","reading":"こんげつ","gloss":"this month","parts":[["今","コン","now"],["月","ゲツ","month, moon"]],"clip":"s_n5u8d3_this_month"},{"id":"next month","word":"来月","reading":"らいげつ","gloss":"next month","parts":[["来","ライ","come, next"],["月","ゲツ","month, moon"]],"clip":"s_n5u8d3_next_month"},{"id":"100 yen","word":"百円","reading":"ひゃくえん","gloss":"100 yen","parts":[["百","ヒャク","hundred"],["円","エン","yen, circle"]],"clip":"s_n5u8d3_100_yen"},{"id":"more expensive","word":"高く","reading":"たかく","gloss":"expensive (before なります: go up in price)","parts":[["高","たか","high, expensive"]],"clip":"s_n5u8d3_more_expensive"}],"check":{"id":"n5u08d3.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_来月_から　コーヒーが　百円　高く　なります。","options":["らいがつ","らいげつ","きげつ","らいつき"],"answer":2,"explain":"来月, \"next month\", is read らいげつ. 月 is がつ in the names of months (一月, いちがつ), but in 来月 and 今月 it is げつ. らいつき is not a word, and 来 is not read き at the start of 来月."}},"skill":{"kind":"listening","ja":"即時応答","en":"Quick response","ask":"えなどが　ありません。ぶんを　聞いて、1から3の　中から、いちばん　いい　ものを　一つ　えらんで　ください。","item":{"id":"n5u08d3.r1","kind":"choice","type":"即時応答","q":"女：リーさん、日本語が　じょうずに　なりましたね。","script":["女：リーさん、日本語がじょうずになりましたね。","ナレーター：1","男：そうですか。じゃあ、がんばってください。","ナレーター：2","男：ありがとうございます。まいにちれんしゅうしましたから。","ナレーター：3","男：はい、じょうずにしました。"],"options":["そうですか。じゃあ、がんばって　ください。","ありがとうございます。まいにち　れんしゅうしましたから。","はい、じょうずに　しました。"],"printed":false,"short":["がんばって ください","ありがとうございます","じょうずに しました"],"answer":2,"why":["She is praising him. がんばって ください is what you say to someone else who has work ahead, not a reply to a compliment.","She says his Japanese has got better. He thanks her and gives the reason: he practised every day.","じょうずに します means making something good on purpose. It does not answer a remark about how his Japanese has changed."],"clip":"l_n5u8d3"},"audio":[["F","リーさん、日本語がじょうずになりましたね。","リーさん、にほんごが　じょうずに　なりましたね。"],["N","1",null],["M","そうですか。じゃあ、がんばってください。",null],["N","2",null],["M","ありがとうございます。まいにちれんしゅうしましたから。",null],["N","3",null],["M","はい、じょうずにしました。",null]]}},{"title":"〜くする・〜にする","grammar":{"points":[{"id":"n5u08d4.p1","form":"〜くします","gloss":"make it …","connect":[{"pos":"い-adjective: drop い, add く","rule":"あかるい → あかる{くします}"},{"pos":"Asking someone to do it","rule":"[小|ちい]さい → [小|ちい]さ{くしてください}"},{"pos":"いい is special: it becomes よく","rule":"いい → よ{くします}"}],"examples":[{"ja":"でんきをつけて、へやをあかる{くします}。","en":"I'll turn on the light and make the room bright.","clip":"x_n5u08d4_p1_1"},{"ja":"ラジオのおとを[小|ちい]さ{くしてください}。","en":"Please turn the radio down.","clip":"x_n5u08d4_p1_2"}],"watch":{"note":"The い-adjective changes to く before します. It cannot stay as い.","bad":"へやをあたたかいします。","good":"へやをあたたかくします。"}},{"id":"n5u08d4.p2","form":"〜にします","gloss":"make it …; I'll have …","connect":[{"pos":"な-adjective (making something so)","rule":"きれい ＋ {にします}"},{"pos":"〜 is a noun (choosing or deciding)","rule":"〜 ＋ {にします}"},{"pos":"Choosing \"the … one\": い-adjective + の","rule":"[大|おお]きいの ＋ {にします}"}],"examples":[{"ja":"おきゃくさんが[来|き]ますから、へやをきれい{にします}。","en":"A guest is coming, so I'll make my room clean.","clip":"x_n5u08d4_p2_1"},{"ja":"「[何|なに]を[飲|の]みますか。」「コーヒー{にします}。」","en":"\"What will you drink?\" \"I'll have coffee.\"","clip":"x_n5u08d4_p2_2"}],"watch":{"note":"きれい ends in い, but it is a な-adjective, so it takes に, not く.","bad":"へやをきれいくします。","good":"へやをきれいにします。"}}],"compare":{"intro":"The first two are about the same room: なる says it changes, くする says someone changes it. にする after a noun says what you choose.","forms":[{"form":"〜くなる","tag":"かわる · it becomes","mark":"dot","ja":"へやがあかる{くなりました}。","en":"The room got bright."},{"form":"〜くする","tag":"かえる · someone makes it","mark":"dot","ja":"へやをあかる{くしました}。","en":"I made the room bright."},{"form":"〜にする","tag":"えらぶ · choose","mark":"dot","ja":"わたしはコーヒー{にします}。","en":"I'll have coffee."}],"check":{"id":"n5u08d4.c1","kind":"choice","type":"文の文法1","label":"へやのでんき","q":"でんきをつけて、へや^を^あかるく（　　）。","options":["にしました","しました","なりました"],"answer":2,"why":["あかるい is an い-adjective, so it takes く alone. You cannot add に after あかるく.","へやを has を: I did something to the room. あかるくしました means \"I made it bright\".","なりました goes with が: へやがあかるくなりました. After へやを it does not fit."],"explain":null}},"drill":[{"id":"n5u08d4.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"テレビのおとが^[大|おお]きい^です。もうすこし（　　）ください。","options":["[小|ちい]さにして","[小|ちい]さくなって","[小|ちい]さくして","[小|ちい]さいして"],"answer":3,"why":["小さい is an い-adjective. It does not take に.","なってください asks the person to become small. Here you ask them to change the sound, so use して.","小さい becomes 小さく before して: \"please turn it down\".","The い must change to く before して."],"explain":null},{"id":"n5u08d4.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"へやが^くらい^ですね。でんきをつけて、（　　）しましょう。","options":["あかるくて","あかるく","あかるい","あかるいに"],"answer":2,"why":["The て form joins two ideas. It does not go before する here.","あかるい becomes あかるく before しましょう: \"let's make it bright\".","The い must change to く before する.","An い-adjective does not take に."],"explain":null},{"id":"n5u08d4.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"「[何|なに]に^しますか^。」「わたしはこうちゃ（　　）します。」","options":["で","に","を","が"],"answer":2,"why":["で does not say what you choose. Use に.","The question is 何にしますか, so the answer is こうちゃにします: \"I'll have tea\".","こうちゃをします is not said. To say what you choose, use に.","が does not go before します to say what you choose."],"explain":null},{"id":"n5u08d4.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"おきゃくさんが[来|き]ますから、へやを（　　）^します^。","options":["きれいに","きれいく","きれいな","きれいだ"],"answer":1,"why":["きれい is a な-adjective, so it takes に before します.","きれい ends in い, but it is not an い-adjective. It never takes く.","きれいな needs a noun after it, like きれいなへや.","きれいだ ends a sentence. It cannot go before します."]},{"id":"n5u08d4.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"すみません、","after":"ください。","tiles":["テレビの","おとを","[小|ちい]さく","して"],"star":2,"bank":[2,0,3,1],"hint":"Whose sound is it? Then how do you want it? して comes right before ください.","full":"すみません、テレビのおとを[小|ちい]さ{くして}ください。","explain":"テレビの goes right before おとを. 小さく joins on to して, and してください asks the person to do it."},{"id":"n5u08d4.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[友|とも]だちが[来|き]ますから、","after":"しました。","tiles":["へやと","だいどころを","きれい","に"],"star":2,"bank":[1,3,0,2],"hint":"Which two places did you clean? に comes right after きれい.","full":"[友|とも]だちが[来|き]ますから、へやとだいどころをきれい{にしました}。","explain":"へやと joins on to だいどころを: \"the room and the kitchen\". きれい is a な-adjective, so に comes after it, then しました."}],"exam":[{"id":"n5u08d4.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ちょっと　あついですね。まどを　あけて、へやを　（　　）　しましょう。","options":["すずしい","すずしいに","すずしくて","すずしく"],"answer":4,"explain":"すずしい is an い-adjective, so it becomes すずしく before しましょう: \"let's make the room cool\". すずしい must change to く, an い-adjective does not take に, and the て form すずしくて does not go before する."},{"id":"n5u08d4.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"「大きい　コップと　小さい　コップが　あります。どちらに　しますか。」「じゃあ、大きい（　　）に　します。」","options":["く","が","の","な"],"answer":3,"explain":"大きいの means \"the big one\", and 大きいのに します says which one you choose. An い-adjective does not take な, 大きいく is not a form, and が cannot come before に."},{"id":"n5u08d4.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしは　コーヒーに　しますが、","after":"します。","tiles":["友だちは","オレンジ","ジュース","に"],"star":2,"bank":[3,1,0,2],"full":"わたしは　コーヒーに　しますが、友だちは　オレンジ　ジュース{に}　します。","explain":"友だちは, オレンジ, ジュース, に. 友だちは shows the other person. オレンジ ジュース is what the friend chooses, and に comes before します."}]},"scene":{"ja":"きっさてんのランチメニュー","en":"The lunch menu at a coffee shop","intro":"Tap each word on the menu that tells you the food, the drink, the size or the price.","words":[{"id":"large","word":"大きい","reading":"おおきい","gloss":"big, large","parts":[["大","おお","big"]],"clip":"s_n5u8d4_large"},{"id":"small","word":"小さい","reading":"ちいさい","gloss":"small","parts":[["小","ちい","small"]],"clip":"s_n5u8d4_small"},{"id":"water","word":"水","reading":"みず","gloss":"water","parts":[["水","みず","water"]],"clip":"s_n5u8d4_water"},{"id":"drinks","word":"飲みもの","reading":"のみもの","gloss":"drinks","parts":[["飲","の","drink"]],"clip":"s_n5u8d4_drinks"},{"id":"yen","word":"円","reading":"えん","gloss":"yen","parts":[["円","エン","yen, circle"]],"clip":"s_n5u8d4_yen"},{"id":"white wine","word":"白ワイン","reading":"しろワイン","gloss":"white wine","parts":[["白","しろ","white"]],"clip":"s_n5u8d4_white_wine"},{"id":"fish","word":"魚","reading":"さかな","gloss":"fish","parts":[["魚","さかな","fish"]],"clip":"s_n5u8d4_fish"},{"id":"half","word":"半分","reading":"はんぶん","gloss":"half","parts":[["半","ハン","half"],["分","ブン","part"]],"clip":"s_n5u8d4_half"}],"check":{"id":"n5u08d4.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_飲みもの_は　何に　しますか。","options":["のみの","のみもの","たべもの","よみもの"],"answer":2,"explain":"飲みもの is のみもの, something to drink. たべもの is 食べもの and よみもの is 読みもの, and のみの is not this word."}},"skill":{"kind":"reading","ja":"内容理解（短文）","en":"Short passage","ask":"Why did the writer choose curry?","seconds":90,"passage":"今日は　友だちと　駅の　前の　店で　ひるごはんを　食べました。友だちは　魚の　ランチに　しました。わたしも　魚が　すきですが、^きのうの　ばんも　魚を　食べました^から、^カレーに　しました^。飲みものは　二人とも　つめたい　コーヒーに　しました。","strategy":"Find カレーに しました, then read the reason that comes before から.","item":{"id":"n5u08d4.r1","kind":"choice","type":"読解・内容理解（短文）","q":"「わたし」は　どうして　カレーに　しましたか。","options":["きのうの　ばんも　魚を　食べたから。","カレーが　安かったから。","魚が　きらいだから。","友だちが　カレーに　したから。"],"answer":1,"short":["きのうも魚を食べた","カレーが安かった","魚がきらい","友だちがカレーにした"],"explain":"The writer ate fish last night too (きのうの ばんも 魚を 食べました), and から says that is why she chose curry.","why":["","The passage says nothing about the price.","She says she likes fish too (わたしも 魚が すきです).","The friend chose the fish lunch, not curry."]}}},{"title":"〜だけ・〜しか〜ない","grammar":{"points":[{"id":"n5u08d5.p1","form":"〜だけ","gloss":"only; just","connect":[{"pos":"Noun (が and を are usually dropped)","rule":"〜{だけ}：[水|みず]{だけ}[飲|の]みました"},{"pos":"Number + counter","rule":"[一|ひと]つ{だけ}／[一人|ひとり]{だけ}／[五分|ごふん]{だけ}"},{"pos":"The ending stays positive","rule":"[一|ひと]つ{だけ}[買|か]いました"}],"examples":[{"ja":"パンを[一|ひと]つ{だけ}[買|か]いました。","en":"I bought just one piece of bread.","clip":"x_n5u08d5_p1_1"},{"ja":"この[店|みせ]は、にちようび{だけ}[休|やす]みです。","en":"This shop is closed only on Sundays.","clip":"x_n5u08d5_p1_2"}],"watch":{"note":"だけ comes straight after the noun. Do not put を in front of it: say コーヒーだけ, not コーヒーをだけ.","bad":"けさはコーヒーをだけ飲みました。","good":"けさはコーヒーだけ飲みました。"}},{"id":"n5u08d5.p2","form":"〜しか〜ません","gloss":"only (and not enough)","connect":[{"pos":"Noun or number + しか, then a negative ending","rule":"〜{しか}…ません：[百円|ひゃくえん]{しか}ありません"},{"pos":"Past: the negative past ending","rule":"[一人|ひとり]{しか}[来|き]ませんでした"},{"pos":"The feeling: less than you want","rule":"[時間|じかん]が[五分|ごふん]{しか}ありません"}],"examples":[{"ja":"さいふに[千円|せんえん]{しか}ありません。","en":"I only have 1,000 yen in my wallet.","clip":"x_n5u08d5_p2_1"},{"ja":"きのうのパーティーには、[三人|さんにん]{しか}[来|き]ませんでした。","en":"Only three people came to the party yesterday.","clip":"x_n5u08d5_p2_2"}],"watch":{"note":"しか means \"only\", but the ending after it is always negative. With a positive ending, use だけ.","bad":"さいふに五百円しかあります。","good":"さいふに五百円しかありません。"}}],"compare":{"intro":"だけ and しか both mean \"only\", but they take different endings; ぐらい is not \"only\" at all.","forms":[{"form":"[一|ひと]つだけ[買|か]いました","tag":"だけ · only","mark":"dot","ja":"りんごを[一|ひと]つ{だけ}[買|か]いました。","en":"I bought just one apple."},{"form":"[百円|ひゃくえん]しかありません","tag":"しか〜ません · only, not enough","mark":"down","ja":"さいふに[百円|ひゃくえん]{しか}ありません。","en":"I have only 100 yen in my wallet."},{"form":"[千円|せんえん]ぐらいです","tag":"ぐらい · about","mark":"dot","ja":"このかさは[千円|せんえん]{ぐらい}です。","en":"This umbrella is about 1,000 yen."}],"check":{"id":"n5u08d5.c1","kind":"choice","type":"文の文法1","label":"テスト","q":"A：お[金|かね]、たくさんありますか。B：^いいえ^、[千円|せんえん]（　　）ありません。","options":["だけ","しか","ぐらい"],"answer":2,"why":["千円だけありません would mean \"just 1,000 yen is missing\". That does not answer the question.","B says いいえ: there is not much money, only 1,000 yen. しか goes with the negative ありません.","ぐらい means \"about\". 千円ぐらいありません does not make sense after いいえ."]}},"drill":[{"id":"n5u08d5.d1","kind":"choice","type":"文の文法1","label":"Choose the word","q":"おなかがいっぱいですから、ケーキは[一|ひと]つ（　　）^[食|た]べました^。","options":["しか","も","だけ","に"],"answer":3,"why":["しか needs a negative ending. Here the ending is 食べました, which is positive.","一つも goes with a negative ending: 一つも食べませんでした (I didn't eat even one). It does not go with 食べました.","The ending 食べました is positive, so \"only one\" is 一つだけ.","に does not go after 一つ here. 一つに食べました is not Japanese."]},{"id":"n5u08d5.d2","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"A：ジュースを[買|か]いませんか。B：すみません、^[百円|ひゃくえん]しか^（　　）。","options":["ありません","ありました","あって","あります"],"answer":1,"why":["しか needs a negative ending: 百円しかありません, \"I only have 100 yen\".","ありました is positive too. しか never goes with it.","あって is the te-form. It cannot end the sentence here, and しか needs a negative ending.","あります is positive. After しか, the ending must be negative."],"explain":null},{"id":"n5u08d5.d3","kind":"choice","type":"文の文法1","label":"Choose the word","q":"A：たまごはたくさんありますか。B：^いいえ^、[二|ふた]つ（　　）ありません。","options":["で","だけ","を","しか"],"answer":4,"why":["で does not fit here. 二つでありません is not Japanese.","二つだけありません would mean \"just two are missing\". B says いいえ, there are not many eggs, so that does not fit.","を does not go with ありません. 二つをありません is not Japanese.","There are not many eggs, only two. しか goes with the negative ありません."],"explain":null},{"id":"n5u08d5.d4","kind":"choice","type":"文の文法1","label":"Choose the word","q":"けさは^[時間|じかん]がありませんでした^から、コーヒー（　　）[飲|の]みました。","options":["だけ","しか","にだけ","をだけ"],"answer":1,"why":["There was no time, so only coffee. The ending 飲みました is positive, so use だけ.","しか needs a negative ending, but 飲みました is positive.","に does not go with 飲みます. You drink something を, not に.","だけ comes straight after the noun. を cannot come before it: コーヒーをだけ is wrong."],"explain":null},{"id":"n5u08d5.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[電車|でんしゃ]まで","after":"、はしりましょう。","tiles":["[五分|ごふん]","しか","ありません","から"],"star":1,"bank":[2,0,3,1],"hint":"How much time comes first, then しか, then the negative ending, then から for the reason.","full":"[電車|でんしゃ]まで[五分|ごふん]{しか}ありませんから、はしりましょう。","explain":"五分しかありません says there is not much time, and から gives the reason for running: \"There are only five minutes until the train, so let's run.\""},{"id":"n5u08d5.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"きのうは","after":"、ねむいです。","tiles":["[三時間|さんじかん]","だけ","ねました","から"],"star":1,"bank":[3,1,0,2],"hint":"How long comes first, then だけ, then the positive ending, then から.","full":"きのうは[三時間|さんじかん]{だけ}ねましたから、ねむいです。","explain":"三時間だけ comes before the positive ending ねました, and から gives the reason: \"I only slept three hours yesterday, so I'm sleepy.\""}],"exam":[{"id":"n5u08d5.e1","kind":"choice","type":"文の文法1","label":"Choose the word","q":"A「りんごを　たくさん　買いましたか。」B「いいえ、高かったですから、二つ（　　）　買いませんでした。」","options":["と","だけ","が","しか"],"answer":4,"explain":"The apples were expensive, so B bought only two: 二つしか買いませんでした. しか goes with the negative ending. 二つだけ買いませんでした would mean \"I didn't buy just two\", which does not fit. が and と cannot go between 二つ and 買いませんでした here."},{"id":"n5u08d5.e2","kind":"choice","type":"文の文法1","label":"Choose the word","q":"A「よく　テレビを　見ますか。」B「いいえ。いそがしいですから、毎日　三十分（　　）　見ます。」","options":["が","だけ","の","しか"],"answer":2,"explain":"B is busy and watches only a little: 三十分だけ見ます. The ending 見ます is positive, so だけ fits. しか needs a negative ending (三十分しか見ません). が and の cannot go between 三十分 and 見ます."},{"id":"n5u08d5.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「ケーキを　たくさん　買いましたか。」B「いいえ。店に　","after":"。」","tiles":["一つ","しか","ありません","でした"],"star":2,"bank":[1,3,0,2],"full":"A「ケーキを　たくさん　買いましたか。」B「いいえ。店に　一つ　{しか}　ありません　でした。」","explain":"一つ, しか, ありません, でした. 一つしか needs a negative ending, and ありませんでした is the negative past: \"There was only one at the shop.\""}]},"scene":{"ja":"えいがかんの　きっぷうりば","en":"The notice at the ticket counter of a small cinema","intro":"Tap every word on the notice you need to know how much a ticket is and when you can go in.","words":[{"id":"entrance","word":"入口","reading":"いりぐち","gloss":"entrance","parts":[["入","いり","enter"],["口","ぐち","mouth, opening"]],"clip":"s_n5u8d5_entrance"},{"id":"oneperson","word":"一人","reading":"ひとり","gloss":"one person","parts":[["一","ひと","one"],["人","り","person"]],"clip":"s_n5u8d5_oneperson"},{"id":"thousandyen","word":"千円","reading":"せんえん","gloss":"1,000 yen","parts":[["千","セン","thousand"],["円","エン","yen"]],"clip":"s_n5u8d5_thousandyen"},{"id":"hundredyen","word":"百円","reading":"ひゃくえん","gloss":"100 yen","parts":[["百","ヒャク","hundred"],["円","エン","yen"]],"clip":"s_n5u8d5_hundredyen"},{"id":"child","word":"子ども","reading":"こども","gloss":"child","parts":[["子","こ","child"]],"clip":"s_n5u8d5_child"},{"id":"pm","word":"午後","reading":"ごご","gloss":"p.m., afternoon","parts":[["午","ゴ","noon"],["後","ゴ","after"]],"clip":"s_n5u8d5_pm"},{"id":"oclock","word":"時","reading":"じ","gloss":"o'clock","parts":[["時","ジ","time, o'clock"]],"clip":"s_n5u8d5_oclock"},{"id":"closed","word":"休み","reading":"やすみ","gloss":"closed; day off","parts":[["休","やす","rest"]],"clip":"s_n5u8d5_closed"}],"check":{"id":"n5u08d5.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"きっぷは　_一人_　千円です。","options":["ひとにん","いちり","いちにん","ひとり"],"answer":4,"explain":"\"One person\" is read ひとり. いちにん is not how you say one person in a sentence like this, and ひとにん and いちり are not readings of 一人."}},"skill":{"kind":"listening","ja":"課題理解","en":"Task comprehension","ask":"二人は　何を　買いますか。","audio":[["N","店で、男の人と女の人が話しています。二人は、何を買いますか。","みせで、おとこのひとと　おんなのひとが　はなしています。ふたりは、なにを　かいますか。"],["M","ぼくは、今、五百円しかありません。","ぼくは、いま、ごひゃくえんしか　ありません。"],["F","わたしは三百円あります。二人で八百円ですね。","わたしは　さんびゃくえん　あります。ふたりで　はっぴゃくえんですね。"],["M","あのケーキ、おいしいですよ。一つ六百円です。","あの　ケーキ、おいしいですよ。ひとつ　ろっぴゃくえんです。"],["F","じゃあ、ケーキは一つだけ買いましょう。それから、ジュースも飲みたいです。ジュースは一本百五十円です。","じゃあ、ケーキは　ひとつだけ　かいましょう。それから、ジュースも　のみたいです。ジュースは　いっぽん　ひゃくごじゅうえんです。"],["M","ケーキと、ジュース二本で、九百円ですね。ぼくたちは、八百円しかありませんよ。","ケーキと、ジュース　にほんで、きゅうひゃくえんですね。ぼくたちは、はっぴゃくえんしか　ありませんよ。"],["F","そうですね。じゃあ、ケーキはだめですね。パンはどうですか。パンは一つ二百円です。","そうですね。じゃあ、ケーキは　だめですね。パンは　どうですか。パンは　ひとつ　にひゃくえんです。"],["M","いいですね。じゃあ、パンを二つと、ジュースを二本買いましょう。七百円ですね。","いいですね。じゃあ、パンを　ふたつと、ジュースを　にほん　かいましょう。ななひゃくえんですね。"],["F","はい、そうしましょう。",null],["N","二人は、何を買いますか。","ふたりは、なにを　かいますか。"]],"item":{"id":"n5u08d5.r1","kind":"choice","type":"課題理解","q":"二人は　何を　買いますか。","script":["ナレーター：店で、男の人と女の人が話しています。二人は、何を買いますか。","男：ぼくは、今、五百円しかありません。","女：わたしは三百円あります。二人で八百円ですね。","男：あのケーキ、おいしいですよ。一つ六百円です。","女：じゃあ、ケーキは一つだけ買いましょう。それから、ジュースも飲みたいです。ジュースは一本百五十円です。","男：ケーキと、ジュース二本で、九百円ですね。ぼくたちは、八百円しかありませんよ。","女：そうですね。じゃあ、ケーキはだめですね。パンはどうですか。パンは一つ二百円です。","男：いいですね。じゃあ、パンを二つと、ジュースを二本買いましょう。七百円ですね。","女：はい、そうしましょう。","ナレーター：二人は、何を買いますか。"],"options":["ケーキ　一つと　ジュース　二本","ケーキ　一つだけ","パン　二つと　ジュース　二本","パン　二つだけ"],"printed":true,"short":["ケーキ一つとジュース二本","ケーキ一つだけ","パン二つとジュース二本","パン二つだけ"],"answer":3,"why":["A cake and two juices cost 900 yen, but they have only 800 yen together.","The woman wants juice too, and in the end they choose bread instead of the cake.","Two pieces of bread (400 yen) and two juices (300 yen) make 700 yen, which they can pay. The man says 買いましょう and the woman agrees.","They buy juice as well as the bread."],"clip":"l_n5u8d5"}}},{"title":"まとめ：似ている文法","grammar":{"points":[],"compare":{"intro":"To tell this unit's points apart, ask how many things you compare (より／のほうが and どちら for two, の中でいちばん for three or more, どちらも／どれも for all of them), whether something changes by itself (くなる／になる) or someone changes it (くする／にする), and whether the ending is negative: だけ and しか both mean only, but しか always needs a negative ending.","forms":[{"form":"〜くなります","tag":"かわる · it becomes (い adjective)","mark":"dot","ja":"このシャツは[先週|せんしゅう]より[安|やす]{くなりました}。","en":"This shirt has got cheaper than last week."},{"form":"〜くします","tag":"かえる · someone makes it (い adjective)","mark":"dot","ja":"[店|みせ]の[人|ひと]がシャツを[安|やす]{くしました}。","en":"The shop staff made the shirt cheaper."},{"form":"〜にします","tag":"〜に＋する · make it (noun, な adjective)","mark":"dot","ja":"[店|みせ]の[人|ひと]がシャツを[千円|せんえん]{にしました}。","en":"The shop staff made the shirt 1,000 yen."}],"check":{"id":"n5u08d6.c1","kind":"choice","type":"文の文法1","label":"セールのかばん","q":"セールですから、[店|みせ]の[人|ひと]^が^かばん^を^[安|やす]く（　　）。","options":["しました","にしました","なりました"],"answer":1,"why":["店の人が is the person who acts and かばんを is the thing changed, so 安くしました: the shop staff made the bags cheaper.","安く already has く. に goes after a noun or a な adjective, like 千円にしました, not after 安く.","なりました says something changed by itself, and that thing takes が: かばんが安くなりました. With 店の人が and かばんを, it does not fit."],"explain":null}},"drill":[{"id":"n5u08d6.d1","kind":"choice","type":"文の文法1","label":"Choose the word","q":"A：^うどんとそば^、（　　）にしますか。B：そばにします。","options":["どちらも","いちばん","どれ","どちら"],"answer":4,"why":["どちらも means both. It answers a question; it cannot ask which one, and どちらもにしますか is not said.","いちばん needs a group of three or more and a word that asks, like どれがいちばん. いちばんにしますか does not ask which one.","どれ is for three or more things. Here there are only two.","A offers two things, うどん and そば, so A asks with どちら: which will you have?"],"explain":null},{"id":"n5u08d6.d2","kind":"choice","type":"文の文法1","label":"Choose the word","q":"このセールは[今日|きょう]（　　）^です^よ。","options":["より","だけ","どれも","しか"],"answer":2,"why":["より compares two things, but nothing is compared here. 今日よりです is not said.","The ending です is positive, so \"only today\" is 今日だけです.","どれも is about three or more things. It cannot follow 今日.","しか needs a negative ending, like 今日しかありません. Here the ending is です."],"explain":null},{"id":"n5u08d6.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[新|あたら]しい[店|みせ]がたくさんできて、この[道|みち]^が^（　　）。","options":["にぎやかくしました","にぎやかくなりました","にぎやかになりました","にぎやかにしました"],"answer":3,"why":["にぎやかく is not a form, and しました does not fit この道が either.","にぎやか is a な adjective, so にぎやかく is not a form.","この道が is the thing that changed, so use なりました. にぎやか is a な adjective, so it takes に: the street got lively.","しました needs someone who acts and a thing with を. Here この道が is the thing that changed."],"explain":null},{"id":"n5u08d6.d4","kind":"choice","type":"文の文法1","label":"Choose the word","q":"このかばんは[三|みっ]つの^[中|なか]で^（　　）[大|おお]きいです。","options":["いちばん","より","のほうが","どちらも"],"answer":1,"why":["三つの中で gives a group of three, so いちばん picks the one: this bag is the biggest of the three.","より follows the thing you measure against, like あのかばんより. It cannot come after 中で.","のほうが follows the winner of two, like このかばんのほうが. It cannot come after 中で.","どちらも is about two things, and it says the same about both. Here one bag out of three is picked."],"explain":null},{"id":"n5u08d6.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"セールでも、このシャツは[前|まえ]より","after":"。","tiles":["[百円|ひゃくえん]","しか","[安|やす]く","なりませんでした"],"star":2,"bank":[3,1,0,2],"hint":"How much comes first, then しか. しか needs a negative ending, and 安い changes before なる.","full":"セールでも、このシャツは[前|まえ]より[百円|ひゃくえん]しか{[安|やす]く}なりませんでした。","explain":"百円, しか, 安く, なりませんでした. 百円しか needs a negative ending, so it goes with なりませんでした. 安い becomes 安く before なる: \"Even in the sale, this shirt only got 100 yen cheaper than before.\""},{"id":"n5u08d6.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A：[何|なに]にしますか。B：メニューの","after":"します。","tiles":["[中|なか]で","いちばん","[安|やす]いの","に"],"star":2,"bank":[2,3,0,1],"hint":"メニューの needs 中で to make the group. 安いの means \"the cheap one\", and に comes right before します.","full":"A：[何|なに]にしますか。B：メニューの[中|なか]でいちばん{[安|やす]いの}にします。","explain":"中で, いちばん, 安いの, に. メニューの中で is the group, いちばん安いの is the cheapest one, and にします says what you choose: \"I'll have the cheapest one on the menu.\""}],"exam":[{"id":"n5u08d6.e1","kind":"choice","type":"文の文法1","label":"Choose the answer","q":"この　店の　ケーキは　どれも　おいしいですが、チーズケーキが　（　　）　すきです。","options":["どちらも","だけ","いちばん","しか"],"answer":3,"explain":"どれも shows there are many cakes, and the speaker picks one: チーズケーキが　いちばん　すきです, I like the cheesecake best. どちらも is about two things and does not pick one. だけ cannot come after が here, and しか needs a negative ending, but the ending is すきです."},{"id":"n5u08d6.e2","kind":"choice","type":"文の文法1","label":"Choose the answer","q":"あつく　なりましたから、かみを　（　　）。","options":["みじかいに　しました","みじかいに　なりました","みじかく　なりました","みじかく　しました"],"answer":4,"explain":"かみを has を, so someone changed the hair: みじかく　しました, I had my hair cut short. なりました needs が (かみが　みじかく　なりました), so it does not fit after かみを. みじかい is an い adjective, so it takes く, not に."},{"id":"n5u08d6.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「どちらの　かばんに　しますか。」\nB「","after":"、それに　します。」","tiles":["白い","かばんの","ほうが","安いですから"],"star":2,"bank":[3,2,0,1],"full":"A「どちらの　かばんに　しますか。」\nB「白い　かばんの　{ほうが}　安いですから、それに　します。」","explain":"白い, かばんの, ほうが, 安いですから. 白い goes before かばん, a noun needs の before ほうが, and から gives the reason for the choice: \"The white bag is cheaper, so I'll take that one.\""}]},"scene":{"ja":"古本の店のセール","en":"A sale poster at a second-hand bookshop","intro":"Tap each word on the bookshop's sale poster with its old and new prices.","words":[{"id":"used-book","word":"古本","reading":"ふるほん","gloss":"second-hand book","parts":[["古","ふる","old"],["本","ホン","book"]],"clip":"s_n5u8d6_used_book"},{"id":"this-week","word":"今週","reading":"こんしゅう","gloss":"this week","parts":[["今","コン","now"],["週","シュウ","week"]],"clip":"s_n5u8d6_this_week"},{"id":"next-week","word":"来週","reading":"らいしゅう","gloss":"next week","parts":[["来","ライ","come, next"],["週","シュウ","week"]],"clip":"s_n5u8d6_next_week"},{"id":"foreign-language","word":"外国語","reading":"がいこくご","gloss":"foreign language","parts":[["外","ガイ","outside"],["国","コク","country"],["語","ゴ","language"]],"clip":"s_n5u8d6_foreign_language"},{"id":"2000-yen","word":"二千円","reading":"にせんえん","gloss":"2,000 yen","parts":[["二","ニ","two"],["千","セン","thousand"],["円","エン","yen"]],"clip":"s_n5u8d6_2000_yen"},{"id":"800-yen","word":"八百円","reading":"はっぴゃくえん","gloss":"800 yen","parts":[["八","ハッ","eight"],["百","ピャク","hundred"],["円","エン","yen"]],"clip":"s_n5u8d6_800_yen"},{"id":"cheaply","word":"安く","reading":"やすく","gloss":"cheaper, cheaply (from 安い)","parts":[["安","やす","cheap"]],"clip":"s_n5u8d6_cheaply"},{"id":"every-day","word":"毎日","reading":"まいにち","gloss":"every day","parts":[["毎","マイ","every"],["日","ニチ","day"]],"clip":"s_n5u8d6_every_day"}],"check":{"id":"n5u08d6.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"この　本は　今週だけ　_八百円_です。","options":["はっぴゃくえん","はっひゃくえん","はちびゃくえん","はちひゃくえん"],"answer":1,"explain":"八百円 is read はっぴゃくえん: 八 becomes はっ and 百 becomes ぴゃく. はちひゃくえん, はっひゃくえん and はちびゃくえん are not how 800 is said."}},"skill":{"kind":"reading","ja":"情報検索","en":"Finding information","ask":"Which item at the café will get cheaper from next month?","seconds":90,"passage":"山川カフェの　おしらせ\n来月から　すこし　かわります。\n（今月　→　来月）\nコーヒー　三百円　→　三百五十円\nこうちゃ　三百円（かわりません）\nケーキ　四百円　→　四百五十円\n^サンドイッチ　五百円　→　四百五十円^\nこれからも　よろしく　おねがいします。","strategy":"Compare the two prices on each line and find the one where the second price, next month's, is lower.","item":{"id":"n5u08d6.r1","kind":"choice","type":"読解・情報検索","q":"来月から　安く　なる　ものは　どれですか。","options":["ケーキ","サンドイッチ","コーヒー","こうちゃ"],"short":["ケーキ","サンドイッチ","コーヒー","こうちゃ"],"answer":2,"explain":"The sandwich line reads 五百円　→　四百五十円: 500 yen this month, 450 yen next month. It is the only price that goes down.","why":["Cake goes from 400 yen to 450 yen, so it gets more expensive.","","Coffee goes from 300 yen to 350 yen, so it gets more expensive.","Tea stays at 300 yen (かわりません, no change)."]}}}],"test":[{"id":"n5u08t.1","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"りんごを　_半分_に　きって、友だちと　食べました。","options":["はんぶん","はんぷん","はんふん","ばんぶん"],"answer":1,"explain":"半分 is はんぶん, half. The 分 in this word is ぶん, with the dakuten. はんふん and はんぷん give 分 the sounds it has in times (ふん, ぷん), which are not used in 半分. ばんぶん wrongly puts a dakuten on は."},{"id":"n5u08t.2","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"この　まちは　前より　人が　_多く_　なりました。","options":["おうく","すくなく","たく","おおく"],"answer":4,"explain":"多く is おおく, from 多い (many). おうく spells the long お with う; 多い is written おおい. すくなく is a real word, but it is 少なく (few), the opposite. たく is not a reading of 多く."},{"id":"n5u08t.3","kind":"choice","type":"表記","label":"Kanji spelling","q":"この　店の　やさいは　先週より　_やすく_　なりました。","options":["高く","安く","休く","女く"],"answer":2,"explain":"やすく (cheaper) is 安く, from 安い. 休 is the やす of 休みます, but 休く is not a word. 女 looks like the bottom of 安, but 女く is not a word. 高く is a real word, but it is たかく (more expensive)."},{"id":"n5u08t.4","kind":"choice","type":"表記","label":"Kanji spelling","q":"この　くつは　ちょっと　_ちいさい_です。もっと　大きいのは　ありますか。","options":["小さい","少ない","小い","少さい"],"answer":1,"explain":"ちいさい (small) is written 小さい. 少 looks like 小 with an extra stroke, but 少さい is not a word. 少ない is a real word, but it is すくない (few). 小い leaves out the さ that 小さい needs."},{"id":"n5u08t.5","kind":"choice","type":"文脈規定","label":"Word in context","q":"わたしの　へやは　せまいですが、あねの　へやは　（　　）です。","options":["みじかい","ひろい","ほそい","せまい"],"answer":2,"explain":"が (but) shows the two rooms are different: my room is small, but my sister's is big, ひろい. せまい would make them the same, so が does not fit. みじかい (short) and ほそい (thin) are not used for the size of a room."},{"id":"n5u08t.6","kind":"choice","type":"文脈規定","label":"Word in context","q":"子どもの　ときは　にんじんが　きらいでしたが、今は　（　　）に　なりました。","options":["きらい","じょうず","すき","へた"],"answer":3,"explain":"でしたが (was, but) shows a change: I disliked carrots as a child, but now I like them, すきに なりました. きらい would mean nothing changed. じょうず (good at) and へた (bad at) are for skills, not for food."},{"id":"n5u08t.7","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"はこの　中に　りんごが　_二つしか　ありません_。","options":["はこの　中に　りんごが　二つも　あります。","はこの　中に　りんごが　一つも　ありません。","はこの　中に　りんごが　二つだけ　あります。","はこの　中に　りんごが　二つより　多く　あります。"],"answer":3,"explain":"二つしか ありません means there are only two, which is the same as 二つだけ あります. 二つも あります stresses that two is a lot, the opposite feeling. 一つも ありません means there are none. 二つより 多く means more than two."},{"id":"n5u08t.8","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"きのう、_へやを　きれいに　しました_。","options":["きのう、へやで　あそびました。","きのう、へやを　かりました。","きのう、へやが　きたなく　なりました。","きのう、へやを　そうじしました。"],"answer":4,"explain":"へやを きれいに しました means I made the room clean, which is closest to そうじしました (cleaned). きたなく なりました says the room got dirty, the opposite. あそびました (played) and かりました (rented) say nothing about making it clean."},{"id":"n5u08t.9","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きのうより　今日（　　）　さむいですね。","options":["のほうが","より","ほうが","のほうに"],"answer":1,"explain":"きのうより already gives the thing compared, so the colder day takes のほうが: 今日のほうが さむい. 今日より would compare today with today. ほう needs の after a noun, so ほうが alone is wrong. さむい needs が for the thing that is cold, not に."},{"id":"n5u08t.10","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　白い　くつと　あの　くろい　くつと、（　　）が　すきですか。」B「白い　くつの　ほうが　すきです。」","options":["どこ","どなた","どれ","どちら"],"answer":4,"explain":"A names two pairs of shoes with と…と, so the question word is どちら (which of the two). どれ is for three or more. どこ asks about a place and どなた about a person, and B answers with one of the shoes."},{"id":"n5u08t.11","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしの　まちは、一年の　中で　八月が　（　　）　あついです。","options":["いちばん","どちら","ほう","どれ"],"answer":1,"explain":"〜の 中で X が いちばん says X is the most of a group: in the whole year, August is the hottest. どちら and どれ are question words and cannot sit in a statement like this. ほう is used with のほうが to compare two things, and there is no の before it here."},{"id":"n5u08t.12","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　二つの　カメラ、どちらが　いいですか。」B「（　　）　いいですが、こちらの　ほうが　安いですよ。」","options":["どちらも","なにも","どれも","どちらが"],"answer":1,"explain":"B says both cameras are good (but this one is cheaper). For two things, both is どちらも. どれも is for three or more, and A asks about 二つ. どちらが is a question and does not answer one. なにも goes with a negative ending, not with いいです."},{"id":"n5u08t.13","kind":"choice","type":"文の文法1","label":"Choose the form","q":"もう　五時ですね。空が　くらく　（　　）ね。","options":["でした","なりました","ありました","しました"],"answer":2,"explain":"The sky changed on its own, so くらく takes なりました (became dark). くらく しました means someone made it dark, and that needs を, not 空が. ありました and でした do not follow the く form."},{"id":"n5u08t.14","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ズボンが　長いですから、少し　みじかく　（　　）　ください。","options":["いて","して","なって","あって"],"answer":2,"explain":"The speaker asks a person to make the trousers shorter: みじかく して ください. みじかく なって ください asks the trousers themselves to become short, which a person cannot ask. あって and いて do not follow the く form to mean make or become."},{"id":"n5u08t.15","kind":"choice","type":"文の文法1","label":"Choose the form","q":"月よう日から　金よう日まで　しごとが　いそがしいですから、テレビは　日よう日（　　）　見ます。","options":["を","だけ","が","しか"],"answer":2,"explain":"The speaker watches TV only on Sunday, and the verb 見ます is positive, so the word is だけ. しか means only too, but it needs a negative verb (見ません). を and が do not go after 日よう日 here; テレビは is what is watched."},{"id":"n5u08t.16","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしの　かぞくの　","after":"　人は　母です。","tiles":["中で","いちばん","はやく","おきる"],"star":1,"bank":[3,1,0,2],"full":"わたしの　かぞくの　中で　{いちばん}　はやく　おきる　人は　母です。","explain":"中で, いちばん, はやく, おきる. かぞくの must be followed by 中で (in my family). いちばん goes right before the word it makes the most: いちばん はやく (the earliest). はやく describes おきる, and おきる describes 人, so it comes just before 人は."},{"id":"n5u08t.17","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしは　いつも　コーヒーに　","after":"　飲みます。","tiles":["さとうを","入れて","あまく","して"],"star":2,"bank":[3,0,2,1],"full":"わたしは　いつも　コーヒーに　さとうを　入れて　{あまく}　して　飲みます。","explain":"さとうを, 入れて, あまく, して. さとうを needs its verb after it: さとうを 入れて (put in sugar). An adjective before する takes the く form: あまく して (make it sweet). して joins to 飲みます, so it comes last."},{"id":"n5u08t.18","kind":"star","type":"文の文法2","label":"Build the sentence","before":"ケーキが　","after":"　しましょう。","tiles":["一つ","しか","ありませんから","半分に"],"star":1,"bank":[2,3,0,1],"full":"ケーキが　一つ　{しか}　ありませんから　半分に　しましょう。","explain":"一つ, しか, ありませんから, 半分に. しか follows the amount and needs a negative verb after it: 一つしか ありません (there is only one). から gives the reason. 半分に goes with しましょう at the end: 半分に しましょう (let's cut it in half)."},{"id":"n5u08t.19","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"駅の　前に　新しい　パンやが　あります。今日、母と　はじめて　行きました。となりの　店より　少し　高いですが、パンが　大きくて、とても　おいしかったです。わたしは　チーズの　パンを　三つ　買いました。母は　あまい　パンを　一つだけ　買いました。こんどは　友だちと　行きたいです。","q":"ただしい　ものは　どれですか。","options":["新しい　パンやは　となりの　店より　安いです。","新しい　パンやの　パンは　大きいです。","母は　チーズの　パンを　三つ　買いました。","わたしは　友だちと　パンやへ　行きました。"],"answer":2,"short":["となりより安い","パンが大きい","母がチーズ三つ","友だちと行った"],"explain":"The writer says パンが 大きくて, とても おいしかった: the bread is big. The new shop is a little more expensive (高い) than the shop next door, not cheaper. The writer bought three cheese breads; the mother bought one sweet bread. The writer went with the mother and wants to go with friends next time."},{"id":"n5u08t.20","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"駅の　前に　新しい　パンやが　あります。今日、母と　はじめて　行きました。となりの　店より　少し　高いですが、パンが　大きくて、とても　おいしかったです。わたしは　チーズの　パンを　三つ　買いました。母は　あまい　パンを　一つだけ　買いました。こんどは　友だちと　行きたいです。","q":"母は　何を　買いましたか。","options":["あまい　パンを　一つ","あまい　パンを　三つ","チーズの　パンを　一つ","チーズの　パンを　三つ"],"answer":1,"short":["あまいの一つ","あまいの三つ","チーズ一つ","チーズ三つ"],"explain":"The passage says 母は あまい パンを 一つだけ 買いました. Three cheese breads (チーズの パンを 三つ) is what the writer bought. Neither person bought three sweet breads or one cheese bread."},{"id":"n5u08t.21","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"レストラン　やま　ランチ（十一時から　二時まで）\nカレー　七百円\n魚の　ランチ　九百円\nパンと　スープ　六百円\n・ランチを　食べる　人は、コーヒーと　こうちゃが　百円に　なります。\n・土よう日と　日よう日は、パンと　スープだけです。","q":"日よう日に　この　レストランで　ランチを　食べます。何を　食べますか。","options":["カレーと　パン","カレー","魚の　ランチ","パンと　スープ"],"answer":4,"short":["カレーとパン","カレー","魚","パンとスープ"],"explain":"The notice says 土よう日と 日よう日は、パンと スープだけです: on Saturday and Sunday there is only bread and soup. Curry and the fish lunch are not served on Sunday, and curry with bread is not on the menu."},{"id":"n5u08t.22","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"レストラン　やま　ランチ（十一時から　二時まで）\nカレー　七百円\n魚の　ランチ　九百円\nパンと　スープ　六百円\n・ランチを　食べる　人は、コーヒーと　こうちゃが　百円に　なります。\n・土よう日と　日よう日は、パンと　スープだけです。","q":"火よう日に　カレーと　コーヒーを　たのみます。ぜんぶで　いくらですか。","options":["七百円","八百円","九百円","千円"],"answer":2,"short":["七百円","八百円","九百円","千円"],"explain":"Curry is 七百円, and with a lunch, coffee is 百円 (コーヒーと こうちゃが 百円に なります). 700 + 100 = 八百円. 七百円 leaves out the coffee. 九百円 is the price of the fish lunch. 千円 does not match any order here."},{"id":"n5u08t.23","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ケンさんへ\n先週から　駅の　前の　としょかんが　新しく　なりました。前より　大きく　なって、本も　多く　なりました。でも、月よう日は　休みです。日よう日は　人が　多いですから、わたしは　いつも　土よう日に　行きます。こんど、いっしょに　行きませんか。\nマリ","q":"新しい　としょかんは　どう　なりましたか。","options":["前より　大きく　なりました。","前より　小さく　なりました。","本が　少なく　なりました。","日よう日が　休みに　なりました。"],"answer":1,"short":["大きくなった","小さくなった","本が少ない","日よう日休み"],"explain":"マリ writes 前より 大きく なって, 本も 多く なりました: the library got bigger and has more books. So it did not get smaller, and the books did not become fewer. The day off is 月よう日; on 日よう日 it is open and crowded."},{"id":"n5u08t.24","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ケンさんへ\n先週から　駅の　前の　としょかんが　新しく　なりました。前より　大きく　なって、本も　多く　なりました。でも、月よう日は　休みです。日よう日は　人が　多いですから、わたしは　いつも　土よう日に　行きます。こんど、いっしょに　行きませんか。\nマリ","q":"マリさんは　どうして　土よう日に　としょかんへ　行きますか。","options":["日よう日は　休みだからです。","土よう日は　本が　多いからです。","日よう日は　人が　多いからです。","ケンさんと　行くからです。"],"answer":3,"short":["日よう日休み","土よう日本が多い","日よう日人が多い","ケンさんと"],"explain":"マリ writes 日よう日は 人が 多いですから, わたしは いつも 土よう日に 行きます: Sunday is crowded, so she goes on Saturday. The library is closed on 月よう日, not 日よう日. The books are not more on Saturday. マリ only invites ケン for next time; that is not why she goes on Saturday."}]}],"items":{"n5u01d1.c1":{"id":"n5u01d1.c1","kind":"choice","type":"文の文法1","label":"じこしょうかい","q":"マリアさんは[先生|せんせい]（　　）。^[日本語|にほんご]をおしえます^。","options":["ですか","です","じゃありません"],"answer":2,"why":["This asks whether she is a teacher, but the speaker already knows: the next sentence says she teaches Japanese.","Maria teaches Japanese, so she is a teacher: use です.","This says she is not a teacher, but the next sentence says she teaches Japanese."],"explain":null,"unit":1,"day":1,"step":"compare"},"n5u01d1.d1":{"id":"n5u01d1.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"はじめまして。わたし（　　）^ルイスです^。","options":["で","は","を","へ"],"answer":2,"why":["で shows where something happens, as in がっこうで. It cannot mark the topic.","は marks the topic, the person you talk about: わたし. Then ルイスです says who that is.","を marks the thing an action is done to, as in パンをたべます. There is no action here.","へ shows the direction you go, as in がっこうへいきます. It cannot mark the topic."],"explain":null,"unit":1,"day":1,"step":"drill"},"n5u01d1.d2":{"id":"n5u01d1.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは^[中国人|ちゅうごくじん]^（　　）。","options":["です","ます","は","を"],"answer":1,"why":["中国人 is a noun, and です after a noun says what someone is.","ます goes after a verb, as in たべます. 中国人 is a noun.","は marks a topic. The sentence still needs an ending after 中国人.","を marks the thing an action is done to. There is no action, and no ending."],"unit":1,"day":1,"step":"drill"},"n5u01d1.d3":{"id":"n5u01d1.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは[先生|せんせい]（　　）。^[学生|がくせい]です^。","options":["です","ます","を","じゃありません"],"answer":4,"why":["先生です would say I am a teacher, but the next sentence says I am a student.","ます goes after a verb. 先生 is a noun.","を marks the thing an action is done to. The sentence would have no ending.","The next sentence says I am a student, so I am not a teacher: 先生じゃありません."],"explain":null,"unit":1,"day":1,"step":"drill"},"n5u01d1.d4":{"id":"n5u01d1.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ルイスさんは[日本人|にほんじん]（　　）。^ブラジル[人|じん]です^。","options":["ありません","ではありません","です","ですか"],"answer":2,"why":["Without では, ありません here would mean \"there is none\", not \"is not\".","Luis is Brazilian, so he is not Japanese. ではありません is the formal way to say \"is not\".","日本人です would say he is Japanese, but the next sentence says he is Brazilian.","This asks whether he is Japanese, but the next sentence already says what he is: Brazilian."],"explain":null,"unit":1,"day":1,"step":"drill"},"n5u01d1.d5":{"id":"n5u01d1.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"はじめまして。","after":"。","tiles":["わたしは","[日本語|にほんご]の","[先生|せんせい]","です"],"star":1,"bank":[3,0,2,1],"hint":"Start with the topic and は. です comes at the very end.","full":"はじめまして。わたし{は}[日本語|にほんご]の[先生|せんせい]{です}。","explain":"わたしは is the topic, so it comes first. 日本語の tells what kind of teacher, so it sits right before 先生, and です closes the sentence.","unit":1,"day":1,"step":"drill"},"n5u01d1.d6":{"id":"n5u01d1.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしは","after":"。","tiles":["[学校|がっこう]の","[先生|せんせい]","では","ありません"],"star":2,"bank":[1,3,0,2],"hint":"Which tiles make \"is not\"? They come after the noun.","full":"わたしは[学校|がっこう]の[先生|せんせい]{ではありません}。","explain":"学校の tells what kind of teacher, so it sits right before 先生. では and ありません together mean \"is not\" (more formal than じゃありません), and they follow the noun.","unit":1,"day":1,"step":"drill"},"n5u01d1.e1":{"id":"n5u01d1.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「マリアさんは　先生ですか。」\nB「いいえ、先生（　　）。学生です。」","options":["ます","ありません","じゃありません","です"],"answer":3,"explain":"いいえ and 学生です show that Maria is not a teacher, so 先生じゃありません. 先生です says the opposite, ます goes after a verb, not a noun, and ありません without じゃ does not mean \"is not\" here.","unit":1,"day":1,"step":"exam"},"n5u01d1.e2":{"id":"n5u01d1.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ルイスさん（　　）　ブラジル人です。","options":["に","で","は","を"],"answer":3,"explain":"は marks ルイスさん as the topic, and ブラジル人です says what he is. を marks the thing an action is done to, に marks a time or a place to go, and で marks where something happens. None of them can mark the topic.","unit":1,"day":1,"step":"exam"},"n5u01d1.e3":{"id":"n5u01d1.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしの","after":"。かいしゃいんです。","tiles":["父は","日本語の","先生","じゃありません"],"star":2,"bank":[3,1,0,2],"full":"わたしの父は日本語の{先生}じゃありません。かいしゃいんです。","explain":"父は, 日本語の, 先生, じゃありません. わたしの goes with 父, the topic. 日本語の tells what kind of teacher, and じゃありません comes last, after the noun.","unit":1,"day":1,"step":"exam"},"n5u01d1.k1":{"id":"n5u01d1.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"わたしは　日本語学校の　_学生_です。","options":["がっせい","かくせい","がくせ","がくせい"],"answer":4,"explain":"学生 is がくせい, with a long せい at the end. 学 becomes がっ only before some sounds, as in 学校 (がっこう), not here. かくせい has the wrong first sound, and がくせ drops the い.","unit":1,"day":1,"step":"scene"},"n5u01d1.r1":{"id":"n5u01d1.r1","kind":"choice","type":"発話表現","q":"はじめて　先生に　あいました。何と　いいますか。","script":["ナレーター：はじめて　先生に　あいました。何と　いいますか。","ナレーター：1","女：どうも　ありがとう。リンです。","ナレーター：2","女：はじめまして。リンです。よろしく　おねがいします。","ナレーター：3","女：はじめまして。リンさんですか。"],"options":["どうも　ありがとう。リンです。","はじめまして。リンです。よろしく　おねがいします。","はじめまして。リンさんですか。"],"printed":false,"short":["ありがとう。リンです","はじめまして。リンです","リンさんですか"],"answer":2,"why":["ありがとう is for thanks. The teacher has not done anything for her yet.","","She is Lin. リンさんですか asks the teacher if the teacher is Lin."],"unit":1,"day":1,"step":"skill","clip":"l_n5u1d1"},"n5u01d2.c1":{"id":"n5u01d2.c1","kind":"choice","type":"文の文法1","label":"クラスで","q":"A：やまださんは[先生|せんせい]ですか。B：いいえ、ちがいます。やまださん（　　）[学生|がくせい]です。","options":["は","も","か"],"answer":1,"why":["B now says what Ms Yamada really is: やまださんは学生です.","も means \"too\". Nobody else in this talk is a student, so there is nothing to add to.","か between names means \"or\", but no second name follows here."],"unit":1,"day":2,"step":"compare"},"n5u01d2.d1":{"id":"n5u01d2.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：キムさんは[先生|せんせい]です（　　）。B：^はい、そうです^。","options":["を","か","も","は"],"answer":2,"why":["を marks what a verb acts on. It cannot follow です.","か after です makes a question, and B answers it with はい、そうです.","も goes after a noun, as in キムさんも. It cannot end a sentence after です.","は goes after a noun, as in キムさんは. It cannot end a sentence after です."],"explain":null,"unit":1,"day":2,"step":"drill"},"n5u01d2.d2":{"id":"n5u01d2.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：それは[日本語|にほんご]の[本|ほん]ですか。B：いいえ、（　　）。^ノートです^。","options":["そうですか","ちがいますか","ちがいます","そうです"],"answer":3,"why":["そうですか means \"oh, I see\". It reacts to news. It does not answer A's question.","ちがいますか asks a question back. B is answering here, not asking.","After いいえ, ちがいます says \"that's not right\". Then B says what it really is: a notebook.","そうです means \"yes, that's right\". It clashes with いいえ, and B goes on to say it is a notebook."],"explain":null,"unit":1,"day":2,"step":"drill"},"n5u01d2.d3":{"id":"n5u01d2.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"やまださん（　　）^キムさんも^[学生|がくせい]です。","options":["は","か","が","も"],"answer":4,"why":["は does not pair with キムさんも. When two names share the sentence like this, each one takes も.","か between names means \"or\", and then キムさん would not take も.","が does not pair with キムさんも either. Each name takes も.","Both people are students: AもBも. キムさんも asks for も after やまださん too."],"explain":null,"unit":1,"day":2,"step":"drill"},"n5u01d2.d4":{"id":"n5u01d2.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：^わたしは[学生|がくせい]です^。B：あ、わたし（　　）です。","options":["も","は","か","が"],"answer":1,"why":["わたしもです means \"me too\": B is a student as well. も replaces the は of わたしは学生です.","わたしはです is not a sentence. は needs a word before です, as in わたしは学生です.","か cannot sit between わたし and です. To ask, か goes at the end: ですか.","わたしがです is not a sentence. が also needs a word before です."],"unit":1,"day":2,"step":"drill"},"n5u01d2.d5":{"id":"n5u01d2.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"やまださんは","after":"。","tiles":["[日本語|にほんご]の","[先生|せんせい]","です","か"],"star":2,"bank":[2,0,3,1],"hint":"What kind of teacher? 日本語の sits right before 先生. か always comes last.","full":"やまださんは[日本語|にほんご]の[先生|せんせい]です{か}。","explain":"日本語の describes 先生, so it goes first. Then です, and か at the very end turns the sentence into a question.","unit":1,"day":2,"step":"drill"},"n5u01d2.d6":{"id":"n5u01d2.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A：わたしは[日本語|にほんご]の[学生|がくせい]です。B：","after":"です。","tiles":["わたし","も","[日本語|にほんご]の","[学生|がくせい]"],"star":1,"bank":[2,0,3,1],"hint":"B is a Japanese student too. Which tile can follow わたし?","full":"A：わたしは[日本語|にほんご]の[学生|がくせい]です。B：わたし{も}[日本語|にほんご]の[学生|がくせい]です。","explain":"B says the same thing as A, so わたし takes も in place of は. 日本語の must sit right before 学生.","unit":1,"day":2,"step":"drill"},"n5u01d2.e1":{"id":"n5u01d2.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：すみません。これは　出口ですか。B：はい、（　　）。","options":["そうですか","なんですか","そうです","ちがいます"],"answer":3,"explain":"はい goes with そうです: \"yes, it is\". はい、ちがいます contradicts itself. そうですか only reacts to news, and なんですか asks a new question instead of answering.","unit":1,"day":2,"step":"exam"},"n5u01d2.e2":{"id":"n5u01d2.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"つくえの　上に、本も　ノート（　　）　あります。","options":["を","も","は","が"],"answer":2,"explain":"本も comes first, so ノート takes も too: 本もノートもあります, \"both a book and a notebook\". は and が cannot pair with 本も like this, and を is not used with あります.","unit":1,"day":2,"step":"exam"},"n5u01d2.e3":{"id":"n5u01d2.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A：","after":"。B：はい、そうです。","tiles":["これは","先生の","本","ですか"],"star":1,"bank":[2,0,3,1],"full":"A：これは　{先生の}　本ですか。B：はい、そうです。","explain":"これは, 先生の, 本, ですか. これは starts the question, 先生の must sit right before 本, and ですか ends it.","unit":1,"day":2,"step":"exam"},"n5u01d2.k1":{"id":"n5u01d2.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"すみません、_出口_は　どこですか。","options":["でくち","しゅつぐち","だしぐち","でぐち"],"answer":4,"explain":"出口 is でぐち: 出 read で, and 口 becomes ぐち after it, as in 入口 (いりぐち). でくち misses that change, しゅつ is the reading in other words, and だしぐち is not a word.","unit":1,"day":2,"step":"scene"},"n5u01d2.r1":{"id":"n5u01d2.r1","kind":"choice","type":"読解・内容理解（短文）","q":"ただしい　ものは　どれですか。","options":["リンさんは　日本語の　先生です。","ワンさんは　中国人です。","ワンさんは　リンさんの　先生です。","ワンさんは　大学生です。"],"short":["リン：日本語の先生","ワン：中国人","ワン：リンの先生","ワン：大学生"],"answer":2,"explain":"ワンさんも中国人です: も means Wang is Chinese too, like Lin.","why":["Lin is a university student. The Japanese teacher is Wang.","","Wang is a teacher, but Lin says わたしの先生じゃありません: not my teacher.","Lin is the university student. Wang is a teacher."],"unit":1,"day":2,"step":"skill"},"n5u01d3.c1":{"id":"n5u01d3.c1","kind":"choice","type":"文の文法1","label":"花やで","q":"すみません、（　　）[花|はな]は[何|なん]ですか。","options":["ここ","これ","この"],"answer":3,"why":["ここ means this place. It cannot go right before 花.","これ stands alone, as in これは何ですか. It cannot go right before 花.","A noun (花) comes right after the blank, so この."],"explain":null,"unit":1,"day":3,"step":"compare"},"n5u01d3.d1":{"id":"n5u01d3.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：（　　）は[何|なん]ですか。　B：^それは^[魚|さかな]です。","options":["この","どれ","あの","これ"],"answer":4,"why":["この needs a noun after it, as in この魚は.","どれ asks which one. It cannot ask 何ですか at the same time.","あの needs a noun after it, as in あの魚は.","これ stands alone before は. B answers with それ because the fish is near A."],"explain":null,"unit":1,"day":3,"step":"drill"},"n5u01d3.d2":{"id":"n5u01d3.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"（　　）^かばん^は[高|たか]いです。","options":["どこ","それ","その","どれ"],"answer":3,"why":["どこ asks where. It cannot go right before かばん.","それ stands alone. It cannot go right before かばん.","A noun (かばん) comes right after the blank, so その.","どれ cannot go before a noun, and this sentence is not a question."],"explain":null,"unit":1,"day":3,"step":"drill"},"n5u01d3.d3":{"id":"n5u01d3.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：（　　）^かさ^がいいですか。　B：その[白|しろ]いかさがいいです。","options":["どの","[何|なに]","あれ","どれ"],"answer":1,"why":["A asks which umbrella, and かさ comes right after the blank, so どの.","何 cannot go right before かさ like this.","あれ stands alone and does not ask a question.","どれ stands alone, as in どれがいいですか. It cannot go right before かさ."],"explain":null,"unit":1,"day":3,"step":"drill"},"n5u01d3.d4":{"id":"n5u01d3.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"すみません、（　　）^を^ください。","options":["あの","どれ","どこ","あれ"],"answer":4,"why":["あの needs a noun before を, as in あの花をください.","どれ asks which one. You cannot ask for something with a question word.","どこ asks where. A place is not something you ask a shop for.","あれ stands alone, so を can come right after it: あれをください."],"explain":null,"unit":1,"day":3,"step":"drill"},"n5u01d3.d5":{"id":"n5u01d3.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"すみません、","after":"。","tiles":["どの","[人|ひと]が","[先生|せんせい]","ですか"],"star":1,"bank":[2,0,3,1],"hint":"どの needs a noun right after it. Which tile can follow どの?","full":"すみません、{どの}[人|ひと]が[先生|せんせい]ですか。","explain":"どの goes right before 人が. 先生 comes before ですか: どの人が先生ですか, \"Which person is the teacher?\"","unit":1,"day":3,"step":"drill"},"n5u01d3.d6":{"id":"n5u01d3.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"すみません、","after":"ですか。","tiles":["あれ","は","[何|なん]の","[店|みせ]"],"star":2,"bank":[3,1,0,2],"hint":"あれ stands alone, so は can come straight after it.","full":"すみません、{あれ}は[何|なん]の[店|みせ]ですか。","explain":"あれは comes first. 何の goes right before 店: あれは何の店ですか, \"What kind of shop is that?\"","unit":1,"day":3,"step":"drill"},"n5u01d3.e1":{"id":"n5u01d3.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：その　魚は　高いですか。　B：いいえ、（　　）魚は　安いです。","options":["これ","この","どれ","ここ"],"answer":2,"explain":"A noun (魚) comes right after the blank, and the fish is near B, so この. これ and ここ stand alone, and どれ is a question word that also cannot go before a noun.","unit":1,"day":3,"step":"exam"},"n5u01d3.e2":{"id":"n5u01d3.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：あなたの　かさは　（　　）ですか。　B：あの　白い　かさです。","options":["この","あの","どれ","どの"],"answer":3,"explain":"B picks one umbrella out of several, so A asked which one: どれ. どの, この and あの all need a noun right after them.","unit":1,"day":3,"step":"exam"},"n5u01d3.e3":{"id":"n5u01d3.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"すみません、","after":"ですか。","tiles":["この","花","は","いくら"],"star":1,"bank":[3,1,0,2],"full":"すみません、{この}　花は　いくらですか。","explain":"この, 花, は, いくら. この needs a noun right after it, so この花は comes first, then いくら before ですか.","unit":1,"day":3,"step":"exam"},"n5u01d3.k1":{"id":"n5u01d3.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"デパートで　_新しい_　本を　買いました。","options":["あたしらい","あらたしい","あたらいし","あたらしい"],"answer":4,"explain":"新しい is read あたらしい, \"new\". The other three mix up the order of the kana.","unit":1,"day":3,"step":"scene"},"n5u01d3.r1":{"id":"n5u01d3.r1","kind":"choice","type":"即時応答","q":"男：すみません、それは　何ですか。","script":["男：すみません、それは何ですか。","ナレーター：1","女：はい、そうです。","ナレーター：2","女：これは、日本のおかしです。","ナレーター：3","女：あれは、おかしです。"],"options":["はい、そうです。","これは、日本のおかしです。","あれは、おかしです。"],"printed":false,"short":["はい、そうです","これは、日本のおかし","あれは、おかし"],"answer":2,"why":["The man asks what it is, not a yes-or-no question, so はい、そうです does not answer him.","He says それ, so the thing is near the woman. She answers with これ and says what it is.","あれ is for something far from both people. He said それ, so the thing is near her."],"unit":1,"day":3,"step":"skill","clip":"l_n5u1d3"},"n5u01d4.c1":{"id":"n5u01d4.c1","kind":"choice","type":"文の文法1","label":"アルバム","q":"A：これはだれの[本|ほん]ですか。　B：[父|ちち]（　　）[本|ほん]です。","options":["も","の","と"],"answer":2,"why":["父も本です would mean \"my father is a book too\".","The owner, then の, then the thing: 父の本 is my father's book.","父と本 would mean \"my father and a book\". The question asks whose book it is."],"explain":null,"unit":1,"day":4,"step":"compare"},"n5u01d4.d1":{"id":"n5u01d4.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：それはだれのかさですか。　B：^わたし^（　　）かさです。","options":["は","を","の","も"],"answer":3,"why":["わたしはかさです would mean \"I am an umbrella\".","を marks the thing you act on with a verb. There is no verb here.","The owner わたし, then の, then かさ: my umbrella.","わたしもかさです would mean \"I am an umbrella too\"."],"explain":null,"unit":1,"day":4,"step":"drill"},"n5u01d4.d2":{"id":"n5u01d4.d2","kind":"star","type":"文の文法2","label":"Build the sentence","before":"これは","after":"です。","tiles":["わたし","の","[友|とも]だち","の[本|ほん]"],"star":2,"bank":[2,3,0,1],"hint":"The owner always comes before の. Who is the friend's, and whose is the book?","full":"これはわたし{の}[友|とも]だちの[本|ほん]です。","explain":"わたしの友だち is my friend, and 友だちの本 is the friend's book. So わたし, の, 友だち, の本: my friend's book.","unit":1,"day":4,"step":"drill"},"n5u01d4.d3":{"id":"n5u01d4.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[山川|やまかわ]さんは^[中学校|ちゅうがっこう]^（　　）[先生|せんせい]です。","options":["か","も","と","の"],"answer":4,"why":["中学校か先生 would mean \"a junior high school or a teacher\".","中学校も先生です would mean \"the school is a teacher too\", which makes no sense.","中学校と先生 would mean \"a junior high school and a teacher\". A person cannot be a school.","Where the teacher belongs: 中学校 + の + 先生, a junior high school teacher."],"explain":null,"unit":1,"day":4,"step":"drill"},"n5u01d4.d4":{"id":"n5u01d4.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[日本語|にほんご]の[先生|せんせい]は^ふたり^です。[中山|なかやま]さん（　　）[山川|やまかわ]さんです。","options":["も","か","と","の"],"answer":3,"why":["中山さんも山川さんです would mean \"Nakayama is Yamakawa too\", which makes no sense.","か means \"or\". It gives one person, not two.","と joins the two names: Nakayama and Yamakawa. That makes two teachers.","中山さんの山川さん would be one person, but the clue says there are two."],"explain":null,"unit":1,"day":4,"step":"drill"},"n5u01d4.d5":{"id":"n5u01d4.d5","kind":"choice","type":"文の文法1","label":"Choose the form","q":"これは^[父|ちち]の[本|ほん]^（　　）^[母|はは]の[本|ほん]^です。","options":["を","の","と","も"],"answer":3,"why":["を marks the thing you act on with a verb. There is no verb here.","父の本の母の本 would mean \"my mother's book of my father's book\", which makes no sense.","と joins the two things: my father's book and my mother's book.","父の本も母の本です would mean \"Dad's book is Mom's book too\". It does not fit after これは."],"explain":null,"unit":1,"day":4,"step":"drill"},"n5u01d4.d6":{"id":"n5u01d4.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしの[父|ちち]","after":"です。","tiles":["と","[母|はは]","は","[先生|せんせい]"],"star":1,"bank":[3,1,0,2],"hint":"と goes between the two people. は comes after both of them.","full":"わたしの[父|ちち]{と}[母|はは]は[先生|せんせい]です。","explain":"父と母 joins the two people, は comes after them, and 先生です says what they are: my father and mother are teachers.","unit":1,"day":4,"step":"drill"},"n5u01d4.e1":{"id":"n5u01d4.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"これは　だれ（　　）かさですか。","options":["の","も","を","が"],"answer":1,"explain":"だれのかさ means \"whose umbrella\": だれ + の + かさ. も, を and が cannot sit between だれ and かさ in this sentence.","unit":1,"day":4,"step":"exam"},"n5u01d4.e2":{"id":"n5u01d4.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしの　すきな　くだものは　りんご（　　）バナナです。","options":["も","を","の","と"],"answer":4,"explain":"と joins two nouns: apples and bananas. りんごのバナナ (\"the apple's banana\") and りんごもバナナ make no sense, and を needs a verb.","unit":1,"day":4,"step":"exam"},"n5u01d4.e3":{"id":"n5u01d4.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あの　女の　人は　","after":"　です。","tiles":["わたし","の","日本語の","先生"],"star":2,"bank":[2,0,3,1],"full":"あの　女の　人は　わたしの　{日本語の}　先生　です。","explain":"わたし, の, 日本語の, 先生: my Japanese teacher. The owner わたし comes first, and 日本語の must sit right before 先生 to say what kind of teacher.","unit":1,"day":4,"step":"exam"},"n5u01d4.k1":{"id":"n5u01d4.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"しゃしんの　_女の子_は　わたしの　友だちです。","options":["おんなのこ","おんなのひと","おとこのひと","おとこのこ"],"answer":1,"explain":"女 is おんな and 子 is こ: 女の子, a girl. おとこのこ is 男の子, and おんなのひと and おとこのひと are 女の人 and 男の人.","unit":1,"day":4,"step":"scene"},"n5u01d4.r1":{"id":"n5u01d4.r1","kind":"choice","type":"読解・内容理解（短文）","q":"しゃしんの　まん中の　男の子の　となりの　女の子は　だれですか。","options":["父の　友だち","父の　友だちの　子ども","母の　友だちの　子ども","わたしの　いもうと"],"short":["父の友だち","父の友だちの子ども","母の友だちの子ども","わたしのいもうと"],"answer":2,"explain":"The boy in the middle is the writer. The girl next to him is 父の友だちの子ども: the child of his father's friend.","why":["Not the friend. She is the friend's child: 友だちの子ども.","","The friend is the father's friend (父の友だち), not the mother's.","The text never says she is the writer's sister."],"unit":1,"day":4,"step":"skill"},"n5u01d5.c1":{"id":"n5u01d5.c1","kind":"choice","type":"文の文法1","label":"駅で","q":"（わたしは^しっています^。[友|とも]だちは^しりません^。）あの[人|ひと]はもり[先生|せんせい]です（　　）。","options":["よ","か","ね"],"answer":1,"why":["You know and your friend does not, so you tell them with よ.","か asks a question, but you already know who she is.","ね asks your friend to agree, but your friend does not know her."],"explain":null,"unit":1,"day":5,"step":"compare"},"n5u01d5.d1":{"id":"n5u01d5.d1","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"（ふたりは^いっしょに[空|そら]を[見|み]ています^。）A「いい[天気|てんき]です（　　）。」B「ええ、そうですね。」","options":["よ","か","を","ね"],"answer":4,"why":["よ tells B something new, but B can see the sky too.","か asks a question, but A can see the weather. B's そうですね agrees; it does not answer a question.","を marks the thing a verb acts on. It cannot end a sentence after です.","Both can see the sky, so A shares a feeling B has too. B agrees with そうですね."],"explain":null,"unit":1,"day":5,"step":"drill"},"n5u01d5.d2":{"id":"n5u01d5.d2","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"（Bさんは^しりません^。）A「Bさん、あの[人|ひと]はわたしの[母|はは]です（　　）。」","options":["か","ね","よ","も"],"answer":3,"why":["か asks a question, but A knows who her own mother is.","ね asks B to agree, but B does not know this.","B does not know, so A tells B something new with よ.","も means \"too\". It cannot end a sentence after です."],"unit":1,"day":5,"step":"drill"},"n5u01d5.d3":{"id":"n5u01d5.d3","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"（ふたりは^いっしょに^ラーメンを[食|た]べています。）A「このラーメンはおいしいです（　　）。」","options":["を","と","よ","ね"],"answer":4,"why":["を marks the thing a verb acts on. It cannot end a sentence after です.","と joins two nouns, as in パンとたまご. It cannot end this sentence.","よ tells B something new, but B is eating the same ramen.","Both are eating it, so A shares a feeling B has too."],"explain":null,"unit":1,"day":5,"step":"drill"},"n5u01d5.d4":{"id":"n5u01d5.d4","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「すみません、[西口|にしぐち]はどこですか。」B「[西口|にしぐち]は","after":"。」","tiles":["あの","ビルの","[前|まえ]です","よ"],"star":1,"bank":[2,3,0,1],"hint":"A asks, so A does not know. Which ending tells new information, and where does it go?","full":"A「すみません、[西口|にしぐち]はどこですか。」B「[西口|にしぐち]はあのビルの[前|まえ]です{よ}。」","explain":"あの goes before ビルの, and ビルの before 前です: \"in front of that building\". よ comes last because B tells A something A does not know.","unit":1,"day":5,"step":"drill"},"n5u01d5.d5":{"id":"n5u01d5.d5","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"（^Aさんは[電車|でんしゃ]を[見|み]ました^。Bさんは[見|み]ませんでした。）A「あ、[電車|でんしゃ]が[来|き]ました（　　）。」","options":["よ","を","ね","か"],"answer":1,"why":["A saw it and B did not, so A tells B something new with よ.","を marks the thing a verb acts on. It cannot end a sentence after ました.","ね asks B to agree, but B did not see the train.","か asks a question, but A saw the train and knows."],"explain":null,"unit":1,"day":5,"step":"drill"},"n5u01d5.d6":{"id":"n5u01d5.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「","after":"。」B「ええ、そうですね。」","tiles":["[今日|きょう]は","いい","[天気|てんき]","ですね"],"star":2,"bank":[3,1,0,2],"hint":"A and B both feel the weather. いい describes a noun, and the ending that shares a feeling comes last.","full":"A「[今日|きょう]はいい[天気|てんき]です{ね}。」B「ええ、そうですね。」","explain":"今日は comes first as the topic. いい goes right before 天気, and ですね ends the sentence because A shares a feeling B has too.","unit":1,"day":5,"step":"drill"},"n5u01d5.e1":{"id":"n5u01d5.e1","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"A「Bさん、いすの　上に　かさが　あります（　　）。」B「あ、わたしのです。ありがとうございます。」","options":["よ","か","を","ね"],"answer":1,"explain":"B did not know and says thank you, so A tells B something new with よ. ね would ask B to agree with something B already knows, か would ask about an umbrella A can see, and を cannot end a sentence.","unit":1,"day":5,"step":"exam"},"n5u01d5.e2":{"id":"n5u01d5.e2","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"（ふたりで　駅まで　あるいて　います。）A「今日は　あついです（　　）。」B「ええ、ほんとうに。」","options":["よ","ね","を","か"],"answer":2,"explain":"They are walking together and both feel the heat, so A shares the feeling with ね and B agrees. か would ask something A can feel, よ would tell B something B already feels, and を cannot end a sentence.","unit":1,"day":5,"step":"exam"},"n5u01d5.e3":{"id":"n5u01d5.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「バスは　どこから　出ますか。」B「","after":"よ。」","tiles":["北口の","前","から","出ます"],"star":2,"bank":[3,1,0,2],"full":"A「バスは　どこから　出ますか。」B「北口の　前{から}　出ますよ。」","explain":"北口の, 前, から, 出ます. 北口の describes 前, から follows the place the bus leaves from, and 出ます goes before よ.","unit":1,"day":5,"step":"exam"},"n5u01d5.k1":{"id":"n5u01d5.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_北口_で　ともだちを　まちます。","options":["きたぐち","きたくち","みなみぐち","ひがしぐち"],"answer":1,"explain":"北 is きた, and in 北口 the 口 is read ぐち, as in 出口 and 入口. きたくち is not a word. みなみぐち is 南口 and ひがしぐち is 東口.","unit":1,"day":5,"step":"scene"},"n5u01d5.r1":{"id":"n5u01d5.r1","kind":"choice","type":"ポイント理解","q":"男の人は　どの　出口から　出ますか。","script":["ナレーター：駅で、男の人と女の人が話しています。男の人はどの出口から出ますか。","男：すみません。山川大学は東口ですか。","女：山川大学ですか。東口じゃありません。北口ですよ。","男：北口ですね。ありがとうございます。","女：あ、すみません。北口は山川デパートです。山川大学は西口ですよ。","男：西口ですね。わかりました。","ナレーター：男の人はどの出口から出ますか。"],"options":["北口","東口","西口","南口"],"printed":true,"short":["北口","東口","西口","南口"],"answer":3,"why":["The woman says 北口 first, then corrects it: the north exit is for the department store.","The man asks about the east exit, but the woman says 東口じゃありません.","The woman corrects herself: 山川大学は西口ですよ. The man checks with 西口ですね.","Nobody talks about the south exit."],"explain":null,"unit":1,"day":5,"step":"skill","clip":"l_n5u1d5"},"n5u01d6.c1":{"id":"n5u01d6.c1","kind":"choice","type":"文の文法1","label":"がっこうで","q":"A：この[白|しろ]いノートは^だれの^ですか。B：[先生|せんせい]（　　）です。","options":["と","の","も"],"answer":2,"why":["先生とです would mean \"with the teacher\". A asked whose notebook it is.","A asks だれの, \"whose\". 先生のです answers it: it is the teacher's.","先生もです would mean \"the teacher too\". It does not say whose the notebook is."],"unit":1,"day":6,"step":"compare"},"n5u01d6.d1":{"id":"n5u01d6.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[今週|こんしゅう]は[休|やす]みです。^[来週|らいしゅう]^（　　）^[休|やす]みです^。","options":["も","を","と","か"],"answer":1,"why":["This week is a day off, and next week is the same, so も: \"next week too\".","を marks the thing an action is done to. 休みです is not an action.","と joins two nouns, as in 今週と来週は休みです. Here 来週 stands alone before 休みです, so と has nothing to join.","来週か休みです is not a sentence. A question か goes at the very end, after です."],"explain":null,"unit":1,"day":6,"step":"drill"},"n5u01d6.d2":{"id":"n5u01d6.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^[先週|せんしゅう]^（　　）テストはどれですか。","options":["これ","この","の","と"],"answer":3,"why":["これ stands alone and never comes before a noun. 先週これテスト is not Japanese.","この points at a thing near you. It cannot come right after 先週.","先週のテスト is \"last week's test\": の joins the two nouns.","と means \"and\". 先週とテスト would be \"last week and the test\"."],"explain":null,"unit":1,"day":6,"step":"drill"},"n5u01d6.d3":{"id":"n5u01d6.d3","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"（^ふたりでカレンダーを[見|み]ています^。）A「わあ、[毎日|まいにち]クラスがあります（　　）。」B「^ほんとうですね^。」","options":["か","を","よ","ね"],"answer":4,"why":["か asks. A can see the answer, and B replies by agreeing, not answering.","を marks the thing an action is done to. It cannot end a sentence.","よ tells news the other person does not know. B is looking at the same calendar.","Both can see the calendar, so A shares what they both see: ね. B agrees."],"explain":null,"unit":1,"day":6,"step":"drill"},"n5u01d6.d4":{"id":"n5u01d6.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^[父|ちち]は[先生|せんせい]です^。[母|はは]^も^[先生|せんせい]（　　）。","options":["を","です","じゃありません","ます"],"answer":2,"why":["を marks the thing an action is done to. The sentence would have no ending.","も says the mother is the same as the father. He is a teacher, so she is a teacher too: 先生です.","This would say she is not a teacher. That does not match も after \"father is a teacher\".","ます goes after a verb. 先生 is a noun."],"explain":null,"unit":1,"day":6,"step":"drill"},"n5u01d6.d5":{"id":"n5u01d6.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"すみません、","after":"ですか。","tiles":["この","クラスは","[何時|なんじ]","から"],"star":0,"bank":[2,0,3,1],"hint":"この is followed by a noun. Which tile is a noun?","full":"すみません、{この}クラスは[何時|なんじ]からですか。","explain":"この needs a noun right after it, and クラスは is the topic. Then 何時から asks the start time, and ですか closes the question.","unit":1,"day":6,"step":"drill"},"n5u01d6.d6":{"id":"n5u01d6.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「[午後|ごご]もクラスがありますか。」B「はい、","after":"よ。」","tiles":["[午後|ごご]は","[中山|なかやま][先生|せんせい]の","クラス","です"],"star":2,"bank":[3,1,0,2],"hint":"Start with the topic. Whose class is it?","full":"A「[午後|ごご]もクラスがありますか。」B「はい、[午後|ごご]は[中山|なかやま][先生|せんせい]{の}クラスですよ。」","explain":"午後は is the topic, so it comes first. 中山先生の tells whose class, so it sits right before クラス. です closes the sentence, and よ after it tells A something new.","unit":1,"day":6,"step":"drill"},"n5u01d6.e1":{"id":"n5u01d6.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"マリアさん（　　）　トムさんは　この　学校の　学生です。","options":["を","の","と","も"],"answer":3,"explain":"と joins two people: マリアさんとトムさん are both students here. の would make Tom \"Maria's Tom\", which makes no sense. マリアさんも　トムさんは does not work: for both you would need マリアさんも　トムさんも. を marks the thing an action is done to.","unit":1,"day":6,"step":"exam"},"n5u01d6.e2":{"id":"n5u01d6.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あしたは　休みですか。」\nB「いいえ、あしたも　クラスが　あります（　　）。」","options":["よ","を","ね","か"],"answer":1,"explain":"A did not know and asked, so B tells new information: よ. ね is for something both people already know, but A just asked. か would turn B's answer into a question, and を cannot end a sentence.","unit":1,"day":6,"step":"exam"},"n5u01d6.e3":{"id":"n5u01d6.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「これは　あなたの　かさですか。」B「いいえ、","after":"。友だちのです。」","tiles":["それは","わたしの","かさ","じゃありません"],"star":1,"bank":[2,3,0,1],"full":"A「これは　あなたの　かさですか。」B「いいえ、それは{わたしの}かさじゃありません。友だちのです。」","explain":"それは, わたしの, かさ, じゃありません. それは is the topic: the umbrella is near A, so B says それ. わたしの goes before かさ, and じゃありません comes last, after the noun.","unit":1,"day":6,"step":"exam"},"n5u01d6.k1":{"id":"n5u01d6.k1","kind":"choice","type":"表記","label":"How the exam asks it","q":"あしたの　_ごご_は　テストが　あります。","options":["午後","後午","午前","五後"],"answer":1,"explain":"ごご is 午後: 午 (noon) and 後 (after). 午前 is ごぜん, the morning. 五後 uses 五, the number five, not 午. 後午 has the two kanji the wrong way round.","unit":1,"day":6,"step":"scene"},"n5u01d6.r1":{"id":"n5u01d6.r1","kind":"choice","type":"読解・情報検索","q":"リンさんは　午前の　かいわの　クラスに　出たいです。何日に　学校へ　行きますか。","options":["十二日","十三日","十五日","十六日"],"short":["12日","13日","15日","16日"],"answer":4,"explain":"Only two lines say 午前: the 13th and the 16th. The note says the teacher is off on the 13th and there is no class, so Lin goes on the 16th.","why":["The class on the 12th is 午後, in the afternoon.","The 13th has a morning class, but the note says the teacher is off and there is no class.","The class on the 15th is 午後, in the afternoon.",""],"unit":1,"day":6,"step":"skill"},"n5u01t.1":{"id":"n5u01t.1","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"わたしの　_国_は　ブラジルです。","options":["こく","まち","しま","くに"],"answer":4,"explain":"国 on its own is くに. こく is how 国 sounds inside longer words such as 中国, never alone. まち (town) and しま (island) are other words with other kanji.","unit":1,"step":"test"},"n5u01t.2":{"id":"n5u01t.2","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"父の　_会社_は　駅の　前です。","options":["かいしゃ","がいしゃ","かいしや","かいじゃ"],"answer":1,"explain":"会社 is かいしゃ, with a small ゃ. がいしゃ adds voicing to か, かいしや has a big や, and かいじゃ adds voicing to しゃ.","unit":1,"step":"test"},"n5u01t.3":{"id":"n5u01t.3","kind":"choice","type":"表記","label":"Kanji spelling","q":"_でんしゃ_で　学校へ　行きます。","options":["雨車","電東","雨東","電車"],"answer":4,"explain":"でんしゃ is 電車: 電 (electricity) with 車 (car). 雨 looks like the top of 電 but is あめ (rain), and 東 looks like 車 but is ひがし (east). Only 電車 is a word.","unit":1,"step":"test"},"n5u01t.4":{"id":"n5u01t.4","kind":"choice","type":"表記","label":"Kanji spelling","q":"_ひがしぐち_は　あちらです。","options":["東口","車口","東日","車日"],"answer":1,"explain":"ひがしぐち is 東口: 東 (east) and 口 (mouth, opening). 車 looks like 東 but is くるま, and 日 looks like 口 but is ひ or にち. Only 東口 is a word.","unit":1,"step":"test"},"n5u01t.5":{"id":"n5u01t.5","kind":"choice","type":"文脈規定","label":"Word in context","q":"あしたは　学校が　（　　）です。","options":["休み","名前","入口","電話"],"answer":1,"explain":"学校が休みです means there is no school tomorrow. A school cannot be a name (名前), an entrance (入口) or a telephone (電話).","unit":1,"step":"test"},"n5u01t.6":{"id":"n5u01t.6","kind":"choice","type":"文脈規定","label":"Word in context","q":"駅の　前の　（　　）で　じしょを　買いました。","options":["国","本や","電話","名前"],"answer":2,"explain":"で here marks the place where you buy, and a bookshop (本や) sells dictionaries. A telephone (電話) and a name (名前) are not places, and a country (国) is not a shop in front of a station.","unit":1,"step":"test"},"n5u01t.7":{"id":"n5u01t.7","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"_この　本は　ふるいです_。","options":["この　本は　あたらしいです。","この　本は　あたらしくないです。","この　本は　大きくないです。","この　本は　たかくないです。"],"answer":2,"explain":"ふるい (old) means the same as あたらしくない (not new). 大きくない is about size and たかくない about price, and あたらしい says the opposite.","unit":1,"step":"test"},"n5u01t.8":{"id":"n5u01t.8","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"ここは　_入口_です。","options":["ここから　出ます。","ここで　休みます。","ここで　買います。","ここから　入ります。"],"answer":4,"explain":"An entrance (入口) is where you go in, so ここから入ります says the same thing. ここから出ます describes an exit (出口), and resting (休みます) or buying (買います) is not what an entrance is for.","unit":1,"step":"test"},"n5u01t.9":{"id":"n5u01t.9","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「それは　日本の　お金ですか。」B「いいえ、日本の　お金（　　）。中国の　お金です。」","options":["ですよ","じゃ　ありません","です","ですか"],"answer":2,"explain":"B says いいえ and then names Chinese money, so B says it is not Japanese money: じゃありません. です and ですよ would say it is Japanese money, which clashes with いいえ, and ですか would ask a question back instead of answering.","unit":1,"step":"test"},"n5u01t.10":{"id":"n5u01t.10","kind":"choice","type":"文の文法1","label":"Choose the form","q":"父は　先生です。母（　　）　かいしゃいんです。","options":["の","を","は","も"],"answer":3,"explain":"The mother has a different job from the father, so she is a new topic with は. も (also) would need her to have the same job as the father, but he is a teacher. 母のかいしゃいん would mean an employee belonging to the mother, and を does not go before です.","unit":1,"step":"test"},"n5u01t.11":{"id":"n5u01t.11","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あの　男の　人は　だれです（　　）。」B「わたしの　父です。」","options":["か","よ","ね","を"],"answer":1,"explain":"だれ (who) makes this a question, and a polite question ends in か. よ tells the listener something and ね asks them to agree; neither can end a question with だれ. を cannot end a sentence.","unit":1,"step":"test"},"n5u01t.12":{"id":"n5u01t.12","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「すみません。（　　）は　いくらですか。」B「それは　千円です。」","options":["あれ","どれ","これ","この"],"answer":3,"explain":"B answers with それ (the thing near you), so the thing is near A: A says これ. この must have a noun after it, so この cannot stand before は. With あれ, B would also say あれ. どれ is a question word, and a question word does not come before は.","unit":1,"step":"test"},"n5u01t.13":{"id":"n5u01t.13","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「それは　何の　本ですか。」B「日本語（　　）　本です。」","options":["の","と","も","を"],"answer":1,"explain":"何の本 asks what kind of book, and B answers 日本語の本: the の links 日本語 to 本 to say what the book is about. 日本語と本 would mean two things, Japanese and a book. も and を cannot join two nouns like this.","unit":1,"step":"test"},"n5u01t.14":{"id":"n5u01t.14","kind":"choice","type":"文の文法1","label":"Choose the form","q":"かばんの　中に　ノート（　　）　ペンが　あります。","options":["を","と","の","も"],"answer":2,"explain":"The bag has two things in it, a notebook and a pen, and と joins them. ノートのペン would mean a pen that belongs to the notebook, which makes no sense. ノートもペンが is not a way to list two things (that would be ノートもペンも), and を cannot join two nouns.","unit":1,"step":"test"},"n5u01t.15":{"id":"n5u01t.15","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"（ふたりで　いっしょに　花を　見て　います。）A「きれいな　花です（　　）。」B「ええ、とても　きれいです。」","options":["ね","よ","か","を"],"answer":1,"explain":"Both people are looking at the same flowers, so A shares the feeling and asks B to agree with ね, and B agrees. よ would tell B something new, but B can see the flowers too. か would ask about something A can see, and を cannot end a sentence.","unit":1,"step":"test"},"n5u01t.16":{"id":"n5u01t.16","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「それは　何ですか。」B「","after":"よ。」","tiles":["これは","日本の","おかし","です"],"star":2,"bank":[2,0,3,1],"full":"A「それは　何ですか。」B「これは　日本の　{おかし}ですよ。」","explain":"これは, 日本の, おかし, です. A says それ, so B, who holds it, says これは. 日本の describes おかし, so it comes just before it, and です goes before よ at the end.","unit":1,"step":"test"},"n5u01t.17":{"id":"n5u01t.17","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「リンさんは　学生です。","after":"か。」B「はい、そうです。」","tiles":["あの","人","も","学生です"],"star":2,"bank":[1,3,2,0],"full":"A「リンさんは　学生です。あの　人{も}　学生ですか。」B「はい、そうです。」","explain":"あの, 人, も, 学生です. あの needs the noun 人 right after it. も follows 人 because that person is a student too, like リンさん. 学生です goes before か.","unit":1,"step":"test"},"n5u01t.18":{"id":"n5u01t.18","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「リンさんは　日本人ですか。」B「いいえ、","after":"です。」","tiles":["リンさんは","中国","の","人"],"star":2,"bank":[3,1,0,2],"full":"A「リンさんは　日本人ですか。」B「いいえ、リンさんは　中国{の}　人です。」","explain":"リンさんは, 中国, の, 人. リンさんは is the topic and comes first. の joins 中国 and 人 (a person of China), so it sits between them, and 人 goes right before です.","unit":1,"step":"test"},"n5u01t.19":{"id":"n5u01t.19","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","q":"これは　何の　おかしですか。","options":["お母さんの　国の　おかし","りんごの　おかし","バナナの　おかし","マリアさんの　国の　おかし"],"answer":3,"passage":"マリアさん\nきのうは　ありがとう　ございました。これは　わたしの　国の　おかしです。りんごの　おかしじゃ　ありません。バナナの　おかしです。とても　あまいですよ。二つ　あります。一つは　マリアさんの、一つは　お母さんのです。\nキム","short":["お母さんの国","りんご","バナナ","マリアさんの国"],"explain":"キム writes バナナのおかしです right after saying it is not an apple sweet (りんごのおかしじゃありません). It is from キム's country (わたしの国), not マリア's, and お母さん is マリア's mother, who gets one of the two sweets.","unit":1,"step":"test"},"n5u01t.20":{"id":"n5u01t.20","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","q":"ただしい　ものは　どれですか。","options":["おかしは　あまく　ないです。","おかしは　一つです。","おかしは　キムさんの　国の　おかしです。","おかしは　マリアさんの　国の　おかしです。"],"answer":3,"passage":"マリアさん\nきのうは　ありがとう　ございました。これは　わたしの　国の　おかしです。りんごの　おかしじゃ　ありません。バナナの　おかしです。とても　あまいですよ。二つ　あります。一つは　マリアさんの、一つは　お母さんのです。\nキム","short":["あまくない","一つ","キムさんの国","マリアさんの国"],"explain":"わたしの国のおかし is written by キム, so it is a sweet from キム's country. There are two (二つあります), not one. It is not from マリア's country, and キム says it is very sweet (とてもあまいですよ).","unit":1,"step":"test"},"n5u01t.21":{"id":"n5u01t.21","kind":"choice","type":"読解・情報検索","label":"Finding information","q":"リンさんは　日本語の　本が　ほしいです。何かいへ　行きますか。","options":["一かい","三かい","四かい","五かい"],"answer":4,"passage":"山川デパート\n五かい　本や・きっさてん\n四かい　子どもの　ふく・おもちゃ\n三かい　男の　人の　ふく\n二かい　女の　人の　ふく・かばん\n一かい　花や・くつ\nちか一かい　魚・やさい・おかし\n出口は　一かいの　東口と　西口です。","short":["一かい","三かい","四かい","五かい"],"explain":"Books are sold at the bookshop (本や), on 五かい. 一かい has flowers and shoes, 三かい has men's clothes, and 四かい has children's clothes and toys.","unit":1,"step":"test"},"n5u01t.22":{"id":"n5u01t.22","kind":"choice","type":"読解・情報検索","label":"Finding information","q":"キムさんは　お母さんに　花と　かばんを　買います。何かいと　何かいへ　行きますか。","options":["一かいと　二かい","一かいと　三かい","二かいと　五かい","二かいと　ちか一かい"],"answer":1,"passage":"山川デパート\n五かい　本や・きっさてん\n四かい　子どもの　ふく・おもちゃ\n三かい　男の　人の　ふく\n二かい　女の　人の　ふく・かばん\n一かい　花や・くつ\nちか一かい　魚・やさい・おかし\n出口は　一かいの　東口と　西口です。","short":["一と二","一と三","二と五","二とちか一"],"explain":"Flowers are at the florist (花や) on 一かい, and bags are on 二かい. 三かい has only men's clothes, 五かい has the bookshop and a café, and ちか一かい has food, not flowers.","unit":1,"step":"test"},"n5u01t.23":{"id":"n5u01t.23","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","q":"ただしい　ものは　どれですか。","options":["あさっての　クラスは　三かいです。","あしたは　クラスが　あります。","あしたは　中山先生が　学校に　来ます。","あさっては　クラスが　あります。"],"answer":4,"passage":"リンさん\nあしたの　日本語の　クラスは　休みです。中山先生は　あした　学校に　来ません。あさっての　クラスは　あります。でも、きょうしつは　三かいの　きょうしつじゃ　ありません。二かいの　きょうしつです。\n山川","short":["三かいでクラス","あしたクラスがある","先生があした来る","あさってクラスがある"],"explain":"The note says あさってのクラスはあります. Tomorrow the class is off (休みです) because 中山先生 is not coming (来ません), and the room is not on 三かい but on 二かい.","unit":1,"step":"test"},"n5u01t.24":{"id":"n5u01t.24","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","q":"あさって、リンさんは　どこへ　行きますか。","options":["三かいの　きょうしつ","二かいの　きょうしつ","中山先生の　うち","どこへも　行きません"],"answer":2,"passage":"リンさん\nあしたの　日本語の　クラスは　休みです。中山先生は　あした　学校に　来ません。あさっての　クラスは　あります。でも、きょうしつは　三かいの　きょうしつじゃ　ありません。二かいの　きょうしつです。\n山川","short":["三かい","二かい","先生のうち","行かない"],"explain":"There is a class the day after tomorrow, and it is in 二かいのきょうしつ. The note says it is not the room on 三かい (三かいのきょうしつじゃありません). 中山先生's home is never mentioned, and リン does go, because the class is on.","unit":1,"step":"test"},"n5u02d1.c1":{"id":"n5u02d1.c1","kind":"choice","type":"文の文法1","label":"ともだちをしょうかいする","q":"[先生|せんせい]、（　　）は^[友|とも]だちのリンさん^です。","options":["これ","こちら","ここ"],"answer":2,"why":["これ points at a thing. Lin is a person.","こちら points politely at a person in front of you. You are talking to your teacher, so the polite word fits.","ここ points at a place. Lin is a person, not a place."],"unit":2,"day":1,"step":"compare"},"n5u02d1.d1":{"id":"n5u02d1.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「すみません。[駅|えき]は（　　）ですか。」\nB「^あそこです^。」","options":["だれ","いつ","どこ","なん"],"answer":3,"why":["だれ asks who. A station is not a person.","いつ asks when. B's answer is a place, not a time.","B answers with a place, あそこ, so A asked where the station is.","なん asks what something is. B's answer is a place."],"explain":null,"unit":2,"day":1,"step":"drill"},"n5u02d1.d2":{"id":"n5u02d1.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「すみません、[学校|がっこう]は（　　）ですか。」\nB「^あの[白|しろ]いたてもの^です。」","options":["そこ","あそこ","どこ","ここ"],"answer":3,"why":["そこ would say the school is near B. A is asking, and B answers with a place.","あそこ is how B answers (あの白いたてもの). A does not know yet, so A cannot say it.","A does not know where the school is, so A asks with どこ, and B answers with あの白いたてもの.","ここ would say the school is right here, but A does not know where it is and asks."],"explain":null,"unit":2,"day":1,"step":"drill"},"n5u02d1.d3":{"id":"n5u02d1.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[店|みせ]の[人|ひと]「エレベーターは（　　）です。^どうぞ^。」","options":["だれ","あちら","あの","どちら"],"answer":2,"why":["だれ asks who. An elevator is not a person, and this is not a question.","Shop staff speak politely, and あちら is the polite way to say あそこ, over there.","あの needs a noun right after it, as in あのドア. Here です follows.","どちら asks where. The sentence ends in です, not ですか: she is telling, not asking."],"explain":null,"unit":2,"day":1,"step":"drill"},"n5u02d1.d4":{"id":"n5u02d1.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「^お[国|くに]^は（　　）ですか。」\nB「ブラジルです。」","options":["いつ","どちら","どれ","だれ"],"answer":2,"why":["いつ asks when. Brazil is not a time.","どちら is the polite way to ask where. お国はどちらですか is how you politely ask someone's country.","どれ asks which one of several things you can see or point at. A country is not in front of you.","だれ asks who. A country is not a person."],"explain":null,"unit":2,"day":1,"step":"drill"},"n5u02d1.d5":{"id":"n5u02d1.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「すみません。","after":"か。」\nB「あそこです。」","tiles":["[山川|やまかわ]","[大学|だいがく]は","どこ","です"],"star":2,"bank":[2,0,3,1],"hint":"The place you ask about comes first, with は. どこ sits right before です.","full":"A「すみません。[山川|やまかわ][大学|だいがく]は{どこ}ですか。」\nB「あそこです。」","explain":"山川 is the name of the university, so it sits right before 大学は, the topic. どこ asks where, and ですか closes the question.","unit":2,"day":1,"step":"drill"},"n5u02d1.d6":{"id":"n5u02d1.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[先生|せんせい]、","after":"です。","tiles":["こちらは","わたしの","[友|とも]だちの","リンさん"],"star":2,"bank":[2,3,0,1],"hint":"Start with the polite word for the person you introduce. Then say who she is.","full":"[先生|せんせい]、{こちら}はわたしの[友|とも]だちのリンさんです。","explain":"こちらは is the topic: the person you are introducing. わたしの goes with 友だち, and 友だちの tells who Lin is, so it sits right before リンさん.","unit":2,"day":1,"step":"drill"},"n5u02d1.e1":{"id":"n5u02d1.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「すみません。トイレは　どこですか。」\nB「（　　）です。あの　白い　ドアです。」","options":["どれ","あの","あそこ","これ"],"answer":3,"explain":"A asks where, and B points at あの白いドア, far from both of them, so あそこ. これ points at a thing near the speaker, どれ asks a question, and あの needs a noun right after it.","unit":2,"day":1,"step":"exam"},"n5u02d1.e2":{"id":"n5u02d1.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「山川さんの　会社は　（　　）ですか。」\nB「駅の　前です。」","options":["いくら","だれ","どちら","いつ"],"answer":3,"explain":"B answers with a place, 駅の前, so A asked where, politely: どちら. だれ asks who, いつ asks when, and いくら asks how much.","unit":2,"day":1,"step":"exam"},"n5u02d1.e3":{"id":"n5u02d1.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"すみません。","after":"か。","tiles":["山川","駅は","こちら","です"],"star":2,"bank":[3,2,0,1],"full":"すみません。山川駅は{こちら}ですか。","explain":"山川, 駅は, こちら, です. 山川 is the name of the station, so it comes right before 駅は, the topic. こちら then says \"this way\", and ですか asks.","unit":2,"day":1,"step":"exam"},"n5u02d1.k1":{"id":"n5u02d1.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_出口_は　あそこです。","options":["でくち","てぐち","でぐち","だぐち"],"answer":3,"explain":"出口 is でぐち: 出 is で, and in this word 口 is read ぐち, as in 北口 (きたぐち). でくち keeps く without the dakuten, てぐち drops the dakuten on で, and だぐち has the wrong vowel.","unit":2,"day":1,"step":"scene"},"n5u02d1.r1":{"id":"n5u02d1.r1","kind":"choice","type":"課題理解","q":"男の人は　はじめに　どこへ　行きますか。","script":["ナレーター：日本語学校で、女の人と男の人が話しています。男の人は、はじめに、どこへ行きますか。","男：すみません。山川先生のへやはどこですか。","女：山川先生のへやは、あそこですよ。でも、山川先生は、いま、しょくどうです。","男：そうですか。しょくどうはどこですか。","女：一かいです。あ、でも、そのまえに、こちらのうけつけで名前を書いてください。","男：はい。うけつけは、こちらですね。","女：ええ、そうです。","ナレーター：男の人は、はじめに、どこへ行きますか。"],"options":["しょくどう","うけつけ","きょうしつ","先生の　へや"],"printed":true,"short":["しょくどう","うけつけ","きょうしつ","先生の へや"],"answer":2,"why":["The teacher is in the cafeteria, but the woman says そのまえに: before that, write your name at the reception desk.","そのまえに means \"before that\". He writes his name at the reception desk first, and checks with うけつけは、こちらですね.","Nobody talks about a classroom.","The man asks about the teacher's room, but the teacher is not there now. He is in the cafeteria."],"explain":null,"unit":2,"day":1,"step":"skill","clip":"l_n5u2d1"},"n5u02d2.c1":{"id":"n5u02d2.c1","kind":"choice","type":"文の文法1","label":"こうえんで","q":"こうえんに[子|こ]どもが（　　）。","options":["あります","います","です"],"answer":2,"why":["あります is for things and plants. Children are people.","Children are people, so they take います.","です says what something is, as in これは本です. 子どもがです is not a sentence."],"unit":2,"day":2,"step":"compare"},"n5u02d2.d1":{"id":"n5u02d2.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：^[水|みず]^がありますか。B：はい、（　　）。","options":["います","です","ありません","あります"],"answer":4,"why":["います is for people and animals. Water is a thing.","はい、です is not an answer. The answer repeats the verb of the question.","ありません means \"there isn't\". It clashes with はい.","Water is a thing, so it takes あります. The yes answer repeats the verb: はい、あります."],"explain":null,"unit":2,"day":2,"step":"drill"},"n5u02d2.d2":{"id":"n5u02d2.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あそこに^いぬ^が（　　）。","options":["います","あります","ありません","じゃありません"],"answer":1,"why":["A dog is an animal, so it takes います.","あります is for things and plants, not for a dog.","ありません is the no form of あります, so it is also wrong for a dog.","じゃありません means \"it is not\". It does not follow が."],"unit":2,"day":2,"step":"drill"},"n5u02d2.d3":{"id":"n5u02d2.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：^ペン^がありますか。B：いいえ、（　　）。","options":["じゃありません","あります","ありません","いません"],"answer":3,"why":["じゃありません means \"it is not\" and needs a noun before it. Here B says the pen is not there.","あります means \"there is\". It clashes with いいえ.","A pen is a thing, so the no answer is ありません.","いません is for people and animals. A pen is a thing."],"explain":null,"unit":2,"day":2,"step":"drill"},"n5u02d2.d4":{"id":"n5u02d2.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：[川|かわ]に^[魚|さかな]^がいますか。B：いいえ、（　　）。","options":["じゃありません","います","いません","ありません"],"answer":3,"why":["じゃありません means \"it is not\" and needs a noun before it. Here B says there are no fish.","います means \"there is\". It clashes with いいえ.","Fish are animals, so the no answer is いません.","ありません is for things and plants. Fish are animals."],"explain":null,"unit":2,"day":2,"step":"drill"},"n5u02d2.d5":{"id":"n5u02d2.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A：その[店|みせ]に[日本語|にほんご]の","after":"。B：はい、あります。","tiles":["[本|ほん]","が","あります","か"],"star":2,"bank":[3,1,0,2],"hint":"日本語の needs a noun right after it. か always comes last.","full":"A：その[店|みせ]に[日本語|にほんご]の[本|ほん]が{あります}か。B：はい、あります。","explain":"日本語の describes 本, so 本 comes first. が follows the thing, then あります, and か at the end makes the question.","unit":2,"day":2,"step":"drill"},"n5u02d2.d6":{"id":"n5u02d2.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あそこに","after":"。[名前|なまえ]はケンくんです。","tiles":["[男|おとこ]の","[子|こ]","が","います"],"star":2,"bank":[2,3,1,0],"hint":"男の needs a noun right after it. Which verb goes with a child?","full":"あそこに[男|おとこ]の[子|こ]が{います}。[名前|なまえ]はケンくんです。","explain":"男の describes 子, so they go together first. が follows the person, and a boy takes います.","unit":2,"day":2,"step":"drill"},"n5u02d2.e1":{"id":"n5u02d2.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あそこに　大きい　木が（　　）。","options":["でした","あります","います","です"],"answer":2,"explain":"A tree is a plant, so it takes あります. います is for people and animals. です and でした say what something is, and cannot follow が here.","unit":2,"day":2,"step":"exam"},"n5u02d2.e2":{"id":"n5u02d2.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：きょうしつに　だれか　いますか。B：はい、先生が（　　）。","options":["あります","います","いません","です"],"answer":2,"explain":"A teacher is a person, so います. あります is for things and plants. いません clashes with はい, and 先生がです is not a sentence.","unit":2,"day":2,"step":"exam"},"n5u02d2.e3":{"id":"n5u02d2.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あの　川には","after":"よ。","tiles":["小さい","魚","が","います"],"star":1,"bank":[3,0,2,1],"full":"あの　川には　小さい　{魚}が　いますよ。","explain":"小さい, 魚, が, います. 小さい describes 魚, so it sits right before it. が follows the fish, and fish take います.","unit":2,"day":2,"step":"exam"},"n5u02d2.k1":{"id":"n5u02d2.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"こうえんに　きれいな　_花_が　たくさん　あります。","options":["き","そら","はな","くさ"],"answer":3,"explain":"花 is read はな, \"flower\". くさ means grass, a different word, き (tree) is 木, and そら (sky) is 空.","unit":2,"day":2,"step":"scene"},"n5u02d2.r1":{"id":"n5u02d2.r1","kind":"choice","type":"読解・内容理解（短文）","q":"こうえんに　ついて、ただしい　ものは　どれですか。","options":["川に　魚は　いません。","花が　たくさん　あります。","白い　ねこが　います。","子どもが　たくさん　います。"],"short":["魚はいない","花がたくさん","白いねこがいる","子どもがたくさん"],"answer":3,"explain":"Maria writes いつも白いねこがいます: there is always a white cat in the park.","why":["Maria writes 川には魚がいます: there are fish in the river.","Maria writes 花はあまりありません: there are not many flowers. The trees are what there are a lot of.","","Maria writes 子どもはあまりいません: there are not many children."],"unit":2,"day":2,"step":"skill"},"n5u02d3.c1":{"id":"n5u02d3.c1","kind":"choice","type":"文の文法1","label":"スーパーで","q":"すみません、[二|に]かいに[何|なに]（　　）ありますか。","options":["に","が","は"],"answer":2,"why":["に already marks the place (二かい). 何 is the thing, not a place.","The place comes first with に, and the thing you ask about takes が: 何がありますか.","A question word like 何 never takes は."],"explain":null,"unit":2,"day":3,"step":"compare"},"n5u02d3.d1":{"id":"n5u02d3.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^あそこに^いぬ（　　）いますよ。","options":["が","を","で","へ"],"answer":1,"why":["The place comes first with に, and the dog is new information, so が.","を marks what you do something to. いる does not take を.","で marks where you do something. Here いぬ is who is there, not a place.","へ marks where you go. いぬ is not a place you go to."],"unit":2,"day":3,"step":"drill"},"n5u02d3.d2":{"id":"n5u02d3.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[本|ほん]やは^[二|に]かい^（　　）あります。","options":["へ","に","を","が"],"answer":2,"why":["へ marks where you go. あります does not take へ.","二かい is where the bookshop is, and the place before あります takes に.","を marks what you do something to. あります does not take を.","The bookshop already has は. 二かいが would make the second floor the thing that exists."],"explain":null,"unit":2,"day":3,"step":"drill"},"n5u02d3.d3":{"id":"n5u02d3.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：お[父|とう]さんは（　　）いますか。　B：^[入口|いりぐち]にいます^。","options":["だれが","どこに","どこが","どこを"],"answer":2,"why":["A already named the person (お父さんは). B answers with a place, not a person.","B answers with a place (入口に), so A asked where: どこにいますか.","どこ is a place, so it takes に here, not が.","いる does not take を."],"explain":null,"unit":2,"day":3,"step":"drill"},"n5u02d3.d4":{"id":"n5u02d3.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：[一|いっ]かいに^[何|なに]が^ありますか。　B：（　　）。","options":["[水|みず]と[花|はな]があります","[水|みず]と[花|はな]がいます","[水|みず]と[花|はな]はどこですか","[水|みず]と[花|はな]にあります"],"answer":1,"why":["A asks 何がありますか, so B names the things with が and uses あります.","Water and flowers are things, so あります, not います.","B must answer A's question, not ask a new one.","に marks the place. Water and flowers are the things that are there, so they take が."],"unit":2,"day":3,"step":"drill"},"n5u02d3.d5":{"id":"n5u02d3.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[店|みせ]の[入口|いりぐち]に","after":"よ。","tiles":["[安|やす]い","[花|はな]","が","あります"],"star":2,"bank":[2,0,3,1],"hint":"The place (入口に) is already first. What is there, and which word marks it?","full":"[店|みせ]の[入口|いりぐち]に[安|やす]い[花|はな]{があります}よ。","explain":"安い goes right before 花. The new thing takes が, and あります comes last: 店の入口に安い花がありますよ, \"There are cheap flowers at the shop entrance.\"","unit":2,"day":3,"step":"drill"},"n5u02d3.d6":{"id":"n5u02d3.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A：すみません、[花|はな]はどこですか。　B：[花|はな]","after":"よ。","tiles":["は","[二|に]かい","に","あります"],"star":2,"bank":[1,3,0,2],"hint":"A already asked about the flowers, so they take は. Which tile marks the place?","full":"A：すみません、[花|はな]はどこですか。　B：[花|はな]{は}[二|に]かい{にあります}よ。","explain":"は goes right after 花 because A already knows about the flowers. Then the place 二かい with に, and あります last: 花は二かいにありますよ.","unit":2,"day":3,"step":"drill"},"n5u02d3.e1":{"id":"n5u02d3.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：きょうしつに　だれが　いますか。　B：先生（　　）　います。","options":["で","が","を","に"],"answer":2,"explain":"A asks だれがいますか, so B names the new person with が. いる does not take を, に would make 先生 a place, and で marks where you do something.","unit":2,"day":3,"step":"exam"},"n5u02d3.e2":{"id":"n5u02d3.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"母は　いま　二かい（　　）。","options":["が　います","で　います","に　あります","に　います"],"answer":4,"explain":"母 is a person, so います, and the place where she is takes に. あります is for things, 二かいが would make the floor the one who is there, and で is for where you do something.","unit":2,"day":3,"step":"exam"},"n5u02d3.e3":{"id":"n5u02d3.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしの　うちの　ちかくに","after":"。","tiles":["大きい","店","が","あります"],"star":2,"bank":[3,1,2,0],"full":"わたしの　うちの　ちかくに　大きい　店{が}　あります。","explain":"大きい, 店, が, あります. The place (ちかくに) comes first, 大きい goes right before 店, the new thing takes が, and あります comes last.","unit":2,"day":3,"step":"exam"},"n5u02d3.k1":{"id":"n5u02d3.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"店の　_入口_に　花が　あります。","options":["いりぐち","にゅうぐち","いれくち","いりくち"],"answer":1,"explain":"入口 is read いりぐち, \"entrance\": 入 is いり and 口 becomes ぐち, as in 出口 (でぐち). いりくち misses the change to ぐ, and にゅうぐち and いれくち are not words.","unit":2,"day":3,"step":"scene"},"n5u02d3.r1":{"id":"n5u02d3.r1","kind":"choice","type":"発話表現","q":"店で　水を　買いたいです。店の　人に　何と　いいますか。","script":["ナレーター：店で　水を　買いたいです。店の　人に　何と　いいますか。","ナレーター：1","男：すみません、水は　どこに　いますか。","ナレーター：2","男：すみません、あそこに　水が　ありますよ。","ナレーター：3","男：すみません、水は　どこに　ありますか。"],"options":["すみません、水は　どこに　いますか。","すみません、あそこに　水が　ありますよ。","すみません、水は　どこに　ありますか。"],"printed":false,"short":["水は　どこに　いますか","あそこに　水が　ありますよ","水は　どこに　ありますか"],"answer":3,"why":["Water is a thing, so the question needs あります, not います.","This tells the assistant where the water is. The man does not know, so he needs to ask.",""],"unit":2,"day":3,"step":"skill","clip":"l_n5u2d3"},"n5u02d4.c1":{"id":"n5u02d4.c1","kind":"choice","type":"文の文法1","label":"はこの中","q":"A：はこの[中|なか]に[何|なに]がありますか。　B：ペン（　　）けしゴムです。^それだけです^。","options":["と","の","や"],"answer":1,"why":["B names everything in the box, so と: a pen and an eraser, nothing else.","ペンのけしゴム would be \"the pen's eraser\". B is listing two things.","や hints that there are other things too, but B says それだけです: that is all."],"explain":null,"unit":2,"day":4,"step":"compare"},"n5u02d4.d1":{"id":"n5u02d4.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"つくえ（　　）^[上|うえ]^に[本|ほん]があります。","options":["と","が","の","に"],"answer":3,"why":["つくえと上 would mean \"the desk and the top\", two separate things.","が marks what is there. Here 本が already does that.","The thing, then の, then the position word: つくえの上, on the desk.","に comes after the position word (上に), not between つくえ and 上."],"explain":null,"unit":2,"day":4,"step":"drill"},"n5u02d4.d2":{"id":"n5u02d4.d2","kind":"choice","type":"文の文法1","label":"Choose the word","q":"わたしは^[山川|やまかわ]さんの[右|みぎ]^にいます。[山川|やまかわ]さんはわたしの（　　）にいます。","options":["[前|まえ]","[上|うえ]","[右|みぎ]","[左|ひだり]"],"answer":4,"why":["We are side by side, so she is not in front of me.","A person standing next to me is not above me.","Two people side by side cannot both be on the other's right.","If I am on Ms. Yamakawa's right, she is on my left."],"explain":null,"unit":2,"day":4,"step":"drill"},"n5u02d4.d3":{"id":"n5u02d4.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"かばんの[中|なか]に[本|ほん]（　　）ノート^など^があります。","options":["や","の","も","を"],"answer":1,"why":["や joins the two nouns, and など says there are other things too.","本のノート would be \"a book's notebook\", which makes no sense.","本もノートなど does not join the two things. も means \"too\".","を marks the thing you act on with a verb. あります does not take を."],"unit":2,"day":4,"step":"drill"},"n5u02d4.d4":{"id":"n5u02d4.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[店|みせ]には^いろいろなもの^があります。パン（　　）ぎゅうにゅうなどです。","options":["を","の","や","で"],"answer":3,"why":["を needs a verb that acts on something. です does not take を.","パンのぎゅうにゅう would be \"bread's milk\", which makes no sense.","The shop has many things, so や gives two examples and など says there are more.","で does not join two nouns in a list."],"explain":null,"unit":2,"day":4,"step":"drill"},"n5u02d4.d5":{"id":"n5u02d4.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしのかばんは","after":"あります。","tiles":["[中山|なかやま]さんの","いすの","[下|した]","に"],"star":2,"bank":[2,0,3,1],"hint":"Whose chair is it? Then the chair, then the position word, then に.","full":"わたしのかばんは[中山|なかやま]さんのいす{の[下|した]}にあります。","explain":"中山さんのいす is Mr. Nakayama's chair. いすの下 is under the chair, and に comes after the position word: under Mr. Nakayama's chair.","unit":2,"day":4,"step":"drill"},"n5u02d4.d6":{"id":"n5u02d4.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"れいぞうこの[中|なか]に[魚|さかな]","after":"あります。","tiles":["や","くだもの","など","が"],"star":2,"bank":[3,2,0,1],"hint":"や goes between two nouns. など comes after the last noun, and が after など.","full":"れいぞうこの[中|なか]に[魚|さかな]{や}くだものなどがあります。","explain":"魚やくだもの joins the two foods, など says there are more, and が marks what is there before あります.","unit":2,"day":4,"step":"drill"},"n5u02d4.e1":{"id":"n5u02d4.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ぎんこうは　えきの　前（　　）あります。","options":["で","に","が","を"],"answer":2,"explain":"The place where something is takes に: えきの前に あります. を needs an action verb, で marks where an action happens, and ぎんこうは already says what is there, so が does not fit.","unit":2,"day":4,"step":"exam"},"n5u02d4.e2":{"id":"n5u02d4.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"テーブルの　上に　りんご（　　）バナナなどが　あります。","options":["へ","の","や","を"],"answer":3,"explain":"や joins two nouns, and など says there is more: apples, bananas and so on. りんごのバナナ makes no sense, を needs an action verb, and へ shows a direction.","unit":2,"day":4,"step":"exam"},"n5u02d4.e3":{"id":"n5u02d4.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"かぎは　テレビの　","after":"　あります。","tiles":["前の","テーブルの","上","に"],"star":1,"bank":[2,3,1,0],"full":"かぎは　テレビの　前の　{テーブルの}　上に　あります。","explain":"前の, テーブルの, 上, に: the key is on the table in front of the TV. テレビの前の テーブル is the table in front of the TV, and テーブルの上に says it is on top of that table.","unit":2,"day":4,"step":"exam"},"n5u02d4.k1":{"id":"n5u02d4.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"まどの　_外_に　大きい　木が　あります。","options":["そと","うち","しろ","なか"],"answer":1,"explain":"外 is そと, outside. なか is 中 (inside), うち means inside or home and is not read from 外 here, and しろ means white.","unit":2,"day":4,"step":"scene"},"n5u02d4.r1":{"id":"n5u02d4.r1","kind":"choice","type":"読解・内容理解（短文）","q":"かぎは　どこに　ありますか。","options":["本だなの　上の　はこの　中","れいぞうこの　中","つくえの　上","本だなの　中"],"short":["本だなの上のはこの中","れいぞうこの中","つくえの上","本だなの中"],"answer":4,"explain":"The note says the key is not on the desk (ありません). The next sentence says it is in the bookshelf next to the desk: 本だなの中.","why":["The box on the bookshelf has pens, notebooks and so on, not the key.","The fridge has bread and fruit, not the key.","The note says つくえの上に ありません: it is not on the desk.",""],"unit":2,"day":4,"step":"skill"},"n5u02d5.c1":{"id":"n5u02d5.c1","kind":"choice","type":"文の文法1","label":"くだものやで","q":"A「このりんごは（　　）ですか。」B「^[一|ひと]つ[百円|ひゃくえん]^です。」","options":["[何時|なんじ]ごろ","いくつ","いくら"],"answer":3,"why":["何時ごろ asks about a time. B answers with a price.","いくつ asks how many. B answers with a price, 百円.","B answers with a price, so A asked how much with いくら."],"explain":null,"unit":2,"day":5,"step":"compare"},"n5u02d5.d1":{"id":"n5u02d5.d1","kind":"choice","type":"文の文法1","label":"Choose the word","q":"（[店|みせ]で）A「すみません、このパンは（　　）ですか。」B「^[百五十円|ひゃくごじゅうえん]^です。」","options":["どこ","いくら","いくつ","[何時|なんじ]"],"answer":2,"why":["どこ asks where. B answers with a price.","B answers with a price, so A asks how much with いくら.","いくつ asks how many or how old. B answers with a price.","何時 asks what time it is. B answers with a price."],"explain":null,"unit":2,"day":5,"step":"drill"},"n5u02d5.d2":{"id":"n5u02d5.d2","kind":"choice","type":"文の文法1","label":"Choose the word","q":"A「いすは（　　）ありますか。」B「^[四|よっ]つ^あります。」","options":["いくつ","[何|なに]","だれ","いくら"],"answer":1,"why":["B counts the chairs with 四つ, so A asks how many with いくつ.","何 asks what. It cannot ask how many, and B gives a number.","だれ asks who. Chairs are not people, and B gives a number.","いくら asks about money. B counts the chairs."],"explain":null,"unit":2,"day":5,"step":"drill"},"n5u02d5.d3":{"id":"n5u02d5.d3","kind":"choice","type":"文の文法1","label":"Choose the word","q":"この[本|ほん]は^[千円|せんえん]^（　　）でした。","options":["ぐらい","いくつ","ごろ","いくら"],"answer":1,"why":["千円 is an amount of money, so \"about\" is ぐらい.","いくつ asks how many. This sentence does not ask anything.","ごろ is for a point in time, like a clock time. 千円 is an amount of money.","いくら asks a question. This sentence tells a price; it does not ask one."],"explain":null,"unit":2,"day":5,"step":"drill"},"n5u02d5.d4":{"id":"n5u02d5.d4","kind":"choice","type":"文の文法1","label":"Choose the word","q":"まいあさ^[七時|しちじ]^（　　）おきます。","options":["いくつ","や","ごろ","など"],"answer":3,"why":["いくつ asks how many. This sentence tells a time; it does not ask.","や joins two nouns in a list. Nothing follows it here.","七時 is a clock time, so \"around seven\" is 七時ごろ.","など ends a list of things, as in パンやたまごなど. It does not follow a clock time here."],"explain":null,"unit":2,"day":5,"step":"drill"},"n5u02d5.d5":{"id":"n5u02d5.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「ここから[駅|えき]まで[何分|なんぷん]ぐらいかかりますか。」B「そうですね、","after":"。」","tiles":["[二十分|にじゅっぷん]","ぐらい","かかります","よ"],"star":1,"bank":[2,0,3,1],"hint":"A asks about a length of time. ぐらい comes right after the number, and よ comes last.","full":"A「ここから[駅|えき]まで[何分|なんぷん]ぐらいかかりますか。」B「そうですね、[二十分|にじゅっぷん]{ぐらい}かかりますよ。」","explain":"二十分 is a length of time, so ぐらい goes right after it. かかります follows, and よ ends the sentence because B tells A something new.","unit":2,"day":5,"step":"drill"},"n5u02d5.d6":{"id":"n5u02d5.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「","after":"。」B「[五|いつ]つあります。」","tiles":["その","りんごは","いくつ","ありますか"],"star":2,"bank":[3,2,0,1],"hint":"B answers with a number of apples. その goes before a noun, and the question word comes before ありますか.","full":"A「そのりんごは{いくつ}ありますか。」B「[五|いつ]つあります。」","explain":"その goes right before りんごは, the topic. B counts with 五つ, so A asks いくつ, and ありますか ends the question.","unit":2,"day":5,"step":"drill"},"n5u02d5.e1":{"id":"n5u02d5.e1","kind":"choice","type":"文の文法1","label":"Choose the word","q":"A「この　ノートは　（　　）ですか。」B「二百円です。」","options":["いくら","だれ","いくつ","何時"],"answer":1,"explain":"B answers with a price, so A asks how much with いくら. いくつ asks how many or how old, 何時 asks the time, and だれ asks who.","unit":2,"day":5,"step":"exam"},"n5u02d5.e2":{"id":"n5u02d5.e2","kind":"choice","type":"文の文法1","label":"Choose the word","q":"きのうは　八時間（　　）　ねました。","options":["ぐらい","いくら","いくつ","ごろ"],"answer":1,"explain":"八時間 is a length of time, so \"about eight hours\" is ぐらい. ごろ is only for a point in time, like 八時. いくら and いくつ ask questions, and this sentence does not ask.","unit":2,"day":5,"step":"exam"},"n5u02d5.e3":{"id":"n5u02d5.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「あした　何時ごろ　来ますか。」B「","after":"よ。」","tiles":["九時","ごろ","に","行きます"],"star":1,"bank":[3,1,0,2],"full":"A「あした　何時ごろ　来ますか。」B「九時{ごろ}に　行きますよ。」","explain":"九時, ごろ, に, 行きます. ごろ comes right after the clock time, に follows ごろ, and 行きます goes before よ.","unit":2,"day":5,"step":"exam"},"n5u02d5.k1":{"id":"n5u02d5.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"この　ケーキは　_六百円_です。","options":["ろくびゃくえん","ろっぴゃくえん","ろくひゃくえん","ろっびゃくえん"],"answer":2,"explain":"六 and 百 join as ろっぴゃく, with a small っ and ぴゃ, as in はっぴゃく (八百). The other three spellings are not words. Compare さんびゃく (三百), which takes びゃく.","unit":2,"day":5,"step":"scene"},"n5u02d5.r1":{"id":"n5u02d5.r1","kind":"choice","type":"即時応答","q":"男：すみません、この　りんごは　一つ　いくらですか。","script":["男：すみません、このりんごは一ついくらですか。","ナレーター：1","女：はい、一つです。","ナレーター：2","女：百二十円です。","ナレーター：3","女：三つあります。"],"options":["はい、一つです。","百二十円です。","三つあります。"],"printed":false,"short":["はい、一つです","百二十円です","三つあります"],"answer":2,"why":["The man asks a price with いくら, not a yes-or-no question. 一つ in his question only means \"for one\".","He asks how much one apple is, and she gives the price.","三つあります says how many there are. That answers いくつ, not いくら."],"unit":2,"day":5,"step":"skill","clip":"l_n5u2d5"},"n5u02d6.c1":{"id":"n5u02d6.c1","kind":"choice","type":"文の文法1","label":"ホテルで","q":"ロビーに^[山川|やまかわ]さん^が（　　）よ。","options":["です","あります","います"],"answer":3,"why":["ロビーに already says where, so the sentence needs a verb for being there. 山川さんがですよ is not Japanese.","あります is for things. 山川さん is a person.","山川さん is a person, so います: \"Mr. Yamakawa is in the lobby.\""],"explain":null,"unit":2,"day":6,"step":"compare"},"n5u02d6.d1":{"id":"n5u02d6.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^[電話|でんわ]^は[一|いっ]かいの[入口|いりぐち]の[右|みぎ]に（　　）。","options":["あります","います","です","など"],"answer":1,"why":["A phone is a thing, and 電話は〜にあります says where the phone is.","います is for people and animals. A phone is a thing.","右に needs a verb after it. With です you would say 右です, without に.","など comes after a list of things, as in 本やノートなど. It cannot take the place of the verb."],"unit":2,"day":6,"step":"drill"},"n5u02d6.d2":{"id":"n5u02d6.d2","kind":"choice","type":"文の文法1","label":"Choose the question word","q":"A：このホテルには、へやが（　　）ありますか。B：^[百|ひゃく]ぐらい^あります。","options":["[何時|なんじ]ごろ","どこに","いくら","いくつ"],"answer":4,"why":["何時ごろ asks about what time. 百ぐらい is not a time.","どこに asks where. B answers how many, not where.","いくら asks a price. B answers with a number of rooms.","B says about a hundred, so A asked how many: いくつ."],"explain":null,"unit":2,"day":6,"step":"drill"},"n5u02d6.d3":{"id":"n5u02d6.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：リンさんはどこにいますか。B：（　　）にいますよ。^あのまどの[前|まえ]^です。","options":["あそこ","あの","あれ","こちら"],"answer":1,"why":["Lin is by a window far from both people (あの), so B points at that place: あそこ.","あの needs a noun right after it, as in あのまど. It cannot come before に.","あれ points at a thing, not a place. You cannot be \"in\" あれ here.","こちら points to the speaker's side, but B says あのまど, a window far from both people."],"explain":null,"unit":2,"day":6,"step":"drill"},"n5u02d6.d4":{"id":"n5u02d6.d4","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"ホテルのへやの[中|なか]（　　）テレビやれいぞうこが^あります^。","options":["で","に","を","が"],"answer":2,"why":["で marks the place where you do something. あります says where a thing is, so it takes に.","With あります, the place where things are takes に: へやの中に.","を marks the thing an action is done to. あります is not that kind of verb.","が already comes after テレビやれいぞうこ. へやの中 is the place, not the thing that is there."],"unit":2,"day":6,"step":"drill"},"n5u02d6.d5":{"id":"n5u02d6.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A：[山川|やまかわ]さんはどこにいますか。B：","after":"よ。","tiles":["あの","[車|くるま]の","[中|なか]に","います"],"star":1,"bank":[2,0,3,1],"hint":"Which car? Then where in the car? A person comes last with います.","full":"A：[山川|やまかわ]さんはどこにいますか。B：あの{[車|くるま]の}[中|なか]にいますよ。","explain":"あの車 is that car over there. 車の中に is inside the car. 山川さん is a person, so います comes last: he is in that car.","unit":2,"day":6,"step":"drill"},"n5u02d6.d6":{"id":"n5u02d6.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[一|いっ]かいの","after":"があります。","tiles":["[店|みせ]","の[中|なか]に","パンや","[水|みず]など"],"star":2,"bank":[3,1,0,2],"hint":"First say the place, then list what is there.","full":"[一|いっ]かいの[店|みせ]{の[中|なか]に}パン{や}[水|みず]{など}があります。","explain":"一かいの店 is the shop on the first floor, and の中に says inside it. Then the list: パンや comes first and 水など closes it, right before があります.","unit":2,"day":6,"step":"drill"},"n5u02d6.e1":{"id":"n5u02d6.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ホテルの　ロビーに　だれ（　　）　いますか。","options":["を","で","が","は"],"answer":3,"explain":"ロビーに　だれが　いますか asks who is in the lobby: the person who is there takes が. だれ is a question word, and a question word does not take は. を marks the thing an action is done to, and います has none. で marks where you do something; here the place already has に.","unit":2,"day":6,"step":"exam"},"n5u02d6.e2":{"id":"n5u02d6.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「ホテルから　駅まで　どのぐらい　かかりますか。」\nB「十五分（　　）です。」","options":["ぐらい","いくら","など","ごろ"],"answer":1,"explain":"A asks how long it takes, so B gives about how long: 十五分ぐらい. ごろ goes with a point in time, like 九時ごろ, not with how long something takes. いくら asks a price. など comes after a list of things.","unit":2,"day":6,"step":"exam"},"n5u02d6.e3":{"id":"n5u02d6.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「トイレは　どこに　ありますか。」B「","after":"ありますよ。」","tiles":["あそこの","エレベーターの","右","に"],"star":2,"bank":[3,1,0,2],"full":"A「トイレは　どこに　ありますか。」B「あそこの　エレベーターの　{右}に　ありますよ。」","explain":"あそこの, エレベーターの, 右, に. あそこの points at the elevator over there, エレベーターの右 is to the right of it, and に comes after the position word, right before あります.","unit":2,"day":6,"step":"exam"},"n5u02d6.k1":{"id":"n5u02d6.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"ビルの　_西口_の　前に　電話が　あります。","options":["にしくち","せいぐち","ひがしぐち","にしぐち"],"answer":4,"explain":"西口 is にしぐち: 西 (にし, west) and 口, which becomes ぐち after にし. ひがしぐち is 東口, the east side. にしくち misses the change from く to ぐ, and せいぐち is not a word.","unit":2,"day":6,"step":"scene"},"n5u02d6.r1":{"id":"n5u02d6.r1","kind":"choice","type":"読解・情報検索","q":"リーさんは　日本語の　本を　買いたいです。何かいへ　行きますか。","options":["一かい","二かい","四かい","五かい"],"short":["1かい","2かい","4かい","5かい"],"answer":2,"explain":"Books are sold at a 本や, and the guide puts the 本や on the second floor. The fourth floor has 日本語 in its name, but it is a school, not a shop.","why":["The first floor has a café and a phone, not books.","","四かい is a Japanese school. It has 日本語 in its name, but it does not sell books.","The fifth floor is a company office."],"unit":2,"day":6,"step":"skill"},"n5u02t.1":{"id":"n5u02t.1","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"ぎんこうは　駅の　_左_に　あります。","options":["ひがし","にし","みぎ","ひだり"],"answer":4,"explain":"左 is ひだり, left. みぎ is 右 (right), which looks like 左 but has 口 at the bottom. ひがし is 東 (east) and にし is 西 (west).","unit":2,"step":"test"},"n5u02t.2":{"id":"n5u02t.2","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"つくえの　上に　りんごが　_三つ_　あります。","options":["さっつ","みつ","さんつ","みっつ"],"answer":4,"explain":"三つ is みっつ, with a small っ. みつ leaves out the small っ, and さんつ and さっつ use さん, the reading of 三 in words like 三百 or 三人. None of them is a word for three things.","unit":2,"step":"test"},"n5u02t.3":{"id":"n5u02t.3","kind":"choice","type":"表記","label":"Kanji spelling","q":"こうえんの　_いりぐち_に　大きい　木が　あります。","options":["人日","人口","入日","入口"],"answer":4,"explain":"いりぐち is 入口: 入 (go in) with 口 (opening). 人 looks like 入 but is ひと (person), so 人口 is another word (population), not いりぐち. 入日 and 人日 have 日 (day) in place of 口.","unit":2,"step":"test"},"n5u02t.4":{"id":"n5u02t.4","kind":"choice","type":"表記","label":"Kanji spelling","q":"_みず_は　れいぞうこの　中に　あります。","options":["木","小","少","水"],"answer":4,"explain":"みず is 水 (water). 木 is き (tree), 小 is the 小 of 小さい (small), and 少 is the 少 of 少し (a little). They look a little like 水 but none of them is read みず.","unit":2,"step":"test"},"n5u02t.5":{"id":"n5u02t.5","kind":"choice","type":"文脈規定","label":"Word in context","q":"本やは　この　ビルの　三（　　）に　あります。","options":["かい","まい","にん","つ"],"answer":1,"explain":"A shop in a building is on a floor, and floors are counted with かい: 三かい. 三つ counts things, 三まい counts flat things such as paper, and 三にん counts people. Only かい says where in the building.","unit":2,"step":"test"},"n5u02t.6":{"id":"n5u02t.6","kind":"choice","type":"文脈規定","label":"Word in context","q":"ここは　（　　）です。本が　たくさん　あります。","options":["ぎんこう","しょくどう","びょういん","としょかん"],"answer":4,"explain":"A place with a lot of books is a library, としょかん. A bank (ぎんこう) has money, a cafeteria (しょくどう) has food, and a hospital (びょういん) has doctors; none of them is known for having many books.","unit":2,"step":"test"},"n5u02t.7":{"id":"n5u02t.7","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"_ぎんこうは　ゆうびんきょくの　右に　あります_。","options":["ゆうびんきょくは　ぎんこうの　左に　あります。","ぎんこうは　ゆうびんきょくの　左に　あります。","ゆうびんきょくは　ぎんこうの　前に　あります。","ゆうびんきょくは　ぎんこうの　右に　あります。"],"answer":1,"explain":"If the bank is on the right of the post office, the post office is on the left of the bank. Option 4 puts the post office on the right, option 2 moves the bank to the left, and option 3 puts the post office in front, not beside it.","unit":2,"step":"test"},"n5u02t.8":{"id":"n5u02t.8","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"ここは　_お手あらい_です。","options":["ここは　げんかんです。","ここは　おふろです。","ここは　トイレです。","ここは　だいどころです。"],"answer":3,"explain":"お手あらい and トイレ are two words for the same room, the toilet. だいどころ is the kitchen, げんかん is the entrance of a house where you take off your shoes, and おふろ is the bath.","unit":2,"step":"test"},"n5u02t.9":{"id":"n5u02t.9","kind":"choice","type":"文の文法1","label":"Choose the word","q":"A「すみません。この　ちかくに　ぎんこうは　ありますか。」B「ええ、（　　）に　ありますよ。あの　たかい　たてものです。」","options":["ここ","あそこ","あれ","どこ"],"answer":2,"explain":"B points to a tall building over there (あの), so the bank is あそこ, a place far from both people. ここ would mean the place where they are standing, which does not fit あの. あれ is a thing, not a place, so あれにあります does not say where. どこ asks a question, but B is answering one.","unit":2,"step":"test"},"n5u02t.10":{"id":"n5u02t.10","kind":"choice","type":"文の文法1","label":"Choose the word","q":"（パーティーで）A「中山さん、（　　）は　わたしの　クラスの　キムさんです。」B「はじめまして。中山です。」","options":["ここ","こちら","どちら","この"],"answer":2,"explain":"When you introduce someone who is with you, you say こちらは, the polite \"this person\". この must have a noun right after it, so この cannot stand before は. ここ is a place, and a place cannot be キムさん. どちら is a question word, and A is not asking anything.","unit":2,"step":"test"},"n5u02t.11":{"id":"n5u02t.11","kind":"choice","type":"文の文法1","label":"Choose the form","q":"へやに　テレビは　ありますが、つくえは　（　　）。","options":["ありません","います","あります","いません"],"answer":1,"explain":"が here means \"but\", so the second half says the opposite of the first: there is a TV but no desk. A desk is a thing, so it takes ありません. あります would not be the opposite of the first half, and います and いません are for people and animals, not for a desk.","unit":2,"step":"test"},"n5u02t.12":{"id":"n5u02t.12","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"A「ジョンさんは　どこですか。」B「ジョンさんは　いま　としょかん（　　）　います。」","options":["へ","に","で","を"],"answer":2,"explain":"To say where someone is, the place takes に before います: としょかんにいます. で marks the place where you do an action (としょかんでべんきょうします), but います only says where he is. を and へ do not mark the place where someone is.","unit":2,"step":"test"},"n5u02t.13":{"id":"n5u02t.13","kind":"choice","type":"文の文法1","label":"Choose the word","q":"つくえの　上に　ノートや　じしょ（　　）が　あります。","options":["ぐらい","ごろ","など","の"],"answer":3,"explain":"や lists a few examples, and など after the last one means \"and other things like that\": ノートやじしょなど. じしょのが あります does not make sense here. ぐらい is for an amount such as a number or a time span, and ごろ is for a point in time; じしょ is neither.","unit":2,"step":"test"},"n5u02t.14":{"id":"n5u02t.14","kind":"choice","type":"文の文法1","label":"Choose the word","q":"A「おとうとさんは　（　　）ですか。」B「八つです。」","options":["いくつ","いつ","どれ","いくら"],"answer":1,"explain":"B answers 八つです, eight years old, so A asks a child's age with いくつ. いくら asks a price, and a person has no price. いつ asks when, and 八つ is not a time. どれ asks which one, and 八つです does not pick one out.","unit":2,"step":"test"},"n5u02t.15":{"id":"n5u02t.15","kind":"choice","type":"文の文法1","label":"Choose the word","q":"きょうしつに　学生が　二十人（　　）　います。","options":["いくら","ぐらい","いくつ","ごろ"],"answer":2,"explain":"二十人 is a number of people, and ぐらい after an amount means \"about\": about twenty students. ごろ means \"around\" only with a point in time, such as 三時ごろ, not with a number of people. いくら and いくつ are question words, and this sentence is not a question.","unit":2,"step":"test"},"n5u02t.16":{"id":"n5u02t.16","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「あ、あの　木の　","after":"が　いますよ。」B「ええ、かわいいですね。」","tiles":["下","に","白い","ねこ"],"star":2,"bank":[3,0,2,1],"full":"A「あ、あの　木の　下に　{白い}　ねこが　いますよ。」B「ええ、かわいいですね。」","explain":"下, に, 白い, ねこ. 木の needs a position word after it, so 下 comes first: 木の下 (under the tree). に marks that place. 白い describes ねこ, so it comes right before it, and ねこ goes before が います, because a cat is alive and takes います.","unit":2,"step":"test"},"n5u02t.17":{"id":"n5u02t.17","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「わたしの　さいふは　どこですか。」B「かばんの　","after":"ありますよ。」","tiles":["中","の","小さい","はこに"],"star":1,"bank":[2,0,3,1],"full":"A「わたしの　さいふは　どこですか。」B「かばんの　中{の}　小さい　はこに　ありますよ。」","explain":"中, の, 小さい, はこに. かばんの中 is the inside of the bag. の joins it to the box: the small box in the bag. 小さい describes はこ, so it comes right before it, and はこに, with に for the place, goes before あります.","unit":2,"step":"test"},"n5u02t.18":{"id":"n5u02t.18","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「あしたは　何時から　うちに　いますか。」B「","after":"いますよ。」","tiles":["午後","五時","ごろ","から"],"star":2,"bank":[1,3,0,2],"full":"A「あしたは　何時から　うちに　いますか。」B「午後　五時{ごろ}から　いますよ。」","explain":"午後, 五時, ごろ, から. 午後 (p.m.) comes before the hour, as in 午後五時. ごろ (around) goes right after the time, and から (from) comes last, answering A's 何時から.","unit":2,"step":"test"},"n5u02t.19":{"id":"n5u02t.19","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ジョンさん\nわたしの　あたらしい　へやは　二かいです。へやには　ベッドと　つくえが　あります。テレビは　ありません。つくえの　上に　とけいが　あります。まどの　外に　高い　木が　あります。木の　上には　ときどき　白い　とりが　います。\nゆき","q":"ゆきさんの　へやに　ない　ものは　どれですか。","options":["ベッド","つくえ","テレビ","とけい"],"answer":3,"short":["ベッド","つくえ","テレビ","とけい"],"explain":"ゆき writes テレビはありません: there is no TV. The room has a bed and a desk (ベッドとつくえがあります), and the clock is on the desk (つくえの上にとけいがあります).","unit":2,"step":"test"},"n5u02t.20":{"id":"n5u02t.20","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ジョンさん\nわたしの　あたらしい　へやは　二かいです。へやには　ベッドと　つくえが　あります。テレビは　ありません。つくえの　上に　とけいが　あります。まどの　外に　高い　木が　あります。木の　上には　ときどき　白い　とりが　います。\nゆき","q":"ただしい　ものは　どれですか。","options":["白い　とりは　ときどき　木の　上に　います。","ゆきさんの　へやは　一かいに　あります。","とけいは　つくえの　下に　あります。","高い　木は　へやの　中に　あります。"],"answer":1,"short":["とりは木の上","へやは一かい","とけいはつくえの下","木はへやの中"],"explain":"ゆき writes 木の上にはときどき白いとりがいます: sometimes a white bird is in the tree. The room is on 二かい, not 一かい. The clock is on the desk (上), not under it (下). The tall tree is outside the window (まどの外), not in the room.","unit":2,"step":"test"},"n5u02t.21":{"id":"n5u02t.21","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"パンの　店「やまの　パン」\nメロンパン　一つ　百五十円\nカレーパン　一つ　二百円\nサンドイッチ　一つ　三百五十円\n午後　五時から　パンと　サンドイッチは　ぜんぶ　一つ　百円です。\n店の　前に　テーブルと　いすが　あります。どうぞ。","q":"リンさんは　午後　二時に　この　店で　カレーパンを　二つ　買います。いくらですか。","options":["百円","二百円","四百円","七百円"],"answer":3,"short":["百円","二百円","四百円","七百円"],"explain":"At two in the afternoon the 五時から price does not apply yet, so a カレーパン is 二百円 each, and two are 四百円. 百円 is the after-five price of one. 二百円 is one at the normal price, or two after five. 七百円 is two sandwiches.","unit":2,"step":"test"},"n5u02t.22":{"id":"n5u02t.22","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"パンの　店「やまの　パン」\nメロンパン　一つ　百五十円\nカレーパン　一つ　二百円\nサンドイッチ　一つ　三百五十円\n午後　五時から　パンと　サンドイッチは　ぜんぶ　一つ　百円です。\n店の　前に　テーブルと　いすが　あります。どうぞ。","q":"キムさんは　午後　六時に　この　店で　メロンパンを　一つと　サンドイッチを　一つ　買います。いくらですか。","options":["二百円","二百五十円","四百円","五百円"],"answer":1,"short":["二百円","二百五十円","四百円","五百円"],"explain":"Six p.m. is after five, and from five everything is 百円 each, so two things are 二百円. 五百円 is the normal price (百五十円 and 三百五十円). 二百五十円 takes the normal price for the メロンパン only, and 四百円 is the price of two カレーパン before five.","unit":2,"step":"test"},"n5u02t.23":{"id":"n5u02t.23","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"マイクさん\nあした　いっしょに　えいがを　見ませんか。えいがは　午後　二時からです。えいがかんは　駅から　あるいて　十分ぐらいです。わたしは　一時半ごろ　駅の　東口の　前に　います。東口の　前には　大きい　花やが　あります。\nゆか","q":"ゆかさんは　あした　何時ごろ　どこに　いますか。","options":["一時半ごろ　えいがかんの　前","一時半ごろ　駅の　東口の　前","二時ごろ　駅の　東口の　前","二時ごろ　えいがかんの　前"],"answer":2,"short":["一時半 えいがかん","一時半 東口","二時 東口","二時 えいがかん"],"explain":"ゆか writes 一時半ごろ駅の東口の前にいます. 二時 is when the film starts, not when she waits. She waits at the station's east exit, not in front of the cinema, which is ten minutes away.","unit":2,"step":"test"},"n5u02t.24":{"id":"n5u02t.24","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"マイクさん\nあした　いっしょに　えいがを　見ませんか。えいがは　午後　二時からです。えいがかんは　駅から　あるいて　十分ぐらいです。わたしは　一時半ごろ　駅の　東口の　前に　います。東口の　前には　大きい　花やが　あります。\nゆか","q":"ただしい　ものは　どれですか。","options":["花やは　駅の　西口の　前に　あります。","えいがは　一時半からです。","えいがかんは　駅の　中に　あります。","駅から　えいがかんまで　十分ぐらいです。"],"answer":4,"short":["花やは西口","えいがは一時半から","えいがかんは駅の中","駅から十分ぐらい"],"explain":"ゆか writes えいがかんは駅からあるいて十分ぐらいです. The film starts at 二時; 一時半 is when she will be at the station. The cinema is a ten-minute walk away, so it is not inside the station. The flower shop is in front of the east exit (東口), not the west exit.","unit":2,"step":"test"},"n5u03d1.c1":{"id":"n5u03d1.c1","kind":"choice","type":"文の文法1","label":"あさごはんのはなし","q":"A「あさごはんを[食|た]べますか。」\nB「^いいえ^、（　　）。」","options":["[食|た]べます","[食|た]べません","[食|た]べるじゃありません"],"answer":2,"why":["食べます means yes, I eat it. B starts with いいえ, so B needs the no ending.","B says いいえ, so the verb takes the no ending: 食べます becomes 食べません.","じゃありません comes after a noun. 食べる is a verb, so its no ending is 食べません."],"unit":3,"day":1,"step":"compare"},"n5u03d1.d1":{"id":"n5u03d1.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「[毎日|まいにち]コーヒーを[飲|の]みますか。」\nB「^はい^、[毎日|まいにち]（　　）。」","options":["[飲|の]みません","[飲|の]みます","[飲|の]みですか","[飲|の]むます"],"answer":2,"why":["飲みません means I don't drink it. B starts with はい, so B drinks it.","B says はい, so B repeats the yes form: 飲みます, I drink it every day.","です does not come right after a verb stem, and B is answering, not asking.","ます joins the ます stem 飲み, not the dictionary form 飲む."],"explain":null,"unit":3,"day":1,"step":"drill"},"n5u03d1.d2":{"id":"n5u03d1.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あした[友|とも]だちと^テニスを^（　　）。","options":["するます","あります","します","きます"],"answer":3,"why":["する changes completely: its polite form is します, not するます.","あります says that a thing is there. It does not take テニスを.","You play tennis with する, and the polite form of する is します. With あした it is a plan.","きます is the polite form of 来る, come. You cannot come tennis."],"explain":null,"unit":3,"day":1,"step":"drill"},"n5u03d1.d3":{"id":"n5u03d1.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「[日|にち]よう[日|び]も[学校|がっこう]へ[行|い]きますか。」\nB「^いいえ^、[日|にち]よう[日|び]は（　　）。」","options":["[行|い]きませんか","[行|い]きます","[行|い]くじゃありません","[行|い]きません"],"answer":4,"why":["行きませんか invites someone: won't you go? B is answering A's question, not inviting.","行きます means yes, I go. B starts with いいえ.","じゃありません comes after a noun. 行く is a verb, so its no ending is 行きません.","B says いいえ, so the verb takes the no ending: 行きます becomes 行きません."],"explain":null,"unit":3,"day":1,"step":"drill"},"n5u03d1.d4":{"id":"n5u03d1.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしはテレビを^あまり^（　　）。","options":["[見|み]ます","[見|み]ません","[見|み]るません","[見|み]じゃありません"],"answer":2,"why":["あまり in the sense \"not much\" goes with a no ending. 見ます is the yes form.","あまり with the no ending says \"not much\": I don't watch TV much.","ません joins the ます stem 見, not the dictionary form 見る.","じゃありません comes after a noun. 見る is a verb, so its no ending is 見ません."],"unit":3,"day":1,"step":"drill"},"n5u03d1.d5":{"id":"n5u03d1.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしは[毎日|まいにち]あさ","after":"。","tiles":["[七時|しちじ]","に","おき","ます"],"star":2,"bank":[3,1,0,2],"hint":"The time comes first, with に right after it. Then the verb, with ます at the end.","full":"わたしは[毎日|まいにち]あさ[七時|しちじ]におき{ます}。","explain":"に marks the time, so it comes right after 七時. おき is the ます stem of おきる, and ます joins it at the end of the sentence.","unit":3,"day":1,"step":"drill"},"n5u03d1.d6":{"id":"n5u03d1.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「[土|ど]よう[日|び]も[会社|かいしゃ]へ[行|い]きますか。」\nB「いいえ、[土|ど]よう[日|び]は","after":"。」","tiles":["[会社|かいしゃ]","へ","[行|い]き","ません"],"star":3,"bank":[2,3,0,1],"hint":"Say where first, with へ. The verb comes last, with the no ending.","full":"A「[土|ど]よう[日|び]も[会社|かいしゃ]へ[行|い]きますか。」\nB「いいえ、[土|ど]よう[日|び]は[会社|かいしゃ]へ[行|い]き{ません}。」","explain":"へ shows where you go, so it comes right after 会社. B says いいえ, so 行き takes the no ending ません.","unit":3,"day":1,"step":"drill"},"n5u03d1.e1":{"id":"n5u03d1.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「中山さんは　毎日　何時に　うちを　出ますか。」\nB「七時に　（　　）。」","options":["出ますか","出ません","出るます","出ます"],"answer":4,"explain":"A asks what time B leaves home every day, and B answers with the time: 七時に出ます. 出ません says B does not leave at seven, which does not answer the question. 出るます is not a form: ます joins 出, the ます stem. 出ますか would be a question, but B is answering.","unit":3,"day":1,"step":"exam"},"n5u03d1.e2":{"id":"n5u03d1.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「よく　本を　読みますか。」\nB「いいえ、あまり　（　　）。」","options":["読みます","読むません","読みましょう","読みません"],"answer":4,"explain":"B says いいえ, and あまり in the sense \"not much\" goes with a no ending: あまり読みません, I don't read much. 読みます is the yes form. 読むません is not a form: ません joins 読み. 読みましょう means let's read, which does not answer A.","unit":3,"day":1,"step":"exam"},"n5u03d1.e3":{"id":"n5u03d1.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"先生は　あした　","after":"。","tiles":["午前","十時","に","来ます"],"star":1,"bank":[3,0,2,1],"full":"先生は　あした　午前十時に{来ます}。","explain":"午前, 十時, に, 来ます. 午前 comes before the hour, as in 午前十時, ten in the morning. に marks the time, so it follows 十時. The verb 来ます ends the sentence: the teacher will come tomorrow.","unit":3,"day":1,"step":"exam"},"n5u03d1.k1":{"id":"n5u03d1.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_来週_　友だちと　山へ　行きます。","options":["らいしゅ","きしゅう","らいしゅう","らいじゅう"],"answer":3,"explain":"来週 is らいしゅう: in this word 来 is read ライ and 週 is read シュウ. らいしゅ drops the long う, きしゅう uses き from 来ます, and らいじゅう adds a dakuten that is not there.","unit":3,"day":1,"step":"scene"},"n5u03d1.r1":{"id":"n5u03d1.r1","kind":"choice","type":"ポイント理解","q":"女の人は　あしたの　午後　何を　しますか。","script":["ナレーター：男の人と女の人が話しています。女の人は、あしたの午後、何をしますか。","男：中山さん、あしたは休みですね。何をしますか。","女：午前は、うちでそうじをします。","男：午後は、デパートへ行きますか。","女：いいえ、行きません。友だちとえいがを見ます。","男：いいですね。わたしは、あしたも会社です。","ナレーター：女の人は、あしたの午後、何をしますか。"],"options":["うちで　そうじを　します","デパートへ　行きます","友だちと　えいがを　見ます","会社へ　行きます"],"printed":true,"short":["うちで そうじ","デパートへ 行く","友だちと えいが","会社へ 行く"],"answer":3,"why":["She cleans the house in the morning (午前), not in the afternoon.","The man asks if she goes to the department store, and she says いいえ、行きません.","In the afternoon she says 友だちとえいがを見ます: she will watch a film with a friend.","The man is the one who goes to work tomorrow (あしたも会社です). She has the day off."],"unit":3,"day":1,"step":"skill","clip":"l_n5u3d1"},"n5u03d2.c1":{"id":"n5u03d2.c1","kind":"choice","type":"文の文法1","label":"きのうのこと","q":"A：きのう、[学校|がっこう]へ[行|い]きましたか。B：はい、（　　）。","options":["[行|い]きません","[行|い]きました","[行|い]きませんでした"],"answer":2,"why":["行きません is not past, and it means \"I don't go\". It clashes with はい too.","はい to a question about yesterday: the polite past, 行きました.","行きませんでした means \"I didn't go\". It clashes with はい."],"explain":null,"unit":3,"day":2,"step":"compare"},"n5u03d2.d1":{"id":"n5u03d2.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^きのう^、デパートで[花|はな]を[買|か]い（　　）。","options":["ません","ますでした","ます","ました"],"answer":4,"why":["ません is not past, and it means \"don't\". For yesterday you need a past form.","There is no ますでした. The past of ます is ました.","ます is for now, habits and the future. きのう points to the past.","きのう is the past, and the sentence says it happened: 買いました."],"explain":null,"unit":3,"day":2,"step":"drill"},"n5u03d2.d2":{"id":"n5u03d2.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：きのう、テレビを[見|み]ましたか。B：^いいえ^、（　　）。","options":["[見|み]ました","[見|み]ませんでした","[見|み]ません","[見|み]ないでした"],"answer":2,"why":["見ました means \"I watched\". It clashes with いいえ.","いいえ to a question about yesterday: the polite past no form, 見ませんでした.","見ません is not past. The question is about yesterday, so add でした.","見ないでした is a common mistake, not standard polite Japanese. Say 見ませんでした."],"unit":3,"day":2,"step":"drill"},"n5u03d2.d3":{"id":"n5u03d2.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^[先週|せんしゅう]の[日|にち]よう[日|び]^は、^[何|なに]も^（　　）。","options":["しません","します","しました","しませんでした"],"answer":4,"why":["しません is a not form, but it is not past. 先週 needs でした after ません.","します is not past, and 何も needs a not form.","何も (nothing) goes with a not form. しました says you did something.","Last Sunday is past, and 何も needs a not form: しませんでした."],"explain":null,"unit":3,"day":2,"step":"drill"},"n5u03d2.d4":{"id":"n5u03d2.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：きのう、[何|なに]を[食|た]べ（　　）か。B：^カレーを[食|た]べました^。","options":["ません","ませんでした","ます","ました"],"answer":4,"why":["食べませんか is an invitation (won't you eat?), not a question about yesterday.","何を食べませんでしたか asks what you did not eat. B tells what she ate.","何を食べますか asks about now or later. きのう and B's answer are in the past.","B answers 食べました, so the question is in the past too: 食べましたか."],"explain":null,"unit":3,"day":2,"step":"drill"},"n5u03d2.d5":{"id":"n5u03d2.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"この[花|はな]は、[駅|えき]の","after":"。","tiles":["[前|まえ]の","[店|みせ]で","[買|か]い","ました"],"star":1,"bank":[2,0,3,1],"hint":"駅の needs a noun right after it. ました comes last, right after the verb.","full":"この[花|はな]は、[駅|えき]の[前|まえ]の[店|みせ]で[買|か]い{ました}。","explain":"駅の前の is \"in front of the station\" and it describes 店. 店で says where, then 買い and ました make the past verb.","unit":3,"day":2,"step":"drill"},"n5u03d2.d6":{"id":"n5u03d2.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"きのうは、","after":"。うちにいました。","tiles":["どこ","へも","[行|い]き","ませんでした"],"star":3,"bank":[3,1,0,2],"hint":"どこへも means \"(not) anywhere\". Which ending is past and a not form?","full":"きのうは、どこへも[行|い]き{ませんでした}。うちにいました。","explain":"どこ and へも go together, then the verb. きのう is past and どこへも needs a not form, so 行きませんでした.","unit":3,"day":2,"step":"drill"},"n5u03d2.e1":{"id":"n5u03d2.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きのう、スーパーで　たまごを（　　）。","options":["買いました","買いません","買いませんか","買います"],"answer":1,"explain":"きのう is the past, and the sentence says what was bought: 買いました. 買います and 買いません are not past, and 買いませんか is an invitation.","unit":3,"day":2,"step":"exam"},"n5u03d2.e2":{"id":"n5u03d2.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：先週の　土よう日、山へ　行きましたか。B：いいえ、（　　）。うちに　いました。","options":["行きません","行きませんでした","行きました","行きます"],"answer":2,"explain":"いいえ to a question about last Saturday, and B stayed at home: 行きませんでした. 行きました clashes with いいえ, and 行きます and 行きません are not past.","unit":3,"day":2,"step":"exam"},"n5u03d2.e3":{"id":"n5u03d2.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"先週の　日よう日、","after":"。","tiles":["友だちの","うち","へ","行きました"],"star":1,"bank":[3,1,0,2],"full":"先週の　日よう日、友だちの　{うち}へ　行きました。","explain":"友だちの, うち, へ, 行きました. 友だちの describes うち, へ marks where to, and the verb comes last.","unit":3,"day":2,"step":"exam"},"n5u03d2.k1":{"id":"n5u03d2.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"この　花は　_千円_でした。","options":["せんえん","ぜんえん","せいえん","ちえん"],"answer":1,"explain":"千円 is read せんえん. 千 becomes ぜん only after 三 (三千, さんぜん). せいえん and ちえん are not readings of 千円.","unit":3,"day":2,"step":"scene"},"n5u03d2.r1":{"id":"n5u03d2.r1","kind":"choice","type":"読解・内容理解（短文）","q":"この　人に　ついて、ただしい　ものは　どれですか。","options":["日よう日は　うちに　いました。","日よう日に　しゅくだいを　しました。","土よう日に　ひとりで　店へ　行きました。","土よう日に　本を　買いました。"],"short":["日よう日はうちにいた","しゅくだいをした","ひとりで店へ行った","本を買った"],"answer":1,"explain":"On Sunday the writer went nowhere (どこへも行きませんでした) and watched TV at home, so the writer was at home.","why":["","The writer writes しゅくだいはしませんでした: no homework was done.","The writer went with 母 (mother), not alone.","The writer looked at books but writes 買いませんでした: no book was bought."],"unit":3,"day":2,"step":"skill"},"n5u03d3.c1":{"id":"n5u03d3.c1","kind":"choice","type":"文の文法1","label":"ともだちと","q":"あした、[友|とも]だちのうち（　　）[行|い]きます。","options":["が","を","へ"],"answer":3,"why":["うちが行きます would make the house the one who goes.","を marks the thing you eat, read or buy. The house is the place you go to.","The friend's house is where you go, and the place before 行きます takes へ."],"explain":null,"unit":3,"day":3,"step":"compare"},"n5u03d3.d1":{"id":"n5u03d3.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[父|ちち]は[毎日|まいにち][新聞|しんぶん]（　　）^[読|よ]みます^。","options":["へ","が","に","を"],"answer":4,"why":["へ marks the place you go to. 読みます is not going anywhere.","With 読みます, the thing you read takes を, not が. 父は already says who reads.","に here would mark a place you go to. A newspaper is not a place.","The newspaper is the thing he reads, so it takes を."],"explain":null,"unit":3,"day":3,"step":"drill"},"n5u03d3.d2":{"id":"n5u03d3.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"らいしゅう、[日本|にほん]（　　）^[行|い]きます^。","options":["を","が","で","へ"],"answer":4,"why":["を does not mark the place you go to.","日本が行きます would make Japan the one who goes.","で marks where you do something, not where you go.","Japan is where you are going, and the place before 行きます takes へ."],"explain":null,"unit":3,"day":3,"step":"drill"},"n5u03d3.d3":{"id":"n5u03d3.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：きのう[何|なに]（　　）[買|か]いましたか。　B：^[本|ほん]を^[買|か]いました。","options":["は","を","へ","が"],"answer":2,"why":["何は does not work in this question. The thing you buy takes を.","A asks about the thing B bought, so 何 takes を, just like 本を in B's answer.","へ marks the place you go to. 買いました is not going anywhere.","The thing you buy takes を, not が."],"explain":null,"unit":3,"day":3,"step":"drill"},"n5u03d3.d4":{"id":"n5u03d3.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[先週|せんしゅう]、[母|はは]がわたしのうち^に^（　　）。","options":["[買|か]いました","[来|き]ました","[食|た]べました","[読|よ]みました"],"answer":2,"why":["うちに with 買いました does not make sense here. うちに needs a verb of going or coming.","うちに is the place she came to, so the verb is one of coming: 来ました.","My house is not something you eat, and うちに needs a verb of going or coming.","My house is not something you read, and うちに needs a verb of going or coming."],"explain":null,"unit":3,"day":3,"step":"drill"},"n5u03d3.d5":{"id":"n5u03d3.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしはきのう","after":"。","tiles":["[新|あたら]しい","[本|ほん]","を","[読|よ]みました"],"star":2,"bank":[3,0,2,1],"hint":"新しい goes right before the thing it describes. Which tile marks the thing you read?","full":"わたしはきのう[新|あたら]しい[本|ほん]{を}[読|よ]みました。","explain":"新しい goes right before 本. The thing you read takes を, and the verb comes last: わたしはきのう新しい本を読みました, \"I read a new book yesterday.\"","unit":3,"day":3,"step":"drill"},"n5u03d3.d6":{"id":"n5u03d3.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あした、[母|はは]と","after":"。","tiles":["[新|あたら]しい","デパート","へ","[行|い]きます"],"star":2,"bank":[1,3,0,2],"hint":"Where are you going? Which tile marks that place?","full":"あした、[母|はは]と[新|あたら]しいデパート{へ}[行|い]きます。","explain":"新しい goes right before デパート. The place you go to takes へ, and 行きます comes last: あした、母と新しいデパートへ行きます, \"Tomorrow I am going to the new department store with my mother.\"","unit":3,"day":3,"step":"drill"},"n5u03d3.e1":{"id":"n5u03d3.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：きのう　何を　しましたか。　B：ともだちと　えいが（　　）　見ました。","options":["に","を","へ","が"],"answer":2,"explain":"The film is the thing they watched, so it takes を. へ and に mark a place you go to, and with 見ました the thing you watch does not take が.","unit":3,"day":3,"step":"exam"},"n5u03d3.e2":{"id":"n5u03d3.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"らいげつ　くにへ（　　）。","options":["かえります","食べます","読みます","あります"],"answer":1,"explain":"くにへ marks the place you go to, so the verb must be one of moving: かえります, \"I will go back to my country.\" 食べます and 読みます take a thing with を, and あります takes a place with に, not へ.","unit":3,"day":3,"step":"exam"},"n5u03d3.e3":{"id":"n5u03d3.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"父は　きのう","after":"。","tiles":["大きい","魚","を","買いました"],"star":2,"bank":[2,3,0,1],"full":"父は　きのう　大きい　魚{を}　買いました。","explain":"大きい, 魚, を, 買いました. 大きい goes right before 魚, the thing he bought takes を, and the verb comes last.","unit":3,"day":3,"step":"exam"},"n5u03d3.k1":{"id":"n5u03d3.k1","kind":"choice","type":"表記","label":"How the exam asks it","q":"あ、_でんしゃ_が　来ましたよ。","options":["雨車","電東","電車","雨東"],"answer":3,"explain":"でんしゃ, \"train\", is written 電車: 電 (electricity) and 車 (vehicle). 雨 (rain) is only the top part of 電, and 東 (east) looks like 車 but is a different kanji. 雨車, 電東 and 雨東 are not words.","unit":3,"day":3,"step":"scene"},"n5u03d3.r1":{"id":"n5u03d3.r1","kind":"choice","type":"課題理解","q":"男の人は　はじめに　何を　買いますか。","script":["ナレーター：駅で、女の人と男の人が話しています。男の人は、はじめに、何を買いますか。","女：電車は十時半ですね。まだ二十分ありますよ。","男：じゃあ、ぼく、店へ行きます。パンとおちゃを買います。","女：パンはありますよ。わたしのかばんの中です。","男：そうですか。じゃあ、おちゃを買います。","女：あ、でも、きっぷは買いましたか。","男：あ、まだです。","女：じゃあ、きっぷが先ですよ。","男：そうですね。おちゃは、あとで買います。","ナレーター：男の人は、はじめに、何を買いますか。"],"options":["きっぷ","おちゃ","パンと　おちゃ","パン"],"printed":true,"short":["きっぷ","おちゃ","パンと おちゃ","パン"],"answer":1,"why":["He has not bought a ticket yet (まだです), and the woman says きっぷが先ですよ, \"the ticket comes first\".","He will buy tea, but he says おちゃは、あとで買います: later, after the ticket.","This was his first plan, but the woman already has bread in her bag.","The woman says パンはありますよ: the bread is in her bag, so he does not buy it."],"explain":null,"unit":3,"day":3,"step":"skill","clip":"l_n5u3d3"},"n5u03d4.c1":{"id":"n5u03d4.c1","kind":"choice","type":"文の文法1","label":"学校の店","q":"[学校|がっこう]の[中|なか]に[店|みせ]があります。その[店|みせ]（　　）^パンを[買|か]います^。","options":["に","を","で"],"answer":3,"why":["に says where a thing is, with あります. Here you do something there: 買います.","パンを already has を. その店を パンを has two を and makes no sense.","Buying is an action, so the shop where you buy takes で."],"unit":3,"day":4,"step":"compare"},"n5u03d4.d1":{"id":"n5u03d4.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは[毎日|まいにち]うち（　　）^テレビを[見|み]ます^。","options":["で","に","を","が"],"answer":1,"why":["見ます is an action, so the place where you watch takes で: at home.","に would say where something is. Watching TV is an action, so に does not fit.","テレビを already has を. うちを テレビを has two を.","うちが would make the house the one watching TV."],"unit":3,"day":4,"step":"drill"},"n5u03d4.d2":{"id":"n5u03d4.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きょうしつ（　　）^つくえやいすがあります^。","options":["へ","で","に","を"],"answer":3,"why":["へ shows a direction you go to. あります is not going anywhere.","あります here says where desks and chairs are. That is not an action, so で does not fit.","Where things are takes に before あります: in the classroom.","あります does not take を."],"explain":null,"unit":3,"day":4,"step":"drill"},"n5u03d4.d3":{"id":"n5u03d4.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"はし（　　）^ごはんを[食|た]べます^。","options":["と","を","に","で"],"answer":4,"why":["はしと ごはんを would mean you eat the chopsticks and the rice.","ごはんを already has を. はしを ごはんを has two を.","はしに does not say what you eat with.","Chopsticks are what you use to eat, so they take で."],"explain":null,"unit":3,"day":4,"step":"drill"},"n5u03d4.d4":{"id":"n5u03d4.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは[毎日|まいにち][電車|でんしゃ]（　　）^[会社|かいしゃ]へ[行|い]きます^。","options":["で","を","と","に"],"answer":1,"why":["The train is how you go, so it takes で: by train.","行きます does not take を for the train here.","電車と would mean you go together with the train, like with a friend.","電車に goes with のります (get on). With 行きます it does not fit."],"explain":null,"unit":3,"day":4,"step":"drill"},"n5u03d4.d5":{"id":"n5u03d4.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[山川|やまかわ]さんは[毎日|まいにち]バス","after":"よ。","tiles":["で","[学校|がっこう]","へ","[来|き]ます"],"star":2,"bank":[3,0,2,1],"hint":"First say how Ms. Yamakawa comes, then where she comes to, then the verb.","full":"[山川|やまかわ]さんは[毎日|まいにち]バス{で}[学校|がっこう]へ[来|き]ますよ。","explain":"バスで is how she comes. 学校へ is where she comes to, and 来ます goes last, right before よ.","unit":3,"day":4,"step":"drill"},"n5u03d4.d6":{"id":"n5u03d4.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[中山|なかやま]さんはいつも[駅|えき]の[前|まえ]の[店|みせ]","after":"。","tiles":["で","パン","を","[買|か]います"],"star":0,"bank":[2,3,0,1],"hint":"The shop is where the action happens. Then what is bought, then the verb.","full":"[中山|なかやま]さんはいつも[駅|えき]の[前|まえ]の[店|みせ]{で}パンを[買|か]います。","explain":"店で is where Mr. Nakayama buys. パンを is what he buys, and 買います comes last.","unit":3,"day":4,"step":"drill"},"n5u03d4.e1":{"id":"n5u03d4.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きのう　デパート（　　）　くつを　買いました。","options":["を","へ","に","で"],"answer":4,"explain":"Buying is an action, so the place where you buy takes で: デパートで 買いました. に would say where something is, くつを already has を, and へ shows the direction you go to, which needs a verb like 行きました.","unit":3,"day":4,"step":"exam"},"n5u03d4.e2":{"id":"n5u03d4.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この　かみには　えんぴつ（　　）　名前を　書きます。","options":["へ","で","を","が"],"answer":2,"explain":"The pencil is what you write with, so it takes で. 名前を already has を, えんぴつが would make the pencil the writer, and へ shows a direction.","unit":3,"day":4,"step":"exam"},"n5u03d4.e3":{"id":"n5u03d4.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「きのう　学校","after":"か。」　B「カレーです。」","tiles":["で","何","を","食べました"],"star":0,"bank":[2,0,3,1],"full":"A「きのう　学校{で}　何を　食べましたか。」　B「カレーです。」","explain":"で, 何, を, 食べました: what did you eat at school yesterday? 学校で is where the eating happened, 何を asks what was eaten, and B answers カレーです.","unit":3,"day":4,"step":"exam"},"n5u03d4.k1":{"id":"n5u03d4.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"土よう日の　_午後_は　日本語の　クラスが　あります。","options":["ごこう","ごぜん","こご","ごご"],"answer":4,"explain":"午後 is ごご, afternoon. ごぜん is 午前 (morning). こご and ごこう are not words; both kanji here are read ご.","unit":3,"day":4,"step":"scene"},"n5u03d4.r1":{"id":"n5u03d4.r1","kind":"choice","type":"読解・内容理解（短文）","q":"リンさんは　金よう日に　どこで　ひるごはんを　食べますか。","options":["学校の　前の　こうえん","えきの　前の　店","うち","学校の　しょくどう"],"short":["学校の前のこうえん","えきの前の店","うち","学校のしょくどう"],"answer":1,"explain":"Lin usually eats lunch in the school cafeteria, but the sentence after が says 金よう日は 学校の 前の こうえんで 食べます: on Fridays, in the park in front of the school.","why":["","The note does not talk about a shop by the station.","Lin reads books at home in the evening. The note does not say Lin eats lunch there.","That is where Lin usually eats, but not on Fridays."],"unit":3,"day":4,"step":"skill"},"n5u03d5.c1":{"id":"n5u03d5.c1","kind":"choice","type":"文の文法1","label":"まちあわせ","q":"A「あしたは^[何時|なんじ]^に[会|あ]い（　　）。」B「^[十時|じゅうじ]はどうですか^。」","options":["ませんか","ました","ましょうか"],"answer":3,"why":["ませんか invites, and the answer is yes or no. It does not go with a question word like 何時.","ました is the past, but A is talking about あした (tomorrow).","A asks \"what time shall we meet?\", and B suggests ten o'clock."],"unit":3,"day":5,"step":"compare"},"n5u03d5.d1":{"id":"n5u03d5.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「[日|にち]よう[日|び]、いっしょにテニスを（　　）。」B「^ええ、しましょう^。」","options":["しません","しませんでした","しませんか","しましたか"],"answer":3,"why":["しません says \"I won't play\". B answers ええ、しましょう, so A must have asked something.","しませんでした says \"I didn't play\". B's しましょう shows A is talking about a plan.","B says yes with しましょう, so A invited B: しませんか.","しましたか asks about the past. B's しましょう shows the tennis has not happened yet."],"explain":null,"unit":3,"day":5,"step":"drill"},"n5u03d5.d2":{"id":"n5u03d5.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「[駅|えき]の[前|まえ]の[店|みせ]でおちゃを[飲|の]みませんか。」B「^ええ^、（　　）。」","options":["[飲|の]みましょう","[飲|の]みませんか","[飲|の]みました","[飲|の]みません"],"answer":1,"why":["ええ says yes, and ましょう agrees: \"Yes, let's have some.\"","飲みませんか is A's invitation. B repeating it does not answer.","飲みました is the past. They have not had the tea yet.","ええ says yes, but 飲みません says \"I won't drink\". The two do not match."],"unit":3,"day":5,"step":"drill"},"n5u03d5.d3":{"id":"n5u03d5.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[先生|せんせい]「みなさん、^[今|いま]から^いっしょにこの[本|ほん]を[読|よ]み（　　）。」","options":["ましたか","ましょう","ました","ませんでした"],"answer":2,"why":["ましたか asks about the past. 今から talks about what happens next.","今から means \"from now\", so the teacher says \"let's read\": 読みましょう.","ました is the past. 今から talks about what happens next.","ませんでした is the past too, and does not fit 今から."],"explain":null,"unit":3,"day":5,"step":"drill"},"n5u03d5.d4":{"id":"n5u03d5.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あした、うちへ[来|き]（　　）。」B「^ええ、ありがとうございます^。」","options":["ませんか","ましたか","ません","ました"],"answer":1,"why":["B thanks A, so A invited B: \"Won't you come to my house?\"","ましたか asks about the past, but A says あした, tomorrow.","来ません says \"I won't come\". B would not say thank you to that.","ました is the past, but A says あした, tomorrow."],"unit":3,"day":5,"step":"drill"},"n5u03d5.d5":{"id":"n5u03d5.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「[土|ど]よう[日|び]に、いっしょに","after":"。」B「いいですね。[行|い]きましょう。」","tiles":["[山|やま]","へ","[行|い]き","ませんか"],"star":2,"bank":[3,1,0,2],"hint":"へ comes right after the place. ませんか joins the verb without ます.","full":"A「[土|ど]よう[日|び]に、いっしょに[山|やま]へ[行|い]き{ませんか}。」B「いいですね。[行|い]きましょう。」","explain":"山 is the place, so へ follows it. 行き is 行きます without ます, and ませんか joins it to make the invitation.","unit":3,"day":5,"step":"drill"},"n5u03d5.d6":{"id":"n5u03d5.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「どこで[会|あ]いましょうか。」B「[駅|えき]の","after":"。」","tiles":["[入口|いりぐち]","の","[前|まえ]で","[会|あ]いましょう"],"star":2,"bank":[2,3,1,0],"hint":"B answers with a place. Which word can follow 駅の? The verb comes last.","full":"A「どこで[会|あ]いましょうか。」B「[駅|えき]の[入口|いりぐち]の[前|まえ]で{[会|あ]いましょう}。」","explain":"駅の入口 is the station entrance, and の joins it to 前で: in front of the entrance. 会いましょう answers A's 会いましょうか.","unit":3,"day":5,"step":"drill"},"n5u03d5.e1":{"id":"n5u03d5.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あした　わたしの　うちで　いっしょに　ばんごはんを　（　　）。」B「ありがとうございます。」","options":["食べましたか","食べませんでした","食べました","食べませんか"],"answer":4,"explain":"A invites B for tomorrow, and B says thank you, so 食べませんか. The other three are past forms and do not fit あした.","unit":3,"day":5,"step":"exam"},"n5u03d5.e2":{"id":"n5u03d5.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あしたは　どこで　（　　）。」B「駅の　入口は　どうですか。」","options":["会いませんか","会いました","会いましたか","会いましょうか"],"answer":4,"explain":"A asks where to meet tomorrow, and B suggests a place: 会いましょうか, \"shall we meet?\" 会いませんか does not go with どこ. 会いました is not a question, and 会いましたか asks about the past.","unit":3,"day":5,"step":"exam"},"n5u03d5.e3":{"id":"n5u03d5.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「土よう日に　いっしょに　","after":"。」B「いいですね。」","tiles":["花見","に","行き","ませんか"],"star":2,"bank":[1,3,0,2],"full":"A「土よう日に　いっしょに　花見に行き{ませんか}。」B「いいですね。」","explain":"花見, に, 行き, ませんか. に after 花見 says where you go, and ませんか joins 行き to invite.","unit":3,"day":5,"step":"exam"},"n5u03d5.k1":{"id":"n5u03d5.k1","kind":"choice","type":"表記","label":"How the exam asks it","q":"花見は　_ごご_　一時からです。","options":["五後","午後","午前","後午"],"answer":2,"explain":"ごご is written 午後: 午 \"noon\" and 後 \"after\". 午前 is ごぜん, the morning. 後午 and 五後 are not words.","unit":3,"day":5,"step":"scene"},"n5u03d5.r1":{"id":"n5u03d5.r1","kind":"choice","type":"即時応答","q":"女：土よう日、いっしょに　花見に　行きませんか。","script":["女：土よう日、いっしょに花見に行きませんか。","ナレーター：1","男：ええ、行きませんか。","ナレーター：2","男：はい、行きませんでした。","ナレーター：3","男：すみません、土よう日はちょっと…。"],"options":["ええ、行きませんか。","はい、行きませんでした。","すみません、土よう日は　ちょっと…。"],"printed":false,"short":["ええ、行きませんか","はい、行きませんでした","土よう日はちょっと…"],"answer":3,"why":["ええ says yes, but 行きませんか is an invitation. To say yes, he would say 行きましょう.","行きませんでした is the past, \"I didn't go\". She is asking about this Saturday.","A polite no: he says sorry and ちょっと… instead of a flat いいえ."],"unit":3,"day":5,"step":"skill","clip":"l_n5u3d5"},"n5u03d6.c1":{"id":"n5u03d6.c1","kind":"choice","type":"文の文法1","label":"まちで","q":"[学校|がっこう]の[前|まえ]（　　）^きっさてんがあります^。","options":["に","を","で"],"answer":1,"why":["With あります, the place where a thing is takes に: 学校の前に.","を marks the thing an action is done to. あります is not that kind of verb, and the café already has が.","で marks where you do something. あります only says where the café is, so the place takes に."],"explain":null,"unit":3,"day":6,"step":"compare"},"n5u03d6.d1":{"id":"n5u03d6.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「^きのう^、[中川|なかがわ]さんと[山|やま]へ（　　）。」B「はい、^[行|い]きました^。」","options":["[行|い]きます","[行|い]きましたか","[行|い]きませんか","[行|い]きましょう"],"answer":2,"why":["行きます is not past, so it does not fit きのう, and without か it is not a question.","きのう is past and B answers はい, 行きました, so A asked about the past: 行きましたか.","行きませんか invites someone to go later. You cannot invite someone to yesterday.","行きましょう suggests going later, and B's はい, 行きました does not answer a suggestion."],"explain":null,"unit":3,"day":6,"step":"drill"},"n5u03d6.d2":{"id":"n5u03d6.d2","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"[母|はは]は[月|げつ]よう[日|び]と[木|もく]よう[日|び]にデパート（　　）^はたらきます^。","options":["で","へ","を","に"],"answer":1,"why":["The department store is where she does the work, so で: デパートではたらきます.","へ marks where you go, with verbs like 行きます. はたらきます is something you do at a place.","を marks the thing an action is done to. デパート is where she works, not what she works on.","に goes with verbs like 行きます, 来ます or あります in this unit. はたらきます is an action done there, so it takes で."],"explain":null,"unit":3,"day":6,"step":"drill"},"n5u03d6.d3":{"id":"n5u03d6.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「つめたいジュースがありますよ。[飲|の]み（　　）。」B「^ありがとうございます^。いただきます。」","options":["ましたか","ませんでした","ませんか","ません"],"answer":3,"why":["飲みましたか asks about the past. B's いただきます takes a drink now.","飲みませんでした says \"I didn't drink\". It is not an offer, so B's thanks do not fit.","A offers a drink: 飲みませんか, \"won't you have some?\" B thanks A and takes it.","飲みません says \"I don't drink\". B would not thank A for that."],"explain":null,"unit":3,"day":6,"step":"drill"},"n5u03d6.d4":{"id":"n5u03d6.d4","kind":"choice","type":"文の文法1","label":"Choose the phrase","q":"A「^きのう^、[何|なに]をしましたか。」B「[友|とも]だちと[駅|えき]の[前|まえ]のデパート（　　）。」","options":["にごはんを[食|た]べません","でごはんを[食|た]べました","へごはんを[食|た]べました","でごはんを[食|た]べます"],"answer":2,"why":["に does not mark where you eat, and 食べません is neither past nor an answer to \"what did you do\".","The store is where they ate, so で, and きのう needs the past: 食べました.","へ marks where you go. 食べました is done at the store, so the place takes で.","で is right, but 食べます is not past. A asked about きのう."],"explain":null,"unit":3,"day":6,"step":"drill"},"n5u03d6.d5":{"id":"n5u03d6.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「[金|きん]よう[日|び]の[午後|ごご]、","after":"。」B「いいですね。[会|あ]いましょう。」","tiles":["[駅|えき]の","[中|なか]の","きっさてんで","[会|あ]いませんか"],"star":2,"bank":[2,3,1,0],"hint":"Where is the café? Start with the biggest place. The invitation comes last.","full":"A「[金|きん]よう[日|び]の[午後|ごご]、[駅|えき]の[中|なか]の{きっさてんで}[会|あ]いませんか。」B「いいですね。[会|あ]いましょう。」","explain":"駅の中の describes the café: the one inside the station. きっさてんで says where you meet, so it takes で, and 会いませんか invites. B says yes with 会いましょう.","unit":3,"day":6,"step":"drill"},"n5u03d6.d6":{"id":"n5u03d6.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[先週|せんしゅう]の[金|きん]よう[日|び]、うちに","after":"。","tiles":["[父|ちち]の","[会社|かいしゃ]の","[人|ひと]が","[来|き]ました"],"star":1,"bank":[3,1,2,0],"hint":"Whose company? Which person? 先週 tells you the time, and the verb comes last.","full":"[先週|せんしゅう]の[金|きん]よう[日|び]、うちに[父|ちち]の{[会社|かいしゃ]の}[人|ひと]が[来|き]ました。","explain":"父の会社の人 is someone from father's company. 人が is the one who came, うちに is where they came to, and 先週 needs the past: 来ました.","unit":3,"day":6,"step":"drill"},"n5u03d6.e1":{"id":"n5u03d6.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きのう　デパートへ　行きましたが、何も　（　　）。","options":["買いましょう","買いませんでした","買いました","買いませんか"],"answer":2,"explain":"何も with a negative means \"nothing\", and きのう needs the past: 何も買いませんでした. 買いました is not negative, so it does not go with 何も. 買いませんか invites and 買いましょう suggests; neither fits a story about yesterday.","unit":3,"day":6,"step":"exam"},"n5u03d6.e2":{"id":"n5u03d6.e2","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"A「日よう日、いっしょに　こうえん（　　）　テニスを　しませんか。」\nB「ええ、しましょう。」","options":["に","で","へ","を"],"answer":2,"explain":"The park is where you play tennis, so で: こうえんで　テニスを　します. へ marks where you go, with 行きます. を already marks テニス. に would need a verb like 行きます or あります.","unit":3,"day":6,"step":"exam"},"n5u03d6.e3":{"id":"n5u03d6.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「きのう　ばんごはんは　どこで　食べましたか。」B「","after":"。」","tiles":["友だちの","うち","で","食べました"],"star":1,"bank":[2,0,3,1],"full":"A「きのう　ばんごはんは　どこで　食べましたか。」B「友だちの　{うち}で　食べました。」","explain":"友だちの, うち, で, 食べました. 友だちの needs a noun after it, うち. で follows the place where they ate, and the verb comes last in the past, like A's question.","unit":3,"day":6,"step":"exam"},"n5u03d6.k1":{"id":"n5u03d6.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"日本語の　クラスは　_九時半_に　はじまります。","options":["きゅうじぱん","くじはん","きゅうじはん","くじばん"],"answer":2,"explain":"九時半 is くじはん: nine o'clock is くじ, and 半 is はん. きゅうじ is not used for the time, and 半 does not change to ばん or ぱん after 時.","unit":3,"day":6,"step":"scene"},"n5u03d6.r1":{"id":"n5u03d6.r1","kind":"choice","type":"読解・情報検索","q":"学生は　金よう日に　何時に　学校へ　来ますか。","options":["午前九時","十二時","午後一時","三時半"],"short":["9:00","12:00","1:00","3:30"],"answer":3,"explain":"Under 金よう日, the morning is 休み, and the film starts at 午後一時. So the students come at one in the afternoon.","why":["Nine o'clock is the start time from Monday to Thursday. On Friday the morning is off.","Twelve is when the Monday to Thursday class ends.","","Half past three is when the Friday film ends, not when students arrive."],"unit":3,"day":6,"step":"skill"},"n5u03t.1":{"id":"n5u03t.1","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"_先週_は　雨が　よく　ふりました。","options":["せいしゅう","せんしゅう","せんしゅ","さきしゅう"],"answer":2,"explain":"先週 is せんしゅう, last week. せんしゅ has a short しゅ in place of しゅう, so it is a different word. さきしゅう uses さき, the reading of 先 when it stands alone, and せいしゅう has せい in place of せん; neither is a word.","unit":3,"step":"test"},"n5u03t.2":{"id":"n5u03t.2","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"よる　うちで　日本の　うたを　_聞きます_。","options":["おきます","ききます","かきます","いきます"],"answer":2,"explain":"聞きます is ききます, listen. かきます is 書きます (write), いきます is 行きます (go), and おきます is get up. None of them is read from 聞, and you listen to a song.","unit":3,"step":"test"},"n5u03t.3":{"id":"n5u03t.3","kind":"choice","type":"表記","label":"Kanji spelling","q":"駅の　_きたぐち_で　友だちを　まちます。","options":["北日","東口","南口","北口"],"answer":4,"explain":"きたぐち is 北口: 北 (north) with 口 (exit). 北日 has 日 (day) in place of 口, and it is not a word. 東口 is ひがしぐち (east exit) and 南口 is みなみぐち (south exit); they are real words but not read きたぐち.","unit":3,"step":"test"},"n5u03t.4":{"id":"n5u03t.4","kind":"choice","type":"表記","label":"Kanji spelling","q":"母に　てがみを　_かきます_。","options":["言きます","話きます","読きます","書きます"],"answer":4,"explain":"かきます (write) is 書きます. 言 is the い of 言います (say), 話 is the はな of 話します (speak), and 読 is the よ of 読みます (read). None of them is read か, so 言きます, 話きます and 読きます are not words.","unit":3,"step":"test"},"n5u03t.5":{"id":"n5u03t.5","kind":"choice","type":"文脈規定","label":"Word in context","q":"駅で　電車に　（　　）。","options":["おります","かいます","よみます","のります"],"answer":4,"explain":"電車に goes with のります: get on the train. おります (get off) takes を or から, as in 電車をおります, not に. かいます (buy) and よみます (read) do not take 電車に, and you do not buy or read a train.","unit":3,"step":"test"},"n5u03t.6":{"id":"n5u03t.6","kind":"choice","type":"文脈規定","label":"Word in context","q":"（　　）は　日よう日でした。あしたは　火よう日です。","options":["あさって","おととい","きのう","きょう"],"answer":3,"explain":"If tomorrow is Tuesday, today is Monday, so yesterday, きのう, was Sunday. おととい (the day before yesterday) was Saturday. きょう is Monday, and it does not go with the past でした. あさって (the day after tomorrow) is in the future, so it cannot take でした.","unit":3,"step":"test"},"n5u03t.7":{"id":"n5u03t.7","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"_まいばん_　日本語の　本を　読みます。","options":["よるは　ときどき　日本語の　本を　読みます。","よるは　日本語の　本を　読みません。","あさは　いつも　日本語の　本を　読みます。","よるは　いつも　日本語の　本を　読みます。"],"answer":4,"explain":"まいばん means every evening, so it is the same as よるは いつも (in the evening, always). Option 3 says in the morning. Option 1 says only sometimes (ときどき). Option 2 says the person does not read in the evening.","unit":3,"step":"test"},"n5u03t.8":{"id":"n5u03t.8","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"きょうは　_しごとを　休みます_。","options":["きょうは　会社で　はたらきます。","きょうは　会社に　います。","きょうは　会社へ　行きます。","きょうは　会社へ　行きません。"],"answer":4,"explain":"しごとを 休みます means taking the day off work, so the person does not go to the office: 会社へ 行きません. Option 3 says the opposite. Options 1 and 2 say the person works or is at the office today.","unit":3,"step":"test"},"n5u03t.9":{"id":"n5u03t.9","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「パクさんは　おさけを　飲みますか。」B「いいえ、おさけは　（　　）。」","options":["飲みませんでした","飲みましょう","飲みます","飲みません"],"answer":4,"explain":"A asks about a habit with 飲みますか, and B says いいえ, so B answers with the polite no ending: 飲みません. 飲みます is a yes answer, which does not follow いいえ. 飲みませんでした is about one time in the past, but A did not ask about the past. 飲みましょう (let's drink) is a suggestion, not an answer about B's habit.","unit":3,"step":"test"},"n5u03t.10":{"id":"n5u03t.10","kind":"choice","type":"文の文法1","label":"Choose the form","q":"けさは　じかんが　ありませんでしたから、あさごはんを　（　　）。","options":["食べませんでした","食べません","食べましょう","食べました"],"answer":1,"explain":"けさ (this morning) is past, and there was no time, so the person did not eat: 食べませんでした. 食べました says the person ate, which does not follow \"there was no time\". 食べません is not past, so it does not fit けさ. 食べましょう (let's eat) is a suggestion, not something that happened.","unit":3,"step":"test"},"n5u03t.11":{"id":"n5u03t.11","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"きのう　としょかんで　本（　　）　二さつ　かりました。","options":["が","に","へ","を"],"answer":4,"explain":"本 is the thing you borrow, so it takes を: 本を かりました. が would make the book the one who borrows. に and へ mark a person or a place, not the thing you borrow.","unit":3,"step":"test"},"n5u03t.12":{"id":"n5u03t.12","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"A「きのうは　何時に　うち（　　）　かえりましたか。」B「十時ごろです。」","options":["と","へ","を","で"],"answer":2,"explain":"うち is where you go back to, and the place you go to takes へ: うちへ かえりました. を does not mark the place you go back to. で marks where you do something, not where you go. と means \"with\", and you do not go home with your home.","unit":3,"step":"test"},"n5u03t.13":{"id":"n5u03t.13","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"日よう日は　こうえん（　　）　友だちと　テニスを　しました。","options":["に","で","を","へ"],"answer":2,"explain":"The park is where they played tennis, and the place of an action takes で: こうえんで テニスを しました. に marks where something is (こうえんに 木が あります) or where you go, but しました is an action. を is already on テニス, and へ marks where you go, which does not fit しました.","unit":3,"step":"test"},"n5u03t.14":{"id":"n5u03t.14","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"わたしは　毎日　じてんしゃ（　　）　駅まで　行きます。","options":["に","が","で","を"],"answer":3,"explain":"A bicycle is how the person goes, and the thing you use takes で: じてんしゃで 行きます. を would make the bicycle the thing you go, which does not make sense. に is for getting on (じてんしゃに のります), not with 行きます. が would make the bicycle the one who goes.","unit":3,"step":"test"},"n5u03t.15":{"id":"n5u03t.15","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　りんご、おいしいですよ。一つ　食べ（　　）。」B「ありがとうございます。いただきます。」","options":["ませんか","ました","ませんでした","ましたか"],"answer":1,"explain":"B thanks A and says いただきます, so A is offering an apple: 食べませんか (won't you have one?). 食べました and 食べませんでした tell what A did, and B would not thank A for that. 食べましたか asks if B already ate one, and ありがとうございます is not an answer to that question.","unit":3,"step":"test"},"n5u03t.16":{"id":"n5u03t.16","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「ケンさん、来週は　何を　しますか。」B「来週の　","after":"。」A「そうですか。いいですね。」","tiles":["土よう日に","国","へ","かえります"],"star":2,"bank":[3,2,0,1],"full":"A「ケンさん、来週は　何を　しますか。」B「来週の　土よう日に　国{へ}　かえります。」A「そうですか。いいですね。」","explain":"土よう日に, 国, へ, かえります. 来週の needs a noun after it, and only 土よう日 fits (来週の土よう日, Saturday next week). へ comes right after the place you go, 国, and the verb かえります ends the sentence.","unit":3,"step":"test"},"n5u03t.17":{"id":"n5u03t.17","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「きれいな　しゃしんですね。」B「ありがとうございます。","after":"　とりました。」","tiles":["父","の","古い","カメラで"],"star":2,"bank":[2,3,1,0],"full":"A「きれいな　しゃしんですね。」B「ありがとうございます。父の　{古い}　カメラで　とりました。」","explain":"父, の, 古い, カメラで. 父の goes before the thing that is his, and 古い describes the camera, so it comes right before カメラで: my father's old camera. 古い cannot come before 父, because 古い is for things, not people. カメラで, with で for the thing you use, comes right before とりました.","unit":3,"step":"test"},"n5u03t.18":{"id":"n5u03t.18","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「つかれましたね。あの　","after":"　少し　休みませんか。」B「ええ、そうしましょう。」","tiles":["大きい","木","の","下で"],"star":1,"bank":[3,1,0,2],"full":"A「つかれましたね。あの　大きい　{木}の　下で　少し　休みませんか。」B「ええ、そうしましょう。」","explain":"大きい, 木, の, 下で. 大きい describes 木 (that big tree). 木の下 is \"under the tree\", and 下で, with で for the place where you do something, goes before 休みませんか. 大きい cannot describe 下, so 木の大きい下 does not work.","unit":3,"step":"test"},"n5u03t.19":{"id":"n5u03t.19","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"きのうは　日よう日でした。午前は　うちで　そうじを　しました。午後は　友だちと　電車で　こうえんへ　行きました。こうえんの　花は　とても　きれいでした。よるは　テレビを　見ませんでした。日本語の　本を　読みました。","q":"この　人は　きのうの　よる　何を　しましたか。","options":["そうじを　しました。","テレビを　見ました。","日本語の　本を　読みました。","友だちと　こうえんへ　行きました。"],"answer":3,"short":["そうじ","テレビ","日本語の本","こうえん"],"explain":"The writer says よるは テレビを 見ませんでした。日本語の 本を 読みました: in the evening the writer read a Japanese book. The cleaning was in the morning (午前). The writer did not watch TV (見ませんでした). The trip to the park with a friend was in the afternoon (午後).","unit":3,"step":"test"},"n5u03t.20":{"id":"n5u03t.20","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"きのうは　日よう日でした。午前は　うちで　そうじを　しました。午後は　友だちと　電車で　こうえんへ　行きました。こうえんの　花は　とても　きれいでした。よるは　テレビを　見ませんでした。日本語の　本を　読みました。","q":"ただしい　ものは　どれですか。","options":["ひとりで　こうえんへ　行きました。","バスで　こうえんへ　行きました。","こうえんの　花は　きれいじゃ　ありませんでした。","午前は　うちに　いました。"],"answer":4,"short":["ひとりで","バスで","花はきれいじゃない","午前はうち"],"explain":"The writer cleaned at home in the morning (午前は うちで そうじを しました), so the writer was at home. The writer went with a friend (友だちと), not alone, and by train (電車で), not by bus. The flowers were very pretty (とても きれいでした).","unit":3,"step":"test"},"n5u03t.21":{"id":"n5u03t.21","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"みどりセンター　土よう日の　クラス\n午前　十時から　十一時半まで　かんじ（二かい）\n午後　一時から　二時半まで　日本の　りょうり（一かい）\n午後　三時から　四時まで　日本の　うた（二かい）\nお金は　いりません。\n日よう日は　休みです。","q":"キムさんは　りょうりの　クラスに　行きます。何時に　何かいへ　行きますか。","options":["十時に　二かい","一時に　一かい","一時に　二かい","三時に　一かい"],"answer":2,"short":["十時 二かい","一時 一かい","一時 二かい","三時 一かい"],"explain":"The cooking class (日本の りょうり) is from 一時 on 一かい. 十時 on 二かい is the kanji class. 二かい is the floor of the kanji and song classes, not the cooking class. 三時 is when the song class starts.","unit":3,"step":"test"},"n5u03t.22":{"id":"n5u03t.22","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"みどりセンター　土よう日の　クラス\n午前　十時から　十一時半まで　かんじ（二かい）\n午後　一時から　二時半まで　日本の　りょうり（一かい）\n午後　三時から　四時まで　日本の　うた（二かい）\nお金は　いりません。\n日よう日は　休みです。","q":"アンナさんは　土よう日の　午後　二時半から　ひまです。どの　クラスに　行きますか。","options":["うたの　クラス","日よう日の　クラス","かんじの　クラス","りょうりの　クラス"],"answer":1,"short":["うた","日よう日","かんじ","りょうり"],"explain":"From 二時半 the only class that has not started yet is the song class, from 三時 to 四時. The kanji class is in the morning, and the cooking class ends at 二時半. There is no Sunday class, because 日よう日は 休みです.","unit":3,"step":"test"},"n5u03t.23":{"id":"n5u03t.23","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ケンさん\n来週の　土よう日に　こうえんで　テニスを　しませんか。わたしは　午前は　しごとが　ありますから、午後　一時から　しましょう。こうえんまでは　駅から　バスで　行きましょう。十二時半に　駅の　南口で　会いましょう。\nたなか","q":"二人は　土よう日、何時に　どこで　会いますか。","options":["十二時半に　駅の　南口で","一時に　駅の　南口で","十二時半に　こうえんで","一時に　こうえんで"],"answer":1,"short":["十二時半 南口","一時 南口","十二時半 こうえん","一時 こうえん"],"explain":"たなか writes 十二時半に 駅の 南口で 会いましょう. 一時 is when the tennis starts, not when they meet. They meet at the station and then go to the park by bus, so they do not meet at the park.","unit":3,"step":"test"},"n5u03t.24":{"id":"n5u03t.24","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ケンさん\n来週の　土よう日に　こうえんで　テニスを　しませんか。わたしは　午前は　しごとが　ありますから、午後　一時から　しましょう。こうえんまでは　駅から　バスで　行きましょう。十二時半に　駅の　南口で　会いましょう。\nたなか","q":"ただしい　ものは　どれですか。","options":["たなかさんは　土よう日の　午前　しごとが　あります。","二人は　こうえんの　入口で　会います。","テニスは　午前からです。","二人は　こうえんまで　あるいて　行きます。"],"answer":1,"short":["午前にしごと","こうえんの入口","テニスは午前","あるいて行く"],"explain":"たなか writes 午前は しごとが あります: there is work on Saturday morning. That is why the tennis is in the afternoon (午後 一時から), not the morning. They go to the park by bus (バスで), not on foot. They meet at the station's south exit (駅の 南口), not at the park entrance.","unit":3,"step":"test"},"n5u04d1.c1":{"id":"n5u04d1.c1","kind":"choice","type":"文の文法1","label":"へやのはなし","q":"A「このへや、どうですか。」\nB「（　　）ですね。」","options":["きれいなへや","きれいへや","きれいのへや"],"answer":1,"why":["きれい is a な-adjective, so it takes な before the noun へや.","きれい ends in い, but it is a な-adjective, not an い-adjective. It cannot join へや as it is.","の joins a noun to a noun. きれい is a な-adjective, so it takes な."],"unit":4,"day":1,"step":"compare"},"n5u04d1.d1":{"id":"n5u04d1.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「そのへやは[大|おお]きいですか。」\nB「^いいえ^、あまり（　　）。」","options":["[大|おお]きいです","[大|おお]きくないです","[大|おお]きいじゃありません","[大|おお]きくです"],"answer":2,"why":["B starts with いいえ, and あまり in the sense \"not very\" goes with a no ending. 大きいです is the yes form.","大きい is an い-adjective: the last い becomes く, then ないです. B says it is not very big.","じゃありません is the no ending for a noun or a な-adjective. 大きい is an い-adjective, so it becomes 大きくないです.","大きく needs ない after it. 大きくです is not a form."],"unit":4,"day":1,"step":"drill"},"n5u04d1.d2":{"id":"n5u04d1.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「[駅|えき]の[前|まえ]のレストランはどうですか。」\nB「^あまり^（　　）。[高|たか]いです。」","options":["いくないです","よくないです","いいじゃありません","いいです"],"answer":2,"why":["いい is special: its no form is よくないです. いくないです is not a form.","B is not happy with the restaurant: あまりよくないです, it is not very good. The no form of いい is よくないです.","じゃありません is for a noun or a な-adjective. いい is an い-adjective, and its no form is よくないです.","あまり in the sense \"not very\" goes with a no ending, and B goes on to say it is expensive."],"explain":null,"unit":4,"day":1,"step":"drill"},"n5u04d1.d3":{"id":"n5u04d1.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「[中山|なかやま]さんのへやはしずかですか。」\nB「^いいえ^、（　　）。」","options":["しずかじゃありません","しずかないです","しずかです","しずかくないです"],"answer":1,"why":["しずか is a な-adjective, so the no form is しずかじゃありません.","しずかないです is not a form. A な-adjective takes じゃありません.","しずかです means yes, it is quiet. B starts with いいえ.","くないです is the no ending for an い-adjective. しずか is a な-adjective, so it takes じゃありません."],"explain":null,"unit":4,"day":1,"step":"drill"},"n5u04d1.d4":{"id":"n5u04d1.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[駅|えき]のちかくに^しずか^（　　）こうえんがあります。","options":["い","です","な","の"],"answer":3,"why":["しずか is a な-adjective. It has no い, so しずかい is not a word.","です ends a sentence. It does not come between しずか and the noun こうえん.","しずか is a な-adjective, so it takes な before the noun こうえん.","の joins a noun to a noun. しずか is a な-adjective, so it takes な."],"explain":null,"unit":4,"day":1,"step":"drill"},"n5u04d1.d5":{"id":"n5u04d1.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[駅|えき]の[前|まえ]に","after":"。","tiles":["[新|あたら]しい","[店|みせ]","が","あります"],"star":1,"bank":[2,0,3,1],"hint":"The い-adjective goes right before the noun it describes. Then が and the verb.","full":"[駅|えき]の[前|まえ]に{[新|あたら]しい}[店|みせ]があります。","explain":"新しい is an い-adjective, so it goes right before 店 with nothing between them. が marks the thing that is there, and あります ends the sentence.","unit":4,"day":1,"step":"drill"},"n5u04d1.d6":{"id":"n5u04d1.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"このへやは","after":"。","tiles":["あまり","しずか","じゃ","ありません"],"star":1,"bank":[3,1,0,2],"hint":"あまり comes before the describing word. The no ending comes last.","full":"このへやはあまりしずか{じゃありません}。","explain":"あまり goes before しずか: not very quiet. しずか is a な-adjective, so its no ending じゃありません follows it at the end.","unit":4,"day":1,"step":"drill"},"n5u04d1.e1":{"id":"n5u04d1.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「その　カメラ、高いですか。」\nB「いいえ、あまり　（　　）。」","options":["高くないです","高くないですか","高いです","高いじゃありません"],"answer":1,"explain":"B says いいえ, and あまり in the sense \"not very\" goes with a no ending. 高い is an い-adjective, so it becomes 高くないです. 高いです is the yes form. じゃありません is for a noun or a な-adjective, not an い-adjective. 高くないですか is a question, but B is answering.","unit":4,"day":1,"step":"exam"},"n5u04d1.e2":{"id":"n5u04d1.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「中山さんの　へやは　きれいですか。」\nB「いいえ、あまり　（　　）。」","options":["きれいじゃありません","きれくないです","きれいくないです","きれいです"],"answer":1,"explain":"きれい ends in い, but it is a な-adjective, so its no form is きれいじゃありません. B says いいえ and あまり, so the yes form きれいです does not fit. きれくないです and きれいくないです treat きれい as an い-adjective, which it is not.","unit":4,"day":1,"step":"exam"},"n5u04d1.e3":{"id":"n5u04d1.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"山川さんは　","after":"です。","tiles":["とても","きれい","な","人"],"star":1,"bank":[2,3,0,1],"full":"山川さんは　とても　きれい{な}人です。","explain":"とても, きれい, な, 人. とても goes before the describing word: very pretty. きれい is a な-adjective, so な joins it to the noun 人. Ms. Yamakawa is a very pretty person.","unit":4,"day":1,"step":"exam"},"n5u04d1.k1":{"id":"n5u04d1.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"この　アパートは　_新しい_です。","options":["あらたしい","あたしい","あたらしい","しんしい"],"answer":3,"explain":"新しい is あたらしい. あらたしい swaps two sounds, あたしい drops ら, and しんしい uses シン, another reading of 新, but 新しい is never read that way.","unit":4,"day":1,"step":"scene"},"n5u04d1.r1":{"id":"n5u04d1.r1","kind":"choice","type":"発話表現","q":"友だちに　あいました。何と　いいますか。","script":["ナレーター：友だちに　あいました。何と　いいますか。","ナレーター：1","男：きょうは　さむいですね。","ナレーター：2","男：きょうは　あついですね。","ナレーター：3","男：きょうは　あつくないですね。"],"options":["きょうは　さむいですね。","きょうは　あついですね。","きょうは　あつくないですね。"],"printed":false,"short":["さむいですね","あついですね","あつくないですね"],"answer":2,"why":["さむい means cold. It is a sunny summer day and he is wiping sweat.","","あつくないです means it is not hot. The man is sweating, so it is hot."],"unit":4,"day":1,"step":"skill","clip":"l_n5u4d1"},"n5u04d2.c1":{"id":"n5u04d2.c1","kind":"choice","type":"文の文法1","label":"きのうのテスト","q":"A：きのうのテストはどうでしたか。B：（　　）。","options":["やさしかったです","やさしいでした","やさしいです"],"answer":1,"why":["The test was yesterday, and やさしい is an い-adjective: the past is やさしかったです.","やさしい is an い-adjective. It changes itself for the past; でした does not go after it.","やさしいです is about now. A asks どうでしたか about yesterday's test."],"unit":4,"day":2,"step":"compare"},"n5u04d2.d1":{"id":"n5u04d2.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^きのう^は、とてもさむ（　　）。","options":["いでした","かったです","かったでした","いです"],"answer":2,"why":["さむい is an い-adjective. でした does not go after it.","きのう is the past, and さむい is an い-adjective: さむかったです.","かった already makes the past. Add only です, not でした.","さむいです is about now. きのう points to the past."],"explain":null,"unit":4,"day":2,"step":"drill"},"n5u04d2.d2":{"id":"n5u04d2.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：きのうのえいがは、どうでしたか。B：^とても^（　　）。","options":["いいでした","よかったです","いかったです","よくなかったです"],"answer":2,"why":["いい is an い-adjective. でした does not go after it.","The past of いい is よかったです. とても よかったです means \"it was very good\".","いい changes to よ in the past: よかったです. いかったです is not a word.","とても goes with a yes form here. For \"not very good\" you say あまりよくなかったです."],"unit":4,"day":2,"step":"drill"},"n5u04d2.d3":{"id":"n5u04d2.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^[先週|せんしゅう]の[土|ど]よう[日|び]^は、[雨|あめ]（　　）。","options":["かったです","じゃありません","です","でした"],"answer":4,"why":["かったです is only for い-adjectives. 雨 is a noun.","じゃありません is not past, and it says it was not rain. For last Saturday you need a past form.","雨です is about now. 先週の土よう日 is in the past.","雨 is a noun, and last Saturday is past: 雨でした."],"explain":null,"unit":4,"day":2,"step":"drill"},"n5u04d2.d4":{"id":"n5u04d2.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：きのうのこうえんは、しずかでしたか。B：^いいえ^、あまり（　　）。","options":["しずかじゃありませんでした","しずかくなかったです","しずかじゃありません","しずかでした"],"answer":1,"why":["いいえ to a question about yesterday, and しずか is a な-adjective: しずかじゃありませんでした.","しずか is a な-adjective. くなかったです is only for い-adjectives.","じゃありません is not past. The question is about yesterday, so add でした.","しずかでした means \"it was quiet\". It clashes with いいえ and あまり."],"explain":null,"unit":4,"day":2,"step":"drill"},"n5u04d2.d5":{"id":"n5u04d2.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"この","after":"。","tiles":["[店|みせ]の","ケーキは","あまり","おいしくなかったです"],"star":2,"bank":[2,3,0,1],"hint":"この needs a noun right after it. あまり goes just before the not form.","full":"この[店|みせ]のケーキはあまりおいし{くなかったです}。","explain":"この店の describes ケーキ, and ケーキは is the topic. あまり (not very) comes before おいしくなかったです, the past not form of おいしい.","unit":4,"day":2,"step":"drill"},"n5u04d2.d6":{"id":"n5u04d2.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[駅|えき]の[前|まえ]の","after":"。","tiles":["[店|みせ]は","あまり","きれい","じゃありませんでした"],"star":2,"bank":[3,1,0,2],"hint":"駅の前の needs a noun right after it. きれい is a な-adjective.","full":"[駅|えき]の[前|まえ]の[店|みせ]はあまりきれい{じゃありませんでした}。","explain":"駅の前の describes 店, the topic. あまり comes before the adjective, and きれい takes じゃありませんでした because it is a な-adjective.","unit":4,"day":2,"step":"drill"},"n5u04d2.e1":{"id":"n5u04d2.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きのうは　天気が　（　　）。","options":["いいです","いいでした","よかったです","いかったです"],"answer":3,"explain":"きのう is the past, and the past of いい is よかったです. いいでした puts でした after an い-adjective, いかったです is not a word, and いいです is about now.","unit":4,"day":2,"step":"exam"},"n5u04d2.e2":{"id":"n5u04d2.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：先週の　パーティーは　どうでしたか。B：とても　（　　）。","options":["にぎやかじゃありませんでした","にぎやかでした","にぎやかかったです","にぎやかいでした"],"answer":2,"explain":"にぎやか is a な-adjective, and the party was last week: にぎやかでした. かったです is only for い-adjectives, にぎやかい is not a word, and とても does not go with じゃありませんでした (say あまり for \"not very\").","unit":4,"day":2,"step":"exam"},"n5u04d2.e3":{"id":"n5u04d2.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"日よう日は　","after":"。","tiles":["とても","いい","天気","でした"],"star":2,"bank":[2,0,3,1],"full":"日よう日は　とても　いい　{天気}でした。","explain":"とても, いい, 天気, でした. とても describes いい, いい describes 天気, and 天気 is a noun, so でした comes after it.","unit":4,"day":2,"step":"exam"},"n5u04d2.k1":{"id":"n5u04d2.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"きのうは　_天気_が　よかったです。","options":["てんぎ","てんき","でんき","てんけ"],"answer":2,"explain":"天気 is read てんき. でんき is a different word (電気, electricity), and てんけ and てんぎ are not readings of 天気.","unit":4,"day":2,"step":"scene"},"n5u04d2.r1":{"id":"n5u04d2.r1","kind":"choice","type":"読解・内容理解（短文）","q":"この　人に　ついて、ただしい　ものは　どれですか。","options":["魚は　あまり　おいしくなかったです。","ホテルは　高くなかったです。","土よう日は　午後も　雨でした。","午後は　空が　きれいでした。"],"short":["魚はおいしくなかった","ホテルは高くなかった","午後も雨だった","午後は空がきれいだった"],"answer":4,"explain":"Rain was only in the morning (午前は雨でした). でも, in the afternoon the sky was very pretty (午後は空がとてもきれいでした).","why":["The writer says the fish was とてもおいしかったです (very good).","The writer says the hotel was ちょっと高かったです (a little expensive).","Only the morning was rainy. In the afternoon the sky was pretty.",""],"unit":4,"day":2,"step":"skill"},"n5u04d3.c1":{"id":"n5u04d3.c1","kind":"choice","type":"文の文法1","label":"レストランで","q":"あのレストランはきれい（　　）おいしいです。","options":["な","くて","で"],"answer":3,"why":["な goes right before a noun. おいしい is not a noun.","きれい ends in い, but it is a な-adjective, so きれいくて is wrong.","きれい is a な-adjective, and で joins it to おいしい."],"explain":null,"unit":4,"day":3,"step":"compare"},"n5u04d3.d1":{"id":"n5u04d3.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この[魚|さかな]は（　　）^おいしいです^。","options":["[安|やす]いで","[安|やす]くて","[安|やす]い","[安|やす]いくて"],"answer":2,"why":["安い is an い-adjective. い-adjectives never join with で.","安い drops its い and adds くて to join おいしい.","Two describing words cannot just sit side by side here. 安い needs to change to 安くて.","Drop the い first: 安くて, not 安いくて."],"unit":4,"day":3,"step":"drill"},"n5u04d3.d2":{"id":"n5u04d3.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この[店|みせ]は（　　）^しずかです^。","options":["きれいだ","きれいくて","きれいな","きれいで"],"answer":4,"why":["だ ends a sentence. It cannot join きれい to しずかです.","きれい is a な-adjective, even though it ends in い. It does not take くて.","な goes right before a noun. しずか is not a noun.","きれい is a な-adjective, and で joins it to しずかです."],"explain":null,"unit":4,"day":3,"step":"drill"},"n5u04d3.d3":{"id":"n5u04d3.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"マリアさんは^かいしゃいん^（　　）、[三十|さんじゅっ]さいです。","options":["で","な","の","くて"],"answer":1,"why":["かいしゃいん is a noun, and で joins it to the next part: \"she is an office worker and thirty\".","かいしゃいん is a noun. A noun does not take な.","の joins two nouns as \"the X's Y\". It cannot end the first part before the comma.","くて is only for い-adjectives. かいしゃいん is a noun."],"explain":null,"unit":4,"day":3,"step":"drill"},"n5u04d3.d4":{"id":"n5u04d3.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きょうは[天気|てんき]が（　　）、^きもちがいいです^。","options":["よくて","いいくて","いいで","いくて"],"answer":1,"why":["いい changes to よ before くて: よくて.","いい does not keep いい before くて. It becomes よくて.","いい is an い-adjective, so it never joins with で.","いくて is not a form of いい. いい becomes よくて."],"unit":4,"day":3,"step":"drill"},"n5u04d3.d5":{"id":"n5u04d3.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[駅|えき]の[前|まえ]に","after":"があります。","tiles":["[新|あたら]しくて","きれいな","パン","や"],"star":1,"bank":[2,0,3,1],"hint":"新しくて needs another describing word after it. Which word is the shop?","full":"[駅|えき]の[前|まえ]に[新|あたら]しくてきれいなパンやがあります。","explain":"新しくて joins to the next describing word, きれいな. きれいな goes right before the noun パンや, \"bakery\": 駅の前に新しくてきれいなパンやがあります, \"There is a new, nice bakery in front of the station.\"","unit":4,"day":3,"step":"drill"},"n5u04d3.d6":{"id":"n5u04d3.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あした、[友|とも]だちと","after":"へ[行|い]きます。","tiles":["きれい","で","[新|あたら]しい","レストラン"],"star":1,"bank":[3,1,0,2],"hint":"で comes right after a な-adjective. The place you go to comes right before へ.","full":"あした、[友|とも]だちときれい{で}[新|あたら]しいレストランへ[行|い]きます。","explain":"きれい is a な-adjective, so で follows it. 新しい goes right before レストラン, the place before へ: \"Tomorrow I am going to a nice, new restaurant with a friend.\"","unit":4,"day":3,"step":"drill"},"n5u04d3.e1":{"id":"n5u04d3.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：新しい　先生は　どんな　人ですか。　B：とても　（　　）　おもしろいですよ。","options":["げんきくて","げんきで","げんきな","げんきだ"],"answer":2,"explain":"げんき is a な-adjective, so it joins おもしろい with で. くて is only for い-adjectives, げんきな needs a noun right after it, and げんきだ cannot join two describing words.","unit":4,"day":3,"step":"exam"},"n5u04d3.e2":{"id":"n5u04d3.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この　白い　セーターは　（　　）　あたたかいです。","options":["安いくて","安くて","安い","安いで"],"answer":2,"explain":"安い is an い-adjective: drop the い and add くて. い-adjectives never take で, 安いくて keeps the い, and 安い cannot sit right before another describing word ending the sentence.","unit":4,"day":3,"step":"exam"},"n5u04d3.e3":{"id":"n5u04d3.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あの　パンやは","after":"です。","tiles":["パンが","おいしくて","店の人も","しんせつ"],"star":2,"bank":[3,0,2,1],"full":"あの　パンやは　パンが　おいしくて　{店の人も}　しんせつです。","explain":"パンが, おいしくて, 店の人も, しんせつ. おいしくて joins \"the bread is good\" to the next part, and しんせつ goes before です: \"At that bakery the bread is good, and the staff are kind too.\"","unit":4,"day":3,"step":"exam"},"n5u04d3.k1":{"id":"n5u04d3.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"すみません、この　魚を　_半分_　ください。","options":["ばんぶん","はんぷん","はんぶん","はんふん"],"answer":3,"explain":"半分, \"half\", is read はんぶん. 分 is ふん or ぷん in times (五分, 十分), but in 半分 it is ぶん. はんふん, ばんぶん and はんぷん are not words.","unit":4,"day":3,"step":"scene"},"n5u04d3.r1":{"id":"n5u04d3.r1","kind":"choice","type":"ポイント理解","q":"二人は　どの　店に　行きますか。","script":["ナレーター：男の人と女の人が話しています。二人はどの店に行きますか。","男：きょうのばんごはん、どこで食べますか。駅の前の新しい店はどうですか。","女：あの店はきれいで、いいですね。でも、高いですよ。","男：そうですか。じゃあ、大学の前の店は？カレーが安くておいしいですよ。","女：うーん、きのうもカレーを食べました。","男：じゃあ、川のそばの店はどうですか。しずかで、魚がおいしいですよ。","女：魚、いいですね。高いですか。","男：いいえ、あまり高くないです。","女：じゃあ、そこへ行きましょう。","ナレーター：二人はどの店に行きますか。"],"options":["大きくて　にぎやかな　店","しずかで　魚が　おいしい　店","カレーが　安くて　おいしい　店","新しくて　きれいな　店"],"printed":true,"short":["大きくて にぎやか","しずかで 魚が おいしい","カレーが 安くて おいしい","新しくて きれい"],"answer":2,"why":["Nobody talks about a big, lively shop.","The shop by the river is quiet and the fish is good, and it is not very expensive. The woman says そこへ行きましょう.","The curry is cheap and good, but the woman ate curry yesterday too (きのうもカレーを食べました).","The woman likes the new shop by the station (きれいで、いいですね), but it is expensive (でも、高いですよ)."],"explain":null,"unit":4,"day":3,"step":"skill","clip":"l_n5u4d3"},"n5u04d4.c1":{"id":"n5u04d4.c1","kind":"choice","type":"文の文法1","label":"テニスクラブ","q":"わたしはテニス（　　）^すきです^。[毎週|まいしゅう][土|ど]よう[日|び]にします。","options":["を","が","に"],"answer":2,"why":["With すきです, the thing you like takes が. テニスを goes with a verb like します.","The thing you like takes が before すきです.","テニスに does not say what you like."],"unit":4,"day":4,"step":"compare"},"n5u04d4.d1":{"id":"n5u04d4.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしはさむい[日|ひ]（　　）^きらいです^。","options":["に","を","が","で"],"answer":3,"why":["さむい日に would mean \"on cold days\", but then nothing says what you dislike.","With きらいです, the thing you dislike takes が, not を.","The thing you dislike takes が before きらいです: cold days.","さむい日で does not say what you dislike."],"explain":null,"unit":4,"day":4,"step":"drill"},"n5u04d4.d2":{"id":"n5u04d4.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしはやさいが（　　）。^だから、あまり[食|た]べません^。","options":["すきです","きらいです","じょうずです","へたです"],"answer":2,"why":["If you liked vegetables, you would not say あまり食べません.","You don't like vegetables, so you don't eat them much.","じょうず is for a skill. Vegetables are not a skill.","へた is for a skill too. Vegetables are not a skill."],"unit":4,"day":4,"step":"drill"},"n5u04d4.d3":{"id":"n5u04d4.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしはえが（　　）。^ねこをかきましたが、[友|とも]だちは「いぬ？」と[言|い]いました^。","options":["へたいです","じょうずです","へたです","じょうずなです"],"answer":3,"why":["へた is not an い word, so へたいです is not a word. Say へたです.","A friend thought the cat was a dog, so the drawing was not good.","The cat looked like a dog: the writer is bad at drawing.","な is not used before です. Say じょうずです."],"explain":null,"unit":4,"day":4,"step":"drill"},"n5u04d4.d4":{"id":"n5u04d4.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[中山|なかやま]さんはテニス（　　）^[上手|じょうず]です^。","options":["で","が","へ","を"],"answer":2,"why":["テニスで would make tennis a tool or a way to do something.","The skill takes が before じょうずです: good at tennis.","へ shows a direction you go to.","With じょうずです, the skill takes が, not を."],"explain":null,"unit":4,"day":4,"step":"drill"},"n5u04d4.d5":{"id":"n5u04d4.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[母|はは]は","after":"。","tiles":["[雨|あめ]の","[日|ひ]","が","きらいです"],"star":2,"bank":[1,3,0,2],"hint":"の joins two nouns: what kind of day? Then the particle for what she dislikes.","full":"[母|はは]は[雨|あめ]の[日|ひ]{がきらいです}。","explain":"雨の日 is a rainy day. It is what she dislikes, so が comes next, and きらいです goes last.","unit":4,"day":4,"step":"drill"},"n5u04d4.d6":{"id":"n5u04d4.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[父|ちち]は","after":"よ。","tiles":["[魚|さかな]の","りょうり","が","じょうずです"],"star":1,"bank":[2,3,1,0],"hint":"What kind of cooking? Then the particle for the skill, then the ending.","full":"[父|ちち]は[魚|さかな]のりょうり{がじょうずです}よ。","explain":"魚の describes りょうり: fish dishes. That is the skill, so が comes next, and じょうずです goes last, before よ.","unit":4,"day":4,"step":"drill"},"n5u04d4.e1":{"id":"n5u04d4.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは　山（　　）　すきです。毎週　山へ　行きます。","options":["が","で","へ","を"],"answer":1,"explain":"The thing you like takes が before すきです: 山が すきです. を does not go with すきです, 山で would be a place where you do something, and へ shows a direction you go to.","unit":4,"day":4,"step":"exam"},"n5u04d4.e2":{"id":"n5u04d4.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"リンさんは　えが　（　　）。リンさんの　えは　とても　きれいです。","options":["上手です","ひろいです","あまいです","下手です"],"answer":1,"explain":"Lin's pictures are very pretty, so Lin is good at drawing: 上手です. 下手です is the opposite. ひろい (wide) and あまい (sweet) do not describe a skill.","unit":4,"day":4,"step":"exam"},"n5u04d4.e3":{"id":"n5u04d4.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「","after":"ですか。」　B「魚です。」","tiles":["どんな","食べもの","が","きらい"],"star":2,"bank":[3,1,0,2],"full":"A「どんな　食べもの{が}　きらいですか。」　B「魚です。」","explain":"どんな, 食べもの, が, きらい: what kind of food don't you like? どんな comes before the noun it asks about, the food you dislike takes が, and きらい joins ですか.","unit":4,"day":4,"step":"exam"},"n5u04d4.k1":{"id":"n5u04d4.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_天気_が　いい　日は　山へ　行きます。","options":["でんき","てんき","てんぎ","でんぎ"],"answer":2,"explain":"天気 is てんき, weather. でんき is 電気 (electricity or a light). てんぎ and でんぎ are not words.","unit":4,"day":4,"step":"scene"},"n5u04d4.r1":{"id":"n5u04d4.r1","kind":"choice","type":"読解・内容理解（短文）","q":"マリアさんに　ついて　ただしい　ものは　どれですか。","options":["毎日　テニスを　します。","りょうりが　きらいです。","テニスは　すきですが、まだ　上手じゃ　ありません。","よく　魚の　りょうりを　つくります。"],"short":["毎日テニスをする","りょうりがきらい","テニスはすきだが上手じゃない","よく魚のりょうりをつくる"],"answer":3,"explain":"Maria loves sports and plays tennis, but after でも she says テニスは まだ へたです: she is not good at it yet.","why":["She plays tennis every week on Saturday, not every day.","She says りょうりも すきです: she likes cooking.","","She does not like fish, so she does not cook fish dishes."],"unit":4,"day":4,"step":"skill"},"n5u04d5.c1":{"id":"n5u04d5.c1","kind":"choice","type":"文の文法1","label":"たんじょう日","q":"A「^たんじょう[日|び]に^[何|なに]が（　　）。」B「^[新|あたら]しいとけい^です。」","options":["[行|い]きたいですか","すきですか","ほしいですか"],"answer":3,"why":["行きたい is about a place you want to go. 何が does not fit it, and a watch is not a place.","すき asks what you like in general. It does not go with たんじょう日に, and B names one new thing to get.","A asks what B wants as a birthday present, and B names a thing: a new watch."],"explain":null,"unit":4,"day":5,"step":"compare"},"n5u04d5.d1":{"id":"n5u04d5.d1","kind":"choice","type":"文の文法1","label":"Choose the word","q":"[新|あたら]しいかばん（　　）^ほしいです^。","options":["に","が","を","で"],"answer":2,"why":["に does not mark the thing you want. Here the bag needs が.","With ほしい, the thing you want takes が.","ほしい is not a verb like 買います. The thing you want takes が, not を.","で marks where or with what you do something. The bag is the thing you want."],"explain":null,"unit":4,"day":5,"step":"drill"},"n5u04d5.d2":{"id":"n5u04d5.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[日|にち]よう[日|び]は、うちでゆっくり（　　）。","options":["[休|やす]みたいです","[休|やす]むたいです","[休|やす]みますたいです","[休|やす]みほしいです"],"answer":1,"why":["休みます without ます is 休み, and たいです joins it: \"I want to rest.\"","たい does not join 休む. It joins 休み, the shape before ます.","たい takes the place of ます. You do not keep ます.","ほしい goes after a thing with が. For doing something, use たい."],"unit":4,"day":5,"step":"drill"},"n5u04d5.d3":{"id":"n5u04d5.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[今日|きょう]はつかれました。^どこへも^[行|い]き（　　）。","options":["たいです","ましょう","たいですか","たくないです"],"answer":4,"why":["どこへも goes with a \"not\" ending, and たいです is not one.","どこへも goes with a \"not\" ending. Also, the speaker is tired, not inviting anyone.","どこへも goes with a \"not\" ending, and the speaker is talking about himself, not asking.","どこへも needs a \"not\" ending: \"I don't want to go anywhere.\""],"explain":null,"unit":4,"day":5,"step":"drill"},"n5u04d5.d4":{"id":"n5u04d5.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この[白|しろ]いかさ、[安|やす]いですよ。」B「かさは^うちに[三本|さんぼん]^あります。^[今|いま]は^（　　）。」","options":["ほしかったです","ほしくないです","ほしいくないです","ほしいじゃないです"],"answer":2,"why":["ほしかったです is the past, \"I wanted it\". B says 今は, now.","B has three umbrellas at home, so he does not want one now. ほしい → ほしくないです.","For \"not\", ほしい drops い and takes くない: ほしくない, not ほしいくない.","じゃない is for nouns and な words. ほしい is an い word: ほしくないです."],"explain":null,"unit":4,"day":5,"step":"drill"},"n5u04d5.d5":{"id":"n5u04d5.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「たんじょう[日|び]に[何|なに]がほしいですか。」B「","after":"。」","tiles":["[白|しろ]い","かばん","が","ほしいです"],"star":2,"bank":[1,3,0,2],"hint":"白い describes the thing. The thing you want takes が, and ほしいです comes last.","full":"A「たんじょう[日|び]に[何|なに]がほしいですか。」B「[白|しろ]いかばんが{ほしいです}。」","explain":"白い comes before かばん, which it describes. が marks the thing B wants, and ほしいです ends the answer.","unit":4,"day":5,"step":"drill"},"n5u04d5.d6":{"id":"n5u04d5.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[今日|きょう]はあついですね。つめたい","after":"。","tiles":["ジュース","が","[飲|の]み","たいです"],"star":2,"bank":[2,0,3,1],"hint":"つめたい describes a drink. たいです joins the verb without ます.","full":"[今日|きょう]はあついですね。つめたいジュースが[飲|の]み{たいです}。","explain":"つめたい describes ジュース. With たい the object can take が, and 飲み (飲みます without ます) takes たいです.","unit":4,"day":5,"step":"drill"},"n5u04d5.e1":{"id":"n5u04d5.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「今日の　ばんごはんは　何が　いいですか。」B「カレーが　（　　）。」","options":["食べたいです","食べました","食べたくないです","食べませんか"],"answer":1,"explain":"A asks what would be good for dinner tonight, and B names curry: 食べたいです. 食べました is the past. 食べたくないです does not answer \"what would be good?\". 食べませんか invites, but B is answering a question.","unit":4,"day":5,"step":"exam"},"n5u04d5.e2":{"id":"n5u04d5.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「たんじょう日に　何が　ほしいですか。」B「何も　（　　）。」","options":["ほしいでした","ほしくないです","ほしいです","ほしいですか"],"answer":2,"explain":"何も goes with a \"not\" ending: \"I don't want anything.\" ほしいです and ほしいですか are not \"not\" endings. ほしいでした is not a correct form; the past of ほしい is ほしかったです.","unit":4,"day":5,"step":"exam"},"n5u04d5.e3":{"id":"n5u04d5.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「来年は　何を　したいですか。」B「","after":"。」","tiles":["新しい","車","を","買いたいです"],"star":2,"bank":[3,2,0,1],"full":"A「来年は　何を　したいですか。」B「新しい車を{買いたいです}。」","explain":"新しい, 車, を, 買いたいです. 新しい describes 車, を marks what B wants to buy, and 買いたいです comes last.","unit":4,"day":5,"step":"exam"},"n5u04d5.k1":{"id":"n5u04d5.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"たんじょう日に　_白い_　花が　ほしいです。","options":["あかい","あおい","しろい","くろい"],"answer":3,"explain":"白い is read しろい, \"white\". くろい is black, あかい is red and あおい is blue; they are written with other kanji.","unit":4,"day":5,"step":"scene"},"n5u04d5.r1":{"id":"n5u04d5.r1","kind":"choice","type":"課題理解","q":"二人は　何を　買いますか。","script":["ナレーター：店で、女の人と男の人が話しています。二人は、何を買いますか。","女：あしたは、リンさんのたんじょう日ですね。何を買いましょうか。","男：本はどうですか。","女：うーん、リンさんのへやには、本がたくさんありますよ。","男：そうですか。じゃあ、このかばんは？大きくて、いいですね。ぼくもほしいです。","女：いいですね。でも、一万円ですよ。ちょっと高いです。","男：そうですね。じゃあ、花はどうですか。この白い花、きれいですよ。","女：ええ、いいですね。花を買いましょう。","ナレーター：二人は、何を買いますか。"],"options":["白い　花","かばんと　花","本","大きい　かばん"],"printed":true,"short":["白い 花","かばんと 花","本","大きい かばん"],"answer":1,"why":["The man suggests the white flowers, and the woman agrees: 花を買いましょう.","They talk about both, but they do not buy the bag. It is too expensive.","The woman says Lin already has many books in her room.","The man likes the bag, but the woman says it is 一万円, a little expensive."],"explain":null,"unit":4,"day":5,"step":"skill","clip":"l_n5u4d5"},"n5u04d6.c1":{"id":"n5u04d6.c1","kind":"choice","type":"文の文法1","label":"[川|かわ]で","q":"^きのう^の[川|かわ]はとてもきれい（　　）。","options":["かったです","でした","です"],"answer":2,"why":["きれい ends in い, but it is a な-adjective, so it never takes かったです.","きれい is a な-adjective, and きのう is past: きれいでした.","きれいです is the present. きのう needs the past."],"unit":4,"day":6,"step":"compare"},"n5u04d6.d1":{"id":"n5u04d6.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この[白|しろ]いシャツ、どうですか。」B「いいですね。^でも、ちょっと[高|たか]いです^。もっと（　　）シャツがほしいです。」","options":["[安|やす]い","[安|やす]くて","[安|やす]いな","[安|やす]かったです"],"answer":1,"why":["Right before a noun, an い-adjective stays as it is: 安いシャツ. B wants a cheaper shirt than this one.","安くて joins 安い to another describing word. Here a noun, シャツ, comes next, so it does not fit.","な is for な-adjectives such as しずか. 安い is an い-adjective and takes no な.","安かったです is the polite past and ends a sentence. It cannot sit right before シャツ."],"unit":4,"day":6,"step":"drill"},"n5u04d6.d2":{"id":"n5u04d6.d2","kind":"choice","type":"文の文法1","label":"Choose the phrase","q":"^[先週|せんしゅう]^、[駅|えき]の[前|まえ]の[店|みせ]でカレーを[食|た]べました。（　　）。","options":["[安|やす]かったでおいしいです","[安|やす]いでおいしかったです","[安|やす]くておいしいでした","[安|やす]くておいしかったです"],"answer":4,"why":["安かった does not join with で. Use 安くて, and put the past on the last word: おいしかったです.","安い is an い-adjective, so it joins with くて, not で.","安くて is right, but おいしい is an い-adjective. Its past is おいしかったです, not おいしいでした.","安い joins with くて, and the last word carries the past for the whole sentence: おいしかったです."],"explain":null,"unit":4,"day":6,"step":"drill"},"n5u04d6.d3":{"id":"n5u04d6.d3","kind":"choice","type":"文の文法1","label":"Choose the particles","q":"わたしは[電車|でんしゃ]（　　）^すきです^。[日|にち]よう[日|び]、[大|おお]きい[駅|えき]（　　）^[行|い]きたいです^。","options":["で／へ","が／で","を／へ","が／へ"],"answer":4,"why":["で marks where you do something or what you use. It cannot mark the thing you like.","が is right for 電車, but 駅 is where you go. 行きたいです keeps the へ of 行きます, so で does not fit.","すきです takes が for the thing you like, not を.","The thing you like takes が: 電車がすきです. With 行きたいです, the place you go to takes へ, as with 行きます."],"explain":null,"unit":4,"day":6,"step":"drill"},"n5u04d6.d4":{"id":"n5u04d6.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^[前|まえ]は^コーヒーが（　　）。^でも、[今|いま]は^[毎日|まいにち][飲|の]みます。","options":["すきでした","きらいです","きらいでした","きらかったです"],"answer":3,"why":["すきでした has the right form, but でも needs a change: liked it before, and still drinks it now, is no contrast.","きらいです is the present. 前は needs the past.","きらい is a な-adjective, so its past is きらいでした. でも then shows the change: now I drink it every day.","きらい ends in い, but it is a な-adjective. It does not change like an い-adjective."],"explain":null,"unit":4,"day":6,"step":"drill"},"n5u04d6.d5":{"id":"n5u04d6.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしは","after":"。","tiles":["[白|しろ]くて","[小|ちい]さい","ねこが","ほしいです"],"star":1,"bank":[2,0,3,1],"hint":"Which tile joins to another describing word? Which one can sit right before a noun?","full":"わたしは[白|しろ]くて{[小|ちい]さい}ねこがほしいです。","explain":"白くて joins to the next describing word, 小さい. 小さい sits right before the noun, ねこ. The thing you want takes が, and ほしいです comes last.","unit":4,"day":6,"step":"drill"},"n5u04d6.d6":{"id":"n5u04d6.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"きのうの","after":"。","tiles":["こうえんは","[花|はな]が","[多|おお]くて","きれいでした"],"star":2,"bank":[3,1,0,2],"hint":"きのうの needs a noun right after it. The past goes on the last word only.","full":"きのうのこうえんは[花|はな]が{[多|おお]くて}きれいでした。","explain":"きのうのこうえんは is the topic. 花が多くて says what was there and joins to きれいでした, which carries the past for both.","unit":4,"day":6,"step":"drill"},"n5u04d6.e1":{"id":"n5u04d6.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きのうの　テストは　（　　）、むずかしかったです。","options":["長かったで","長いくて","長いで","長くて"],"answer":4,"explain":"長い is an い-adjective, so it joins with くて: 長くて、むずかしかったです. The past goes on the last word only. 長いで and 長かったで use で, which is for な-adjectives and nouns, and 長いくて keeps the い it should drop.","unit":4,"day":6,"step":"exam"},"n5u04d6.e2":{"id":"n5u04d6.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは　えいがが　すきです。こんどの　日よう日、新しい　えいがを　（　　）。","options":["ほしいです","見ほしいです","見たいです","見るたいです"],"answer":3,"explain":"Seeing a film is an action, so use たい on the ます form: 見ます → 見たいです. ほしいです is for a thing and takes が, not を. 見ほしいです is not a form, and たい does not join 見る.","unit":4,"day":6,"step":"exam"},"n5u04d6.e3":{"id":"n5u04d6.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「きのうの　レストランは　どうでしたか。」B「","after":"とても　おいしかったです。」","tiles":["店は","古くて","小さかったですが","りょうりは"],"star":2,"bank":[1,3,2,0],"full":"A「きのうの　レストランは　どうでしたか。」B「店は　古くて　{小さかったですが}　りょうりは　とても　おいしかったです。」","explain":"店は, 古くて, 小さかったですが, りょうりは. The shop was old and small: 古くて joins to 小さかったです. が (but) then turns to the food, and りょうりは goes with おいしかったです.","unit":4,"day":6,"step":"exam"},"n5u04d6.k1":{"id":"n5u04d6.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"この　まちには　_古い_　店が　たくさん　あります。","options":["くろい","ふかい","ふるい","ひろい"],"answer":3,"explain":"古い is ふるい, \"old\". ひろい (wide), くろい (black) and ふかい (deep) are real words, but they are written with other kanji or in kana.","unit":4,"day":6,"step":"scene"},"n5u04d6.r1":{"id":"n5u04d6.r1","kind":"choice","type":"読解・情報検索","q":"十さいの　子どもは　いくら　はらいますか。","options":["三千円","千五百円","四千五百円","お金は　いりません"],"short":["3,000円","1,500円","4,500円","free"],"answer":2,"explain":"The line 子ども（六さい〜十二さい） covers children from six to twelve. A ten-year-old pays 千五百円.","why":["Three thousand yen is the price for 大人, adults.","","Four thousand five hundred yen is one adult and one child together. The question asks about the child only.","Only children up to five years old pay nothing."],"unit":4,"day":6,"step":"skill"},"n5u04t.1":{"id":"n5u04t.1","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"父の　カメラは　_古い_ですが、まだ　よく　とれます。","options":["ふとい","ふるい","ふろい","くるい"],"answer":2,"explain":"古い is ふるい, old. ふとい is a different word (thick), not read from 古. ふろい and くるい change one sound of ふるい, and they are not words.","unit":4,"step":"test"},"n5u04t.2":{"id":"n5u04t.2","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"きょうは　_空_が　あおくて　きれいです。","options":["くも","うみ","そうら","そら"],"answer":4,"explain":"空 here is そら, the sky. くも (cloud) and うみ (sea) are other words, not read from 空. そうら has a long そう, and it is not a word.","unit":4,"step":"test"},"n5u04t.3":{"id":"n5u04t.3","kind":"choice","type":"表記","label":"Kanji spelling","q":"この　くつは　_やすい_ですが、とても　いいです。","options":["高い","女い","休い","安い"],"answer":4,"explain":"やすい (cheap) is 安い. 高い is たかい (expensive), the opposite. 女 is おんな and 休 is the やす of 休みます, so 女い and 休い are not words.","unit":4,"step":"test"},"n5u04t.4":{"id":"n5u04t.4","kind":"choice","type":"表記","label":"Kanji spelling","q":"あしたは　_ごご_から　雨です。","options":["午後","五後","午前","後午"],"answer":1,"explain":"ごご (afternoon) is 午後. 午前 is ごぜん (morning), a real word but not ごご. 後午 has the two kanji the wrong way round, and 五後 uses 五 (five); neither is a word.","unit":4,"step":"test"},"n5u04t.5":{"id":"n5u04t.5","kind":"choice","type":"文脈規定","label":"Word in context","q":"へやが　（　　）ですから、まどを　あけました。","options":["ひろい","ふるい","あつい","さむい"],"answer":3,"explain":"You open the window because the room is hot: あつい. If the room is さむい (cold), you would not open the window. ひろい (big) and ふるい (old) are not reasons to open a window.","unit":4,"step":"test"},"n5u04t.6":{"id":"n5u04t.6","kind":"choice","type":"文脈規定","label":"Word in context","q":"この　本は　（　　）ですから、子どもも　よく　読みます。","options":["むずかしい","たかい","やさしい","おもい"],"answer":3,"explain":"Children read the book often because it is easy: やさしい. むずかしい (difficult) is the opposite reason. たかい (expensive) and おもい (heavy) do not explain why children read it a lot.","unit":4,"step":"test"},"n5u04t.7":{"id":"n5u04t.7","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"わたしの　へやは　_せまい_です。","options":["わたしの　へやは　しずかじゃ　ありません。","わたしの　へやは　ひろいです。","わたしの　へやは　ひろくないです。","わたしの　へやは　あかるくないです。"],"answer":3,"explain":"せまい means small (not roomy), so it is the same as ひろくないです, not big. Option 2 says the opposite. あかるくない (not bright) and しずかじゃ ありません (not quiet) talk about other things, not the size.","unit":4,"step":"test"},"n5u04t.8":{"id":"n5u04t.8","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"きのうの　テストは　_むずかしくなかったです_。","options":["きのうの　テストは　むずかしかったです。","きのうの　テストは　たのしかったです。","きのうの　テストは　やさしくなかったです。","きのうの　テストは　やさしかったです。"],"answer":4,"explain":"むずかしくなかったです means the test was not difficult, so it was easy: やさしかったです. Option 1 says it was difficult. Option 2 says it was fun, which is about something else. Option 3 says it was not easy, the opposite.","unit":4,"step":"test"},"n5u04t.9":{"id":"n5u04t.9","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ここは　とても　（　　）　まちですね。","options":["にぎやかな","にぎやかの","にぎやかい","にぎやかで"],"answer":1,"explain":"にぎやか is a な-word, and it takes な before a noun: にぎやかな まち (a lively town). の does not join にぎやか to a noun, and にぎやかい is not a form. にぎやかで means \"lively and\", so it cannot go right before まち.","unit":4,"step":"test"},"n5u04t.10":{"id":"n5u04t.10","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この　いすは　大きいですが、あまり　（　　）。","options":["おもいじゃ　ありません","おもくないです","おもいくないです","おもいです"],"answer":2,"explain":"あまり goes with a not form, and the not form of おもい (heavy) is おもくないです: the chair is big but not very heavy. おもいです is not a not form, so it does not go with あまり. じゃ ありません is for な-words and nouns, not for an い-word like おもい. おもいくないです keeps the い, but the い changes to く.","unit":4,"step":"test"},"n5u04t.11":{"id":"n5u04t.11","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きのうは　とても　（　　）から、どこへも　行きませんでした。","options":["さむかったです","さむいでした","さむくなかったです","さむいです"],"answer":1,"explain":"きのう is past, and the past of さむい is さむかったです: it was very cold, so the person went nowhere. さむいです is not past. さむいでした is not a form; an い-word does not take でした. さむくなかったです (it was not cold) does not go with とても, and it is not a reason to stay in.","unit":4,"step":"test"},"n5u04t.12":{"id":"n5u04t.12","kind":"choice","type":"文の文法1","label":"Choose the form","q":"子どもの　とき、やさいが　（　　）。でも、今は　大すきです。","options":["すきでした","すきくなかったです","すきじゃ　ありません","すきじゃ　ありませんでした"],"answer":4,"explain":"でも、今は 大すきです shows that it was different as a child, so the person did not like vegetables then: すきじゃ ありませんでした. すきでした (liked) does not fit でも. すき is a な-word, so すきくなかったです is not a form. すきじゃ ありません is about now, but 子どもの とき is the past.","unit":4,"step":"test"},"n5u04t.13":{"id":"n5u04t.13","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この　かばんは　（　　）、べんりです。","options":["かるくて","かるいで","かるくで","かるいくて"],"answer":1,"explain":"To join the い-word かるい (light) to べんりです, い changes to くて: かるくて、べんりです (light and handy). で joins な-words and nouns, not い-words, so かるいで and かるくで are wrong. かるいくて keeps the い, but the い changes to く.","unit":4,"step":"test"},"n5u04t.14":{"id":"n5u04t.14","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"あの　人は　ピアノ（　　）　とても　じょうずですね。","options":["を","で","が","と"],"answer":3,"explain":"The thing someone is good at takes が: ピアノが じょうずです. を does not go with じょうずです. で would mark a place or a tool, and と means \"with\"; neither makes sense with じょうずです here.","unit":4,"step":"test"},"n5u04t.15":{"id":"n5u04t.15","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きょねん　はじめて　日本へ　行きました。来年も　また　（　　）。","options":["行きほしいです","行きたかったです","行きたいです","行くたいです"],"answer":3,"explain":"来年 (next year) is in the future, so the person says what they want to do: 行きたいです. 行きたかったです is past, and it does not fit 来年. たい joins the ます form without ます (行き), not 行く, so 行くたいです is wrong. ほしい is for things you want, not actions, so 行きほしいです is not Japanese.","unit":4,"step":"test"},"n5u04t.16":{"id":"n5u04t.16","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「山川さんは　どの　人ですか。」B「あの　","after":"です。」","tiles":["ギター","が","じょうずな","人"],"star":2,"bank":[2,3,0,1],"full":"A「山川さんは　どの　人ですか。」B「あの　ギターが　{じょうずな}　人です。」","explain":"ギター, が, じょうずな, 人. The thing someone is good at takes が, so ギターが comes first. じょうずな, with な before a noun, describes 人: あの ギターが じょうずな 人 (that person who is good at the guitar). じょうずな cannot come before ギター, because then が and 人 have no place.","unit":4,"step":"test"},"n5u04t.17":{"id":"n5u04t.17","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「りょこうは　どうでしたか。」B「","after":"が、とても　きれいでした。」","tiles":["ホテルの","へやは","少し","せまかったです"],"star":2,"bank":[3,1,0,2],"full":"A「りょこうは　どうでしたか。」B「ホテルの　へやは　{少し}　せまかったですが、とても　きれいでした。」","explain":"ホテルの, へやは, 少し, せまかったです. ホテルの needs a noun after it, so it goes before へやは (the hotel room). 少し (a little) comes right before the word it describes, せまかったです, and せまかったです comes last because が follows it: the room was a little small, but very clean.","unit":4,"step":"test"},"n5u04t.18":{"id":"n5u04t.18","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「今　何が　いちばん　ほしいですか。」B「","after":"　ほしいです。」","tiles":["大きくて","かるい","かばん","が"],"star":1,"bank":[1,3,0,2],"full":"A「今　何が　いちばん　ほしいですか。」B「大きくて　{かるい}　かばんが　ほしいです。」","explain":"大きくて, かるい, かばん, が. 大きくて (big and) joins the next describing word, かるい, and かるい comes right before the noun かばん: a big, light bag. The thing you want takes が, so が comes right before ほしいです. 大きくて cannot come right before かばん, because くて does not join a noun.","unit":4,"step":"test"},"n5u04t.19":{"id":"n5u04t.19","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"わたしは　先月から　新しい　アパートに　すんで　います。へやは　あまり　ひろくないですが、あかるくて　きれいです。駅から　あるいて　五分ですから、べんりです。でも、ちかくに　店が　ありませんから、かいものは　たいへんです。今は　大きい　つくえが　ほしいです。","q":"この　人の　へやは　どんな　へやですか。","options":["ひろくて　あかるいです。","ひろくないですが、あかるいです。","あかるくないですが、きれいです。","ひろいですが、きれいじゃ　ありません。"],"answer":2,"short":["ひろい・あかるい","ひろくない・あかるい","あかるくない","きれいじゃない"],"explain":"The writer says へやは あまり ひろくないですが、あかるくて きれいです: not very big, but bright and clean. Option 1 says the room is big. Option 3 says it is not bright. Option 4 says it is big and not clean.","unit":4,"step":"test"},"n5u04t.20":{"id":"n5u04t.20","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"わたしは　先月から　新しい　アパートに　すんで　います。へやは　あまり　ひろくないですが、あかるくて　きれいです。駅から　あるいて　五分ですから、べんりです。でも、ちかくに　店が　ありませんから、かいものは　たいへんです。今は　大きい　つくえが　ほしいです。","q":"ただしい　ものは　どれですか。","options":["アパートは　駅から　とおいです。","アパートの　ちかくに　店が　たくさん　あります。","この　人は　今　つくえが　ほしいです。","アパートは　古いです。"],"answer":3,"short":["駅からとおい","店がたくさん","つくえがほしい","古い"],"explain":"The writer ends with 今は 大きい つくえが ほしいです: now the writer wants a big desk. The apartment is new (新しい アパート), not old. It is a five-minute walk from the station, so it is not far. There are no shops near it (ちかくに 店が ありません).","unit":4,"step":"test"},"n5u04t.21":{"id":"n5u04t.21","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"アパートの　あんない\nＡ　駅から　あるいて　三分　へやは　小さいです　六万円\nＢ　駅から　バスで　十分　へやは　ひろくて　あかるいです　五万円\nＣ　駅から　あるいて　十五分　へやは　ひろいです　四万円\nＤ　駅から　あるいて　八分　へやは　せまくて　古いです　三万円","q":"リーさんは　ひろい　へやが　いいです。でも、バスは　きらいです。どの　アパートが　いいですか。","options":["Ｃ","Ｄ","Ａ","Ｂ"],"answer":1,"short":["Ｃ","Ｄ","Ａ","Ｂ"],"explain":"Ｃ has a big room (ひろいです), and you walk from the station, so there is no bus. Ａ has a small room (小さいです). Ｂ has a big room, but you go there by bus (バスで). Ｄ has a small, old room (せまくて 古いです).","unit":4,"step":"test"},"n5u04t.22":{"id":"n5u04t.22","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"アパートの　あんない\nＡ　駅から　あるいて　三分　へやは　小さいです　六万円\nＢ　駅から　バスで　十分　へやは　ひろくて　あかるいです　五万円\nＣ　駅から　あるいて　十五分　へやは　ひろいです　四万円\nＤ　駅から　あるいて　八分　へやは　せまくて　古いです　三万円","q":"ワンさんの　お金は　毎月　五万円までです。駅から　あるいて　行きたいです。いちばん　駅から　ちかい　アパートは　どれですか。","options":["Ｃ","Ｄ","Ａ","Ｂ"],"answer":2,"short":["Ｃ","Ｄ","Ａ","Ｂ"],"explain":"Ｃ (四万円) and Ｄ (三万円) cost 五万円 or less, and you walk to both from the station. Ｄ is eight minutes away and Ｃ is fifteen, so Ｄ is the nearest. Ａ is nearer, but it costs 六万円, which is too much. Ｂ costs 五万円, but you go there by bus.","unit":4,"step":"test"},"n5u04t.23":{"id":"n5u04t.23","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"マリアさん\nあしたの　パーティーの　ケーキは　わたしが　買います。駅の　前の　店は　ケーキが　小さくて　高いですから、川の　ちかくの　店で　買います。そこの　ケーキは　大きくて　おいしいです。マリアさんは　つめたい　ジュースを　買って　ください。\nゆき","q":"ゆきさんは　どうして　駅の　前の　店で　ケーキを　買いませんか。","options":["ケーキが　小さくて　高いですから","ケーキが　大きくて　おいしいですから","店が　駅から　とおいですから","店に　ジュースが　ありませんから"],"answer":1,"short":["小さくて高い","大きくておいしい","駅からとおい","ジュースがない"],"explain":"ゆき writes 駅の 前の 店は ケーキが 小さくて 高いですから: the cakes there are small and expensive. Big and tasty (大きくて おいしい) is the cake at the shop near the river. The note does not say the shop is far from the station; it is in front of it. The juice is for マリア to buy, and the note says nothing about juice at that shop.","unit":4,"step":"test"},"n5u04t.24":{"id":"n5u04t.24","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"マリアさん\nあしたの　パーティーの　ケーキは　わたしが　買います。駅の　前の　店は　ケーキが　小さくて　高いですから、川の　ちかくの　店で　買います。そこの　ケーキは　大きくて　おいしいです。マリアさんは　つめたい　ジュースを　買って　ください。\nゆき","q":"マリアさんは　何を　買いますか。","options":["川の　ちかくの　店の　ケーキ","つめたい　ジュース","ケーキと　ジュース","駅の　前の　店の　ケーキ"],"answer":2,"short":["川のちかくのケーキ","ジュース","ケーキとジュース","駅の前のケーキ"],"explain":"ゆき writes マリアさんは つめたい ジュースを 買って ください: マリア buys cold juice. ゆき buys the cake (ケーキは わたしが 買います), from the shop near the river, so options 3, 1 and 4 are wrong. Nobody buys cake at the shop in front of the station.","unit":4,"step":"test"},"n5u05d1.c1":{"id":"n5u05d1.c1","kind":"choice","type":"文の文法1","label":"店のじかん","q":"この[店|みせ]は[十時|じゅうじ]（　　）[八時|はちじ]までです。","options":["ごろ","に","から"],"answer":3,"why":["ごろ means \"about\". 十時ごろ八時まで does not give a start, so the sentence does not work.","に marks one point in time, as in 十時に行きます. It cannot give the start before 八時まで.","まで gives the closing time, so the opening time takes から: from ten until eight."],"explain":null,"unit":5,"day":1,"step":"compare"},"n5u05d1.d1":{"id":"n5u05d1.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[毎日|まいにち]^あさ[六時|ろくじ]^（　　）おきます。","options":["で","に","を","へ"],"answer":2,"why":["六時でおきます is not Japanese. The time when you do something takes に.","六時 is a clock time, so it takes に: I get up at six.","を marks the thing a verb acts on, as in パンを食べます. 六時 is the time, not a thing you act on.","へ marks the place you go to. 六時 is a time, not a place."],"unit":5,"day":1,"step":"drill"},"n5u05d1.d2":{"id":"n5u05d1.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「^いつ^[山|やま]へ[行|い]きますか。」\nB「（　　）[行|い]きます。」","options":["あしたに","あしたを","あした","あしたで"],"answer":3,"why":["あした counts from today, so it takes no に.","を marks the thing a verb acts on. あした is the time, and it takes nothing.","あした takes no particle: あした行きます, I will go tomorrow.","あしたで is not Japanese here. あした takes nothing before the verb."],"unit":5,"day":1,"step":"drill"},"n5u05d1.d3":{"id":"n5u05d1.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この[店|みせ]は[午前|ごぜん][十時|じゅうじ]^から^[午後|ごご][七時|しちじ]（　　）です。","options":["に","を","まで","で"],"answer":3,"why":["に marks the time something happens, as in 七時に行きます. After から, the end time takes まで.","を marks the thing a verb acts on. 七時をです is not Japanese.","から gives the opening time, so まで gives the closing time: until seven.","七時でです is not Japanese. After から, the end time takes まで."],"unit":5,"day":1,"step":"drill"},"n5u05d1.d4":{"id":"n5u05d1.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[月|げつ]よう[日|び]（　　）[金|きん]よう[日|び]^まで^[学校|がっこう]へ[行|い]きます。","options":["まで","で","から","に"],"answer":3,"why":["まで already sits after 金よう日. 月よう日まで金よう日まで is not Japanese.","月よう日で does not give a start. The first day takes から.","金よう日まで gives the last day, so the first day takes から: from Monday to Friday.","に marks one day, as in 月よう日に行きます. With 金よう日まで after it, the first day needs から."],"explain":null,"unit":5,"day":1,"step":"drill"},"n5u05d1.d5":{"id":"n5u05d1.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あしたは","after":"。","tiles":["[七時|しちじ]","[半|はん]","に","おきます"],"star":2,"bank":[3,1,0,2],"hint":"半 comes right after the hour. Then the time takes に, and the verb comes last.","full":"あしたは[七時|しちじ][半|はん]{に}おきます。","explain":"七時半 is one time, so 半 sits right after 七時. A clock time takes に, and おきます ends the sentence. あした itself takes no に; は is fine after it.","unit":5,"day":1,"step":"drill"},"n5u05d1.d6":{"id":"n5u05d1.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"ぎんこうは[午前|ごぜん]","after":"です。","tiles":["[九時|くじ]","から","[午後|ごご][三時|さんじ]","まで"],"star":1,"bank":[2,3,0,1],"hint":"午前 needs an hour right after it. The start takes から, the end takes まで.","full":"ぎんこうは[午前|ごぜん][九時|くじ]{から}[午後|ごご][三時|さんじ]{まで}です。","explain":"午前 goes with 九時: nine in the morning. That is the start, so から follows it. 午後三時 is the end, so まで follows it, right before です.","unit":5,"day":1,"step":"drill"},"n5u05d1.e1":{"id":"n5u05d1.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは　毎週　土よう日（　　）　プールへ　行きます。","options":["が","で","に","を"],"answer":3,"explain":"土よう日 is a day of the week, so it takes に: on Saturdays. 毎週 itself takes no particle. で does not give the day when something happens, を marks a thing a verb acts on, and が marks who or what does something. None of them fits after 土よう日 here.","unit":5,"day":1,"step":"exam"},"n5u05d1.e2":{"id":"n5u05d1.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　店は　何時（　　）ですか。」\nB「よる　九時までです。」","options":["まで","に","を","から"],"answer":1,"explain":"B answers with 九時まで, the closing time, so A asked 何時までですか: until what time? 何時から asks the opening time, which B does not give. 何時にですか and 何時をですか do not work after この店は.","unit":5,"day":1,"step":"exam"},"n5u05d1.e3":{"id":"n5u05d1.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あしたの　","after":"ですか。","tiles":["テスト","は","何時","から"],"star":2,"bank":[2,3,0,1],"full":"あしたの　テストは　{何時}からですか。","explain":"テスト, は, 何時, から. あしたの describes テスト, so テスト comes first, then は. The question is 何時からですか: from what time is tomorrow's test?","unit":5,"day":1,"step":"exam"},"n5u05d1.k1":{"id":"n5u05d1.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"ぎんこうは　_午後_三時までです。","options":["ごうご","ごぜん","ごご","ごこ"],"answer":3,"explain":"午後 is ごご, the afternoon. ごぜん is 午前, the morning, a different word. ごこ and ごうご are not words.","unit":5,"day":1,"step":"scene"},"n5u05d1.r1":{"id":"n5u05d1.r1","kind":"choice","type":"即時応答","q":"男：すみません、この　店は　何時までですか。","script":["男：すみません、この　店は　何時までですか。","ナレーター：1","女：午前　十時からです。","ナレーター：2","女：八時間です。","ナレーター：3","女：よる　八時までです。"],"options":["午前　十時からです。","八時間です。","よる　八時までです。"],"printed":false,"short":["午前十時からです","八時間です","よる八時までです"],"answer":3,"why":["十時から is the opening time. The man asks 何時まで, until what time.","八時間 is how many hours. The man asks for a clock time with 何時.",""],"unit":5,"day":1,"step":"skill","clip":"l_n5u5d1"},"n5u05d2.c1":{"id":"n5u05d2.c1","kind":"choice","type":"文の文法1","label":"くすりの じかん","q":"[食|た]べた（　　）、くすりを[飲|の]みます。","options":["に","[前|まえ]に","[後|あと]で"],"answer":3,"why":["に goes after a clock time such as 九時, not after a verb.","前に takes the dictionary form: 食べる前に. 食べた does not go before 前に.","食べた is the た-form, and 後で comes after it: 食べた後で, \"after eating\"."],"explain":null,"unit":5,"day":2,"step":"compare"},"n5u05d2.d1":{"id":"n5u05d2.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[学校|がっこう]へ^[行|い]く^（　　）、しんぶんを[読|よ]みます。","options":["[前|まえ]に","[後|あと]で","の[前|まえ]に","[前|まえ]で"],"answer":1,"why":["行く is the dictionary form, and 前に comes right after it: 行く前に.","後で takes the た-form: 行った後で. 行く does not go before 後で.","の goes after a noun, as in ごはんの前に. 行く is a verb.","前で is a place, \"in front of\" something. Here you need a time, 前に."],"unit":5,"day":2,"step":"drill"},"n5u05d2.d2":{"id":"n5u05d2.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[友|とも]だちが^[来|き]た^（　　）、いっしょにごはんを[食|た]べました。","options":["の[後|あと]で","まで","[後|あと]で","[前|まえ]に"],"answer":3,"why":["の goes after a noun, as in じゅぎょうの後で. 来た is a verb.","まで does not go after 来た. It would also mean \"until\", which does not fit eating together.","来た is the た-form, and 後で comes right after it: 来た後で, \"after my friend came\".","前に takes the dictionary form: 来る前に. 来た does not go before 前に."],"explain":null,"unit":5,"day":2,"step":"drill"},"n5u05d2.d3":{"id":"n5u05d2.d3","kind":"choice","type":"文の文法1","label":"Choose the word","q":"しゅくだい（　　）^[前|まえ]に^、[少|すこ]し[休|やす]みます。","options":["の","を","に","で"],"answer":1,"why":["しゅくだい is a noun, and a noun takes の before 前に: しゅくだいの前に.","を marks the thing you act on. It cannot join a noun to 前に.","に cannot join a noun to 前に. Only の can.","で cannot join a noun to 前に. Only の can."],"unit":5,"day":2,"step":"drill"},"n5u05d2.d4":{"id":"n5u05d2.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"えいがを（　　）^[後|あと]で^、[友|とも]だちとごはんを[食|た]べました。","options":["[見|み]る","[見|み]ます","[見|み]て","[見|み]た"],"answer":4,"why":["見る is the dictionary form. It goes before 前に, not 後で.","The polite ます form does not go before 後で.","見て is a different form (unit 6). It does not go before 後で.","後で takes the た-form: 見た後で, \"after watching\"."],"explain":null,"unit":5,"day":2,"step":"drill"},"n5u05d2.d5":{"id":"n5u05d2.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[日本|にほん]へ","after":"[買|か]いました。","tiles":["[来|く]る","[前|まえ]に","[日本語|にほんご]の","[本|ほん]を"],"star":1,"bank":[2,0,3,1],"hint":"日本へ needs a verb right after it. Which form of くる goes before 前に?","full":"[日本|にほん]へ[来|く]る{[前|まえ]に}[日本語|にほんご]の[本|ほん]を[買|か]いました。","explain":"日本へ goes with 来る, and the dictionary form 来る comes before 前に. 日本語の describes 本, and 本を is what was bought.","unit":5,"day":2,"step":"drill"},"n5u05d2.d6":{"id":"n5u05d2.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"じゅぎょうが","after":"。","tiles":["おわった","[後|あと]で","[先生|せんせい]と","[話|はな]しました"],"star":1,"bank":[3,1,0,2],"hint":"じゅぎょうが needs a verb right after it. 後で follows the た-form.","full":"じゅぎょうがおわった{[後|あと]で}[先生|せんせい]と[話|はな]しました。","explain":"じゅぎょうが goes with おわった, the た-form, and 後で comes right after it. 先生と goes before the verb 話しました, which ends the sentence.","unit":5,"day":2,"step":"drill"},"n5u05d2.e1":{"id":"n5u05d2.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"テレビを　見る　（　　）、しゅくだいを　します。","options":["の　前に","前で","前に","後で"],"answer":3,"explain":"見る is the dictionary form, so 前に comes after it: 見る前に. 後で needs the た-form (見た後で), の goes only after a noun, and 前で means \"in front of\" a place.","unit":5,"day":2,"step":"exam"},"n5u05d2.e2":{"id":"n5u05d2.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"シャワーを　（　　）　後で、ばんごはんを　食べます。","options":["あびる","あびます","あびて","あびた"],"answer":4,"explain":"後で takes the た-form, even for every day: あびた後で. あびる goes before 前に, the polite ます form does not go before 後で, and あびて is a different form.","unit":5,"day":2,"step":"exam"},"n5u05d2.e3":{"id":"n5u05d2.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"シャワーは　いつも　","after":"。","tiles":["学校へ","行く","前に","あびます"],"star":2,"bank":[3,2,0,1],"full":"シャワーは　いつも　学校へ　行く　{前に}　あびます。","explain":"学校へ, 行く, 前に, あびます. 学校へ goes with 行く, the dictionary form 行く comes before 前に, and the verb あびます ends the sentence.","unit":5,"day":2,"step":"exam"},"n5u05d2.k1":{"id":"n5u05d2.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"この　くすりは　_毎日_　飲みます。","options":["まいじつ","まいにち","まいび","めいにち"],"answer":2,"explain":"毎日 is read まいにち, \"every day\". まいび, めいにち and まいじつ are not readings of 毎日.","unit":5,"day":2,"step":"scene"},"n5u05d2.r1":{"id":"n5u05d2.r1","kind":"choice","type":"読解・内容理解（短文）","q":"この　人は　あさごはんの　前に　何を　しますか。","options":["日本語の　本を　読みます。","水を　飲みます。","テニスを　します。","おふろに　入ります。"],"short":["日本語の本を読む","水を飲む","テニスをする","おふろに入る"],"answer":2,"explain":"After getting up, the writer drinks a glass of water (おきた後で、水を一ぱい飲みます). それから (after that) comes breakfast, so the water is before breakfast.","why":["The writer reads before going to bed (ねる前に), not before breakfast.","","Tennis is after school (学校の後で), so it comes after breakfast.","The bath is before dinner (ばんごはんの前に), not before breakfast."],"unit":5,"day":2,"step":"skill"},"n5u05d3.c1":{"id":"n5u05d3.c1","kind":"choice","type":"文の文法1","label":"むかしのはなし","q":"わたしは[子|こ]ども（　　）、[魚|さかな]がきらいでした。","options":["てから","のとき","の[後|あと]で"],"answer":2,"why":["てから goes after a verb in the te-form. 子ども is a noun.","子ども is a noun, so の joins it to とき: \"when I was a child\".","の後で means \"after\". \"After a child\" makes no sense here."],"unit":5,"day":3,"step":"compare"},"n5u05d3.d1":{"id":"n5u05d3.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[手|て]を（　　）、^ごはんを[食|た]べます^。","options":["あらいてから","あらってから","あらうてから","あらいから"],"answer":2,"why":["あらいて is not a word. The te-form of あらいます is あらって.","あらって is the te-form of あらいます. あらってから: wash first, then eat.","あらうて is not a word. Use the te-form あらって.","から does not join あらい. For \"after\", use the te-form: あらってから."],"unit":5,"day":3,"step":"drill"},"n5u05d3.d2":{"id":"n5u05d3.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：^いつ^テレビを[見|み]ますか。B：しゅくだいを（　　）[見|み]ます。","options":["しますてから","してから","するから","しから"],"answer":2,"why":["てから does not go after します. Use the te-form: してから.","して is the te-form of します. してから answers いつ: after the homework.","するから means \"because I do\", not \"after\". It does not answer いつ.","から does not join し. Use the te-form: してから."],"explain":null,"unit":5,"day":3,"step":"drill"},"n5u05d3.d3":{"id":"n5u05d3.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^[大学生|だいがくせい]^（　　）、よくテニスをしました。","options":["でとき","とき","のとき","なとき"],"answer":3,"why":["で does not join a noun to とき. Use の.","大学生 is a noun. A noun needs の before とき.","大学生 is a noun, so の joins it to とき: \"when I was a university student\".","な is for な-adjectives such as ひま. 大学生 is a noun."],"explain":null,"unit":5,"day":3,"step":"drill"},"n5u05d3.d4":{"id":"n5u05d3.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"（　　）^とき^、[友|とも]だちに[電話|でんわ]をします。","options":["ひまい","ひま","ひまな","ひまだ"],"answer":3,"why":["ひまい is not a word. ひま is a な-adjective.","ひま is a な-adjective. It keeps な before とき: ひまなとき.","ひま is a な-adjective, and な joins it to とき: \"when I am free\".","だ ends a sentence. ひまだ cannot come right before とき."],"explain":null,"unit":5,"day":3,"step":"drill"},"n5u05d3.d5":{"id":"n5u05d3.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[毎|まい]ばん","after":"[見|み]ます。","tiles":["しゅくだいを","して","から","テレビを"],"star":2,"bank":[3,1,0,2],"hint":"から comes right after the te-form して. What do you do first?","full":"[毎|まい]ばんしゅくだいをして{から}テレビを[見|み]ます。","explain":"しゅくだいを, して, から, テレビを. してから puts the homework first, and テレビを goes with 見ます: \"Every evening I do my homework and then watch TV.\"","unit":5,"day":3,"step":"drill"},"n5u05d3.d6":{"id":"n5u05d3.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[日本|にほん]へ","after":"を[買|か]いました。","tiles":["[行|い]く","とき","[新|あたら]しい","かばん"],"star":1,"bank":[2,0,3,1],"hint":"日本へ goes with 行く, and とき follows it. 新しい goes right before the thing you bought.","full":"[日本|にほん]へ[行|い]く{とき}[新|あたら]しいかばんを[買|か]いました。","explain":"行く, とき, 新しい, かばん. 日本へ行くとき is \"when I went to Japan\", and 新しい describes かばん: \"When I went to Japan, I bought a new bag.\"","unit":5,"day":3,"step":"drill"},"n5u05d3.e1":{"id":"n5u05d3.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あさは　シャワーを　あびて（　　）、　ごはんを　食べます。","options":["ので","まえに","とき","から"],"answer":4,"explain":"あびて is the te-form, and から after it gives the order: shower first, then breakfast. まえに and とき follow the dictionary form (あびる), not the te-form, and ので never follows the te-form.","unit":5,"day":3,"step":"exam"},"n5u05d3.e2":{"id":"n5u05d3.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"へやが　しずか（　　）　とき、　本を　読みます。","options":["で","の","な","に"],"answer":3,"explain":"しずか is a な-adjective, so it keeps な before とき: \"When the room is quiet, I read.\" の is for a noun (子どもの　とき), and に and で cannot join a word to とき.","unit":5,"day":3,"step":"exam"},"n5u05d3.e3":{"id":"n5u05d3.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"毎あさ","after":"読みます。","tiles":["コーヒーを","飲んで","から","新聞を"],"star":2,"bank":[3,0,2,1],"full":"毎あさ　コーヒーを　飲んで　{から}　新聞を　読みます。","explain":"コーヒーを, 飲んで, から, 新聞を. 飲んでから puts the coffee first, and 新聞を goes with 読みます: \"Every morning I drink coffee and then read the newspaper.\"","unit":5,"day":3,"step":"exam"},"n5u05d3.k1":{"id":"n5u05d3.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"としょかんの　_入口_は　あちらです。","options":["いりくち","でぐち","いりぐち","にゅうぐち"],"answer":3,"explain":"入口, \"entrance\", is read いりぐち: 口 becomes ぐち after いり. でぐち is 出口, \"exit\". いりくち and にゅうぐち are not words.","unit":5,"day":3,"step":"scene"},"n5u05d3.r1":{"id":"n5u05d3.r1","kind":"choice","type":"ポイント理解","q":"女の人は　うちへ　かえってから、　はじめに　何を　しますか。","script":["ナレーター：女の人と男の人が話しています。女の人はうちへかえってから、はじめに何をしますか。","男：川口さん、きょう、しごとの後で、いっしょにごはんを食べませんか。","女：すみません。きょうはとしょかんへ行きます。本をかえします。","男：そうですか。","女：としょかんへ行ってから、スーパーで買いものをします。","男：たいへんですね。うちへかえってから、すぐばんごはんをつくりますか。","女：いいえ。うちへかえってから、はじめに母に電話をします。ばんごはんはその後です。","男：そうですか。","ナレーター：女の人はうちへかえってから、はじめに何をしますか。"],"options":["ばんごはんを　つくります","としょかんへ　行きます","スーパーで　買いものを　します","母に　電話を　します"],"printed":true,"short":["ばんごはん","としょかんへ 行く","スーパーで 買いもの","母に 電話"],"answer":4,"why":["The man asks about dinner, but she says いいえ. Dinner comes after the call (ばんごはんはその後です).","She goes to the library before she gets home (としょかんへ行ってから、スーパーで…).","She shops at the supermarket after the library, also before she gets home.","At home she first calls her mother: うちへかえってから、はじめに母に電話をします."],"explain":null,"unit":5,"day":3,"step":"skill","clip":"l_n5u5d3"},"n5u05d4.c1":{"id":"n5u05d4.c1","kind":"choice","type":"文の文法1","label":"しゅくだい","q":"いつもおんがくを^[聞|き]き^（　　）、しゅくだいをします。","options":["てから","ながら","たり"],"answer":2,"why":["てから goes on the て form: 聞いてから. 聞きてから is not a form.","聞き is the ます form without ます, and ながら joins it: two things at the same time.","たり goes on the た form: 聞いたり. 聞きたり is not a form."],"explain":null,"unit":5,"day":4,"step":"compare"},"n5u05d4.d1":{"id":"n5u05d4.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[父|ちち]はいつもラジオを（　　）、^[車|くるま]をあらいます^。","options":["[聞|き]いてながら","[聞|き]きますながら","[聞|き]きながら","[聞|き]くながら"],"answer":3,"why":["聞いて is the て form. ながら does not go on it.","ます has to come off before ながら: 聞き, not 聞きます.","The ます form without ます, then ながら: he listens while he washes the car.","聞く is the dictionary form. ながら does not go on it."],"explain":null,"unit":5,"day":4,"step":"drill"},"n5u05d4.d2":{"id":"n5u05d4.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ジュースを[飲|の]み（　　）、^[友|とも]だちと[話|はな]しました^。","options":["まで","ながら","たり","から"],"answer":2,"why":["まで does not join 飲み.","飲み is the ます form without ます. With ながら, she drinks and talks at the same time.","たり goes on the た form: 飲んだり. 飲みたり is not a form.","から does not join 飲み. It would need 飲んでから."],"explain":null,"unit":5,"day":4,"step":"drill"},"n5u05d4.d3":{"id":"n5u05d4.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[休|やす]みの[日|ひ]は、[本|ほん]を^[読|よ]んだり^、テレビを（　　）します。","options":["[見|み]たり","[見|み]ながら","[見|み]て","[見|み]ます"],"answer":1,"why":["読んだり comes first, so the second action takes たり too, then します.","見ながら needs a main action after it. します alone does not say what you do.","見て cannot come right before します here.","見ます is already an ending. It cannot come before another します."],"unit":5,"day":4,"step":"drill"},"n5u05d4.d4":{"id":"n5u05d4.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きのうは[友|とも]だちとカレーを（　　）、^[話|はな]したり^しました。","options":["[食|た]べますたり","[食|た]べるたり","[食|た]べたり","[食|た]べだり"],"answer":3,"why":["たり does not go on the ます form.","たり does not go on the dictionary form.","The た form of 食べます is 食べた, so 食べたり, paired with 話したり.","だり is only for verbs whose た form ends in だ, like 読んだ. 食べた ends in た."],"explain":null,"unit":5,"day":4,"step":"drill"},"n5u05d4.d5":{"id":"n5u05d4.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[母|はは]は","after":"。","tiles":["うたを","うたい","ながら","りょうりをします"],"star":1,"bank":[2,3,0,1],"hint":"Which action is the main one? It comes last, with the polite ending.","full":"[母|はは]はうたをうたい{ながら}りょうりをします。","explain":"うたを comes before うたい, and ながら goes right after the stem うたい. Cooking is the main action, so りょうりをします goes last.","unit":5,"day":4,"step":"drill"},"n5u05d4.d6":{"id":"n5u05d4.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[日|にち]よう[日|び]は[山|やま]へ","after":"します。","tiles":["[行|い]ったり","[友|とも]だちの","うちで","あそんだり"],"star":1,"bank":[3,1,0,2],"hint":"What do you do with 山へ? Then: whose house?","full":"[日|にち]よう[日|び]は[山|やま]へ[行|い]っ{たり}[友|とも]だちのうちであそん{だり}します。","explain":"山へ goes with 行ったり. 友だちの describes うち, so 友だちの comes right before うちで, and あそんだり follows, before します.","unit":5,"day":4,"step":"drill"},"n5u05d4.e1":{"id":"n5u05d4.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ラジオを　（　　）　ながら、そうじを　します。","options":["聞いて","聞きます","聞き","聞く"],"answer":3,"explain":"ながら goes on the ます form without ます: 聞きながら. It does not go on the dictionary form 聞く, the て form 聞いて, or 聞きます with ます still on.","unit":5,"day":4,"step":"exam"},"n5u05d4.e2":{"id":"n5u05d4.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"休みの　日は　そうじを　したり、せんたくを　（　　）　します。","options":["しながら","して","します","したり"],"answer":4,"explain":"The first action has したり, so the second takes たり too, and します ends the list: せんたくを したり します. しながら needs a main action after it, and して and します cannot come right before します.","unit":5,"day":4,"step":"exam"},"n5u05d4.e3":{"id":"n5u05d4.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"父は　いつも","after":"を　飲みます。","tiles":["新聞を","読み","ながら","コーヒー"],"star":2,"bank":[3,1,0,2],"full":"父は　いつも　新聞を　読み{ながら}　コーヒーを　飲みます。","explain":"新聞を, 読み, ながら, コーヒー: he drinks coffee while reading the newspaper. 新聞を goes with 読み, ながら follows the stem, and コーヒー sits right before を 飲みます.","unit":5,"day":4,"step":"exam"},"n5u05d4.k1":{"id":"n5u05d4.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_午後_　二時から　山の　話を　聞きます。","options":["ごご","ごうご","ごこ","ごぜん"],"answer":1,"explain":"午後 is ごご, the afternoon. ごぜん is 午前, the morning. ごうご and ごこ are not words.","unit":5,"day":4,"step":"scene"},"n5u05d4.r1":{"id":"n5u05d4.r1","kind":"choice","type":"読解・内容理解（短文）","q":"この　人は　日よう日の　午後、何を　しますか。","options":["うちで　おんがくを　聞きます。","こうえんで　はしります。","きっさてんや　本やへ　行きます。","テレビを　見ながら　ばんごはんを　食べます。"],"short":["うちでおんがくを聞く","こうえんではしる","きっさてんや本やへ行く","テレビを見ながらばんごはん"],"answer":3,"explain":"After 午後は, the writer talks with friends at a coffee shop and looks at books in a bookshop: they go to both places.","why":["The writer listens to music while running in the park in the morning, not at home.","Running in the park is in the morning (午前).","","Dinner in front of the TV is in the evening (よる)."],"unit":5,"day":4,"step":"skill"},"n5u05d5.c1":{"id":"n5u05d5.c1","kind":"choice","type":"文の文法1","label":"しゅくだい","q":"A「もうしゅくだいをしましたか。」B「^いいえ^、（　　）。^これからします^。」","options":["しませんでした","まだです","もうしました"],"answer":2,"why":["しませんでした tells about a past time. It does not answer もう〜ましたか; for \"not yet\" say まだです.","B says いいえ and will do it from now, so it is not done yet: まだです.","もうしました means it is already done, but B says いいえ and これからします."],"explain":null,"unit":5,"day":5,"step":"compare"},"n5u05d5.d1":{"id":"n5u05d5.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「いっしょにひるごはんを[食|た]べませんか。」B「^すみません^、^もう^（　　）。」","options":["[食|た]べました","[食|た]べましょう","[食|た]べませんか","[食|た]べたいです"],"answer":1,"why":["B has already eaten, so B says sorry: もう食べました, \"I have already eaten.\"","食べましょう says yes to the plan, but B says すみません to turn it down.","食べませんか is an invitation. A is the one inviting; B is answering.","B says すみません to say no. もう食べたいです does not turn A down."],"unit":5,"day":5,"step":"drill"},"n5u05d5.d2":{"id":"n5u05d5.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あんパンはありますか。」B「^すみません^、[今日|きょう]は^もう^（　　）。」","options":["ありました","ありませんでした","ありません","あります"],"answer":3,"why":["ありました is the past. The customer asks about now.","ありませんでした is the past. The bread is gone now, so the shop says ありません.","もう with a \"not\" ending means \"not any more\": they are sold out now.","すみません tells us the news is bad. もうあります does not say they are gone."],"explain":null,"unit":5,"day":5,"step":"drill"},"n5u05d5.d3":{"id":"n5u05d5.d3","kind":"choice","type":"文の文法1","label":"Choose the answer","q":"A「もう[駅|えき]につきましたか。」B「^いいえ^、（　　）。^あと[五分|ごふん]ぐらいです^。」","options":["まだです","もうつきました","つきませんでした","もうありません"],"answer":1,"why":["B is not at the station yet; five more minutes. いいえ、まだです is \"not yet\".","もうつきました means he has arrived, but he says いいえ and five more minutes.","つきませんでした tells about a past time. To answer もう〜ましたか with \"not yet\", say まだです.","もうありません means \"there is none any more\". It does not answer \"have you arrived?\"."],"unit":5,"day":5,"step":"drill"},"n5u05d5.d4":{"id":"n5u05d5.d4","kind":"choice","type":"文の文法1","label":"Choose the word","q":"[電車|でんしゃ]は[九時|くじ]です。^[今|いま]は[八時|はちじ]です^。（　　）[時間|じかん]がありますね。","options":["いつ","ぜんぜん","まだ","もう"],"answer":3,"why":["いつ asks \"when\". This sentence is not a question.","ぜんぜん goes with a \"not\" ending like ありません. Here the verb is あります.","It is eight and the train is at nine, so there is still time: まだ時間があります.","With an hour left, the speaker means \"still\", and that is まだ. もう here would sound like time is running out."],"explain":null,"unit":5,"day":5,"step":"drill"},"n5u05d5.d5":{"id":"n5u05d5.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"すみません、[九時|くじ]の","after":"。","tiles":["[電車|でんしゃ]","は","もう","[出|で]ました"],"star":2,"bank":[3,2,0,1],"hint":"九時の describes a noun. Then the topic with は, then もう before the verb.","full":"すみません、[九時|くじ]の[電車|でんしゃ]は{もう}[出|で]ました。","explain":"九時の goes before 電車. は makes the train the topic, and もう comes before 出ました: \"The nine o'clock train has already left.\"","unit":5,"day":5,"step":"drill"},"n5u05d5.d6":{"id":"n5u05d5.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「おとうとさんは[大学生|だいがくせい]ですか。」B「いいえ、おとうとは","after":"。」","tiles":["まだ","[十六|じゅうろく]","さい","です"],"star":0,"bank":[2,0,3,1],"hint":"まだ comes before the noun it is about. さい follows the number, and です comes last.","full":"A「おとうとさんは[大学生|だいがくせい]ですか。」B「いいえ、おとうとは{まだ}[十六|じゅうろく]さいです。」","explain":"まだ comes first, then 十六さい (sixteen years old), then です: \"He is still sixteen.\"","unit":5,"day":5,"step":"drill"},"n5u05d5.e1":{"id":"n5u05d5.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　本、もう　読みましたか。」B「はい、（　　）。おもしろかったです。」","options":["もう　読みます","もう　読みました","まだ　読みました","まだです"],"answer":2,"explain":"B says はい and おもしろかったです, so B has finished the book: もう読みました. まだ does not go with a finished action like 読みました. まだです means \"not yet\", which does not fit はい. もう読みます talks about now or later, but B already read it.","unit":5,"day":5,"step":"exam"},"n5u05d5.e2":{"id":"n5u05d5.e2","kind":"choice","type":"文の文法1","label":"Choose the word","q":"A「山下さんは　まだ　会社に　いますか。」B「いいえ、（　　）　いません。五時に　かえりました。」","options":["たくさん","すこし","もう","まだ"],"answer":3,"explain":"山下さん went home at five, so he is not at the office any more: もういません. まだいません would mean he has not come yet. たくさん and すこし tell how many or how much, and do not fit one person who has left.","unit":5,"day":5,"step":"exam"},"n5u05d5.e3":{"id":"n5u05d5.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「何か　飲みませんか。」B「いいですね。でも、つめたい","after":"よ。」","tiles":["ジュース","は","もう","ありません"],"star":2,"bank":[2,3,0,1],"full":"A「何か　飲みませんか。」B「いいですね。でも、つめたいジュースは{もう}ありませんよ。」","explain":"ジュース, は, もう, ありません. つめたい describes ジュース, は makes it the topic, and もう with ありません means \"there is none left\".","unit":5,"day":5,"step":"exam"},"n5u05d5.k1":{"id":"n5u05d5.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"三時の　電車は　もう　_出ました_。","options":["でました","だしました","きました","いました"],"answer":1,"explain":"出ました is read でました, \"has left\". だしました would be written 出しました, with し. きました (来ました) and いました are other verbs.","unit":5,"day":5,"step":"scene"},"n5u05d5.r1":{"id":"n5u05d5.r1","kind":"choice","type":"課題理解","q":"男の人は　このあと　何を　しますか。","script":["ナレーター：女の人と男の人が話しています。男の人は、このあと何をしますか。","女：あしたから、りょこうですね。もう、きっぷを買いましたか。","男：はい、きのう、駅で買いました。","女：ホテルは？","男：ホテルにも、もう電話しました。","女：じゃあ、かばんに、もうふくを入れましたか。","男：いいえ、まだです。","女：え、まだですか。あしたの電車は、あさ七時ですよ。","男：そうですね。じゃあ、今から入れます。おかしは、あした駅で買います。","ナレーター：男の人は、このあと何をしますか。"],"options":["ホテルに　電話します","かばんに　ふくを　入れます","おかしを　買います","きっぷを　買います"],"printed":true,"short":["ホテルに 電話","ふくを 入れる","おかしを 買う","きっぷを 買う"],"answer":2,"why":["He already called the hotel: もう電話しました.","He has not packed yet (いいえ、まだです), and he says 今から入れます, \"I'll pack now.\"","He will buy snacks tomorrow at the station, not now.","He already bought the ticket yesterday at the station: はい、きのう、駅で買いました."],"explain":null,"unit":5,"day":5,"step":"skill","clip":"l_n5u5d5"},"n5u05d6.c1":{"id":"n5u05d6.c1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ひるごはんを^[食|た]べた^（　　）、[少|すこ]し[休|やす]みます。","options":["[前|まえ]に","[後|あと]で","てから"],"answer":2,"why":["前に comes after the dictionary form: 食べる前に. 食べた does not go before 前に.","食べた is the た-form, and the た-form goes before 後で: 食べた後で, after I eat lunch.","てから joins the te-form: 食べてから. 食べた is not a te-form."],"unit":5,"day":6,"step":"compare"},"n5u05d6.d1":{"id":"n5u05d6.d1","kind":"choice","type":"文の文法1","label":"Choose the particles","q":"[学校|がっこう]は[八時|はちじ][半|はん]（　　）^[三時|さんじ]まで^です。わたしは[毎日|まいにち][七時|しちじ]（　　）^おきます^。","options":["から／に","まで／に","から／で","に／に"],"answer":1,"why":["The start of the school day takes から, paired with 三時まで. The time you get up is one point in time, so it takes に.","まで marks an end. 八時半まで三時まで gives two ends and no start.","から is right for the start. But a clock time with おきます takes に, not で.","The second に is right, but the first is not. With まで for the end, the start takes から."],"explain":null,"unit":5,"day":6,"step":"drill"},"n5u05d6.d2":{"id":"n5u05d6.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[母|はは]はいつも^ねる^（　　）、ラジオを[聞|き]きます。","options":["[前|まえ]に","[後|あと]で","てから","ながら"],"answer":1,"why":["ねる is the dictionary form, the form that goes before 前に: she listens to the radio before she goes to bed.","後で needs the た-form: ねた後で. ねる does not go before 後で.","から in this pattern joins the te-form, as in 食べてから. ねる is not a te-form.","ながら goes on the ます form without ます, as in 聞きながら. ねる is the dictionary form, so it does not fit."],"unit":5,"day":6,"step":"drill"},"n5u05d6.d3":{"id":"n5u05d6.d3","kind":"choice","type":"文の文法1","label":"Choose the words","q":"この[店|みせ]は[十時|じゅうじ]から[七時|しちじ]（　　）です。^[今|いま]はよるの[八時|はちじ]^ですから、（　　）[買|か]いものができません。","options":["まで／もう","まで／まだ","に／もう","から／まだ"],"answer":1,"why":["十時から pairs with 七時まで for the closing time. It is eight at night now, after closing, so もう〜ません: you can't shop any more.","まで is right, but まだ〜ません means not yet, as if the shop opens later. At eight at night it has already closed.","With 十時から, the end takes まで, not に. もう is right.","The opening time already has から, so the closing time needs まで. And まだ means not yet, but the shop has already closed."],"unit":5,"day":6,"step":"drill"},"n5u05d6.d4":{"id":"n5u05d6.d4","kind":"choice","type":"文の文法1","label":"Choose the words","q":"あつい（　　）、テレビを^[見|み]^（　　）アイスを[食|た]べます。","options":["とき／たり","のとき／から","とき／ながら","のとき／ながら"],"answer":3,"why":["とき is right, but たり needs a second たり and します at the end. This sentence ends in 食べます.","An い-adjective takes no の before とき. And から in this pattern joins the te-form, 見て, not 見.","あつい is an い-adjective, so とき comes right after it. 見 is the ます form without ます, so ながら fits: I watch TV while I eat ice cream.","ながら is right, but an い-adjective takes no の before とき: あついとき."],"explain":null,"unit":5,"day":6,"step":"drill"},"n5u05d6.d5":{"id":"n5u05d6.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"テストが","after":"[読|よ]んだりしました。","tiles":["おわった","[後|あと]で","[友|とも]だちと[話|はな]したり","[本|ほん]を"],"star":2,"bank":[3,1,0,2],"hint":"Which form goes before 後で? Which tile goes with 読んだり at the end?","full":"テストがおわった[後|あと]で{[友|とも]だちと[話|はな]したり}[本|ほん]を[読|よ]んだりしました。","explain":"おわった is the た-form, so it goes right before 後で. Then the two たり actions follow: 友だちと話したり first, then 本を, which goes with 読んだりしました at the end.","unit":5,"day":6,"step":"drill"},"n5u05d6.d6":{"id":"n5u05d6.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「もう[本|ほん]を[買|か]いましたか。」B「いいえ、まだです。","after":"[買|か]います。」","tiles":["ぎんこう","へ","[行|い]って","から"],"star":2,"bank":[2,0,3,1],"hint":"First one action, then the other. Which tile can join から?","full":"A「もう[本|ほん]を[買|か]いましたか。」B「いいえ、まだです。ぎんこうへ{[行|い]って}から[買|か]います。」","explain":"いいえ、まだです answers もう〜ましたか: not yet. Then ぎんこうへ行ってから: 行って is the te-form, and から joins it to say first the bank, then buying the book.","unit":5,"day":6,"step":"drill"},"n5u05d6.e1":{"id":"n5u05d6.e1","kind":"choice","type":"文の文法1","label":"Choose the answer","q":"A「もう　ひるごはんを　食べましたか。」\nB「いいえ、（　　）。じゅぎょうが　おわった　後で　食べます。」","options":["まだです","もう　食べました","食べませんでした","もう　ありません"],"answer":1,"explain":"B has not eaten yet and will eat after class, so the answer to もう〜ましたか is いいえ、まだです. もう　食べました says B has eaten, which does not go with いいえ. 食べませんでした tells about a past time B did not eat, not \"not yet\". もう　ありません means there is none left, which does not answer the question.","unit":5,"day":6,"step":"exam"},"n5u05d6.e2":{"id":"n5u05d6.e2","kind":"choice","type":"文の文法1","label":"Choose the word","q":"父は　毎あさ　新聞を　読んで（　　）、会社へ　行きます。","options":["前に","後で","とき","から"],"answer":4,"explain":"読んで is the te-form, and から joins it: 読んでから, first the paper, then work. 前に needs the dictionary form (読む前に) and 後で needs the た-form (読んだ後で). とき does not join a te-form either. Only から fits after 読んで.","unit":5,"day":6,"step":"exam"},"n5u05d6.e3":{"id":"n5u05d6.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"しごとの　","after":"日本語を　べんきょうします。","tiles":["後で","六時","から","八時まで"],"star":1,"bank":[3,2,0,1],"full":"しごとの　後で　{六時}　から　八時まで　日本語を　べんきょうします。","explain":"後で, 六時, から, 八時まで. しごとの goes with 後で: after work. Then the start comes first with から, 六時から, and the end comes after it with まで, 八時まで.","unit":5,"day":6,"step":"exam"},"n5u05d6.k1":{"id":"n5u05d6.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"バスは　_四時十五分_に　学校へ　かえります。","options":["よんじじゅうごふん","しじじゅうごふん","よじじゅうごぷん","よじじゅうごふん"],"answer":4,"explain":"四時 is always よじ, and 十五分 is じゅうごふん, so 四時十五分 is よじじゅうごふん. よんじ and しじ are not used for four o'clock, and 五 is followed by ふん, not ぷん.","unit":5,"day":6,"step":"scene"},"n5u05d6.r1":{"id":"n5u05d6.r1","kind":"choice","type":"読解・情報検索","q":"みんなは　何時に　学校に　かえりますか。","options":["九時","十二時","二時半","四時十五分"],"short":["9:00","12:00","2:30","4:15"],"answer":4,"explain":"The line 四時十五分　学校に　かえります gives the time the class gets back to school: a quarter past four.","why":["At nine the bus leaves the school.","Twelve is lunch on top of the mountain.","Half past two is when the bus leaves the mountain, not when it gets to the school.",""],"unit":5,"day":6,"step":"skill"},"n5u05t.1":{"id":"n5u05t.1","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"わたしは　_毎週_　日よう日に　テニスを　します。","options":["まいしゅう","まいしゅ","めいしゅう","まいにち"],"answer":1,"explain":"毎週 is まいしゅう, every week. まいにち is a real word, but it is 毎日 (every day), not read from 週. まいしゅ has a short しゅ, and めいしゅう changes まい to めい; neither is a word.","unit":5,"step":"test"},"n5u05t.2":{"id":"n5u05t.2","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"_来月_　国へ　かえります。","options":["らいつき","らいげつ","らいがつ","こんげつ"],"answer":2,"explain":"来月 is らいげつ, next month. こんげつ is 今月 (this month), a different word. In 来月 the 月 is げつ, so らいがつ and らいつき are not words.","unit":5,"step":"test"},"n5u05t.3":{"id":"n5u05t.3","kind":"choice","type":"表記","label":"Kanji spelling","q":"_せんしゅう_　友だちと　山へ　行きました。","options":["先週","千週","生週","先月"],"answer":1,"explain":"せんしゅう (last week) is 先週. 先月 is せんげつ (last month), a real word but not せんしゅう. 千 is the number one thousand and 生 is the せい of 先生, so 千週 and 生週 are not words.","unit":5,"step":"test"},"n5u05t.4":{"id":"n5u05t.4","kind":"choice","type":"表記","label":"Kanji spelling","q":"_まいにち_　七時半に　うちを　出ます。","options":["毎月","毎目","母日","毎日"],"answer":4,"explain":"まいにち (every day) is 毎日. 毎月 is まいつき (every month), a real word but not まいにち. 毎目 uses 目 (eye) instead of 日, and 母日 uses 母 (mother) instead of 毎; neither is a word.","unit":5,"step":"test"},"n5u05t.5":{"id":"n5u05t.5","kind":"choice","type":"文脈規定","label":"Word in context","q":"A「おなかが　すきましたね。」B「ええ。もう　十二時ですから、（　　）ごはんを　食べに　行きましょう。」","options":["あさ","ばん","ごご","ひる"],"answer":4,"explain":"They are hungry at twelve o'clock, so they go for lunch: ひるごはん. あさごはん is breakfast and ばんごはん is dinner, and neither is eaten at twelve. ごご (afternoon) does not join ごはん to name a meal.","unit":5,"step":"test"},"n5u05t.6":{"id":"n5u05t.6","kind":"choice","type":"文脈規定","label":"Word in context","q":"きょうは　月よう日です。（　　）は　水よう日です。","options":["おととい","あした","きのう","あさって"],"answer":4,"explain":"Today is Monday, and Wednesday is two days later: あさって (the day after tomorrow). あした would be Tuesday. きのう (yesterday) and おととい (the day before yesterday) are days before Monday, so they would be Sunday and Saturday.","unit":5,"step":"test"},"n5u05t.7":{"id":"n5u05t.7","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"テストは　_一時から　二時半まで_です。","options":["テストは　一時間です。","テストは　一時間半です。","テストは　二時間半です。","テストは　三十分です。"],"answer":2,"explain":"From one o'clock until half past two is one and a half hours: 一時間半. 一時間 is half an hour too short and 三十分 is much too short. 二時間半 comes from reading only the end time, 二時半, not the length of the test.","unit":5,"step":"test"},"n5u05t.8":{"id":"n5u05t.8","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"_けさ_　コーヒーを　飲みました。","options":["きのうの　ばん　コーヒーを　飲みました。","きのうの　あさ　コーヒーを　飲みました。","きょうの　ばん　コーヒーを　飲みました。","きょうの　あさ　コーヒーを　飲みました。"],"answer":4,"explain":"けさ means this morning, which is きょうの あさ. きのうの あさ is yesterday morning, not this morning. きのうの ばん and きょうの ばん are evenings, not mornings.","unit":5,"step":"test"},"n5u05t.9":{"id":"n5u05t.9","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"あしたの　あさ　十時（　　）　駅の　前で　会いましょう。","options":["が","に","で","を"],"answer":2,"explain":"A clock time when something happens takes に: 十時に 会いましょう (let's meet at ten). で here would mark a place, and the place is 駅の 前で already. を and が do not go after a time that says when you meet.","unit":5,"step":"test"},"n5u05t.10":{"id":"n5u05t.10","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"うちから　学校（　　）　あるいて　二十分です。","options":["を","で","と","まで"],"answer":4,"explain":"から goes with まで: うちから 学校まで (from home to school) is twenty minutes on foot. 学校を あるいて would mean walking around inside the school. 学校で marks where something happens, and 学校と means \"with the school\"; neither gives the end of the walk.","unit":5,"step":"test"},"n5u05t.11":{"id":"n5u05t.11","kind":"choice","type":"文の文法1","label":"Choose the form","q":"うちを　（　　）　前に、テレビを　けします。","options":["出た","出て","出ます","出る"],"answer":4,"explain":"前に joins the dictionary form of a verb: 出る 前に (before leaving). 出た is the past form, which goes with 後で, not 前に. 出て (the て form) and 出ます (the polite ending) do not come before 前に.","unit":5,"step":"test"},"n5u05t.12":{"id":"n5u05t.12","kind":"choice","type":"文の文法1","label":"Choose the form","q":"おふろに　入った　（　　）、ジュースを　飲みます。","options":["まで","前に","ながら","後で"],"answer":4,"explain":"入った is the past form, and the past form goes before 後で: 入った 後で (after taking a bath). 前に needs the dictionary form (入る 前に), so 入った 前に is wrong. ながら joins the ます form without ます (入りながら), not 入った. 入った まで does not make sense here.","unit":5,"step":"test"},"n5u05t.13":{"id":"n5u05t.13","kind":"choice","type":"文の文法1","label":"Choose the form","q":"母に　電話を　かけて（　　）、出かけます。","options":["ながら","から","とき","まで"],"answer":2,"explain":"The て form plus から means \"after doing A, then B\": かけてから 出かけます (I call my mother, then go out). ながら joins the ます form without ます (かけながら), and とき joins the dictionary or past form (かける とき), so neither follows かけて. かけて まで does not make sense here.","unit":5,"step":"test"},"n5u05t.14":{"id":"n5u05t.14","kind":"choice","type":"文の文法1","label":"Choose the form","q":"なつ休みは　うみで　およいだり、山に　（　　）　しました。","options":["のぼりました","のぼったり","のぼって","のぼりながら"],"answer":2,"explain":"およいだり needs a second たり form before しました: およいだり、のぼったり しました (swam, climbed mountains and so on). のぼって and のぼりながら do not go right before しました, and のぼりました しました puts two polite verbs together.","unit":5,"step":"test"},"n5u05t.15":{"id":"n5u05t.15","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「しゅくだいは　もう　おわりましたか。」B「いいえ、（　　）です。今から　します。」","options":["よく","いつも","もう","まだ"],"answer":4,"explain":"B says いいえ and will start now, so the homework is not finished yet: まだです. もうです is not a way to answer, and もう (already) does not fit いいえ. よく (often) and いつも (always) do not answer \"is it finished yet?\".","unit":5,"step":"test"},"n5u05t.16":{"id":"n5u05t.16","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「いつ　この　まちに　来ましたか。」B「","after":"　来ました。」","tiles":["十さい","の","とき","に"],"star":1,"bank":[2,0,3,1],"full":"A「いつ　この　まちに　来ましたか。」B「十さい{の}　ときに　来ました。」","explain":"十さい, の, とき, に. A noun (十さい, ten years old) joins とき with の: 十さいの とき (when I was ten). に after とき says when B came: ときに 来ました. の cannot go after とき or に, because then 十さい and とき are not joined.","unit":5,"step":"test"},"n5u05t.17":{"id":"n5u05t.17","kind":"star","type":"文の文法2","label":"Build the sentence","before":"父は　毎あさ　ラジオを　","after":"。","tiles":["聞き","ながら","こうえんを","あるきます"],"star":2,"bank":[3,1,0,2],"full":"父は　毎あさ　ラジオを　聞きながら　{こうえんを}　あるきます。","explain":"聞き, ながら, こうえんを, あるきます. ラジオを needs its verb right after it, so 聞き comes first, and ながら joins it: 聞きながら (while listening). The main action comes after the ながら part: こうえんを あるきます (walks in the park), with あるきます at the end. こうえんを cannot come before 聞き, because you do not listen to a park.","unit":5,"step":"test"},"n5u05t.18":{"id":"n5u05t.18","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「もう　おきますか。」B「いいえ、","after":"、もう少し　ねます。」","tiles":["まだ","六時","です","から"],"star":1,"bank":[2,3,0,1],"full":"A「もう　おきますか。」B「いいえ、まだ　{六時}ですから、もう少し　ねます。」","explain":"まだ, 六時, です, から. まだ goes before the time: まだ 六時です (it is still only six). から after です gives the reason: it is still six, so B sleeps a little more. まだ cannot come after 六時 or です, because まだ comes before the word it describes.","unit":5,"step":"test"},"n5u05t.19":{"id":"n5u05t.19","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"わたしは　毎あさ　六時半に　おきて、いぬと　さんぽに　行きます。さんぽから　かえってから、シャワーを　あびて、あさごはんを　食べます。会社は　九時からです。ひる休みは　十二時から　一時までです。ひる休みには　いつも　本を　読みながら　パンを　食べます。","q":"この　人は　さんぽの　後で、はじめに　何を　しますか。","options":["シャワーを　あびます。","本を　読みます。","会社へ　行きます。","あさごはんを　食べます。"],"answer":1,"short":["シャワー","本","会社","あさごはん"],"explain":"The writer says さんぽから かえってから、シャワーを あびて、あさごはんを 食べます: first a shower, then breakfast. Breakfast comes after the shower, not first. The writer reads at lunch break, and work starts at nine, after breakfast.","unit":5,"step":"test"},"n5u05t.20":{"id":"n5u05t.20","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"わたしは　毎あさ　六時半に　おきて、いぬと　さんぽに　行きます。さんぽから　かえってから、シャワーを　あびて、あさごはんを　食べます。会社は　九時からです。ひる休みは　十二時から　一時までです。ひる休みには　いつも　本を　読みながら　パンを　食べます。","q":"ただしい　ものは　どれですか。","options":["会社は　九時までです。","ひる休みは　一時間です。","ひる休みに　本を　読んだ　後で、パンを　食べます。","この　人は　六時に　おきます。"],"answer":2,"short":["九時まで","ひる休み一時間","読んだ後でパン","六時におきる"],"explain":"Lunch break is 十二時から 一時まで, which is one hour. The writer gets up at 六時半, not six. Work is 九時から (starts at nine), not until nine. The writer eats bread while reading (読みながら), not after reading.","unit":5,"step":"test"},"n5u05t.21":{"id":"n5u05t.21","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"さくらプール\n月よう日　休み\n火よう日〜金よう日　午前　十時〜午後　八時\n土よう日・日よう日　午前　九時〜午後　五時\n＊水よう日の　午後　一時から　三時までは　休みです。\n＊子どもは　お父さんか　お母さんと　いっしょに　来て　ください。","q":"リンさんは　毎日　六時まで　しごとを　します。しごとの　後で　プールへ　行きたいです。何よう日に　行きますか。","options":["木よう日","土よう日","日よう日","月よう日"],"answer":1,"short":["木","土","日","月"],"explain":"Rin finishes work at six, so the pool must be open after six. On 木よう日 it is open until 午後 八時. 月よう日 is the pool's day off (休み). On 土よう日 and 日よう日 it closes at 午後 五時, before Rin finishes work.","unit":5,"step":"test"},"n5u05t.22":{"id":"n5u05t.22","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"さくらプール\n月よう日　休み\n火よう日〜金よう日　午前　十時〜午後　八時\n土よう日・日よう日　午前　九時〜午後　五時\n＊水よう日の　午後　一時から　三時までは　休みです。\n＊子どもは　お父さんか　お母さんと　いっしょに　来て　ください。","q":"ヤンさんは　水よう日の　午後に　プールへ　行きます。何時に　行きますか。","options":["午後　三時半","午後　二時","午後　二時半","午後　九時"],"answer":1,"short":["三時半","二時","二時半","九時"],"explain":"On 水よう日 the pool is open until 午後 八時, but it is closed 午後 一時から 三時まで. 三時半 is after the break and before eight. 二時 and 二時半 fall in the closed time, and 九時 is after the pool closes.","unit":5,"step":"test"},"n5u05t.23":{"id":"n5u05t.23","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ゆうたへ\nお母さんは　今から　買いものに　行きます。六時ごろ　かえります。しゅくだいを　してから、あそびに　行って　ください。ばんごはんの　前に、へやの　まどを　しめて　ください。おかしは　ばんごはんの　後で　食べましょう。\n母","q":"ゆうたくんは　いつ　おかしを　食べますか。","options":["しゅくだいの　前","あそびに　行く　前","ばんごはんの　前","ばんごはんの　後"],"answer":4,"short":["しゅくだいの前","あそぶ前","ばんごはんの前","ばんごはんの後"],"explain":"The note says おかしは ばんごはんの 後で 食べましょう: after dinner. Before homework and before going out to play are not times for snacks in the note. ばんごはんの 前 is when ゆうた closes the windows, not when he eats snacks.","unit":5,"step":"test"},"n5u05t.24":{"id":"n5u05t.24","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ゆうたへ\nお母さんは　今から　買いものに　行きます。六時ごろ　かえります。しゅくだいを　してから、あそびに　行って　ください。ばんごはんの　前に、へやの　まどを　しめて　ください。おかしは　ばんごはんの　後で　食べましょう。\n母","q":"ただしい　ものは　どれですか。","options":["お母さんは　六時に　買いものに　行きます。","ゆうたくんは　あそびに　行ってから、しゅくだいを　します。","ゆうたくんは　お母さんと　買いものに　行きます。","ゆうたくんは　ばんごはんの　前に　まどを　しめます。"],"answer":4,"short":["六時に買いもの","あそんでからしゅくだい","母と買いもの","前にまどをしめる"],"explain":"The note says ばんごはんの 前に、へやの まどを しめて ください, so ゆうた closes the windows before dinner. His mother goes shopping now (今から) and comes back around six, so she does not leave at six. ゆうた does his homework first (しゅくだいを してから), then plays. His mother goes shopping alone; ゆうた stays and does homework.","unit":5,"step":"test"},"n5u06d1.c1":{"id":"n5u06d1.c1","kind":"choice","type":"文の文法1","label":"店で","q":"すみません、その[白|しろ]いペン（　　）。","options":["てください","ませんか","をください"],"answer":3,"why":["てください goes after a verb in the て form, like 書いて. ペン is a noun.","ませんか goes after a verb, as in 行きませんか. It cannot come after a noun.","ペン is a thing, so you ask for it with をください: that white pen, please."],"explain":null,"unit":6,"day":1,"step":"compare"},"n5u06d1.d1":{"id":"n5u06d1.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"よる、[本|ほん]を（　　）^、ねます^。","options":["[読|よ]みて","[読|よ]いて","[読|よ]って","[読|よ]んで"],"answer":4,"why":["う-verbs do not just add て. み changes to んで.","いて is for verbs with き before ます, like 書きます → 書いて.","って is for verbs with い, ち or り before ます, like かいます → かって.","読みます has み before ます, so it becomes 読んで: I read, then I sleep."],"explain":null,"unit":6,"day":1,"step":"drill"},"n5u06d1.d2":{"id":"n5u06d1.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[駅|えき]へ（　　）、^[電車|でんしゃ]にのります^。","options":["[行|い]んで","[行|い]いて","[行|い]って","[行|い]きて"],"answer":3,"why":["んで is for verbs with み, び or に before ます, like 読みます → 読んで.","Most verbs with き become いて, but 行きます is the exception.","行きます becomes 行って: I go to the station, then I get on the train.","う-verbs do not just add て. 行きます becomes 行って."],"explain":null,"unit":6,"day":1,"step":"drill"},"n5u06d1.d3":{"id":"n5u06d1.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"すみません、ここに[名前|なまえ]を（　　）^ください^。","options":["[書|か]きて","[書|か]いで","[書|か]きます","[書|か]いて"],"answer":4,"why":["う-verbs do not just add て. き changes to い: 書いて.","いで is for verbs with ぎ before ます, like およぎます → およいで. 書きます takes て.","ください never goes after the ます form.","書きます has き before ます, so it becomes 書いて: please write your name here."],"explain":null,"unit":6,"day":1,"step":"drill"},"n5u06d1.d4":{"id":"n5u06d1.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[今日|きょう]、うちでしゅくだいを（　　）^ください^。","options":["して","しって","するて","します"],"answer":1,"why":["します becomes して: please do your homework at home today.","There is no small っ in the て form of します. It is just して.","する never takes て directly. The て form is して.","ください never goes after the ます form."],"unit":6,"day":1,"step":"drill"},"n5u06d1.d5":{"id":"n5u06d1.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[駅|えき]で","after":"。","tiles":["[電車|でんしゃ]を","おりて","バスに","のります"],"star":1,"bank":[2,0,3,1],"hint":"Getting off the train comes first, with て. Which tile goes with おりて? The second action ends the sentence.","full":"[駅|えき]で[電車|でんしゃ]をおり{て}バスにのります。","explain":"電車をおりて is the first action, so it comes first, in the て form. バスにのります is the second action, and its ます ending closes the sentence.","unit":6,"day":1,"step":"drill"},"n5u06d1.d6":{"id":"n5u06d1.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"すみません、もう","after":"。","tiles":["[少|すこ]し","ゆっくり","[話|はな]して","ください"],"star":2,"bank":[1,3,0,2],"hint":"もう少し is one phrase: a little more. ください comes last, right after the て form.","full":"すみません、もう[少|すこ]しゆっくり[話|はな]して{ください}。","explain":"もう少し means a little more, so 少し sits right after もう. ゆっくり describes how to speak, so it comes before 話して. ください follows the て form and ends the request.","unit":6,"day":1,"step":"drill"},"n5u06d1.e1":{"id":"n5u06d1.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"友だちを　三十分　（　　）、いっしょに　えいがを　見ました。","options":["まつて","まって","まんで","まちて"],"answer":2,"explain":"まちます has ち before ます, so it becomes まって: I waited thirty minutes for my friend, then we saw a film together. まちて and まつて are not forms of this verb, and んで is for verbs with み, び or に, like よみます → よんで.","unit":6,"day":1,"step":"exam"},"n5u06d1.e2":{"id":"n5u06d1.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"先生「では、本の　十ページを　（　　）　ください。」","options":["見て","見って","見んで","見ます"],"answer":1,"explain":"見ます is a る-verb: drop ます and add て, so 見てください, please look at page ten. 見って and 見んで are not forms of 見ます, and ください never goes after the ます form.","unit":6,"day":1,"step":"exam"},"n5u06d1.e3":{"id":"n5u06d1.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"まどを　","after":"　ください。","tiles":["あけて","へやの","そうじを","して"],"star":2,"bank":[3,1,0,2],"full":"まどを　あけて　へやの　{そうじを}　して　ください。","explain":"あけて, へやの, そうじを, して. まどを goes with あけて, the first action. へやの describes そうじ, and そうじを して is the second action, right before ください.","unit":6,"day":1,"step":"exam"},"n5u06d1.k1":{"id":"n5u06d1.k1","kind":"choice","type":"文脈規定","label":"How the exam asks it","q":"テストの　前に、本を　かばんに　（　　）　ください。","options":["出して","読んで","書いて","入れて"],"answer":4,"explain":"かばんに means into the bag, so 入れて: please put your book in your bag before the test. 出して would need かばんから (out of the bag). 読んで and 書いて do not go with かばんに.","unit":6,"day":1,"step":"scene"},"n5u06d1.r1":{"id":"n5u06d1.r1","kind":"choice","type":"発話表現","q":"へやが　あついです。まどの　そばの　人に　何と　いいますか。","script":["ナレーター：へやが　あついです。まどの　そばの　人に　何と　いいますか。","ナレーター：1","女：すみません、まどを　あけましたか。","ナレーター：2","女：すみません、まどを　しめて　ください。","ナレーター：3","女：すみません、まどを　あけて　ください。"],"options":["すみません、まどを　あけましたか。","すみません、まどを　しめて　ください。","すみません、まどを　あけて　ください。"],"printed":false,"short":["まどをあけましたか","まどをしめてください","まどをあけてください"],"answer":3,"why":["あけましたか asks if he already opened it. It does not ask him to open it.","しめて means close. The room is hot and the window is already closed, so she wants it open.",""],"unit":6,"day":1,"step":"skill","clip":"l_n5u6d1"},"n5u06d2.c1":{"id":"n5u06d2.c1","kind":"choice","type":"文の文法1","label":"でんわを かりる","q":"A：すみません、ここで[電話|でんわ]を（　　）か。B：ええ、どうぞ。","options":["かけないでください","かけてもいいです","かけてください"],"answer":2,"why":["ないでください asks someone not to do something. It does not take か, and ええ、どうぞ answers \"may I?\".","A asks permission with てもいいですか, and B says yes with ええ、どうぞ.","てください asks someone else to do something. くださいか is not said, and ええ、どうぞ answers \"may I?\"."],"unit":6,"day":2,"step":"compare"},"n5u06d2.d1":{"id":"n5u06d2.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ここは^[出口|でぐち]です^。ここから（　　）ください。","options":["[入|はい]って","[入|はい]りません","[入|はい]らない","[入|はい]らないで"],"answer":4,"why":["入ってください asks people to come in, but this is the exit, not the way in.","The polite ません form does not go before ください.","でください needs で: 入らないでください. 入らないください is not said.","This is the exit, so the sign asks people not to come in: 入らないでください."],"explain":null,"unit":6,"day":2,"step":"drill"},"n5u06d2.d2":{"id":"n5u06d2.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この[本|ほん]は[古|ふる]いです。^[何|なに]も^（　　）ください。","options":["[書|か]きませんで","[書|か]かない","[書|か]かないで","[書|か]いて"],"answer":3,"why":["The polite ません form does not go before でください.","The で is missing: 書かないでください.","何も goes with a \"not\" form, and 書かないでください means \"please don't write\".","何も needs a \"not\" form after it. 何も書いてください is not said."],"explain":null,"unit":6,"day":2,"step":"drill"},"n5u06d2.d3":{"id":"n5u06d2.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：この[本|ほん]を（　　）^もいいですか^。B：ええ、どうぞ。","options":["[読|よ]んで","[読|よ]む","[読|よ]みます","[読|よ]まない"],"answer":1,"why":["もいいですか follows the て-form: 読んでもいいですか, \"may I read it?\".","読む is the dictionary form. It does not go before もいいです.","The polite ます form does not go before もいいです.","読まない is the ない-form. 読まないもいいですか is not said."],"unit":6,"day":2,"step":"drill"},"n5u06d2.d4":{"id":"n5u06d2.d4","kind":"choice","type":"文の文法1","label":"Choose the answer","q":"A：まどをあけてもいいですか。B：（　　）。きょうは^さむいですから^。","options":["すみません、ちょっと…","はい、あけましょう","いいえ、どういたしまして","ええ、どうぞ"],"answer":1,"why":["B says no softly, and gives the reason: it is cold today.","あけましょう agrees to open it, but B says it is cold.","どういたしまして answers ありがとう, not a question asking permission.","ええ、どうぞ says yes, but B's reason (it is cold today) is a reason to keep the window shut."],"explain":null,"unit":6,"day":2,"step":"drill"},"n5u06d2.d5":{"id":"n5u06d2.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[電車|でんしゃ]の[中|なか]で","after":"。","tiles":["[大|おお]きい","こえで","[話|はな]さないで","ください"],"star":2,"bank":[2,0,3,1],"hint":"大きい describes a noun. Which tile can come right before ください?","full":"[電車|でんしゃ]の[中|なか]で[大|おお]きいこえで[話|はな]さ{ないでください}。","explain":"大きい describes こえ, so 大きいこえで goes together. 話さないで comes right before ください and ends the sentence.","unit":6,"day":2,"step":"drill"},"n5u06d2.d6":{"id":"n5u06d2.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"すみません、この","after":"。","tiles":["ペンを","つかって","も","いいですか"],"star":2,"bank":[3,1,0,2],"hint":"この needs a noun right after it. も comes between the て-form and いいですか.","full":"すみません、このペンをつかって{もいいですか}。","explain":"この goes with ペン, so ペンを comes first. Then the て-form つかって, then も, then いいですか.","unit":6,"day":2,"step":"drill"},"n5u06d2.e1":{"id":"n5u06d2.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この　へやで　おかしを　（　　）　ください。","options":["食べない","食べないで","食べませんで","食べなくて"],"answer":2,"explain":"The ない-form + でください asks someone not to do something: 食べないでください. The ません form does not go before でください, 食べなくてください is not said, and 食べないください is missing で.","unit":6,"day":2,"step":"exam"},"n5u06d2.e2":{"id":"n5u06d2.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「すみません、この　いすに　（　　）　いいですか。」\nB「ええ、どうぞ。」","options":["すわりも","すわっても","すわるも","すわりますも"],"answer":2,"explain":"Asking permission uses the て-form + もいいですか: すわってもいいですか. The dictionary form, the ます form and すわり cannot go before も here.","unit":6,"day":2,"step":"exam"},"n5u06d2.e3":{"id":"n5u06d2.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「すみません、","after":"。」\nB「ええ、どうぞ。」","tiles":["その","まどを","あけても","いいですか"],"star":2,"bank":[3,2,0,1],"full":"A「すみません、その　まどを　{あけても}　いいですか。」\nB「ええ、どうぞ。」","explain":"その, まどを, あけても, いいですか. その must sit right before まど, あけても is the て-form + も, and いいですか ends the question.","unit":6,"day":2,"step":"exam"},"n5u06d2.k1":{"id":"n5u06d2.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"こうえんの　_入口_は　どこですか。","options":["いりぐち","はいりぐち","いりこう","でぐち"],"answer":1,"explain":"入口 is read いりぐち, \"entrance\". でぐち is 出口, \"exit\", and はいりぐち and いりこう are not words.","unit":6,"day":2,"step":"scene"},"n5u06d2.r1":{"id":"n5u06d2.r1","kind":"choice","type":"読解・内容理解（短文）","q":"この　こうえんで　しても　いい　ことは　どれですか。","options":["木の　下で　おべんとうを　食べます。","花の　中に　入って　しゃしんを　とります。","よる　七時に　こうえんで　あそびます。","月よう日の　午前に　さんぽします。"],"short":["木の下でおべんとうを食べる","花の中に入る","よる七時にあそぶ","月よう日にさんぽする"],"answer":1,"explain":"The notice says 木の下でおべんとうを食べてもいいです: eating your lunch under the trees is all right.","why":["","The notice says 花の中に入らないでください.","The park is open only until 5 p.m. (午後五時まで).","The park is closed on Mondays (月よう日は休みです)."],"unit":6,"day":2,"step":"skill"},"n5u06d3.c1":{"id":"n5u06d3.c1","kind":"choice","type":"文の文法1","label":"プールのきまり","q":"プールのそばはあぶないですから、（　　）。","options":["はしってもいいです","はしらなくてもいいです","はしってはいけません"],"answer":3,"why":["てもいいです gives permission. Running is not allowed where it is dangerous (あぶないですから).","なくてもいいです means \"you don't have to run\". Nobody has to run, so this is not a rule here.","あぶないですから gives the reason for a rule: \"It's dangerous by the pool, so you must not run.\""],"unit":6,"day":3,"step":"compare"},"n5u06d3.d1":{"id":"n5u06d3.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：[先生|せんせい]、ここでパンを[食|た]べてもいいですか。B：^いいえ^、（　　）。","options":["[食|た]べてもいいです","[食|た]べなくてもいいです","[食|た]べてはいけません","[食|た]べてください"],"answer":3,"why":["食べてもいいです means \"yes, you may\". It does not fit after いいえ.","食べなくてもいいです means \"you don't have to eat\". A asked for permission, not whether he has to eat.","いいえ says no to \"may I eat?\", and 食べてはいけません says it: \"No, you must not eat.\"","食べてください means \"please eat\". It does not fit after いいえ."],"unit":6,"day":3,"step":"drill"},"n5u06d3.d2":{"id":"n5u06d3.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^プールの[中|なか]で^ジュースを（　　）。","options":["[飲|の]みてはいけません","[飲|の]むではいけません","[飲|の]んてはいけません","[飲|の]んではいけません"],"answer":4,"why":["飲みて is not a word. The te-form is 飲んで.","はいけません follows the te-form, not the dictionary form 飲む. Say 飲んではいけません.","The te-form of 飲みます ends in で: 飲んで. 飲んて is not a word.","飲んで is the te-form of 飲みます. 飲んではいけません: \"You must not drink juice in the pool.\""],"explain":null,"unit":6,"day":3,"step":"drill"},"n5u06d3.d3":{"id":"n5u06d3.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[土|ど]よう[日|び]は^じゅぎょうがありません^。[学校|がっこう]へ（　　）。","options":["きなくてもいいです","こないくてもいいです","こなくてもいいです","くなくてもいいです"],"answer":3,"why":["The ない form of 来ます is 来ない, read こない. きなくて is not a word.","Take off the い of こない before くても. こないくても is wrong.","There are no classes, so こなくてもいいです (来なくてもいいです): \"You don't have to come to school.\"","くなくて is not a word. The ない form of 来ます is こない."],"unit":6,"day":3,"step":"drill"},"n5u06d3.d4":{"id":"n5u06d3.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この[本|ほん]はながいですから、[今日|きょう]^ぜんぶ^[読|よ]（　　）。","options":["まなくてもいいです","みなくてもいいです","むなくてもいいです","まないくてもいいです"],"answer":1,"why":["読まない minus い, plus くてもいいです: \"The book is long, so you don't have to read it all today.\"","読みなくて is not a word. The ない form of 読みます is 読まない.","読むなくて is not a word. The ない form is 読まない.","Take off the い of 読まない before くても. 読まないくても is wrong."],"explain":null,"unit":6,"day":3,"step":"drill"},"n5u06d3.d5":{"id":"n5u06d3.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"テストの","after":"いけません。","tiles":["とき","となりの","[人|ひと]と","[話|はな]しては"],"star":3,"bank":[2,0,3,1],"hint":"テストの goes with とき. となりの goes right before the person, and 話しては comes just before いけません.","full":"テストのときとなりの[人|ひと]と[話|はな]し{ては}いけません。","explain":"とき, となりの, 人と, 話しては. テストのとき is \"during the test\", and となりの describes 人: \"During the test, you must not talk with the person next to you.\"","unit":6,"day":3,"step":"drill"},"n5u06d3.d6":{"id":"n5u06d3.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[今日|きょう]は[雨|あめ]ですから、","after":"です。","tiles":["プールに","[入|はい]ら","なくても","いい"],"star":2,"bank":[3,1,0,2],"hint":"入ら is the ない form without ない. なくても joins it, and いい comes just before です.","full":"[今日|きょう]は[雨|あめ]ですから、プールに[入|はい]ら{なくても}いいです。","explain":"プールに, 入ら, なくても, いい. プールに goes with 入ら, and 入らなくてもいいです means \"you don't have to go in\": \"It's raining today, so you don't have to go in the pool.\"","unit":6,"day":3,"step":"drill"},"n5u06d3.e1":{"id":"n5u06d3.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ここは　先生の　へやです。　学生は　入っては（　　）。","options":["しません","いいです","ください","いけません"],"answer":4,"explain":"入っては needs いけません after it: \"Students must not go in.\" Permission is 入っても いいです, with も, not は. ください follows the te-form alone (入って ください), and 入っては しません is not a phrase.","unit":6,"day":3,"step":"exam"},"n5u06d3.e2":{"id":"n5u06d3.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"今日は　しゅくだいが　ありません。　何も（　　）　いいです。","options":["しないくても","しても","しなくても","しては"],"answer":3,"explain":"There is no homework, so しなくても いいです: \"You don't have to do anything.\" 何も needs a negative after it, so しても いいです fails. しては goes with いけません, not いいです, and しないくても is not a form: the い of しない drops before くても.","unit":6,"day":3,"step":"exam"},"n5u06d3.e3":{"id":"n5u06d3.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"プールに　入る","after":"いけません。","tiles":["前に","パンや","おかしを","食べては"],"star":3,"bank":[1,3,0,2],"full":"プールに　入る　前に　パンや　おかしを　{食べては}　いけません。","explain":"前に, パンや, おかしを, 食べては. 入る前に is \"before going in\", パンや おかしを is what you eat, and 食べては goes with いけません: \"You must not eat bread or sweets before going in the pool.\"","unit":6,"day":3,"step":"exam"},"n5u06d3.k1":{"id":"n5u06d3.k1","kind":"choice","type":"表記","label":"How the exam asks it","q":"プールに　_はいる_　前に、　シャワーを　あびて　ください。","options":["人る","入る","八る","大る"],"answer":2,"explain":"はいる, \"to go in\", is written 入る. 人 (person), 八 (eight) and 大 (big) look a little like 入, but 人る, 八る and 大る are not words.","unit":6,"day":3,"step":"scene"},"n5u06d3.r1":{"id":"n5u06d3.r1","kind":"choice","type":"即時応答","q":"男：先生、プールの　中で　ぼうしを　とっても　いいですか。","script":["男：先生、プールの　中で　ぼうしを　とっても　いいですか。","ナレーター：1","女：いいえ、とらなくても　いいです。","ナレーター：2","女：はい、とりました。","ナレーター：3","女：いいえ、とっては　いけません。"],"options":["いいえ、とらなくても　いいです。","はい、とりました。","いいえ、とっては　いけません。"],"printed":false,"short":["とらなくてもいいです","とりました","とってはいけません"],"answer":3,"why":["とらなくてもいいです means \"you don't have to take it off\". The boy asks for permission, so this does not answer him.","とりました says what someone did. The boy asks whether he may take his cap off.",""],"unit":6,"day":3,"step":"skill","clip":"l_n5u6d3"},"n5u06d4.c1":{"id":"n5u06d4.c1","kind":"choice","type":"文の文法1","label":"かぞく","q":"あには[三年前|さんねんまえ]にけっこんしました。^[今|いま]^はおおさかに（　　）。","options":["すんでいます","すみました","すみます"],"answer":1,"why":["He moved there and still lives there: a lasting state, so すんでいます.","すみました is past, but 今は is about now.","すみます is a plan: \"will live\". 今は asks where he lives now."],"explain":null,"unit":6,"day":4,"step":"compare"},"n5u06d4.d1":{"id":"n5u06d4.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"「もしもし、^[今|いま][何|なに]をしていますか^。」「[今|いま]、テレビを（　　）。」","options":["[見|み]ます","[見|み]ました","[見|み]ています","[見|み]て"],"answer":3,"why":["見ます is a habit or a plan. It does not say what you are doing now.","見ました is past. The question is about right now.","The question asks what you are doing now, so the answer uses 見ています.","A polite answer cannot end on the て form alone. It needs います."],"unit":6,"day":4,"step":"drill"},"n5u06d4.d2":{"id":"n5u06d4.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[今|いま]、[外|そと]は[雨|あめ]が（　　）^います^。","options":["ふった","ふって","ふりて","ふるて"],"answer":2,"why":["ふった is the た form. います goes on the て form.","ふります becomes ふって, then います: it is raining now.","ふりて is not a form. ふる makes its て form with って.","The dictionary form ふる does not take て."],"explain":null,"unit":6,"day":4,"step":"drill"},"n5u06d4.d3":{"id":"n5u06d4.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"「この[店|みせ]の[名前|なまえ]をしっていますか。」「^いいえ^、（　　）。」","options":["しりません","しっていません","しってください","しっています"],"answer":1,"why":["The negative of しっています is しりません: \"No, I don't know.\"","しっていません is not used. Say しりません.","しってください is a request. It does not answer the question.","しっています means \"I know\". It does not fit after いいえ."],"explain":null,"unit":6,"day":4,"step":"drill"},"n5u06d4.d4":{"id":"n5u06d4.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"「どこに（　　）か。」「^とうきょうにすんでいます^。」","options":["すみます","すみましょう","すんで","すんでいます"],"answer":4,"why":["すみますか asks where you will live. The answer says where you live now.","すみましょうか means \"shall we live?\". It does not match the answer.","すんで cannot come right before か.","The answer is すんでいます, so the question asks the same: where do you live?"],"unit":6,"day":4,"step":"drill"},"n5u06d4.d5":{"id":"n5u06d4.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[父|ちち]は[今|いま]、[電話|でんわ]で","after":"います。","tiles":["[会社|かいしゃ]の","[人|ひと]","と","[話|はな]して"],"star":2,"bank":[3,0,2,1],"hint":"Whose person? Then: who is Dad talking with?","full":"[父|ちち]は[今|いま]、[電話|でんわ]で[会社|かいしゃ]の[人|ひと]と[話|はな]して{います}。","explain":"会社の describes 人, and と says who he talks with: 会社の人と. 話して comes last, right before います.","unit":6,"day":4,"step":"drill"},"n5u06d4.d6":{"id":"n5u06d4.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしは","after":"。","tiles":["あの","[人|ひと]の","[名前|なまえ]を","しりません"],"star":3,"bank":[2,3,0,1],"hint":"あの points at a person. The verb comes last.","full":"わたしはあの[人|ひと]の[名前|なまえ]を{しりません}。","explain":"あの goes right before 人の, and 人の describes 名前を. しりません, the negative of しっています, ends the sentence.","unit":6,"day":4,"step":"drill"},"n5u06d4.e1":{"id":"n5u06d4.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"「リンさんは　けっこん　して　いますか。」「はい、（　　）。子どもも　二人　います。」","options":["します","しません","して　います","して　いません"],"answer":3,"explain":"The question asks about a lasting state, so a yes answer is はい、して います: she is married. します is a plan, and しません and して いません do not fit after はい.","unit":6,"day":4,"step":"exam"},"n5u06d4.e2":{"id":"n5u06d4.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"「今、何を　して　いますか。」「へやで　本を　（　　）。」","options":["読んで　います","読みます","読みました","読んで　ください"],"answer":1,"explain":"The question asks what you are doing now, so the answer is 読んで います. 読みます is a habit or plan, 読みました is past, and 読んで ください is a request.","unit":6,"day":4,"step":"exam"},"n5u06d4.e3":{"id":"n5u06d4.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あの　人は　白い","after":"かけて　います。","tiles":["シャツを","きて","くろい","めがねを"],"star":2,"bank":[3,1,0,2],"full":"あの　人は　白い　シャツを　きて　{くろい}　めがねを　かけて　います。","explain":"シャツを, きて, くろい, めがねを. 白い describes シャツ, and you きる a shirt. くろい describes めがね, which goes right before かけて います.","unit":6,"day":4,"step":"exam"},"n5u06d4.k1":{"id":"n5u06d4.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"リンさんは　今　_電話_を　かけて　います。","options":["てんか","てんわ","でんわ","でんか"],"answer":3,"explain":"電話 is でんわ, a phone call. てんわ and てんか are not words, and でんか is a different word.","unit":6,"day":4,"step":"scene"},"n5u06d4.r1":{"id":"n5u06d4.r1","kind":"choice","type":"読解・内容理解（短文）","q":"お母さんは　今　何を　して　いますか。","options":["へやで　本を　読んで　います。","テレビを　見て　います。","外で　友だちと　話して　います。","にわで　車を　あらって　います。"],"short":["本を読んでいる","テレビを見ている","外で友だちと話している","車をあらっている"],"answer":3,"explain":"After が, the writer says that today her mother is outside talking with a friend. 話して います is what she is doing now.","why":["The older brother is reading in his room.","She usually watches TV at this time (見ます), but not today.","","The father is washing the car."],"unit":6,"day":4,"step":"skill"},"n5u06d5.c1":{"id":"n5u06d5.c1","kind":"choice","type":"文の文法1","label":"しゃしん","q":"あした、[友|とも]だちと[山|やま]へ^しゃしんをとり^（　　）。","options":["に[行|い]きます","へ[行|い]きます","つもりです"],"answer":1,"why":["とり is the ます form of とります without ます. With に行きます it says what you go to do: take photos.","へ marks a place you go to, and しゃしんをとり is not a place. 山へ already says where.","つもりです needs the dictionary form: とるつもりです. とりつもりです is not Japanese."],"unit":6,"day":5,"step":"compare"},"n5u06d5.d1":{"id":"n5u06d5.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あした、デパートへくつを（　　）^に[行|い]きます^。","options":["[買|か]う","[買|か]って","[買|か]います","[買|か]い"],"answer":4,"why":["買う is the dictionary form. In this pattern, drop ます from 買います instead: 買いに.","買って is the te-form. 買ってに is not Japanese.","買いますに is not Japanese. Take ます off first: 買いに.","Before に行きます, use the ます form without ます: 買います becomes 買い."],"explain":null,"unit":6,"day":5,"step":"drill"},"n5u06d5.d2":{"id":"n5u06d5.d2","kind":"choice","type":"文の文法1","label":"Choose the particle","q":"[日|にち]よう[日|び]は、[母|はは]と^かいもの^（　　）[行|い]きます。","options":["で","が","に","を"],"answer":3,"why":["で shows where something happens or how. かいもので行きます does not mean \"go shopping\".","が would make かいもの the one who goes. The speaker and mother are the ones going.","かいもの is a noun of action. かいものに行きます means \"go shopping\".","かいものを行きます is not said. To say what you go to do, use に."],"explain":null,"unit":6,"day":5,"step":"drill"},"n5u06d5.d3":{"id":"n5u06d5.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[来週|らいしゅう]の[休|やす]みは、うみへ（　　）^つもりです^。","options":["[行|い]きます","[行|い]って","[行|い]く","[行|い]き"],"answer":3,"why":["行きますつもりです is a common mistake. つもり takes the dictionary form 行く.","行って is the te-form. 行ってつもりです is not Japanese.","つもりです follows the dictionary form: 行くつもりです, \"I plan to go\".","行き is the ます form without ます. It goes before に行きます, not before つもり."],"explain":null,"unit":6,"day":5,"step":"drill"},"n5u06d5.d4":{"id":"n5u06d5.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^あしたはテストです^。[今日|きょう]はテレビを（　　）つもりです。","options":["[見|み]ない","[見|み]ません","[見|み]て","[見|み]に"],"answer":1,"why":["There is a test tomorrow, so the plan is not to watch TV. ない form + つもりです means \"plan not to\".","見ません is the polite \"not\" ending. つもり takes the ない form: 見ないつもりです.","見て is the te-form. 見てつもりです is not Japanese.","見に goes before 行きます or 来ます, not before つもり."],"unit":6,"day":5,"step":"drill"},"n5u06d5.d5":{"id":"n5u06d5.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[日|にち]よう[日|び]、[友|とも]だちが","after":"。","tiles":["うち","へ","あそび","に[来|き]ます"],"star":2,"bank":[2,0,3,1],"hint":"First the place with へ. Then what the friend comes to do, with に来ます.","full":"[日|にち]よう[日|び]、[友|とも]だちがうちへあそび{に[来|き]ます}。","explain":"うちへ says where the friend comes, and あそびに来ます says why: \"On Sunday a friend is coming to my house to hang out.\"","unit":6,"day":5,"step":"drill"},"n5u06d5.d6":{"id":"n5u06d5.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[来週|らいしゅう]の[休|やす]みは、","after":"です。","tiles":["[山|やま]","へ","[行|い]く","つもり"],"star":2,"bank":[3,0,2,1],"hint":"The place comes first with へ. The dictionary form 行く goes right before つもり.","full":"[来週|らいしゅう]の[休|やす]みは、[山|やま]へ[行|い]く{つもり}です。","explain":"山へ is where, 行く is the dictionary form, and つもりです comes last: \"Next week on my day off, I plan to go to the mountains.\"","unit":6,"day":5,"step":"drill"},"n5u06d5.e1":{"id":"n5u06d5.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あした　何を　しますか。」B「としょかんへ　本を（　　）　行きます。」","options":["かえします","かえさない","かえしに","かえす"],"answer":3,"explain":"B goes to the library to return a book: かえしに行きます, the ます form without ます plus に. かえす行きます and かえします行きます are not Japanese; to say what you go to do, drop ます and add に. かえさない is a \"not\" form and makes no sense with 行きます here.","unit":6,"day":5,"step":"exam"},"n5u06d5.e2":{"id":"n5u06d5.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あしたも　会社に　行きますか。」B「いいえ、あしたは　休みです。会社には（　　）　つもりです。」","options":["行かない","行く","行きません","行って"],"answer":1,"explain":"B says いいえ and tomorrow is a day off, so B plans not to go: 行かないつもりです. 行くつもりです means B plans to go, which does not fit いいえ. 行きません is the polite ending and cannot go before つもり. 行ってつもりです is not Japanese.","unit":6,"day":5,"step":"exam"},"n5u06d5.e3":{"id":"n5u06d5.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「日よう日は　何を　しますか。」B「山へ　","after":"　つもりです。」","tiles":["しゃしん","を","とりに","行く"],"star":2,"bank":[3,1,0,2],"full":"A「日よう日は　何を　しますか。」B「山へ　しゃしんをとりに行く　{つもり}です。」","explain":"しゃしん, を, とりに, 行く. しゃしんを is what B takes, とりに says what B goes to do, and the dictionary form 行く comes right before つもりです.","unit":6,"day":5,"step":"exam"},"n5u06d5.k1":{"id":"n5u06d5.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_来週_の　土よう日は　川へ　行く　つもりです。","options":["せんしゅう","らいしゅう","らいしゅ","こんしゅう"],"answer":2,"explain":"来週 is read らいしゅう, \"next week\". らいしゅ is missing the long う. こんしゅう is 今週 (this week) and せんしゅう is 先週 (last week).","unit":6,"day":5,"step":"scene"},"n5u06d5.r1":{"id":"n5u06d5.r1","kind":"choice","type":"課題理解","q":"男の人は　土よう日　はじめに　どこへ　行きますか。","script":["ナレーター：女の人と男の人が話しています。男の人は、土よう日、はじめにどこへ行きますか。","女：土よう日、いっしょに出かけませんか。","男：いいですね。こうえんへ行きますか。","女：土よう日は、雨ですよ。駅の前のデパートへ、くつを買いに行きませんか。","男：いいですよ。ぼくは、本やへ、本を買いに行くつもりです。","女：じゃあ、デパートの後で、本やへ行きましょう。","男：でも、デパートは十一時からですよ。本やは九時からです。","女：そうですか。じゃあ、はじめに本やへ行きましょう。ひるごはんは、デパートのレストランで食べましょう。","男：はい、そうしましょう。","ナレーター：男の人は、土よう日、はじめにどこへ行きますか。"],"options":["デパート","本や","レストラン","こうえん"],"printed":true,"short":["デパート","本や","レストラン","こうえん"],"answer":2,"why":["They first planned the department store, but it opens at eleven, so they go there after the bookshop.","The bookshop opens at nine and the store at eleven, so the woman says はじめに本やへ行きましょう and he agrees.","They will eat lunch at the restaurant in the department store, later in the day.","The man asks about the park, but the woman says it will rain on Saturday, so they do not go there."],"explain":null,"unit":6,"day":5,"step":"skill","clip":"l_n5u6d5"},"n5u06d6.c1":{"id":"n5u06d6.c1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^ここにペンがたくさんあります^から、ペンはもって（　　）。","options":["[来|き]てはいけません","[来|こ]なくてもいいです","[来|き]てもいいです"],"answer":2,"why":["This says you must not bring a pen. Many pens being here is not a reason to ban yours.","There are many pens here, so you do not need to bring one: もって来なくてもいいです.","This says you may bring a pen. But から gives a reason: there are many pens here already. That is a reason you need not bring one, not a reason you may."],"explain":null,"unit":6,"day":6,"step":"compare"},"n5u06d6.d1":{"id":"n5u06d6.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"テストのとき、^となりの[人|ひと]のこたえ^を（　　）。","options":["[見|み]てもいいです","[見|み]ないでください","[見|み]なくてもいいです","[見|み]てください"],"answer":2,"why":["てもいいです says it is all right to look. In a test, looking at the next person's answers is not all right.","ないでください asks you not to do something: during the test, please don't look at the answers of the person next to you.","なくてもいいです says you do not need to look, as if looking were normally asked of you. The point here is that looking is not allowed.","てください asks you to look at the next person's answers. No test asks that."],"unit":6,"day":6,"step":"drill"},"n5u06d6.d2":{"id":"n5u06d6.d2","kind":"choice","type":"文の文法1","label":"Choose the words","q":"A：お[母|かあ]さんはうちにいますか。B：いいえ。[母|はは]は[今|いま]、[店|みせ]へパンを（　　）^[行|い]って^（　　）。","options":["[買|か]いに／ください","[買|か]う／います","[買|か]いに／います","[買|か]います／います"],"answer":3,"why":["買いに is right, but 行ってください asks the listener to go. B is telling A where Mom is, so it does not fit 母は.","買う cannot join 行って. Before 行きます, use the ます form without ます plus に: 買いに.","買いに行って says she went to buy bread, and います says that is how things are now: she has gone to the shop, so she is not home.","買います cannot join 行って. Take off ます and add に: 買いに."],"unit":6,"day":6,"step":"drill"},"n5u06d6.d3":{"id":"n5u06d6.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは[今|いま]、[中国|ちゅうごく]にすんでいます。^[来年|らいねん]^、[日本|にほん]に（　　）。","options":["すむつもりです","すみました","すみますつもりです","すんでください"],"answer":1,"why":["すむ is the dictionary form, and すむつもりです says what I plan to do next year: live in Japan.","すみました is the past. 来年 means next year, so the sentence needs a plan.","つもり follows the dictionary form, すむ, not the ます form すみます.","てください asks someone else to do something. Here わたし is talking about my own plan."],"explain":null,"unit":6,"day":6,"step":"drill"},"n5u06d6.d4":{"id":"n5u06d6.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[毎日|まいにち]、うちへかえって、てを（　　）^、ごはんを[食|た]べます^。","options":["あらっています","あらって","あらいます","あらってください"],"answer":2,"why":["The sentence goes on after the blank to 食べます, so the verb here takes the te-form, not ています.","The te-form joins actions in order: I go home, wash my hands, and eat. The last verb, 食べます, gives the ending for the whole sentence.","The sentence goes on after the blank to 食べます, so the verb here takes the te-form, not the ます ending.","てください asks someone to wash. This sentence tells what I do every day, and it goes on after the blank."],"explain":null,"unit":6,"day":6,"step":"drill"},"n5u06d6.d5":{"id":"n5u06d6.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"このへやで","after":"[飲|の]んでもいいです。","tiles":["パンを","[食|た]べては","いけませんが","[水|みず]を"],"star":1,"bank":[3,1,0,2],"hint":"Which food goes with 食べては, and which drink goes with 飲んでも at the end?","full":"このへやでパンを{[食|た]べては}いけませんが[水|みず]を[飲|の]んでもいいです。","explain":"パンを goes with 食べては, and 食べては goes with いけません: you must not eat bread. が then turns to what is all right: 水を goes with 飲んでもいいです at the end. \"You must not eat bread in this room, but you may drink water.\"","unit":6,"day":6,"step":"drill"},"n5u06d6.d6":{"id":"n5u06d6.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[先生|せんせい]、ちょっと[外|そと]へ","after":"いいですか。","tiles":["ジュースを","[買|か]いに","[行|い]って","も"],"star":2,"bank":[3,0,2,1],"hint":"What do you go out to do? Which tile joins the te-form to いいですか?","full":"[先生|せんせい]、ちょっと[外|そと]へジュースを[買|か]いに{[行|い]って}もいいですか。","explain":"ジュースを goes with 買いに, and 買いに goes with 行って: go out to buy juice. Then 行って + もいいですか asks for permission. \"Teacher, may I go out for a moment to buy juice?\"","unit":6,"day":6,"step":"drill"},"n5u06d6.e1":{"id":"n5u06d6.e1","kind":"choice","type":"文の文法1","label":"Choose the answer","q":"A「この　へやで　コーヒーを　飲んでも　いいですか。」\nB「すみません、ここでは（　　）。水は　いいですよ。」","options":["飲んで　ください","飲んでは　いけません","飲んでも　いいです","飲まなくても　いいです"],"answer":2,"explain":"B starts with すみません and then says water is all right, so coffee is not allowed: 飲んでは　いけません. 飲まなくても　いいです says A does not need to drink it, which does not answer a request for permission. 飲んで　ください asks A to drink it, and 飲んでも　いいです allows it; neither fits すみません and the contrast with 水は　いいですよ.","unit":6,"day":6,"step":"exam"},"n5u06d6.e2":{"id":"n5u06d6.e2","kind":"choice","type":"文の文法1","label":"Choose the answer","q":"A「この　かみに　名前も　書きますか。」\nB「いいえ、名前は（　　）　いいです。ばんごうだけ　書いて　ください。」","options":["書いては","書かなくても","書きますも","書いても"],"answer":2,"explain":"B says いいえ and asks for only the number, so there is no need to write the name: 書かなくても　いいです. 書いても　いいです would allow the name, which does not go with いいえ and ばんごうだけ. 書いては goes with いけません, not いいです. 書きますも is not Japanese: も follows the te-form.","unit":6,"day":6,"step":"exam"},"n5u06d6.e3":{"id":"n5u06d6.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"今　へやで　いもうとが　","after":"こえで　電話を　しないで　ください。","tiles":["ねて","います","から","大きい"],"star":2,"bank":[2,0,3,1],"full":"今　へやで　いもうとが　ねて　います　{から}　大きい　こえで　電話を　しないで　ください。","explain":"ねて, います, から, 大きい. いもうとが goes with ねて　います: she is sleeping now. から gives that as the reason. 大きい goes right before こえで: please don't talk on the phone in a loud voice.","unit":6,"day":6,"step":"exam"},"n5u06d6.k1":{"id":"n5u06d6.k1","kind":"choice","type":"表記","label":"How the exam asks it","q":"_まいにち_　午後　五時に　学校の　ドアを　しめます。","options":["毎日","母日","毎目","毎月"],"answer":1,"explain":"まいにち, every day, is written 毎日. 母 (mother) looks like 毎 but is a different kanji, and 目 (eye) looks like 日. 毎月 is a real word, but it means every month and is read まいつき.","unit":6,"day":6,"step":"scene"},"n5u06d6.r1":{"id":"n5u06d6.r1","kind":"choice","type":"読解・情報検索","q":"金よう日、としょしつは　何時まで　あいて　いますか。","options":["午前九時","午後三時","午後四時","午後六時"],"short":["9:00 a.m.","3:00 p.m.","4:00 p.m.","6:00 p.m."],"answer":2,"explain":"The line 金よう日　午前九時〜午後三時 gives the Friday hours. The library opens at nine and closes at three in the afternoon.","why":["Nine in the morning is when the library opens, not when it closes.","","Four in the afternoon is when cleaning starts on Wednesdays.","Six in the evening is the closing time from Monday to Thursday, not Friday."],"unit":6,"day":6,"step":"skill"},"n5u06t.1":{"id":"n5u06t.1","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"この　ビルの　_出口_は　あちらです。","options":["でるくち","いりぐち","でくち","でぐち"],"answer":4,"explain":"出口 is でぐち, exit. いりぐち is a real word, but it is 入口 (entrance), not 出口. In 出口 the 口 is ぐち, so でくち is not a word, and でるくち uses the verb でる; it is not a word either.","unit":6,"step":"test"},"n5u06t.2":{"id":"n5u06t.2","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"あしたの　_午後_、友だちと　えいがを　見に　行きます。","options":["ごこ","ごぜん","ごご","ごうご"],"answer":3,"explain":"午後 is ごご, afternoon. ごぜん is a real word, but it is 午前 (morning, a.m.). ごうご has a long ごう, and ごこ has こ without the dakuten; neither is a word.","unit":6,"step":"test"},"n5u06t.3":{"id":"n5u06t.3","kind":"choice","type":"表記","label":"Kanji spelling","q":"つかれましたね。少し　_やすんで_　ください。","options":["木んで","休んで","安んで","本んで"],"answer":2,"explain":"やすんで (rest) is written 休んで, from 休みます. 安 is the やす of 安い (cheap), and it does not write the verb やすむ. 本 (book) and 木 (tree) only look like 休; 本んで and 木んで are not words.","unit":6,"step":"test"},"n5u06t.4":{"id":"n5u06t.4","kind":"choice","type":"表記","label":"Kanji spelling","q":"先生の　話を　よく　_きいて_　ください。","options":["間いて","書いて","耳いて","聞いて"],"answer":4,"explain":"きいて (listen) is 聞いて, from 聞きます. 書いて is a real word, but it is かいて (write). 間 is the かん of 時間 and 耳 means ear; 間いて and 耳いて are not words.","unit":6,"step":"test"},"n5u06t.5":{"id":"n5u06t.5","kind":"choice","type":"文脈規定","label":"Word in context","q":"へやが　くらいですね。でんきを　（　　）　ください。","options":["しめて","けして","あけて","つけて"],"answer":4,"explain":"The room is dark, so you ask someone to turn the light on: でんきを つけて ください. けして (turn off) would make the room darker. You open and close doors and windows with あけて and しめて, not a light.","unit":6,"step":"test"},"n5u06t.6":{"id":"n5u06t.6","kind":"choice","type":"文脈規定","label":"Word in context","q":"A「すみません、トイレは　どこですか。」B「この　ろうかを　まっすぐ　行って、（　　）に　まがって　ください。」","options":["中","前","右","上"],"answer":3,"explain":"まがって means turn, and you turn right or left: 右に まがって (turn right). 前に is the way you are already going (まっすぐ), so it is not a turn. 上に and 中に do not say which way to turn in a hallway.","unit":6,"step":"test"},"n5u06t.7":{"id":"n5u06t.7","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"あしたは　学校が　_休み_です。","options":["あしたは　学校に　行きます。","あしたは　学校が　あさからです。","あしたは　学校で　べんきょうします。","あしたは　学校が　ありません。"],"answer":4,"explain":"学校が 休みです means there is no school that day, the same as 学校が ありません. 学校に 行きます and 学校で べんきょうします say the opposite. 学校が あさからです says when school starts, so there is school.","unit":6,"step":"test"},"n5u06t.8":{"id":"n5u06t.8","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"あの　人は　_わたしの　おばあさん_です。","options":["あの　人は　わたしの　あにの　子どもです。","あの　人は　わたしの　母の　お母さんです。","あの　人は　わたしの　父の　おねえさんです。","あの　人は　わたしの　母の　いもうとです。"],"answer":2,"explain":"おばあさん is your grandmother, and your mother's mother is a grandmother. Your father's older sister and your mother's younger sister are aunts (おばさん). Your older brother's child is a niece or nephew.","unit":6,"step":"test"},"n5u06t.9":{"id":"n5u06t.9","kind":"choice","type":"文の文法1","label":"Choose the form","q":"友だちと　五時まで　こうえんで　（　　）、うちへ　かえりました。","options":["あそって","あそんで","あそいで","あそびて"],"answer":2,"explain":"あそびます (play) is a verb whose ます form ends in び, so its て form is あそんで: あそんで、かえりました (played, then went home). You cannot add て straight to the stem, so あそびて is wrong. あそって and あそいで use the endings of other verbs (like まって and およいで).","unit":6,"step":"test"},"n5u06t.10":{"id":"n5u06t.10","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あぶないですから、この　川で　（　　）　ください。","options":["およがなくて","およいで","およがないで","およぎませんで"],"answer":3,"explain":"The river is dangerous, so this asks people not to swim: およがないで ください. およいで ください asks them to swim, the opposite of what あぶないですから needs. The polite ません form does not go before で ください, and およがなくて ください is not a request.","unit":6,"step":"test"},"n5u06t.11":{"id":"n5u06t.11","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　えんぴつで　（　　）　いいですか。」B「いいえ、ペンで　書いて　ください。」","options":["書きても","書いては","書くも","書いても"],"answer":4,"explain":"A asks for permission, which is the て form + も いいですか: 書いても いいですか (may I write?). 書きて is not the て form of 書きます. 書いては goes with いけません, not いいですか. 書く (the dictionary form) does not go before も here.","unit":6,"step":"test"},"n5u06t.12":{"id":"n5u06t.12","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あしたは　休みですから、はやく　（　　）　いいです。ゆっくり　ねて　ください。","options":["おきなくても","おきても","おきては","おきないくても"],"answer":1,"explain":"It is a holiday and the speaker says to sleep in, so you don't have to get up early: おきなくても いいです. おきても いいです (you may get up early) does not fit ゆっくり ねて ください. おきては goes with いけません, not いいです. おきないくても keeps the い of ない, which must be dropped (おきなくても).","unit":6,"step":"test"},"n5u06t.13":{"id":"n5u06t.13","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　しんぶんを　うちへ　もって　かえっても　いいですか。」B「いいえ、みんなの　しんぶんですから、（　　）。」","options":["もって　かえっては　いけません","もって　かえらなくても　いいです","もって　かえっても　いいです","もって　かえって　ください"],"answer":1,"explain":"B says いいえ to a request for permission and gives a reason (it is everyone's newspaper), so B says you must not take it home: もって かえっては いけません. もって かえっても いいです and もって かえって ください would mean yes, not いいえ. もって かえらなくても いいです (you don't have to take it) does not answer \"may I take it?\".","unit":6,"step":"test"},"n5u06t.14":{"id":"n5u06t.14","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「もしもし、今　何を　して　いますか。」B「駅の　前で　友だちを　（　　）。」","options":["まって　ください","まちます","まって　います","まちました"],"answer":3,"explain":"A asks what B is doing right now (今 何を して いますか), so B answers with the て form + います: まって います (I am waiting). まちます is for habits or plans, not this moment. まちました is finished, and まって ください asks A to wait, which does not answer the question.","unit":6,"step":"test"},"n5u06t.15":{"id":"n5u06t.15","kind":"choice","type":"文の文法1","label":"Choose the form","q":"日よう日、こうえんへ　花を　（　　）　行きました。","options":["見に","見へ","見るに","見ますに"],"answer":1,"explain":"To say why you go somewhere, use the ます form without ます + に: 見に 行きました (went to see). The purpose takes に, not へ, so 見へ is wrong. The dictionary form (見る) and the full ます form (見ます) do not go before に 行きます.","unit":6,"step":"test"},"n5u06t.16":{"id":"n5u06t.16","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「どうやって　駅へ　行きますか。」B「この　みちを　","after":"　右に　まがって　ください。」","tiles":["まっすぐ","行って","二つめの","かどを"],"star":1,"bank":[2,0,3,1],"full":"A「どうやって　駅へ　行きますか。」B「この　みちを　まっすぐ　{行って}　二つめの　かどを　右に　まがって　ください。」","explain":"まっすぐ, 行って, 二つめの, かどを. まっすぐ goes right before the verb it describes: まっすぐ 行って (go straight, and then). 二つめの joins the noun after it: 二つめの かどを (the second corner), and かどを comes just before 右に まがって. 行って cannot come after かどを, because then まがって has no corner to turn at.","unit":6,"step":"test"},"n5u06t.17":{"id":"n5u06t.17","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あそこで　","after":"が　わたしの　あにです。","tiles":["ギターを","ひいて","いる","人"],"star":1,"bank":[1,3,0,2],"full":"あそこで　ギターを　{ひいて}　いる　人が　わたしの　あにです。","explain":"ギターを, ひいて, いる, 人. ギターを needs its verb after it: ギターを ひいて (playing the guitar). いる follows the て form to say it is happening now, and the whole part describes 人: ひいて いる 人 (the person who is playing). 人 must come last, right before が.","unit":6,"step":"test"},"n5u06t.18":{"id":"n5u06t.18","kind":"star","type":"文の文法2","label":"Build the sentence","before":"来年　とうきょうへ　","after":"　行く　つもりです。","tiles":["日本語","を","べんきょうし","に"],"star":2,"bank":[3,2,0,1],"full":"来年　とうきょうへ　日本語を　{べんきょうし}に　行く　つもりです。","explain":"日本語, を, べんきょうし, に. を marks what you study, so it goes right after 日本語: 日本語を べんきょうし. The purpose of going takes the ます form without ます + に: べんきょうしに 行く. に cannot go after 日本語, because then べんきょうし has nothing to join 行く.","unit":6,"step":"test"},"n5u06t.19":{"id":"n5u06t.19","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"みなさんへ\nあしたは　みんなで　山へ　行きます。あさ　八時に　学校の　前に　来て　ください。おべんとうと　飲みものを　もって　来て　ください。おかしは　もって　来ても　いいです。でも、ゲームは　もって　来ては　いけません。あしたは　いい　天気ですから、かさは　もって　来なくても　いいです。\n先生","q":"もって　来ては　いけない　ものは　どれですか。","options":["おかし","かさ","ゲーム","おべんとう"],"answer":3,"short":["おかし","かさ","ゲーム","おべんとう"],"explain":"The note says ゲームは もって 来ては いけません: games must not be brought. おかし is allowed (もって 来ても いいです). かさ is just not needed (もって 来なくても いいです), which is different from not allowed. おべんとう must be brought (もって 来て ください).","unit":6,"step":"test"},"n5u06t.20":{"id":"n5u06t.20","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"みなさんへ\nあしたは　みんなで　山へ　行きます。あさ　八時に　学校の　前に　来て　ください。おべんとうと　飲みものを　もって　来て　ください。おかしは　もって　来ても　いいです。でも、ゲームは　もって　来ては　いけません。あしたは　いい　天気ですから、かさは　もって　来なくても　いいです。\n先生","q":"ただしい　ものは　どれですか。","options":["おかしは　もって　来ても　いいです。","かさは　もって　来て　ください。","飲みものは　もって　来ないで　ください。","おべんとうは　もって　来なくても　いいです。"],"answer":1,"short":["おかしはいい","かさをもってくる","飲みものはだめ","おべんとうはいらない"],"explain":"The note says おかしは もって 来ても いいです, so snacks are allowed. おべんとう and 飲みもの must be brought (もって 来て ください), so the options about 飲みもの and おべんとう say the opposite. かさ does not have to be brought because the weather will be good, so 来て ください is wrong.","unit":6,"step":"test"},"n5u06t.21":{"id":"n5u06t.21","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"さくらとしょかん\n火よう日〜日よう日　午前　九時〜午後　七時\n（月よう日は　休み）\n＊本は　一人　五さつまで　かりても　いいです。\n＊としょかんの　中で　飲みものを　飲まないで　ください。\n＊としょかんの　中で　電話を　かけては　いけません。","q":"ヤンさんは　としょかんで　何を　しても　いいですか。","options":["本を　読みながら　ジュースを　飲みます。","中で　友だちに　電話を　かけます。","本を　四さつ　かります。","月よう日に　本を　かります。"],"answer":3,"short":["ジュース","電話","四さつ","月よう日"],"explain":"One person may borrow up to five books (五さつまで), so four books is all right. Drinking inside is not allowed (飲まないで ください), and phone calls are not allowed (かけては いけません). The library is closed on 月よう日 (休み).","unit":6,"step":"test"},"n5u06t.22":{"id":"n5u06t.22","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"さくらとしょかん\n火よう日〜日よう日　午前　九時〜午後　七時\n（月よう日は　休み）\n＊本は　一人　五さつまで　かりても　いいです。\n＊としょかんの　中で　飲みものを　飲まないで　ください。\n＊としょかんの　中で　電話を　かけては　いけません。","q":"リーさんは　本を　かりに　行きたいです。いつ　行きますか。","options":["月よう日の　午後　三時","水よう日の　午前　八時","金よう日の　午後　八時","土よう日の　午前　十一時"],"answer":4,"short":["月・三時","水・八時","金・八時","土・十一時"],"explain":"On 土よう日 the library is open from 午前 九時 to 午後 七時, so 午前 十一時 is fine. 月よう日 is the library's day off. 午前 八時 is before it opens at nine, and 午後 八時 is after it closes at seven.","unit":6,"step":"test"},"n5u06t.23":{"id":"n5u06t.23","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"リサさんへ\n今、わたしは　かぞくと　こうえんに　います。わたしは　木の　下で　この　メールを　書いて　います。いもうとは　いぬと　あそんで　います。父と　母は　店で　おべんとうを　買って　います。午後は　みんなで　川へ　魚を　見に　行く　つもりです。\nマリ","q":"いもうとは　今　何を　して　いますか。","options":["おべんとうを　買って　います。","川で　魚を　見て　います。","メールを　書いて　います。","いぬと　あそんで　います。"],"answer":4,"short":["おべんとう","魚","メール","いぬ"],"explain":"The email says いもうとは いぬと あそんで います: the sister is playing with the dog. マリ, the writer, is writing the email. The parents are buying lunch boxes. Seeing the fish at the river is the plan for the afternoon, not what anyone is doing now.","unit":6,"step":"test"},"n5u06t.24":{"id":"n5u06t.24","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"リサさんへ\n今、わたしは　かぞくと　こうえんに　います。わたしは　木の　下で　この　メールを　書いて　います。いもうとは　いぬと　あそんで　います。父と　母は　店で　おべんとうを　買って　います。午後は　みんなで　川へ　魚を　見に　行く　つもりです。\nマリ","q":"マリさんたちは　午後　何を　しますか。","options":["うちで　メールを　書きます。","川へ　魚を　見に　行きます。","こうえんで　いぬと　あそびます。","店で　おべんとうを　買います。"],"answer":2,"short":["メール","川で魚","いぬ","おべんとう"],"explain":"The email says 午後は みんなで 川へ 魚を 見に 行く つもりです: in the afternoon they plan to go to the river to see fish. Buying lunch boxes, writing the email and playing with the dog are what the family is doing now, in the park, not the afternoon plan.","unit":6,"step":"test"},"n5u07d1.c1":{"id":"n5u07d1.c1","kind":"choice","type":"文の文法1","label":"先生に","q":"[先生|せんせい]、あしたも[学校|がっこう]に（　　）か。","options":["[来|き]ます","[来|く]る","[来|こ]ない"],"answer":1,"why":["You speak to a teacher politely, so use the ます form: 来ますか.","来る is the plain form, for friends. 来るか to a teacher sounds rough.","来ないか is a rough, casual invitation, and it asks the wrong thing. You are asking if the teacher comes."],"explain":null,"unit":7,"day":1,"step":"compare"},"n5u07d1.d1":{"id":"n5u07d1.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：[今|いま]から[何|なに]を^する^？B：[本|ほん]を（　　）よ。","options":["[読|よ]みる","[読|よ]る","[読|よ]む","[読|よ]く"],"answer":3,"why":["読みます is a う-verb. Do not keep み and add る; み changes to む.","Only the sound before ます changes, and み becomes む, not る.","A asks in the plain form, so B answers in it too. 読みます has み before ます, so the dictionary form is 読む.","く is for verbs with き before ます, like 書きます → 書く."],"explain":null,"unit":7,"day":1,"step":"drill"},"n5u07d1.d2":{"id":"n5u07d1.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：あした、テニス（　　）？B：^うん、いいね^！","options":["する","しく","しる","すく"],"answer":1,"why":["します is special: its dictionary form is する. A plain question between friends: テニス、する？","しく is not a form of します.","し comes from します, but the dictionary form of します is する. しる is a different verb (to know).","く is for verbs with き before ます, like 書きます → 書く. します is special."],"explain":null,"unit":7,"day":1,"step":"drill"},"n5u07d1.d3":{"id":"n5u07d1.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[今日|きょう]は[店|みせ]で^[何|なに]も^（　　）。","options":["[買|か]わない","[買|か]あない","[買|か]いない","[買|か]らない"],"answer":1,"why":["何も needs a negative verb. 買う ends in う, which becomes わ: 買わない.","The last sound moves to the あ-row, but う is special: it becomes わ, not あ.","い is the sound in 買います. ない does not go after the ます-form sound.","ら is for う-verbs that end in る, like 入る → 入らない. 買う ends in う."],"explain":null,"unit":7,"day":1,"step":"drill"},"n5u07d1.d4":{"id":"n5u07d1.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：[山川|やまかわ]さんも[来|く]る？B：^ううん^、[山川|やまかわ]さんは（　　）よ。","options":["くない","こらない","こない","きない"],"answer":3,"why":["く stays only in くる. Before ない it changes to こ.","来る is not a う-verb, so there is no ら. It is just こ + ない.","ううん means no, so B needs the ない form. 来る is special: its ない form is こない.","き is the sound in 来ます. The ない form uses こ instead."],"explain":null,"unit":7,"day":1,"step":"drill"},"n5u07d1.d5":{"id":"n5u07d1.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あしたは","after":"よ。","tiles":["[七時|しちじ]に","おきて","[学校|がっこう]へ","[行|い]く"],"star":3,"bank":[2,0,3,1],"hint":"First the time, then getting up in the て form. The dictionary form 行く ends the casual sentence, right before よ.","full":"あしたは[七時|しちじ]におきて[学校|がっこう]へ[行|い]{く}よ。","explain":"七時に says when you get up, so it comes right before おきて. 学校へ goes with 行く, and 行く, the plain form, ends the sentence before よ.","unit":7,"day":1,"step":"drill"},"n5u07d1.d6":{"id":"n5u07d1.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[日|にち]よう[日|び]は","after":"よ。","tiles":["うちに","いて","どこへも","[行|い]かない"],"star":2,"bank":[3,1,0,2],"hint":"どこへも needs a negative verb right after it. うちに goes with いて.","full":"[日|にち]よう[日|び]はうちにいてどこへも[行|い]か{ない}よ。","explain":"うちにいて (I stay at home) is the first part, in the て form. どこへも goes with a negative, so it sits right before 行かない, which ends the sentence before よ.","unit":7,"day":1,"step":"drill"},"n5u07d1.e1":{"id":"n5u07d1.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あした　何を　する？」　B「友だちと　山へ　（　　）よ。」","options":["行む","行きる","行る","行く"],"answer":4,"explain":"行きます has き before ます, so the dictionary form is 行く: I'm going to the mountains with a friend. 行る and 行む change き to the wrong sound, and 行きる keeps き, which a う-verb never does.","unit":7,"day":1,"step":"exam"},"n5u07d1.e2":{"id":"n5u07d1.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　ケーキ、食べる？」　B「ううん、今は　（　　）。」","options":["食べらない","食べるない","食べない","食べかない"],"answer":3,"explain":"食べる is a る-verb: drop る and add ない, so 食べない, not now. 食べらない and 食べかない treat it like a う-verb, and 食べるない keeps る.","unit":7,"day":1,"step":"exam"},"n5u07d1.e3":{"id":"n5u07d1.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あした　友だちと　","after":"よ。","tiles":["えいがを","見て","ばんごはんを","食べる"],"star":1,"bank":[2,3,0,1],"full":"あした　友だちと　えいがを　{見て}　ばんごはんを　食べるよ。","explain":"えいがを, 見て, ばんごはんを, 食べる. えいがを goes with 見て, the first action. ばんごはんを 食べる is the second action, and the dictionary form ends the sentence before よ.","unit":7,"day":1,"step":"exam"},"n5u07d1.k1":{"id":"n5u07d1.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_後で_　電話するね。","options":["ごで","まえで","うしろで","あとで"],"answer":4,"explain":"後で is read あとで, later: I'll call you later. うしろ (behind) is written 後ろ, with ろ. ご is the reading in 午後, but ごで is not a word. まえ is 前.","unit":7,"day":1,"step":"scene"},"n5u07d1.r1":{"id":"n5u07d1.r1","kind":"choice","type":"即時応答","q":"男：あした、うちに　来る？","script":["男：あした、うちに　来る？","ナレーター：1","女：うん、来ない。","ナレーター：2","女：うん、行く。","ナレーター：3","女：ううん、行く。"],"options":["うん、来ない。","うん、行く。","ううん、行く。"],"printed":false,"short":["うん、来ない","うん、行く","ううん、行く"],"answer":2,"why":["うん means yes, but 来ない means she won't come. The two halves do not match.","A plain question gets a plain answer. When you go to the other person's place, you say 行く, not 来る.","ううん means no, but 行く says she will go. The two halves do not match."],"unit":7,"day":1,"step":"skill","clip":"l_n5u7d1"},"n5u07d2.c1":{"id":"n5u07d2.c1","kind":"choice","type":"文の文法1","label":"あさごはんの話","q":"A：けさ、[何|なに]を（　　）か。B：パンを[食|た]べました。","options":["[食|た]べました","[食|た]べたことがあります","[食|た]べます"],"answer":1,"why":["けさ is one time today, so A uses the polite past, and B answers the same way.","たことがあります asks about experience in your life. It does not go with けさ, this morning.","食べます is for now or later, but けさ is already past, and B answers with 食べました."],"unit":7,"day":2,"step":"compare"},"n5u07d2.d1":{"id":"n5u07d2.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^きのう^は^どこにも^（　　）。","options":["[行|い]きなかった","[行|い]かなかった","[行|い]った","[行|い]かない"],"answer":2,"why":["The ない-form of 行く is 行かない, so the past is 行かなかった. 行きなかった is not a word.","どこにも needs a \"not\" form, and きのう needs the past: 行かなかった.","どこにも goes with a \"not\" form. どこにも行った is not said.","行かない is for now or later, but きのう is yesterday."],"explain":null,"unit":7,"day":2,"step":"drill"},"n5u07d2.d2":{"id":"n5u07d2.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^きのう^、[友|とも]だちがうちに（　　）。","options":["くる","きた","こた","くった"],"answer":2,"why":["くる is for now or later, but きのう is yesterday.","The た-form of 来る is 来た, read きた.","こ is used in 来ない, not before た.","くった is not a form of 来る."],"explain":null,"unit":7,"day":2,"step":"drill"},"n5u07d2.d3":{"id":"n5u07d2.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは^まだ^[外国|がいこく]に[行|い]った（　　）。","options":["ことをします","ことがありません","ことがあります","ことでした"],"answer":2,"why":["The experience pattern is ことがある, not ことをする.","まだ … ことがありません: I have not been abroad yet.","まだ here needs a \"not\" ending. まだ行ったことがあります is not said.","ことでした does not follow the た-form to talk about experience."],"explain":null,"unit":7,"day":2,"step":"drill"},"n5u07d2.d4":{"id":"n5u07d2.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：[日本|にほん]のおかしを（　　）^ことがありますか^。B：はい、あります。","options":["[食|た]べた","[食|た]べます","[食|た]べて","[食|た]べました"],"answer":1,"why":["ことがありますか follows the た-form: 食べたことがありますか, \"have you ever eaten…?\".","The polite ます form does not go before こと.","The て-form does not go before こと.","The polite ました form does not go before こと. Use the plain 食べた."],"unit":7,"day":2,"step":"drill"},"n5u07d2.d5":{"id":"n5u07d2.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしは","after":"。","tiles":["[大|おお]きい","[山|やま]に","のぼった","ことがありません"],"star":2,"bank":[2,0,3,1],"hint":"大きい describes a noun. Which verb form comes right before こと?","full":"わたしは[大|おお]きい[山|やま]にのぼった{ことがありません}。","explain":"大きい describes 山, so 大きい山に goes together. The た-form のぼった comes before ことがありません, which ends the sentence.","unit":7,"day":2,"step":"drill"},"n5u07d2.d6":{"id":"n5u07d2.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"きのうは","after":"。","tiles":["[本|ほん]を","[読|よ]んで","テレビは","[見|み]なかった"],"star":1,"bank":[2,3,1,0],"hint":"You read a book and watch TV. Which form can end the sentence?","full":"きのうは[本|ほん]を[読|よ]んでテレビは[見|み]{なかった}。","explain":"本を goes with 読んで, and the て-form links to the next part. テレビは goes with 見なかった, the past negative, which ends the sentence.","unit":7,"day":2,"step":"drill"},"n5u07d2.e1":{"id":"n5u07d2.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「きのう　何を　した？」\nB「うちで　べんきょうを　（　　）。」","options":["しった","する","した","して"],"answer":3,"explain":"A asks about yesterday in plain style, so B answers with the plain past of する: した. して asks someone to do it, しった is not a form of する, and する is for now or later.","unit":7,"day":2,"step":"exam"},"n5u07d2.e2":{"id":"n5u07d2.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　まちの　古い　おてらを　見た　（　　）　ありますか。」\nB「いいえ、まだ　ありません。」","options":["ことに","ことで","ことが","ことを"],"answer":3,"explain":"Experience is た-form + ことが　あります. ことを, ことに and ことで cannot go before あります here.","unit":7,"day":2,"step":"exam"},"n5u07d2.e3":{"id":"n5u07d2.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしは　","after":"　ありません。","tiles":["外国の","川で","およいだ","ことが"],"star":2,"bank":[3,2,0,1],"full":"わたしは　外国の　川で　{およいだ}　ことが　ありません。","explain":"外国の, 川で, およいだ, ことが. 外国の must sit right before 川, and the た-form およいだ comes before ことが　ありません.","unit":7,"day":2,"step":"exam"},"n5u07d2.k1":{"id":"n5u07d2.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"あしたの　_天気_は　どうですか。","options":["てんき","てんけ","でんき","てんぎ"],"answer":1,"explain":"天気 is read てんき, \"weather\". でんき is 電気, \"electricity\", and てんけ and てんぎ are not words.","unit":7,"day":2,"step":"scene"},"n5u07d2.r1":{"id":"n5u07d2.r1","kind":"choice","type":"読解・内容理解（短文）","q":"ケンさんが　まだ　した　ことが　ない　ことは　どれですか。","options":["大きい　山に　のぼる　こと","川の　魚を　食べる　こと","北の　まちへ　行く　こと","古い　おてらを　見る　こと"],"short":["大きい山にのぼる","川の魚を食べる","北のまちへ行く","古いおてらを見る"],"answer":2,"explain":"Ken writes 川の魚はまだ食べたことがありません: he has not eaten the river fish yet. He will eat it tonight.","why":["He will climb tomorrow, but he climbed it three years ago too (三年前にものぼったことがあります).","","He is in the northern town now (いま北のまちにいます).","He saw the old temple yesterday (きのうは古いおてらを見ました)."],"unit":7,"day":2,"step":"skill"},"n5u07d3.c1":{"id":"n5u07d3.c1","kind":"choice","type":"文の文法1","label":"ピクニック","q":"[天気|てんき]がいいです（　　）、[外|そと]で[食|た]べましょう。","options":["でも","から","が"],"answer":2,"why":["でも starts a new sentence (いいです。でも、…). It cannot come right after いいです inside one sentence, and \"but\" does not fit the meaning either.","The good weather is the reason for eating outside: \"The weather is nice, so let's eat outside.\"","が means \"but\". Nice weather and eating outside do not go against each other."],"explain":null,"unit":7,"day":3,"step":"compare"},"n5u07d3.d1":{"id":"n5u07d3.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^ねつがありました^（　　）、[学校|がっこう]を[休|やす]みました。","options":["でも","も","が","から"],"answer":4,"why":["でも starts a new sentence (ありました。でも、…). It cannot follow ありました inside one sentence.","も means \"too\" and goes after a noun. It cannot join two sentences.","が means \"but\". Having a fever is not something that goes against staying home.","The fever is the reason: \"I had a fever, so I stayed home from school.\""],"explain":null,"unit":7,"day":3,"step":"drill"},"n5u07d3.d2":{"id":"n5u07d3.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[今日|きょう]は^[日|にち]よう[日|び]^（　　）、[学校|がっこう]は[休|やす]みです。","options":["いから","ですが","だから","から"],"answer":3,"why":["いから is not a form. い belongs to い adjectives such as ねむい, and 日よう日 is a noun.","ですが means \"but\". Sunday and school being closed do not go against each other.","Noun + だから gives the reason: \"Today is Sunday, so there is no school.\"","日よう日 is a noun, so it needs だ or です before から. 日よう日から means \"from Sunday\"."],"explain":null,"unit":7,"day":3,"step":"drill"},"n5u07d3.d3":{"id":"n5u07d3.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"このアパートはひろいです（　　）、^[古|ふる]いです^。","options":["を","が","でも","から"],"answer":2,"why":["を marks the thing you do something to. It cannot join two sentences.","Big is good and old is not, so が (but) joins them: \"This flat is big, but it's old.\"","でも starts a new sentence (ひろいです。でも、…). It cannot follow ひろいです inside one sentence.","から gives a reason, but being big is not the reason the flat is old."],"explain":null,"unit":7,"day":3,"step":"drill"},"n5u07d3.d4":{"id":"n5u07d3.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[毎日|まいにち][電車|でんしゃ]で[会社|かいしゃ]へ[行|い]きます（　　）、^[今日|きょう]はバスで[行|い]きました^。","options":["から","が","でも","まで"],"answer":2,"why":["から gives a reason, but going by train every day is not the reason for taking the bus today.","Every day it is the train, but today it was the bus: \"I go to work by train every day, but today I went by bus.\"","でも starts a new sentence (行きます。でも、…). It cannot follow 行きます inside one sentence.","まで means \"until\" or \"as far as\". 行きますまで is not correct."],"explain":null,"unit":7,"day":3,"step":"drill"},"n5u07d3.d5":{"id":"n5u07d3.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"おなかが","after":"ません。","tiles":["いたいです","から","[何|なに]も","[食|た]べ"],"star":1,"bank":[2,0,3,1],"hint":"おなかが goes with いたいです, and から comes right after the reason. 何も goes before the verb with ません.","full":"おなかがいたいです{から}[何|なに]も[食|た]べません。","explain":"いたいです, から, 何も, 食べ. The stomachache is the reason, so から follows いたいです: \"My stomach hurts, so I won't eat anything.\"","unit":7,"day":3,"step":"drill"},"n5u07d3.d6":{"id":"n5u07d3.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"この[店|みせ]は","after":"ありません。","tiles":["ひろい","ですが、","あまり","きれいじゃ"],"star":3,"bank":[3,1,0,2],"hint":"ひろい goes with ですが、. あまり needs a negative, so it goes before きれいじゃ ありません.","full":"この[店|みせ]はひろい{ですが}、あまりきれいじゃありません。","explain":"ひろい, ですが、, あまり, きれいじゃ. ですが joins the good point and the bad point, and あまり goes with the negative: \"This shop is big, but it's not very clean.\"","unit":7,"day":3,"step":"drill"},"n5u07d3.e1":{"id":"n5u07d3.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"今日は　雨（　　）、　テニスは　しません。","options":["まで","が","から","だから"],"answer":4,"explain":"雨 is a noun, so it needs だ before から: 雨だから, \"because it's raining\". 雨から means \"from the rain\", and 雨まで means \"until the rain\". 雨が needs a verb after it, such as ふります.","unit":7,"day":3,"step":"exam"},"n5u07d3.e2":{"id":"n5u07d3.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしの　へやは　せまいです（　　）、　まどが　大きくて　あかるいです。","options":["が","と","から","も"],"answer":1,"explain":"The room is small (bad), but the window is big and bright (good), so が, \"but\", joins them. から would make the small room the reason for the big window. も and と cannot join two sentences here.","unit":7,"day":3,"step":"exam"},"n5u07d3.e3":{"id":"n5u07d3.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あしたは　テストが","after":"します。","tiles":["あります","から","今日は","べんきょう"],"star":1,"bank":[2,3,1,0],"full":"あしたは　テストが　あります　{から}　今日は　べんきょう　します。","explain":"あります, から, 今日は, べんきょう. テストが あります is the reason, so から follows it, and 今日は べんきょう します is the result: \"I have a test tomorrow, so I'll study today.\"","unit":7,"day":3,"step":"exam"},"n5u07d3.k1":{"id":"n5u07d3.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"雨ですから、　店は　午後　_四時_に　しまります。","options":["しじ","よっじ","よんじ","よじ"],"answer":4,"explain":"四時, \"four o'clock\", is read よじ. 四 is often よん (四百, よんひゃく), but before 時 it is よ. しじ is not used for the time, and よっじ is not a word.","unit":7,"day":3,"step":"scene"},"n5u07d3.r1":{"id":"n5u07d3.r1","kind":"choice","type":"ポイント理解","q":"女の人は　どうして　土よう日に　えいがに　行きませんか。","script":["ナレーター：男の人と女の人が話しています。女の人はどうして土よう日にえいがに行きませんか。","男：山下さん、土よう日にいっしょにえいがを見ませんか。","女：すみません。土よう日はちょっと…。","男：しごとですか。","女：いいえ、しごとは休みですが、母が国から来ます。いっしょにごはんを食べます。","男：そうですか。じゃあ、日よう日はどうですか。","女：日よう日はいいですよ。えいがはだいすきですから。","男：じゃ、日よう日に行きましょう。","ナレーター：女の人はどうして土よう日にえいがに行きませんか。"],"options":["かぜを　ひいたから","お母さんが　来るから","えいがが　すきじゃないから","しごとが　あるから"],"printed":true,"short":["かぜ","お母さんが 来る","えいがが すきじゃない","しごと"],"answer":2,"why":["Nobody talks about a cold.","しごとは休みですが、母が国から来ます: her mother is coming, and they will eat together.","She says えいがはだいすきですから, and she agrees to go on Sunday.","The man guesses work, but she says いいえ、しごとは休みです."],"explain":null,"unit":7,"day":3,"step":"skill","clip":"l_n5u7d3"},"n5u07d4.c1":{"id":"n5u07d4.c1","kind":"choice","type":"文の文法1","label":"あしたのてんき","q":"「あしたは[雨|あめ]ですか。」「たぶん[雨|あめ]^だ^（　　）。」","options":["とおもいます","です","でしょう"],"answer":1,"why":["A noun takes だ before とおもいます: 雨だとおもいます.","です comes right after 雨, without だ.","でしょう comes right after 雨, without だ: 雨でしょう."],"explain":null,"unit":7,"day":4,"step":"compare"},"n5u07d4.d1":{"id":"n5u07d4.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^あした^の[午前|ごぜん]は[雨|あめ]が（　　）。","options":["ふったでしょう","ふってでしょう","ふるでしょう","ふりますでしょう"],"answer":3,"why":["ふった is past, but あした is tomorrow.","The て form does not go before でしょう.","The plain form ふる + でしょう: a guess about tomorrow.","The polite ます form does not go before でしょう."],"explain":null,"unit":7,"day":4,"step":"drill"},"n5u07d4.d2":{"id":"n5u07d4.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"「この[本|ほん]、おもしろい（　　）？」「^ええ、とても^おもしろいです。」","options":["でしょう","ですでしょう","だでしょう","なでしょう"],"answer":1,"why":["おもしろい + でしょう with the voice going up: \"It's interesting, right?\"","でしょう takes the place of です. You cannot use both.","だ does not go before でしょう.","おもしろい is an い-adjective, so it never takes な."],"unit":7,"day":4,"step":"drill"},"n5u07d4.d3":{"id":"n5u07d4.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[山川|やまかわ]さんはかぜですから、^あした^は（　　）とおもいます。","options":["[来|こ]ない","[来|き]ません","[来|こ]なくて","[来|こ]なかった"],"answer":1,"why":["The plain form 来ない goes before とおもいます.","来ません is the polite form. Before と, use the plain form.","The て form cannot end the thought before と.","来なかった is past, but あした is tomorrow."],"unit":7,"day":4,"step":"drill"},"n5u07d4.d4":{"id":"n5u07d4.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あの[人|ひと]はリンさんのお[父|とう]さん（　　）^とおもいます^。","options":["です","の","だ","な"],"answer":3,"why":["です is polite. Before と, use the plain だ.","お父さんの needs a noun after it, and とおもいます is not one.","お父さん is a noun, so it takes だ before とおもいます.","な does not come after a noun at the end of a thought."],"explain":null,"unit":7,"day":4,"step":"drill"},"n5u07d4.d5":{"id":"n5u07d4.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あしたは","after":"。","tiles":["[雨|あめ]が","ふって、","さむい","でしょう"],"star":1,"bank":[2,0,3,1],"hint":"What happens first, then what is it like? でしょう comes last.","full":"あしたは[雨|あめ]がふって、さむい{でしょう}。","explain":"雨が goes with ふって, and the comma joins it to the next part. さむい is the plain form, so でしょう comes right after it.","unit":7,"day":4,"step":"drill"},"n5u07d4.d6":{"id":"n5u07d4.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あ、","after":"おもいます。","tiles":["この","かさは","[山川|やまかわ]さんの","だと"],"star":2,"bank":[3,1,0,2],"hint":"この points at the umbrella. Whose is it? だと comes right before おもいます.","full":"あ、このかさは[山川|やまかわ]さんのだ{とおもいます}。","explain":"この goes right before かさは. 山川さんの means \"Mr. Yamakawa's\", and it takes だ before とおもいます, like a noun.","unit":7,"day":4,"step":"drill"},"n5u07d4.e1":{"id":"n5u07d4.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"「リンさんは　どこですか。」「さあ。でも、もう　うちへ　（　　）と　おもいます。」","options":["かえり","かえった","かえりました","かえって"],"answer":2,"explain":"もう says it has already happened, so the plain past かえった goes before と おもいます. かえりました is polite and cannot go before と, and かえって and かえり cannot end the thought.","unit":7,"day":4,"step":"exam"},"n5u07d4.e2":{"id":"n5u07d4.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あしたは　東の　ほうは　はれですが、西の　ほうは　雨（　　）。","options":["ですでしょう","だと","でしょう","だでしょう"],"answer":3,"explain":"A noun takes でしょう directly: 雨でしょう, a guess about tomorrow. でしょう never comes after だ or です, and 雨だと cannot end the sentence.","unit":7,"day":4,"step":"exam"},"n5u07d4.e3":{"id":"n5u07d4.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あの　店の","after":"おもいます。","tiles":["ケーキは","やすくて","おいしい","と"],"star":2,"bank":[2,3,0,1],"full":"あの　店の　ケーキは　やすくて　{おいしい}と　おもいます。","explain":"ケーキは, やすくて, おいしい, と. 店の describes ケーキ. やすくて joins on to おいしい, and the plain form おいしい goes before と おもいます.","unit":7,"day":4,"step":"exam"},"n5u07d4.k1":{"id":"n5u07d4.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"あしたの　_午後_は　雨でしょう。","options":["ごご","ごぜん","ごうご","ごごう"],"answer":1,"explain":"午後 is ごご, the afternoon. ごぜん is 午前, the morning. ごうご and ごごう are not words.","unit":7,"day":4,"step":"scene"},"n5u07d4.r1":{"id":"n5u07d4.r1","kind":"choice","type":"読解・内容理解（短文）","q":"この　人は　どうして　セーターを　もって　行きますか。","options":["あしたは　雨が　ふるから。","山の　上は　さむいと　おもうから。","友だちが　さむいと　言ったから。","今日は　雨で　さむかったから。"],"short":["あしたは雨がふる","山の上はさむいとおもう","友だちが言った","今日さむかった"],"answer":2,"explain":"The writer thinks it will be cold on the mountain (さむいと おもいます), and だから says that is why she takes a sweater.","why":["The forecast says it will be sunny tomorrow (はれるでしょう).","","The writer thinks this herself. The friend says nothing.","Today it rained, but the passage does not say it was cold, and the sweater is for the mountain."],"unit":7,"day":4,"step":"skill"},"n5u07d5.c1":{"id":"n5u07d5.c1","kind":"choice","type":"文の文法1","label":"テスト","q":"^あしたはテストです^から、[今日|きょう]はべんきょうし（　　）。","options":["なくてもいいです","なければなりません","ないほうがいいです"],"answer":2,"why":["しなくてもいいです means \"you don't have to study\". With a test tomorrow, that does not make sense.","There is a test tomorrow, so you must study today: べんきょうしなければなりません.","しないほうがいいです is advice not to study. Before a test, that is the wrong advice."],"unit":7,"day":5,"step":"compare"},"n5u07d5.d1":{"id":"n5u07d5.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^かぜ^ですね。[今日|きょう]はおふろに（　　）ほうがいいですよ。","options":["[入|はい]りません","[入|はい]らない","[入|はい]って","[入|はい]らなくて"],"answer":2,"why":["入りません is the polite ending. Before ほうがいいです, use the plain form: 入らない.","You have a cold, so the advice is not to take a bath. ない form + ほうがいいです means \"you had better not\".","入って is the te-form. 入ってほうがいい is not Japanese.","入らなくて is the te-form of 入らない. It does not go before ほうがいいです."],"unit":7,"day":5,"step":"drill"},"n5u07d5.d2":{"id":"n5u07d5.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"のどがいたいですね。このくすりを（　　）^ほうがいいです^よ。","options":["[飲|の]んで","[飲|の]み","[飲|の]んだ","[飲|の]みます"],"answer":3,"why":["飲んで is the te-form. 飲んでほうがいい is not Japanese.","飲み is the ます form without ます. It goes before に行きます, not before ほうがいいです.","飲んだ is the た form. た form + ほうがいいです gives advice: \"you had better take this medicine\".","飲みます is the polite ending. The plain form goes before ほう: 飲んだ."],"explain":null,"unit":7,"day":5,"step":"drill"},"n5u07d5.d3":{"id":"n5u07d5.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あしたは[九時|くじ]に[駅|えき]へ（　　）^なりません^。","options":["[行|い]ってければ","[行|い]かないければ","[行|い]きなければ","[行|い]かなければ"],"answer":4,"why":["行って is the te-form. 行ってければ is not Japanese.","The い of 行かない must come off first: 行かな + ければ. 行かないければ is not Japanese.","行き is the ます form without ます. This pattern starts from the ない form 行かない, not from 行きます.","Take 行かない, drop the last い, add ければなりません: \"I have to go to the station at nine.\""],"explain":null,"unit":7,"day":5,"step":"drill"},"n5u07d5.d4":{"id":"n5u07d5.d4","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"A：あしたは[休|やす]みですか。B：^いいえ^、あしたも[会社|かいしゃ]へ[行|い]か（　　）。","options":["ないでください","なければなりません","なくてもいいです","ないほうがいいです"],"answer":2,"why":["行かないでください asks someone else not to go. B is talking about B's own day.","いいえ means tomorrow is not a day off, so B has to go: 行かなければなりません.","行かなくてもいいです means \"I don't have to go\". B said いいえ, tomorrow is not a day off, so that does not fit.","行かないほうがいいです is advice not to go. After いいえ, B is saying tomorrow is a work day, so this does not fit."],"explain":null,"unit":7,"day":5,"step":"drill"},"n5u07d5.d5":{"id":"n5u07d5.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"かぜですから、[今日|きょう]は","after":"いいです。","tiles":["うち","で","[休|やす]んだ","ほうが"],"star":2,"bank":[2,0,3,1],"hint":"First where, with で. Then the た form, then ほうが right before いいです.","full":"かぜですから、[今日|きょう]はうちで[休|やす]んだ{ほうが}いいです。","explain":"うちで says where, 休んだ is the た form, and ほうがいいです comes last: \"You have a cold, so you had better rest at home today.\"","unit":7,"day":5,"step":"drill"},"n5u07d5.d6":{"id":"n5u07d5.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"このくすりは、","after":"なりません。","tiles":["ごはん","の","[後|あと]で","[飲|の]まなければ"],"star":2,"bank":[3,1,0,2],"hint":"Which meal? Then when? Then the must form before なりません.","full":"このくすりは、ごはんの{[後|あと]で}[飲|の]まなければなりません。","explain":"ごはんの後で says when, and 飲まなければなりません says it is a must: \"You have to take this medicine after meals.\"","unit":7,"day":5,"step":"drill"},"n5u07d5.e1":{"id":"n5u07d5.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「のどが　いたいです。」B「じゃあ、つめたい　ものは（　　）　ほうが　いいですよ。」","options":["食べません","食べない","食べないで","食べなくて"],"answer":2,"explain":"A has a sore throat, so B advises not eating cold things: 食べないほうがいいです. 食べません is the polite ending and cannot go before ほう. 食べないで and 食べなくて are te-forms, and neither goes before ほうがいいです.","unit":7,"day":5,"step":"exam"},"n5u07d5.e2":{"id":"n5u07d5.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あしたも　学校へ　来ますか。」B「はい。テストが　ありますから、八時に（　　）　なりません。」","options":["来て","来なければ","来ないければ","来なくても"],"answer":2,"explain":"B has a test, so B must come at eight: 来なければなりません. 来ないければ keeps the い of ない, which must come off. 来なくても goes with いいです (don't have to), not なりません. 来てなりません is not Japanese.","unit":7,"day":5,"step":"exam"},"n5u07d5.e3":{"id":"n5u07d5.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「あしたは　山へ　行きます。」B「山は　さむいですよ。","after":"　いいですよ。」","tiles":["コートを","もって","行った","ほうが"],"star":2,"bank":[1,3,0,2],"full":"A「あしたは　山へ　行きます。」B「山は　さむいですよ。コートを　もって　行った　{ほうが}　いいですよ。」","explain":"コートを, もって, 行った, ほうが. コートを is what to take, もって行った is the た form of もって行く, and ほうが comes right before いいです: \"You had better take a coat.\"","unit":7,"day":5,"step":"exam"},"n5u07d5.k1":{"id":"n5u07d5.k1","kind":"choice","type":"文脈規定","label":"How the exam asks it","q":"かぜですから、今日は　うちで（　　）　ほうが　いいです。","options":["休んだ","およいだ","出かけた","はたらいた"],"answer":1,"explain":"With a cold, the advice is to rest at home: 休んだほうがいいです. 出かけた (went out) does not go with うちで. はたらいた (worked) and およいだ (swam) are not good advice for someone with a cold.","unit":7,"day":5,"step":"scene"},"n5u07d5.r1":{"id":"n5u07d5.r1","kind":"choice","type":"課題理解","q":"男の人は　この　あと　はじめに　何を　しなければ　なりませんか。","script":["ナレーター：びょういんで、いしゃと男の人が話しています。男の人は、このあと、はじめに何をしなければなりませんか。","女：かぜですね。今日は、はやくうちへかえって、休んだほうがいいですよ。","男：はい。午後は、会社を休みます。","女：それから、このくすりを飲まなければなりません。ごはんの後で、飲んでください。","男：あのう、今日は、まだひるごはんを食べていません。","女：じゃあ、くすりの前に、何か食べなければなりませんね。","男：はい。駅の前の店で何か食べてから、うちへかえります。","女：そうですね。うちでは、水をたくさん飲んで、はやくねたほうがいいですよ。","男：わかりました。ありがとうございました。","ナレーター：男の人は、このあと、はじめに何をしなければなりませんか。"],"options":["うちで　ねる","くすりを　飲む","ごはんを　食べる","水を　飲む"],"printed":true,"short":["うちでねる","くすりを飲む","ごはんを食べる","水を飲む"],"answer":3,"why":["Going to bed early is advice for later, at home. He eats first.","The medicine is taken after a meal, and he has not had lunch yet, so the medicine comes after eating.","He has not eaten lunch, and the doctor says he must eat before the medicine. He will eat at a shop near the station first.","The doctor says to drink a lot of water at home, after he goes back."],"explain":null,"unit":7,"day":5,"step":"skill","clip":"l_n5u7d5"},"n5u07d6.c1":{"id":"n5u07d6.c1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：すしを[食|た]べた（　　）か。B：いいえ、^まだありません^。","options":["ことがあります","ほうがいいです","なければなりません"],"answer":1,"why":["B answers まだありません, \"not yet\", so A asked about experience: have you ever eaten sushi?","食べたほうがいいですか asks for advice: should I eat sushi? まだありません does not answer that.","なければなりません follows the ない form (食べなければ), not the た form. And B's まだありません answers a question about experience."],"unit":7,"day":6,"step":"compare"},"n5u07d6.d1":{"id":"n5u07d6.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：このえいが、[見|み]たことがある？B：うん、^[先週|せんしゅう]^[友|とも]だちと（　　）よ。","options":["[見|み]ない","[見|み]た","[見|み]る","[見|み]たことがある"],"answer":2,"why":["見ない means \"I don't watch it\". It does not go with うん or with 先週.","先週 names one time in the past, so the plain past 見た fits: I saw it with a friend last week.","見る is the dictionary form, for now or later. 先週 is last week.","たことがある is for experience at some time in your life. With a set time like 先週, just use the past: 見た."],"explain":null,"unit":7,"day":6,"step":"drill"},"n5u07d6.d2":{"id":"n5u07d6.d2","kind":"choice","type":"文の文法1","label":"Choose the word","q":"このくつは[安|やす]いです（　　）、^[小|ちい]さいですから、[買|か]わないほうがいいです^よ。","options":["が","でも","を","から"],"answer":1,"why":["が says but: the shoes are cheap, but they are small, so you had better not buy them.","でも cannot sit at the end of the first part. It starts a new sentence.","を marks the thing you act on. It cannot follow 安いです.","Cheap is not a reason not to buy them. The reason comes later: 小さいですから."],"explain":null,"unit":7,"day":6,"step":"drill"},"n5u07d6.d3":{"id":"n5u07d6.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：[午後|ごご]は[雨|あめ]がふりますか。B：さあ……。でも、^[空|そら]がくらいです^から、（　　）。","options":["ふったことがあります","ふったほうがいいです","ふらなければなりません","ふるとおもいます"],"answer":4,"why":["たことがあります tells about past experience. A asks about this afternoon.","ほうがいいです gives advice about what someone should do. Rain is not something you can advise.","なければなりません says someone must do something. Rain has no duty to fall.","B is not sure (さあ), but the dark sky is a reason to guess: I think it will rain."],"explain":null,"unit":7,"day":6,"step":"drill"},"n5u07d6.d4":{"id":"n5u07d6.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：あの[店|みせ]の[魚|さかな]は^[古|ふる]いですよ^。B：じゃあ、あの[店|みせ]では（　　）ほうがいいですね。","options":["[買|か]った","[買|か]いません","[買|か]わなかった","[買|か]わない"],"answer":4,"why":["買ったほうがいい says you had better buy it. Old fish is a reason not to.","The polite ます form does not go before ほう. Use the plain form: 買わない.","For \"had better not\", use the ない form, 買わない, not the past 買わなかった.","The fish is old, so the advice is not to buy it: 買わないほうがいいです. Before ほうがいい, \"not\" is the ない form."],"explain":null,"unit":7,"day":6,"step":"drill"},"n5u07d6.d5":{"id":"n5u07d6.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あしたは","after":"かさをもって[行|い]ったほうがいいですよ。","tiles":["[雨|あめ]が","ふる","でしょう","から"],"star":2,"bank":[2,3,0,1],"hint":"First the guess about tomorrow, then the word that makes it a reason for the advice.","full":"あしたは[雨|あめ]がふる{でしょう}からかさをもって[行|い]ったほうがいいですよ。","explain":"雨が goes with ふる, and ふる + でしょう is the guess: it will probably rain. から then makes the guess a reason for the advice at the end. \"It will probably rain tomorrow, so you had better take an umbrella.\"","unit":7,"day":6,"step":"drill"},"n5u07d6.d6":{"id":"n5u07d6.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[日本|にほん]へは","after":"のぼったことがありません。","tiles":["[行|い]った","ことが","ありますが","ふじ[山|さん]には"],"star":3,"bank":[3,1,0,2],"hint":"Which place goes with 行った, and which goes with のぼった at the end?","full":"[日本|にほん]へは[行|い]ったことがありますが{ふじ[山|さん]には}のぼったことがありません。","explain":"日本へは goes with 行ったことがありますが: I have been to Japan, but. ふじ山には goes right before のぼった: I have never climbed Mount Fuji. \"I have been to Japan, but I have never climbed Mount Fuji.\"","unit":7,"day":6,"step":"drill"},"n5u07d6.e1":{"id":"n5u07d6.e1","kind":"choice","type":"文の文法1","label":"Choose the answer","q":"子どもの　とき、父と　この　川で　およいだ（　　）。","options":["なければ　なりません","ことが　あります","ほうが　いいです","ことを　します"],"answer":2,"explain":"子どもの　とき is a time in the past, and the speaker tells an experience: I have swum in this river with my father. ほうが　いいです gives advice, which does not fit a memory from childhood. ことを　します is not Japanese here. なければ　なりません follows the ない form (およがなければ), not the た form.","unit":7,"day":6,"step":"exam"},"n5u07d6.e2":{"id":"n5u07d6.e2","kind":"choice","type":"文の文法1","label":"Choose the answer","q":"あの　店は　いつも　人が　多いです（　　）、　おいしいと　おもいます。","options":["まで","から","を","でも"],"answer":2,"explain":"Many people always go there, and that is the reason for my view: I think it is good. から gives a reason. を marks the thing an action is done to and cannot follow です. でも starts a new sentence and cannot follow 多いです here. まで means until.","unit":7,"day":6,"step":"exam"},"n5u07d6.e3":{"id":"n5u07d6.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あしたは　六時に　","after":"　はやく　ねた　ほうが　いいです。","tiles":["おきなければ","なりません","から","今日は"],"star":2,"bank":[3,0,2,1],"full":"あしたは　六時に　おきなければ　なりません　{から}　今日は　はやく　ねた　ほうが　いいです。","explain":"おきなければ, なりません, から, 今日は. 六時に goes with おきなければ　なりません: you must get up at six tomorrow. から makes that the reason. 今日は goes with the advice at the end: you had better go to bed early today.","unit":7,"day":6,"step":"exam"},"n5u07d6.k1":{"id":"n5u07d6.k1","kind":"choice","type":"表記","label":"How the exam asks it","q":"_らいしゅう_の　土よう日に　みんなで　山を　あるきます。","options":["来週","先週","来年","毎週"],"answer":1,"explain":"らいしゅう, next week, is written 来週. 先週 is せんしゅう, last week. 来年 is らいねん, next year. 毎週 is まいしゅう, every week.","unit":7,"day":6,"step":"scene"},"n5u07d6.r1":{"id":"n5u07d6.r1","kind":"choice","type":"読解・情報検索","q":"水よう日、子どもは　いくらですか。","options":["百円","二百円","四百円","六百円"],"short":["100 yen","200 yen","400 yen","600 yen"],"answer":2,"explain":"The line 大人　四百円　子ども　二百円 gives the usual prices. The cheaper price, 百円, is only for Tuesday, so on Wednesday a child pays 二百円.","why":["One hundred yen is the child price on Tuesday only, not Wednesday.","","Four hundred yen is the price for adults.","Six hundred yen is an adult and a child together, not one child."],"unit":7,"day":6,"step":"skill"},"n5u07t.1":{"id":"n5u07t.1","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"なつ休みに　はじめて　_外国_へ　行きました。","options":["そとくに","がいごく","がいこく","かいこく"],"answer":3,"explain":"外国 is がいこく, a foreign country. The 国 here is こく, not ごく, so がいごく is wrong. かいこく has か without the dakuten. そとくに reads each kanji the way it sounds on its own (そと, くに), but 外国 is never read that way.","unit":7,"step":"test"},"n5u07t.2":{"id":"n5u07t.2","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"わたしの　まちは　とうきょうの　_西_に　あります。","options":["みなみ","きた","にし","ひがし"],"answer":3,"explain":"西 is にし, west. ひがし, みなみ and きた are real words, but they are east (東), south (南) and north (北).","unit":7,"step":"test"},"n5u07t.3":{"id":"n5u07t.3","kind":"choice","type":"表記","label":"Kanji spelling","q":"友だちと　_でんしゃ_で　うみへ　行った　ことが　あります。","options":["電東","気車","雨車","電車"],"answer":4,"explain":"でんしゃ (train) is written 電車. 雨 (rain) looks like the top of 電 but is not the same kanji, and 東 (east) looks like 車 but is not 車. 気 is the き of 天気; 雨車, 電東 and 気車 are not words.","unit":7,"step":"test"},"n5u07t.4":{"id":"n5u07t.4","kind":"choice","type":"表記","label":"Kanji spelling","q":"あつい　日は　水を　たくさん　_のんだ_　ほうが　いいです。","options":["飲んだ","読んだ","休んだ","話んだ"],"answer":1,"explain":"のんだ (drank) is 飲んだ, from 飲みます. 読んだ and 休んだ are real words, but they are よんだ (read) and やすんだ (rested). 話 is the はな of 話します; 話んだ is not a word.","unit":7,"step":"test"},"n5u07t.5":{"id":"n5u07t.5","kind":"choice","type":"文脈規定","label":"Word in context","q":"そらが　くらいですね。午後は　（　　）が　ふるでしょう。","options":["くもり","かぜ","はれ","雨"],"answer":4,"explain":"The sky is dark, and ふる (fall) is used for rain: 雨が ふるでしょう (it will probably rain). かぜ (wind), はれ (sunny weather) and くもり (cloudy weather) do not fall, so they do not go with ふる.","unit":7,"step":"test"},"n5u07t.6":{"id":"n5u07t.6","kind":"choice","type":"文脈規定","label":"Word in context","q":"この　くつは　もう　（　　）ですから、新しいのを　買います。","options":["高い","安い","新しい","古い"],"answer":4,"explain":"The speaker buys new shoes because these are already old: もう 古いですから. 新しい says the shoes are new, so there is no reason to buy new ones. もう (already) does not fit 高い or 安い; shoes do not become expensive or cheap with time.","unit":7,"step":"test"},"n5u07t.7":{"id":"n5u07t.7","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"_おととい_　友だちに　あいました。","options":["二日後に　友だちに　あいます。","きのう　友だちに　あいました。","二日前に　友だちに　あいました。","三日前に　友だちに　あいました。"],"answer":3,"explain":"おととい is the day before yesterday, which is two days ago: 二日前. きのう is one day ago and 三日前 is three days ago. 二日後 is two days from now, in the future.","unit":7,"step":"test"},"n5u07t.8":{"id":"n5u07t.8","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"わたしは　にくが　_すきじゃ　ありません_。","options":["わたしは　にくが　大すきです。","わたしは　にくを　食べた　ことが　ありません。","わたしは　にくを　よく　食べます。","わたしは　にくが　きらいです。"],"answer":4,"explain":"すきじゃ ありません (do not like) is closest to きらいです (dislike). 大すきです says the opposite. よく 食べます (eat it often) does not fit someone who does not like it. 食べた ことが ありません means never having eaten it, which is not the same as not liking it.","unit":7,"step":"test"},"n5u07t.9":{"id":"n5u07t.9","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あした　パーティーに　行く？」B「ううん、しごとが　あるから　（　　）。」","options":["行くない","行かない","行った","行きない"],"answer":2,"explain":"B says ううん (no), so B uses the plain negative. 行きます ends in き, so ない joins the あ sound: 行かない. ない does not go on the stem (行きない) or on the dictionary form (行くない). 行った is past, but the party is あした.","unit":7,"step":"test"},"n5u07t.10":{"id":"n5u07t.10","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「日よう日、何を　する？」B「うちで　へやの　そうじを　（　　）よ。」","options":["する","した","しる","して"],"answer":1,"explain":"A asks what B will do on Sunday with the plain する, so B answers with the dictionary form: そうじを するよ (I will clean). した is past and does not answer a question about Sunday plans. してよ asks A to do the cleaning. しる is not a form of する.","unit":7,"step":"test"},"n5u07t.11":{"id":"n5u07t.11","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きのうは　つかれて　いたから、九時に　（　　）。","options":["ねた","ねる","ねて","ねった"],"answer":1,"explain":"きのう (yesterday) needs the past. ねます drops ます and adds た: ねた (went to bed). ねる is not past. ねて does not end a sentence about yesterday. ねった adds an extra っ; that is for verbs like かえる (かえった), not ねる.","unit":7,"step":"test"},"n5u07t.12":{"id":"n5u07t.12","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「きものを　（　　）　ことが　ありますか。」B「いいえ、まだ　ありません。」","options":["きました","きた","きて","きます"],"answer":2,"explain":"To ask about experience, use the た form + ことが ありますか: きた ことが ありますか (have you ever worn a kimono?). The て form does not go before こと. The polite きます and きました do not go before こと either; the word before こと must be plain.","unit":7,"step":"test"},"n5u07t.13":{"id":"n5u07t.13","kind":"choice","type":"文の文法1","label":"Choose the form","q":"あには　スポーツが　すきです（　　）、わたしは　あまり　すきじゃ　ありません。","options":["を","から","で","が"],"answer":4,"explain":"The two parts contrast: my brother likes sports, but I don't much. が after です means but. から would say the brother's liking is the reason I don't like sports, which makes no sense. で and を cannot follow です to join two sentences.","unit":7,"step":"test"},"n5u07t.14":{"id":"n5u07t.14","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「リンさんは　もう　ひるごはんを　食べましたか。」B「さあ…。まだ　（　　）と　おもいます。」","options":["食べないだ","食べなかったです","食べて　いない","食べて　いません"],"answer":3,"explain":"Before と おもいます the verb is plain, and まだ (not yet) goes with ～て いない: まだ 食べて いないと おもいます. 食べて いません and 食べなかったです are polite, and polite forms do not go before と おもいます. だ comes after a noun, not after ない, so 食べないだ is wrong.","unit":7,"step":"test"},"n5u07t.15":{"id":"n5u07t.15","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「あした　いっしょに　あそびませんか。」B「すみません。あしたは　びょういんへ　（　　）。」","options":["行かないで　ください","行かなければ　なりません","行かなくても　いいです","行っては　いけません"],"answer":2,"explain":"B says すみません to turn down the invitation and gives the reason: B has to go to the hospital, 行かなければ なりません. 行かなくても いいです (I don't have to go) is no reason to say no. 行っては いけません says B must not go, which is not a reason to refuse either. 行かないで ください asks A not to go.","unit":7,"step":"test"},"n5u07t.16":{"id":"n5u07t.16","kind":"star","type":"文の文法2","label":"Build the sentence","before":"きのうは　","after":"　ねました。","tiles":["あたまが","いたかった","から","はやく"],"star":1,"bank":[2,3,1,0],"full":"きのうは　あたまが　{いたかった}から　はやく　ねました。","explain":"あたまが, いたかった, から, はやく. あたまが needs its adjective after it: あたまが いたかった (my head hurt). から follows the plain past to give the reason: いたかったから. はやく describes ねました, so it goes last, right before the verb. はやく cannot come first, because it does not describe いたかった.","unit":7,"step":"test"},"n5u07t.17":{"id":"n5u07t.17","kind":"star","type":"文の文法2","label":"Build the sentence","before":"母は　「あしたは　","after":"」と　言いました。","tiles":["天気が","よく","なる","でしょう"],"star":1,"bank":[3,0,2,1],"full":"母は　「あしたは　天気が　{よく}　なるでしょう」と　言いました。","explain":"天気が, よく, なる, でしょう. 天気が comes first because it is what changes. An adjective before なる takes the く form: よく なる (become good). でしょう follows the plain なる and ends the quote, right before 」と.","unit":7,"step":"test"},"n5u07t.18":{"id":"n5u07t.18","kind":"star","type":"文の文法2","label":"Build the sentence","before":"あついですから、","after":"　いいですよ。","tiles":["ぼうしを","かぶって","出かけた","ほうが"],"star":2,"bank":[1,3,0,2],"full":"あついですから、ぼうしを　かぶって　{出かけた}　ほうが　いいですよ。","explain":"ぼうしを, かぶって, 出かけた, ほうが. ぼうしを needs its verb after it: ぼうしを かぶって (put on a hat, and then). Advice uses the た form + ほうが いい: 出かけた ほうが いいです. ほうが must come right before いいです, and 出かけた right before ほうが.","unit":7,"step":"test"},"n5u07t.19":{"id":"n5u07t.19","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"十月十日（土）\n今日は　リーさんと　山の　上の　こうえんへ　行った。わたしは　はじめてだったが、リーさんは　前にも　来た　ことが　あると　言って　いた。こうえんには　花が　たくさん　あって、とても　きれいだった。かえりに　駅の　前の　店で　ばんごはんを　食べた。","q":"ただしい　ものは　どれですか。","options":["二人は　こうえんで　ばんごはんを　食べました。","リーさんは　前にも　この　こうえんへ　来た　ことが　あります。","こうえんには　花が　あまり　ありませんでした。","わたしは　前にも　この　こうえんへ　来た　ことが　あります。"],"answer":2,"short":["こうえんでごはん","リーさんは前にも来た","花が少ない","わたしは前にも来た"],"explain":"The diary says リーさんは 前にも 来た ことが あると 言って いた, so リーさん had been there before. The writer went for the first time (はじめてだった). They ate dinner at a shop in front of the station, not in the park. The park had a lot of flowers (たくさん).","unit":7,"step":"test"},"n5u07t.20":{"id":"n5u07t.20","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"十月十日（土）\n今日は　リーさんと　山の　上の　こうえんへ　行った。わたしは　はじめてだったが、リーさんは　前にも　来た　ことが　あると　言って　いた。こうえんには　花が　たくさん　あって、とても　きれいだった。かえりに　駅の　前の　店で　ばんごはんを　食べた。","q":"二人は　かえりに　何を　しましたか。","options":["山の　上で　しゃしんを　とりました。","駅の　前の　店で　ばんごはんを　食べました。","こうえんで　花を　買いました。","リーさんの　うちへ　行きました。"],"answer":2,"short":["しゃしん","駅の前でごはん","花を買った","リーさんのうち"],"explain":"The diary ends かえりに 駅の 前の 店で ばんごはんを 食べた: on the way home they ate dinner at a shop by the station. It says nothing about buying flowers, going to リーさん's house or taking photos.","unit":7,"step":"test"},"n5u07t.21":{"id":"n5u07t.21","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"みどりプール\n午前　十時〜午後　八時（火よう日は　休み）\n・はじめて　来た　人は、うけつけで　名前を　書かなければ　なりません。\n・十さいまでの　子どもは、大人と　いっしょに　入らなければ　なりません。\n・プールに　入る　前に、シャワーを　あびて　ください。\n・プールの　中で　水や　ジュースを　飲まないで　ください。","q":"八さいの　ケンくんは　はじめて　この　プールに　来ました。ただしい　ものは　どれですか。","options":["うけつけで　名前を　書かなければ　なりません。","シャワーを　あびなくても　いいです。","プールの　中で　ジュースを　飲んでも　いいです。","一人で　プールに　入っても　いいです。"],"answer":1,"short":["名前を書く","シャワーなし","中でジュース","一人で入る"],"explain":"ケンくん is here for the first time, so he must write his name at the front desk (はじめて 来た 人は … 書かなければ なりません). He is eight, so he must go in with an adult, not alone. Everyone must shower before going in. Drinking in the pool is not allowed (飲まないで ください).","unit":7,"step":"test"},"n5u07t.22":{"id":"n5u07t.22","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"みどりプール\n午前　十時〜午後　八時（火よう日は　休み）\n・はじめて　来た　人は、うけつけで　名前を　書かなければ　なりません。\n・十さいまでの　子どもは、大人と　いっしょに　入らなければ　なりません。\n・プールに　入る　前に、シャワーを　あびて　ください。\n・プールの　中で　水や　ジュースを　飲まないで　ください。","q":"アンさんは　この　プールに　行きたいです。いつ　行きますか。","options":["月よう日の　午前　八時","火よう日の　午後　三時","水よう日の　午後　九時","木よう日の　午後　六時"],"answer":4,"short":["月・八時","火・三時","水・九時","木・六時"],"explain":"The pool is open from 午前 十時 to 午後 八時, and it is closed on 火よう日. 木よう日の 午後 六時 is inside those hours. 午前 八時 is two hours before it opens, 火よう日 is its day off, and 午後 九時 is an hour after it closes.","unit":7,"step":"test"},"n5u07t.23":{"id":"n5u07t.23","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ジョンさんへ\nあした、いっしょに　山へ　行きますね。テレビの　ニュースでは、午後から　雨だと　言って　いました。だから、あさ　七時に　出かけた　ほうが　いいと　おもいます。山の　上は　さむいですから、コートを　もって　来て　ください。かさは　わたしが　二本　もって　行きます。\nゆか","q":"ゆかさんは　どうして　七時に　出かけた　ほうが　いいと　おもって　いますか。","options":["午後から　雨が　ふるからです。","山の　上は　さむいからです。","かさが　ないからです。","あさは　雨が　ふるからです。"],"answer":1,"short":["午後から雨","山の上はさむい","かさがない","あさ雨"],"explain":"ゆか writes that the news said 午後から 雨だ, and then だから (so) suggests leaving at seven. The cold on the mountain is the reason for the coat, not for leaving early. ゆか has two umbrellas, and the rain starts in the afternoon, not the morning.","unit":7,"step":"test"},"n5u07t.24":{"id":"n5u07t.24","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ジョンさんへ\nあした、いっしょに　山へ　行きますね。テレビの　ニュースでは、午後から　雨だと　言って　いました。だから、あさ　七時に　出かけた　ほうが　いいと　おもいます。山の　上は　さむいですから、コートを　もって　来て　ください。かさは　わたしが　二本　もって　行きます。\nゆか","q":"ジョンさんは　何を　もって　行かなければ　なりませんか。","options":["コート","おべんとう","かさ","ぼうし"],"answer":1,"short":["コート","おべんとう","かさ","ぼうし"],"explain":"ゆか asks ジョン to bring a coat because it is cold on the mountain: コートを もって 来て ください. ゆか will bring the umbrellas herself (かさは わたしが 二本 もって 行きます). The letter does not mention a hat or a lunch box.","unit":7,"step":"test"},"n5u08d1.c1":{"id":"n5u08d1.c1","kind":"choice","type":"文の文法1","label":"Two things","q":"[電車|でんしゃ]とバスと（　　）が[安|やす]いですか。","options":["なに","どれ","どちら"],"answer":3,"why":["なに asks what something is. The two things are already named, so you ask which one.","どれ is for three or more things. Here there are only two: the train and the bus.","Two things, 電車 and バス, are listed with と, so ask with どちら."],"explain":null,"unit":8,"day":1,"step":"compare"},"n5u08d1.d1":{"id":"n5u08d1.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この[店|みせ]は^あの[店|みせ]^（　　）[安|やす]いです。","options":["から","で","と","より"],"answer":4,"why":["から means from or because. It does not compare two things.","で marks a place where something happens. It does not compare two things.","と means and or with. あの店と安いです does not make sense.","This shop is being measured against that shop, so あの店 takes より: cheaper than that shop."],"explain":null,"unit":8,"day":1,"step":"drill"},"n5u08d1.d2":{"id":"n5u08d1.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^バスより^[電車|でんしゃ]（　　）はやいです。","options":["ほうが","よりが","のほうを","のほうが"],"answer":4,"why":["の is missing. A noun needs の before ほう: 電車のほうが.","よりが is not a form. より already went on バス.","はやい is an adjective, so the winner takes が, not を.","バスより names the loser, so the winner 電車 takes のほうが: the train is faster."],"explain":null,"unit":8,"day":1,"step":"drill"},"n5u08d1.d3":{"id":"n5u08d1.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：^コーヒーとこうちゃと^（　　）がいいですか。B：こうちゃのほうがいいです。","options":["どちら","どこ","だれ","どれ"],"answer":1,"why":["A offers two drinks, coffee and black tea, so A asks with どちら.","どこ asks about a place, not a drink.","だれ asks about a person, not a drink.","どれ is for three or more things. A offers only two drinks."],"explain":null,"unit":8,"day":1,"step":"drill"},"n5u08d1.d4":{"id":"n5u08d1.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：いぬとねこと、どちらがすきですか。B：（　　）すきです。^いぬもねこも^かわいいですから。","options":["どちらも","どれも","どちらが","なにも"],"answer":1,"why":["B likes dogs and cats, both of the two, so B says どちらも.","どれも is for three or more things. A asked about only two animals.","どちらが asks a question. B is answering, not asking.","なにも goes with a negative verb, like なにもすきじゃありません. Here B says すきです."],"unit":8,"day":1,"step":"drill"},"n5u08d1.d5":{"id":"n5u08d1.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"この[店|みせ]の","after":"です。","tiles":["パンは","あの[店|みせ]","より","[安|やす]い"],"star":2,"bank":[2,0,3,1],"hint":"この店の must go right before the thing it owns. より follows the shop you measure against.","full":"この[店|みせ]のパンはあの[店|みせ]{より}[安|やす]いです。","explain":"この店の goes with パン, so パンは comes first. あの店 is the one you measure against, so より comes right after it. 安い ends the sentence before です.","unit":8,"day":1,"step":"drill"},"n5u08d1.d6":{"id":"n5u08d1.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[電車|でんしゃ]と","after":"か。","tiles":["バスと","どちらが","[安|やす]い","です"],"star":1,"bank":[3,1,0,2],"hint":"Each of the two things takes と. どちらが comes after both of them.","full":"[電車|でんしゃ]とバスと{どちらが}[安|やす]いですか。","explain":"電車と and バスと name the two things, then どちらが asks which. 安いです comes last, before か.","unit":8,"day":1,"step":"drill"},"n5u08d1.e1":{"id":"n5u08d1.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"電車は　バス（　　）　高いですが、はやいです。","options":["より","から","で","に"],"answer":1,"explain":"The train is measured against the bus, so バス takes より: the train costs more than the bus, but it is faster. から means from or because, で marks a place or a means, and に marks a time or a place. None of them compares two things.","unit":8,"day":1,"step":"exam"},"n5u08d1.e2":{"id":"n5u08d1.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「にくと　魚と　どちらが　すきですか。」　B「魚（　　）　すきです。」","options":["のほうで","のほうへ","のほうが","ほうが"],"answer":3,"explain":"A asks which of two, so B answers with the one B chooses ＋ のほうが: I like fish better. ほうが drops the の a noun needs. のほうで and のほうへ use the wrong small word; すき takes が.","unit":8,"day":1,"step":"exam"},"n5u08d1.e3":{"id":"n5u08d1.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"この　電車は　","after":"です。","tiles":["あの","電車","より","新しい"],"star":2,"bank":[3,2,0,1],"full":"この　電車は　あの　電車{より}　新しいです。","explain":"あの, 電車, より, 新しい. あの goes right before 電車, より follows the train you measure against, and 新しい ends the sentence before です: this train is newer than that one.","unit":8,"day":1,"step":"exam"},"n5u08d1.k1":{"id":"n5u08d1.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_新しい_　電車に　のりたいです。","options":["あたらい","あたらしい","あだらしい","あらたしい"],"answer":2,"explain":"新しい is read あたらしい, new: I want to ride the new train. あだらしい has だ instead of た, あらたしい swaps ら and た, and あたらい drops し.","unit":8,"day":1,"step":"scene"},"n5u08d1.r1":{"id":"n5u08d1.r1","kind":"choice","type":"ポイント理解","q":"女の人は　何で　大学まで　行きますか。","script":["ナレーター：男の人と女の人が話しています。女の人は何で大学まで行きますか。","女：大学まで、バスと電車と、どちらがはやいですか。","男：電車のほうがはやいですよ。でも、駅まで十五分あるきます。","女：十五分ですか。バスはどうですか。","男：バスは電車より時間がかかりますが、この店の前から出ますよ。","女：じゃあ、バスで行きます。タクシーは高いですから。","ナレーター：女の人は何で大学まで行きますか。"],"options":["電車","バス","タクシー","じてんしゃ"],"printed":true,"short":["電車","バス","タクシー","じてんしゃ"],"answer":2,"why":["The man says the train is faster, but it is a 15-minute walk to the station. She asks about the bus instead.","The bus takes longer than the train (電車より時間がかかります), but it leaves from in front of this shop. She says バスで行きます.","She says タクシーは高いですから: she does not take a taxi because it costs a lot.","Nobody talks about a bicycle."],"unit":8,"day":1,"step":"skill","clip":"l_n5u8d1"},"n5u08d2.c1":{"id":"n5u08d2.c1","kind":"choice","type":"文の文法1","label":"くだものの話","q":"A：りんごとみかんと、どちらがすきですか。B：（　　）すきです。","options":["いちばん","どちらも","どれも"],"answer":2,"why":["いちばん needs three or more things, and B does not say which one. いちばんすきです does not answer A's question.","A asks about two fruits, and B likes both: どちらもすきです.","どれも is for three or more. With two things, use どちらも."],"unit":8,"day":2,"step":"compare"},"n5u08d2.d1":{"id":"n5u08d2.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"くだものの（　　）、^[何|なに]がいちばん^すきですか。","options":["[中|なか]が","[中|なか]を","[中|なか]に","[中|なか]で"],"answer":4,"why":["が is already on 何, the one being picked. くだものの中が does not fit here.","を marks what a verb acts on. There is no verb here that takes 中を.","With いちばん, the group you choose from is marked with の中で. の中に is for where something is, like かばんの中にあります.","の中で gives the group: of all fruits, which one do you like best?"],"explain":null,"unit":8,"day":2,"step":"drill"},"n5u08d2.d2":{"id":"n5u08d2.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：かぞくの[中|なか]で、（　　）がいちばんせが[高|たか]いですか。B：^[父|ちち]です^。","options":["[何|なに]","だれ","いつ","どこ"],"answer":2,"why":["何 asks about a thing. For people in the family, ask with だれ.","The answer is a person (父), so the question word is だれ: who is the tallest?","いつ asks about a time, but B answers with a person.","どこ asks about a place, but B answers with a person."],"explain":null,"unit":8,"day":2,"step":"drill"},"n5u08d2.d3":{"id":"n5u08d2.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^この[二|ふた]つのかさは^（　　）[高|たか]いです。","options":["どれも","だれも","どこも","どちらも"],"answer":4,"why":["どれも is for three or more things. Here there are only two.","だれも is for people, and umbrellas are not people.","どこも is for places, and umbrellas are not places.","二つ means two umbrellas, so \"both\" is どちらも."],"explain":null,"unit":8,"day":2,"step":"drill"},"n5u08d2.d4":{"id":"n5u08d2.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A：この[店|みせ]の^パン^はどうですか。B：（　　）おいしいですよ。","options":["どこも","どれも","だれも","[何|なに]も"],"answer":2,"why":["どこも is for places. B is talking about the bread, not about places.","The shop has many kinds of bread, and どれも with a positive ending means every one of them is good.","だれも is for people, and bread is not a person.","何も goes with a negative ending, like 何もありません. 何もおいしいです is not said."],"explain":null,"unit":8,"day":2,"step":"drill"},"n5u08d2.d5":{"id":"n5u08d2.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"この[三|みっ]つのかばんの","after":"。","tiles":["[中|なか]で","どれが","いちばん[安|やす]い","ですか"],"star":1,"bank":[2,0,3,1],"hint":"First finish the group with の中で. Then the question word, then what you want to know.","full":"この[三|みっ]つのかばんの[中|なか]でどれが{いちばん}[安|やす]いですか。","explain":"かばんの needs 中で right after it to make the group. どれが is the one being picked, then いちばん安い, and ですか ends the question.","unit":8,"day":2,"step":"drill"},"n5u08d2.d6":{"id":"n5u08d2.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[本|ほん]を[三|さん]さつ[読|よ]みましたが、","after":"。","tiles":["どれも","あまり","おもしろく","ありませんでした"],"star":0,"bank":[3,1,0,2],"hint":"Which word means \"every one of the three books\"? あまり needs a negative ending.","full":"[本|ほん]を[三|さん]さつ[読|よ]みましたが、{どれも}あまりおもしろくありませんでした。","explain":"どれも, every one of the three books, comes first. あまり goes before the negative おもしろくありませんでした, which ends the sentence.","unit":8,"day":2,"step":"drill"},"n5u08d2.e1":{"id":"n5u08d2.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　店の　ケーキの　中で　（　　）が　いちばん　人気が　ありますか。」\nB「この　白い　ケーキです。」","options":["どこ","いつ","だれ","どれ"],"answer":4,"explain":"A picks one cake out of the shop's cakes, so the question word is どれ. だれ is for people, どこ is for places and いつ is for times, but B answers with a cake.","unit":8,"day":2,"step":"exam"},"n5u08d2.e2":{"id":"n5u08d2.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「へやに　だれか　いますか。」\nB「いいえ、（　　）　いません。」","options":["だれが","だれも","だれに","だれか"],"answer":2,"explain":"いいえ … いません means there is nobody, and \"nobody\" is だれも with a negative ending. だれか is \"someone\" and does not fit after いいえ, だれが asks \"who\", and だれに does not go with いません here.","unit":8,"day":2,"step":"exam"},"n5u08d2.e3":{"id":"n5u08d2.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「","after":"　いちばん　新しい　本ですか。」\nB「その　白い　本です。」","tiles":["この","三つの","中で","どれが"],"star":2,"bank":[3,0,2,1],"full":"A「この　三つの　{中で}　どれが　いちばん　新しい　本ですか。」\nB「その　白い　本です。」","explain":"この, 三つの, 中で, どれが. この goes before 三つの, the group ends with 中で, and どれが, the one being picked, comes right before いちばん.","unit":8,"day":2,"step":"exam"},"n5u08d2.k1":{"id":"n5u08d2.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"この　店で　いちばん　_人気_が　ある　本は　どれですか。","options":["にんき","にき","にんぎ","ひんき"],"answer":1,"explain":"人気 is read にんき, \"popular\". 人 is にん here, as in 三人, and 気 is き, as in 天気. にんぎ, ひんき and にき are not words.","unit":8,"day":2,"step":"scene"},"n5u08d2.r1":{"id":"n5u08d2.r1","kind":"choice","type":"読解・内容理解（短文）","q":"ユキさんは　どうして　あきが　いちばん　すきですか。","options":["魚が　おいしいから","天気が　よくて、山の　木が　きれいだから","あきは　あついから","父の　店が　あるから"],"short":["魚がおいしい","天気と山の木","あきはあつい","父の店がある"],"answer":2,"explain":"Right after あきがいちばんすきです, Yuki writes the reason: 天気がよくて、山の木がとてもきれいだからです.","why":["Fish is Yuki's favourite food, and the fish is good, but that is not why Yuki likes autumn.","","It is summer that is hot (なつはあついですから), and that is why Yuki does not like summer.","Yuki's father has a shop with good fish, but this is about food, not about autumn."],"unit":8,"day":2,"step":"skill"},"n5u08d3.c1":{"id":"n5u08d3.c1","kind":"choice","type":"文の文法1","label":"ギター","q":"[前|まえ]はへたでしたが、[今|いま]はじょうず（　　）。","options":["になりました","くなりました","でした"],"answer":1,"why":["Before it was bad, now it is good: a change. じょうず is a な adjective, so it takes に: \"I used to be bad, but now I've got good.\"","く is for い adjectives such as さむい. じょうず is a な adjective, so じょうずく is not a form.","でした is the past, but 今は means \"now\". \"Now it was good\" does not work, and it does not show the change either."],"unit":8,"day":3,"step":"compare"},"n5u08d3.d1":{"id":"n5u08d3.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[雨|あめ]がふって、^さむ^（　　）なりました。","options":["い","くて","に","く"],"answer":4,"why":["The い must change to く before なりました. さむいなりました is not correct.","くて means \"and\" (さむくて、…). It cannot come right before なりました.","に is for な adjectives and nouns. さむい is an い adjective.","さむい is an い adjective: take off い and add く. \"It rained and it got cold.\""],"explain":null,"unit":8,"day":3,"step":"drill"},"n5u08d3.d2":{"id":"n5u08d3.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"^くすりを[飲|の]みました^から、かぜはもう（　　）なりました。","options":["よく","いいに","よに","いく"],"answer":1,"why":["いい is special: before なります it becomes よく. \"I took medicine, so my cold is already better.\"","いい is an い adjective, so it does not take に.","よに is not a form. You need the whole よく.","いく is the verb \"go\". It is not a form of いい."],"explain":null,"unit":8,"day":3,"step":"drill"},"n5u08d3.d3":{"id":"n5u08d3.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしは[来年|らいねん]、^[大学生|だいがくせい]^（　　）なります。","options":["に","が","く","を"],"answer":1,"why":["大学生 is a noun, so it takes に before なります: \"I will become a university student next year.\"","なります marks what you become with に. 大学生が would make the student the subject, but the subject here is わたし.","く is for い adjectives. 大学生 is a noun.","を marks the thing you do something to. なります does not take を."],"unit":8,"day":3,"step":"drill"},"n5u08d3.d4":{"id":"n5u08d3.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[駅|えき]が[新|あたら]しくなって、^きれい^（　　）なりました。","options":["く","に","な","で"],"answer":2,"why":["きれい ends in い, but it is a な adjective, so きれいく is not a form.","きれい is a な adjective, so it takes に: \"The station became new and got clean.\"","な goes before a noun (きれいな駅). It cannot come before なりました.","で joins two ideas (きれいで、…). It cannot come right before なりました."],"unit":8,"day":3,"step":"drill"},"n5u08d3.d5":{"id":"n5u08d3.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[外|そと]が","after":"つけましょう。","tiles":["くらく","なりました","から、","[電気|でんき]を"],"star":1,"bank":[3,1,0,2],"hint":"くらい becomes くらく before なりました. から comes right after the reason, and 電気を goes before つけましょう.","full":"[外|そと]がくら{くなりました}から、[電気|でんき]をつけましょう。","explain":"くらく, なりました, から、, 電気を. It has got dark, and that is the reason, so から follows なりました: \"It's got dark outside, so let's turn on the light.\"","unit":8,"day":3,"step":"drill"},"n5u08d3.d6":{"id":"n5u08d3.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしは","after":"。","tiles":["[日本語|にほんご]の","[先生|せんせい]に","なり","たいです"],"star":2,"bank":[2,0,3,1],"hint":"日本語の tells what kind of teacher, so it goes before 先生に. たいです joins the ます stem なり.","full":"わたしは[日本語|にほんご]の[先生|せんせい]{になり}たいです。","explain":"日本語の, 先生に, なり, たいです. 先生 is a noun, so it takes に before なります, and なりたいです means \"want to become\": \"I want to become a Japanese teacher.\"","unit":8,"day":3,"step":"drill"},"n5u08d3.e1":{"id":"n5u08d3.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"へやを　そうじしましたから、　（　　）　なりました。","options":["きれいに","きれいな","きれいで","きれいく"],"answer":1,"explain":"きれい is a な adjective, so it takes に before なりました: \"I cleaned the room, so it got clean.\" きれいく is not a form, even though きれい ends in い. きれいな goes before a noun, and きれいで joins two ideas.","unit":8,"day":3,"step":"exam"},"n5u08d3.e2":{"id":"n5u08d3.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"この　店の　ケーキは　先月から　百円　（　　）　なりました。","options":["高かった","高くて","高い","高く"],"answer":4,"explain":"高い is an い adjective, so い changes to く before なりました: \"The cake at this shop has gone up by 100 yen since last month.\" 高い and 高かった cannot come right before なりました, and 高くて means \"expensive and …\".","unit":8,"day":3,"step":"exam"},"n5u08d3.e3":{"id":"n5u08d3.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"もう","after":"か。","tiles":["十時に","なりました","から、","ねましょう"],"star":1,"bank":[2,3,0,1],"full":"もう　十時に　{なりました}　から、　ねましょう　か。","explain":"十時に, なりました, から、, ねましょう. A time takes に before なります, から follows the reason, and ねましょうか is the suggestion: \"It's already ten o'clock, so shall we go to bed?\"","unit":8,"day":3,"step":"exam"},"n5u08d3.k1":{"id":"n5u08d3.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_来月_から　コーヒーが　百円　高く　なります。","options":["らいがつ","らいげつ","きげつ","らいつき"],"answer":2,"explain":"来月, \"next month\", is read らいげつ. 月 is がつ in the names of months (一月, いちがつ), but in 来月 and 今月 it is げつ. らいつき is not a word, and 来 is not read き at the start of 来月.","unit":8,"day":3,"step":"scene"},"n5u08d3.r1":{"id":"n5u08d3.r1","kind":"choice","type":"即時応答","q":"女：リーさん、日本語が　じょうずに　なりましたね。","script":["女：リーさん、日本語がじょうずになりましたね。","ナレーター：1","男：そうですか。じゃあ、がんばってください。","ナレーター：2","男：ありがとうございます。まいにちれんしゅうしましたから。","ナレーター：3","男：はい、じょうずにしました。"],"options":["そうですか。じゃあ、がんばって　ください。","ありがとうございます。まいにち　れんしゅうしましたから。","はい、じょうずに　しました。"],"printed":false,"short":["がんばって ください","ありがとうございます","じょうずに しました"],"answer":2,"why":["She is praising him. がんばって ください is what you say to someone else who has work ahead, not a reply to a compliment.","She says his Japanese has got better. He thanks her and gives the reason: he practised every day.","じょうずに します means making something good on purpose. It does not answer a remark about how his Japanese has changed."],"unit":8,"day":3,"step":"skill","clip":"l_n5u8d3"},"n5u08d4.c1":{"id":"n5u08d4.c1","kind":"choice","type":"文の文法1","label":"へやのでんき","q":"でんきをつけて、へや^を^あかるく（　　）。","options":["にしました","しました","なりました"],"answer":2,"why":["あかるい is an い-adjective, so it takes く alone. You cannot add に after あかるく.","へやを has を: I did something to the room. あかるくしました means \"I made it bright\".","なりました goes with が: へやがあかるくなりました. After へやを it does not fit."],"explain":null,"unit":8,"day":4,"step":"compare"},"n5u08d4.d1":{"id":"n5u08d4.d1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"テレビのおとが^[大|おお]きい^です。もうすこし（　　）ください。","options":["[小|ちい]さにして","[小|ちい]さくなって","[小|ちい]さくして","[小|ちい]さいして"],"answer":3,"why":["小さい is an い-adjective. It does not take に.","なってください asks the person to become small. Here you ask them to change the sound, so use して.","小さい becomes 小さく before して: \"please turn it down\".","The い must change to く before して."],"explain":null,"unit":8,"day":4,"step":"drill"},"n5u08d4.d2":{"id":"n5u08d4.d2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"へやが^くらい^ですね。でんきをつけて、（　　）しましょう。","options":["あかるくて","あかるく","あかるい","あかるいに"],"answer":2,"why":["The て form joins two ideas. It does not go before する here.","あかるい becomes あかるく before しましょう: \"let's make it bright\".","The い must change to く before する.","An い-adjective does not take に."],"explain":null,"unit":8,"day":4,"step":"drill"},"n5u08d4.d3":{"id":"n5u08d4.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"「[何|なに]に^しますか^。」「わたしはこうちゃ（　　）します。」","options":["で","に","を","が"],"answer":2,"why":["で does not say what you choose. Use に.","The question is 何にしますか, so the answer is こうちゃにします: \"I'll have tea\".","こうちゃをします is not said. To say what you choose, use に.","が does not go before します to say what you choose."],"explain":null,"unit":8,"day":4,"step":"drill"},"n5u08d4.d4":{"id":"n5u08d4.d4","kind":"choice","type":"文の文法1","label":"Choose the form","q":"おきゃくさんが[来|き]ますから、へやを（　　）^します^。","options":["きれいに","きれいく","きれいな","きれいだ"],"answer":1,"why":["きれい is a な-adjective, so it takes に before します.","きれい ends in い, but it is not an い-adjective. It never takes く.","きれいな needs a noun after it, like きれいなへや.","きれいだ ends a sentence. It cannot go before します."],"unit":8,"day":4,"step":"drill"},"n5u08d4.d5":{"id":"n5u08d4.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"すみません、","after":"ください。","tiles":["テレビの","おとを","[小|ちい]さく","して"],"star":2,"bank":[2,0,3,1],"hint":"Whose sound is it? Then how do you want it? して comes right before ください.","full":"すみません、テレビのおとを[小|ちい]さ{くして}ください。","explain":"テレビの goes right before おとを. 小さく joins on to して, and してください asks the person to do it.","unit":8,"day":4,"step":"drill"},"n5u08d4.d6":{"id":"n5u08d4.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[友|とも]だちが[来|き]ますから、","after":"しました。","tiles":["へやと","だいどころを","きれい","に"],"star":2,"bank":[1,3,0,2],"hint":"Which two places did you clean? に comes right after きれい.","full":"[友|とも]だちが[来|き]ますから、へやとだいどころをきれい{にしました}。","explain":"へやと joins on to だいどころを: \"the room and the kitchen\". きれい is a な-adjective, so に comes after it, then しました.","unit":8,"day":4,"step":"drill"},"n5u08d4.e1":{"id":"n5u08d4.e1","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ちょっと　あついですね。まどを　あけて、へやを　（　　）　しましょう。","options":["すずしい","すずしいに","すずしくて","すずしく"],"answer":4,"explain":"すずしい is an い-adjective, so it becomes すずしく before しましょう: \"let's make the room cool\". すずしい must change to く, an い-adjective does not take に, and the て form すずしくて does not go before する.","unit":8,"day":4,"step":"exam"},"n5u08d4.e2":{"id":"n5u08d4.e2","kind":"choice","type":"文の文法1","label":"Choose the form","q":"「大きい　コップと　小さい　コップが　あります。どちらに　しますか。」「じゃあ、大きい（　　）に　します。」","options":["く","が","の","な"],"answer":3,"explain":"大きいの means \"the big one\", and 大きいのに します says which one you choose. An い-adjective does not take な, 大きいく is not a form, and が cannot come before に.","unit":8,"day":4,"step":"exam"},"n5u08d4.e3":{"id":"n5u08d4.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしは　コーヒーに　しますが、","after":"します。","tiles":["友だちは","オレンジ","ジュース","に"],"star":2,"bank":[3,1,0,2],"full":"わたしは　コーヒーに　しますが、友だちは　オレンジ　ジュース{に}　します。","explain":"友だちは, オレンジ, ジュース, に. 友だちは shows the other person. オレンジ ジュース is what the friend chooses, and に comes before します.","unit":8,"day":4,"step":"exam"},"n5u08d4.k1":{"id":"n5u08d4.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"_飲みもの_は　何に　しますか。","options":["のみの","のみもの","たべもの","よみもの"],"answer":2,"explain":"飲みもの is のみもの, something to drink. たべもの is 食べもの and よみもの is 読みもの, and のみの is not this word.","unit":8,"day":4,"step":"scene"},"n5u08d4.r1":{"id":"n5u08d4.r1","kind":"choice","type":"読解・内容理解（短文）","q":"「わたし」は　どうして　カレーに　しましたか。","options":["きのうの　ばんも　魚を　食べたから。","カレーが　安かったから。","魚が　きらいだから。","友だちが　カレーに　したから。"],"answer":1,"short":["きのうも魚を食べた","カレーが安かった","魚がきらい","友だちがカレーにした"],"explain":"The writer ate fish last night too (きのうの ばんも 魚を 食べました), and から says that is why she chose curry.","why":["","The passage says nothing about the price.","She says she likes fish too (わたしも 魚が すきです).","The friend chose the fish lunch, not curry."],"unit":8,"day":4,"step":"skill"},"n5u08d5.c1":{"id":"n5u08d5.c1","kind":"choice","type":"文の文法1","label":"テスト","q":"A：お[金|かね]、たくさんありますか。B：^いいえ^、[千円|せんえん]（　　）ありません。","options":["だけ","しか","ぐらい"],"answer":2,"why":["千円だけありません would mean \"just 1,000 yen is missing\". That does not answer the question.","B says いいえ: there is not much money, only 1,000 yen. しか goes with the negative ありません.","ぐらい means \"about\". 千円ぐらいありません does not make sense after いいえ."],"unit":8,"day":5,"step":"compare"},"n5u08d5.d1":{"id":"n5u08d5.d1","kind":"choice","type":"文の文法1","label":"Choose the word","q":"おなかがいっぱいですから、ケーキは[一|ひと]つ（　　）^[食|た]べました^。","options":["しか","も","だけ","に"],"answer":3,"why":["しか needs a negative ending. Here the ending is 食べました, which is positive.","一つも goes with a negative ending: 一つも食べませんでした (I didn't eat even one). It does not go with 食べました.","The ending 食べました is positive, so \"only one\" is 一つだけ.","に does not go after 一つ here. 一つに食べました is not Japanese."],"unit":8,"day":5,"step":"drill"},"n5u08d5.d2":{"id":"n5u08d5.d2","kind":"choice","type":"文の文法1","label":"Choose the ending","q":"A：ジュースを[買|か]いませんか。B：すみません、^[百円|ひゃくえん]しか^（　　）。","options":["ありません","ありました","あって","あります"],"answer":1,"why":["しか needs a negative ending: 百円しかありません, \"I only have 100 yen\".","ありました is positive too. しか never goes with it.","あって is the te-form. It cannot end the sentence here, and しか needs a negative ending.","あります is positive. After しか, the ending must be negative."],"explain":null,"unit":8,"day":5,"step":"drill"},"n5u08d5.d3":{"id":"n5u08d5.d3","kind":"choice","type":"文の文法1","label":"Choose the word","q":"A：たまごはたくさんありますか。B：^いいえ^、[二|ふた]つ（　　）ありません。","options":["で","だけ","を","しか"],"answer":4,"why":["で does not fit here. 二つでありません is not Japanese.","二つだけありません would mean \"just two are missing\". B says いいえ, there are not many eggs, so that does not fit.","を does not go with ありません. 二つをありません is not Japanese.","There are not many eggs, only two. しか goes with the negative ありません."],"explain":null,"unit":8,"day":5,"step":"drill"},"n5u08d5.d4":{"id":"n5u08d5.d4","kind":"choice","type":"文の文法1","label":"Choose the word","q":"けさは^[時間|じかん]がありませんでした^から、コーヒー（　　）[飲|の]みました。","options":["だけ","しか","にだけ","をだけ"],"answer":1,"why":["There was no time, so only coffee. The ending 飲みました is positive, so use だけ.","しか needs a negative ending, but 飲みました is positive.","に does not go with 飲みます. You drink something を, not に.","だけ comes straight after the noun. を cannot come before it: コーヒーをだけ is wrong."],"explain":null,"unit":8,"day":5,"step":"drill"},"n5u08d5.d5":{"id":"n5u08d5.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"[電車|でんしゃ]まで","after":"、はしりましょう。","tiles":["[五分|ごふん]","しか","ありません","から"],"star":1,"bank":[2,0,3,1],"hint":"How much time comes first, then しか, then the negative ending, then から for the reason.","full":"[電車|でんしゃ]まで[五分|ごふん]{しか}ありませんから、はしりましょう。","explain":"五分しかありません says there is not much time, and から gives the reason for running: \"There are only five minutes until the train, so let's run.\"","unit":8,"day":5,"step":"drill"},"n5u08d5.d6":{"id":"n5u08d5.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"きのうは","after":"、ねむいです。","tiles":["[三時間|さんじかん]","だけ","ねました","から"],"star":1,"bank":[3,1,0,2],"hint":"How long comes first, then だけ, then the positive ending, then から.","full":"きのうは[三時間|さんじかん]{だけ}ねましたから、ねむいです。","explain":"三時間だけ comes before the positive ending ねました, and から gives the reason: \"I only slept three hours yesterday, so I'm sleepy.\"","unit":8,"day":5,"step":"drill"},"n5u08d5.e1":{"id":"n5u08d5.e1","kind":"choice","type":"文の文法1","label":"Choose the word","q":"A「りんごを　たくさん　買いましたか。」B「いいえ、高かったですから、二つ（　　）　買いませんでした。」","options":["と","だけ","が","しか"],"answer":4,"explain":"The apples were expensive, so B bought only two: 二つしか買いませんでした. しか goes with the negative ending. 二つだけ買いませんでした would mean \"I didn't buy just two\", which does not fit. が and と cannot go between 二つ and 買いませんでした here.","unit":8,"day":5,"step":"exam"},"n5u08d5.e2":{"id":"n5u08d5.e2","kind":"choice","type":"文の文法1","label":"Choose the word","q":"A「よく　テレビを　見ますか。」B「いいえ。いそがしいですから、毎日　三十分（　　）　見ます。」","options":["が","だけ","の","しか"],"answer":2,"explain":"B is busy and watches only a little: 三十分だけ見ます. The ending 見ます is positive, so だけ fits. しか needs a negative ending (三十分しか見ません). が and の cannot go between 三十分 and 見ます.","unit":8,"day":5,"step":"exam"},"n5u08d5.e3":{"id":"n5u08d5.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「ケーキを　たくさん　買いましたか。」B「いいえ。店に　","after":"。」","tiles":["一つ","しか","ありません","でした"],"star":2,"bank":[1,3,0,2],"full":"A「ケーキを　たくさん　買いましたか。」B「いいえ。店に　一つ　{しか}　ありません　でした。」","explain":"一つ, しか, ありません, でした. 一つしか needs a negative ending, and ありませんでした is the negative past: \"There was only one at the shop.\"","unit":8,"day":5,"step":"exam"},"n5u08d5.k1":{"id":"n5u08d5.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"きっぷは　_一人_　千円です。","options":["ひとにん","いちり","いちにん","ひとり"],"answer":4,"explain":"\"One person\" is read ひとり. いちにん is not how you say one person in a sentence like this, and ひとにん and いちり are not readings of 一人.","unit":8,"day":5,"step":"scene"},"n5u08d5.r1":{"id":"n5u08d5.r1","kind":"choice","type":"課題理解","q":"二人は　何を　買いますか。","script":["ナレーター：店で、男の人と女の人が話しています。二人は、何を買いますか。","男：ぼくは、今、五百円しかありません。","女：わたしは三百円あります。二人で八百円ですね。","男：あのケーキ、おいしいですよ。一つ六百円です。","女：じゃあ、ケーキは一つだけ買いましょう。それから、ジュースも飲みたいです。ジュースは一本百五十円です。","男：ケーキと、ジュース二本で、九百円ですね。ぼくたちは、八百円しかありませんよ。","女：そうですね。じゃあ、ケーキはだめですね。パンはどうですか。パンは一つ二百円です。","男：いいですね。じゃあ、パンを二つと、ジュースを二本買いましょう。七百円ですね。","女：はい、そうしましょう。","ナレーター：二人は、何を買いますか。"],"options":["ケーキ　一つと　ジュース　二本","ケーキ　一つだけ","パン　二つと　ジュース　二本","パン　二つだけ"],"printed":true,"short":["ケーキ一つとジュース二本","ケーキ一つだけ","パン二つとジュース二本","パン二つだけ"],"answer":3,"why":["A cake and two juices cost 900 yen, but they have only 800 yen together.","The woman wants juice too, and in the end they choose bread instead of the cake.","Two pieces of bread (400 yen) and two juices (300 yen) make 700 yen, which they can pay. The man says 買いましょう and the woman agrees.","They buy juice as well as the bread."],"unit":8,"day":5,"step":"skill","clip":"l_n5u8d5"},"n5u08d6.c1":{"id":"n5u08d6.c1","kind":"choice","type":"文の文法1","label":"セールのかばん","q":"セールですから、[店|みせ]の[人|ひと]^が^かばん^を^[安|やす]く（　　）。","options":["しました","にしました","なりました"],"answer":1,"why":["店の人が is the person who acts and かばんを is the thing changed, so 安くしました: the shop staff made the bags cheaper.","安く already has く. に goes after a noun or a な adjective, like 千円にしました, not after 安く.","なりました says something changed by itself, and that thing takes が: かばんが安くなりました. With 店の人が and かばんを, it does not fit."],"explain":null,"unit":8,"day":6,"step":"compare"},"n5u08d6.d1":{"id":"n5u08d6.d1","kind":"choice","type":"文の文法1","label":"Choose the word","q":"A：^うどんとそば^、（　　）にしますか。B：そばにします。","options":["どちらも","いちばん","どれ","どちら"],"answer":4,"why":["どちらも means both. It answers a question; it cannot ask which one, and どちらもにしますか is not said.","いちばん needs a group of three or more and a word that asks, like どれがいちばん. いちばんにしますか does not ask which one.","どれ is for three or more things. Here there are only two.","A offers two things, うどん and そば, so A asks with どちら: which will you have?"],"explain":null,"unit":8,"day":6,"step":"drill"},"n5u08d6.d2":{"id":"n5u08d6.d2","kind":"choice","type":"文の文法1","label":"Choose the word","q":"このセールは[今日|きょう]（　　）^です^よ。","options":["より","だけ","どれも","しか"],"answer":2,"why":["より compares two things, but nothing is compared here. 今日よりです is not said.","The ending です is positive, so \"only today\" is 今日だけです.","どれも is about three or more things. It cannot follow 今日.","しか needs a negative ending, like 今日しかありません. Here the ending is です."],"explain":null,"unit":8,"day":6,"step":"drill"},"n5u08d6.d3":{"id":"n5u08d6.d3","kind":"choice","type":"文の文法1","label":"Choose the form","q":"[新|あたら]しい[店|みせ]がたくさんできて、この[道|みち]^が^（　　）。","options":["にぎやかくしました","にぎやかくなりました","にぎやかになりました","にぎやかにしました"],"answer":3,"why":["にぎやかく is not a form, and しました does not fit この道が either.","にぎやか is a な adjective, so にぎやかく is not a form.","この道が is the thing that changed, so use なりました. にぎやか is a な adjective, so it takes に: the street got lively.","しました needs someone who acts and a thing with を. Here この道が is the thing that changed."],"explain":null,"unit":8,"day":6,"step":"drill"},"n5u08d6.d4":{"id":"n5u08d6.d4","kind":"choice","type":"文の文法1","label":"Choose the word","q":"このかばんは[三|みっ]つの^[中|なか]で^（　　）[大|おお]きいです。","options":["いちばん","より","のほうが","どちらも"],"answer":1,"why":["三つの中で gives a group of three, so いちばん picks the one: this bag is the biggest of the three.","より follows the thing you measure against, like あのかばんより. It cannot come after 中で.","のほうが follows the winner of two, like このかばんのほうが. It cannot come after 中で.","どちらも is about two things, and it says the same about both. Here one bag out of three is picked."],"explain":null,"unit":8,"day":6,"step":"drill"},"n5u08d6.d5":{"id":"n5u08d6.d5","kind":"star","type":"文の文法2","label":"Build the sentence","before":"セールでも、このシャツは[前|まえ]より","after":"。","tiles":["[百円|ひゃくえん]","しか","[安|やす]く","なりませんでした"],"star":2,"bank":[3,1,0,2],"hint":"How much comes first, then しか. しか needs a negative ending, and 安い changes before なる.","full":"セールでも、このシャツは[前|まえ]より[百円|ひゃくえん]しか{[安|やす]く}なりませんでした。","explain":"百円, しか, 安く, なりませんでした. 百円しか needs a negative ending, so it goes with なりませんでした. 安い becomes 安く before なる: \"Even in the sale, this shirt only got 100 yen cheaper than before.\"","unit":8,"day":6,"step":"drill"},"n5u08d6.d6":{"id":"n5u08d6.d6","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A：[何|なに]にしますか。B：メニューの","after":"します。","tiles":["[中|なか]で","いちばん","[安|やす]いの","に"],"star":2,"bank":[2,3,0,1],"hint":"メニューの needs 中で to make the group. 安いの means \"the cheap one\", and に comes right before します.","full":"A：[何|なに]にしますか。B：メニューの[中|なか]でいちばん{[安|やす]いの}にします。","explain":"中で, いちばん, 安いの, に. メニューの中で is the group, いちばん安いの is the cheapest one, and にします says what you choose: \"I'll have the cheapest one on the menu.\"","unit":8,"day":6,"step":"drill"},"n5u08d6.e1":{"id":"n5u08d6.e1","kind":"choice","type":"文の文法1","label":"Choose the answer","q":"この　店の　ケーキは　どれも　おいしいですが、チーズケーキが　（　　）　すきです。","options":["どちらも","だけ","いちばん","しか"],"answer":3,"explain":"どれも shows there are many cakes, and the speaker picks one: チーズケーキが　いちばん　すきです, I like the cheesecake best. どちらも is about two things and does not pick one. だけ cannot come after が here, and しか needs a negative ending, but the ending is すきです.","unit":8,"day":6,"step":"exam"},"n5u08d6.e2":{"id":"n5u08d6.e2","kind":"choice","type":"文の文法1","label":"Choose the answer","q":"あつく　なりましたから、かみを　（　　）。","options":["みじかいに　しました","みじかいに　なりました","みじかく　なりました","みじかく　しました"],"answer":4,"explain":"かみを has を, so someone changed the hair: みじかく　しました, I had my hair cut short. なりました needs が (かみが　みじかく　なりました), so it does not fit after かみを. みじかい is an い adjective, so it takes く, not に.","unit":8,"day":6,"step":"exam"},"n5u08d6.e3":{"id":"n5u08d6.e3","kind":"star","type":"文の文法2","label":"Build the sentence","before":"A「どちらの　かばんに　しますか。」\nB「","after":"、それに　します。」","tiles":["白い","かばんの","ほうが","安いですから"],"star":2,"bank":[3,2,0,1],"full":"A「どちらの　かばんに　しますか。」\nB「白い　かばんの　{ほうが}　安いですから、それに　します。」","explain":"白い, かばんの, ほうが, 安いですから. 白い goes before かばん, a noun needs の before ほうが, and から gives the reason for the choice: \"The white bag is cheaper, so I'll take that one.\"","unit":8,"day":6,"step":"exam"},"n5u08d6.k1":{"id":"n5u08d6.k1","kind":"choice","type":"漢字読み","label":"How the exam asks it","q":"この　本は　今週だけ　_八百円_です。","options":["はっぴゃくえん","はっひゃくえん","はちびゃくえん","はちひゃくえん"],"answer":1,"explain":"八百円 is read はっぴゃくえん: 八 becomes はっ and 百 becomes ぴゃく. はちひゃくえん, はっひゃくえん and はちびゃくえん are not how 800 is said.","unit":8,"day":6,"step":"scene"},"n5u08d6.r1":{"id":"n5u08d6.r1","kind":"choice","type":"読解・情報検索","q":"来月から　安く　なる　ものは　どれですか。","options":["ケーキ","サンドイッチ","コーヒー","こうちゃ"],"short":["ケーキ","サンドイッチ","コーヒー","こうちゃ"],"answer":2,"explain":"The sandwich line reads 五百円　→　四百五十円: 500 yen this month, 450 yen next month. It is the only price that goes down.","why":["Cake goes from 400 yen to 450 yen, so it gets more expensive.","","Coffee goes from 300 yen to 350 yen, so it gets more expensive.","Tea stays at 300 yen (かわりません, no change)."],"unit":8,"day":6,"step":"skill"},"n5u08t.1":{"id":"n5u08t.1","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"りんごを　_半分_に　きって、友だちと　食べました。","options":["はんぶん","はんぷん","はんふん","ばんぶん"],"answer":1,"explain":"半分 is はんぶん, half. The 分 in this word is ぶん, with the dakuten. はんふん and はんぷん give 分 the sounds it has in times (ふん, ぷん), which are not used in 半分. ばんぶん wrongly puts a dakuten on は.","unit":8,"step":"test"},"n5u08t.2":{"id":"n5u08t.2","kind":"choice","type":"漢字読み","label":"Kanji reading","q":"この　まちは　前より　人が　_多く_　なりました。","options":["おうく","すくなく","たく","おおく"],"answer":4,"explain":"多く is おおく, from 多い (many). おうく spells the long お with う; 多い is written おおい. すくなく is a real word, but it is 少なく (few), the opposite. たく is not a reading of 多く.","unit":8,"step":"test"},"n5u08t.3":{"id":"n5u08t.3","kind":"choice","type":"表記","label":"Kanji spelling","q":"この　店の　やさいは　先週より　_やすく_　なりました。","options":["高く","安く","休く","女く"],"answer":2,"explain":"やすく (cheaper) is 安く, from 安い. 休 is the やす of 休みます, but 休く is not a word. 女 looks like the bottom of 安, but 女く is not a word. 高く is a real word, but it is たかく (more expensive).","unit":8,"step":"test"},"n5u08t.4":{"id":"n5u08t.4","kind":"choice","type":"表記","label":"Kanji spelling","q":"この　くつは　ちょっと　_ちいさい_です。もっと　大きいのは　ありますか。","options":["小さい","少ない","小い","少さい"],"answer":1,"explain":"ちいさい (small) is written 小さい. 少 looks like 小 with an extra stroke, but 少さい is not a word. 少ない is a real word, but it is すくない (few). 小い leaves out the さ that 小さい needs.","unit":8,"step":"test"},"n5u08t.5":{"id":"n5u08t.5","kind":"choice","type":"文脈規定","label":"Word in context","q":"わたしの　へやは　せまいですが、あねの　へやは　（　　）です。","options":["みじかい","ひろい","ほそい","せまい"],"answer":2,"explain":"が (but) shows the two rooms are different: my room is small, but my sister's is big, ひろい. せまい would make them the same, so が does not fit. みじかい (short) and ほそい (thin) are not used for the size of a room.","unit":8,"step":"test"},"n5u08t.6":{"id":"n5u08t.6","kind":"choice","type":"文脈規定","label":"Word in context","q":"子どもの　ときは　にんじんが　きらいでしたが、今は　（　　）に　なりました。","options":["きらい","じょうず","すき","へた"],"answer":3,"explain":"でしたが (was, but) shows a change: I disliked carrots as a child, but now I like them, すきに なりました. きらい would mean nothing changed. じょうず (good at) and へた (bad at) are for skills, not for food.","unit":8,"step":"test"},"n5u08t.7":{"id":"n5u08t.7","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"はこの　中に　りんごが　_二つしか　ありません_。","options":["はこの　中に　りんごが　二つも　あります。","はこの　中に　りんごが　一つも　ありません。","はこの　中に　りんごが　二つだけ　あります。","はこの　中に　りんごが　二つより　多く　あります。"],"answer":3,"explain":"二つしか ありません means there are only two, which is the same as 二つだけ あります. 二つも あります stresses that two is a lot, the opposite feeling. 一つも ありません means there are none. 二つより 多く means more than two.","unit":8,"step":"test"},"n5u08t.8":{"id":"n5u08t.8","kind":"choice","type":"言い換え類義","label":"Same meaning","q":"きのう、_へやを　きれいに　しました_。","options":["きのう、へやで　あそびました。","きのう、へやを　かりました。","きのう、へやが　きたなく　なりました。","きのう、へやを　そうじしました。"],"answer":4,"explain":"へやを きれいに しました means I made the room clean, which is closest to そうじしました (cleaned). きたなく なりました says the room got dirty, the opposite. あそびました (played) and かりました (rented) say nothing about making it clean.","unit":8,"step":"test"},"n5u08t.9":{"id":"n5u08t.9","kind":"choice","type":"文の文法1","label":"Choose the form","q":"きのうより　今日（　　）　さむいですね。","options":["のほうが","より","ほうが","のほうに"],"answer":1,"explain":"きのうより already gives the thing compared, so the colder day takes のほうが: 今日のほうが さむい. 今日より would compare today with today. ほう needs の after a noun, so ほうが alone is wrong. さむい needs が for the thing that is cold, not に.","unit":8,"step":"test"},"n5u08t.10":{"id":"n5u08t.10","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　白い　くつと　あの　くろい　くつと、（　　）が　すきですか。」B「白い　くつの　ほうが　すきです。」","options":["どこ","どなた","どれ","どちら"],"answer":4,"explain":"A names two pairs of shoes with と…と, so the question word is どちら (which of the two). どれ is for three or more. どこ asks about a place and どなた about a person, and B answers with one of the shoes.","unit":8,"step":"test"},"n5u08t.11":{"id":"n5u08t.11","kind":"choice","type":"文の文法1","label":"Choose the form","q":"わたしの　まちは、一年の　中で　八月が　（　　）　あついです。","options":["いちばん","どちら","ほう","どれ"],"answer":1,"explain":"〜の 中で X が いちばん says X is the most of a group: in the whole year, August is the hottest. どちら and どれ are question words and cannot sit in a statement like this. ほう is used with のほうが to compare two things, and there is no の before it here.","unit":8,"step":"test"},"n5u08t.12":{"id":"n5u08t.12","kind":"choice","type":"文の文法1","label":"Choose the form","q":"A「この　二つの　カメラ、どちらが　いいですか。」B「（　　）　いいですが、こちらの　ほうが　安いですよ。」","options":["どちらも","なにも","どれも","どちらが"],"answer":1,"explain":"B says both cameras are good (but this one is cheaper). For two things, both is どちらも. どれも is for three or more, and A asks about 二つ. どちらが is a question and does not answer one. なにも goes with a negative ending, not with いいです.","unit":8,"step":"test"},"n5u08t.13":{"id":"n5u08t.13","kind":"choice","type":"文の文法1","label":"Choose the form","q":"もう　五時ですね。空が　くらく　（　　）ね。","options":["でした","なりました","ありました","しました"],"answer":2,"explain":"The sky changed on its own, so くらく takes なりました (became dark). くらく しました means someone made it dark, and that needs を, not 空が. ありました and でした do not follow the く form.","unit":8,"step":"test"},"n5u08t.14":{"id":"n5u08t.14","kind":"choice","type":"文の文法1","label":"Choose the form","q":"ズボンが　長いですから、少し　みじかく　（　　）　ください。","options":["いて","して","なって","あって"],"answer":2,"explain":"The speaker asks a person to make the trousers shorter: みじかく して ください. みじかく なって ください asks the trousers themselves to become short, which a person cannot ask. あって and いて do not follow the く form to mean make or become.","unit":8,"step":"test"},"n5u08t.15":{"id":"n5u08t.15","kind":"choice","type":"文の文法1","label":"Choose the form","q":"月よう日から　金よう日まで　しごとが　いそがしいですから、テレビは　日よう日（　　）　見ます。","options":["を","だけ","が","しか"],"answer":2,"explain":"The speaker watches TV only on Sunday, and the verb 見ます is positive, so the word is だけ. しか means only too, but it needs a negative verb (見ません). を and が do not go after 日よう日 here; テレビは is what is watched.","unit":8,"step":"test"},"n5u08t.16":{"id":"n5u08t.16","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしの　かぞくの　","after":"　人は　母です。","tiles":["中で","いちばん","はやく","おきる"],"star":1,"bank":[3,1,0,2],"full":"わたしの　かぞくの　中で　{いちばん}　はやく　おきる　人は　母です。","explain":"中で, いちばん, はやく, おきる. かぞくの must be followed by 中で (in my family). いちばん goes right before the word it makes the most: いちばん はやく (the earliest). はやく describes おきる, and おきる describes 人, so it comes just before 人は.","unit":8,"step":"test"},"n5u08t.17":{"id":"n5u08t.17","kind":"star","type":"文の文法2","label":"Build the sentence","before":"わたしは　いつも　コーヒーに　","after":"　飲みます。","tiles":["さとうを","入れて","あまく","して"],"star":2,"bank":[3,0,2,1],"full":"わたしは　いつも　コーヒーに　さとうを　入れて　{あまく}　して　飲みます。","explain":"さとうを, 入れて, あまく, して. さとうを needs its verb after it: さとうを 入れて (put in sugar). An adjective before する takes the く form: あまく して (make it sweet). して joins to 飲みます, so it comes last.","unit":8,"step":"test"},"n5u08t.18":{"id":"n5u08t.18","kind":"star","type":"文の文法2","label":"Build the sentence","before":"ケーキが　","after":"　しましょう。","tiles":["一つ","しか","ありませんから","半分に"],"star":1,"bank":[2,3,0,1],"full":"ケーキが　一つ　{しか}　ありませんから　半分に　しましょう。","explain":"一つ, しか, ありませんから, 半分に. しか follows the amount and needs a negative verb after it: 一つしか ありません (there is only one). から gives the reason. 半分に goes with しましょう at the end: 半分に しましょう (let's cut it in half).","unit":8,"step":"test"},"n5u08t.19":{"id":"n5u08t.19","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"駅の　前に　新しい　パンやが　あります。今日、母と　はじめて　行きました。となりの　店より　少し　高いですが、パンが　大きくて、とても　おいしかったです。わたしは　チーズの　パンを　三つ　買いました。母は　あまい　パンを　一つだけ　買いました。こんどは　友だちと　行きたいです。","q":"ただしい　ものは　どれですか。","options":["新しい　パンやは　となりの　店より　安いです。","新しい　パンやの　パンは　大きいです。","母は　チーズの　パンを　三つ　買いました。","わたしは　友だちと　パンやへ　行きました。"],"answer":2,"short":["となりより安い","パンが大きい","母がチーズ三つ","友だちと行った"],"explain":"The writer says パンが 大きくて, とても おいしかった: the bread is big. The new shop is a little more expensive (高い) than the shop next door, not cheaper. The writer bought three cheese breads; the mother bought one sweet bread. The writer went with the mother and wants to go with friends next time.","unit":8,"step":"test"},"n5u08t.20":{"id":"n5u08t.20","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"駅の　前に　新しい　パンやが　あります。今日、母と　はじめて　行きました。となりの　店より　少し　高いですが、パンが　大きくて、とても　おいしかったです。わたしは　チーズの　パンを　三つ　買いました。母は　あまい　パンを　一つだけ　買いました。こんどは　友だちと　行きたいです。","q":"母は　何を　買いましたか。","options":["あまい　パンを　一つ","あまい　パンを　三つ","チーズの　パンを　一つ","チーズの　パンを　三つ"],"answer":1,"short":["あまいの一つ","あまいの三つ","チーズ一つ","チーズ三つ"],"explain":"The passage says 母は あまい パンを 一つだけ 買いました. Three cheese breads (チーズの パンを 三つ) is what the writer bought. Neither person bought three sweet breads or one cheese bread.","unit":8,"step":"test"},"n5u08t.21":{"id":"n5u08t.21","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"レストラン　やま　ランチ（十一時から　二時まで）\nカレー　七百円\n魚の　ランチ　九百円\nパンと　スープ　六百円\n・ランチを　食べる　人は、コーヒーと　こうちゃが　百円に　なります。\n・土よう日と　日よう日は、パンと　スープだけです。","q":"日よう日に　この　レストランで　ランチを　食べます。何を　食べますか。","options":["カレーと　パン","カレー","魚の　ランチ","パンと　スープ"],"answer":4,"short":["カレーとパン","カレー","魚","パンとスープ"],"explain":"The notice says 土よう日と 日よう日は、パンと スープだけです: on Saturday and Sunday there is only bread and soup. Curry and the fish lunch are not served on Sunday, and curry with bread is not on the menu.","unit":8,"step":"test"},"n5u08t.22":{"id":"n5u08t.22","kind":"choice","type":"読解・情報検索","label":"Finding information","passage":"レストラン　やま　ランチ（十一時から　二時まで）\nカレー　七百円\n魚の　ランチ　九百円\nパンと　スープ　六百円\n・ランチを　食べる　人は、コーヒーと　こうちゃが　百円に　なります。\n・土よう日と　日よう日は、パンと　スープだけです。","q":"火よう日に　カレーと　コーヒーを　たのみます。ぜんぶで　いくらですか。","options":["七百円","八百円","九百円","千円"],"answer":2,"short":["七百円","八百円","九百円","千円"],"explain":"Curry is 七百円, and with a lunch, coffee is 百円 (コーヒーと こうちゃが 百円に なります). 700 + 100 = 八百円. 七百円 leaves out the coffee. 九百円 is the price of the fish lunch. 千円 does not match any order here.","unit":8,"step":"test"},"n5u08t.23":{"id":"n5u08t.23","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ケンさんへ\n先週から　駅の　前の　としょかんが　新しく　なりました。前より　大きく　なって、本も　多く　なりました。でも、月よう日は　休みです。日よう日は　人が　多いですから、わたしは　いつも　土よう日に　行きます。こんど、いっしょに　行きませんか。\nマリ","q":"新しい　としょかんは　どう　なりましたか。","options":["前より　大きく　なりました。","前より　小さく　なりました。","本が　少なく　なりました。","日よう日が　休みに　なりました。"],"answer":1,"short":["大きくなった","小さくなった","本が少ない","日よう日休み"],"explain":"マリ writes 前より 大きく なって, 本も 多く なりました: the library got bigger and has more books. So it did not get smaller, and the books did not become fewer. The day off is 月よう日; on 日よう日 it is open and crowded.","unit":8,"step":"test"},"n5u08t.24":{"id":"n5u08t.24","kind":"choice","type":"読解・内容理解（短文）","label":"Short passage","passage":"ケンさんへ\n先週から　駅の　前の　としょかんが　新しく　なりました。前より　大きく　なって、本も　多く　なりました。でも、月よう日は　休みです。日よう日は　人が　多いですから、わたしは　いつも　土よう日に　行きます。こんど、いっしょに　行きませんか。\nマリ","q":"マリさんは　どうして　土よう日に　としょかんへ　行きますか。","options":["日よう日は　休みだからです。","土よう日は　本が　多いからです。","日よう日は　人が　多いからです。","ケンさんと　行くからです。"],"answer":3,"short":["日よう日休み","土よう日本が多い","日よう日人が多い","ケンさんと"],"explain":"マリ writes 日よう日は 人が 多いですから, わたしは いつも 土よう日に 行きます: Sunday is crowded, so she goes on Saturday. The library is closed on 月よう日, not 日よう日. The books are not more on Saturday. マリ only invites ケン for next time; that is not why she goes on Saturday.","unit":8,"step":"test"},"n5mock1":{"id":"n5mock1","kind":"choice","type":"漢字読み","label":"もんだい1","rubric":"＿＿＿の　ことばの　ただしい　よみかたは　どれですか。こたえは　１・２・３・４の　中から　一つ　えらんで　ください。","q":"きのうの　_午後_、としょかんで　べんきょうしました。","options":["こご","ごご","ごうご","ごこ"],"answer":2,"explain":"午後 is ごご, \"afternoon\": 午 is ご and 後 is ご. こご and ごこ change one ご to こ, and ごうご adds a long sound that is not there.","step":"mock"},"n5mock2":{"id":"n5mock2","kind":"choice","type":"表記","label":"もんだい2","rubric":"＿＿＿の　ことばの　ただしい　かきかたは　どれですか。こたえは　１・２・３・４の　中から　一つ　えらんで　ください。","q":"毎あさ　_でんしゃ_で　会社へ　行きます。","options":["雨車","電東","電車","雨東"],"answer":3,"explain":"でんしゃ, \"train\", is 電車: 電 (electric) and 車 (vehicle). 雨 (rain) is the top part of 電 only, and 東 (east) looks like 車 but is not. So 雨車, 電東 and 雨東 are not words.","step":"mock"},"n5mock3":{"id":"n5mock3","kind":"choice","type":"文脈規定","label":"もんだい3","rubric":"（　　）に　いれる　ことばは　どれですか。こたえは　１・２・３・４の　中から　一つ　えらんで　ください。","q":"へやが　さむいですね。（　　）を　しめましょうか。","options":["でんき","まど","かさ","いす"],"answer":2,"explain":"The room is cold, so they close the window: まどを しめる. でんき (the light) is turned off with けす, not しめる. A かさ (umbrella) is closed with とじる, and it does nothing for a cold room. いす (a chair) cannot be closed at all.","step":"mock"},"n5mock4":{"id":"n5mock4","kind":"choice","type":"言い換え類義","label":"もんだい4","rubric":"＿＿＿の　ぶんと　いみが　ちかい　ぶんを　えらんで　ください。こたえは　１・２・３・４の　中に　一つ　あります。","q":"まどが　小さいので、_この　へやは　くらいです_。","options":["この　へやは　あかるく　ないです。","この　へやは　ひろく　ないです。","この　へやは　しずかでは　ないです。","この　へやは　きれいでは　ないです。"],"answer":1,"short":["あかるく ない","ひろく ない","しずかでは ない","きれいでは ない"],"explain":"くらい (dark) means the same as あかるく ない (not bright). ひろく ない is \"not big\", しずかでは ない is \"not quiet\" and きれいでは ない is \"not clean\". None of those is about light.","step":"mock"},"n5mock5":{"id":"n5mock5","kind":"choice","type":"文の文法1","label":"もんだい1","rubric":"（　　）に　何を　入れますか。１・２・３・４から　いちばん　いい　ものを　一つ　えらんで　ください。","q":"雨が　ふって　いますから、きょうは　どこへも　（　　）。","options":["行きます","行きました","行きません","行きましょう"],"answer":3,"explain":"どこへも (\"not anywhere\") needs a negative verb after it, and it is raining, so the speaker stays in: 行きません. 行きます, 行きました and 行きましょう are all positive, so they cannot follow どこへも. (To say \"go somewhere\" you need どこかへ.)","step":"mock"},"n5mock6":{"id":"n5mock6","kind":"choice","type":"文の文法1","label":"もんだい1","rubric":"（　　）に　何を　入れますか。１・２・３・４から　いちばん　いい　ものを　一つ　えらんで　ください。","q":"あには　わたし（　　）　せが　高いです。","options":["ほど","まで","より","から"],"answer":3,"explain":"To compare two people, the one you measure against takes より: \"my brother is taller than me\". ほど is used with a negative (わたしほど 高く ないです). まで (\"until, as far as\") and から (\"from\") do not compare.","step":"mock"},"n5mock7":{"id":"n5mock7","kind":"choice","type":"文の文法2","label":"もんだい2","rubric":"★に　入る　ものは　どれですか。１・２・３・４から　いちばん　いい　ものを　一つ　えらんで　ください。","q":"これは　＿＿　＿＿　★　＿＿　です。","before":"これは　","after":"　です。","star":2,"options":["本","書いた","父","が"],"order":[3,4,2,1],"answer":2,"explain":"The sentence is これは 父 が 書いた 本 です, \"This is a book my father wrote.\" 父が 書いた describes 本, so it comes right before it, and が follows 父. The third blank (★) is 書いた. Other orders fail: 本が 父 書いた has 父 with no particle, and 父が 本 書いた leaves 本 with no particle and the sentence ends in 書いた です.","step":"mock"},"n5mock8":{"id":"n5mock8","kind":"choice","type":"読解・内容理解（短文）","label":"もんだい4","rubric":"つぎの　ぶんしょうを　よんでから、しつもんの　こたえを　えらんで　ください。こたえは　１・２・３・４の　中に　一つ　あります。","passage":"キムさん\nあしたの　午後　三時に　スミスさんが　うちに　来ます。わたしは　二時から　出かけますから、スミスさんに　つくえの　上の　本を　わたして　ください。それから、スミスさんと　いっしょに　テーブルの　上の　ケーキを　食べて　ください。\nゆき","q":"キムさんは　あした　何を　しますか。","options":["スミスさんに　本を　わたして、ケーキを　いっしょに　食べます。","スミスさんに　本を　かりて、ケーキを　かいます。","二時に　ゆきさんと　いっしょに　出かけます。","三時に　スミスさんの　うちへ　行きます。"],"answer":1,"short":["本をわたしてケーキを食べる","本をかりてケーキをかう","二時にゆきさんと出かける","スミスさんのうちへ行く"],"explain":"Yuki asks Kim to give (わたして) Smith the book on the desk and to eat the cake with him. Kim does not borrow a book or buy a cake (2). Yuki goes out at two, alone (3). Smith comes to the house; Kim does not go to his (4).","step":"mock"},"n5mock9":{"id":"n5mock9","kind":"choice","type":"読解・情報検索","label":"もんだい6","rubric":"みぎの　ページの　あんないを　よんで、しつもんの　こたえを　えらんで　ください。こたえは　１・２・３・４の　中に　一つ　あります。","passage":"みどり　どうぶつえん　ねだん\n\nおとな（13さいから）　300円\n子ども（6さいから　12さいまで）　200円\n5さいまでの　子ども　0円\n\n＊土よう日と　日よう日は、おとなは　400円です。","q":"リンさんは　土よう日に、8さいの　むすこと　3さいの　むすめと　どうぶつえんへ　行きます。三人で　いくら　はらいますか。","options":["500円","600円","700円","800円"],"answer":2,"short":["500円","600円","700円","800円"],"explain":"On Saturday an adult pays 400円. The 8-year-old son pays 200円 and the 3-year-old daughter pays nothing: 400 + 200 = 600円. 500円 uses the weekday adult price (300 + 200). 700円 and 800円 also charge the 3-year-old 200円.","step":"mock"},"n5mock10":{"id":"n5mock10","kind":"choice","type":"課題理解","label":"もんだい1","rubric":"もんだい1は、まず　しつもんが　あります。それを　よく　聞いて　ください。つぎに　話を　聞いて、もんだいようしの　1から4の　中で　いちばん　あう　ものを　えらんで　ください。","q":"男の人は　何を　買って　きますか。","options":["つめたい　おちゃ","あたたかい　おちゃ","つめたい　おちゃと　パン","パン"],"answer":1,"explain":"She asks for cold tea, then for two pieces of bread, but he already bought bread and it is on the desk, so she says おちゃだけで いいです: only the tea. Warm tea (2) is not what she wants. Tea and bread (3) and bread alone (4) are wrong because the bread is already there.","script":"会社で　女の人と　男の人が　話して　います。男の人は　何を　買って　きますか。\n女：すみません、コンビニへ　行きますか。\n男：はい、行きますよ。\n女：じゃあ、おちゃを　買って　きて　ください。\n男：おちゃですね。つめたい　おちゃですか。\n女：はい、つめたいのを　おねがいします。あ、それから、パンも　二つ　おねがいします。\n男：パンは　さっき　わたしが　買いましたよ。つくえの　上に　あります。\n女：あ、ほんとうだ。じゃあ、おちゃだけで　いいです。\n男の人は　何を　買って　きますか。","parts":[{"k":"q","ja":"しつもん","en":"the question","sim":2000,"lines":[["N","会社で　女の人と　男の人が　話して　います。男の人は　何を　買って　きますか。","かいしゃで　おんなのひとと　おとこのひとが　はなして　います。おとこのひとは　なにを　かって　きますか。"]]},{"k":"talk","ja":"はなし","en":"the conversation","sim":4200,"lines":[["F","すみません、コンビニへ　行きますか。",null],["M","はい、行きますよ。",null],["F","じゃあ、おちゃを　買って　きて　ください。",null],["M","おちゃですね。つめたい　おちゃですか。",null],["F","はい、つめたいのを　おねがいします。あ、それから、パンも　二つ　おねがいします。","はい、つめたいのを　おねがいします。あ、それから、パンも　ふたつ　おねがいします。"],["M","パンは　さっき　わたしが　買いましたよ。つくえの　上に　あります。",null],["F","あ、ほんとうだ。じゃあ、おちゃだけで　いいです。",null]]},{"k":"q2","ja":"しつもん","en":"the question again","sim":1600,"lines":[["N","男の人は　何を　買って　きますか。","おとこのひとは　なにを　かって　きますか。"]]},{"k":"ans","ja":"こたえ","en":"answer time","wait":8000,"sim":6000}],"step":"mock"},"n5mock11":{"id":"n5mock11","kind":"choice","type":"ポイント理解","label":"もんだい2","rubric":"もんだい2も、まず　しつもんが　あります。それを　よく　聞いて　ください。つぎに　話を　聞いて、もんだいようしの　1から4の　中で　いちばん　あう　ものを　えらんで　ください。","q":"二人は　あした　何時に　会いますか。","options":["12時半","1時","2時","2時半"],"answer":2,"explain":"He first says two o'clock, but she wants lunch before the film. He offers 12:30, she says that is a little early, and they settle on 一時に しましょう: one o'clock. 12時半 was turned down, 2時 was the first plan, and 2時半 is when the film starts.","script":"男の人と　女の人が　話して　います。二人は　あした　何時に　会いますか。\n男：あしたの　えいが、何時からですか。\n女：二時半からです。\n男：じゃあ、二時に　駅の　前で　会いましょうか。\n女：うーん、その　前に　いっしょに　ひるごはんを　食べませんか。\n男：いいですね。じゃあ、十二時半は　どうですか。\n女：ちょっと　はやいですね。一時に　しましょう。\n男：はい、わかりました。\n二人は　あした　何時に　会いますか。","parts":[{"k":"q","ja":"しつもん","en":"the question","sim":2000,"lines":[["N","男の人と　女の人が　話して　います。二人は　あした　何時に　会いますか。","おとこのひとと　おんなのひとが　はなして　います。ふたりは　あした　なんじに　あいますか。"]]},{"k":"talk","ja":"はなし","en":"the conversation","sim":4200,"lines":[["M","あしたの　えいが、何時からですか。","あしたの　えいが、なんじからですか。"],["F","二時半からです。","にじはんからです。"],["M","じゃあ、二時に　駅の　前で　会いましょうか。","じゃあ、にじに　えきの　まえで　あいましょうか。"],["F","うーん、その　前に　いっしょに　ひるごはんを　食べませんか。",null],["M","いいですね。じゃあ、十二時半は　どうですか。","いいですね。じゃあ、じゅうにじはんは　どうですか。"],["F","ちょっと　はやいですね。一時に　しましょう。","ちょっと　はやいですね。いちじに　しましょう。"],["M","はい、わかりました。",null]]},{"k":"q2","ja":"しつもん","en":"the question again","sim":1600,"lines":[["N","二人は　あした　何時に　会いますか。","ふたりは　あした　なんじに　あいますか。"]]},{"k":"ans","ja":"こたえ","en":"answer time","wait":8000,"sim":6000}],"step":"mock"},"n5mock12":{"id":"n5mock12","kind":"choice","type":"即時応答","label":"もんだい4","rubric":"もんだい4に　えは　ありません。ぶんを　聞いてから、1から3の　へんじの　中で　いちばん　あう　ものを　えらんで　ください。","q":"女：この　ペン、ちょっと　かりても　いいですか。","options":["ええ、どうぞ。","いいえ、かりません。","はい、ありがとうございます。"],"answer":1,"short":["ええ、どうぞ","いいえ、かりません","ありがとうございます"],"explain":"She asks to borrow the pen, so the reply is permission: ええ、どうぞ. いいえ、かりません talks as if he were the one borrowing. はい、ありがとうございます is what the borrower says, not the owner.","script":"女：この　ペン、ちょっと　かりても　いいですか。\n1：ええ、どうぞ。\n2：いいえ、かりません。\n3：はい、ありがとうございます。","parts":[{"k":"line","ja":"ぶん","en":"the line","sim":1600,"lines":[["F","この　ペン、ちょっと　かりても　いいですか。",null]]},{"k":"replies","ja":"へんじ 1・2・3","en":"the three replies","sim":3400,"lines":[["N","1",null],["M","ええ、どうぞ。",null],["N","2",null],["M","いいえ、かりません。",null],["N","3",null],["M","はい、ありがとうございます。",null]]},{"k":"ans","ja":"こたえ","en":"answer time","wait":6000,"sim":5000}],"step":"mock"}},"below":""};
